using System;
using System.Collections;
using UnityEngine;
using UnityEngine.Networking;

namespace FTProject.AOT
{
    // APK-owned shell. No references to any hot-update assembly are permitted here.
    public class BootLoader : MonoBehaviour
    {
        private const int ProbeTimeoutSeconds = 2;
        private static BootLoader _instance;
        private bool _retry;
        private void Awake()
        {
            if (_instance != null && _instance != this) { Destroy(gameObject); return; }
            _instance = this;
            Application.targetFrameRate = 60;
            BootLocalization.Initialize();
            BootUiSymbolKeeper.Ensure();
            StartCoroutine(BootRoutine());
        }
        private void OnDestroy()
        {
            if (_instance == this) { _instance = null; BootUpdateSession.Controls(); BootServerSelection.StopDiscovery(); }
        }
        private IEnumerator WaitRetry(string reason)
        {
            _retry = false;
            Debug.LogWarning("[Boot] Waiting for retry: " + reason);
            BootUpdateSession.Report("Failed", BootUpdateSession.Overall, -1, reason);
            BootUpdateSession.Controls(retry: () => _retry = true);
            while (!_retry) yield return null;
            BootUpdateSession.Controls();
        }
        private IEnumerator BootRoutine()
        {
            // Give the scene-configured HotUpdateView a frame before any IO or DLL work.
            BootUpdateSession.Report("Preparing", 0);
            yield return null;
#if UNITY_EDITOR && !FORCE_AB
            // The editor already owns the current assemblies and builds its own virtual manifest.
            // APK descriptors, staged DLLs and network availability must not affect this mode.
            BootReleaseStore.UseEditorSimulation();
            Debug.Log("[Boot] Editor simulation: current assemblies and project assets; no release server required.");
            Exception loadError = null;
#else
            while (true)
            {
                yield return BootReleaseStore.PrepareBaseline();
                if (BootReleaseStore.Error == null) break;
                yield return WaitRetry(BootReleaseStore.Error);
            }
            yield return HotUpdateAssembler.PrefetchStreamingAssetsToPersistent(null);
            while (true)
            {
                BootUpdateSession.Report("Checking", .05f);
                string winner = null;
                string manual = ReadServerOverride();
                if (!string.IsNullOrEmpty(manual))
                {
                    yield return ProbeCandidatesCo(new[] { manual }, (url, source) => winner = url, errors => Debug.LogWarning(errors));
                }
                else
                {
                    BootServerSelection.StartDiscovery();
                    yield return ProbeCandidatesCo(BootServerSelection.Candidates, (url, source) => winner = url, errors => Debug.LogWarning(errors));
                    if (winner == null)
                    {
                        float deadline = Time.realtimeSinceStartup + 2f;
                        while (!BootServerSelection.DiscoveryFinished && Time.realtimeSinceStartup < deadline) yield return null;
                        string[] discovered = BootServerSelection.TakeDiscovered();
                        if (discovered.Length > 0) yield return ProbeCandidatesCo(discovered, (url, source) => winner = url, errors => Debug.LogWarning(errors));
                    }
                    BootServerSelection.StopDiscovery();
                }
                if (winner == null)
                {
                    BootServerSelection.MarkReachabilityChecked();
                    BootReleaseStore.UseOffline(manual ?? BootServerSelection.Candidates[0]);
                    BootUpdateSession.Report("Offline", .2f, -1);
                    break;
                }
                BootServerSelection.SetSelected(winner, "release probe");
                BootServerSelection.MarkReachabilityChecked();
                var localCandidate = BootReleaseStore.Selected;
                yield return BootReleaseStore.SelectRemote(winner);
                if (BootReleaseStore.Error != null)
                {
                    if (BootReleaseStore.TryUseLocalCandidate(localCandidate, winner, BootReleaseStore.Error)) break;
                    yield return WaitRetry(BootReleaseStore.Error);
                    continue;
                }
                HotUpdateDllDownloader.Result result = null;
                yield return HotUpdateDllDownloader.DownloadAll(winner,
                    (done, total) => BootUpdateSession.Report("DLL", .1f + .2f * done / Mathf.Max(total, 1), (float)done / Mathf.Max(total, 1), done + "/" + total),
                    value => result = value);
                if (result == null || !string.IsNullOrEmpty(result.ErrorSummary) || !BootReleaseStore.VerifyDlls(BootReleaseStore.Selected))
                {
                    string reason = result?.ErrorSummary ?? "DLL set incomplete";
                    if (BootReleaseStore.TryUseLocalCandidate(localCandidate, winner, reason)) break;
                    yield return WaitRetry(reason);
                    continue;
                }
                break;
            }
            BootUpdateSession.Report("Loading DLL", .32f);
            yield return null;
            Exception loadError = null;
            try { HotUpdateAssembler.LoadHotUpdateAssemblies(null); }
            catch (Exception e) { loadError = e; }
            if (loadError != null)
            {
                // Some assemblies may already be resident. Retrying Assembly.Load is unsafe.
                Debug.LogError("[Boot] Assembly load failed; process restart required: " + loadError);
                BootUpdateSession.Report("Restart", .32f, -1, loadError.Message);
                yield break;
            }
#endif
            IHotUpdateEntry entry = HotUpdateEntryLocator.CreateEntry(out string error);
            if (entry == null) { BootUpdateSession.Report("Restart", .32f, -1, error); yield break; }
            try { entry.Start(); }
            catch (Exception e) { loadError = e; }
            if (loadError != null) { BootUpdateSession.Report("Restart", .32f, -1, loadError.Message); yield break; }
            // The inner gate owns retries and liveness; there is no wall-clock scene timeout
            // that can interrupt a healthy download or a player-paused transfer.
            bool done = false, ok = false;
            do
            {
                done = false;
                entry.EnterMainScene((success, reason) => { done = true; ok = success; error = reason; });
                while (!done) yield return null;
                if (!ok) yield return WaitRetry(error);
            } while (!ok);
        }
        private IEnumerator ProbeCandidatesCo(string[] candidates,
            Action<string, string> onWinner, Action<string> onErrorSummary)
        {
            // 每个候选一个探测槽：发出后不 yield 单发请求，统一轮询收割
            ProbeSlot[] slots = new ProbeSlot[candidates.Length];
            slotsErrorSummary = new string[candidates.Length];

            for (int i = 0; i < candidates.Length; i++)
            {
                string root = (candidates[i] ?? "").TrimEnd('/');
                string url = root + "/release.json";

                UnityWebRequest req = UnityWebRequest.Get(url);
                req.timeout = ProbeTimeoutSeconds;
                req.downloadHandler = new DownloadHandlerBuffer();

                slots[i] = new ProbeSlot { Index = i, Url = url, Request = req };
                req.SendWebRequest();   // 异步发出；并发等待靠下面的轮询
            }

            float t0 = Time.realtimeSinceStartup;

            while (true)
            {
                bool allDone = true;

                for (int i = 0; i < slots.Length; i++)
                {
                    ProbeSlot s = slots[i];
                    if (s == null || s.Done)
                    {
                        continue;
                    }

                    if (s.Request.isDone)
                    {
                        s.Done = true;
                        UnityWebRequest r = s.Request;

                        if (r.result == UnityWebRequest.Result.Success
                            && r.responseCode == 200
                            && string.IsNullOrEmpty(r.downloadHandler.text) == false)
                        {
                            // 先成功者胜出：中止其余请求，立刻返回
                            Debug.Log(string.Format(
                                "[Boot] 候选服务器 {0}/{1} 可达（并发探测耗时 {2:F2}s）：{3}",
                                s.Index + 1, slots.Length, Time.realtimeSinceStartup - t0, s.Url));
                            AbortProbeSlots(slots, s.Index);
                            onWinner(candidates[s.Index],
                                string.Format("候选 {0}/{1}", s.Index + 1, slots.Length));
                            yield break;
                        }

                        slotsErrorSummary[s.Index] = string.Format("  候选{0} {1} → {2}（HTTP {3}）",
                            s.Index + 1, s.Url, r.error, r.responseCode);
                    }
                    else
                    {
                        allDone = false;
                    }
                }

                if (allDone)
                {
                    break;
                }
                yield return null;
            }

            // 全部失败：统一中止并释放请求，再上抛错误摘要
            AbortProbeSlots(slots, -1);
            if (onErrorSummary != null)
            {
                onErrorSummary(string.Join("\n", slotsErrorSummary));
            }
        }

        /// <summary>中止并释放除胜出者以外的全部探测请求（胜出者本体用完即释；-1 = 全部释放）。</summary>
        private static void AbortProbeSlots(ProbeSlot[] slots, int winnerIndex)
        {
            for (int i = 0; i < slots.Length; i++)
            {
                ProbeSlot s = slots[i];
                if (s == null || s.Request == null)
                {
                    continue;
                }
                if (i != winnerIndex)
                {
                    s.Request.Abort();
                }
                s.Request.Dispose();
            }
        }

        private string[] slotsErrorSummary = new string[0];

        /// <summary>并发探测的单发请求槽位（Index 对应候选数组下标）。</summary>
        private class ProbeSlot
        {
            public int Index;
            public string Url;
            public UnityWebRequest Request;
            public bool Done;
        }

        /// <summary>读 persistentDataPath/server.txt 的第一行（跳过空行与 # 注释）。没有则返回 null。</summary>
        private static string ReadServerOverride()
        {
            try
            {
                string file = System.IO.Path.Combine(Application.persistentDataPath, "server.txt");
                if (System.IO.File.Exists(file) == false)
                {
                    return null;
                }

                string[] lines = System.IO.File.ReadAllLines(file);
                for (int i = 0; i < lines.Length; i++)
                {
                    string line = lines[i].Trim();
                    if (line.Length == 0 || line.StartsWith("#"))
                    {
                        continue;
                    }
                    return line.TrimEnd('/');
                }
            }
            catch (Exception)
            {
                // 读不到就当没覆盖，用常量地址
            }
            return null;
        }

    }
}

using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using UnityEngine;

namespace FTProject.AOT
{
    public static class BootLocalization
    {
        private const string Preference = "FT.Boot.Language";
        public static Language Current { get; private set; }
        public static bool HasSelection { get; private set; }
        [Serializable] private class LegacySave { public LegacySettings settings; }
        [Serializable] private class LegacySettings { public string language; }

        public static void Initialize()
        {
            // Read the existing SQLite selection without creating/migrating/writing its database.
            string code = ReadSqlite();
            if (string.IsNullOrEmpty(code))
            {
                try
                {
                    string path = Path.Combine(Application.persistentDataPath, "freetower_save.json");
                    if (File.Exists(path)) code = JsonUtility.FromJson<LegacySave>(File.ReadAllText(path))?.settings?.language;
                }
                catch (Exception e) { Debug.LogWarning("[BootLoc] Legacy save: " + e.Message); }
            }
            if (string.IsNullOrEmpty(code)) code = PlayerPrefs.GetString(Preference, "");
            HasSelection = code == "en" || code == "zh-Hans" || code == "zh-Hant";
            Current = LanguageUtil.FromCode(code);
        }

        public static void Remember(Language language)
        {
            Current = language; HasSelection = true;
            PlayerPrefs.SetString(Preference, language.ToCode());
            PlayerPrefs.Save();
        }

        public static string Get(string key)
        {
            bool traditional = Current == Language.ChineseTraditional;
            if (Current == Language.English) return English(key);
            switch (key)
            {
                case "Preparing": return traditional ? "正在準備啟動資源" : "正在准备启动资源";
                case "Checking": return traditional ? "正在檢查更新" : "正在检查更新";
                case "DLL": return traditional ? "正在下載與校驗程式" : "正在下载与校验程序";
                case "Loading DLL": return traditional ? "正在載入程式" : "正在加载程序";
                case "Initializing": return traditional ? "正在初始化資源" : "正在初始化资源";
                case "Resources": return traditional ? "正在下載與校驗資源" : "正在下载与校验资源";
                case "Offline": return traditional ? "離線：校驗本機資源" : "离线：校验本地资源";
                case "Ready": return traditional ? "更新完成，正在進入遊戲" : "更新完成，正在进入游戏";
                case "Failed": return traditional ? "更新失敗，請重試" : "更新失败，请重试";
                case "Restart": return traditional ? "程式載入失敗，請重新啟動遊戲" : "程序加载失败，请重新启动游戏";
                case "Pause": return traditional ? "暫停" : "暂停";
                case "Resume": return traditional ? "繼續" : "继续";
                case "Retry": return traditional ? "重試" : "重试";
                case "Paused": return traditional ? "已暫停" : "已暂停";
                case "Title": return traditional ? "遊戲更新" : "游戏更新";
                case "Overall": return traditional ? "整體" : "总体";
                case "Stage": return traditional ? "階段" : "阶段";
                default: return key;
            }
        }

        public static string EnglishText(string key) { return English(key); }

        private static string English(string key)
        {
            switch (key)
            {
                case "Preparing": return "Preparing startup files";
                case "Checking": return "Checking for updates";
                case "DLL": return "Downloading and verifying code";
                case "Loading DLL": return "Loading code";
                case "Initializing": return "Initializing resources";
                case "Resources": return "Downloading and verifying resources";
                case "Offline": return "Offline: verifying local resources";
                case "Ready": return "Update complete, entering game";
                case "Failed": return "Update failed. Please retry";
                case "Restart": return "Code loading failed. Please restart the game";
                case "Title": return "GAME UPDATE";
                default: return key;
            }
        }

#if UNITY_EDITOR_WIN || UNITY_STANDALONE_WIN
        private const string Sqlite = "winsqlite3";
#elif UNITY_IOS
        private const string Sqlite = "__Internal";
#else
        private const string Sqlite = "sqlite3";
#endif
        [DllImport(Sqlite, CallingConvention = CallingConvention.Cdecl)] private static extern int sqlite3_open_v2(byte[] path, out IntPtr db, int flags, IntPtr vfs);
        [DllImport(Sqlite, CallingConvention = CallingConvention.Cdecl)] private static extern int sqlite3_prepare_v2(IntPtr db, byte[] sql, int len, out IntPtr stmt, IntPtr tail);
        [DllImport(Sqlite, CallingConvention = CallingConvention.Cdecl)] private static extern int sqlite3_step(IntPtr stmt);
        [DllImport(Sqlite, CallingConvention = CallingConvention.Cdecl)] private static extern IntPtr sqlite3_column_text(IntPtr stmt, int col);
        [DllImport(Sqlite, CallingConvention = CallingConvention.Cdecl)] private static extern int sqlite3_finalize(IntPtr stmt);
        [DllImport(Sqlite, CallingConvention = CallingConvention.Cdecl)] private static extern int sqlite3_close(IntPtr db);

        private static string ReadSqlite()
        {
            IntPtr db = IntPtr.Zero, stmt = IntPtr.Zero;
            try
            {
                string path = Path.Combine(Application.persistentDataPath, "freetower.db");
                if (!File.Exists(path)) return null;
                if (sqlite3_open_v2(Encoding.UTF8.GetBytes(path + "\0"), out db, 1, IntPtr.Zero) != 0) return null;
                byte[] sql = Encoding.UTF8.GetBytes("SELECT v FROM kv_store WHERE k='settings.language' AND sensitive=0 LIMIT 1\0");
                if (sqlite3_prepare_v2(db, sql, sql.Length, out stmt, IntPtr.Zero) != 0) return null;
                return sqlite3_step(stmt) == 100 ? Marshal.PtrToStringAnsi(sqlite3_column_text(stmt, 0)) : null;
            }
            catch (Exception e) { Debug.LogWarning("[BootLoc] Saved language fallback: " + e.Message); return null; }
            finally
            {
                if (stmt != IntPtr.Zero) sqlite3_finalize(stmt);
                if (db != IntPtr.Zero) sqlite3_close(db);
            }
        }
    }
}

using System;
using System.Collections;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;
using UnityEngine.Networking;

namespace FTProject.AOT
{
    [Serializable] public sealed class BootDllFile { public string name; public string md5; }
    [Serializable] public sealed class BootRelease
    {
        public int schema = 2;
        public int playerApi = 2;
        public string aotSignature;
        public string id;
        public string resourceVersion;
        public string manifestMd5;
        public string contentRoot;
        public BootDllFile[] dlls;
    }

    // A release is a complete DLL set plus a pinned YooAsset manifest version.
    // Staged DLLs are immutable; last-good is committed only after the resource gate.
    public static class BootReleaseStore
    {
        public static BootRelease Selected { get; private set; }
        public static string Error { get; private set; }
        public static string ServerRoot { get; private set; }
        public static bool Offline { get; private set; }
        private static BootRelease _baseline;
        public static bool UsesBuiltinManifest => Selected != null && _baseline != null
            && Selected.resourceVersion == _baseline.resourceVersion && Selected.manifestMd5 == _baseline.manifestMd5;
        private static string Root => Path.Combine(Application.persistentDataPath, "BootReleases");
        public static string MetadataDirectory => Path.Combine(Root, "metadata", _baseline.aotSignature);
        public static string DllDirectory => DirectoryFor(Selected);
        public static string ResourceRoot => ServerRoot.TrimEnd('/') + "/" + Selected.contentRoot;
        public static string DirectoryFor(BootRelease release) => Path.Combine(Root, Hash(JsonUtility.ToJson(release)));
        public static string Hash(string value)
        {
            using (var hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-", "").ToLowerInvariant();
        }
        public static string Md5(string file)
        {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(file)) return BitConverter.ToString(md5.ComputeHash(stream)).Replace("-", "").ToLowerInvariant();
        }
        public static bool Matches(string path, string hash)
        {
            try { return File.Exists(path) && string.Equals(Md5(path), hash, StringComparison.OrdinalIgnoreCase); }
            catch (Exception) { return false; }
        }
        public static bool Valid(BootRelease release)
        {
            if (release == null || release.schema != 2 || release.playerApi != 2 || string.IsNullOrEmpty(release.aotSignature)
                || string.IsNullOrEmpty(release.id) || string.IsNullOrEmpty(release.resourceVersion)
                || release.manifestMd5 == null || !System.Text.RegularExpressions.Regex.IsMatch(release.manifestMd5, "^[a-fA-F0-9]{32}$")
                || string.IsNullOrEmpty(release.contentRoot) || !release.contentRoot.StartsWith("releases/", StringComparison.Ordinal)
                || release.contentRoot.Contains("..") || release.contentRoot.Contains(":") || release.contentRoot.Contains("\\")
                || release.dlls == null || release.dlls.Length != HotUpdateAssembler.HotUpdateAssemblies.Length) return false;
            foreach (string required in HotUpdateAssembler.HotUpdateAssemblies)
            {
                int count = 0;
                foreach (var file in release.dlls)
                    if (file != null && file.name == required && file.md5 != null
                        && System.Text.RegularExpressions.Regex.IsMatch(file.md5, "^[a-fA-F0-9]{32}$")) count++;
                if (count != 1) return false;
            }
            return _baseline == null || release.aotSignature == _baseline.aotSignature;
        }
        public static bool VerifyDlls(BootRelease release)
        {
            if (!Valid(release)) return false;
            foreach (var file in release.dlls)
                if (!Matches(Path.Combine(DirectoryFor(release), file.name), file.md5)) return false;
            return true;
        }

        public static IEnumerator PrepareBaseline()
        {
            Error = null; Selected = null; _baseline = null; ServerRoot = null; Offline = false;
            string json = null;
            yield return ReadStreaming("boot-release.json", value => json = value);
            try
            {
                var release = JsonUtility.FromJson<BootRelease>(json ?? "");
                if (!Valid(release)) throw new Exception("APK boot-release.json is missing or invalid. Rebuild the APK.");
                _baseline = release;
                Directory.CreateDirectory(DirectoryFor(release));
            }
            catch (Exception e) { Error = e.Message; }
            if (Error != null) yield break;

            // Read APK DLLs into a separate release directory. Never overwrite a downloaded set.
            foreach (var file in _baseline.dlls)
            {
                string destination = Path.Combine(DirectoryFor(_baseline), file.name);
                if (Matches(destination, file.md5)) continue;
                using (var request = UnityWebRequest.Get(StreamingUrl("HybridCLR/" + file.name)))
                {
                    request.timeout = 15;
                    yield return request.SendWebRequest();
                    try
                    {
                        if (request.result != UnityWebRequest.Result.Success) throw new Exception(file.name + ": " + request.error);
                        File.WriteAllBytes(destination + ".tmp", request.downloadHandler.data);
                        if (!Matches(destination + ".tmp", file.md5)) throw new Exception("APK DLL checksum: " + file.name);
                        AtomicMove(destination + ".tmp", destination);
                    }
                    catch (Exception e) { Error = e.Message; }
                }
                if (Error != null) yield break;
            }
            Selected = _baseline;
            try
            {
                string active = Path.Combine(Root, "active.json");
                if (File.Exists(active))
                {
                    var cached = JsonUtility.FromJson<BootRelease>(File.ReadAllText(active));
                    if (VerifyDlls(cached)) Selected = cached;
                }
            }
            catch (Exception e) { Debug.LogWarning("[Release] Ignoring corrupt last-good: " + e.Message); }
            Debug.Log("[Release] Local candidate " + Selected.id + " resources=" + Selected.resourceVersion);
        }

        public static IEnumerator SelectRemote(string root)
        {
            Error = null; ServerRoot = root; Offline = false;
            using (var request = UnityWebRequest.Get(root.TrimEnd('/') + "/release.json?t=" + DateTime.UtcNow.Ticks))
            {
                request.timeout = 8;
                yield return request.SendWebRequest();
                try
                {
                    if (request.result != UnityWebRequest.Result.Success) throw new Exception("Release request: " + request.error);
                    var release = JsonUtility.FromJson<BootRelease>(request.downloadHandler.text);
                    if (!Valid(release)) throw new Exception("Incompatible or incomplete release. This update requires a matching APK.");
                    Directory.CreateDirectory(DirectoryFor(release));
                    // Reuse verified unchanged DLLs, never mix in unverified fallback files.
                    foreach (var file in release.dlls)
                    {
                        string target = Path.Combine(DirectoryFor(release), file.name);
                        string previous = Path.Combine(DllDirectory, file.name);
                        if (!Matches(target, file.md5) && Matches(previous, file.md5)) File.Copy(previous, target, true);
                    }
                    Selected = release;
                    Debug.Log("[Release] Pinned " + release.id + " resources=" + release.resourceVersion);
                }
                catch (Exception e) { Error = e.Message; }
            }
        }

        public static void UseOffline(string root)
        {
            ServerRoot = root; Offline = true;
            Debug.Log("[Release] Offline candidate " + Selected?.id + "; all bundles must pass local verification.");
        }

        // Only call before loading any hot-update assembly. The resource gate must still
        // verify the complete matching manifest and bundles before entering Main.
        public static bool TryUseLocalCandidate(BootRelease candidate, string root, string reason)
        {
            if (!VerifyDlls(candidate)) return false;
            Selected = candidate;
            Error = null;
            Debug.LogWarning("[Release] Update unavailable; using verified local DLL set " + candidate.id + ": " + reason);
            UseOffline(root);
            BootUpdateSession.Report("Offline", .2f, -1);
            return true;
        }

#if UNITY_EDITOR && !FORCE_AB
        public static void UseEditorSimulation()
        {
            Selected = null; _baseline = null; Error = null; ServerRoot = null; Offline = false;
        }
#endif

        public static void RetryPinnedOnline() { Offline = false; }

        public static void Commit()
        {
            if (!VerifyDlls(Selected)) throw new Exception("Cannot activate an incomplete DLL set");
            string target = Path.Combine(Root, "active.json");
            File.WriteAllText(target + ".tmp", JsonUtility.ToJson(Selected, true));
            AtomicMove(target + ".tmp", target);
            Debug.Log("[Release] COMMIT " + Selected.id + " resources=" + Selected.resourceVersion);
        }

        public static void AtomicMove(string temporary, string target)
        {
            // A backup would require a hard link on some Mono platforms; Android FUSE
            // does not consistently support those. The final rename remains atomic.
            if (File.Exists(target)) File.Replace(temporary, target, null);
            else File.Move(temporary, target);
        }
        private static string StreamingUrl(string relative)
        {
            string path = Application.streamingAssetsPath + "/" + relative;
            return path.Contains("://") ? path : new Uri(path).AbsoluteUri;
        }
        private static IEnumerator ReadStreaming(string relative, Action<string> result)
        {
            using (var request = UnityWebRequest.Get(StreamingUrl(relative)))
            {
                request.timeout = 15;
                yield return request.SendWebRequest();
                result(request.result == UnityWebRequest.Result.Success ? request.downloadHandler.text : null);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using UnityEngine;

namespace FTProject.AOT
{
    /// <summary>
    /// 热更服务器选址（**单一来源**）：常量兜底候选 + UDP 自动发现 + 探测胜出结果。
    ///
    /// ==================================================================
    /// 【解决什么问题】
    ///   开发机在两个环境跑：
    ///     · 公司＝模拟器（MuMu/AVD）→ 访问宿主机走 10.0.2.2（NAT 网关常量，
    ///       与局域网 IP 无关，**永不变**）；
    ///     · 家＝手机真机 → 需要电脑的局域网 IP，但 DHCP 下 **IP 会变**。
    ///   以前单常量地址换环境就得改代码重打包，漏改即"热更静默失效"
    ///   （探测超时 → 跳过热更 → 玩本地旧版本，不报错）。
    ///
    /// 【自动发现怎么工作】
    ///   电脑上跑 `.workbuddy/tools/hotupdate_server.py`（HTTP 8000 + UDP 广播），
    ///   每秒向局域网广播 "FTHOTUPD1|port=8000"；本类 <see cref="StartDiscovery"/>
    ///   在 Boot 阶段开后台线程监听 UDP 28000，收到广播后取**来源 IP** 拼
    ///   http 地址作为候选 —— 电脑 IP 怎么变都能自动拿到。
    ///   随后 BootLoader 对候选做 HTTP 探测（md5.txt 200 校验），
    ///   天然过滤误报（别的设备恰好在 8000 端口上开了非本项目的服务）。
    ///
    /// 【选址优先级（与 ResServerConfig.GetServerUrl 一致）】
    ///   ① persistentDataPath/server.txt 第一行（手工覆盖，诊断用）
    ///   ② <see cref="SelectedUrl"/>（UDP 发现 / 常量候选中**探测可达**者）
    ///   ③ ResServerConfig.ServerUrl 常量（兜底）
    ///
    /// 【可达性结论（2026-10-15 新增）】探测段结束后 BootLoader 无条件调用
    ///   <see cref="MarkReachabilityChecked"/>；<see cref="RemoteHotUpdateAllowed"/>
    ///   是 AB 资源与 dll 两条链路共用的闸门 —— 服务器不可达时全部改用本地资源。
    ///
    /// 【为什么放 AOT 侧】dll 下载发生在热更程序集加载**之前**，只能由 AOT 驱动；
    ///   热更侧允许引用 AOT，ResServerConfig 经本类读胜出地址，两链路同源。
    /// ==================================================================
    /// </summary>
    public static class BootServerSelection
    {
        /// <summary>
        /// 常量兜底候选（UDP 发现失败时的最后阵地）。
        ///   · 10.0.2.2 = 模拟器 NAT 网关（公司场景主路径，永不变）；
        ///   · 若某环境 IP 长期固定（或有公网/内网穿透地址），可在此追加一行，
        ///     例如 "http://192.168.1.100:8000"。
        /// 家里真机的 IP **不需要**写在这里 —— 由 UDP 自动发现接管。
        /// </summary>
        public static readonly string[] Candidates = new string[]
        {
            "http://10.0.2.2:8000",
        };

        // ---------------- UDP 自动发现（与 hotupdate_server.py 配对） ----------------

        /// <summary>UDP 监听端口。**必须与 hotupdate_server.py --udp-port 一致**。</summary>
        public const int UdpListenPort = 28000;

        /// <summary>广播包魔数前缀。**必须与 hotupdate_server.py 的 MAGIC 一致**。</summary>
        private const string UdpMagic = "FTHOTUPD1|";

        /// <summary>
        /// 未收到任何广播时的监听窗口（秒）。期间常量候选探测在并行跑，不白等。
        ///
        /// 【2026-10-15 起 1.5s（原 2.5s）】取值依据：hotupdate_server.py 默认
        /// --interval 1.0s，即广播间隔 ≈1s —— 任何长度 ≥1s 的窗口都**必然**收到
        /// 至少一轮广播（间隔 1s + 网络抖动余量）。窗口缩短的直接收益：
        /// "服务器不在场"时最多只多等 1.5s 就回退本地资源（与 1s 探测并存）。
        /// </summary>
        private const float UdpWindowSeconds = 1.5f;

        /// <summary>收到首个广播后的收尾窗口（秒）：多网卡会重复广播，留时间汇总去重。</summary>
        private const float UdpTailSeconds = 0.6f;

        private static UdpClient _udp;
        private static Thread _udpThread;
        private static volatile bool _udpStop;
        private static readonly object _udpLock = new object();
        private static readonly List<string> _discovered = new List<string>();
        private static float _udpElapsed;
        private static bool _udpFinished = true;

        /// <summary>后台监听是否已结束（收满窗口 / 收到首包后再收尾 / 被提前停止）。</summary>
        public static bool DiscoveryFinished
        {
            get { return _udpFinished; }
        }

        /// <summary>UDP 监听已运行的总时长（秒），供启动日志/状态条显示。</summary>
        public static float DiscoveryElapsed
        {
            get { return _udpElapsed; }
        }

        /// <summary>启动后台 UDP 自动发现（仅 Boot 启动链调用一次；重复调用幂等）。</summary>
        public static void StartDiscovery()
        {
            lock (_udpLock)
            {
                if (_udpThread != null && _udpThread.IsAlive)
                {
                    return;
                }
                _udpStop = false;
                _udpFinished = false;
                _udpElapsed = 0f;
                lock (_discovered)
                {
                    _discovered.Clear();
                }
                _udpThread = new Thread(UdpListenLoop);
                _udpThread.IsBackground = true;
                _udpThread.Start();
                Debug.Log("[Boot] UDP 自动发现启动（监听 :" + UdpListenPort + "，窗口 "
                    + UdpWindowSeconds + "s）");
            }
        }

        /// <summary>停止并释放 UDP 监听（拿到胜出者或决定离线时调用；幂等）。</summary>
        public static void StopDiscovery()
        {
            lock (_udpLock)
            {
                _udpStop = true;
                _udpFinished = true;
                if (_udp != null)
                {
                    try { _udp.Close(); } catch (Exception) { }
                    _udp = null;
                }
            }
        }

        /// <summary>取走当前已发现的候选地址（快照并清空内部缓冲）。</summary>
        public static string[] TakeDiscovered()
        {
            lock (_discovered)
            {
                if (_discovered.Count == 0)
                {
                    return new string[0];
                }
                string[] snapshot = _discovered.ToArray();
                _discovered.Clear();
                return snapshot;
            }
        }

        /// <summary>后台线程：阻塞收包 + 窗口控制（收到首包后进入收尾窗口）。</summary>
        private static void UdpListenLoop()
        {
            // 用 Stopwatch 计时（UnityEngine API 在后台线程不可靠）
            System.Diagnostics.Stopwatch watch = System.Diagnostics.Stopwatch.StartNew();
            double windowEnd = UdpWindowSeconds;
            bool gotPacket = false;
            UdpClient client = null;

            try
            {
                client = new UdpClient(UdpListenPort);
                _udp = client;
                Debug.Log("[Boot] UDP 监听已绑定 :" + UdpListenPort);

                while (_udpStop == false)
                {
                    _udpElapsed = (float)watch.Elapsed.TotalSeconds;

                    if (client.Available > 0)
                    {
                        IPEndPoint ep = new IPEndPoint(IPAddress.Any, 0);
                        byte[] data = client.Receive(ref ep);
                        if (gotPacket == false)
                        {
                            // 首包到达：窗口收窄为"已等时长 + 收尾窗"（汇总多网卡重复包）
                            gotPacket = true;
                            windowEnd = _udpElapsed + UdpTailSeconds;
                            Debug.Log("[Boot] UDP 收到首个广播 ← " + ep.Address);
                        }
                        string url = ParseBroadcast(data, ep);
                        if (string.IsNullOrEmpty(url) == false)
                        {
                            lock (_discovered)
                            {
                                if (_discovered.Contains(url) == false)
                                {
                                    _discovered.Add(url);
                                    Debug.Log("[Boot] UDP 发现热更服务器候选：" + url);
                                }
                            }
                        }
                    }
                    else if (watch.Elapsed.TotalSeconds >= windowEnd)
                    {
                        break;
                    }
                    else
                    {
                        Thread.Sleep(50);
                    }
                }
            }
            catch (ObjectDisposedException)
            {
                // StopDiscovery 关闭 socket 的正常打断
            }
            catch (SocketException e)
            {
                // 端口被占 / 绑定失败：UDP 发现不可用，静默退化（常量候选仍有效）
                Debug.LogWarning("[Boot] UDP 自动发现不可用（" + e.Message
                    + "），退回常量候选探测。");
            }
            catch (Exception e)
            {
                Debug.LogWarning("[Boot] UDP 自动发现异常（不影响启动）：" + e.Message);
            }
            finally
            {
                if (client != null)
                {
                    try { client.Close(); } catch (Exception) { }
                }
                if (ReferenceEquals(_udp, client))
                {
                    _udp = null;
                }
                _udpFinished = true;
                _udpElapsed = (float)watch.Elapsed.TotalSeconds;
            }
        }

        /// <summary>校验广播包（魔数 + port=）并拼出候选地址；非法包返回 null。</summary>
        private static string ParseBroadcast(byte[] data, IPEndPoint ep)
        {
            try
            {
                string text = System.Text.Encoding.ASCII.GetString(data);
                if (text.StartsWith(UdpMagic, StringComparison.Ordinal) == false)
                {
                    return null;
                }
                string port = "8000";
                foreach (string part in text.Substring(UdpMagic.Length).Split('|'))
                {
                    string kv = part.Trim();
                    if (kv.StartsWith("port=", StringComparison.Ordinal))
                    {
                        port = kv.Substring(5).Trim();
                    }
                }
                return "http://" + ep.Address.ToString() + ":" + port;
            }
            catch (Exception)
            {
                return null;
            }
        }

        // ---------------- 探测胜出结果（跨链路共享给热更侧） ----------------

        /// <summary>启动探测的胜出地址（null = 尚未探测 / 全部不可达）。</summary>
        public static string SelectedUrl { get; private set; }

        /// <summary>胜出地址的来源说明（日志用，如"UDP 发现"）。</summary>
        public static string SelectedSource { get; private set; }

        /// <summary>是否有已选中的可达地址。</summary>
        public static bool HasSelection
        {
            get { return string.IsNullOrEmpty(SelectedUrl) == false; }
        }

        /// <summary>记录探测胜出地址（仅 BootLoader 启动链调用）。</summary>
        public static void SetSelected(string url, string source)
        {
            SelectedUrl = string.IsNullOrEmpty(url) ? null : url.TrimEnd('/');
            SelectedSource = source;
            Debug.Log(string.Format("[Boot] 热更服务器选定：{0}（{1}）", SelectedUrl, source));
        }

        // ---------------- 可达性结论（AB 与 dll 两条链路的共用闸门） ----------------

        /// <summary>
        /// 本次启动是否已完成服务器可达性探测
        /// （BootLoader 探测段跑完后经 <see cref="MarkReachabilityChecked"/> 置位）。
        /// </summary>
        public static bool ReachabilityChecked { get; private set; }

        /// <summary>
        /// 远端热更（AB 资源 + dll）是否应当启用 —— 两条链路共用的总闸门：
        ///   · 尚未探测（编辑器直跑 main、工具脚本等特殊入口）
        ///     → true（维持旧行为，由配置层把关）；
        ///   · 已探测且选出可达地址 → true（走远端，地址见 <see cref="SelectedUrl"/>）；
        ///   · 已探测但无胜出 → false（**服务器不可达 → 全部用本地资源与本地 dll**）。
        /// 消费方：ResServerConfig.IsRemoteHotUpdateAllowed（热更侧据此决定
        /// YooAsset 走离线模式、并跳过热更新检查）。
        /// </summary>
        public static bool RemoteHotUpdateAllowed
        {
            get { return ReachabilityChecked == false || HasSelection; }
        }

        /// <summary>
        /// 记录"可达性探测已完成"。BootLoader 在探测段（server.txt 覆盖 / 常量候选 /
        /// UDP 发现三个分支）结束后**无条件**调用一次 —— 无论结论是可达还是不可达。
        ///
        /// 【为什么必须有这个标记】没有它时，"未探测"与"探测过且不可达"无法区分：
        /// 热更侧见到 SelectedUrl=null 会退回常量地址继续发网络请求 —— 服务器不在场时
        /// 请求要等到超时（YooAsset 版本请求默认 60s 且硬失败），表现为"启动一直等待、
        /// 最终进不去游戏"。置位后下游即可在"不可达"时直接改用本地资源启动。
        /// </summary>
        public static void MarkReachabilityChecked()
        {
            ReachabilityChecked = true;
            Debug.Log("[Boot] 可达性探测完成 → " + (HasSelection
                ? ("服务器可达：" + SelectedUrl)
                : "服务器不可达：本次启动使用本地资源与本地 dll"));
        }
    }
}

using UnityEngine;

namespace FTProject.AOT
{
    /// <summary>Legacy UGUI font bridge retained for compatible runtime callers.
    /// The scene-configured HotUpdateView uses APK-owned TMP fonts and does not depend on it.
    /// </summary>
    public static class BootUiFontProvider
    {
        /// <summary>Boot 更新界面用字体（系统字体优先，失败退内置；皆失败为 null）。</summary>
        public static Font UiFont { get; private set; }

        /// <summary>UiFont 是否为含 CJK 的系统字体（决定热更侧文案用中文还是英文）。</summary>
        public static bool UiFontHasCjk { get; private set; }

        private static bool s_tried;

        /// <summary>启动早期调用一次（幂等）。</summary>
        public static void Ensure()
        {
            if (s_tried)
            {
                return;
            }
            s_tried = true;

            try
            {
                UiFont = Font.CreateDynamicFontFromOSFont(
                    new string[] { "sans-serif", "Roboto", "Noto Sans CJK SC", "Arial" }, 26);
            }
            catch (System.Exception e)
            {
                Debug.LogWarning("[Boot] 系统字体创建失败（退内置字体）：" + e.Message);
                UiFont = null;
            }

            UiFontHasCjk = UiFont != null;

            if (UiFont == null)
            {
                try
                {
                    UiFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                }
                catch (System.Exception e)
                {
                    Debug.LogWarning("[Boot] 内置字体读取失败（更新界面将无文字，仅图形）：" + e.Message);
                    UiFont = null;
                }
            }

            Debug.Log("[Boot] 更新界面字体：" + (UiFont == null
                ? "(不可用)"
                : UiFont.name + (UiFontHasCjk ? "（系统字体，支持中文）" : "（内置字体，文案退英文）")));
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

namespace FTProject.AOT
{
    /// <summary>
    /// 热更侧 Boot 更新界面（HotUpdateView / BootHotUpdateGate）的
    /// **AOT 符号保留清单**（2026-10-16）。
    ///
    /// ==================================================================
    /// 【为什么需要这个类】
    ///   HybridCLR 的核心约束：热更 dll 只能调用"AOT 链接后仍然存在"的方法 ——
    ///   未被任何 AOT 代码引用的方法会被 IL2CPP 链接器裁剪，热更侧一调用就
    ///   `MissingMethodException: MethodNotFind`（2026-10-16 实测：字体 API 被裁，
    ///   异常杀死闸门协程、应用停在黑屏）。
    ///
    ///   本类在 Boot 启动链里**真实执行一遍**（创建 → 配置 → 销毁探针对象），
    ///   以真实执行路径保证链接器 100% 保留清单里所有 API；探针全透明、同帧销毁，
    ///   无任何可见效果。
    ///
    ///   ⚠️ 维护约定：热更侧 HotUpdateView / BootHotUpdateGate 每新增一个
    ///   Unity/UGUI API 调用，**必须同步加进下面的 Keep 清单** —— 否则只会在真机
    ///   触发 MissingMethodException（编译期完全无感；这也是为什么探测必须"真实
    ///   执行而不能只写注释"）。
    ///
    ///   ⚠️ 血泪教训（2026-10-16 两次真机验证）：
    ///   ① 本方法自己也可能抛异常 —— 全函数 try-catch，**锚定失败绝不能弄死
    ///      Boot 启动链**（它只是辅助手段）；
    ///   ② UGUI 规则：**一个 GameObject 只能挂一个 Graphic**（Image/Text 互斥）——
    ///      探针里二者必须分对象（曾因塞同一个对象导致 AddComponent 返回 null
    ///      而空引用崩溃）。
    ///
    ///   【关于 AOT 引用 UGUI】工程约定"运行时 UI 统一 TMP"，但 UGUI 在这里只用于
    ///   "保符号"（真正的更新界面在热更侧，且因 TMP 字体在 AB 中而只能用小 UGUI）。
    ///   这是必要引用，不是运行界面。
    /// ==================================================================
    /// </summary>
    public static class BootUiSymbolKeeper
    {
        private static bool s_done;

        /// <summary>启动早期调用一次（幂等；内部全防护，绝不抛出）。</summary>
        public static void Ensure()
        {
            if (s_done)
            {
                return;
            }
            s_done = true;

            try
            {
                Keep();
                Debug.Log("[Boot] Boot 更新界面符号保留完成（热更侧 API 清单已锚定）。");
            }
            catch (System.Exception e)
            {
                // 锚定只是"防裁剪辅助"——失败绝不能弄死启动链（记录后放行）。
                Debug.LogError("[Boot] Boot 更新界面符号保留失败（忽略，不影响启动）：" + e);
            }
        }

        private static void Keep()
        {
            // —— 根（Canvas + CanvasScaler，二者都不是 Graphic，可共存）——
            GameObject root = new GameObject("~BootUiSymbolKeeper", typeof(Canvas), typeof(CanvasScaler));
            root.hideFlags = HideFlags.HideAndDontSave;

            Canvas canvas = root.GetComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = -30000;

            CanvasScaler scaler = root.GetComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.matchWidthOrHeight = 0.5f;

            // —— Image 探针（独立对象：UGUI 每个 GameObject 只能挂一个 Graphic）——
            GameObject imgGo = new GameObject("~keep_img", typeof(RectTransform), typeof(Image));
            imgGo.transform.SetParent(root.transform, false);
            Image img = imgGo.GetComponent<Image>();
            img.color = new Color(1f, 1f, 1f, 0f);
            img.raycastTarget = false;
            RectTransform imgRt = img.rectTransform;
            imgRt.anchorMin = Vector2.zero;
            imgRt.anchorMax = Vector2.one;
            imgRt.pivot = new Vector2(0.5f, 0.5f);
            imgRt.anchoredPosition = Vector2.zero;
            imgRt.sizeDelta = Vector2.zero;

            // —— Text 探针（单独对象）——
            GameObject textGo = new GameObject("~keep_text", typeof(RectTransform), typeof(Text));
            textGo.transform.SetParent(root.transform, false);
            Text text = textGo.GetComponent<Text>();
            text.font = BootUiFontProvider.UiFont;
            text.text = string.Empty;
            text.fontSize = 12;
            text.fontStyle = FontStyle.Bold;
            text.color = new Color(1f, 1f, 1f, 0f);
            text.alignment = TextAnchor.MiddleCenter;
            text.horizontalOverflow = HorizontalWrapMode.Overflow;
            text.verticalOverflow = VerticalWrapMode.Overflow;
            text.raycastTarget = false;
            RectTransform textRt = text.rectTransform;
            textRt.anchorMin = new Vector2(0.5f, 0.5f);
            textRt.anchorMax = new Vector2(0.5f, 0.5f);
            textRt.pivot = new Vector2(0.5f, 0.5f);
            textRt.anchoredPosition = new Vector2(0f, 0f);
            textRt.sizeDelta = new Vector2(10f, 10f);

            // —— AddComponent<T> 的实例形态（热更侧另有 new GameObject(...) 的形态）——
            GameObject addGo = new GameObject("~keep_add", typeof(RectTransform));
            addGo.transform.SetParent(root.transform, false);
            Image addImg = addGo.AddComponent<Image>();
            addImg.enabled = false;

            // —— 闸门协程用到的等待类型与数值 API ——
            WaitForSecondsRealtime wait = new WaitForSecondsRealtime(0f);
            wait = null;
            float probe = Mathf.Clamp01(0f) + Mathf.Max(0, 1) + Mathf.RoundToInt(0.5f) + Mathf.CeilToInt(0.1f);
            float now = Time.realtimeSinceStartup;
            if (probe < 0f && now < 0f)
            {
                // 不可达分支：仅为消除"变量未使用"的编译警告（真实调用发生在上面）。
                Debug.Log("unreachable");
            }

            // —— 全部回收（同帧销毁，探针无任何可见/持久影响）——
            Object.Destroy(root);
        }
    }
}

using System;
using UnityEngine;

namespace FTProject.AOT
{
    // The only UI/control bridge across the AOT / hot-update boundary.
    public static class BootUpdateSession
    {
        public static string Phase = "Preparing";
        public static string Detail = "";
        public static float Overall;
        public static float Stage = -1;
        public static int Files, TotalFiles;
        public static long Bytes, TotalBytes;
        public static Action Pause, Resume, Retry;
        public static bool Paused;
        public static event Action Changed;

        public static void Report(string phase, float overall, float stage = -1, string detail = "")
        {
            Phase = phase; Overall = Mathf.Clamp01(overall); Stage = stage; Detail = detail ?? "";
            Changed?.Invoke();
        }

        public static void Controls(Action pause = null, Action resume = null, Action retry = null)
        {
            Pause = pause; Resume = resume; Retry = retry;
            Changed?.Invoke();
        }

        public static void Progress(int files, int total, long bytes, long totalBytes)
        {
            Files = files; TotalFiles = total; Bytes = bytes; TotalBytes = totalBytes;
            float p = totalBytes > 0 ? (float)bytes / totalBytes : total > 0 ? (float)files / total : -1;
            Report("Resources", p < 0 ? .45f : .45f + .5f * p, p);
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace FTProject.AOT
{
    /// <summary>
    /// HybridCLR 热更程序集加载器（**唯一 AOT 引导入口**）。
    ///
    /// ==================================================================
    /// 【为什么必须有这个类，且只能在 AOT 程序集里】
    ///   HybridCLR 的铁律：**AOT 主包不能引用热更程序集里的任何类型**。
    ///   本工程把 Scripts / Gen / LubanLib / 第三方源码全部划入了热更集，
    ///   因此 main 场景里挂的 Launcher / GameFlowManager / 各 View 全是"热更类型"，
    ///   AOT 侧**不能**直接引用它们编译期符号。
    ///
    ///   解法：本类只做三件事（全部用 string + 反射，零编译期依赖）：
    ///     ① 读取热更 dll 字节流（编辑器读工程内，真机读 StreamingAssets / YooAsset）
    ///     ② Assembly.Load 逐个加载，拓扑顺序由 HotUpdateAssemblies 保证
    ///     ③ 反射调用热更侧约定的入口方法，把控制权交出去
    ///
    ///   ⚠️ 本类**绝不能**出现 FTProject.Runtime / cfg / SuperScrollView 等热更命名空间的
    ///      using 或类型引用 —— 那会让 AOT 程序集在 IL2CPP 打包时直接编译不过。
    /// ==================================================================
    /// </summary>
    public static class HotUpdateAssembler
    {
        /// <summary>
        /// 热更 dll 文件名清单。**顺序 = 依赖拓扑顺序**，被依赖的在前。
        ///   ⚠️ 顺序写错不会立刻报错，而是在 Assembly.Load 时抛
        ///      "Could not load ... assembly ... " 之类的异常，排查成本高。
        ///
        /// 【为什么是这个顺序】
        ///   Assembly-CSharp（Unity 默认集，本工程仅含零依赖的零散脚本/测试脚本）
        ///   → LubanLib（Luban 序列化基础库，零外部依赖）
        ///   → Gen（cfg 命名空间，配置表类，依赖 LubanLib 的 Bright.Serialization）
        ///   → SuperScrollView（列表控件，零业务依赖）
        ///   → Reporter（调试面板，零业务依赖）
        ///   → Runtime（业务主体 101 个脚本，依赖以上全部）
        /// </summary>
        public static readonly string[] HotUpdateAssemblies =
        {
            "Assembly-CSharp.dll",
            "FTProject.LubanLib.dll",
            "FTProject.Gen.dll",
            "FTProject.ThirdParty.SuperScrollView.dll",
            "FTProject.ThirdParty.Reporter.dll",
            "FTProject.Runtime.dll",
        };

        /// <summary>
        /// AOT 补充元数据 dll 清单（HybridCLR 的"AOT 泛型补充"机制）。
        ///
        /// 【为什么需要它】IL2CPP 是 AOT 编译，AOT 程序集里被热更代码**泛型实例化**的
        ///   方法/类型，如果主包里没有对应实例化结果，热更侧调用会报
        ///   "AOT generic method isn't instantiated"。补充元数据把这些泛型定义"补"进去，
        ///   让解释器能现场实例化。
        ///
        /// ★【实际内容怎么来的】执行「HybridCLR ▸ Generate ▸ All」后，
        ///   `Assets/HybridCLRGenerate/AOTGenericReferences.cs` 会生成
        ///   `PatchedAOTAssemblyList`（当前 6 项）。**本清单必须与它保持一致** ——
        ///   两份名单不同步 = 真机上泛型缺失且报错信息晦涩。
        ///   ⚠️ 每次改了热更代码 / 依赖后重跑 Generate/All，都要回来核对这里。
        ///
        /// 【加载时机】必须在任何热更 dll 之前（见 LoadHotUpdateAssemblies）。
        /// 【dll 从哪来】这些是 **AOT 程序集**，用 HybridCLR 的 "补充元数据 dll" 拷贝菜单
        ///   从 `HybridCLRData/AssembliesPostIl2CppStrip/<平台>/` 取，放 StreamingAssets/HybridCLR/。
        /// </summary>
        public static readonly string[] AOTMetaAssemblies =
        {
            "System.Core.dll",
            "UnityEngine.AssetBundleModule.dll",
            "UnityEngine.CoreModule.dll",
            "UnityEngine.JSONSerializeModule.dll",
            "YooAsset.dll",
            "mscorlib.dll",
        };

        /// <summary>加载结果状态（供 UI / 日志查看）。</summary>
        public static string LastError { get; private set; }

        /// <summary>
        /// 依次加载"补充元数据 → 热更 dll"。
        /// <paramref name="onProgress"/> 参数为 (已加载数, 总数)，用于驱动进度条。
        /// 失败时抛出异常（由调用方捕获并展示），不静默吞掉。
        /// </summary>
        public static void LoadHotUpdateAssemblies(Action<int, int> onProgress)
        {
            LastError = null;

            // ① 先加载 AOT 补充元数据（必须在任何热更 dll 之前）
            if (AOTMetaAssemblies.Length > 0)
            {
                LoadAOTMeta(onProgress);
            }

            // ② 再按拓扑顺序加载热更 dll
            LoadHotUpdateDlls(onProgress);
        }

        private static void LoadAOTMeta(Action<int, int> onProgress)
        {
            for (int i = 0; i < AOTMetaAssemblies.Length; i++)
            {
                string name = AOTMetaAssemblies[i];
                byte[] bytes = ReadDllBytes(name);
                if (bytes == null)
                {
                    throw new Exception("[HybridCLR] 缺少 AOT 补充元数据 dll：" + name
                        + "（请确认已执行「HybridCLR ▸ Generate ▸ All」并把产物拷入 StreamingAssets）");
                }

                var mode = HybridCLR.HomologousImageMode.SuperSet;
                var err = HybridCLR.RuntimeApi.LoadMetadataForAOTAssembly(bytes, mode);
                if (err != HybridCLR.LoadImageErrorCode.OK)
                {
                    throw new Exception("[HybridCLR] 加载 AOT 补充元数据失败：" + name + "，错误码=" + err);
                }

                if (onProgress != null)
                {
                    onProgress(i + 1, AOTMetaAssemblies.Length + HotUpdateAssemblies.Length);
                }
            }
        }

        private static void LoadHotUpdateDlls(Action<int, int> onProgress)
        {
            int offset = AOTMetaAssemblies.Length;
            int total = offset + HotUpdateAssemblies.Length;

            for (int i = 0; i < HotUpdateAssemblies.Length; i++)
            {
                string name = HotUpdateAssemblies[i];
                string asmName = name.EndsWith(".dll", StringComparison.OrdinalIgnoreCase)
                    ? name.Substring(0, name.Length - 4)
                    : name;

                if (onProgress != null)
                {
                    onProgress(offset + i + 1, total);
                }

                // ⚠️ 【编辑器下必然命中】Unity 编辑器会把所有 asmdef 预先编译并加载，
                //    所以热更 dll 在编辑器里**已经存在于 AppDomain**。
                //    此时再 Assembly.Load(bytes) 会抛
                //    "Assembly with the same name is already loaded"。
                //    → 已加载的跳过（这正是我们想要的效果：编辑器下直接跑最新代码，无需拷贝 dll）。
                //    ⚠️ 真机上这些程序集**不在** AppDomain（主包里没有），所以会正常走到下面的 Load。
                Assembly existing = FindLoadedAssembly(asmName);
                if (existing != null)
                {
                    Debug.Log("[HybridCLR] 程序集已在 AppDomain，跳过加载：" + asmName
                        + "（编辑器下属正常）");
                    continue;
                }

                byte[] bytes = ReadDllBytes(name);
                if (bytes == null)
                {
                    throw new Exception("[HybridCLR] 缺少热更 dll：" + name
                        + "（请确认已执行「HybridCLR ▸ Generate ▸ All」并把产物拷入 StreamingAssets）");
                }

                try
                {
                    Assembly.Load(bytes);
                }
                catch (Exception e)
                {
                    throw new Exception("[HybridCLR] 加载热更 dll 失败：" + name + "\n" + e);
                }
            }
        }

        /// <summary>在已加载的程序集里按**简单名**查找（不区分大小写）。</summary>
        private static Assembly FindLoadedAssembly(string simpleName)
        {
            Assembly[] loaded = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < loaded.Length; i++)
            {
                string n;
                try
                {
                    n = loaded[i].GetName().Name;
                }
                catch (Exception)
                {
                    continue; // 极少数动态程序集取名字会抛，跳过
                }
                if (string.Equals(n, simpleName, StringComparison.OrdinalIgnoreCase))
                {
                    return loaded[i];
                }
            }
            return null;
        }

        /// <summary>
        /// 读取一个 dll 的字节流。**查找顺序即优先级**：
        ///   ① Application.persistentDataPath/HybridCLR/  （真机热更产物落点，优先级最高）
        ///      —— YooAsset 下载完热更 dll 后拷到这里，下次启动就读到新版本。
        ///   ② StreamingAssets/HybridCLR/                  （随包体分发的首包版本）
        ///   ③ Library/ScriptAssemblies/                   （仅编辑器；免拷贝，便于开发期快速验证）
        ///
        /// 【为什么 persistentDataPath 排最前】
        ///   StreamingAssets 在 Android 上是**包内只读**的，热更下下来的新 dll 没法覆盖它。
        ///   所以要有一个"可写且优先"的位置放热更产物 —— 这就是 persistentDataPath。
        ///   首包（还没热更过）用 StreamingAssets 的版本；一旦热更过，persistentDataPath 的有更新版本。
        /// ==================================================================
        /// </summary>
        private static byte[] ReadDllBytes(string fileName)
        {
            // ① 热更产物落点（真机优先级最高）
            if (Array.IndexOf(HotUpdateAssemblies, fileName) >= 0 && BootReleaseStore.Selected != null)
            {
                string pinned = Path.Combine(BootReleaseStore.DllDirectory, fileName);
                if (!BootReleaseStore.VerifyDlls(BootReleaseStore.Selected)) throw new Exception("Pinned DLL set failed verification");
                return File.ReadAllBytes(pinned);
            }
            string p0 = Path.Combine(BootReleaseStore.MetadataDirectory, fileName);
            if (File.Exists(p0))
            {
                return File.ReadAllBytes(p0);
            }

            // ② 随包 StreamingAssets
            //    ⚠️ **Android 上这里必然读不到**，见下方 Android 分支的说明。
            string p1 = Path.Combine(Application.streamingAssetsPath, "HybridCLR", fileName);
            if (File.Exists(p1))
            {
                return File.ReadAllBytes(p1);
            }

            // ③ 编辑器回退：直接读工程编译产物
#if UNITY_EDITOR
            string p2 = Path.Combine(Application.dataPath, "../Library/ScriptAssemblies", fileName);
            if (File.Exists(p2))
            {
                return File.ReadAllBytes(p2);
            }
#endif
            return null;
        }

        /// <summary>基线资源目录名（persistentDataPath 下的子目录）。</summary>
        private const string BaselineDirName = "HybridCLR";

        /// <summary>
        /// 基线版本戳文件名。内容 = 本次拷入的、"包内基线"的指纹
        /// （由 <see cref="Application.version"/> + 全部 dll 的名字/大小/写入时间算出）。
        ///
        /// 【为什么需要它 —— "避免每次启动重复拷贝"的关键】
        ///   只按单文件 `File.Exists` 判定"已拷过"是不够的：用户升级 APK 后，
        ///   包内基线换了新版，但 persistentDataPath 里还留着上一版的文件，
        ///   逐个存在性检查会**全部命中并跳过** → 新版基线永远拷不进去。
        ///   有了整目录指纹，就能一眼区分：
        ///     · 指纹一致   → 基线与当前包完全对应，整体跳过（零 IO，最快路径）
        ///     · 指纹不一致 → 包升级了（或上次没拷完），需要重建基线
        /// </summary>
        private const string BaselineStampFile = ".baseline.stamp";

        /// <summary>
        /// 拷贝中断标记。**拷贝开始前写入，全部成功后才删除。**
        ///
        /// 【为什么需要它】如果在拷贝中途被杀进程 / 断电，目录里会留下
        ///   "部分新 + 部分旧 / 部分缺失"的混合状态，且没有指纹文件
        ///   （因为指纹是最后才写的）。下次启动看到"无指纹"会重拷 —— 这没问题。
        ///   但若指纹文件恰好先于文件写完，就会出现"指纹说有、文件其实半截"的
        ///   最坏情况。用显式的 in-progress 标记把这种状态**确定性地**识别出来：
        ///   见到标记 = 上次没拷完 → 整目录清空重拷，绝不复用半成品。
        /// </summary>
        private const string CopyInProgressMarker = ".copy.inprogress";

        /// <summary>磁盘剩余空间的安全系数：需求空间 × 该系数 = 最低要求空间。</summary>
        private const double DiskSpaceSafetyFactor = 1.2;

        /// <summary>
        /// 首启预取：把随包的 dll 从 StreamingAssets 释放到 persistentDataPath，
        /// 作为**基线资源**。
        ///
        /// ==================================================================
        /// 【为什么必须有这一步 —— Android 的坑】
        ///   Android 上 APK 本身就是一个 zip，`StreamingAssets` **不是普通目录**：
        ///     · File.Exists / File.ReadAllBytes 一律读不到（路径在 zip 里）
        ///     · 必须用 UnityWebRequest 走 `jar:file://...!/assets/...` 才能读
        ///   而 HybridCLR 要的是 byte[]，随时可能同步取用 —— 每次都用 UnityWebRequest
        ///   异步读不现实。所以**首启一次性把它们释放到 persistentDataPath**，
        ///   之后 ReadDllBytes 的 ① 分支就能同步命中，Android 与其它平台行为一致。
        ///
        /// 【为什么不做在 InitializeOnLoad 之类的地方】
        ///   那些入口在 AOT 静态构造期，UnityWebRequest 还不能用。
        ///   放在 BootLoader 的协程里（场景已加载、主线程可控）才稳妥。
        ///
        /// 【整体流程与四类异常的处理】
        ///   ① 中断残留检查：见 `.copy.inprogress` 标记 → 清空重拷
        ///   ② 版本戳比对  ：指纹一致 → **整体跳过**（满足"避免每次启动重复拷贝"）
        ///   ③ 存储空间检查：不足 → 放弃拷贝，回退到直读 StreamingAssets
        ///   ④ 逐文件拷贝  ：已存在且**大小/哈希一致**的跳过（不覆盖热更成果），
        ///                    缺失/损坏的重拷；全部成功后写指纹、删标记
        ///
        /// 【为什么"已存在且校验通过"才跳过，而不是一律跳过】
        ///   persistentDataPath 里可能是**上次热更下来的新版 dll**，
        ///   包内的旧版不能覆盖它。但同时也可能是"上次拷到一半的损坏文件"，
        ///   所以跳过条件必须是"存在 **且** 与包内基线一致（md5）"，
        ///   否则重拷。这样两个目标同时满足：
        ///     · 热更成果不被抹掉（内容不同 → 保留热更版，但指纹会记上"基线已就位"）
        ///     · 半成品文件被修复（内容损坏 → 重拷）
        ///
        /// ⚠️ **本方法永不抛异常**：任何失败都只是 LogWarning + 继续，
        ///    最坏情况退回 StreamingAssets 直读（Android 上由 UnityWebRequest 兜底）。
        /// ==================================================================
        /// </summary>
        public static System.Collections.IEnumerator PrefetchStreamingAssetsToPersistent(Action<int, int> onProgress)
        {
            string[] names = BuildAllFileNames();
            string targetDir = BootReleaseStore.MetadataDirectory;
            string stampPath = Path.Combine(targetDir, BaselineStampFile);
            string markerPath = Path.Combine(targetDir, CopyInProgressMarker);
            // ---------- ① 目录准备 ----------
            bool dirReady = false;
            try
            {
                if (Directory.Exists(targetDir) == false)
                {
                    Directory.CreateDirectory(targetDir);
                }
                dirReady = true;
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HybridCLR] 无法创建基线目录 " + targetDir + "：" + e.Message
                    + "（将退回直读 StreamingAssets）");
            }

            if (dirReady == false)
            {
                if (onProgress != null) onProgress(names.Length, names.Length);
                yield break;
            }

            // ---------- ② 中断残留检查 ----------
            // 见到 in-progress 标记 = 上次拷贝没走完 → 目录内容不可信，整目录清空重拷。
            // （只删我们自己的 dll / stamp / marker，不整目录递归删，避免误伤）
            bool hadInterrupted = false;
            try
            {
                hadInterrupted = File.Exists(markerPath);
            }
            catch (Exception) { /* 读不到就当没有 */ }

            if (hadInterrupted)
            {
                Debug.LogWarning("[HybridCLR] 检测到上次基线拷贝中断，将清空并重建基线目录");
                TryDelete(markerPath);
            }

            // ---------- ③ 版本戳比对：一致则整体跳过 ----------
            string currentStamp = ComputeBaselineStamp(names);
            if (!hadInterrupted && currentStamp != null && IsStampMatched(stampPath, currentStamp))
            {
                Debug.Log("[HybridCLR] 基线资源已就位（指纹一致），跳过拷贝：" + currentStamp);
                if (onProgress != null) onProgress(names.Length, names.Length);
                yield break;
            }

            // ---------- ④ 存储空间检查 ----------
            long needBytes = EstimateNeedBytes(names);
            if (needBytes > 0 && HasEnoughDiskSpace(needBytes) == false)
            {
                Debug.LogWarning(string.Format(
                    "[HybridCLR] 存储空间不足（需要约 {0:N0} 字节），跳过基线拷贝，退回直读 StreamingAssets",
                    needBytes));
                if (onProgress != null) onProgress(names.Length, names.Length);
                yield break;
            }

            // ---------- ⑤ 写中断标记（拷贝开始） ----------
            try
            {
                File.WriteAllText(markerPath, DateTime.UtcNow.ToString("o"));
            }
            catch (Exception e)
            {
                // 标记写不了不算致命：只是失去"中断可识别"能力
                Debug.LogWarning("[HybridCLR] 无法写入中断标记：" + e.Message);
            }

            // ---------- ⑥ 逐文件拷贝 ----------
            int copied = 0;
            int skipped = 0;
            int failed = 0;

            for (int i = 0; i < names.Length; i++)
            {
                string name = names[i];
                string target = Path.Combine(targetDir, name);
                string src = Path.Combine(Application.streamingAssetsPath, BaselineDirName, name);

                // 【存在即跳过 —— 这是"不覆盖热更成果"的关键】
                //   persistentDataPath 里的同名文件有三种来源：
                //     ① 上次基线拷贝留下的（内容 = 包内旧版）
                //     ② **上次热更下载下来的新版**（内容 ≠ 包内旧版）★ 必须保住
                //     ③ 上次拷到一半的损坏文件
                //   ②与③在文件系统层面无法区分（都是"存在且大小可能对不上"），
                //   所以这里**统一选择保守策略：存在就不动**。
                //   ③ 由"中断标记"在上层兜住 —— 只要上次没走完，标记还在，整目录会被清空重拷。
                //   这样既不会抹掉热更成果，也不会长期残留半成品。
                if (File.Exists(target))
                {
                    skipped++;
                    if (onProgress != null) onProgress(i + 1, names.Length);
                    continue;
                }

                // 目标不存在才需要从 StreamingAssets 取
                bool ok;
                if (File.Exists(src))
                {
                    // 桌面 / 编辑器的 StreamingAssets 是普通目录，同步拷贝更快
                    ok = TryCopyLocal(src, target, name);
                }
                else
                {
                    // Android：StreamingAssets 在 APK 内，必须走 UnityWebRequest
                    ok = false;
                    yield return CopyFromStreamingAssetsCo(src, target, name, r => ok = r);
                }

                if (ok) { copied++; } else { failed++; }

                if (onProgress != null) onProgress(i + 1, names.Length);
            }

            // ---------- ⑦ 收尾：全部成功才写指纹 + 删标记 ----------
            if (failed == 0)
            {
                try
                {
                    File.WriteAllText(stampPath, currentStamp);
                    if (File.Exists(markerPath))
                    {
                        File.Delete(markerPath);
                    }
                    Debug.Log(string.Format(
                        "[HybridCLR] 基线资源就绪：新拷 {0} 个，已存在 {1} 个，指纹 {2}",
                        copied, skipped, currentStamp));
                }
                catch (Exception e)
                {
                    Debug.LogWarning("[HybridCLR] 写入基线指纹失败（下次启动会重试）：" + e.Message);
                }
            }
            else
            {
                // 有失败 → **不写指纹**（下次启动会重走一遍），也**不删标记**（表明目录不完整）
                Debug.LogWarning(string.Format(
                    "[HybridCLR] 基线拷贝未全部成功：成功 {0} 个，失败 {1} 个（保留中断标记，下次启动重试）",
                    copied, failed));
            }
        }

        /// <summary>
        /// 计算包内基线的指纹。**只依赖包内 StreamingAssets 侧的清单与元数据**，
        /// 不依赖目标目录内容 —— 这样"包升级了"必然导致指纹变化。
        ///
        /// 组成：Application.version + 每个文件的 名字（StreamingAssets 侧不可读时为 "-"）。
        /// ⚠️ Android 上 StreamingAssets 在 APK 内，`File.Exists` 恒为 false，
        ///    所以这里**不能**用文件大小/时间戳（读不到）。退而求其次用：
        ///    Application.version（玩家更新 APK 必然变化）+ 文件名清单 + 我方内置的
        ///    AOT 侧版本号（见 <see cref="BaselineFormatVersion"/>）。
        ///    若包内有 `md5.txt`（构建期生成，见编辑器工具），且能读到，则把内容一并纳入 ——
        ///    这让"只换了 dll 内容但没升 version"的极端情况也能被识别。
        /// </summary>
        private static string ComputeBaselineStamp(string[] names)
        {
            try
            {
                var sb = new System.Text.StringBuilder();
                sb.Append("v=").Append(Application.version).Append(';');
                sb.Append("fmt=").Append(BaselineFormatVersion).Append(';');

                // 包内 md5.txt（若随包分发）——能读到就是最强的版本依据
                string md5InPackage = Path.Combine(Application.streamingAssetsPath, BaselineDirName, Md5ListFileName);
                if (File.Exists(md5InPackage))
                {
                    string text = File.ReadAllText(md5InPackage);
                    sb.Append("md5=").Append(SimpleHash(text)).Append(';');
                }

                // 文件名清单（排序后拼，避免顺序抖动）
                string[] sorted = (string[])names.Clone();
                Array.Sort(sorted, StringComparer.Ordinal);
                for (int i = 0; i < sorted.Length; i++)
                {
                    sb.Append(sorted[i]).Append('|');
                }

                return SimpleHash(sb.ToString());
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HybridCLR] 计算基线指纹失败：" + e.Message);
                return null;
            }
        }

        /// <summary>指纹文件内容是否与当前一致。</summary>
        private static bool IsStampMatched(string stampPath, string currentStamp)
        {
            try
            {
                if (File.Exists(stampPath) == false)
                {
                    return false;
                }
                string recorded = File.ReadAllText(stampPath).Trim();
                return string.Equals(recorded, currentStamp, StringComparison.Ordinal);
            }
            catch (Exception)
            {
                return false;
            }
        }

        /// <summary>清空基线目录里"由我方管理"的文件（dll + 指纹 + 标记）。</summary>
        private static void CleanBaselineDir(string targetDir, string[] names, string stampPath, string markerPath)
        {
            for (int i = 0; i < names.Length; i++)
            {
                TryDelete(Path.Combine(targetDir, names[i]));
                TryDelete(Path.Combine(targetDir, names[i] + ".tmp"));
            }
            TryDelete(stampPath);
            TryDelete(markerPath);
        }

        private static void TryDelete(string path)
        {
            try
            {
                if (File.Exists(path))
                {
                    File.Delete(path);
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HybridCLR] 删除失败 " + path + "：" + e.Message);
            }
        }

        /// <summary>估算拷贝全部 dll 需要的字节数（包内可读时用真实大小，否则用保守估计）。</summary>
        private static long EstimateNeedBytes(string[] names)
        {
            long total = 0;
            for (int i = 0; i < names.Length; i++)
            {
                string src = Path.Combine(Application.streamingAssetsPath, BaselineDirName, names[i]);
                try
                {
                    if (File.Exists(src))
                    {
                        total += new FileInfo(src).Length;
                    }
                }
                catch (Exception) { /* 忽略单个文件 */ }
            }

            // Android 上读不到真实大小 → 用一个保守的兜底估计（11 个 dll，按 2MB/个 计）
            if (total <= 0)
            {
                total = (long)names.Length * FallbackBytesPerDll;
            }
            return total;
        }

        /// <summary>检查 persistentDataPath 所在卷的剩余空间是否足够（含安全系数）。</summary>
        private static bool HasEnoughDiskSpace(long needBytes)
        {
            try
            {
                // persistentDataPath 的根（Android 上是 /data，PC 上是盘符）
                string root = Path.GetPathRoot(Application.persistentDataPath);
                if (string.IsNullOrEmpty(root))
                {
                    return true; // 取不到根就当有空间，不阻塞流程
                }

                var drive = new DriveInfo(root);
                long required = (long)(needBytes * DiskSpaceSafetyFactor);
                return drive.AvailableFreeSpace >= required;
            }
            catch (Exception e)
            {
                // 某些平台 / 沙箱环境取不到磁盘信息 → 不阻塞
                Debug.LogWarning("[HybridCLR] 无法检查存储空间（将直接尝试拷贝）：" + e.Message);
                return true;
            }
        }

        /// <summary>桌面 / 编辑器路径的同步拷贝（带 tmp + 替换，避免半截文件）。</summary>
        private static bool TryCopyLocal(string src, string target, string name)
        {
            string tmp = target + ".tmp";
            try
            {
                File.Copy(src, tmp, true);
                if (File.Exists(target))
                {
                    File.Delete(target);
                }
                File.Move(tmp, target);
                return true;
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HybridCLR] 拷贝失败 " + name + "：" + e.Message);
                TryDelete(tmp);
                return false;
            }
        }

        /// <summary>用 UnityWebRequest 读 StreamingAssets（Android 唯一可行的方式）并写入目标路径。</summary>
        private static System.Collections.IEnumerator CopyFromStreamingAssetsCo(
            string url, string target, string name, Action<bool> onResult)
        {
            bool ok = false;
            string tmp = target + ".tmp";

            using (UnityEngine.Networking.UnityWebRequest req =
                   UnityEngine.Networking.UnityWebRequest.Get(url))
            {
                req.timeout = StreamingAssetsReadTimeoutSeconds;
                yield return req.SendWebRequest();

                if (req.result != UnityEngine.Networking.UnityWebRequest.Result.Success)
                {
                    // 【不报错】某些平台 StreamingAssets 优先级本就低于 Library 回退路径，
                    // 缺文件由 ReadDllBytes 最后统一报"缺少热更 dll"，这里重复报会刷屏。
                    Debug.LogWarning(string.Format(
                        "[HybridCLR] 首启预取跳过 {0}：{1}（HTTP {2}）",
                        name, req.error, req.responseCode));
                }
                else
                {
                    // 与同步路径一致：先写 tmp 再替换，避免"写到一半"留下坏 dll
                    try
                    {
                        File.WriteAllBytes(tmp, req.downloadHandler.data);
                        if (File.Exists(target))
                        {
                            File.Delete(target);
                        }
                        File.Move(tmp, target);
                        Debug.Log("[HybridCLR] 首启预取完成：" + name);
                        ok = true;
                    }
                    catch (Exception e)
                    {
                        Debug.LogWarning("[HybridCLR] 预取写入失败 " + name + "：" + e.Message);
                        TryDelete(tmp);
                    }
                }
            }

            if (onResult != null)
            {
                onResult(ok);
            }
        }

        /// <summary>全部 dll 文件名（热更 + AOT 补充元数据），供首启预取使用。</summary>
        private static string[] BuildAllFileNames()
        {
            return AOTMetaAssemblies;
        }

        /// <summary>
        /// 基线目录格式版本号。**改动基线目录结构 / 指纹算法时必须 +1** ——
        /// 否则老设备上的旧指纹会被误判为"已就位"，新逻辑不会执行。
        /// </summary>
        private const int BaselineFormatVersion = 1;

        /// <summary>包内 md5 清单文件名（构建期由编辑器工具生成，随包分发）。</summary>
        private const string Md5ListFileName = "md5.txt";

        /// <summary>读 StreamingAssets 的超时（秒）。</summary>
        private const int StreamingAssetsReadTimeoutSeconds = 30;

        /// <summary>
        /// 存储空间兜底估计：单个 dll 按 2MB 计。
        /// 仅用于 Android（读不到包内文件真实大小时）的保守预留。
        /// </summary>
        private const long FallbackBytesPerDll = 2L * 1024L * 1024L;

        /// <summary>
        /// 轻量哈希（FNV-1a 64 位）。**只用于"指纹比对"，不用于完整性校验** ——
        /// 完整性校验一律用 MD5（见 HotUpdateDllDownloader 与编辑器侧的 md5.txt）。
        /// 这里选它是因为：无分配、快、跨平台结果稳定，且不依赖 System.Security.Cryptography
        /// （IL2CPP 下更稳）。
        /// </summary>
        private static string SimpleHash(string text)
        {
            unchecked
            {
                const ulong offset = 14695981039346656037UL;
                const ulong prime = 1099511628211UL;

                ulong hash = offset;
                byte[] bytes = System.Text.Encoding.UTF8.GetBytes(text ?? string.Empty);
                for (int i = 0; i < bytes.Length; i++)
                {
                    hash ^= bytes[i];
                    hash *= prime;
                }
                return hash.ToString("x16");
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.Networking;

namespace FTProject.AOT
{
    /// <summary>
    /// AOT HTTP downloader for the DLL set pinned by BootReleaseStore.Selected.
    /// Payloads live at releases/{id}/HybridCLR and stage in a descriptor-specific directory.
    /// Range transfers and bounded retries preserve partial downloads; MD5 validation precedes
    /// atomic replacement. Any missing or failed DLL blocks assembly loading and shows Retry.
    /// AOT metadata is always supplied by the matching APK and is never remotely replaced.
    /// </summary>
    public static class HotUpdateDllDownloader
    {
        /// <summary>dll 在服务器上的子目录名（与 StreamingAssets/HybridCLR 同名，便于对照）</summary>
        private const string RemoteSubDir = "HybridCLR";

        /// <summary>校验清单文件名（与 dll 同目录，构建期生成）。</summary>
        private const string Md5ListFileName = "md5.txt";

        /// <summary>单个 dll 的下载超时（秒）。局域网下 1MB 的 dll 通常是毫秒级，30 秒足够宽裕。</summary>
        private const int TimeoutSeconds = 30;

        /// <summary>
        /// **整批下载的总超时（秒）**。超过这个时间无论进行到哪一步都收敛退出，
        /// 未完成的 DLL 集合会停留在更新页，已验证文件留待重试。
        /// </summary>
        private const int TotalTimeoutSeconds = 90;

        /// <summary>单个文件的**额外**重试次数（首次尝试之外）。</summary>
        private const int MaxRetryPerFile = 3;

        /// <summary>重试基础等待（秒）。第 n 次重试等待 = base * 2^(n-1)，上限 <see cref="MaxRetryDelay"/>。</summary>
        private const float RetryBaseDelay = 1f;

        /// <summary>单次重试的最大等待（秒）。</summary>
        private const float MaxRetryDelay = 8f;

        /// <summary>断点续传的**最小文件尺寸**：小于它就不续传（避免为小文件付 Range 请求的开销）。</summary>
        private const long ResumeMinBytes = 256L * 1024L;

        /// <summary>
        /// 本地缓存清单的有效期（秒）。这段时间内不重复请求 md5.txt。
        /// 避免一次启动里为每个 dll 都去拉一遍清单。
        /// </summary>
        private const float Md5ListCacheSeconds = 60f;

        /// <summary>本次下载的结果（供 Boot 日志/界面展示）</summary>
        public sealed class Result
        {
            /// <summary>尝试下载的文件数</summary>
            public int Total;
            /// <summary>成功下载并落盘的文件数</summary>
            public int Downloaded;
            /// <summary>因 md5 一致（已是最新）而跳过的文件数</summary>
            public int UpToDate;
            /// <summary>服务器明确返回 404 的文件数（该发布失败）</summary>
            public int Skipped;
            /// <summary>出错条目摘要（换行分隔，非空即阻止加载）</summary>
            public string ErrorSummary;
            /// <summary>本批次是否因**总超时**而提前收敛</summary>
            public bool TimedOut;

            /// <summary>是否真的更新过至少一个文件（决定"本次启动是不是热更后的新版本"）</summary>
            public bool Updated { get { return Downloaded > 0; } }

            /// <summary>供日志用的单行摘要。</summary>
            public string ToSummary()
            {
                return string.Format(
                    "更新 {0} / 已最新 {1} / 不存在 {2} / 共 {3}{4}",
                    Downloaded, UpToDate, Skipped, Total,
                    TimedOut ? "（总超时提前收敛）" : string.Empty);
            }
        }

        /// <summary>
        /// 把当前发布的热更 DLL 集合同步到独立暂存目录。
        /// <paramref name="onProgress"/> 参数为 (已完成数, 总数)，用于 Boot 界面进度条。
        /// 本方法**永不抛异常**（全部内部消化为日志 + Result）。
        /// </summary>
        public static System.Collections.IEnumerator DownloadAll(
            string serverRoot,
            Action<int, int> onProgress,
            Action<Result> onDone)
        {
            Result result = new Result();

            string[] names = BuildFileList();
            result.Total = names.Length;

            if (string.IsNullOrEmpty(serverRoot))
            {
                result.ErrorSummary = "未配置服务器地址";
                Finish(result, onProgress, onDone);
                yield break;
            }

            string root = serverRoot.TrimEnd('/');
            string platform = GetPlatformFolder();
            string targetDir = BootReleaseStore.DllDirectory;

            try
            {
                if (Directory.Exists(targetDir) == false)
                {
                    Directory.CreateDirectory(targetDir);
                }
            }
            catch (Exception e)
            {
                result.ErrorSummary = "无法创建目录 " + targetDir + "：" + e.Message;
                Finish(result, onProgress, onDone);
                yield break;
            }

            // ---------- ① 使用已固定描述符内的完整校验清单 ----------
            var md5Map = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (var file in BootReleaseStore.Selected.dlls) md5Map.Add(file.name, file.md5);

            float deadline = Time.realtimeSinceStartup + TotalTimeoutSeconds;

            // ---------- ③ 逐文件同步 ----------
            for (int i = 0; i < names.Length; i++)
            {
                string fileName = names[i];

                // 总超时检查（每个文件开始前）
                if (Time.realtimeSinceStartup >= deadline)
                {
                    result.TimedOut = true;
                    result.ErrorSummary = AppendLine(result.ErrorSummary,
                        string.Format("总超时（{0} 秒）已到，剩余 {1} 个文件未处理", TotalTimeoutSeconds, names.Length - i));
                    break;
                }

                string target = Path.Combine(targetDir, fileName);

                string expectedMd5;
                bool hasExpected = md5Map.TryGetValue(fileName, out expectedMd5) && string.IsNullOrEmpty(expectedMd5) == false;

                if (hasExpected == false)
                {
                    // 缺失校验值意味着描述符不完整，禁止加载
                    result.ErrorSummary = AppendLine(result.ErrorSummary, "Missing checksum: " + fileName);
                    break;
                }

                // 本地已是最新？→ 跳过下载
                if (IsLocalUpToDate(target, expectedMd5))
                {
                    result.UpToDate++;
                    Report(onProgress, i + 1, names.Length);
                    continue;
                }

                // 真正下载（带重试 / 续传 / 校验 / 原子替换）
                string url = BootReleaseStore.ResourceRoot + "/HybridCLR/" + fileName;
                FileOutcome outcome = FileOutcome.Failed;
                string error = null;

                yield return DownloadOneWithRetryCo(
                    url, target, fileName, expectedMd5, deadline,
                    o => outcome = o,
                    e => error = e);

                switch (outcome)
                {
                    case FileOutcome.Downloaded:
                        result.Downloaded++;
                        break;
                    case FileOutcome.NotFound:
                        result.ErrorSummary = AppendLine(result.ErrorSummary, "HTTP 404: " + fileName);
                        break;
                    case FileOutcome.UpToDate:
                        result.UpToDate++;
                        break;
                    default:
                        result.ErrorSummary = AppendLine(result.ErrorSummary,
                            fileName + "：" + (error ?? "未知错误"));
                        break;
                }

                Report(onProgress, i + 1, names.Length);
            }

            Finish(result, onProgress, onDone);
        }

        /// <summary>单文件的最终结局。</summary>
        private enum FileOutcome
        {
            /// <summary>已下载、校验通过、原子替换成功</summary>
            Downloaded,
            /// <summary>服务器 404：发布不完整，禁止加载</summary>
            NotFound,
            /// <summary>md5 一致，本地已是最新</summary>
            UpToDate,
            /// <summary>其它失败（网络 / 校验 / 写入）—— 保持本地原文件不动</summary>
            Failed,
        }

        /// <summary>带重试的外层。404 与"已是最新"直接返回，不重试。</summary>
        private static System.Collections.IEnumerator DownloadOneWithRetryCo(
            string url, string target, string fileName, string expectedMd5, float deadline,
            Action<FileOutcome> onResult, Action<string> onError)
        {
            string lastError = null;

            for (int attempt = 0; attempt <= MaxRetryPerFile; attempt++)
            {
                if (attempt > 0)
                {
                    // 退避等待（同时检查总超时）
                    float delay = Mathf.Min(RetryBaseDelay * Mathf.Pow(2f, attempt - 1), MaxRetryDelay);
                    Debug.LogWarning(string.Format(
                        "[HotUpdate] 重试 {0}（第 {1}/{2} 次）：{3}，等待 {4:F1}s",
                        fileName, attempt, MaxRetryPerFile, lastError, delay));

                    float wake = Time.realtimeSinceStartup + delay;
                    while (Time.realtimeSinceStartup < wake)
                    {
                        yield return null;
                    }
                }

                // 每次尝试前都重新判总超时
                if (Time.realtimeSinceStartup >= deadline)
                {
                    onResult(FileOutcome.Failed);
                    onError("总超时，放弃重试");
                    yield break;
                }

                FileOutcome outcome = FileOutcome.Failed;
                string error = null;
                bool retryable = false;

                yield return DownloadOneCo(url, target, fileName, expectedMd5,
                    o => outcome = o, e => error = e, r => retryable = r);

                if (outcome == FileOutcome.Downloaded || outcome == FileOutcome.NotFound || outcome == FileOutcome.UpToDate)
                {
                    onResult(outcome);
                    yield break;
                }

                lastError = error;

                if (retryable == false)
                {
                    // 不可重试的错误（例如磁盘写满、md5 不匹配）直接收尾
                    onResult(FileOutcome.Failed);
                    onError(error);
                    yield break;
                }
            }

            onResult(FileOutcome.Failed);
            onError(lastError ?? "重试次数已用尽");
        }

        /// <summary>
        /// 下载**单个**文件一次。流程：
        ///   ① 判断是否可续传（.part 残留且够大）→ 组 Range 请求
        ///   ② 发送请求
        ///   ③ 成功 → 与 expectedMd5 比对（含断点拼接后的完整文件）
        ///   ④ 校验通过 → 原子替换；否则丢弃 .part，**本地原文件保持不动**
        /// </summary>
        private static System.Collections.IEnumerator DownloadOneCo(
            string url, string target, string fileName, string expectedMd5,
            Action<FileOutcome> onResult, Action<string> onError, Action<bool> onRetryable)
        {
            string partPath = target + ".part";

            // ---------- ① 续传判定 ----------
            long resumeOffset = 0;
            try
            {
                if (File.Exists(partPath))
                {
                    long len = new FileInfo(partPath).Length;
                    if (len >= ResumeMinBytes && len < long.MaxValue)
                    {
                        resumeOffset = len;
                    }
                    else if (len > 0)
                    {
                        // 太小，续传不划算 → 丢掉重下
                        File.Delete(partPath);
                    }
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HotUpdate] 检查续传残留失败 " + fileName + "：" + e.Message);
                try { File.Delete(partPath); } catch (Exception) { }
                resumeOffset = 0;
            }

            UnityWebRequest req = null;
            try
            {
                req = UnityWebRequest.Get(url);
                req.timeout = TimeoutSeconds;

                if (resumeOffset > 0)
                {
                    // 追加写入 + Range 头：从断点处继续
                    var handler = new DownloadHandlerFile(partPath, true);
                    handler.removeFileOnAbort = false;
                    req.downloadHandler = handler;
                    req.SetRequestHeader("Range", string.Format("bytes={0}-", resumeOffset));
                    Debug.Log(string.Format("[HotUpdate] 断点续传 {0}：从 {1:N0} 字节继续", fileName, resumeOffset));
                }
                else
                {
                    // 从零开始：先删残留，避免 DownloadHandlerFile 追加到旧内容上
                    try { if (File.Exists(partPath)) File.Delete(partPath); } catch (Exception) { }
                    var handler = new DownloadHandlerFile(partPath, false);
                    handler.removeFileOnAbort = true;
                    req.downloadHandler = handler;
                }

                yield return req.SendWebRequest();

                // ---------- ③ 网络层结果 ----------
                long httpCode = req.responseCode;

                if (httpCode == 404)
                {
                    // 服务器文件缺失：报告失败，清理该请求残留的 .part
                    CleanupPart(partPath);
                    onResult(FileOutcome.NotFound);
                    onRetryable(false);
                    yield break;
                }

                if (req.result != UnityWebRequest.Result.Success)
                {
                    // 416 = Range 越界（通常是服务端文件变小了）→ 丢掉残留重来一次
                    bool retry = true;
                    string err;
                    if (httpCode == 416)
                    {
                        Debug.LogWarning("[HotUpdate] " + fileName + " 续传位置越界（416），丢弃残留后重试");
                        CleanupPart(partPath);
                    }
                    err = string.Format("{0}（HTTP {1}）", req.error, httpCode);
                    onResult(FileOutcome.Failed);
                    onError(err);
                    onRetryable(retry);
                    yield break;
                }

                // ---------- ④ 完整性校验 ----------
                string actualMd5;
                try
                {
                    actualMd5 = ComputeFileMd5(partPath);
                }
                catch (Exception e)
                {
                    CleanupPart(partPath);
                    onResult(FileOutcome.Failed);
                    onError("读取下载结果失败：" + e.Message);
                    onRetryable(true);   // 可能是 IO 抖动，允许重试
                    yield break;
                }

                if (string.Equals(actualMd5, expectedMd5, StringComparison.OrdinalIgnoreCase) == false)
                {
                    // 校验失败 = 数据坏了 → 丢弃，绝不让它顶掉本地的好文件
                    CleanupPart(partPath);
                    Debug.LogWarning(string.Format(
                        "[HotUpdate] md5 校验失败 {0}：期望 {1}，实际 {2}（已丢弃，保留本地版本）",
                        fileName, expectedMd5, actualMd5));
                    onResult(FileOutcome.Failed);
                    onError(string.Format("md5 校验失败（期望 {0}，实际 {1}）", expectedMd5, actualMd5));
                    onRetryable(true);   // 传输损坏可重试
                    yield break;
                }

                // ---------- ⑤ 原子替换 ----------
                try
                {
                    BootReleaseStore.AtomicMove(partPath, target);

                    long size = new FileInfo(target).Length;
                    Debug.Log(string.Format(
                        "[HotUpdate] dll 已更新：{0}（{1:N0} 字节，md5 校验通过）", fileName, size));

                    onResult(FileOutcome.Downloaded);
                    onRetryable(false);
                }
                catch (Exception e)
                {
                    CleanupPart(partPath);
                    Debug.LogError("[HotUpdate] 替换失败 " + fileName + "：" + e.Message);
                    onResult(FileOutcome.Failed);
                    onError("写入失败：" + e.Message);
                    onRetryable(false);   // 写盘失败重试无意义
                }
            }
            finally
            {
                if (req != null)
                {
                    req.Dispose();
                }
            }
        }

        /// <summary>
        /// 拉取 md5 清单。成功 → 返回 文件名→md5 的字典；失败 → null。
        /// </summary>
        private static System.Collections.IEnumerator FetchMd5ListCo(
            string url, Action<Dictionary<string, string>> onDone)
        {
            Dictionary<string, string> map = null;

            using (UnityWebRequest req = UnityWebRequest.Get(url))
            {
                req.timeout = TimeoutSeconds;
                req.downloadHandler = new DownloadHandlerBuffer();

                yield return req.SendWebRequest();

                if (req.result == UnityWebRequest.Result.Success)
                {
                    try
                    {
                        map = ParseMd5List(req.downloadHandler.text);
                        Debug.Log(string.Format("[HotUpdate] 已获取校验清单，共 {0} 条", map.Count));
                    }
                    catch (Exception e)
                    {
                        Debug.LogWarning("[HotUpdate] 解析 md5 清单失败：" + e.Message);
                        map = null;
                    }
                }
                else
                {
                    Debug.LogWarning(string.Format(
                        "[HotUpdate] 获取 md5 清单失败（HTTP {0}）：{1}\n  URL: {2}",
                        req.responseCode, req.error, url));
                }
            }

            if (onDone != null)
            {
                onDone(map);
            }
        }

        /// <summary>
        /// 解析校验清单。容忍以下格式差异：
        ///   · `#` 开头的注释行、空行
        ///   · md5 与文件名之间用**空格或制表符**分隔（兼容 `md5sum` 输出）
        ///   · 文件名前可能有 `*` 前缀（`md5sum -b` 二进制模式）
        ///   · md5 大小写不敏感（统一转小写存储）
        ///   · 行尾 `\r`（Windows 生成的清单）
        /// </summary>
        private static Dictionary<string, string> ParseMd5List(string text)
        {
            var map = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrEmpty(text))
            {
                return map;
            }

            string[] lines = text.Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                string line = lines[i].Trim();
                if (line.Length == 0 || line[0] == '#')
                {
                    continue;
                }

                // 取第一个空白符切分
                int sep = -1;
                for (int c = 0; c < line.Length; c++)
                {
                    if (line[c] == ' ' || line[c] == '\t')
                    {
                        sep = c;
                        break;
                    }
                }
                if (sep <= 0)
                {
                    continue;
                }

                string hash = line.Substring(0, sep).Trim().ToLowerInvariant();
                string file = line.Substring(sep).Trim();

                // 去掉 md5sum 二进制模式的 `*` 前缀
                if (file.StartsWith("*", StringComparison.Ordinal))
                {
                    file = file.Substring(1);
                }
                // 只取文件名（清单里可能写了相对路径）
                file = Path.GetFileName(file);

                if (hash.Length != 32 || file.Length == 0)
                {
                    continue;
                }

                map[file] = hash;
            }
            return map;
        }

        /// <summary>本地文件是否已是最新（md5 一致）。任何异常都返回 false（宁可重下）。</summary>
        private static bool IsLocalUpToDate(string path, string expectedMd5)
        {
            try
            {
                if (File.Exists(path) == false)
                {
                    return false;
                }
                string actual = ComputeFileMd5(path);
                return string.Equals(actual, expectedMd5, StringComparison.OrdinalIgnoreCase);
            }
            catch (Exception)
            {
                return false;
            }
        }

        /// <summary>计算文件 md5（流式读取，避免大文件一次性进内存）。</summary>
        private static string ComputeFileMd5(string path)
        {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(path))
            {
                byte[] hash = md5.ComputeHash(stream);
                var sb = new System.Text.StringBuilder(hash.Length * 2);
                for (int i = 0; i < hash.Length; i++)
                {
                    sb.Append(hash[i].ToString("x2"));
                }
                return sb.ToString();
            }
        }

        private static void CleanupPart(string partPath)
        {
            try
            {
                if (File.Exists(partPath))
                {
                    File.Delete(partPath);
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HotUpdate] 清理临时文件失败 " + partPath + "：" + e.Message);
            }
        }

        private static void Report(Action<int, int> onProgress, int done, int total)
        {
            if (onProgress != null)
            {
                onProgress(done, total);
            }
        }

        private static void Finish(Result result, Action<int, int> onProgress, Action<Result> onDone)
        {
            Report(onProgress, result.Total, result.Total);
            if (onDone != null)
            {
                onDone(result);
            }
        }

        private static string AppendLine(string existing, string line)
        {
            return string.IsNullOrEmpty(existing) ? line : (existing + "\n" + line);
        }

        /// <summary>要同步的完整热更 DLL 名单；不包含 AOT 元数据</summary>
        private static string[] BuildFileList()
        {
            return HotUpdateAssembler.HotUpdateAssemblies;
        }

        /// <summary>
        /// 平台目录名。**必须与 YooAsset 的构建输出平台名一致**，
        /// 否则服务器上的目录名对不上（YooAsset 用 BuildTarget 的名字，如 "Android"）。
        /// </summary>
        private static string GetPlatformFolder()
        {
#if UNITY_ANDROID
            return "Android";
#elif UNITY_IOS
            return "iOS";
#elif UNITY_STANDALONE_WIN
            return "StandaloneWindows64";
#elif UNITY_STANDALONE_OSX
            return "StandaloneOSX";
#else
            return "Unknown";
#endif
        }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;

namespace FTProject.AOT
{
    /// <summary>
    /// 在已加载程序集里查找 <see cref="IHotUpdateEntry"/> 的实现类并实例化。
    ///
    /// ==================================================================
    /// 【它解决的问题】
    ///   AOT 侧**不能 `new` 热更类型**（编译期符号依赖会让 IL2CPP 打包失败），
    ///   所以"接口"本身解决不了"谁来实例化"的问题 —— 这一步必须靠反射。
    ///
    ///   于是本类是**唯一**保留反射的地方，且职责收窄到一件事：
    ///   「找到实现者，并把它变成 IHotUpdateEntry」。
    ///   一旦拿到接口引用，后续所有调用都是**强类型**的（`entry.Start()`），
    ///   不再有字符串、不再有 MethodInfo。
    ///
    /// 【为什么用 `typeof(IHotUpdateEntry)` 而不是字符串】
    ///   `typeof` 走的是编译期类型系统 → 接口改名/挪程序集会**编译报错**（好）。
    ///   而旧方案用 `"FTProject.HotUpdateEntry"` 字符串 → 改名只在运行时炸（坏）。
    ///   这就是本次改造想要的核心收益。
    ///
    /// 【为什么不用 `Assembly.GetTypes()` 全扫】
    ///   `GetTypes()` 会把每个程序集的所有类型都反射构造一遍（含泛型构造、依赖解析），
    ///   在 IL2CPP 下开销明显，且某些程序集（如 Unity 内置）会抛 ReflectionTypeLoadException。
    ///   所以这里用 `GetType(name, false)` 只探**已知候选名**（快、稳）。
    ///   ⚠️ 候选名是**唯一**剩下的字符串契约（见 EntryTypeNames），
    ///      改热更侧类名必须同步这里。但它比旧方案健壮：
    ///      名字写错时会走 `CreateEntry` 的兜底扫描并给出明确错误。
    ///
    /// 【编辑器特例】
    ///   编辑器下热更 dll 已在 AppDomain，`GetType` 天然能找到。
    ///   真机上热更 dll 由 `HotUpdateAssembler` 先 `Assembly.Load` 进来，同样能找到。
    ///   两条路径对本类透明 —— 无需分支。
    /// ==================================================================
    /// </summary>
    public static class HotUpdateEntryLocator
    {
        /// <summary>
        /// 热更侧入口实现类的**候选全名**（按优先级）。
        ///
        /// ⚠️ 唯一剩下的字符串契约：热更侧改了类名，这里要同步。
        ///    加到这里的是"**预期**的名字"；名字不对时兜底扫描仍可能找到，
        ///    但会打 Warning 提示你同步（见 TryFallbackScan）。
        /// </summary>
        private static readonly string[] EntryTypeNames =
        {
            "FTProject.HotUpdateEntry",
        };

        /// <summary>
        /// 查找并实例化热更入口。失败时返回 null 并给出可读原因。
        /// </summary>
        /// <param name="error">失败原因（成功时为 null）</param>
        public static IHotUpdateEntry CreateEntry(out string error)
        {
            error = null;

            // ① 快路径：按候选全名精确找（常规情况走这里，零全扫开销）
            for (int i = 0; i < EntryTypeNames.Length; i++)
            {
                Type t = FindTypeByFullName(EntryTypeNames[i]);
                if (t == null)
                {
                    continue;
                }

                if (!TryInstantiate(t, out IHotUpdateEntry entry, out string reason))
                {
                    error = "找到入口类型「" + t.FullName + "」但不能实例化：" + reason;
                    return null;
                }
                return entry;
            }

            // ② 兜底：按接口扫描（候选名全部失效时用；会打 Warning）
            return TryFallbackScan(out error);
        }

        /// <summary>在所有已加载程序集中按全名查类型（不抛异常）。</summary>
        private static Type FindTypeByFullName(string fullName)
        {
            Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < assemblies.Length; i++)
            {
                Type found;
                try
                {
                    found = assemblies[i].GetType(fullName, false);
                }
                catch (Exception)
                {
                    continue; // 个别动态程序集取类型会抛，跳过
                }

                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        /// <summary>
        /// 兜底扫描：遍历所有程序集找 `IHotUpdateEntry` 的实现类。
        /// 只在候选名失效时走，成功后打 Warning 提醒同步候选名。
        /// </summary>
        private static IHotUpdateEntry TryFallbackScan(out string error)
        {
            error = null;

            Type iface = typeof(IHotUpdateEntry);
            var candidates = new List<Type>();

            Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < assemblies.Length; i++)
            {
                Type[] types;
                try
                {
                    types = assemblies[i].GetTypes();
                }
                catch (ReflectionTypeLoadException e)
                {
                    // 部分类型加载失败也要拿能拿到的（Unity 内置程序集常这样）
                    types = e.Types;
                }
                catch (Exception)
                {
                    continue;
                }

                if (types == null)
                {
                    continue;
                }

                for (int j = 0; j < types.Length; j++)
                {
                    Type t = types[j];
                    if (t == null || t.IsAbstract || t.IsInterface)
                    {
                        continue;
                    }
                    if (iface.IsAssignableFrom(t))
                    {
                        candidates.Add(t);
                    }
                }
            }

            if (candidates.Count == 0)
            {
                error = "在所有已加载程序集中找不到任何 IHotUpdateEntry 的实现类。\n"
                    + "  请确认：① 热更 dll（FTProject.Runtime.dll）已成功加载；\n"
                    + "          ② 热更侧存在 `: IHotUpdateEntry` 的实现类（当前候选名："
                    + string.Join(" / ", EntryTypeNames) + "）。";
                return null;
            }

            if (candidates.Count > 1)
            {
                error = "找到多个 IHotUpdateEntry 实现类，无法确定用哪个："
                    + string.Join("、", candidates.ConvertAll(c => c.FullName).ToArray())
                    + "\n  请只保留一个实现类。";
                return null;
            }

            Type target = candidates[0];
            UnityEngine.Debug.LogWarning(
                "[HotUpdate] 候选名未命中，兜底扫描找到 IHotUpdateEntry 实现类：「"
                + target.FullName + "」。\n"
                + "  ⚠️ 请把它同步进 HotUpdateEntryLocator.EntryTypeNames，以走快路径、"
                + "并避免每次启动都全扫。");

            if (!TryInstantiate(target, out IHotUpdateEntry entry, out string reason))
            {
                error = "兜底找到入口类型「" + target.FullName + "」但不能实例化：" + reason;
                return null;
            }
            return entry;
        }

        /// <summary>实例化实现类（要求无参可构造）。</summary>
        private static bool TryInstantiate(Type t, out IHotUpdateEntry entry, out string error)
        {
            entry = null;
            error = null;

            try
            {
                object instance = Activator.CreateInstance(t);
                entry = instance as IHotUpdateEntry;
                if (entry == null)
                {
                    // 理论上不会发生（t 已由 IsAssignableFrom 校验过）
                    error = "实例化成功但类型转换失败（内部错误）";
                    return false;
                }
                return true;
            }
            catch (MissingMethodException)
            {
                error = "该类型没有 public 无参构造函数。"
                    + "IHotUpdateEntry 的实现类必须能被无参构造。";
                return false;
            }
            catch (Exception e)
            {
                error = e.ToString();
                return false;
            }
        }
    }
}

using TMPro;
using FTProject.AOT;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    public class HotUpdateView : MonoBehaviour
    {
        public const string LogicalName = "HotUpdateView";

        public const float FillMaxWidth = 900f;

        private const float SmoothSec = 0.25f;
        private const float IndeterminateCyclesPerSec = 0.8f;

        private static readonly Color Cyan = new Color(0.208f, 0.878f, 1f, 1f);              // #35E0FF
        private static readonly Color TextPrimary = new Color(0.910f, 0.941f, 0.980f, 1f);   // #E8F0FA
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f); // #9FB3C8
        private static readonly Color TextTertiary = new Color(0.369f, 0.451f, 0.588f, 1f);  // #5E7396
        private static readonly Color Danger = new Color(1f, 0.302f, 0.369f, 1f);            // #FF4D5E

        private TMP_Text _title;
        private TMP_Text _phaseText;
        private TMP_Text _percentText;
        private TMP_Text _sizeText;
        private TMP_Text _speedText;
        private TMP_Text _detailText;
        private TMP_Text _failText;
        private RectTransform _fill;
        private RectTransform _glow;
        private Button _pauseBtn;
        private Button _resumeBtn;
        private Button _retryBtn;
        private GameObject _buttonGroup;

        private float _target;
        private float _shown;
        private float _velocity;
        private bool _indeterminate;
        private float _indeterminateT;

        private long _lastBytes = -1;
        private float _lastBytesTime;
        private float _speedBytesPerSec;
        private long _totalBytes;
        private long _currentBytes;
        private int _currentCount;
        private int _totalCount;
        private bool _englishFallback;

        private void Awake()
        {
            _title = FindText("Panel/HotTitle");
            _phaseText = FindText("Panel/PhaseText");
            _percentText = FindText("Panel/PercentText");
            _sizeText = FindText("Panel/SizeText");
            _speedText = FindText("Panel/SpeedText");
            _detailText = FindText("Panel/DetailText");
            _failText = FindText("Panel/FailText");
            _fill = FindRect("Panel/ProgressBar/Fill");
            _glow = FindRect("Panel/ProgressBar/Glow");
            _pauseBtn = FindButton("Panel/BtnGroup/PauseBtn");
            _resumeBtn = FindButton("Panel/BtnGroup/ResumeBtn");
            _retryBtn = FindButton("Panel/BtnGroup/RetryBtn");
            var buttonGroup = transform.Find("Panel/BtnGroup");
            _buttonGroup = buttonGroup != null ? buttonGroup.gameObject : null;
            uint[] missingGlyphs;
            _englishFallback = _phaseText == null || _phaseText.font == null
                || !_phaseText.font.HasCharacters(BootLocalization.Get("Preparing"), out missingGlyphs, true, true);

            if (_title != null) _title.color = TextPrimary;
            if (_percentText != null) _percentText.color = Cyan;
            if (_sizeText != null) _sizeText.color = TextSecondary;
            if (_speedText != null) _speedText.color = TextSecondary;
            if (_detailText != null) _detailText.color = TextTertiary;
            if (_failText != null)
            {
                _failText.color = Danger;
                _failText.enableWordWrapping = true;
                _failText.overflowMode = TextOverflowModes.Ellipsis;
                _failText.enableAutoSizing = true;
                _failText.fontSizeMin = 18;
                _failText.fontSizeMax = 26;
                _failText.rectTransform.sizeDelta = new Vector2(1400, 100);
            }

            if (_pauseBtn != null) _pauseBtn.onClick.AddListener(OnClickPause);
            if (_resumeBtn != null) _resumeBtn.onClick.AddListener(OnClickResume);
            if (_retryBtn != null) _retryBtn.onClick.AddListener(OnClickRetry);

            _indeterminate = true;
            ApplyProgress(0f);
            ShowFail(string.Empty);
            SetButtonState(HotButtonState.None);
        }

        private void OnEnable()
        {
            BootUpdateSession.Changed += RenderSession;
            RenderSession();
        }
        private void OnDisable() { BootUpdateSession.Changed -= RenderSession; }
        private void RenderSession()
        {
            _indeterminate = BootUpdateSession.Stage < 0;
            _target = BootUpdateSession.Overall;
            SetPhase(Localize(BootUpdateSession.Paused ? "Paused" : BootUpdateSession.Phase));
            if (_title != null) _title.text = Localize("Title");
            _currentCount = BootUpdateSession.Files; _totalCount = BootUpdateSession.TotalFiles;
            _currentBytes = BootUpdateSession.Bytes; _totalBytes = BootUpdateSession.TotalBytes;
            UpdateSpeed(_currentBytes);
            RefreshTexts();
            bool failed = BootUpdateSession.Phase == "Failed" || BootUpdateSession.Phase == "Restart";
            ShowFail(failed ? BootUpdateSession.Detail : "");
            if (!failed && _detailText != null && !string.IsNullOrEmpty(BootUpdateSession.Detail))
                _detailText.text = BootUpdateSession.Detail;
            SetButtonState(BootUpdateSession.Retry != null ? HotButtonState.Retry
                : BootUpdateSession.Paused && BootUpdateSession.Resume != null ? HotButtonState.Resume
                : BootUpdateSession.Pause != null ? HotButtonState.Pause : HotButtonState.None);
            SetLabel(_pauseBtn, "Pause"); SetLabel(_resumeBtn, "Resume"); SetLabel(_retryBtn, "Retry");
        }
        private string Localize(string key) { return _englishFallback ? BootLocalization.EnglishText(key) : BootLocalization.Get(key); }
        private void SetLabel(Button button, string key)
        {
            if (button != null) { var label = button.GetComponentInChildren<TMP_Text>(true); if (label != null) label.text = Localize(key); }
        }
        private void OnClickPause() { BootUpdateSession.Pause?.Invoke(); RenderSession(); }
        private void OnClickResume() { BootUpdateSession.Resume?.Invoke(); RenderSession(); }
        private void OnClickRetry()
        {
            var retry = BootUpdateSession.Retry;
            BootUpdateSession.Controls();
            retry?.Invoke();
        }

        private enum HotButtonState
        {
            None,
            Pause,
            Resume,
            Retry
        }

        private void SetPhase(string phase)
        {
            if (_phaseText != null)
            {
                _phaseText.text = phase;
                _phaseText.color = TextPrimary;
            }
        }

        private void SetButtonState(HotButtonState state)
        {
            // The prefab starts with the whole group hidden. Enabling only a child
            // leaves Retry/Pause/Resume invisible and prevents recovery on a clean APK.
            if (_buttonGroup != null) _buttonGroup.SetActive(state != HotButtonState.None);
            SetActive(_pauseBtn, state == HotButtonState.Pause);
            SetActive(_resumeBtn, state == HotButtonState.Resume);
            SetActive(_retryBtn, state == HotButtonState.Retry);
        }

        private static void SetActive(Button b, bool active)
        {
            if (b != null && b.gameObject.activeSelf != active)
            {
                b.gameObject.SetActive(active);
            }
        }

        private void ShowFail(string reason)
        {
            if (_failText == null)
            {
                return;
            }
            bool show = !string.IsNullOrEmpty(reason);
            _failText.text = show ? reason : string.Empty;
            if (_failText.gameObject.activeSelf != show)
            {
                _failText.gameObject.SetActive(show);
            }
        }

        private void UpdateSpeed(long bytes)
        {
            float now = Time.realtimeSinceStartup;
            if (_lastBytes < 0)
            {
                _lastBytes = bytes;
                _lastBytesTime = now;
                return;
            }
            float dt = now - _lastBytesTime;
            if (dt < 0.2f)
            {
                return;   // 采样太密会让速率数字剧烈抖动，看不出真实速度
            }
            _speedBytesPerSec = Mathf.Max(0, (bytes - _lastBytes) / dt);
            _lastBytes = bytes;
            _lastBytesTime = now;
        }

        private void RefreshTexts()
        {
            if (_sizeText != null)
            {
                _sizeText.text = string.Format("{0:F1} MB / {1:F1} MB", _currentBytes / 1048576f, _totalBytes / 1048576f);
            }
            if (_speedText != null)
            {
                float mbs = _speedBytesPerSec / 1048576f;
                string eta = "--:--";
                if (_speedBytesPerSec > 1024f && _totalBytes > _currentBytes)
                {
                    int left = Mathf.Max(0, Mathf.RoundToInt((_totalBytes - _currentBytes) / _speedBytesPerSec));
                    eta = string.Format("{0:00}:{1:00}", left / 60, left % 60);
                }
                _speedText.text = string.Format("{0:F1} MB/s  ETA {1}", mbs, eta);
            }
            if (_detailText != null)
            {
                _detailText.text = string.Format("{0}/{1}", _currentCount, _totalCount);
            }
        }

        private void Update()
        {
            float dt = Time.unscaledDeltaTime;

            if (_indeterminate)
            {
                _indeterminateT += dt * IndeterminateCyclesPerSec;
                ApplyProgress(_target);
                if (_percentText != null)
                {
                    _percentText.text = Localize("Overall") + " " + Mathf.RoundToInt(_target * 100f) + "%  | " + Localize("Stage") + " ...";
                }
                return;
            }

            _shown = Mathf.SmoothDamp(_shown, _target, ref _velocity, SmoothSec, Mathf.Infinity, dt);
            if (Mathf.Abs(_shown - _target) < 0.0005f)
            {
                _shown = _target;
                _velocity = 0f;
            }
            ApplyProgress(_shown);
        }

        private void ApplyProgress(float t)
        {
            float clamped = Mathf.Clamp01(t);
            SetFillWidth(_fill, clamped);
            SetFillWidth(_glow, clamped);
            if (_percentText != null && !_indeterminate)
            {
                _percentText.text = Localize("Overall") + " " + Mathf.RoundToInt(clamped * 100f) + "% | " + Localize("Stage") + " " + Mathf.RoundToInt(Mathf.Clamp01(BootUpdateSession.Stage) * 100f) + "%";
            }
        }

        private static void SetFillWidth(RectTransform rt, float t)
        {
            if (rt == null)
            {
                return;
            }
            Vector2 size = rt.sizeDelta;
            size.x = FillMaxWidth * t;
            rt.sizeDelta = size;
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[HotUpdate] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private RectTransform FindRect(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[HotUpdate] 缺少矩形节点「" + path + "」");
                return null;
            }
            return tr as RectTransform;
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[HotUpdate] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

namespace FTProject.AOT
{
    using System;

    /// <summary>
    /// 热更启动入口契约（**定义在 AOT 侧，由热更侧实现**）。
    ///
    /// ==================================================================
    /// 【为什么把它放在 AOT 程序集，而不是热更侧】
    ///   HybridCLR 的铁律是「AOT 主包不得引用热更类型」，但**反向引用是允许的**
    ///   （热更集可以引用 AOT 集）。所以把接口定义在 AOT，让热更侧来 `: IHotUpdateEntry`
    ///   实现 —— 这样：
    ///
    ///     ✅ 编译器保证契约（改方法签名两边同时报错），不再是"字符串约定"
    ///     ✅ 非空性是编译期的（实现类必须实现接口全部成员，漏一个直接编译失败）
    ///     ✅ 接口方法可以带**强类型参数**（bool / 枚举 / 自定义结构），
    ///        而不像以前的反射调用只能无参
    ///     ✅ IDE 能跳转、能重命名、能找到所有实现
    ///
    ///   对比旧方案（`BootLoader` 里写 `EntryTypeName = "FTProject.HotUpdateEntry"` +
    ///   `EntryMethodName = "Start"` 反射调用）：改类名/方法名**不会**编译报错，
    ///   只在运行时抛"找不到入口类型"，排查成本高。这是本次改造的核心动机。
    ///
    /// 【仍然需要一次"查找实现类"】
    ///   接口解决了"契约强类型化"，但 AOT 侧**仍然不能 `new` 热更类型**
    ///   （那会形成编译期符号依赖，IL2CPP 打包直接挂）。
    ///   所以激活流程保留一步"在已加载程序集里找实现类" —— 见
    ///   `HotUpdateEntryLocator.CreateEntry()`。
    ///   区别在于：这一步失败时**错误信息是确定的**（"没有任何类型实现 IHotUpdateEntry"），
    ///   而不是以前那种"名字写错了但看起来像别的问题"。
    ///
    /// 【接口该定义什么 / 不该定义什么】
    ///   ✅ 该定义：与场景无关的启动动作（初始化管理器、准备配置等），
    ///     以及必要时的启动结果/进度反馈。
    ///   ❌ 不该定义：访问 main 场景对象的动作 —— 调用它时 main 还没加载。
    ///     那些应该放在 main 场景的 GameSceneLauncher / Launcher 里。
    ///
    /// 【命名由来】
    ///   类名沿用 `IHotUpdateEntry`（"热更入口"）而非更长的名字，是因为
    ///   它描述的就是"热更代码的启动入口"这一件事，与本工程既有叫法一致。
    /// ==================================================================
    /// </summary>
    public interface IHotUpdateEntry
    {
        /// <summary>
        /// 热更程序集加载完成后由 AOT 侧调用（**在 main 场景加载之前**）。
        ///
        /// 【实现要求】
        ///   - 不能访问任何场景对象（此时 main 还没加载，Boot 也即将卸载）
        ///   - 不能假设 Unity 的 MonoBehaviour 生命周期（本方法不在任何 MonoBehaviour 上）
        ///   - 耗时操作要短：它是在启动链的关键路径上同步执行的
        ///
        /// 【关于重复调用】由实现方自行决定是否需要防重入（推荐用静态 bool 标记）。
        ///   约定：重复调用**不应抛异常**，最多打一条 Warning 后返回。
        /// </summary>
        void Start();

        /// <summary>
        /// 加载 main 场景（**异步**；HybridCLR 真机上场景必须由热更侧从 AssetBundle 加载）。
        ///
        /// 【为什么是热更侧的职责】
        ///   真机上"挂了热更脚本的场景"打进 Build Settings 会在打包时被烘焙成空壳
        ///   （热更程序集被 IFilterBuildAssemblies 剔除，组件序列化成 32 字节 stub），
        ///   运行时表现为 missing script + serialization layout 错误。
        ///   HybridCLR 官方工作流：这类场景必须打 AB，且**在热更 dll 加载后**由
        ///   AB 加载（YooAsset SceneHandle / AssetBundle.LoadFromFile 均可）。
        ///   资源系统的模式选择（联机/离线）也只在热更侧可知（依赖 ResServerConfig），
        ///   所以场景加载放在这里，AOT 侧只等结果。
        ///
        /// 【回调约定】
        ///   - onResult(ok, err)：ok=false 时 err 为可读错误信息
        ///   - 成功时场景已以 Single 模式激活（Boot 场景随之卸载，Boot 侧协程自然终止）
        ///   - 回调在主线程；失败时**不会**激活场景，由 AOT 侧决定展示什么
        /// </summary>
        void EnterMainScene(Action<bool, string> onResult);
    }
}

namespace FTProject
{
    /// <summary>
    /// 支持的语言。
    ///
    /// 【为什么 English = 0】它是**硬兜底**：多语言表缺 key 或某语言文本为空时，
    /// 一律回退到英文（见 LanguageManager.GetText 的回退链：当前语言 → 英文 → null）。
    /// 让英文占 0 使 `(Language)0` 天然就是安全默认值。
    /// </summary>
    public enum Language
    {
        English = 0,
        ChineseSimplified = 1,
        ChineseTraditional = 2,
    }

    /// <summary>语言枚举与稳定语言码之间的转换。</summary>
    public static class LanguageUtil
    {
        /// <summary>
        /// 语言码（BCP-47 风格）。
        /// 【为什么存档存码而不是枚举 int】将来在枚举中间插入新语言会让老存档的 int
        /// 含义漂移（例如以后加 Japanese=1，老存档里存的 1 本该是简中却变成日文）。
        /// 存字符串码则永不漂移。
        /// </summary>
        public static string ToCode(this Language lang)
        {
            switch (lang)
            {
                case Language.ChineseSimplified:  return "zh-Hans";
                case Language.ChineseTraditional: return "zh-Hant";
                default:                          return "en";
            }
        }

        /// <summary>语言码 → 枚举。无法识别时回退英文（不报错）。</summary>
        public static Language FromCode(string code)
        {
            if (code == "zh-Hans") return Language.ChineseSimplified;
            if (code == "zh-Hant") return Language.ChineseTraditional;
            return Language.English;
        }

        /// <summary>语言在 UI 上的自显名（设置界面用；刻意不查表，避免"用语言 A 显示语言 B 的名字"时缺 key）。</summary>
        public static string DisplayName(this Language lang)
        {
            switch (lang)
            {
                case Language.ChineseSimplified:  return "简体中文";
                case Language.ChineseTraditional: return "繁體中文";
                default:                          return "English";
            }
        }
    }
}

using System;
using System.Collections.Generic;
using TMPro;
