        private static void SkippedWaves()
        {
            Set(GameFlowManager.Instance, "_roundCursor", GameFlowManager.Instance.RatingProfile.expectedWaveCount);
            StartWave();
            var info = PopupInfo();
            Check(GameFlowManager.Instance.State == GameFlowState.GameOver && !info.ratingResult.valid && !info.progressSaved, "Jumping final cursor cannot fabricate formal evidence");
            NoClear("Skipped waves");
        }

        private static LevelClearView Popup()
        {
            var view = UnityEngine.Object.FindObjectOfType<LevelClearView>(); Check(view != null, "Actual clear popup exists"); return view;
        }
        private static LevelClearInfo PopupInfo() { var info = (LevelClearInfo)Field(Popup(), "_info"); Check(info != null, "Popup has result data"); return info; }

        private static void Migration()
        {
            var save = SaveManager.Instance;
            Check(save.IsUnlocked(1) && !save.IsUnlocked(2), "Player unlock baseline executes despite editor all-unlock default");
            save.Data.levels.Add(new LevelProgress { levelId = 1, stars = 3, clearCount = 7, bestTimeMs = 123456, bestHpLeft = 20 }); save.Save();
            Check(save.IsUnlocked(2), "Historical clear unlocks next level before migration");
            Check(save.GetStars(1) == 0 && save.TotalStars == 0 && save.GetLegacyStars(1) == 3, "Legacy three-star record is archived, not multiplied into current five-star total");
            var p = save.Data.Find(1);
            Check(p.clearCount == 7 && p.legacy.Count == 1 && p.legacy[0].bestTimeMs == 123456 && save.IsUnlocked(2), "Migration preserves historical count/time/unlock");
            string backup; Check(Storage.TryGetValue("rating-backup/1/legacy-v1-three-stars", out backup) && backup.Contains("123456"), "Durable original legacy backup");
            save.EnsureRatingVersion(1); Check(save.Data.Find(1).legacy.Count == 1, "Repeated migration is idempotent");
            var metrics = TerminalFixture();
            Check(save.RecordClear(1, LevelRatingEvaluator.Evaluate(GameFlowManager.Instance.RatingProfile, metrics)), "Current-version fixture can settle after migration");
            Check(save.TotalStars == 5 && save.Data.Find(1).clearCount == 8 && save.GetLegacyStars(1) == 3, "Current total excludes archived stars");
            p = save.Data.Find(1); p.ratingVersionKey += "-obsolete"; save.Save();
            Check(save.GetStars(1) == 0 && save.TotalStars == 0 && save.IsUnlocked(2) && save.Data.Find(1).legacy.Count == 2, "New rating identity archives current stars while retaining unlock");
        }

        private static LevelRunMetrics TerminalFixture()
        {
            var flow = GameFlowManager.Instance; var profile = flow.RatingProfile; var m = flow.RunMetrics;
            m.runId = "safety-fixture-" + Guid.NewGuid().ToString("N");
            m.completedWaveCount = profile.expectedWaveCount; m.successfulSpawned = profile.expectedEnemyCount; m.killed = profile.expectedEnemyCount;
            m.leaked = m.bossLeaked = m.criticalLeaked = 0; m.victory = true; m.debugOverride = false; m.statisticsValid = m.timingValid = true;
            m.hp = m.maxHp = PlayerDataManager.Instance.MaxHp; m.combatElapsedSeconds = profile.parCombatTimeMs / 1000d - .0625d;
            m.levelElapsedSeconds = m.combatElapsedSeconds + 95d; m.waves.Clear();
            for (int i = 0; i < flow.Level.RoundIds.Count; i++)
            {
                var round = Configs.GetRound(flow.Level.RoundIds[i]); int expected = 0;
                foreach (int group in round.WaveIds) expected += Configs.GetWaveGroup(group).EnemyCount;
                m.waves.Add(new WaveRunMetrics { ordinal = i + 1, expected = expected, successfulSpawned = expected, killed = expected,
                    hp = m.hp, gold = 137, clearGold = round.RewardGold, combatStartSeconds = m.combatElapsedSeconds * i / profile.expectedWaveCount,
                    combatEndSeconds = m.combatElapsedSeconds * (i + 1) / profile.expectedWaveCount, levelEndSeconds = m.levelElapsedSeconds * (i + 1) / profile.expectedWaveCount });
            }
            Check(LevelRatingEvaluator.Evaluate(profile, m).valid, "Constructed safety fixture matches current actual plan counts/version");
            return m;
        }

        private static void ExecuteDatabase(object database, string sql)
        {
            database.GetType().GetMethod("Execute").Invoke(database, new object[] { sql, new object[0] });
        }

        private static void PendingSave(bool json)
        {
            var save = SaveManager.Instance; var flow = GameFlowManager.Instance;
            ISaveStorage original = Storage, backend = original; SaveData originalData = save.Data;
            string directory = null; object database = null; string blockedPath = null; bool blocked = false;
            if (json)
            {
                directory = Path.Combine(Path.GetDirectoryName(original.Location), "json-flow"); Directory.CreateDirectory(directory);
                Type type = typeof(SaveManager).Assembly.GetType("FTProject.JsonSaveStorage", true);
                object crypto = Field(original, "_crypto");
                backend = (ISaveStorage)Activator.CreateInstance(type, BindingFlags.Instance | BindingFlags.NonPublic, null, new object[] { crypto, directory }, null);
                backend.Initialize(); Set(save, "_storage", backend); Set(save, "_data", new SaveData());
            }
            try
            {
                var profile = flow.RatingProfile;
                save.Data.levels.Add(new LevelProgress { levelId = 1, stars = 4, clearCount = 2, ratingVersionKey = profile.versionKey }); save.Save();
                var fixture = TerminalFixture(); Set(flow, "_run", fixture); Set(flow, "_roundCursor", profile.expectedWaveCount);
                PlayerDataManager.Instance.RestoreState(1, 137, fixture.hp, fixture.maxHp, fixture.killed, 0);
                GameClock.RestoreTimers(fixture.combatElapsedSeconds, fixture.levelElapsedSeconds, true);
                flow.SaveSnapshotNow(); Check(save.HasSnapshot && backend.LoadSnapshot().valid, "Durable complete terminal checkpoint before write fault");
                string before = JsonUtility.ToJson(save.Data.Find(1)), checkpoint = JsonUtility.ToJson(save.Snapshot);
                if (json) { blockedPath = backend.Location + ".tmp"; Directory.CreateDirectory(blockedPath); }
                else { database = Field(backend, "_db"); ExecuteDatabase(database, "PRAGMA query_only=ON"); }
                blocked = true;
                Call(flow, "CompleteVictory");
                var info = PopupInfo();
                Check(info.savePending && !info.progressSaved && !info.newRecord && info.ratingResult.valid, "Real CompleteVictory -> Win -> popup enters pending state");
                Check(info.ratingResult.metrics.runId == fixture.runId, "Pending result freezes the original runId");
                Check(JsonUtility.ToJson(save.Data.Find(1)) == before && JsonUtility.ToJson(save.Snapshot) == checkpoint && backend.LoadSnapshot().valid, "Failed commit publishes neither progress nor checkpoint removal");
                Check(JsonUtility.ToJson(backend.LoadLevels()[0]) == before, "Failed backend remains at prior best/count");
                var view = Popup(); var next = (Button)Field(view, "_nextBtn"); Check(next != null && (!next.gameObject.activeInHierarchy || !next.interactable), "Actual Next button unavailable while pending");
                int nextEvents = 0; Action<int> observer = ignored => nextEvents++;
                EventDispatcher.AddEventListener<int>(EventName.SelectLevelRequestEvent, observer);
                try { Call(view, "OnClickNext"); Check(nextEvents == 0, "Programmatic Next handler also blocks unsaved result"); }
                finally { EventDispatcher.RemoveEventListener<int>(EventName.SelectLevelRequestEvent, observer); }
                Call(view, "OnClickRetry"); Check(PopupInfo().savePending && save.Data.Find(1).clearCount == 2, "Retry during fault remains pending without double count");
                if (json) Directory.Delete(blockedPath); else ExecuteDatabase(database, "PRAGMA query_only=OFF"); blocked = false;
                Call(Popup(), "OnClickRetry"); info = PopupInfo();
                Check(info.progressSaved && !info.savePending && info.newRecord && info.ratingResult.metrics.runId == fixture.runId, "Actual retry button saves same runId and refreshes popup");
                Check(save.Data.Find(1).clearCount == 3 && save.GetStars(1) == 5 && !save.HasSnapshot && !backend.LoadSnapshot().valid, "Exactly one clear commits with atomic checkpoint invalidation");
                Check(((Button)Field(Popup(), "_nextBtn")).interactable, "Next becomes available after durable success");
                Check(save.RecordClear(1, LevelRatingEvaluator.Evaluate(profile, fixture)), "Duplicate same-run result is accepted idempotently");
                Call(flow, "CompleteVictory"); PlayerDataManager.Instance.Win();
                Check(save.Data.Find(1).clearCount == 3 && backend.LoadLevels()[0].committedRunIds.Count == 1, "Duplicate terminal callbacks cannot count again");
                if (json)
                {
                    backend.Dispose(); backend.Initialize();
                    Check(backend.LoadLevels()[0].clearCount == 3 && !backend.LoadSnapshot().valid, "JSON reopen observes exactly one saved result");
                }
                else
                {
                    using (save.SetTestStorageContext(GetTestContext()))
                        Check(save.Data.Find(1).clearCount == 3 && !save.HasSnapshot && save.IsRunCommitted(1, fixture.runId), "SQLite close/reopen observes durable one-run result");
                    backend = Storage; database = null;
                }
            }
            finally
            {
                if (blocked) { if (json) Directory.Delete(blockedPath); else ExecuteDatabase(database, "PRAGMA query_only=OFF"); }
                if (json) { backend.Dispose(); Set(save, "_storage", original); Set(save, "_data", originalData); }
            }
        }

        private static string GetTestContext()
        {
            Type factory = typeof(SaveManager).Assembly.GetType("FTProject.SaveStorageFactory", true);
            return (string)factory.GetProperty("ActiveTestContextId", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic).GetValue(null, null);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Linq;
using SimpleJSON;
using TMPro;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject.EditorTools
{
    /// <summary>Renders the shipped prefabs with real view bindings and fonts in an isolated test session.</summary>
    public static class BalanceUiVisualVerifier
    {
        private const int CaptureLayer = 31;
        private static readonly MethodInfo FillDetail = typeof(LevelDetailView).GetMethod("Fill", BindingFlags.Instance | BindingFlags.NonPublic);

        public static string CaptureAll(string outputDirectory)
        {
            if (!EditorApplication.isPlaying || !SaveManager.IsTestStorage || !Configs.IsLoaded || !LanguageManager.IsReady)
                throw new InvalidOperationException("UI capture requires a booted PlayMode scene with isolated balance-test storage.");
            outputDirectory = Path.GetFullPath(outputDirectory);
            Directory.CreateDirectory(outputDirectory);
            var results = new JSONArray();
            Language previousLanguage = LanguageManager.Current;
            GameObject stage = null;
            RenderTexture previousTarget = RenderTexture.active;
            try
            {
                stage = new GameObject("Balance UI capture (temporary)");
                stage.hideFlags = HideFlags.HideAndDontSave;
                var cameraObject = new GameObject("Capture camera"); cameraObject.transform.SetParent(stage.transform, false);
                Camera camera = cameraObject.AddComponent<Camera>(); camera.enabled = false;
                camera.orthographic = true; camera.clearFlags = CameraClearFlags.SolidColor;
                camera.backgroundColor = new Color(.035f, .06f, .10f); camera.cullingMask = 1 << CaptureLayer;
                camera.nearClipPlane = .1f; camera.farClipPlane = 2000f;
                camera.transform.localPosition = new Vector3(0, 0, -1000);
                foreach (var size in new[] { new Vector2Int(1920, 1080), new Vector2Int(1024, 768) })
                {
                    // Match the main scene CanvasScaler: 1920x1080 reference, width/height match=.5.
                    float scale = Mathf.Sqrt(size.x / 1920f * (size.y / 1080f));
                    Vector2 logicalSize = new Vector2(size.x / scale, size.y / scale);
                    camera.orthographicSize = logicalSize.y * .5f;
                    camera.aspect = (float)size.x / size.y;
                    var canvasObject = new GameObject("Actual prefab canvas", typeof(RectTransform), typeof(Canvas));
                    canvasObject.transform.SetParent(stage.transform, false); canvasObject.layer = CaptureLayer;
                    RectTransform canvasRect = (RectTransform)canvasObject.transform; canvasRect.sizeDelta = logicalSize;
                    Canvas canvas = canvasObject.GetComponent<Canvas>(); canvas.renderMode = RenderMode.WorldSpace;
                    canvas.worldCamera = camera; canvas.referencePixelsPerUnit = 100;
                    var target = new RenderTexture(size.x, size.y, 24, RenderTextureFormat.ARGB32);
                    target.Create(); camera.targetTexture = target;
                    try
                    {
                        foreach (Language language in new[] { Language.English, Language.ChineseSimplified, Language.ChineseTraditional })
                        {
                            LanguageManager.SetLanguage(language);
                            foreach (string scenario in new[] { "select-first", "select-last", "detail-L" + Configs.LevelTable.DataList.Max(l => l.Id), "clear-five", "clear-low", "clear-save-pending" })
                            {
                                bool detail = scenario.StartsWith("detail", StringComparison.Ordinal);
                                bool select = scenario.StartsWith("select", StringComparison.Ordinal);
                                string prefabName = select ? "SelectView" : detail ? "LevelDetailView" : "LevelClearView";
                                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/UI/" + prefabName + ".prefab");
                                if (prefab == null) throw new FileNotFoundException("Actual prefab missing: " + prefabName);
                                GameObject instance = UnityEngine.Object.Instantiate(prefab, canvasRect, false);
                                try
                                {
                                    SetLayer(instance.transform);
                                    var root = instance.GetComponent<RectTransform>();
                                    root.anchorMin = Vector2.zero; root.anchorMax = Vector2.one;
                                    root.offsetMin = Vector2.zero; root.offsetMax = Vector2.zero;
                                    if (detail) FillDetail.Invoke(instance.GetComponent<LevelDetailView>(), new object[] { Configs.LevelTable.DataList.Max(l => l.Id) });
                                    else if (!select) instance.GetComponent<LevelClearView>().Show(CreateClearFixture(scenario));
                                    if (select)
                                    {
                                        Canvas.ForceUpdateCanvases();
                                        var view = instance.GetComponent<SelectView>();
                                        typeof(SelectView).GetMethod("LateUpdate", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(view, null);
                                        typeof(SelectView).GetMethod("CenterOnIndexInstant", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(view,
                                            new object[] { scenario == "select-last" ? Configs.LevelTable.DataList.Count - 1 : 0 });
                                        typeof(SelectView).GetMethod("LateUpdate", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(view, null);
                                    }
                                    Canvas.ForceUpdateCanvases();
                                    foreach (var text in instance.GetComponentsInChildren<TMP_Text>(false)) text.ForceMeshUpdate(true, true);
                                    Canvas.ForceUpdateCanvases();
                                    string file = scenario + "-" + language.ToCode() + "-" + size.x + "x" + size.y + ".png";
                                    camera.Render(); RenderTexture.active = target;
                                    var image = new Texture2D(size.x, size.y, TextureFormat.RGB24, false);
                                    try
                                    {
                                        image.ReadPixels(new Rect(0, 0, size.x, size.y), 0, 0); image.Apply();
                                        File.WriteAllBytes(Path.Combine(outputDirectory, file), image.EncodeToPNG());
                                    }
                                    finally { UnityEngine.Object.DestroyImmediate(image); }
                                    JSONNode entry = Analyze(instance, camera);
                                    entry["scenario"] = scenario; entry["language"] = language.ToCode();
                                    entry["width"] = size.x; entry["height"] = size.y; entry["image"] = file;
                                    entry["prefab"] = AssetDatabase.GetAssetPath(prefab);
                                    if (select) { entry["campaignLevelCount"] = Configs.LevelTable.DataList.Count; entry["maximumStars"] = Configs.LevelTable.DataList.Count * 5; }
                                    results.Add(entry);
                                }
                                finally { UnityEngine.Object.DestroyImmediate(instance); }
                            }
                        }
                    }
                    finally
                    {
                        camera.targetTexture = null; RenderTexture.active = previousTarget;
                        target.Release(); UnityEngine.Object.DestroyImmediate(target);
                        UnityEngine.Object.DestroyImmediate(canvasObject);
                    }
                }
            }
            finally
            {
                RenderTexture.active = previousTarget;
                LanguageManager.SetLanguage(previousLanguage);
                if (stage != null) UnityEngine.Object.DestroyImmediate(stage);
            }
            JSONNode report = new JSONObject(); report["coverage"] = "Actual shipped prefabs and view bindings; synthetic settlement fixtures, not gameplay certification; 1920x1080 and 1024x768 using main CanvasScaler match=.5; safe-area/device input remains separate.";
            report["results"] = results; report["images"] = results.Count;
            File.WriteAllText(Path.Combine(outputDirectory, "ui-visual-results.json"), report.ToString(2), new System.Text.UTF8Encoding(false));
            return report.ToString();
        }

        private static LevelClearInfo CreateClearFixture(string scenario)
        {
            int lastLevel = Configs.LevelTable.DataList.Max(l => l.Id);
            var profile = Configs.GetLevelRating(lastLevel);
            if (profile == null) throw new InvalidOperationException("Final level rating is missing");
            bool low = scenario == "clear-low", pending = scenario == "clear-save-pending";
            var metrics = new LevelRunMetrics
            {
                runId = "ui-fixture-" + scenario, profileId = profile.profileId, profileRevision = profile.profileRevision,
                balanceRevision = profile.balanceRevision, ratingRevision = profile.ratingRevision, planHash = profile.planHash,
                expectedWaveCount = profile.expectedWaveCount, completedWaveCount = profile.expectedWaveCount,
                expectedEnemyCount = profile.expectedEnemyCount, successfulSpawned = profile.expectedEnemyCount,
                leaked = low ? 3 : 0, bossLeaked = low ? 1 : 0, criticalLeaked = low ? 2 : 0,
                killed = profile.expectedEnemyCount - (low ? 3 : 0), hp = low ? 1 : 20, maxHp = 20,
                victory = true, statisticsValid = true, timingValid = true,
                combatElapsedSeconds = profile.parCombatTimeMs / 1000d * (low ? 1.5d : 1d)
            };
            metrics.levelElapsedSeconds = metrics.combatElapsedSeconds + 95d;
            int remaining = profile.expectedEnemyCount;
            for (int i = 0; i < profile.expectedWaveCount; i++)
            {
                int expected = remaining / (profile.expectedWaveCount - i); remaining -= expected;
                int leaks = low && i == 0 ? 3 : 0;
                metrics.waves.Add(new WaveRunMetrics { ordinal = i + 1, expected = expected, successfulSpawned = expected,
                    killed = expected - leaks, leaked = leaks, bossLeaked = low && i == 0 ? 1 : 0,
                    criticalLeaked = low && i == 0 ? 2 : 0 });
            }
            var rating = LevelRatingEvaluator.Evaluate(profile, metrics);
            if (!rating.valid) throw new InvalidOperationException("UI fixture is invalid: " + string.Join(", ", rating.reasons));
            if (pending) rating.reasons = new[] { "Record could not be saved; retry save" };
            return new LevelClearInfo { victory = true, levelId = lastLevel, levelName = Localization.LevelName(lastLevel, "Level " + lastLevel),
                stars = rating.stars, previousBest = low ? 5 : 3, newRecord = !low && !pending,
                hp = metrics.hp, maxHp = metrics.maxHp, killed = metrics.killed, leaked = metrics.leaked,
                ratingResult = rating, progressSaved = !pending, savePending = pending,
                hasNext = false, nextLevelId = 0 };
        }

        private static JSONNode Analyze(GameObject instance, Camera camera)
        {
            JSONNode entry = new JSONObject(); entry["texts"] = new JSONArray();
            int issues = 0;
            foreach (var text in instance.GetComponentsInChildren<TMP_Text>(false))
            {
                var missing = new HashSet<char>();
                if (text.font != null)
                    foreach (char c in text.GetParsedText())
                        if (!char.IsWhiteSpace(c) && !text.font.HasCharacter(c, true, false)) missing.Add(c);
                var corners = new Vector3[4]; text.rectTransform.GetWorldCorners(corners);
                Rect visibleBounds = ViewportBounds(corners, camera);
                bool clipped = false;
                for (Transform parent = text.transform.parent; parent != null; parent = parent.parent)
                {
                    var mask = parent.GetComponent<RectMask2D>();
                    var stencil = parent.GetComponent<Mask>();
                    if ((mask == null || !mask.isActiveAndEnabled) && (stencil == null || !stencil.isActiveAndEnabled)) continue;
                    var rect = parent as RectTransform;
                    if (rect == null) continue;
                    rect.GetWorldCorners(corners);
                    Rect clip = ViewportBounds(corners, camera);
                    visibleBounds = Rect.MinMaxRect(Mathf.Max(visibleBounds.xMin, clip.xMin), Mathf.Max(visibleBounds.yMin, clip.yMin),
                        Mathf.Min(visibleBounds.xMax, clip.xMax), Mathf.Min(visibleBounds.yMax, clip.yMax));
                    clipped = true;
                }
                bool visible = visibleBounds.width > 0 && visibleBounds.height > 0;
                bool outside = visible && (visibleBounds.xMin < -.003f || visibleBounds.xMax > 1.003f || visibleBounds.yMin < -.003f || visibleBounds.yMax > 1.003f);
                JSONNode row = new JSONObject(); row["path"] = AnimationUtility.CalculateTransformPath(text.transform, instance.transform);
                row["text"] = text.text; row["fontSize"] = text.fontSize; row["overflow"] = text.isTextOverflowing;
                row["outsideViewport"] = outside; row["missingGlyphs"] = new string(new List<char>(missing).ToArray());
                row["visibleAfterMasks"] = visible; row["ancestorMaskApplied"] = clipped;
                if (visible && (text.isTextOverflowing || outside || missing.Count > 0)) issues++;
                entry["texts"].Add(row);
            }
            entry["issueCount"] = issues;
            return entry;
        }

        private static Rect ViewportBounds(Vector3[] corners, Camera camera)
        {
            Vector2 min = new Vector2(float.PositiveInfinity, float.PositiveInfinity), max = new Vector2(float.NegativeInfinity, float.NegativeInfinity);
            foreach (var corner in corners)
            {
                Vector3 p = camera.WorldToViewportPoint(corner);
                min = Vector2.Min(min, p); max = Vector2.Max(max, p);
            }
            return Rect.MinMaxRect(min.x, min.y, max.x, max.y);
        }

        private static void SetLayer(Transform root)
        {
            root.gameObject.layer = CaptureLayer;
            foreach (Transform child in root) SetLayer(child);
        }
    }
}

#if UNITY_EDITOR
// Reproducible acceptance driver for the real window handlers and transactional pipeline.
// Every editor/process operation is asynchronous and isolated from official saves.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using SimpleJSON;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    [InitializeOnLoad]
    public static class BalanceWorkbenchAcceptanceDriver
    {
        private const BindingFlags Private = BindingFlags.Instance | BindingFlags.NonPublic;
        private const string EnvSession = "FT.Balance.Acceptance.PreviousKey";
        private static JSONNode state;
        private static string Root { get { return BalanceWorkbenchProcess.ProjectRoot; } }
        private static string StatePath { get { return Path.Combine(Root, "Library/BalanceWorkbench/acceptance-driver-state.json"); } }
        private static string DraftPath { get { return Path.Combine(Root, "Library/BalanceWorkbench/draft.json"); } }
        static BalanceWorkbenchAcceptanceDriver() { EditorApplication.update += Poll; }

        public static string Start()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling ||
                BalanceWorkbenchProcess.Running || BalancePlayModeVerifier.Running)
                throw new InvalidOperationException("Acceptance requires an idle EditMode editor.");
            if (File.Exists(StatePath) && JSON.Parse(File.ReadAllText(StatePath))["active"].AsBool)
                throw new InvalidOperationException("An acceptance driver is already active.");
            string integration = Path.Combine(Root, "Library/BalanceWorkbench/integration-verifier-state.json");
            if (File.Exists(integration) && JSON.Parse(File.ReadAllText(integration))["active"].AsBool)
                throw new InvalidOperationException("Finish the process integration verifier before apply/rollback acceptance.");
            bool open = Resources.FindObjectsOfTypeAll<LevelBalanceWorkbench>().Length > 0;
            bool draftExisted = File.Exists(DraftPath);
            byte[] originalDraft = draftExisted ? File.ReadAllBytes(DraftPath) : null;
            var window = EditorWindow.GetWindow<LevelBalanceWorkbench>();
            Set(window, "_autoPreview", false); Call(window, "PersistDraft");
            if (open) { draftExisted = File.Exists(DraftPath); originalDraft = draftExisted ? File.ReadAllBytes(DraftPath) : null; }
            state = new JSONObject(); state["active"] = true; state["startedUtc"] = DateTime.UtcNow.ToString("O");
            state["events"] = new JSONArray(); state["windowWasOpen"] = open;
            state["draftExisted"] = draftExisted;
            state["originalDraftBase64"] = originalDraft != null ? Convert.ToBase64String(originalDraft) : "";
            state["lastOutputPref"] = EditorPrefs.GetString("FT.Balance.LastOutput", "");
            state["lastBackupPref"] = EditorPrefs.GetString("FT.Balance.LastBackup", "");
            state["formalBefore"] = FormalHashes(); state["officialSavesBefore"] = OfficialSaveHashes();
            state["keyShardBefore"] = KeyShardHash();
            state["output"] = Path.Combine(Root, "Docs/BalanceEvidence/workbench-acceptance-" + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"));
            Directory.CreateDirectory(state["output"].Value);
            state["initialPlanHash"] = JSON.Parse(File.ReadAllText(Path.Combine(Root, "Assets/ConfigJson/tblevelrating.json")))[0]["planHash"].Value;
            // Loading a recipe is the same private handler used by Restore Applied Recipe.
            Call(window, "LoadRecipe", Path.Combine(Root, "Luban/BalanceDesign/balance_design.json"));
            Set(window, "_preset", 3); Recipe(window)["selectedProfileId"] = "D04"; Call(window, "Changed");
            state["beforeWave"] = Recipe(window).ToString();
            Undo.IncrementCurrentGroup();
            Set(window, "_level", 1); Set(window, "_wave", 2); Set(window, "_scope", 0);
            Set(window, "_target", 0); Set(window, "_field", "targetEhp"); Set(window, "_operation", 1); Set(window, "_value", "1.01");
            Call(window, "AddOverride"); Undo.FlushUndoRecordObjects(); Undo.IncrementCurrentGroup();
            state["waveOverrideId"] = Recipe(window)["overrides"][Recipe(window)["overrides"].Count - 1]["id"].Value;
            state["afterWave"] = Recipe(window).ToString();
            Check(state["afterWave"].Value != state["beforeWave"].Value, "same window handler adds L1 W2 EHP x1.01");
            Next("undo"); return StatePath;
        }

        public static string Status() { return File.Exists(StatePath) ? File.ReadAllText(StatePath) : "No acceptance driver state"; }
        private static void Poll()
        {
            if (EditorApplication.isCompiling || EditorApplication.isUpdating) return;
            try
            {
                if (state == null && File.Exists(StatePath)) state = JSON.Parse(File.ReadAllText(StatePath));
                if (state == null || !state["active"].AsBool) return;
                string phase = state["phase"].Value;
                if (EditorApplication.isPlayingOrWillChangePlaymode && phase != "play-wait") return;
                if ((DateTime.UtcNow - DateTime.Parse(state["phaseStartedUtc"].Value, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind)).TotalSeconds > 720)
                    throw new TimeoutException("Acceptance stage timed out: " + phase);
                if (phase == "undo") { Undo.PerformUndo(); Next("undo-check"); }
                else if (phase == "undo-check")
                {
                    Check(Recipe(Window()).ToString() == state["beforeWave"].Value, "Unity Undo restores the exact recipe");
                    Undo.PerformRedo(); Next("redo-check");
                }
                else if (phase == "redo-check")
                {
                    var w = Window(); Check(Recipe(w).ToString() == state["afterWave"].Value, "Unity Redo restores the exact override");
                    Set(w, "_scope", 1); Set(w, "_wave", 3); Set(w, "_lastWave", 4);
                    Set(w, "_value", "1.001"); Call(w, "AddOverride");
                    var range = Recipe(w)["overrides"][Recipe(w)["overrides"].Count - 1];
                    state["rangeOverrideId"] = range["id"].Value;
                    Check(range["scope"].Value == "range" && range["levelId"].AsInt == 1 && range["waveStart"].AsInt == 3 && range["waveEnd"].AsInt == 4,
                        "same window handler records an exact L1 W3-W4 range override");
                    Set(w, "_scope", 2); Set(w, "_level", 2); Call(w, "AddOverride");
                    var level = Recipe(w)["overrides"][Recipe(w)["overrides"].Count - 1];
                    state["levelOverrideId"] = level["id"].Value;
                    Check(level["scope"].Value == "level" && level["levelId"].AsInt == 2 && !level.HasKey("waveOrdinal"),
                        "same window handler records a whole-level override without a wave cursor");
                    Set(w, "_target", 3); Set(w, "_scope", 3); Set(w, "_towerId", 1);
                    Set(w, "_field", "power"); Set(w, "_operation", 0); Set(w, "_value", "7"); Call(w, "AddOverride");
                    SwitchProfile(w, 0); Check(Recipe(w)["selectedProfileId"].Value == "D01", "draft profile switches to D01");
                    SwitchProfile(w, 3); Check(Recipe(w)["selectedProfileId"].Value == "D04", "draft profile switches back to D04");
                    string custom = "ACCEPTANCE_" + DateTime.UtcNow.ToString("yyyyMMddHHmmss");
                    Set(w, "_newPreset", custom); Call(w, "SaveAsPreset"); state["profileId"] = custom;
                    Check(Recipe(w)["selectedProfileId"].Value == custom, "Save As creates and selects a stable custom preset");
                    Check(Recipe(w)["overrides"].Children.Count(n => n["profileId"].Value == custom) >= 4, "custom preset copies wave, range, level and tower overrides");
                    state["customRecipe"] = Recipe(w).ToString(); Call(w, "PersistDraft"); w.Close(); Next("reopen");
                }
                else if (phase == "reopen")
                {
                    var w = Window(); Check(Recipe(w).ToString() == state["customRecipe"].Value, "close and reopen restores the complete local draft");
                    Check(Equal(FormalHashes(), state["formalBefore"]), "edits, Undo, preset switch and draft recovery leave formal files unchanged");
                    StartJob(w, "preview", "preview-wait");
                }
                else if (phase == "preview-wait" && JobDone())
                {
                    string output = state["jobOutput"].Value;
                    var p = JSON.Parse(File.ReadAllText(Path.Combine(output, "preview.json")));
                    Check(p["validation"]["passed"].AsBool && p["changes"].Count > 0, "preview validates and lists concrete differences");
                    var plan = JSON.Parse(File.ReadAllText(Path.Combine(output, "resolved-plan.json")));
                    Check(plan["tables"]["tbtowerinfo"].Children.First(n => n["id"].AsInt == 1)["power"].AsDouble == 7, "resolved shared core contains tower 1 power 7");
                    string suffix = "-" + state["profileId"].Value;
                    var waves = plan["waves"].Children.ToArray();
                    Check(waves.Single(n => n["levelId"].AsInt == 1 && n["waveOrdinal"].AsInt == 2)["overrideSources"]["targetEhp"]["id"].Value == state["waveOverrideId"].Value + suffix,
                        "resolved shared core applies the single-wave override to its exact wave");
                    string rangeId = state["rangeOverrideId"].Value + suffix;
                    Check(waves.Count(n => n["overrideSources"]["targetEhp"]["id"].Value == rangeId) == 2 &&
                          waves.Where(n => n["overrideSources"]["targetEhp"]["id"].Value == rangeId).All(n => n["levelId"].AsInt == 1 && (n["waveOrdinal"].AsInt == 3 || n["waveOrdinal"].AsInt == 4)),
                        "resolved shared core applies the range to exactly L1 W3 and W4");
                    string levelId = state["levelOverrideId"].Value + suffix;
                    Check(waves.Count(n => n["overrideSources"]["targetEhp"]["id"].Value == levelId) == plan["wavesPerLevel"].AsInt &&
                          waves.Where(n => n["overrideSources"]["targetEhp"]["id"].Value == levelId).All(n => n["levelId"].AsInt == 2),
                        "resolved shared core applies the level override to the complete configured inventory of L2 only");
                    state["candidatePlanHash"] = plan["tables"]["tblevelrating"][0]["planHash"].Value;
                    Check(state["candidatePlanHash"].Value != state["initialPlanHash"].Value, "custom candidate changes rating content identity");
                    Check(Equal(FormalHashes(), state["formalBefore"]), "preview does not change Excel, Gen, ConfigJson or authority recipe");
                    Check(Equal(OfficialSaveHashes(), state["officialSavesBefore"]), "preview never opens or writes official saves");
                    StartJob(Window(), "validate", "validate-wait");
                }
                else if (phase == "validate-wait" && JobDone())
                {
                    Check(JSON.Parse(File.ReadAllText(Path.Combine(state["jobOutput"].Value, "validation.json")))["passed"].AsBool, "window fast validation succeeds");
                    StartJob(Window(), "apply", "apply-wait");
                }
                else if (phase == "apply-wait" && JobDone())
                {
                    state["applyOutput"] = state["jobOutput"].Value;
                    state["transaction"] = Path.Combine(state["applyOutput"].Value, "transaction.json");
                    Check(JSON.Parse(File.ReadAllText(state["transaction"].Value))["phase"].Value == "committed", "staged Excel and real Luban apply commit one transaction");
                    Check(JSON.Parse(File.ReadAllText(Path.Combine(state["applyOutput"].Value, "validation.json")))["passed"].AsBool, "formal readback validation succeeds");
                    var formal = JSON.Parse(File.ReadAllText(Path.Combine(Root, "Assets/ConfigJson/tblevelrating.json")))[0];
                    state["appliedPlanHash"] = formal["planHash"].Value; state["runtimeContentHash"] = formal["runtimeContentHash"].Value;
                    Check(state["appliedPlanHash"].Value == state["candidatePlanHash"].Value, "formal export contains previewed planHash");
                    string report = Path.Combine(state["output"].Value, "report"); Directory.CreateDirectory(report);
                    // Same copy/filter behavior as the window's report-export action (no folder dialog).
                    foreach (string file in Directory.GetFiles(state["applyOutput"].Value))
                        if (new[] { ".json", ".csv", ".md", ".log" }.Contains(Path.GetExtension(file))) File.Copy(file, Path.Combine(report, Path.GetFileName(file)), true);
                    Check(File.Exists(Path.Combine(report, "waves.csv")) && File.Exists(Path.Combine(report, "report.md")) && File.Exists(Path.Combine(report, "preview.json")), "JSON, CSV and readable Markdown reports export");
                    string oldKey = Environment.GetEnvironmentVariable("FT_SAVE_KEY");
                    SessionState.SetString(EnvSession, oldKey ?? ""); SessionState.SetBool(EnvSession + ".exists", oldKey != null);
                    Environment.SetEnvironmentVariable("FT_SAVE_KEY", Convert.ToBase64String(new byte[32]));
                    state["testKeyOverrideSet"] = true;
                    string playOutput = Path.Combine(state["output"].Value, "new-formal-game"); state["playOutput"] = playOutput;
                    var request = new JSONObject(); request["output"] = playOutput; request["stepSeconds"] = .0625; request["stepsPerUpdate"] = 60;
                    var run = new JSONObject(); run["profileId"] = state["profileId"].Value; run["levelId"] = 1; run["strategy"] = "mixed"; run["speed"] = 1;
                    request["runs"] = new JSONArray(); request["runs"].Add(run);
                    string path = Path.Combine(Path.GetDirectoryName(StatePath), "acceptance-play-request.json"); File.WriteAllText(path, request.ToString(2));
                    Next("play-wait"); BalancePlayModeVerifier.StartBatch(path);
                }
                else if (phase == "play-wait" && !EditorApplication.isPlayingOrWillChangePlaymode && !BalancePlayModeVerifier.Running)
                {
                    var results = JSON.Parse(File.ReadAllText(Path.Combine(state["playOutput"].Value, "unity-results.json")));
                    Check(results.Count == 1 && results[0]["state"].Value == "finished", "a real new PlayMode game completes after formal apply");
                    Check(results[0]["profile"]["planHash"].Value == state["appliedPlanHash"].Value && results[0]["profile"]["runtimeContentHash"].Value == state["runtimeContentHash"].Value, "new game loads applied planHash and exact runtime content hash");
                    Check(results[0]["storagePath"].Value.Replace('\\', '/').Contains("/BalanceTests/"), "new game writes only its independent test storage");
                    Check(Equal(OfficialSaveHashes(), state["officialSavesBefore"]), "apply and isolated new game leave every official save byte unchanged");
                    StartRollback();
                }
                else if ((phase == "rollback-wait" || phase == "emergency-rollback-wait") && JobDone())
                {
                    Check(JSON.Parse(File.ReadAllText(state["transaction"].Value))["phase"].Value == "rolled_back", "window rollback restores the entire apply transaction");
                    Check(Equal(FormalHashes(), state["formalBefore"]), "rollback restores every formal file hash and removes appended files exactly");
                    Finish(string.IsNullOrEmpty(state["error"].Value));
                }
                else if ((phase == "failure-wait-play-exit" || phase == "failure-wait-job") && !EditorApplication.isPlayingOrWillChangePlaymode && !BalanceWorkbenchProcess.Running)
                {
                    string transaction = state["transaction"].Value;
                    if (string.IsNullOrEmpty(transaction)) transaction = Path.Combine(state["jobOutput"].Value, "transaction.json");
                    if (File.Exists(transaction) && JSON.Parse(File.ReadAllText(transaction))["phase"].Value == "committed")
                    { state["transaction"] = transaction; state["emergencyRollbackAttempted"] = true; StartRollback(true); }
                    else Finish(false);
                }
            }
            catch (Exception ex)
            {
                if (state == null) return;
                state["error"] = ex.ToString();
                if (EditorApplication.isPlayingOrWillChangePlaymode && BalancePlayModeVerifier.Running)
                { Next("failure-wait-play-exit"); BalancePlayModeVerifier.Cancel(); return; }
                if (BalanceWorkbenchProcess.Running)
                { Next("failure-wait-job"); BalanceWorkbenchProcess.Cancel(); return; }
                string transaction = state["transaction"].Value;
                if (string.IsNullOrEmpty(transaction) && !string.IsNullOrEmpty(state["jobOutput"].Value)) transaction = Path.Combine(state["jobOutput"].Value, "transaction.json");
                if (!state["emergencyRollbackAttempted"].AsBool && File.Exists(transaction) && JSON.Parse(File.ReadAllText(transaction))["phase"].Value == "committed" && !EditorApplication.isPlayingOrWillChangePlaymode && !BalanceWorkbenchProcess.Running)
                { state["transaction"] = transaction; state["emergencyRollbackAttempted"] = true; StartRollback(true); }
                else Finish(false);
            }
        }

        private static LevelBalanceWorkbench Window() { var w = EditorWindow.GetWindow<LevelBalanceWorkbench>(); Set(w, "_autoPreview", false); return w; }
        private static JSONNode Recipe(LevelBalanceWorkbench w) { return (JSONNode)Get(w, "_recipe"); }
        private static void Set(object owner, string field, object value) { owner.GetType().GetField(field, Private).SetValue(owner, value); }
        private static object Get(object owner, string field) { return owner.GetType().GetField(field, Private).GetValue(owner); }
        private static object Call(object owner, string method, params object[] args) { return owner.GetType().GetMethod(method, Private).Invoke(owner, args); }
        private static void SwitchProfile(LevelBalanceWorkbench w, int index) { Call(w, "BeforeEdit", "切换数值预设"); Set(w, "_preset", index); var nodes = (List<JSONNode>)Call(w, "ProfileNodes"); Recipe(w)["selectedProfileId"] = nodes[index]["id"].Value; Call(w, "Changed"); }
        private static void StartJob(LevelBalanceWorkbench w, string command, string phase)
        {
            Call(w, "Run", command);
            if (!BalanceWorkbenchProcess.Running) throw new InvalidOperationException("Window did not start " + command);
            state["jobOutput"] = BalanceWorkbenchProcess.DirectoryPath;
            if (command == "preview")
            {
                string ownedJob = BalanceWorkbenchProcess.JobId;
                var second = ScriptableObject.CreateInstance<LevelBalanceWorkbench>();
                try
                {
                    Set(second, "_autoPreview", false); second.Show(); Call(second, "Run", "preview");
                    Check(BalanceWorkbenchProcess.Running && BalanceWorkbenchProcess.JobId == ownedJob && BalanceWorkbenchProcess.DirectoryPath == state["jobOutput"].Value,
                        "a second live workbench cannot replace or duplicate the active preview job");
                }
                finally { second.Close(); }
            }
            Next(phase);
        }
        private static bool JobDone() { if (BalanceWorkbenchProcess.Running) return false; if (BalanceWorkbenchProcess.ExitCode != 0) throw new InvalidOperationException("Window process failed: " + BalanceWorkbenchProcess.Log); return true; }
        private static void StartRollback(bool emergency = false) { var w = Window(); Set(w, "_rollbackPath", state["transaction"].Value); StartJob(w, "rollback", emergency ? "emergency-rollback-wait" : "rollback-wait"); }
        private static void Next(string phase) { state["phase"] = phase; state["phaseStartedUtc"] = DateTime.UtcNow.ToString("O"); Persist(); }
        private static void Persist() { Directory.CreateDirectory(Path.GetDirectoryName(StatePath)); File.WriteAllText(StatePath, state.ToString(2), new UTF8Encoding(false)); }
        private static void Check(bool condition, string description) { var e = new JSONObject(); e["passed"] = condition; e["description"] = description; e["elapsedSeconds"] = (DateTime.UtcNow - DateTime.Parse(state["startedUtc"].Value, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind)).TotalSeconds; state["events"].Add(e); Persist(); if (!condition) throw new InvalidOperationException(description); }
        private static bool Equal(JSONNode a, JSONNode b) { return a.ToString() == b.ToString(); }
        private static string HashBytes(byte[] data) { using (var hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(data)).Replace("-", "").ToLowerInvariant(); }
        private static string KeyShardHash() { return PlayerPrefs.HasKey("FT.KeyShard.B.v1") ? HashBytes(Encoding.UTF8.GetBytes(PlayerPrefs.GetString("FT.KeyShard.B.v1"))) : "absent"; }
        private static JSONNode HashFiles(IEnumerable<string> files, string root) { var hashes = new JSONObject(); foreach (var p in files.OrderBy(p => p, StringComparer.Ordinal)) hashes[Path.GetFullPath(p).Substring(Path.GetFullPath(root).Length).Replace('\\', '/')] = HashBytes(File.ReadAllBytes(p)); return hashes; }
        private static JSONNode FormalHashes() { return HashFiles(new[] { "Assets/ConfigJson", "Assets/Gen", "Luban/Config/Datas", "Luban/BalanceDesign" }.SelectMany(p => Directory.GetFiles(Path.Combine(Root, p), "*", SearchOption.AllDirectories)), Root); }
        private static JSONNode OfficialSaveHashes() { string path = Application.persistentDataPath; return HashFiles(Directory.Exists(path) ? Directory.GetFiles(path, "*", SearchOption.AllDirectories).Where(p => !p.Substring(path.Length).Replace('\\', '/').StartsWith("/BalanceTests/", StringComparison.OrdinalIgnoreCase)) : Enumerable.Empty<string>(), path); }
        private static void Finish(bool passed)
        {
            if (state == null) return;
            if (state["testKeyOverrideSet"].AsBool)
            {
                Environment.SetEnvironmentVariable("FT_SAVE_KEY", SessionState.GetBool(EnvSession + ".exists", false) ? SessionState.GetString(EnvSession, "") : null);
                SessionState.EraseString(EnvSession); SessionState.EraseBool(EnvSession + ".exists"); state["testKeyOverrideSet"] = false;
            }
            foreach (var w in Resources.FindObjectsOfTypeAll<LevelBalanceWorkbench>()) w.Close();
            if (state["draftExisted"].AsBool) File.WriteAllBytes(DraftPath, Convert.FromBase64String(state["originalDraftBase64"].Value));
            else if (File.Exists(DraftPath)) File.Delete(DraftPath);
            EditorPrefs.SetString("FT.Balance.LastOutput", state["lastOutputPref"].Value); EditorPrefs.SetString("FT.Balance.LastBackup", state["lastBackupPref"].Value);
            state["formalHashesRestored"] = Equal(FormalHashes(), state["formalBefore"]);
            state["officialSaveHashesUnchanged"] = Equal(OfficialSaveHashes(), state["officialSavesBefore"]);
            state["keyShardUnchanged"] = KeyShardHash() == state["keyShardBefore"].Value;
            state["passed"] = passed && state["formalHashesRestored"].AsBool && state["officialSaveHashesUnchanged"].AsBool && state["keyShardUnchanged"].AsBool;
            state["active"] = false; state["phase"] = state["passed"].AsBool ? "complete" : "failed";
            state["elapsedSeconds"] = (DateTime.UtcNow - DateTime.Parse(state["startedUtc"].Value, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind)).TotalSeconds;
            Persist();
            var result = JSON.Parse(state.ToString()); result.Remove("originalDraftBase64"); result.Remove("beforeWave"); result.Remove("afterWave"); result.Remove("customRecipe");
            File.WriteAllText(Path.Combine(state["output"].Value, "result.json"), result.ToString(2), new UTF8Encoding(false));
            if (state["windowWasOpen"].AsBool) EditorWindow.GetWindow<LevelBalanceWorkbench>();
        }
    }
}
#endif

#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using SimpleJSON;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// Explicit asynchronous integration checks for the real workbench/process pair.
    /// Only Library candidates are generated; this suite never applies formal data or enters PlayMode.
    /// The final phase explicitly requests a real script-domain reload and resumes from its own journal.
    /// </summary>
    [InitializeOnLoad]
    public static class BalanceWorkbenchIntegrationVerifier
    {
        private const BindingFlags InstancePrivate = BindingFlags.Instance | BindingFlags.NonPublic;
        private const BindingFlags StaticPrivate = BindingFlags.Static | BindingFlags.NonPublic;
        private static readonly string DomainToken = Guid.NewGuid().ToString("N");
        private static JSONNode state;
        private static string Root { get { return BalanceWorkbenchProcess.ProjectRoot; } }
        private static string Local { get { return Path.Combine(Root, "Library/BalanceWorkbench"); } }
        private static string StatePath { get { return Path.Combine(Local, "integration-verifier-state.json"); } }
        private static string DraftPath { get { return Path.Combine(Local, "draft.json"); } }

        static BalanceWorkbenchIntegrationVerifier() { EditorApplication.update += Poll; }

        [MenuItem("Tools/塔防/数值验证/运行工作台进程与重载专项", false, 170)]
        public static void RunFromMenu() { Start(); }

        public static string Start()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling || EditorApplication.isUpdating ||
                BalanceWorkbenchProcess.Running || BalancePlayModeVerifier.Running)
                throw new InvalidOperationException("Integration verification requires an idle EditMode editor.");
            if (File.Exists(StatePath) && JSON.Parse(File.ReadAllText(StatePath))["active"].AsBool)
                throw new InvalidOperationException("An integration verification is already active.");
            string acceptance = Path.Combine(Local, "acceptance-driver-state.json");
            if (File.Exists(acceptance) && JSON.Parse(File.ReadAllText(acceptance))["active"].AsBool)
                throw new InvalidOperationException("Finish the apply/rollback acceptance driver first.");

            bool open = Resources.FindObjectsOfTypeAll<LevelBalanceWorkbench>().Length > 0;
            var window = EditorWindow.GetWindow<LevelBalanceWorkbench>();
            Set(window, "_autoPreview", false);
            if (open) Call(window, "PersistDraft");
            state = new JSONObject(); state["active"] = true;
            state["startedUtc"] = DateTime.UtcNow.ToString("O"); state["events"] = new JSONArray();
            state["windowWasOpen"] = open;
            state["draftExisted"] = File.Exists(DraftPath);
            state["originalDraftBase64"] = File.Exists(DraftPath) ? Convert.ToBase64String(File.ReadAllBytes(DraftPath)) : "";
            state["pythonPrefExisted"] = EditorPrefs.HasKey("FT.Balance.Python");
            state["pythonPref"] = EditorPrefs.GetString("FT.Balance.Python", "");
            state["lastOutputPref"] = EditorPrefs.GetString("FT.Balance.LastOutput", "");
            state["lastBackupPref"] = EditorPrefs.GetString("FT.Balance.LastBackup", "");
            state["formalBefore"] = FormalDigest(); state["officialSavesBefore"] = OfficialSaveDigest();
            state["output"] = Path.Combine(Root, "Docs/BalanceEvidence/workbench-integration-" + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff"));
            Directory.CreateDirectory(state["output"].Value);
            state["coverage"] = "Actual window handlers and owned Python preview processes; real log file lock, cancellation, injected runner clock timeout, actual script-domain reload; no formal apply and no PlayMode.";
            Call(window, "LoadRecipe", Path.Combine(Root, "Luban/BalanceDesign/balance_design.json"));
            Call(window, "PersistDraft");
            state["testDraft"] = Recipe(window).ToString();
            Next("missing-python");
            return StatePath;
        }

        public static string Status() { return File.Exists(StatePath) ? File.ReadAllText(StatePath) : "No integration verifier state"; }

        public static void Cancel()
        {
            LoadState();
            if (state == null || !state["active"].AsBool) return;
            state["error"] = "Integration verification cancelled by caller.";
            if (OwnsCurrentJob() && BalanceWorkbenchProcess.Running) BalanceWorkbenchProcess.Cancel();
            Next("failure-wait");
        }

        private static void Poll()
        {
            if (EditorApplication.isCompiling || EditorApplication.isUpdating) return;
            try
            {
                LoadState();
                if (state == null || !state["active"].AsBool) return;
                if (EditorApplication.isPlayingOrWillChangePlaymode)
                    throw new InvalidOperationException("Integration verification must remain in EditMode.");
                string phase = state["phase"].Value;
                if (phase != "failure-wait" && Age(state["phaseStartedUtc"].Value) > 120)
                    throw new TimeoutException("Integration phase timed out: " + phase);

                if (phase == "missing-python")
                {
                    string previous = BalanceWorkbenchProcess.Python;
                    try
                    {
                        BalanceWorkbenchProcess.Python = Path.Combine(Local, "missing-python-" + Guid.NewGuid().ToString("N") + ".exe");
                        Call(Window(), "Run", "preview");
                        state["jobId"] = BalanceWorkbenchProcess.JobId;
                        state["jobOutput"] = BalanceWorkbenchProcess.DirectoryPath;
                        Check(!BalanceWorkbenchProcess.Running, "an actual missing Python executable refuses startup without creating a live job");
                        Check(BalanceWorkbenchProcess.Log.Contains("Dependency repair:") && BalanceWorkbenchProcess.Log.Contains("unavailable"),
                            "missing dependency reports the executable failure and an actionable repair command");
                    }
                    finally { BalanceWorkbenchProcess.Python = previous; }
                    Check(ReadDraft() == state["testDraft"].Value, "dependency failure preserves the complete draft");
                    Check(FormalDigest() == state["formalBefore"].Value, "dependency failure leaves all formal files unchanged");
                    StartPreview("locked-log");
                    ProbeLockedLogAndReentry();
                    Next("locked-log-wait");
                }
                else if (phase == "locked-log-wait" && !BalanceWorkbenchProcess.Running)
                {
                    CheckPreviewCompleted("log write failure and window reentry do not discard the successful preview outcome");
                    StartPreview("cancel");
                    BalanceWorkbenchProcess.Cancel();
                    Next("cancel-wait");
                }
                else if (phase == "cancel-wait" && !BalanceWorkbenchProcess.Running)
                {
                    CheckCancelled("explicit preview cancellation terminates the owned job and retains a cancellation marker");
                    StartPreview("timeout");
                    Process process = OwnedProcess();
                    Check(process != null && !process.HasExited, "timeout probe observes a real live preview process before the clock injection");
                    DateTime original = (DateTime)GetProcessField("_started");
                    try
                    {
                        SetProcessField("_started", DateTime.UtcNow.AddSeconds(-601));
                        CallProcessPoll();
                    }
                    finally { SetProcessField("_started", original); }
                    state["timeoutProbe"] = "Only the editor runner's private start clock was advanced by reflection. The real non-mutation timeout branch cancels the real preview child; no production timeout parameter is injected.";
                    Next("timeout-wait");
                }
                else if (phase == "timeout-wait" && !BalanceWorkbenchProcess.Running)
                {
                    CheckCancelled("the runner timeout uses the real cancellation path and leaves formal data unchanged");
                    StartPreview("reload");
                    state["reloadJobId"] = BalanceWorkbenchProcess.JobId;
                    state["reloadDirectory"] = BalanceWorkbenchProcess.DirectoryPath;
                    state["beforeReloadToken"] = DomainToken;
                    state["reloadRequestedUtc"] = DateTime.UtcNow.ToString("O");
                    Call(Window(), "PersistDraft");
                    Next("reload-wait");
                    EditorUtility.RequestScriptReload();
                }
                else if (phase == "reload-wait")
                {
                    if (DomainToken == state["beforeReloadToken"].Value) return;
                    if (!state["newDomainObserved"].AsBool)
                    {
                        state["newDomainObserved"] = true;
                        state["afterReloadToken"] = DomainToken;
                        Check(true, "RequestScriptReload actually replaced the script domain and resumed the persisted verifier phase");
                        Check(BalanceWorkbenchProcess.JobId == state["reloadJobId"].Value &&
                              BalanceWorkbenchProcess.DirectoryPath == state["reloadDirectory"].Value,
                            "the process runner recovers the exact journal job identity after domain reload");
                        Check((bool)GetProcessField("_recovered"), "the production runner executed its persisted-job recovery path");
                        state["liveChildObservedAfterReload"] = BalanceWorkbenchProcess.Running;
                        state["recoveryObservation"] = BalanceWorkbenchProcess.Running
                            ? "Observed an owned live child after reload, then waited for its exit."
                            : "Child had already exited by the first resumed observation; validated terminal receipt and recovered outcome instead.";
                        Persist();
                    }
                    if (BalanceWorkbenchProcess.Running) return;
                    CheckPreviewCompleted("the domain-recovered preview publishes its actual successful terminal outcome");
                    JSONNode receipt = JSON.Parse(File.ReadAllText(Path.Combine(state["reloadDirectory"].Value, "cli-exit.json")));
                    Check(receipt["jobId"].Value == state["reloadJobId"].Value && receipt["command"].Value == "preview" && receipt["exitCode"].AsInt == 0,
                        "the recovered outcome matches the real CLI terminal receipt, job ID and command");
                    Check(ReadDraft() == state["testDraft"].Value, "the actual domain reload preserves the complete workbench draft");
                    Finish(true);
                }
                else if (phase == "failure-wait" && !BalanceWorkbenchProcess.Running) Finish(false);
            }
            catch (Exception error)
            {
                if (state == null) return;
                if (string.IsNullOrEmpty(state["error"].Value)) state["error"] = error.ToString();
                if (OwnsCurrentJob() && BalanceWorkbenchProcess.Running)
                {
                    BalanceWorkbenchProcess.Cancel(); Next("failure-wait");
                }
                else Finish(false);
            }
        }

        private static void ProbeLockedLogAndReentry()
        {
            Process process = OwnedProcess();
            Check(process != null && !process.HasExited, "log-lock probe observes a real live owned preview child");
            string jobId = BalanceWorkbenchProcess.JobId;
            string directory = BalanceWorkbenchProcess.DirectoryPath;
            string journalBefore = File.ReadAllText(Path.Combine(directory, "editor-job.json"));
            using (var locked = new FileStream(Path.Combine(directory, "editor.log"), FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None))
            {
                SetProcessField("_lastPersist", double.NegativeInfinity);
                CallProcessPoll();
                Check(!process.HasExited && BalanceWorkbenchProcess.Running && BalanceWorkbenchProcess.JobId == jobId,
                    "an actual exclusive editor.log lock cannot detach a child observed alive before and after monitor polling");
                Check(BalanceWorkbenchProcess.Log.Contains("Cannot persist diagnostic log"),
                    "the locked log produces a diagnostic while process ownership is retained");
            }
            var window = Window(); Call(window, "PersistDraft"); window.Close();
            var reopened = Window();
            Check(BalanceWorkbenchProcess.Running && BalanceWorkbenchProcess.JobId == jobId &&
                  File.ReadAllText(Path.Combine(directory, "editor-job.json")) == journalBefore,
                "closing and reopening the window leaves the active process and its ownership journal intact");
            var second = ScriptableObject.CreateInstance<LevelBalanceWorkbench>();
            try
            {
                Set(second, "_autoPreview", false); second.Show(); Call(second, "Run", "preview");
                Check(BalanceWorkbenchProcess.Running && BalanceWorkbenchProcess.JobId == jobId && BalanceWorkbenchProcess.DirectoryPath == directory,
                    "a simultaneous second window cannot replace the live preview job");
            }
            finally { second.Close(); }
            Check(Recipe(reopened).ToString() == state["testDraft"].Value, "active-job window reentry preserves the same complete draft");
        }

        private static void StartPreview(string label)
        {
            if (BalanceWorkbenchProcess.Running) throw new InvalidOperationException("Previous job has not terminated.");
            Call(Window(), "Run", "preview");
            state["jobId"] = BalanceWorkbenchProcess.JobId;
            state["jobOutput"] = BalanceWorkbenchProcess.DirectoryPath;
            Check(BalanceWorkbenchProcess.Running, label + " starts an actual asynchronous CLI preview");
            string full = Path.GetFullPath(BalanceWorkbenchProcess.DirectoryPath).Replace('\\', '/');
            string local = Path.GetFullPath(Local).Replace('\\', '/').TrimEnd('/') + "/";
            Check(full.StartsWith(local, StringComparison.OrdinalIgnoreCase), "preview output stays below Library/BalanceWorkbench");
            state[label + "Output"] = BalanceWorkbenchProcess.DirectoryPath;
            Persist();
        }

        private static void CheckPreviewCompleted(string description)
        {
            Check(OwnsCurrentJob() && BalanceWorkbenchProcess.ExitCode == 0, description);
            string path = Path.Combine(state["jobOutput"].Value, "preview.json");
            Check(File.Exists(path) && JSON.Parse(File.ReadAllText(path))["validation"]["passed"].AsBool,
                "the real preview candidate exists and passed the shared core validation");
        }

        private static void CheckCancelled(string description)
        {
            Check(OwnsCurrentJob() && BalanceWorkbenchProcess.ExitCode != 0 && BalanceWorkbenchProcess.ExitCode != int.MinValue &&
                  File.Exists(Path.Combine(state["jobOutput"].Value, "cancel.request")), description);
            Check(ReadDraft() == state["testDraft"].Value, "cancellation keeps the complete draft available for retry");
        }

        private static bool OwnsCurrentJob() { return state != null && BalanceWorkbenchProcess.JobId == state["jobId"].Value && BalanceWorkbenchProcess.DirectoryPath == state["jobOutput"].Value; }
        private static Process OwnedProcess() { return GetProcessField("_process") as Process; }
        private static object GetProcessField(string name) { return typeof(BalanceWorkbenchProcess).GetField(name, StaticPrivate).GetValue(null); }
        private static void SetProcessField(string name, object value) { typeof(BalanceWorkbenchProcess).GetField(name, StaticPrivate).SetValue(null, value); }
        private static void CallProcessPoll() { typeof(BalanceWorkbenchProcess).GetMethod("Poll", StaticPrivate).Invoke(null, null); }
        private static LevelBalanceWorkbench Window() { var w = EditorWindow.GetWindow<LevelBalanceWorkbench>(); Set(w, "_autoPreview", false); return w; }
        private static JSONNode Recipe(LevelBalanceWorkbench w) { return (JSONNode)w.GetType().GetField("_recipe", InstancePrivate).GetValue(w); }
        private static void Set(object owner, string field, object value) { owner.GetType().GetField(field, InstancePrivate).SetValue(owner, value); }
        private static object Call(object owner, string method, params object[] args) { return owner.GetType().GetMethod(method, InstancePrivate).Invoke(owner, args); }
        private static string ReadDraft() { return JSON.Parse(File.ReadAllText(DraftPath)).ToString(); }
        private static double Age(string utc) { return (DateTime.UtcNow - DateTime.Parse(utc, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind)).TotalSeconds; }
        private static void LoadState() { if (state == null && File.Exists(StatePath)) state = JSON.Parse(File.ReadAllText(StatePath)); }
        private static void Next(string phase) { state["phase"] = phase; state["phaseStartedUtc"] = DateTime.UtcNow.ToString("O"); Persist(); }
        private static void Persist() { Directory.CreateDirectory(Local); File.WriteAllText(StatePath, state.ToString(2), new UTF8Encoding(false)); }
        private static void Check(bool passed, string description)
        {
            var entry = new JSONObject(); entry["passed"] = passed; entry["description"] = description;
            entry["elapsedSeconds"] = Age(state["startedUtc"].Value); state["events"].Add(entry); Persist();
            if (!passed) throw new InvalidOperationException(description);
        }

        private static string Hash(byte[] bytes) { using (var sha = SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", "").ToLowerInvariant(); }
        private static string Digest(IEnumerable<string> paths, string basePath)
        {
            string prefix = Path.GetFullPath(basePath).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            var entries = new StringBuilder();
            foreach (string path in paths.OrderBy(p => p, StringComparer.Ordinal))
                entries.Append(Path.GetFullPath(path).Substring(prefix.Length).Replace('\\', '/')).Append('\t').Append(Hash(File.ReadAllBytes(path))).Append('\n');
            return Hash(Encoding.UTF8.GetBytes(entries.ToString()));
        }
        private static string FormalDigest()
        {
            return Digest(new[] { "Assets/ConfigJson", "Assets/Gen", "Luban/Config/Datas", "Luban/BalanceDesign" }
                .SelectMany(relative => Directory.GetFiles(Path.Combine(Root, relative), "*", SearchOption.AllDirectories)), Root);
        }
        private static string OfficialSaveDigest()
        {
            string path = Application.persistentDataPath;
            return Digest(Directory.Exists(path) ? Directory.GetFiles(path, "*", SearchOption.AllDirectories)
                .Where(p => !p.Substring(path.Length).Replace('\\', '/').StartsWith("/BalanceTests/", StringComparison.OrdinalIgnoreCase)) : Enumerable.Empty<string>(), path);
        }

        private static void Finish(bool passed)
        {
            if (state == null) return;
            var errors = new List<Exception>();
            try
            {
                foreach (var window in Resources.FindObjectsOfTypeAll<LevelBalanceWorkbench>()) window.Close();
                if (state["draftExisted"].AsBool) File.WriteAllBytes(DraftPath, Convert.FromBase64String(state["originalDraftBase64"].Value));
                else if (File.Exists(DraftPath)) File.Delete(DraftPath);
            }
            catch (Exception error) { errors.Add(error); }
            try
            {
                if (state["pythonPrefExisted"].AsBool) EditorPrefs.SetString("FT.Balance.Python", state["pythonPref"].Value);
                else EditorPrefs.DeleteKey("FT.Balance.Python");
                EditorPrefs.SetString("FT.Balance.LastOutput", state["lastOutputPref"].Value);
                EditorPrefs.SetString("FT.Balance.LastBackup", state["lastBackupPref"].Value);
            }
            catch (Exception error) { errors.Add(error); }
            try { state["formalHashesUnchanged"] = FormalDigest() == state["formalBefore"].Value; }
            catch (Exception error) { errors.Add(error); }
            try { state["officialSaveHashesUnchanged"] = OfficialSaveDigest() == state["officialSavesBefore"].Value; }
            catch (Exception error) { errors.Add(error); }
            state["recoveryErrors"] = new JSONArray(); foreach (Exception error in errors) state["recoveryErrors"].Add(error.ToString());
            state["passed"] = passed && errors.Count == 0 && state["formalHashesUnchanged"].AsBool && state["officialSaveHashesUnchanged"].AsBool;
            state["elapsedSeconds"] = Age(state["startedUtc"].Value);
            state["active"] = false; state["phase"] = state["passed"].AsBool ? "complete" : "failed";
            Persist();
            var result = JSON.Parse(state.ToString()); result.Remove("originalDraftBase64"); result.Remove("testDraft");
            File.WriteAllText(Path.Combine(state["output"].Value, "result.json"), result.ToString(2), new UTF8Encoding(false));
            if (state["windowWasOpen"].AsBool) Window();
        }
    }
}
