                _newPreset = GUILayout.TextField(_newPreset, GUILayout.Width(110));
                if (GUILayout.Button("另存预设")) SaveAsPreset();
                BalanceWorkbenchProcess.Python = EditorGUILayout.TextField("Python", BalanceWorkbenchProcess.Python);
            }
        }

        private void SaveAsPreset()
        {
            if (string.IsNullOrWhiteSpace(_newPreset) || ProfileNodes().Any(n => n["id"].Value == _newPreset))
            { _status = "预设ID必须非空且唯一；内置八档不能覆盖。"; return; }
            BeforeEdit("另存自定义预设");
            string oldProfile = ProfileId;
            var source = JSON.Parse(ProfileNodes()[_preset].ToString()); source["id"] = _newPreset;
            source["name"] = "自定义 " + _newPreset;
            if (_recipe["profiles"].IsArray) _recipe["profiles"].Add(source);
            else _recipe["profiles"][_newPreset] = source;
            _preset = ProfileNodes().Count - 1; _recipe["selectedProfileId"] = _newPreset;
            if (_recipe["overrides"].IsArray)
            {
                var copies = new List<JSONNode>();
                foreach (var kv in _recipe["overrides"])
                    if (kv.Value["profileId"].Value == oldProfile)
                    { var copy = JSON.Parse(kv.Value.ToString()); copy["profileId"] = _newPreset; copy["id"] = copy["id"].Value + "-" + _newPreset; copies.Add(copy); }
                foreach (var n in copies) _recipe["overrides"].Add(n);
            }
            Changed(); _status = "自定义预设已写入草稿；正式应用后纳入权威配方版本。";
        }

        private void Run(string command)
        {
            PersistDraft(); _dirtyAt = -1;
            string job = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff") + "-" + command;
            _lastOutput = Path.Combine(Local, job);
            string args = "--profile " + BalanceWorkbenchProcess.Quote(ProfileId) + " --recipe " + BalanceWorkbenchProcess.Quote(DraftPath) + " --out " + BalanceWorkbenchProcess.Quote(_lastOutput);
            if (command == "simulate")
                args += " --strategy " + new[] { "normal", "power", "mixed" }[_strategy] + " --step " + _step.ToString("R", CultureInfo.InvariantCulture) + " --seed " + _seed + (_allProfiles ? " --all-profiles" : " --level-min " + _level + " --level-max " + _level);
            if (command == "rollback") args += " --transaction " + BalanceWorkbenchProcess.Quote(_rollbackPath);
            if (BalanceWorkbenchProcess.Start(command, args, _lastOutput))
            {
                _status = "运行 " + command + " · " + job;
                EditorPrefs.SetString("FT.Balance.LastOutput", _lastOutput);
            }
            else _status = "未启动。检查任务日志、Python和编译状态。";
        }

        private void LoadPreview()
        {
            _preview = null; _plan = null;
            if (string.IsNullOrEmpty(_lastOutput)) return;
            string p = Path.Combine(_lastOutput, "preview.json");
            string plan = Path.Combine(_lastOutput, "resolved-plan.json");
            try
            {
                if (File.Exists(p)) _preview = JSON.Parse(File.ReadAllText(p));
                if (File.Exists(plan)) _plan = JSON.Parse(File.ReadAllText(plan));
            }
            catch (Exception ex) { _status = "候选读取失败: " + ex.Message; }
        }

        private void JobCompleted()
        {
            _lastOutput = BalanceWorkbenchProcess.DirectoryPath; LoadPreview();
            bool ok = BalanceWorkbenchProcess.ExitCode == 0;
            _status = (ok ? "已完成 " : "失败（正式应用未认证成功） ") + BalanceWorkbenchProcess.Command + " · " + BalanceWorkbenchProcess.ElapsedSeconds.ToString("F2") + "s · " + _lastOutput;
            if (ok && BalanceWorkbenchProcess.IsMutation)
            {
                if (BalanceWorkbenchProcess.Command == "apply") _rollbackPath = Path.Combine(_lastOutput, "transaction.json");
                string result = Path.Combine(_lastOutput, "result.json");
                if (File.Exists(result))
                {
                    var n = JSON.Parse(File.ReadAllText(result));
                    if (!string.IsNullOrEmpty(n["backup"].Value)) _rollbackPath = n["backup"];
                }
                EditorPrefs.SetString("FT.Balance.LastBackup", _rollbackPath);
                AssetDatabase.Refresh();
            }
            Repaint();
        }
    }
}

using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 生成战斗用预制体：子弹 + 全部怪物（P0-4）。
    ///
    /// 一、Bullet_Normal.prefab（从零创建）
    ///   极简结构：SpriteRenderer(圆点) + BaseBullet，约一格的四分之一
    ///
    /// 二、全部怪物
    ///   委托给 <see cref="MonsterPrefabBuilder"/>：它会把
    ///   `Assets/_UIAssets/Monsters/**` 下的每个怪物转成战斗预制体
    ///   （去物理 / 挂 BaseEnemy / 自适应血条）。
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建）▸ 生成战斗预制体
    /// </summary>
    public static class BattlePrefabBuilder
    {
        public const string BulletPath = "Assets/Prefabs/Bullet/Bullet_Normal.prefab";

        private const string BulletSpriteKey = "Bullet_Dot";

        [MenuItem("Tools/塔防/高级（单步重建）/生成战斗预制体", false, 302)]
        public static void Build()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            BuildInternal(report);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log(report.Errors > 0
                ? "[M0] 战斗预制体生成有错误：\n" + report.Text
                : "[M0] 战斗预制体生成完成：\n" + report.Text);
        }

        /// <summary>供一键向导调用（不弹窗）</summary>
        public static void BuildInternal(EditorUtil.Report report)
        {
            BuildBullet(report);
            MonsterPrefabBuilder.BuildAllInternal(report);
        }

        // ------------------------------------------------------------------
        // 子弹
        // ------------------------------------------------------------------

        private static void BuildBullet(EditorUtil.Report report)
        {
            report.Head("生成子弹预制体 → " + BulletPath);

            Sprite dot = AssetDatabase.LoadAssetAtPath<Sprite>(
                EditorUtil.GeneratedArtDir + "/" + BulletSpriteKey + ".png");
            if (dot == null)
            {
                report.Error("找不到子弹贴图，请先执行「高级（单步重建）▸ 生成占位美术」");
                return;
            }

            AssetDatabase.DeleteAsset(BulletPath);
            EditorUtil.EnsureFolderOfFile(BulletPath);

            GameObject go = new GameObject("Bullet_Normal");
            SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
            sr.sprite = dot;
            sr.sortingLayerName = BoardSorting.LayerMain;
            sr.sortingOrder = BoardSorting.Bullet;
            go.AddComponent<BaseBullet>();

            GameObject saved = PrefabUtility.SaveAsPrefabAsset(go, BulletPath);
            Object.DestroyImmediate(go);

            if (saved == null)
            {
                report.Error("保存失败：" + BulletPath);
                return;
            }
            Bounds b;
            if (EditorUtil.TryMeasureBounds(saved, out b))
            {
                report.Ok(string.Format("Bullet_Normal.prefab（SpriteRenderer + BaseBullet，直径 {0:F2} 世界单位）",
                    b.size.x));
            }
            else
            {
                report.Ok("Bullet_Normal.prefab（SpriteRenderer + BaseBullet）");
            }
        }
    }
}

using System;
using System.IO;
using System.Linq;
using System.Text;
using FTProject.AOT;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace FTProject.EditorTools
{
    public static class BootReleaseBuilder
    {
        public const string EvidenceRoot = "Builds/BootRefactor";
        public const string TestRoot = EvidenceRoot + "/Server";
        public const string TestPackage = "com.ftproject.freedomtower.bootvalidation";

        [MenuItem("Tools/塔防/启动重构/配置 Boot 首屏")]
        public static void ConfigureBoot()
        {
            if (EditorApplication.isPlaying) throw new InvalidOperationException("Exit Play before configuring Boot");
            string error;
            if (!AddMainSceneCollector.Ensure(out error)) throw new Exception(error);
            var scene = EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity", OpenSceneMode.Single);
            var existing = scene.GetRootGameObjects().FirstOrDefault(x => x.name == "BootCanvas");
            if (existing == null)
            {
                var canvas = new GameObject("BootCanvas", typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));
                canvas.GetComponent<Canvas>().renderMode = RenderMode.ScreenSpaceOverlay;
                canvas.GetComponent<Canvas>().sortingOrder = 1000;
                var scaler = canvas.GetComponent<CanvasScaler>();
                scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
                scaler.referenceResolution = new Vector2(1920, 1080);
                scaler.matchWidthOrHeight = .5f;
                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/BootUI/HotUpdateView.prefab");
                var view = (GameObject)PrefabUtility.InstantiatePrefab(prefab, canvas.transform);
                var rect = view.GetComponent<RectTransform>();
                rect.anchorMin = Vector2.zero; rect.anchorMax = Vector2.one;
                rect.offsetMin = rect.offsetMax = Vector2.zero;
                new GameObject("BootEventSystem", typeof(EventSystem), typeof(StandaloneInputModule));
            }
            EditorBuildSettings.scenes = new[] {
                new EditorBuildSettingsScene("Assets/Scenes/Boot.unity", true),
                new EditorBuildSettingsScene("Assets/Scenes/Main.unity", false) };
            EditorSceneManager.SaveScene(scene);
            AssetDatabase.SaveAssets();
            ValidateShell();
        }

        public static void ValidateShell()
        {
            var enabled = EditorBuildSettings.scenes.Where(x => x.enabled).ToArray();
            if (enabled.Length != 1 || enabled[0].path != "Assets/Scenes/Boot.unity")
                throw new BuildFailedException("Only Boot may be enabled in APK Build Settings; Main must load from YooAsset.");
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/BootUI/HotUpdateView.prefab");
            if (prefab == null || prefab.GetComponent<HotUpdateView>() == null) throw new BuildFailedException("AOT HotUpdateView missing");
            foreach (var component in prefab.GetComponentsInChildren<MonoBehaviour>(true))
            {
                if (component == null) throw new BuildFailedException("Boot UI has a missing script");
                string assembly = component.GetType().Assembly.GetName().Name;
                if (HotUpdateAssembler.HotUpdateAssemblies.Contains(assembly + ".dll"))
                    throw new BuildFailedException("Boot UI depends on hot-update component: " + component.GetType());
            }
            foreach (string dependency in AssetDatabase.GetDependencies("Assets/Scenes/Boot.unity", true))
            {
                if (!dependency.EndsWith(".cs", StringComparison.OrdinalIgnoreCase)) continue;
                var script = AssetDatabase.LoadAssetAtPath<MonoScript>(dependency);
                var type = script != null ? script.GetClass() : null;
                if (type != null && HotUpdateAssembler.HotUpdateAssemblies.Contains(type.Assembly.GetName().Name + ".dll"))
                    throw new BuildFailedException("Boot scene depends on hot-update script: " + dependency);
            }
        }

        public static string AotSignature()
        {
            var paths = Directory.GetFiles("Assets/AOTAssembly", "*.cs").OrderBy(x => x, StringComparer.Ordinal);
            var source = new StringBuilder("BootPlayerApi=2\n");
            foreach (string path in paths) source.Append(path.Replace('\\', '/')).Append('\n').Append(File.ReadAllText(path)).Append('\n');
            source.Append(File.ReadAllText("Assets/link.xml"));
            return BootReleaseStore.Hash(source.ToString());
        }

        // Immutable payloads first; atomic release.json replacement is the last publishing step.
        // Calling this against a test root does not touch the existing HotUpdateServer deployment.
        public static string Publish(string version, string outputRoot, bool writeApkBaseline)
        {
            ValidateShell();
            string build = HotUpdatePaths.BuildDir(version);
            if (!File.Exists(Path.Combine(build, "FreeTower_" + version + ".bytes")))
                throw new FileNotFoundException("Build the requested YooAsset version first", build);
            var release = new BootRelease { aotSignature = AotSignature(), resourceVersion = version };
            release.manifestMd5 = BootReleaseStore.Md5(Path.Combine(build, "FreeTower_" + version + ".bytes"));
            string apkDescriptor = "Assets/StreamingAssets/boot-release.json";
            if (!writeApkBaseline && File.Exists(apkDescriptor))
            {
                var baseline = JsonUtility.FromJson<BootRelease>(File.ReadAllText(apkDescriptor));
                if (baseline.aotSignature != release.aotSignature)
                    throw new BuildFailedException("AOT changed: publish a new APK baseline before building a hot update");
                if (baseline.resourceVersion == version && !string.IsNullOrEmpty(baseline.manifestMd5) && baseline.manifestMd5 != release.manifestMd5)
                    throw new BuildFailedException("Resource version is immutable; increment the version for changed AB content");
            }
            string releaseRoot = Path.Combine(outputRoot, "releases");
            if (Directory.Exists(releaseRoot))
                foreach (string previous in Directory.GetFiles(releaseRoot, "release.json", SearchOption.AllDirectories))
                {
                    var old = JsonUtility.FromJson<BootRelease>(File.ReadAllText(previous));
                    if (old.resourceVersion == version && !string.IsNullOrEmpty(old.manifestMd5) && old.manifestMd5 != release.manifestMd5)
                        throw new BuildFailedException("Resource version already published with different content: " + version);
                }
            release.dlls = HotUpdateAssembler.HotUpdateAssemblies.Select(name => new BootDllFile {
                name = name, md5 = BootReleaseStore.Md5(Path.Combine(HotUpdatePaths.DllDir, name)) }).ToArray();
            string identity = version + "|" + release.aotSignature + "|" + string.Join("|", release.dlls.Select(x => x.name + ":" + x.md5));
            // Include all built resource hashes so rebuilding the same version cannot mutate a release.
            foreach (string file in Directory.GetFiles(build).Where(IsPayload).OrderBy(x => x, StringComparer.Ordinal))
                identity += "|" + Path.GetFileName(file) + ":" + BootReleaseStore.Md5(file);
            release.id = version + "-" + BootReleaseStore.Hash(identity).Substring(0, 16);
            release.contentRoot = "releases/" + release.id;
            string destination = Path.Combine(outputRoot, release.contentRoot);
            Directory.CreateDirectory(destination);
            foreach (string file in Directory.GetFiles(build).Where(IsPayload)) CopyVerified(file, Path.Combine(destination, Path.GetFileName(file)));
            string dllRoot = Path.Combine(destination, "HybridCLR");
            Directory.CreateDirectory(dllRoot);
            foreach (var file in release.dlls) CopyVerified(Path.Combine(HotUpdatePaths.DllDir, file.name), Path.Combine(dllRoot, file.name));
            string dllList = string.Join("\n", release.dlls.Select(x => x.md5 + "  " + x.name)) + "\n";
            string listPath = Path.Combine(dllRoot, "md5.txt");
            if (File.Exists(listPath) && File.ReadAllText(listPath) != dllList) throw new IOException("Immutable DLL checksum list collision");
            File.WriteAllText(listPath, dllList, new UTF8Encoding(false));
            var inventory = new HotUpdateManifestDto { version = version, platform = HotUpdatePaths.PlatformFolder,
                package = "FreeTower", note = "Immutable release payload inventory" };
            inventory.files = Directory.GetFiles(destination, "*", SearchOption.AllDirectories)
                .Where(x => Path.GetFileName(x) != "release.json" && Path.GetFileName(x) != "payloads.json")
                .OrderBy(x => x, StringComparer.Ordinal)
                .Select(x => new HotUpdateFileEntryDto { path = x.Substring(destination.Length + 1).Replace('\\', '/'),
                    size = new FileInfo(x).Length, md5 = BootReleaseStore.Md5(x) }).ToArray();
            inventory.totalBytes = inventory.files.Sum(x => x.size);
            File.WriteAllText(Path.Combine(destination, "payloads.json"), JsonUtility.ToJson(inventory, true), new UTF8Encoding(false));
            string json = JsonUtility.ToJson(release, true);
            File.WriteAllText(Path.Combine(destination, "release.json"), json, new UTF8Encoding(false));
            Directory.CreateDirectory(outputRoot);
            string pointer = Path.Combine(outputRoot, "release.json");
            File.WriteAllText(pointer + ".tmp", json, new UTF8Encoding(false));
            BootReleaseStore.AtomicMove(pointer + ".tmp", pointer);
            if (writeApkBaseline)
            {
                File.WriteAllText("Assets/StreamingAssets/boot-release.json", json, new UTF8Encoding(false));
                AssetDatabase.Refresh();
            }
            Debug.Log("[ReleaseBuild] Published " + release.id + " => " + outputRoot);
            return release.id;
        }

        private static bool IsPayload(string path)
        {
            string extension = Path.GetExtension(path);
            return extension == ".bundle" || extension == ".bytes" || extension == ".hash" || extension == ".version"
                || HotUpdateFileUtil.IsBareHashFile(Path.GetFileName(path));
        }
        private static void CopyVerified(string source, string destination)
        {
            if (File.Exists(destination))
            {
                if (BootReleaseStore.Md5(source) != BootReleaseStore.Md5(destination)) throw new IOException("Immutable payload collision: " + destination);
                return;
            }
            File.Copy(source, destination);
            if (BootReleaseStore.Md5(source) != BootReleaseStore.Md5(destination)) throw new IOException("Copy checksum mismatch: " + destination);
        }

        public static void BuildBaseline()
        {
            var report = new EditorUtil.Report();
            bool ok = FTYooAssetSetupWizard.BuildRealBundlesCore("2.0.0", false, report);
            Directory.CreateDirectory(EvidenceRoot);
            File.WriteAllText(EvidenceRoot + "/ab-baseline.txt", ok + "\n" + report.Text);
            if (!ok) throw new BuildFailedException(report.Text);
            Publish("2.0.0", TestRoot, true);
        }
        public static void ScheduleBaseline() { EditorApplication.delayCall += BuildBaseline; }
        public static void ScheduleIsolatedApk() { EditorApplication.delayCall += BuildIsolatedApk; }

        public static void BuildIsolatedApk()
        {
            string originalId = PlayerSettings.GetApplicationIdentifier(BuildTargetGroup.Android);
            string originalName = PlayerSettings.productName;
            try
            {
                PlayerSettings.SetApplicationIdentifier(BuildTargetGroup.Android, TestPackage);
                PlayerSettings.productName = "FreeTower Boot Validation";
                Directory.CreateDirectory(EvidenceRoot);
                var report = BuildPipeline.BuildPlayer(new BuildPlayerOptions {
                    scenes = new[] { "Assets/Scenes/Boot.unity" }, target = BuildTarget.Android,
                    locationPathName = EvidenceRoot + "/baseline.apk", options = BuildOptions.Development });
                File.WriteAllText(EvidenceRoot + "/apk-result.txt", report.summary.result + " errors=" + report.summary.totalErrors);
                if (report.summary.result != BuildResult.Succeeded) throw new BuildFailedException("Isolated APK build failed");
            }
            finally
            {
                PlayerSettings.SetApplicationIdentifier(BuildTargetGroup.Android, originalId);
                PlayerSettings.productName = originalName;
                AssetDatabase.SaveAssets();
            }
        }
    }

    public sealed class BootBuildGuard : IPreprocessBuildWithReport
    {
        public int callbackOrder => -1000;
        public void OnPreprocessBuild(BuildReport report)
        {
            BootReleaseBuilder.ValidateShell();
            // HybridCLR exports a temporary scripts-only project to generate stripped metadata.
            // That prerequisite intentionally precedes creation of the final APK baseline.
            if (report.summary.outputPath.Replace('\\', '/').Contains("/StrippedAOTDllsTempProj/")) return;
            string path = "Assets/StreamingAssets/boot-release.json";
            if (!File.Exists(path)) throw new BuildFailedException("Publish an APK baseline release before building");
            var release = JsonUtility.FromJson<BootRelease>(File.ReadAllText(path));
            if (!BootReleaseStore.Valid(release) || release.aotSignature != BootReleaseBuilder.AotSignature())
                throw new BuildFailedException("APK baseline AOT signature is stale; rebuild DLL/AB and publish baseline");
            foreach (var file in release.dlls)
                if (!BootReleaseStore.Matches(Path.Combine(HotUpdatePaths.DllDir, file.name), file.md5))
                    throw new BuildFailedException("APK baseline DLL mismatch: " + file.name);
            string versionFile = "Assets/StreamingAssets/yoo/FreeTower/FreeTower.version";
            if (!File.Exists(versionFile) || File.ReadAllText(versionFile).Trim() != release.resourceVersion)
                throw new BuildFailedException("APK builtin resources and baseline release version differ");
            string builtinManifest = "Assets/StreamingAssets/yoo/FreeTower/FreeTower_" + release.resourceVersion + ".bytes";
            if (!BootReleaseStore.Matches(builtinManifest, release.manifestMd5))
                throw new BuildFailedException("APK builtin manifest differs from the pinned baseline");
        }
    }
}

using System.IO;
using System.Text;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 一键构建 APK（Android）。
    ///
    /// 流程：
    ///   ① 前置检查：非编译中 / 非运行中 / 当前构建目标必须是 Android
    ///   ② 环境自检：JDK / SDK / NDK 路径是否已配置（缺了只警告不中止，让 Gradle 自己报真正的错）
    ///   ③ BuildPipeline.BuildPlayer 构建到 &lt;工程根目录&gt;/Builds/Android/freedomtower.apk
    ///      （未配置签名 keystore 时 Unity 自动使用 debug keystore，仅限开发用）
    ///   ④ 自检：APK 文件是否存在、大小是否合理，结果全部走 Console 日志（不弹窗）
    ///
    /// 状态文件：&lt;工程根目录&gt;/Library/FTBuildApkStatus.txt
    ///   构建开始 / 结束都会追加一行带时间戳的状态（START / DONE OK / DONE FAIL），
    ///   供外部脚本（MCP/CI）轮询构建进度，避免阻塞式等待。
    ///
    /// 菜单：
    ///   Tools ▸ 塔防 ▸ 6. 一键构建 APK
    /// </summary>
    public static class BuildApk
    {
        /// <summary>输出路径（相对工程根目录）</summary>
        public const string OutputRelative = "Builds/Android/freedomtower.apk";

        /// <summary>构建状态文件（相对工程根目录，外部轮询用）</summary>
        public const string StatusFileRelative = "Library/FTBuildApkStatus.txt";

        [MenuItem("Tools/塔防/6. 一键构建 APK", false, 110)]
        public static void BuildMenu()
        {
            // 【不直接 Build】BuildPipeline.BuildPlayer 会阻塞主线程十几分钟，
            // 菜单回调里先只做调度（delayCall），让菜单调用本身立刻返回。
            EditorApplication.delayCall += BuildNow;
        }

        public static void BuildNow()
        {
            // ① 前置检查
            if (EditorApplication.isCompiling)
            {
                Debug.LogError("[BuildApk] 构建中止：编辑器正在编译脚本，请等编译完成后再试。");
                WriteStatus("DONE FAIL compiling");
                return;
            }
            if (EditorApplication.isPlaying)
            {
                Debug.LogError("[BuildApk] 构建中止：编辑器正在 Play 模式，请先退出。");
                WriteStatus("DONE FAIL playing");
                return;
            }
            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                Debug.LogError("[BuildApk] 构建中止：当前构建目标是 " +
                               EditorUserBuildSettings.activeBuildTarget + "，请先切换到 Android（File ▸ Build Settings）。");
                WriteStatus("DONE FAIL wrong_target");
                return;
            }

            // ② 环境自检（只警告不中止）
            EditorUtil.Report env = new EditorUtil.Report();
            env.Head("构建环境自检");
            CheckEnv("JDK", "JdkPath", env);
            CheckEnv("SDK", "AndroidSdkRoot", env);
            CheckEnv("NDK", "AndroidNdkRoot", env);
            if (string.IsNullOrEmpty(PlayerSettings.Android.keystoreName))
            {
                env.Ok("未配置签名 keystore → 使用 debug keystore（仅开发用）");
            }
            else
            {
                env.Ok("签名 keystore：" + PlayerSettings.Android.keystoreName);
            }
            Debug.Log("[BuildApk] " + env.Text);

            // ③ 收集构建场景
            var sceneList = new StringBuilder();
            System.Collections.Generic.List<string> scenes = new System.Collections.Generic.List<string>();
            foreach (EditorBuildSettingsScene s in EditorBuildSettings.scenes)
            {
                if (!s.enabled) continue;
                scenes.Add(s.path);
                sceneList.AppendLine("    " + s.path);
            }
            if (scenes.Count == 0)
            {
                Debug.LogError("[BuildApk] 构建中止：Build Settings 里没有任何启用的场景。");
                WriteStatus("DONE FAIL no_scenes");
                return;
            }

            string outputPath = Path.GetFullPath(OutputRelative);
            string outputDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            Debug.Log("[BuildApk] 开始构建 APK → " + outputPath + "\n场景：\n" + sceneList);
            WriteStatus("START " + System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));

            // ④ 构建（阻塞主线程，IL2CPP 首包可能十几分钟以上）
            BuildPlayerOptions options = new BuildPlayerOptions
            {
                scenes = scenes.ToArray(),
                locationPathName = outputPath,
                target = BuildTarget.Android,
                options = BuildOptions.None,
            };
            BuildReport report = BuildPipeline.BuildPlayer(options);

            // ⑤ 结果自检
            if (report.summary.result == BuildResult.Succeeded)
            {
                long sizeMb = (long)(report.summary.totalSize / (1024 * 1024));
                Debug.Log("[BuildApk] ✔ 构建成功：" + outputPath +
                          "（" + sizeMb + " MB，耗时 " + report.summary.totalTime.TotalMinutes.ToString("F1") + " 分钟）");
                WriteStatus("DONE OK size=" + sizeMb + "MB path=" + OutputRelative);
            }
            else
            {
                Debug.LogError("[BuildApk] ✘ 构建失败：result=" + report.summary.result +
                               "，错误 " + report.summary.totalErrors + " 条，详见 Console / Editor.log。");
                WriteStatus("DONE FAIL build_result=" + report.summary.result);
            }
        }

        /// <summary>检查一项 Android 工具链路径是否已配置，结果只记日志</summary>
        private static void CheckEnv(string label, string prefsKey, EditorUtil.Report report)
        {
            string path = EditorPrefs.GetString(prefsKey, "");
            if (string.IsNullOrEmpty(path) || !Directory.Exists(path))
            {
                report.Warn(label + " 路径未配置或不存在（EditorPrefs." + prefsKey + " = '" + path + "'）");
            }
            else
            {
                report.Ok(label + "：" + path);
            }
        }

        /// <summary>往状态文件追加一行（外部轮询用；失败不影响构建）</summary>
        public static void WriteStatus(string line)
        {
            try
            {
                File.AppendAllText(Path.GetFullPath(StatusFileRelative),
                    System.DateTime.Now.ToString("HH:mm:ss") + " " + line + "\n");
            }
            catch (System.Exception e)
            {
                Debug.LogWarning("[BuildApk] 状态文件写入失败：" + e.Message);
            }
        }
    }

    /// <summary>
    /// 一键完整构建流水线：热更 dll ▸ 资源包 ▸ APK。
    ///
    /// 流程（也是状态机的各个阶段）：
    ///   ① DllGenerate —— 执行「HybridCLR ▸ Generate ▸ All」
    ///      （产出热更 dll + AOT 裁剪元数据到 HybridCLRData/，且会重写
    ///        AOTGenericReferences.cs，可能触发脚本编译 / 域重载）
    ///   ② DllCopy —— 拷贝热更 dll + AOT 元数据到 StreamingAssets/HybridCLR/，
    ///      再生成 md5.txt 校验清单（首包自带 + 上传服务器用）
    ///   ③ AbBuild —— 构建资源包：
    ///      USE_YOOASSET 宏开启 → YooAsset 真实资源包（版本号自动递增）；
    ///      未开启 → 旧的 BuildPipeline.BuildAssetBundles（StreamingAssets/AssetBundles）
    ///   ④ ApkBuild —— 复用「6. 一键构建 APK」构建 APK
    ///
    /// 【为什么做成状态机而不是一个大方法】步骤 ① 会改脚本（AOTGenericReferences.cs）
    /// 触发编译甚至域重载 —— 域重载会把正在执行的方法栈直接杀掉。状态存 SessionState
    /// （域重载后仍在），由 EditorApplication.update 每帧驱动，编译完成后从断点继续。
    ///
    /// 状态文件：同 BuildApk（Library/FTBuildApkStatus.txt），每个阶段完成都会追加一行
    ///   PHASE …，供 MCP / CI 轮询。
    ///
    /// 菜单：
    ///   Tools ▸ 塔防 ▸ 7. 一键完整构建（DLL ▸ AB ▸ APK）
    /// </summary>
    [InitializeOnLoad]
    public static class BuildApkFull
    {
        /// <summary>SessionState 键：当前阶段</summary>
        private const string PhaseKey = "FTBuildApkFull.Phase";

        /// <summary>SessionState 键：本次选定的资源包版本号</summary>
        private const string VersionKey = "FTBuildApkFull.Version";

        /// <summary>
        /// YooAsset 包裹名（= AB 输出目录名）。
        /// ⚠️ 与 YooAssetResLoader.PackageName 一致；此处手写是因为该常量套在
        /// USE_YOOASSET 宏里，未开宏时引用会编译不过。
        /// </summary>
        private const string YooPackageName = "FreeTower";

        [MenuItem("Tools/塔防/7. 一键完整构建（DLL ▸ AB ▸ APK）", false, 111)]
        public static void StartMenu()
        {
            if (GetPhase() != "Idle")
            {
                Debug.LogError("[BuildFull] 已有完整构建在进行中（阶段 " + GetPhase() + "），请先等它结束。");
                return;
            }
            if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                Debug.LogError("[BuildFull] 编辑器正在编译 / 导入，请等空闲后再试。");
                return;
            }
            if (EditorApplication.isPlaying)
            {
                Debug.LogError("[BuildFull] 编辑器正在 Play 模式，请先退出。");
                return;
            }
            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                Debug.LogError("[BuildFull] 构建中止：当前构建目标是 " +
                               EditorUserBuildSettings.activeBuildTarget + "，请先切换到 Android。");
                return;
            }

            // HybridCLR 生成 AOTGenericReferences.cs 后会触发编译：先设好下一阶段再执行，
            // 这样即使域重载发生在调用过程中，流水线也能从 DllCopy 继续而不是从头再来。
            SetPhase("DllGenerate");
            BuildApk.WriteStatus("START FULL " + System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            Debug.Log("[BuildFull] 完整构建开始：DLL ▸ AB ▸ APK（状态见 Library/FTBuildApkStatus.txt）");
        }

        static BuildApkFull()
        {
            // 【InitializeOnLoad】每次域重载后重新挂上驱动器，流水线从 SessionState 断点继续。
            EditorApplication.update += Tick;
        }

        private static void Tick()
        {
            string phase = GetPhase();
            if (phase == "Idle")
            {
                return;
            }
            // 编译 / 导入中一律等待（状态机会在空闲后自动继续）
            if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                return;
            }

            switch (phase)
            {
                case "DllGenerate":
                    TickDllGenerate();
                    break;
                case "DllCopy":
                    TickDllCopy();
                    break;
                case "AbBuild":
                    TickAbBuild();
                    break;
                case "ApkBuild":
                    SetPhase("Idle");
                    BuildApk.BuildNow();
                    break;
            }
        }

        // ------------------------------------------------------------------
        // ① HybridCLR Generate/All
        // ------------------------------------------------------------------

        private static void TickDllGenerate()
        {
            // 先推进阶段再执行：Generate/All 过程中就可能触发域重载
            SetPhase("DllCopy");

            bool ok = EditorApplication.ExecuteMenuItem("HybridCLR/Generate/All");
            if (!ok)
            {
                Fail("执行「HybridCLR/Generate/All」失败：找不到该菜单（确认 HybridCLR 包已安装）。");
                return;
            }
            BuildApk.WriteStatus("PHASE dll_generate ok");
            Debug.Log("[BuildFull] ① HybridCLR Generate/All 完成。");

            // 生成产物含 .cs（AOTGenericReferences），刷新可能触发编译；下一 tick 会等它结束
            AssetDatabase.Refresh();
        }

        // ------------------------------------------------------------------
        // ② 拷贝热更 dll + 生成 md5 清单
        // ------------------------------------------------------------------

        private static void TickDllCopy()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            HybridCLRDllCopier.Copy(report);
            if (report.Errors > 0)
            {
                Fail("拷贝热更 dll 失败：\n" + report.Text);
                return;
            }

            EditorUtil.Report md5Report = new EditorUtil.Report();
            HybridCLRMd5Generator.Generate(md5Report);
            if (md5Report.Errors > 0)
            {
                Fail("生成 md5 清单失败：\n" + md5Report.Text);
                return;
            }

            Debug.Log("[BuildFull] ② 热更 dll 就位：\n" + report.Text + md5Report.Text);
            BuildApk.WriteStatus("PHASE dll ok");
            Debug.Log("[BuildFull] ② 热更 dll + md5 清单完成。");

            // StreamingAssets 新增了文件，刷新导入；.cs 不会因此变化，一般不触发编译
            AssetDatabase.Refresh();
            SetPhase("AbBuild");
        }

        // ------------------------------------------------------------------
        // ③ 构建资源包
        // ------------------------------------------------------------------

        private static void TickAbBuild()
        {
            SetPhase("ApkBuild");

            string version = NextVersion();
            SessionState.SetString(VersionKey, version);

            Debug.Log("[BuildFull] ③ 开始构建资源包，版本 " + version + " …");
#if USE_YOOASSET
            EditorUtil.Report abReport = new EditorUtil.Report();
            bool ok = FTYooAssetSetupWizard.BuildRealBundlesCore(version, false, abReport);
            if (!ok)
            {
                Fail("YooAsset 资源包构建失败：\n" + abReport.Text);
                return;
            }
            BootReleaseBuilder.Publish(version, "Library/FT_HotUpdate/apk-baseline", true);
            Debug.Log("[BuildFull] ③ YooAsset 资源包构建成功：\n" + abReport.Text);
            BuildApk.WriteStatus("PHASE ab ok version=" + version + " (yooasset)");
#else
            // 旧链路（未开 USE_YOOASSET）：BuildPipeline.BuildAssetBundles，
            // 产物进 StreamingAssets/AssetBundles/<平台>/，自检与日志在 BuildAssetBundles 内部。
            BuildAssetBundles.Build();
            string manifestFile = System.IO.Path.Combine(
                FTProject.ResPathUtil.BuildOutputRoot, FTProject.ResPathUtil.ManifestBundleName);
            if (!File.Exists(manifestFile))
            {
                Fail("旧链路 AB 构建后找不到主清单：" + manifestFile + "（详情见上方日志）");
                return;
            }
            BuildApk.WriteStatus("PHASE ab ok (legacy)");
            Debug.Log("[BuildFull] ③ 旧链路 AssetBundle 构建成功。");
#endif
        }

        /// <summary>
        /// 自动选下一个资源包版本号：扫 Bundles/&lt;平台&gt;/&lt;包裹&gt;/ 下已有的
        /// "x.y.z" 目录，取最大版本把 patch 位 +1；没有任何历史版本则从 1.0.0 起。
        /// </summary>
        private static string NextVersion()
        {
            string root = Path.Combine("Bundles",
                EditorUserBuildSettings.activeBuildTarget.ToString(), YooPackageName);
            string fullRoot = Path.GetFullPath(root);

            int major = 1, minor = 0, patch = -1;
            if (Directory.Exists(fullRoot))
            {
                foreach (string dir in Directory.GetDirectories(fullRoot))
                {
                    string name = Path.GetFileName(dir);
                    string[] parts = name.Split('.');
                    if (parts.Length != 3) continue;
                    int a, b, c;
                    if (!int.TryParse(parts[0], out a) || !int.TryParse(parts[1], out b)
                        || !int.TryParse(parts[2], out c)) continue;
                    if (a > major || (a == major && (b > minor || (b == minor && c > patch))))
                    {
                        major = a; minor = b; patch = c;
                    }
                }
            }

            if (patch < 0)
            {
                return "1.0.0";
            }
            return major + "." + minor + "." + (patch + 1);
        }

        // ------------------------------------------------------------------
        // 通用
        // ------------------------------------------------------------------

        private static void Fail(string message)
        {
            SetPhase("Idle");
            Debug.LogError("[BuildFull] ✘ 完整构建失败：" + message);
            BuildApk.WriteStatus("DONE FAIL full_pipeline");
        }

        private static string GetPhase()
        {
            return SessionState.GetString(PhaseKey, "Idle");
        }

        private static void SetPhase(string phase)
        {
            SessionState.SetString(PhaseKey, phase);
        }
    }
}

using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 打包 AssetBundle（P0-3）。
    ///
    /// 流程：
    ///   ① 检查配置表是否已导出且**能按 TextAsset 读取**（读不到就直接中止）
    ///   ② 按 ResTable 打 AB 标记（唯一数据源，见 ABNameSetter）
    ///   ③ BuildPipeline 构建到 Assets/StreamingAssets/AssetBundles/&lt;平台&gt;/
    ///      【为什么产物放 StreamingAssets】它随包体一起发出、能按平台分目录，
    ///      运行时用 Application.streamingAssetsPath 统一寻址。
    ///      （注意：这是"产物目录"，与"源数据目录" Assets/ConfigJson 不同，
    ///        后者是普通 Assets 目录，会被打进 config 包。）
    ///   ④ 自检：主清单是否存在、每个预期的包是否都产出了
    ///
    /// 菜单：
    ///   Tools ▸ 塔防 ▸ 5. 打包 AssetBundle
    ///   Tools ▸ 塔防 ▸ 高级（单步重建）▸ 5b. 严格模式打包（引用缺失即失败）
    /// </summary>
    public static class BuildAssetBundles
    {
        /// <summary>配置表源数据目录（Luban 的 --output_data_dir）</summary>
        public const string ConfigDir = "Assets/ConfigJson";

        [MenuItem("Tools/塔防/5. 打包 AssetBundle", false, 105)]
        public static void Build()
        {
            BuildInternal(false);
        }

        [MenuItem("Tools/塔防/高级（单步重建）/5b. 严格模式打包（引用缺失即失败）", false, 311)]
        public static void BuildStrict()
        {
            BuildInternal(true);
        }

        private static void BuildInternal(bool strict)
        {
            EditorUtil.Report report = new EditorUtil.Report();

            // ① 先确认配置表已导出（缺了就没必要往下走）
            if (!CheckConfigReady(report))
            {
                Debug.LogError("[M0] 打包中止：配置表未就绪。\n" + report.Text);
                return;
            }

            // ② 打标（同时会校验 ResTable 里登记的资源是否都存在）
            ABNameSetter.Apply(report);
            if (report.Errors > 0)
            {
                Debug.LogError("[M0] 打包中止：ResTable 里有资源不存在。请先执行「Tools ▸ 塔防 ▸ 一键补齐 M0 资源」。\n" + report.Text);
                return;
            }

            // ③ 构建
            string outputDir = ResPathUtil.BuildOutputRoot;
            Directory.CreateDirectory(outputDir);

            BuildAssetBundleOptions options =
                BuildAssetBundleOptions.ChunkBasedCompression |   // LZ4：兼顾压缩率与随机读取
                BuildAssetBundleOptions.UseContentHash;           // 用内容算 hash，构建结果可复现
            // 【命名坑】这个枚举里**没有** `Deterministic` 这个成员（会报 CS0117）。
            // 它历史上叫 `DeterministicAssetBundle`（已废弃），
            // Unity 2022.2+ 的正式写法是 `UseContentHash`。
            if (strict)
            {
                options |= BuildAssetBundleOptions.StrictMode;    // 引用缺失直接失败
            }

            report.Head("构建 AssetBundle → " + outputDir);
            report.Ok("平台目录：" + ResPathUtil.PlatformFolder +
                      "（构建目标 " + EditorUserBuildSettings.activeBuildTarget + "）");

            AssetBundleManifest manifest = BuildPipeline.BuildAssetBundles(
                outputDir, options, EditorUserBuildSettings.activeBuildTarget);

            if (manifest == null)
            {
                report.Error("BuildPipeline 返回 null，打包失败。请查看 Console 上方的详细错误。");
                Debug.LogError("[M0] AssetBundle 打包失败：\n" + report.Text);
                return;
            }

            // ④ 自检
            string[] built = manifest.GetAllAssetBundles();
            report.Ok(string.Format("成功产出 {0} 个包：", built.Length));
            long totalBytes = 0;
            for (int i = 0; i < built.Length; i++)
            {
                string file = Path.Combine(outputDir, built[i]);
                long size = File.Exists(file) ? new FileInfo(file).Length : 0;
                totalBytes += size;
                report.Ok(string.Format("  · {0,-16} {1,8:F1} KB", built[i], size / 1024f));
            }
            report.Ok(string.Format("合计 {0:F1} KB（含主清单）", totalBytes / 1024f));

            // 每个预期包都必须产出，否则运行时必然报"资源不可用"
            for (int i = 0; i < ResBundle.All.Length; i++)
            {
                bool found = false;
                for (int j = 0; j < built.Length; j++)
                {
                    if (built[j] == ResBundle.All[i])
                    {
                        found = true;
                        break;
                    }
                }
                if (!found)
                {
                    report.Warn(string.Format("预期包「{0}」未产出 —— " +
                        "多半是 ResTable 里该包下的资源都没能打上标", ResBundle.All[i]));
                }
            }

            string manifestFile = Path.Combine(outputDir, ResPathUtil.ManifestBundleName);
            if (!File.Exists(manifestFile))
            {
                report.Error("主清单包缺失：" + manifestFile +
                             "\n  BundleResLoader 启动时会读它，缺了会直接初始化失败");
            }
            else
            {
                report.Ok("主清单包就绪：" + ResPathUtil.ManifestBundleName);
            }

            AssetDatabase.Refresh();
            Debug.Log(report.Errors > 0
                ? "[M0] AssetBundle 打包有错误：\n" + report.Text
                : "[M0] AssetBundle 打包完成：\n" + report.Text);
        }

        // ------------------------------------------------------------------
        // 配置表就绪检查
        // ------------------------------------------------------------------

        /// <summary>
        /// 确认配置表 JSON 已导出、且**能被当作 TextAsset 加载**。
        ///
        /// 【为什么要专门查"能当 TextAsset 加载"】这是踩过的坑：
        /// StreamingAssets 下的文件会被 Unity 当作"原始文件"（DefaultAsset）处理，
        /// 于是 `LoadAssetAtPath&lt;Object&gt;()` 拿得到（自检会误判为"存在"），
        /// 但 `LoadAssetAtPath&lt;TextAsset&gt;()` 返回 null，读配置直接失败。
        /// 所以这里用 TextAsset 类型去查，才能真实反映运行时能否读到内容。
        /// </summary>
        public static bool CheckConfigReady(EditorUtil.Report report)
        {
            report.Head("检查配置表是否已导出");

            List<string> missing = new List<string>();
            int ok = 0;
            foreach (System.Collections.Generic.KeyValuePair<string, ResAddress> kv in ResTable.All)
            {
                ResAddress addr = kv.Value;
                if (addr.Bundle != ResBundle.Config)
                {
                    continue;
                }
                if (AssetDatabase.LoadAssetAtPath<TextAsset>(addr.EditorPath) == null)
                {
                    missing.Add(string.Format("      逻辑名「{0}」→ {1}", kv.Key, addr.EditorPath));
                }
                else
                {
                    ok++;
                }
            }

            if (missing.Count > 0)
            {
                report.Error(string.Format(
                    "有 {0} 张配置表读不到内容（不是有效 TextAsset）：\n{1}\n" +
                    "      修复：执行 Luban/gen_code_json.bat 重新导出（输出目录为 Assets/ConfigJson）",
                    missing.Count, string.Join("\n", missing.ToArray())));
                return false;
            }

            report.Ok(string.Format("{0} 张配置表就绪，且都能按 TextAsset 读取", ok));
            return true;
        }
    }
}

using System.Collections.Generic;
using System.Text;
using TMPro;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// Editor 工具共用方法。
    /// 集中放这里的原因：几个脚本都要"确保目录存在""取默认字体""设 Sprite 导入参数"，
    /// 复制多份迟早会分叉（尤其是 Sprite 导入参数，分叉会导致图集批次不一致）。
    /// </summary>
    public static class EditorUtil
    {
        /// <summary>所有程序生成的占位美术都放这里</summary>
        public const string GeneratedArtDir = "Assets/Art/Generated";

        /// <summary>M0 统一使用的每单位像素数（与现有美术一致）</summary>
        public const float DefaultPPU = 100f;

        // ------------------------------------------------------------------
        // 目录
        // ------------------------------------------------------------------

        /// <summary>确保资源目录存在（会递归创建父级）</summary>
        public static void EnsureFolder(string assetFolder)
        {
            if (string.IsNullOrEmpty(assetFolder) || AssetDatabase.IsValidFolder(assetFolder))
            {
                return;
            }
            string[] parts = assetFolder.Split('/');
            string cur = parts[0];   // "Assets"
            for (int i = 1; i < parts.Length; i++)
            {
                string next = cur + "/" + parts[i];
                if (!AssetDatabase.IsValidFolder(next))
                {
                    AssetDatabase.CreateFolder(cur, parts[i]);
                }
                cur = next;
            }
        }

        /// <summary>确保某个文件所在的目录存在</summary>
        public static void EnsureFolderOfFile(string assetFilePath)
        {
            int idx = assetFilePath.LastIndexOf('/');
            if (idx > 0)
            {
                EnsureFolder(assetFilePath.Substring(0, idx));
            }
        }

        // ------------------------------------------------------------------
        // 生成器安全护栏（★ 重要）
        // ------------------------------------------------------------------

        /// <summary>
        /// 生成器的"可安全重建"判定。
        ///
        /// 【为什么需要它】本工程的 Editor 生成器一律是「DeleteAsset + 重建」，
        /// 与"人在编辑器里手工调 prefab"天然互斥 —— 跑一次向导就抹掉手工成果
        /// （真实案例：HudView 手工加的三颗塔按钮被生成器删掉）。
        ///
        /// 约定：**只允许生成器管理"它自己产出的那套节点"**。
        /// 若在 prefab 里发现生成器预期之外的一级子节点，说明有人手工加过东西，
        /// 此时**必须中止并报错**，而不是静默删除。
        /// </summary>
        /// <param name="prefabPath">预制体路径</param>
        /// <param name="expectedChildren">生成器预期会产出的直接子节点名集合</param>
        /// <param name="extra">发现的"额外节点"（逗号分隔）；无额外节点时为 null</param>
        /// <returns>true = 结构纯净，可安全重建；false = 有手工痕迹，应中止</returns>
        public static bool IsSafeToRebuild(string prefabPath, string[] expectedChildren, out string extra)
        {
            extra = null;
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            if (prefab == null)
            {
                return true;    // 不存在 → 首次生成，安全
            }

            List<string> extras = new List<string>();
            Transform root = prefab.transform;
            for (int i = 0; i < root.childCount; i++)
            {
                string childName = root.GetChild(i).name;
                bool known = false;
                for (int j = 0; j < expectedChildren.Length; j++)
                {
                    if (childName == expectedChildren[j])
                    {
                        known = true;
                        break;
                    }
                }
                if (!known)
                {
                    extras.Add(childName);
                }
            }

            if (extras.Count > 0)
            {
                extra = string.Join("、", extras.ToArray());
                return false;
            }
            return true;
        }

