using System.IO;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 【无人值守】标志文件驱动的构建触发器。
    ///
    /// 场景：Unity 编辑器（GUI）开着、但外部（脚本 / CI / 助手）需要发起一次热更构建，
    /// 而 batchmode 因工程锁不可用。此时在 `Library/FT_AUTOBUILD.trigger` 写入：
    ///   - "full"（或任意非 "dll" 内容）→ 跑完整流水线（dll ▸ 拷贝 ▸ 收集器 ▸ AB）；
    ///   - "dll"  → 仅重编热更 dll（dll-only 模式）。
    /// 编辑器在下一次域重载 / 启动后自动消费标志文件并执行对应流水线；
    /// 与菜单 9 / 9a、batchmode Start / StartDllOnly 完全同源。
    ///
    /// 【为什么挂在 [InitializeOnLoad】域重载是"编辑器检测到脚本变更"的必然副产物：
    /// 把标志文件与代码改动**一起**准备好，重载后本触发器立即接手，全流程无需人工点菜单。
    /// </summary>
    [InitializeOnLoad]
    public static class FT_AutoBuildTrigger
    {
        private const string TriggerRel = "Library/FT_AUTOBUILD.trigger";

        static FT_AutoBuildTrigger()
        {
            EditorApplication.delayCall += Check;
        }

        private static void Check()
        {
            try
            {
                string root = Path.GetDirectoryName(Application.dataPath);
                string path = Path.Combine(root, TriggerRel);
                if (!File.Exists(path))
                {
                    return;
                }

                string mode = File.ReadAllText(path).Trim().ToLowerInvariant();
                File.Delete(path);   // 先删再跑：后续域重载续跑时不会二次触发
                Debug.Log("[AutoBuild] 标志文件触发构建，mode=" + mode);

                if (mode == "dll")
                {
                    ReporterHotfixBuild.StartDllOnly();
                }
                else if (mode == "uimainmenu")
                {
                    // 只重建 MainMenuView.prefab（UI-only 改动的无人值守通道）。
                    // 【为什么不能跑 full】全量重建会覆盖 HudView 等手工改造过的 prefab，
                    // 自动化里绝不允许；主菜单 prefab 完全由生成器维护，单独重建安全。
                    UIPrefabBuilder.RebuildMainMenuOnly();
                }
                else if (mode == "monkeydir")
                {
                    // 2026-10-17 Monkey 上下方向接入：分件美术 ▸ Profile ▸ 覆盖控制器 ▸ 预制体，
                    // 完成后写 Library/FT_MONKEYDIR_STATUS.txt（无人值守验证通道）。
                    EnemyDirectionPrefabBuilder.BuildAndVerify(EnemyDirectionPrefabBuilder.Monkey);
                }
                else if (mode == "feature")
                {
                    // 2026-10-14 需求流水线：Luban ▸ GameIntroView.prefab ▸ HUD 右上角按钮
                    // ▸ TextLocalizer ▸ 交接 ReporterHotfixBuild（dll+AB）。
                    // 全程幂等、不弹窗、不重建手工 prefab，见 FT_FeatureBuild。
                    FT_FeatureBuild.Start();
                }
                else
                {
                    ReporterHotfixBuild.Start();
                }
            }
            catch (System.Exception e)
            {
                Debug.LogError("[AutoBuild] 触发器异常：" + e);
            }
        }
    }
}

using System.IO;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 【无人值守·2026-10-14 需求流水线】一键串联：
    ///   ① Luban 导出配置表（Localization.xlsx 新词条 → json + C#）
    ///   ② 生成 GameIntroView.prefab（缺失才建；已存在不碰）
    ///   ③ HudView.prefab 右上角幂等补挂 Btn_Pause / Btn_Intro（不重建、不碰其他节点）
    ///   ④ 批量挂 TextLocalizer（幂等，覆盖新 prefab 与新按钮的 Label）
    ///   ⑤ 交接给 ReporterHotfixBuild（热更 dll ▸ 拷贝+md5 ▸ 收集器 ▸ AB）
    ///
    /// 【触发方式】
    ///   · Library/FT_AUTOBUILD.trigger 写 "feature"（域重载后由 FT_AutoBuildTrigger 消费）；
    ///   · 或菜单 Tools ▸ 塔防 ▸ 自动化（无弹窗）▸ 一键：介绍弹窗+拖拽建造+HUD按钮。
    ///
    /// 【为什么做成状态机】与 ReporterHotfixBuild 同一套防身逻辑：任何阶段若被
    /// 意外的脚本编译/域重载打断，SessionState 里的阶段游标会在重载后原地重跑（幂等），
    /// 宁可多花几秒也不静默用旧产物。
    ///
    /// 【状态文件】Library/FTFeatureBuildStatus.txt：
    ///   START FEATURE → PHASE luban ok → PHASE prefab ok → DONE OK (handoff to ReporterHotfixBuild)
    ///   外部轮询到 DONE OK 后改看 Library/FTReporterBuildStatus.txt 等 DONE。
    /// </summary>
    [InitializeOnLoad]
    public static class FT_FeatureBuild
    {
        private const string PhaseKey = "FTFeatureBuild.Phase";
        private const string StatusFileRelative = "Library/FTFeatureBuildStatus.txt";

        private static string ProjectRoot
        {
            get { return Path.GetDirectoryName(Application.dataPath); }
        }

        private static string StatusFilePath
        {
            get { return Path.Combine(ProjectRoot, StatusFileRelative); }
        }

        [MenuItem("Tools/塔防/自动化（无弹窗）/一键：介绍弹窗+拖拽建造+HUD按钮（Luban▸prefab▸AB）", false, 903)]
        public static void StartFromMenu()
        {
            Start();
        }

        /// <summary>入口（菜单 / FT_AutoBuildTrigger 共用）。</summary>
        public static void Start()
        {
            string phase = GetPhase();
            if (phase != "Idle" && phase != "Done" && phase != "Fail")
            {
                Debug.LogWarning("[FeatureBuild] 已有流水线在跑（" + phase + "），忽略本次 Start。");
                return;
            }

            try { File.Delete(StatusFilePath); }
            catch (System.Exception) { }

            SetPhase("Luban");
            WriteStatus("START FEATURE " + System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            Debug.Log("[FeatureBuild] 开始：Luban ▸ GameIntro prefab ▸ HUD 右上角按钮 ▸ TextLocalizer ▸ 热更 dll+AB");
        }

        static FT_FeatureBuild()
        {
            EditorApplication.update += Tick;
        }

        private static void Tick()
        {
            string phase = GetPhase();
            if (phase == "Idle" || phase == "Done" || phase == "Fail")
            {
                return;
            }
            if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                return;
            }

            try
            {
                switch (phase)
                {
                    case "Luban": TickLuban(); break;
                    case "Prefab": TickPrefab(); break;
                    case "Hotfix": TickHotfix(); break;
                }
            }
            catch (System.Exception e)
            {
                Fail(phase + " 阶段异常：" + e);
            }
        }

        // ------------------------------------------------------------------
        // ① Luban 导出（前置：.workbuddy/tools 的脚本已把新词条写进 Localization.xlsx）
        // ------------------------------------------------------------------

        private static void TickLuban()
        {
            Debug.Log("[FeatureBuild] ① 导出配置表（Luban）…");
            EditorUtil.Report report = new EditorUtil.Report();
            if (!LubanExporter.ExportInternal(report))
            {
                Fail("① Luban 导出失败：\n" + report.Text);
                return;
            }
            SetPhase("Prefab");
            WriteStatus("PHASE luban ok");
            Debug.Log("[FeatureBuild] ① 完成。");
        }

        // ------------------------------------------------------------------
        // ② prefab：新界面（缺失才建）+ HUD 补挂 + 多语言挂载（全部幂等）
        // ------------------------------------------------------------------

        private static void TickPrefab()
        {
            Debug.Log("[FeatureBuild] ② GameIntroView.prefab + HUD 右上角按钮 + TextLocalizer …");
            EditorUtil.Report report = new EditorUtil.Report();

            // GameIntroView.prefab 缺失才生成（幂等；新界面完全由生成器维护）
            UIPrefabBuilder.EnsureGameIntroView(report);

            UIPrefabBuilder.EnsureHudTopRightButtons(report);
            LocalizationPrefabBinder.BindAll(report);

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            if (report.Errors > 0)
            {
                Fail("② prefab 阶段失败：\n" + report.Text);
                return;
            }
            Debug.Log("[FeatureBuild] ② 完成：\n" + report.Text);

            SetPhase("Hotfix");
            WriteStatus("PHASE prefab ok");
        }

        // ------------------------------------------------------------------
        // ③ 交接热更流水线（dll + AB）
        // ------------------------------------------------------------------

        private static void TickHotfix()
        {
            SetPhase("Done");
            WriteStatus("DONE OK (handoff to ReporterHotfixBuild)");
            Debug.Log("[FeatureBuild] ✔ 前置步骤全部完成，交接给 ReporterHotfixBuild（dll ▸ AB）…");
            ReporterHotfixBuild.Start();
        }

        // ------------------------------------------------------------------
        // 通用
        // ------------------------------------------------------------------

        private static void Fail(string message)
        {
            SetPhase("Fail");
            Debug.LogError("[FeatureBuild] ✘ 流水线失败：" + message);

            string oneLine = message.Replace("\r", " ").Replace("\n", " ");
            if (oneLine.Length > 160)
            {
                oneLine = oneLine.Substring(0, 160);
            }
            WriteStatus("DONE FAIL " + oneLine);
        }

        private static string GetPhase()
        {
            return SessionState.GetString(PhaseKey, "Idle");
        }

        private static void SetPhase(string phase)
        {
            SessionState.SetString(PhaseKey, phase);
        }

        private static void WriteStatus(string line)
        {
            try
            {
                File.AppendAllText(StatusFilePath,
                    System.DateTime.Now.ToString("HH:mm:ss") + " " + line + "\n");
            }
            catch (System.Exception e)
            {
                Debug.LogWarning("[FeatureBuild] 状态文件写入失败：" + e.Message);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using FTProject.AOT;
using System.Net;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>一条"要部署/要上传"的文件记录。</summary>
    public class HotUpdatePlanFile
    {
        /// <summary>本机绝对路径（dll 侧通常是 StreamingAssets/HybridCLR/…）。</summary>
        public string SourcePath;

        /// <summary>相对服务器根的路径：releases/{id}/… 或最后激活的 release.json。</summary>
        public string RelativePath;

        public long Size;
        public string Md5;

        /// <summary>true = 不可变 release 的 HybridCLR/ 下热更 DLL 与校验清单。</summary>
        public bool IsDll;
    }

    /// <summary>一次热更的完整产物清单（AB + dll + 清单自身）。</summary>
    public class HotUpdatePlan
    {
        public string Version;
        public string Platform;
        public string BuildDir;
        public List<HotUpdatePlanFile> Files = new List<HotUpdatePlanFile>();
        public string ManifestPath;
        public long TotalBytes;
        public int BundleCount;
        public int DllCount;

        public string Describe()
        {
            return string.Format("版本 {0} · {1} 个 AB 文件 · {2} 个 dll/清单 · 合计 {3}",
                Version, BundleCount, DllCount, HotUpdateFileUtil.FormatSize(TotalBytes));
        }
    }

    /// <summary>校验结果（失败项要能直接贴到群里排查，所以保留前若干条原文）。</summary>
    public class HotUpdateVerifyResult
    {
        public int Checked;
        public readonly List<string> Failures = new List<string>();
        public readonly List<string> Warnings = new List<string>();

        public bool Ok { get { return Failures.Count == 0; } }

        public string Describe()
        {
            string text = string.Format("校验 {0} 项：失败 {1} · 警告 {2}", Checked, Failures.Count, Warnings.Count);
            if (Failures.Count > 0)
            {
                int show = Math.Min(Failures.Count, 12);
                text += "\n失败明细：\n  · " + string.Join("\n  · ", Failures.GetRange(0, show).ToArray());
                if (Failures.Count > show)
                {
                    text += string.Format("\n  …（还有 {0} 条）", Failures.Count - show);
                }
            }
            if (Warnings.Count > 0)
            {
                int show = Math.Min(Warnings.Count, 8);
                text += "\n警告：\n  · " + string.Join("\n  · ", Warnings.GetRange(0, show).ToArray());
                if (Warnings.Count > show)
                {
                    text += string.Format("\n  …（还有 {0} 条）", Warnings.Count - show);
                }
            }
            return text;
        }
    }

    /// <summary>落盘的热更清单（服务器根 hotupdate_manifest.json，客户端不读，人/CI 读）。</summary>
    [Serializable]
    public class HotUpdateManifestDto
    {
        public string version;
        public string platform;
        public string package;
        public string builtAt;
        public string note;
        public long totalBytes;
        public HotUpdateFileEntryDto[] files;
    }

    [Serializable]
    public class HotUpdateFileEntryDto
    {
        public string path;
        public long size;
        public string md5;
    }

    /// <summary>
    /// Publish immutable releases/{id}/ payloads and activate release.json last.
    /// HTTP validation downloads and hashes the real served bytes, including extensionless bundles.
    /// </summary>
    public static class HotUpdateDeployer
    {
        private const string Md5ListName = "md5.txt";

        // ==================================================================
        // 清单生成
        // ==================================================================

        /// <summary>
        /// 从「AB 构建输出 + 随包 dll」生成部署清单。
        /// 只收客户端真的会请求的文件；`.report` / `link.xml` / `.meta` 一律跳过。
        /// </summary>
        public static HotUpdatePlan BuildPlan(string version, string buildDir, string dllDir,
            string platform, EditorUtil.Report report)
        {
            try
            {
                string stage = Path.Combine("Library", "FTBootReleaseStage", version);
                BootReleaseBuilder.Publish(version, stage, false);
                return PlanForRelease(stage, platform, report);
            }
            catch (Exception e)
            {
                report.Error("Release staging failed: " + e.Message);
                return new HotUpdatePlan { Version = version, Platform = platform };
            }
        }

        public static HotUpdatePlan BuildPlanFromCdn(string version, string cdnRoot, string dllDir,
            string platform, EditorUtil.Report report)
        {
            try { return PlanForRelease(cdnRoot, platform, report); }
            catch (Exception e)
            {
                report.Error("No complete release descriptor: " + e.Message);
                return new HotUpdatePlan { Version = version, Platform = platform };
            }
        }

        private static HotUpdatePlan PlanForRelease(string root, string platform, EditorUtil.Report report)
        {
            string pointer = Path.Combine(root, "release.json");
            var release = JsonUtility.FromJson<BootRelease>(File.ReadAllText(pointer));
            if (!BootReleaseStore.Valid(release)) throw new IOException("Invalid release.json");
            var plan = new HotUpdatePlan { Version = release.resourceVersion, Platform = platform, BuildDir = root };
            string payload = Path.Combine(root, release.contentRoot);
            var inventory = JsonUtility.FromJson<HotUpdateManifestDto>(File.ReadAllText(Path.Combine(payload, "payloads.json")));
            if (inventory == null || inventory.files == null || inventory.version != release.resourceVersion)
                throw new IOException("Release inventory missing or invalid");
            foreach (var entry in inventory.files)
            {
                if (string.IsNullOrEmpty(entry.path) || entry.path.Contains("..") || entry.path.Contains(":") || entry.path.StartsWith("/"))
                    throw new IOException("Invalid inventory path");
                string path = Path.Combine(payload, entry.path);
                if (!File.Exists(path) || new FileInfo(path).Length != entry.size || HotUpdateFileUtil.Md5(path) != entry.md5)
                    throw new IOException("Inventory checksum mismatch: " + entry.path);
                string relative = release.contentRoot + "/" + entry.path;
                AddFile(plan, path, relative, relative.Contains("/HybridCLR/"), report);
            }
            foreach (var dll in release.dlls)
                if (!BootReleaseStore.Matches(Path.Combine(payload, "HybridCLR", dll.name), dll.md5))
                    throw new IOException("Release DLL missing or checksum mismatch: " + dll.name);
            if (!BootReleaseStore.Matches(Path.Combine(payload, "FreeTower_" + release.resourceVersion + ".bytes"), release.manifestMd5))
                throw new IOException("Release manifest checksum mismatch");
            AddFile(plan, Path.Combine(payload, "payloads.json"), release.contentRoot + "/payloads.json", false, report);
            AddFile(plan, Path.Combine(payload, "release.json"), release.contentRoot + "/release.json", false, report);
            // The only mutable activation pointer is always the last operation.
            AddFile(plan, pointer, "release.json", false, report);
            report.Ok(plan.Describe());
            return plan;
        }

        private static void AddFile(HotUpdatePlan plan, string fullPath, string relative, bool isDll,
            EditorUtil.Report report)
        {
            try
            {
                FileInfo info = new FileInfo(fullPath);
                HotUpdatePlanFile file = new HotUpdatePlanFile();
                file.SourcePath = fullPath;
                file.RelativePath = relative.Replace('\\', '/');
                file.Size = info.Length;
                file.Md5 = HotUpdateFileUtil.Md5(fullPath);
                file.IsDll = isDll;
                plan.Files.Add(file);
                plan.TotalBytes += file.Size;
                if (isDll)
                {
                    plan.DllCount++;
                }
                else
                {
                    plan.BundleCount++;
                }
            }
            catch (Exception e)
            {
                report.Error("读取文件失败 " + fullPath + "：" + e.Message);
            }
        }

        /// <summary>写清单 JSON（服务器根 + 本机历史各一份）。</summary>
        public static bool WriteManifest(HotUpdatePlan plan, string outputPath, string note, EditorUtil.Report report)
        {
            try
            {
                HotUpdateManifestDto dto = new HotUpdateManifestDto();
                dto.version = plan.Version;
                dto.platform = plan.Platform;
                dto.package = HotUpdatePaths.PackageName;
                dto.builtAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                dto.note = note;
                dto.totalBytes = plan.TotalBytes;

                dto.files = new HotUpdateFileEntryDto[plan.Files.Count];
                for (int i = 0; i < plan.Files.Count; i++)
                {
                    HotUpdateFileEntryDto entry = new HotUpdateFileEntryDto();
                    entry.path = plan.Files[i].RelativePath;
                    entry.size = plan.Files[i].Size;
                    entry.md5 = plan.Files[i].Md5;
                    dto.files[i] = entry;
                }

                string json = JsonUtility.ToJson(dto, true);
                HotUpdateFileUtil.WriteText(outputPath, json);
                plan.ManifestPath = outputPath;
                report.Ok("清单已写入：" + outputPath);
                return true;
            }
            catch (Exception e)
            {
                report.Error("写清单失败：" + e.Message);
                return false;
            }
        }

        // ==================================================================
        // 本地部署
        // ==================================================================

        /// <summary>Copy immutable payloads with MD5 checks, then atomically replace release.json.
        /// No legacy flat paths or StreamingAssets junctions are written.</summary>
        public static bool DeployLocal(HotUpdatePlan plan, string cdnRoot, EditorUtil.Report report)
        {
            try
            {
                if (!plan.Files.Any(x => x.RelativePath == "release.json")) throw new IOException("Activation descriptor missing");
                foreach (var file in plan.Files.OrderBy(x => x.RelativePath == "release.json"))
                {
                    string target = Path.Combine(cdnRoot, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
                    Directory.CreateDirectory(Path.GetDirectoryName(target));
                    if (IsSamePath(file.SourcePath, target)) continue;
                    if (file.RelativePath != "release.json" && File.Exists(target))
                    {
                        if (HotUpdateFileUtil.Md5(target) != file.Md5) throw new IOException("Immutable collision: " + file.RelativePath);
                        continue;
                    }
                    File.Copy(file.SourcePath, target + ".tmp", true);
                    if (HotUpdateFileUtil.Md5(target + ".tmp") != file.Md5) throw new IOException("Copy checksum: " + file.RelativePath);
                    BootReleaseStore.AtomicMove(target + ".tmp", target);
                }
                HotUpdateFileUtil.WriteText(Path.Combine(HotUpdatePaths.StateDir, "last_version.txt"), plan.Version);
                report.Ok("Immutable payloads verified; release.json activated last. " + plan.Describe());
                return true;
            }
            catch (Exception e) { report.Error("Local deployment failed: " + e.Message); return false; }
        }

        private static bool IsSamePath(string a, string b)
        {
            try
            {
                return string.Equals(Path.GetFullPath(a), Path.GetFullPath(b), StringComparison.OrdinalIgnoreCase);
            }
            catch (Exception)
            {
                return false;
            }
        }

        // ==================================================================
        // 远端上传（HTTP PUT）
        // ==================================================================

        /// <summary>
        /// 把清单里的全部文件 + 清单自身 PUT 到远端根地址。**阻塞**调用（由流水线放到后台线程）。
        /// 任一个文件失败即中断（避免半套资源上线 → 客户端下载到一半版本）。
        /// </summary>
        /// <param name="progress">(已处理, 总数) 回调，线程安全由调用方保证（只写 volatile 计数）</param>
        public static bool UploadAll(HotUpdatePlan plan, string baseUrl, string header,
            Action<int, int> progress, out string error)
        {
            error = null;
            if (string.IsNullOrEmpty(baseUrl))
            {
                error = "远端地址为空。";
                return false;
            }

            baseUrl = baseUrl.TrimEnd('/');
            if (!baseUrl.StartsWith("http://", StringComparison.OrdinalIgnoreCase)
                && !baseUrl.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            {
                error = "远端地址必须以 http:// 或 https:// 开头：" + baseUrl;
                return false;
            }

            List<HotUpdatePlanFile> all = new List<HotUpdatePlanFile>(plan.Files.Where(x => x.RelativePath != "release.json"));
            if (!string.IsNullOrEmpty(plan.ManifestPath) && File.Exists(plan.ManifestPath))
            {
                HotUpdatePlanFile manifest = new HotUpdatePlanFile();
                manifest.SourcePath = plan.ManifestPath;
                manifest.RelativePath = HotUpdatePaths.ManifestFileName;
                manifest.Size = new FileInfo(plan.ManifestPath).Length;
                manifest.Md5 = HotUpdateFileUtil.Md5(plan.ManifestPath);
                all.Add(manifest);
            }

            var pointer = plan.Files.FirstOrDefault(x => x.RelativePath == "release.json");
            if (pointer == null) { error = "Activation descriptor missing"; return false; }
            all.Add(pointer);
            int total = all.Count;
            for (int i = 0; i < total; i++)
            {
                HotUpdatePlanFile file = all[i];
                string url = baseUrl + "/" + file.RelativePath;
                string fileError;
                if (!PutFile(url, file.SourcePath, header, out fileError))
                {
                    error = string.Format("上传失败（{0}/{1}）{2}\n  {3}", i + 1, total, file.RelativePath, fileError);
                    return false;
                }
                if (!VerifyHttpFile(file, baseUrl, out fileError))
                {
                    error = "HTTP content verification failed: " + file.RelativePath + " " + fileError;
                    return false;
                }
                if (progress != null) progress(i + 1, total);
            }

            return true;
        }

        private static bool PutFile(string url, string localPath, string header, out string error)
        {
            error = null;
            try
            {
                FileInfo info = new FileInfo(localPath);
                HttpWebRequest request = CreateRequest(url, "PUT");
                request.ContentType = "application/octet-stream";
                request.ContentLength = info.Length;
                ApplyHeader(request, header);

                using (Stream requestStream = request.GetRequestStream())
                using (FileStream fileStream = new FileStream(localPath, FileMode.Open, FileAccess.Read, FileShare.Read))
                {
                    byte[] buffer = new byte[128 * 1024];
                    int read;
                    while ((read = fileStream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        requestStream.Write(buffer, 0, read);
                    }
                }

                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                {
                    int code = (int)response.StatusCode;
                    if (code == 200 || code == 201 || code == 202 || code == 204)
                    {
                        return true;
                    }
                    error = "服务器返回 HTTP " + code;
                    return false;
                }
            }
            catch (WebException e)
            {
                error = DescribeWebException(e);
                if (e.Response is HttpWebResponse)
                {
                    HttpWebResponse resp = (HttpWebResponse)e.Response;
                    if ((int)resp.StatusCode == 405)
                    {
                        error += "（服务器不支持 PUT：请改用本地部署，或换成对象存储/CI 上传通道）";
                    }
                }
                return false;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private static void ApplyHeader(HttpWebRequest request, string header)
        {
            if (string.IsNullOrEmpty(header))
            {
                return;
            }
            int colon = header.IndexOf(':');
            if (colon <= 0)
            {
                return;
            }
            string name = header.Substring(0, colon).Trim();
            string value = header.Substring(colon + 1).Trim();
            if (name.Length == 0)
            {
                return;
            }
            try
            {
                request.Headers[name] = value;
            }
            catch (Exception)
            {
                // 受限头（如 Content-Type）走属性设置；这里静默忽略即可，别让上传因此失败
            }
        }

        // ==================================================================
        // 校验 ①：本地文件完整性
        // ==================================================================

        /// <summary>
        /// 校验"服务器目录里的东西确实是这一版、且和构建产物一模一样"。
        /// 校验对象 = 清单里的每个文件（存在 + 大小 + MD5 一致）。
        /// </summary>
        public static void VerifyLocalFiles(HotUpdatePlan plan, string cdnRoot, bool deployedLocally,
            HotUpdateVerifyResult result)
        {
            foreach (var file in plan.Files)
            {
                string path = deployedLocally ? Path.Combine(cdnRoot, file.RelativePath) : file.SourcePath;
                result.Checked++;
                if (!File.Exists(path) || new FileInfo(path).Length != file.Size || HotUpdateFileUtil.Md5(path) != file.Md5)
                    result.Failures.Add("Payload missing or checksum mismatch: " + file.RelativePath);
            }
        }

        // ==================================================================
        // 校验 ②：HTTP 链路（与客户端同一条请求路径）
        // ==================================================================

        /// <summary>
        /// GET every descriptor, manifest, DLL and bundle through the real HTTP path and compare MD5.
        /// 阻塞调用（由流水线放到后台线程），不碰任何 Unity API。
        /// </summary>
        public static void VerifyHttp(HotUpdatePlan plan, string baseUrl,
            Action<int, int> progress, HotUpdateVerifyResult result)
        {
            int done = 0;
            foreach (var file in plan.Files)
            {
                result.Checked++;
                if (!VerifyHttpFile(file, baseUrl.TrimEnd('/'), out string error))
                    result.Failures.Add("GET " + file.RelativePath + ": " + error);
                progress?.Invoke(++done, plan.Files.Count);
            }
        }

        private static bool VerifyHttpFile(HotUpdatePlanFile file, string baseUrl, out string error)
        {
            error = null;
            try
            {
                var request = CreateRequest(baseUrl.TrimEnd('/') + "/" + file.RelativePath + "?verify=" + DateTime.UtcNow.Ticks, "GET");
                using (var response = (HttpWebResponse)request.GetResponse())
                using (var stream = response.GetResponseStream())
                using (var md5 = System.Security.Cryptography.MD5.Create())
                {
                    string hash = BitConverter.ToString(md5.ComputeHash(stream)).Replace("-", "").ToLowerInvariant();
                    if (hash != file.Md5) { error = "MD5 mismatch: " + hash + " expected " + file.Md5; return false; }
                }
                return true;
            }
            catch (Exception e) { error = e.Message; return false; }
        }

        /// <summary>探测某个地址上的版本号（用于"端口被别的服务占着"时判断能不能复用）。</summary>
        public static bool TryGetRemoteVersion(string baseUrl, out string version, out string error)
        {
            version = "";
            string body;
            if (TryGetText(baseUrl.TrimEnd('/') + "/release.json", out body, out error))
            {
                var release = JsonUtility.FromJson<BootRelease>(body);
                if (release != null && !string.IsNullOrEmpty(release.resourceVersion)) { version = release.resourceVersion; return true; }
            }
            if (!TryGetText(baseUrl.TrimEnd('/') + "/" + HotUpdatePaths.VersionFileName, out body, out error)) return false;
            version = body.Trim();
            return true;
        }

        private static bool TryGetText(string url, out string body, out string error)
        {
            body = "";
            error = null;
            try
            {
                HttpWebRequest request = CreateRequest(url, "GET");
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                using (StreamReader reader = new StreamReader(response.GetResponseStream(), Encoding.UTF8))
                {
                    body = reader.ReadToEnd();
                }
                return true;
            }
            catch (WebException e)
            {
                error = DescribeWebException(e);
                return false;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private static HttpWebRequest CreateRequest(string url, string method)
        {
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = method;
            // ★ 必须绕开系统代理：本机 Clash/TUN 会把 127.0.0.1 请求劫持成 502
            request.Proxy = null;
            request.Timeout = 8000;
            request.ReadWriteTimeout = 15000;
            request.KeepAlive = false;
            request.AllowAutoRedirect = true;
            request.UserAgent = "FT-HotUpdate-Verify/1.0";
            return request;
        }

        private static string DescribeWebException(WebException e)
        {
            if (e.Response is HttpWebResponse)
            {
                HttpWebResponse resp = (HttpWebResponse)e.Response;
                return string.Format("HTTP {0} {1}", (int)resp.StatusCode, resp.StatusDescription);
            }
            return e.Status + "：" + e.Message;
        }
    }
}

using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 编辑器内的**本地热更静态服务器**（HTTP/1.1，GET/HEAD），把 HotUpdateServer/ 根目录
    /// 按客户端真实请求路径发布出来，用于"一键热更"的最后一步本地运行验证。
    ///
    /// ==================================================================
    /// 【为什么不用 HttpListener】
    ///   ① Windows 上 HttpListener 需要 URL ACL（非管理员常直接 AccessDenied），
    ///      而这里的端口会随用户配置变化，不可能每次去 netsh 加规则；
    ///   ② 它在 Mono/Unity 里的行为随平台差异较大，出错信息也很难懂。
    ///   直接 TcpListener 手写最小 HTTP 反而稳定、零依赖、错误信息可控。
    ///
    /// 【为什么不用现成的 hotupdate_server.py】
    ///   那个脚本要另外开终端（派生进程在 Windows 上无法常驻），而且它顺带做 UDP 广播，
    ///   在编辑器里跑验证只需要 HTTP。本类只服务"验证"这一个场景；
    ///   真机联调仍然用 python 脚本（它负责 UDP 自动发现，本类不替代它）。
    ///
    /// 【只绑 127.0.0.1】
    ///   验证是编辑器自己发请求，绑回环即可（也避开防火墙弹窗）。
    ///   模拟器访问宿主机走 10.0.2.2 → 映射到宿主机回环，同样可用。
    ///   真机（局域网 IP）请用 python 脚本，它绑 0.0.0.0。
    ///
    /// 【验证用的请求不走系统代理】
    ///   本机 Clash/TUN 会把 127.0.0.1 的请求劫持到代理并返回 502，
    ///   校验器（HotUpdateDeployer）里所有 HttpWebRequest 都显式 `Proxy = null`。
    /// ==================================================================
    /// </summary>
    [InitializeOnLoad]
    public static class HotUpdateLocalServer
    {
        private static TcpListener _listener;
        private static Thread _thread;
        private static volatile bool _running;
        private static string _root;
        private static int _port;
        private static long _served;
        private static string _lastError;

        /// <summary>是否正在服务。</summary>
        public static bool IsRunning { get { return _running; } }

        public static int Port { get { return _port; } }

        public static string Root { get { return _root; } }

        /// <summary>服务地址（未启动时按当前端口给出"预期地址"，供探测失败信息使用）。</summary>
        public static string Url
        {
            get { return "http://127.0.0.1:" + (_port > 0 ? _port : HotUpdateSettings.VerifyPort); }
        }

        /// <summary>已受理的请求数（面板显示"已服务 N 个请求"）。</summary>
        public static long ServedCount { get { return Interlocked.Read(ref _served); } }

        public static string LastError { get { return _lastError; } }

        static HotUpdateLocalServer()
        {
            // 域重载 / 退出编辑器时收掉后台线程，避免线程拿着已卸载的代码继续跑。
            AssemblyReloadEvents.beforeAssemblyReload += Stop;
            EditorApplication.quitting += Stop;
        }

        /// <summary>
        /// 启动（幂等：同 root + 同端口时直接返回 true）。
        /// </summary>
        /// <param name="root">要发布的本地目录（一般是 HotUpdateServer）</param>
        /// <param name="port">端口（被占用时返回 false，并把系统错误放进 error）</param>
        public static bool Start(string root, int port, out string error)
        {
            bool ignored;
            return Start(root, port, out ignored, out error);
        }

        /// <summary>
        /// 启动（带"本次是否真的新起了服务"的返回值）。
        /// 【为什么需要 startedNow】流水线在收尾时只应停掉**自己起的**服务：
        /// 用户可能早就用菜单 10c 起着服务在真机上联调，流水线跑完把它关掉很讨人厌。
        /// </summary>
        public static bool Start(string root, int port, out bool startedNow, out string error)
        {
            error = null;
            startedNow = false;
            if (string.IsNullOrEmpty(root) || !Directory.Exists(root))
            {
                error = "要发布的目录不存在：" + root;
                return false;
            }

            if (_running && _port == port
                && string.Equals(_root, Path.GetFullPath(root), StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            Stop();

            try
            {
                TcpListener listener = new TcpListener(IPAddress.Loopback, port);
                listener.Start();

                _listener = listener;
                _root = Path.GetFullPath(root);
                _port = port;
                _served = 0;
                _lastError = null;
                _running = true;

                _thread = new Thread(AcceptLoop);
                _thread.IsBackground = true;
                _thread.Name = "FT-HotUpdateHttp";
                _thread.Start();

                Debug.Log("[HotUpdate] 本地热更服务器已启动：" + Url + " → " + _root);
                startedNow = true;
                return true;
            }
            catch (Exception e)
            {
                _running = false;
                _listener = null;
                _lastError = e.Message;
                error = e.Message;
                startedNow = false;
                return false;
            }
        }

        /// <summary>停止服务（幂等）。</summary>
        public static void Stop()
        {
            _running = false;
            try
            {
                if (_listener != null)
                {
                    _listener.Stop();
                }
            }
            catch (Exception)
            {
            }
            _listener = null;
            _thread = null;
        }

        // ------------------------------------------------------------------
        // 受理循环
        // ------------------------------------------------------------------

        private static void AcceptLoop()
        {
            while (_running)
            {
                TcpClient client = null;
                try
                {
                    client = _listener.AcceptTcpClient();
                }
                catch (Exception)
                {
                    // Stop() 会让 AcceptTcpClient 抛异常，属于正常退出路径
                    break;
                }

                try
                {
                    HandleClient(client);
                }
                catch (Exception e)
                {
                    _lastError = e.Message;
                }
                finally
                {
                    try { client.Close(); }
                    catch (Exception) { }
                }
            }
        }

        private static void HandleClient(TcpClient client)
        {
            client.ReceiveTimeout = 5000;
            NetworkStream stream = client.GetStream();

            string header = ReadHeader(stream);
            if (string.IsNullOrEmpty(header))
            {
                return;
            }

            string[] lines = header.Split(new[] { "\r\n" }, StringSplitOptions.None);
            string[] first = lines[0].Split(' ');
            if (first.Length < 3)
            {
                WriteText(stream, 400, "Bad Request", "请求行格式不对");
                return;
            }

            string method = first[0].ToUpperInvariant();
            if (method != "GET" && method != "HEAD")
            {
                WriteText(stream, 405, "Method Not Allowed", "只支持 GET / HEAD");
                return;
            }

            string rawPath = first[1];
            int q = rawPath.IndexOf('?');
            if (q >= 0)
            {
                rawPath = rawPath.Substring(0, q);
            }

            string decoded;
            try
            {
                decoded = Uri.UnescapeDataString(rawPath);
            }
            catch (Exception)
            {
                decoded = rawPath;
            }

            string relative = decoded.TrimStart('/').Replace('/', Path.DirectorySeparatorChar);
            string full = Path.GetFullPath(Path.Combine(_root, relative));

            // 目录穿越防护：解析后的绝对路径必须仍在根目录内
            string guard = _root.EndsWith(Path.DirectorySeparatorChar.ToString())
                ? _root
                : _root + Path.DirectorySeparatorChar;
            if (!full.StartsWith(guard, StringComparison.OrdinalIgnoreCase)
                && !string.Equals(full, _root, StringComparison.OrdinalIgnoreCase))
            {
                WriteText(stream, 403, "Forbidden", "越界路径");
                return;
            }

            if (Directory.Exists(full))
            {
                if (method == "HEAD")
                {
                    WriteHeader(stream, 200, "OK", "text/html; charset=utf-8", 0);
                }
                else
                {
                    WriteText(stream, 200, "OK", BuildListing(full, decoded));
                }
                Interlocked.Increment(ref _served);
                return;
            }

            if (!File.Exists(full))
            {
                WriteText(stream, 404, "Not Found", "文件不存在：" + decoded);
                Interlocked.Increment(ref _served);
                return;
            }

            long length;
            try
            {
                length = new FileInfo(full).Length;
            }
            catch (Exception e)
            {
                WriteText(stream, 500, "Internal Server Error", e.Message);
                return;
            }

            WriteHeader(stream, 200, "OK", ContentTypeOf(full), length);
            if (method == "GET")
            {
                using (FileStream fs = new FileStream(full, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                {
                    byte[] buffer = new byte[64 * 1024];
                    long sent = 0;
                    while (sent < length)
                    {
                        int read = fs.Read(buffer, 0, buffer.Length);
                        if (read <= 0)
                        {
                            break;
                        }
                        stream.Write(buffer, 0, read);
                        sent += read;
                    }
                }
            }
            Interlocked.Increment(ref _served);
        }

        /// <summary>读到空行为止（上限 16KB，防恶意长头把线程拖死）。</summary>
        private static string ReadHeader(NetworkStream stream)
        {
            StringBuilder sb = new StringBuilder();
            byte[] one = new byte[1];
            int matched = 0;
            while (sb.Length < 16 * 1024)
            {
                int read;
                try
                {
                    read = stream.Read(one, 0, 1);
                }
                catch (Exception)
                {
                    return null;
                }
                if (read <= 0)
                {
                    break;
                }
                char c = (char)one[0];
                sb.Append(c);
                if ((matched == 0 || matched == 2) && c == '\r') matched++;
                else if ((matched == 1 || matched == 3) && c == '\n') matched++;
                else matched = 0;
                if (matched == 4)
                {
                    break;
                }
            }
            return sb.ToString();
        }

        private static void WriteHeader(NetworkStream stream, int code, string reason, string contentType, long length)
        {
            string head = "HTTP/1.1 " + code + " " + reason + "\r\n"
                + "Content-Type: " + contentType + "\r\n"
                + "Content-Length: " + length + "\r\n"
                + "Cache-Control: no-store\r\n"
                + "Connection: close\r\n\r\n";
            byte[] bytes = Encoding.ASCII.GetBytes(head);
            stream.Write(bytes, 0, bytes.Length);
        }

        private static void WriteText(NetworkStream stream, int code, string reason, string body)
        {
            byte[] bytes = Encoding.UTF8.GetBytes(body ?? "");
            WriteHeader(stream, code, reason, "text/plain; charset=utf-8", bytes.Length);
            stream.Write(bytes, 0, bytes.Length);
        }

        private static string ContentTypeOf(string path)
        {
            string ext = Path.GetExtension(path).ToLowerInvariant();
            if (ext == ".txt" || ext == ".version" || ext == ".json" || ext == ".hash")
            {
                return "text/plain; charset=utf-8";
            }
            return "application/octet-stream";
        }

        /// <summary>目录索引（浏览器打开根地址时能看到版本文件与文件数，便于人工确认）。</summary>
        private static string BuildListing(string dir, string urlPath)
        {
            string[] files;
            string[] dirs;
            try
            {
                files = Directory.GetFiles(dir);
                dirs = Directory.GetDirectories(dir);
            }
            catch (Exception e)
            {
                return "读取目录失败：" + e.Message;
            }

            StringBuilder sb = new StringBuilder();
            sb.Append("<html><meta charset=\"utf-8\"><body style=\"font-family:Consolas,monospace\">");
            sb.Append("<h3>FT HotUpdate · ").Append(WebUtility.HtmlEncode(urlPath)).Append("</h3>");
            sb.Append("<p>root: ").Append(WebUtility.HtmlEncode(dir)).Append("</p><ul>");
            if (!string.Equals(Path.GetFullPath(dir), _root, StringComparison.OrdinalIgnoreCase))
            {
                sb.Append("<li><a href=\"../\">../</a></li>");
            }
            for (int i = 0; i < dirs.Length; i++)
            {
                string name = Path.GetFileName(dirs[i]);
                sb.Append("<li><a href=\"").Append(Uri.EscapeDataString(name)).Append("/\">")
                  .Append(WebUtility.HtmlEncode(name)).Append("/</a></li>");
            }
            for (int i = 0; i < files.Length; i++)
            {
                string name = Path.GetFileName(files[i]);
                long size = 0;
                try { size = new FileInfo(files[i]).Length; }
                catch (Exception) { }
                sb.Append("<li><a href=\"").Append(Uri.EscapeDataString(name)).Append("\">")
                  .Append(WebUtility.HtmlEncode(name)).Append("</a> · ")
                  .Append(HotUpdateFileUtil.FormatSize(size)).Append("</li>");
            }
            sb.Append("</ul></body></html>");
            return sb.ToString();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using HybridCLR.Editor.Commands;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

#if USE_YOOASSET
using YooAsset.Editor;
#endif

namespace FTProject.EditorTools
{
    /// <summary>
    /// 一键热更的运行日志：**同时**写 Console 与文件。
    ///
    /// 【为什么必须有文件】失败时人往往只看到"红了一片"，而 MCP / CI 会话结束后
    /// Console 也看不到了。落一份 Logs/HotUpdate/last_run.log，排查时直接看这个文件，
    /// 或者把它贴给同事。
    /// </summary>
    public static class HotUpdateLog
    {
        private static readonly object Sync = new object();

        public static string FilePath { get { return HotUpdatePaths.LogFile; } }

        /// <summary>开始一次运行：清空旧日志并写头。</summary>
        public static void Begin(string header)
        {
            try
            {
                string dir = Path.GetDirectoryName(HotUpdatePaths.LogFile);
                if (!string.IsNullOrEmpty(dir))
                {
                    Directory.CreateDirectory(dir);
                }
                File.WriteAllText(HotUpdatePaths.LogFile,
                    header + "\n============================================================\n",
                    new UTF8Encoding(false));
            }
            catch (Exception)
            {
                // 日志文件写不了不能影响主流程
            }
        }

        public static void Line(string message)
        {
            Append(message);
            Debug.Log("[HotUpdate] " + message);
        }

        public static void Warn(string message)
        {
            Append("[警告] " + message);
            Debug.LogWarning("[HotUpdate] " + message);
        }

        public static void Error(string message)
        {
            Append("[错误] " + message);
            Debug.LogError("[HotUpdate] " + message);
        }

        private static void Append(string message)
        {
            if (message == null)
            {
                return;
            }
            try
            {
                lock (Sync)
                {
                    string[] lines = message.Replace("\r\n", "\n").Split('\n');
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i < lines.Length; i++)
                    {
                        sb.Append(DateTime.Now.ToString("HH:mm:ss.fff")).Append("  ").Append(lines[i]).Append('\n');
                    }
                    File.AppendAllText(HotUpdatePaths.LogFile, sb.ToString(), new UTF8Encoding(false));
                }
            }
            catch (Exception)
            {
            }
        }

        /// <summary>读日志尾部（面板显示用；只读不阻塞写）。</summary>
        public static string Tail(int maxChars)
        {
            try
            {
                if (!File.Exists(HotUpdatePaths.LogFile))
                {
                    return "";
                }
                using (FileStream fs = new FileStream(HotUpdatePaths.LogFile, FileMode.Open,
                           FileAccess.Read, FileShare.ReadWrite))
                {
                    long take = Math.Min(fs.Length, Math.Max(maxChars, 1024));
                    fs.Seek(-take, SeekOrigin.End);
                    byte[] buffer = new byte[take];
                    int read = fs.Read(buffer, 0, buffer.Length);
                    string text = Encoding.UTF8.GetString(buffer, 0, read);
                    // 从头截断可能落在多字节字符中间，丢掉第一行残片
                    int firstBreak = text.IndexOf('\n');
                    if (firstBreak >= 0 && text.Length > firstBreak + 1)
                    {
                        text = text.Substring(firstBreak + 1);
                    }
                    return text;
                }
            }
            catch (Exception e)
            {
                return "（读取日志失败：" + e.Message + "）";
            }
        }
    }

    /// <summary>
    /// **一键热更流水线**：重编热更 dll ▸ 同步 dll+md5 ▸ 构建 AB（版本自增） ▸ 生成清单
    /// ▸ 部署到本地资源服务器 ▸ 上传远端 ▸ 本地运行验证 ▸（可选）Play 冒烟。
    ///
    /// ==================================================================
    /// 【为什么又是状态机】HybridCLR `Generate/All` 会重写 `AOTGenericReferences.cs`，
    /// 触发脚本编译与域重载 —— 正在执行的方法栈会被直接杀掉。所以：
    ///   · 阶段游标存 SessionState（域重载后保留）；
    ///   · [InitializeOnLoad] 每次域重载后重新挂 Tick；
    ///   · 阶段**执行成功之后**才推进；被打断时下一轮原地重跑（幂等），
    ///     宁可多花几分钟，也绝不静默使用旧产物。
    ///   · 版本号在 Preflight 就定好并写进 SessionState：重跑不会二次自增。
    ///
    /// 【与已有菜单的关系】
    ///   · 菜单 7（BuildApkFull）：DLL ▸ AB ▸ APK，**不出热更服务器的部署**；
    ///   · 菜单 9（ReporterHotfixBuild）：DLL ▸ AB，部署要另开终端跑 python；
    ///   · 本流水线：DLL ▸ AB ▸ 清单 ▸ 部署 ▸ 上传 ▸ 本地验证，全在编辑器内完成，
    ///     但**不构建 APK**（热更不改包体）。
    ///   三者共用同一批底层实现（PrebuildCommand / HybridCLRDllCopier /
    ///   HybridCLRMd5Generator / FTYooAssetSetupWizard.BuildRealBundlesCore），
    ///   不存在"两套构建逻辑漂移"的问题。
    ///
    /// 【失败即中断】任一阶段失败 → 阶段置 Fail、写 DONE FAIL 到状态文件、
    ///   Console 红字 + 日志文件，并停掉还没走完的异步任务；不会带着半套产物继续。
    ///
    /// 【外部观测】
    ///   Library/FT_HotUpdateStatus.txt  逐行追加：START / PHASE xxx ok / DONE OK|FAIL
    ///   Logs/HotUpdate/last_run.log     完整日志
    /// ==================================================================
    /// </summary>
    [InitializeOnLoad]
    public static class HotUpdatePipeline
    {
        // ------------------------------------------------------------------
        // SessionState 键（域重载后必须保留的东西）
        // ------------------------------------------------------------------

        private const string PhaseKey = "FT.Hot.Update.Phase";
        private const string OptionsKey = "FT.Hot.Update.Options";
        private const string VersionKey = "FT.Hot.Update.Version";
        private const string PlanFromCdnKey = "FT.Hot.Update.PlanFromCdn";
        private const string FailPhaseKey = "FT.Hot.Update.FailPhase";
        private const string LastErrorKey = "FT.Hot.Update.LastError";
        private const string StartedKey = "FT.Hot.Update.StartedAt";
        private const string PlayEnterKey = "FT.Hot.Update.PlayEnter";
        private const string PlayStartKey = "FT.Hot.Update.PlayStart";
        private const string PlayErrorsKey = "FT.Hot.Update.PlayErrors";
        private const string PlayIgnoredKey = "FT.Hot.Update.PlayIgnored";
        private const string FileCountKey = "FT.Hot.Update.FileCount";

        /// <summary>
        /// Play 冒烟时**不计入**错误的日志片段（编辑器环境噪音，与游戏无关）。
        ///
        /// 【为什么要有】本机每次进 Play 都会抛
        /// `CommandInvokationFailure: Unity Remote requirements check failed`
        /// （Unity Remote 的 Android 设备检查，和热更/游戏逻辑无关）。
        /// 不过滤的话，冒烟永远"有 1 条错误"，这个检查就失去意义了。
        /// 新发现的环境噪音按同样格式追加，并在日志里显式说明"已忽略 N 条"。
        /// </summary>
        private static readonly string[] PlayLogIgnorePatterns =
        {
            "Unity Remote requirements check failed",
        };

        /// <summary>阶段顺序（面板按这个顺序画步骤条，进度也按它算）。</summary>
