            "PlaySmokeWait",
            "Finish",
            "Done",
        };

        /// <summary>每个阶段在面板上显示的中文名（与 Phases 一一对应）。</summary>
        public static readonly string[] PhaseTitles =
        {
            "预检（平台 / 版本 / 环境）",
            "重新编译热更 DLL（HybridCLR Generate/All）",
            "同步 dll + 生成 md5 清单",
            "构建 AB 资源包（版本自增）",
            "生成热更清单 / 构建记录",
            "部署到本地资源服务器",
            "上传到远端资源服务器",
            "本地运行验证（文件 + HTTP 链路）",
            "进入 Play 冒烟",
            "Play 冒烟观察（8 秒）",
            "收尾",
            "完成",
        };

        // ------------------------------------------------------------------
        // 运行期状态（域重载会丢，可丢的都放这里；要紧的都在 SessionState）
        // ------------------------------------------------------------------

        private static HotUpdatePlan _plan;
        private static Task _verifyTask;
        private static Task _uploadTask;
        private static HotUpdateVerifyResult _verifyResult;
        private static volatile string _verifyError;
        private static volatile bool _uploadOk;
        private static volatile string _uploadError;
        private static volatile int _jobDone;
        private static volatile int _jobTotal;
        private static bool _serverStartedByPipeline;

        private static readonly string MainScenePath = "Assets/Scenes/Main.unity";

        // ------------------------------------------------------------------
        // 对外状态（面板/菜单/MCP 只读）
        // ------------------------------------------------------------------

        public static string CurrentPhase { get { return GetPhase(); } }

        public static bool IsRunning
        {
            get
            {
                string phase = GetPhase();
                return phase != "Idle" && phase != "Done" && phase != "Fail";
            }
        }

        public static string CurrentVersion { get { return SessionState.GetString(VersionKey, ""); } }

        public static string LastError { get { return SessionState.GetString(LastErrorKey, ""); } }

        public static string StartedAt { get { return SessionState.GetString(StartedKey, ""); } }

        public static HotUpdateOptions Options { get { return GetOptions(); } }

        public static bool LocalServerRunning { get { return HotUpdateLocalServer.IsRunning; } }

        /// <summary>当前阶段下标（失败时返回失败所在阶段，便于面板标红）。</summary>
        public static int StepIndex
        {
            get
            {
                string phase = GetPhase();
                if (phase == "Fail")
                {
                    phase = SessionState.GetString(FailPhaseKey, "Preflight");
                }
                int index = Array.IndexOf(Phases, phase);
                return index < 0 ? 0 : index;
            }
        }

        /// <summary>0..1 的总体进度。</summary>
        public static float Progress01
        {
            get
            {
                if (GetPhase() == "Done")
                {
                    return 1f;
                }

                // 仅验证模式跳过了前 7 个构建阶段：进度从 Verify 起算，
                // 否则一进来就显示 63%，看起来像"已经快跑完了"。
                int start = 0;
                if (GetOptions().verifyOnly)
                {
                    start = Array.IndexOf(Phases, "Verify");
                }
                int last = Phases.Length - 1;
                int index = Mathf.Max(StepIndex, start);
                int span = last - start;
                return span <= 0 ? 0f : Mathf.Clamp01((float)(index - start) / span);
            }
        }

        /// <summary>异步任务（上传 / HTTP 校验）的进度文本。</summary>
        public static string JobText
        {
            get
            {
                if (string.IsNullOrEmpty(CurrentPhase))
                {
                    return "";
                }
                int done = _jobDone;
                int total = _jobTotal;
                if (total <= 0)
                {
                    return "";
                }
                if (_uploadTask != null)
                {
                    return string.Format("上传 {0}/{1}", done, total);
                }
                if (_verifyTask != null)
                {
                    return string.Format("校验 {0}/{1}", done, total);
                }
                return "";
            }
        }

        public static float JobProgress01
        {
            get { return _jobTotal <= 0 ? 0f : Mathf.Clamp01((float)_jobDone / _jobTotal); }
        }

        // ------------------------------------------------------------------
        // 启动 / 取消
        // ------------------------------------------------------------------

        static HotUpdatePipeline()
        {
            EditorApplication.update += Tick;
            Application.logMessageReceived += OnLogMessage;
        }

        /// <summary>完整流水线（菜单 / 面板按钮）。</summary>
        public static void StartFull()
        {
            string reason;
            if (!CanStart(out reason))
            {
                Debug.LogError("[HotUpdate] 无法开始：" + reason);
                return;
            }
            HotUpdateOptions options = HotUpdateOptions.FromSettings(false);
            Begin(options);
        }

        /// <summary>只做本地验证（不构建、不部署）：验证服务器上"现在这一版"完不完整。</summary>
        public static void StartVerifyOnly()
        {
            string reason;
            if (!CanStart(out reason))
            {
                Debug.LogError("[HotUpdate] 无法开始：" + reason);
                return;
            }
            HotUpdateOptions options = HotUpdateOptions.FromSettings(true);
            options.verify = true;
            Begin(options);
        }

        private static bool CanStart(out string reason)
        {
            reason = null;
            if (IsRunning)
            {
                reason = "已有热更流水线在跑（阶段 " + CurrentPhase + "），请等它结束或先取消。";
                return false;
            }
            if (EditorApplication.isPlaying)
            {
                reason = "编辑器处于 Play 模式，请先退出。";
                return false;
            }
            if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                reason = "编辑器正在编译 / 导入资源，请等空闲后再试。";
                return false;
            }
            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                reason = "当前构建目标是 " + EditorUserBuildSettings.activeBuildTarget +
                         "，热更 dll / AB 会打到错误平台。请先切到 Android。";
                return false;
            }
            if (OtherPipelineBusy())
            {
                reason = "另一条构建流水线正在运行（菜单 7 / 9）。两者同时跑会互相踩产物，请等它结束。";
                return false;
            }
            return true;
        }

        /// <summary>
        /// 检查菜单 7 / 9 的流水线是否在跑。
        /// 【为什么读字符串而不是引用】那两个类的阶段键是 private const，
        /// 这里按**约定好的键名**读取 SessionState —— 只读、无编译依赖，键名变更时
        /// 最坏情况是漏检（不会编译失败）。
        /// </summary>
        private static bool OtherPipelineBusy()
        {
            string reporter = SessionState.GetString("FTReporterBuild.Phase", "Idle");
            string full = SessionState.GetString("FTBuildApkFull.Phase", "Idle");
            return IsBusyPhase(reporter) || IsBusyPhase(full);
        }

        private static bool IsBusyPhase(string phase)
        {
            return !string.IsNullOrEmpty(phase)
                && phase != "Idle" && phase != "Done" && phase != "Fail";
        }

        private static void Begin(HotUpdateOptions options)
        {
            _plan = null;
            _verifyTask = null;
            _uploadTask = null;
            _verifyResult = null;
            _verifyError = null;
            _uploadError = null;
            _jobDone = 0;
            _jobTotal = 0;
            _serverStartedByPipeline = false;

            SessionState.SetString(OptionsKey, JsonUtility.ToJson(options));
            SessionState.SetString(VersionKey, options.verifyOnly ? "" : (options.versionOverride ?? ""));
            SessionState.SetString(LastErrorKey, "");
            SessionState.SetString(FailPhaseKey, "");
            SessionState.SetString(StartedKey, DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            SessionState.SetString(PlayEnterKey, "");
            SessionState.SetString(PlayStartKey, "");
            SessionState.SetInt(PlayErrorsKey, 0);
            SessionState.SetInt(PlayIgnoredKey, 0);
            SessionState.SetInt(FileCountKey, 0);
            SessionState.SetBool(PlanFromCdnKey, options.verifyOnly);

            HotUpdateLog.Begin(string.Format(
                "一键热更 {0}\n工程：{1}\n平台：{2}\n模式：{3}",
                DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),
                HotUpdatePaths.ProjectRoot,
                HotUpdatePaths.PlatformFolder,
                options.verifyOnly ? "仅本地验证" : "完整（dll ▸ AB ▸ 部署 ▸ 验证）"));

            WriteStatus("START " + (options.verifyOnly ? "VERIFY-ONLY " : "HOTUPDATE ") +
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));

            if (options.verifyOnly)
            {
                HotUpdateLog.Line("模式：仅本地验证（不重编 dll、不构建 AB、不改部署）");
                SetPhase("Verify");
            }
            else
            {
                HotUpdateLog.Line("模式：完整热更（本地部署=" + (options.local ? "开" : "关") +
                                  "，远端上传=" + (options.remote ? "开" : "关") +
                                  "，本地验证=" + (options.verify ? "开" : "关") +
                                  "，Play 冒烟=" + (options.play ? "开" : "关") + "）");
                SetPhase("Preflight");
            }
        }

        /// <summary>中断当前流水线（异步任务无法强杀，只能停在本帧之后不再推进）。</summary>
        public static void Cancel()
        {
            if (!IsRunning)
            {
                return;
            }
            Fail("已取消（用户中断，阶段：" + CurrentPhase + "）");
        }

        // ------------------------------------------------------------------
        // Tick 驱动
        // ------------------------------------------------------------------

        private static void Tick()
        {
            string phase = GetPhase();
            if (phase == "Idle" || phase == "Done" || phase == "Fail")
            {
                return;
            }
            // 编译 / 导入期间一律等待（空闲后自动继续）
            if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                return;
            }

            try
            {
                switch (phase)
                {
                    case "Preflight": TickPreflight(); break;
                    case "DllGenerate": TickDllGenerate(); break;
                    case "DllCopy": TickDllCopy(); break;
                    case "AbBuild": TickAbBuild(); break;
                    case "Manifest": TickManifest(); break;
                    case "DeployLocal": TickDeployLocal(); break;
                    case "UploadRemote": TickUploadRemote(); break;
                    case "Verify": TickVerify(); break;
                    case "PlaySmokeStart": TickPlaySmokeStart(); break;
                    case "PlaySmokeWait": TickPlaySmokeWait(); break;
                    case "Finish": TickFinish(); break;
                }
            }
            catch (Exception e)
            {
                Fail(phase + " 阶段异常：\n" + e);
            }
        }

        // ------------------------------------------------------------------
        // ① 预检
        // ------------------------------------------------------------------

        private static void TickPreflight()
        {
            HotUpdateLog.Line("① 预检：平台 / 版本 / 环境");

            if (EditorApplication.isPlaying)
            {
                Fail("编辑器处于 Play 模式，请先退出。");
                return;
            }
            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                Fail("当前构建目标是 " + EditorUserBuildSettings.activeBuildTarget +
                     "，热更 dll / AB 会打到错误平台。请先切到 Android。");
                return;
            }

#if !USE_YOOASSET
            Fail("当前平台未启用 USE_YOOASSET 宏，AB 热更链路依赖它。\n" +
                 "请先执行「Tools ▸ 塔防 ▸ YooAsset 接入 ▸ 1. 启用 USE_YOOASSET 宏」。");
            return;
#else
            if (BundleCollectorSettingData.HasSettingAsset() == false)
            {
                Fail("还没有 YooAsset 收集器配置资产，请先执行「YooAsset 接入 → 接入向导 → ① 生成 / 修复收集器配置」。");
                return;
            }
#endif

            string version;
            string overrideVersion = (GetOptions().versionOverride ?? "").Trim();
            if (overrideVersion.Length > 0)
            {
                if (!HotUpdateVersionUtil.IsValid(overrideVersion))
                {
                    Fail("手动指定的版本号格式不对（要 x.y.z）：" + overrideVersion);
                    return;
                }
                version = overrideVersion;
                HotUpdateLog.Line("版本号：手动指定 " + version);
            }
            else
            {
                version = HotUpdateVersionUtil.Next();
                HotUpdateLog.Line("版本号：自动递增 → " + version + "（" + HotUpdateVersionUtil.Describe() + "）");
            }

            if (!HotUpdateVersionUtil.IsValid(version))
            {
                Fail("版本号解析失败：" + version);
                return;
            }

            SessionState.SetString(VersionKey, version);

            string buildDir = HotUpdatePaths.BuildDir(version);
            if (Directory.Exists(buildDir))
            {
                HotUpdateLog.Warn("版本目录已存在，将先清理再构建：" + buildDir);
            }

            HotUpdateLog.Line("随包 dll 目录：" + HotUpdatePaths.DllDir);
            HotUpdateLog.Line("AB 输出目录：" + buildDir);
            HotUpdateLog.Line("本地服务器根：" + HotUpdatePaths.CdnRoot);
            if (GetOptions().remote)
            {
                HotUpdateLog.Line("远端上传：" + GetOptions().remoteUrl);
            }

            Advance("DllGenerate");
        }

        // ------------------------------------------------------------------
        // ② HybridCLR Generate/All
        // ------------------------------------------------------------------

        private static void TickDllGenerate()
        {
            HotUpdateLog.Line("② 重新编译热更 DLL（HybridCLR Generate/All）…");
            // 直接调包内 API（与菜单「HybridCLR/Generate/All」同一实现），
            // 不依赖 batchmode 下菜单系统的可用性。
            PrebuildCommand.GenerateAll();
            AssetDatabase.Refresh();
            HotUpdateLog.Line("Generate/All 完成（若中途触发域重载，本阶段会重跑一次，产物幂等）。");
            Advance("DllCopy");
        }

        // ------------------------------------------------------------------
        // ③ 拷贝 dll + md5
        // ------------------------------------------------------------------

        private static void TickDllCopy()
        {
            HotUpdateLog.Line("③ 同步热更 dll 到 StreamingAssets + 生成 md5 清单 …");

            EditorUtil.Report copyReport = new EditorUtil.Report();
            HybridCLRDllCopier.Copy(copyReport);
            if (copyReport.Errors > 0)
            {
                Fail("同步热更 dll 失败：\n" + copyReport.Text);
                return;
            }

            EditorUtil.Report md5Report = new EditorUtil.Report();
            HybridCLRMd5Generator.Generate(md5Report);
            if (md5Report.Errors > 0)
            {
                Fail("生成 dll md5 清单失败：\n" + md5Report.Text);
                return;
            }

            AssetDatabase.Refresh();
            HotUpdateLog.Line(copyReport.Text);
            HotUpdateLog.Line(md5Report.Text);
            Advance("AbBuild");
        }

        // ------------------------------------------------------------------
        // ④ 构建 AB
        // ------------------------------------------------------------------

        private static void TickAbBuild()
        {
            string version = CurrentVersion;
            string buildDir = HotUpdatePaths.BuildDir(version);
            HotUpdateLog.Line("④ 构建 AB 资源包 v" + version + " …");

#if USE_YOOASSET
            EditorUtil.Report report = new EditorUtil.Report();
            bool ok = FTYooAssetSetupWizard.BuildRealBundlesCore(version, GetOptions().fullRebuild, report);
            if (!ok)
            {
                Fail("AB 构建失败：\n" + report.Text);
                return;
            }
            HotUpdateLog.Line(report.Text);

            // 产物自检：客户端真正依赖的三个入口文件必须存在
            string versionFile = Path.Combine(buildDir, HotUpdatePaths.VersionFileName);
            string hashFile = Path.Combine(buildDir, "FreeTower_" + version + ".hash");
            string bytesFile = Path.Combine(buildDir, "FreeTower_" + version + ".bytes");
            List<string> missing = new List<string>();
            if (!File.Exists(versionFile)) missing.Add(HotUpdatePaths.VersionFileName);
            if (!File.Exists(hashFile)) missing.Add(Path.GetFileName(hashFile));
            if (!File.Exists(bytesFile)) missing.Add(Path.GetFileName(bytesFile));
            if (missing.Count > 0)
            {
                Fail("AB 构建后缺少关键产物：" + string.Join("、", missing.ToArray()) + "\n目录：" + buildDir);
                return;
            }

            string builtVersion = File.ReadAllText(versionFile).Trim();
            if (builtVersion != version)
            {
                Fail(string.Format("AB 产物里的版本号是 {0}，与目标 {1} 不一致（构建参数没生效？）",
                    builtVersion, version));
                return;
            }

            HotUpdateLog.Line("AB 构建完成：" + buildDir);
            Advance("Manifest");
#else
            Fail("当前平台未启用 USE_YOOASSET 宏，无法构建 YooAsset 资源包。");
#endif
        }

        // ------------------------------------------------------------------
        // ⑤ 生成清单
        // ------------------------------------------------------------------

        private static void TickManifest()
        {
            HotUpdateLog.Line("⑤ 生成热更清单（AB + dll）…");
            HotUpdatePlan plan = EnsurePlan();
            if (plan == null)
            {
                return;
            }

            HotUpdateLog.Line(plan.Describe());
            SessionState.SetInt(FileCountKey, plan.Files.Count);

            // 把清单写进本机历史（部署阶段会再拷一份到服务器根）
            string historyDir = Path.Combine(HotUpdatePaths.StateDir, "history");
            Directory.CreateDirectory(historyDir);
            EditorUtil.Report report = new EditorUtil.Report();
            string manifestPath = Path.Combine(historyDir, plan.Version + ".json");
            if (!HotUpdateDeployer.WriteManifest(plan, manifestPath, "构建完成（尚未部署）", report))
            {
                Fail("写热更清单失败：\n" + report.Text);
                return;
            }

            HotUpdateLog.Line(report.Text);
            Advance("DeployLocal");
        }

        // ------------------------------------------------------------------
        // ⑥ 本地部署
        // ------------------------------------------------------------------

        private static void TickDeployLocal()
        {
            HotUpdateOptions options = GetOptions();
            if (!options.local)
            {
                HotUpdateLog.Line("⑥ 跳过本地部署（未启用）。");
                Advance("UploadRemote");
                return;
            }

            HotUpdateLog.Line("⑥ 部署到本地资源服务器：" + HotUpdatePaths.CdnRoot);
            HotUpdatePlan plan = EnsurePlan();
            if (plan == null)
            {
                return;
            }

            EditorUtil.Report report = new EditorUtil.Report();
            if (!HotUpdateDeployer.DeployLocal(plan, HotUpdatePaths.CdnRoot, report))
            {
                Fail("本地部署失败：\n" + report.Text);
                return;
            }

            HotUpdateLog.Line(report.Text);
            Advance("UploadRemote");
        }

        // ------------------------------------------------------------------
        // ⑦ 远端上传（后台线程）
        // ------------------------------------------------------------------

        private static void TickUploadRemote()
        {
            if (_uploadTask != null)
            {
                PollUpload();
                return;
            }

            HotUpdateOptions options = GetOptions();
            if (!options.remote)
            {
                HotUpdateLog.Line("⑦ 跳过远端上传（未启用）。");
                Advance("Verify");
                return;
            }
            if (string.IsNullOrEmpty(options.remoteUrl))
            {
                Fail("已勾选远端上传，但远端根地址为空。请回到面板填写（例如 https://cdn.example.com/freedomtower）。");
                return;
            }

            HotUpdatePlan plan = EnsurePlan();
            if (plan == null)
            {
                return;
            }

            HotUpdateLog.Line("⑦ 上传到远端：" + options.remoteUrl + "（共 " + (plan.Files.Count + 1) + " 个文件）");

            _jobDone = 0;
            _jobTotal = plan.Files.Count + 1;
            _uploadOk = false;
            _uploadError = null;

            string baseUrl = options.remoteUrl;
            string header = options.remoteHeader;
            _uploadTask = Task.Run(() =>
            {
                string error;
                bool ok = HotUpdateDeployer.UploadAll(plan, baseUrl, header,
                    (done, total) =>
                    {
                        _jobDone = done;
                        _jobTotal = total;
                    }, out error);
                _uploadOk = ok;
                _uploadError = error;
            });
        }

        private static void PollUpload()
        {
            if (!_uploadTask.IsCompleted)
            {
                return;
            }
            Exception exception = _uploadTask.Exception;
            _uploadTask = null;
            _jobDone = 0;
            _jobTotal = 0;

            if (exception != null)
            {
                Fail("远端上传异常：" + exception.GetBaseException().Message);
                return;
            }
            if (!_uploadOk)
            {
                Fail("远端上传失败：" + (_uploadError ?? "未知错误"));
                return;
            }

            HotUpdateLog.Line("远端上传完成。");
            Advance("Verify");
        }

        // ------------------------------------------------------------------
        // ⑧ 本地运行验证（文件 + HTTP 链路）
        // ------------------------------------------------------------------

        private static void TickVerify()
        {
            if (_verifyTask != null)
            {
                PollVerify();
                return;
            }

            HotUpdateOptions options = GetOptions();
            if (!options.verify)
            {
                HotUpdateLog.Line("⑧ 跳过本地验证（未启用）。");
                Advance("PlaySmokeStart");
                return;
            }

            HotUpdatePlan plan = EnsurePlan();
            if (plan == null)
            {
                return;
            }

            HotUpdateLog.Line("⑧ 本地运行验证：文件完整性 + HTTP 链路 …");

            HotUpdateVerifyResult result = new HotUpdateVerifyResult();
            HotUpdateDeployer.VerifyLocalFiles(plan, HotUpdatePaths.CdnRoot, options.local, result);

            string baseUrl = null;
            if (options.local)
            {
                string error;
                bool startedNow;
                if (HotUpdateLocalServer.Start(HotUpdatePaths.CdnRoot, HotUpdateSettings.VerifyPort,
                        out startedNow, out error))
                {
                    baseUrl = HotUpdateLocalServer.Url;
                    // 只停"自己起的"服务：用户可能正用菜单 10c 起的服务在真机联调
                    _serverStartedByPipeline = startedNow;
                    if (startedNow)
                    {
                        HotUpdateLog.Line("本地静态服务器：" + baseUrl + " → " + HotUpdatePaths.CdnRoot);
                    }
                    else
                    {
                        HotUpdateLog.Line("复用已在运行的本地静态服务器：" + baseUrl);
                    }
                }
                else
                {
                    // 端口被占用：可能已经开着官方 python 服务器（或别的工程）。
                    // 能读到版本号就复用它，读不到就只做文件级检查。
                    string existingUrl = "http://127.0.0.1:" + HotUpdateSettings.VerifyPort;
                    string existingVersion;
                    string probeError;
                    if (HotUpdateDeployer.TryGetRemoteVersion(existingUrl, out existingVersion, out probeError))
                    {
                        baseUrl = existingUrl;
                        result.Warnings.Add(string.Format(
                            "端口 {0} 已被占用，复用已有服务做校验（其上版本 {1}）", HotUpdateSettings.VerifyPort, existingVersion));
                        if (existingVersion != plan.Version)
                        {
                            result.Warnings.Add(string.Format(
                                "已有服务上的版本 {0} 与本次 {1} 不一致：它服务的可能不是当前部署目录。",
                                existingVersion, plan.Version));
                        }
                    }
                    else
                    {
                        result.Warnings.Add("本地静态服务器启动失败，且无可复用的服务：" + error);
                    }
                }
            }
            else if (options.remote && !string.IsNullOrEmpty(options.remoteUrl))
            {
                baseUrl = options.remoteUrl.TrimEnd('/');
                HotUpdateLog.Line("验证远端地址：" + baseUrl);
            }

            if (result.Failures.Count > 0)
            {
                Fail("本地校验未通过（文件级）：\n" + result.Describe());
                return;
            }

            if (string.IsNullOrEmpty(baseUrl))
            {
                result.Warnings.Add("没有可用的 HTTP 服务，本次只做了文件级校验。");
                HotUpdateLog.Warn(result.Describe());
                Advance("PlaySmokeStart");
                return;
            }

            _jobDone = 0;
            _jobTotal = plan.Files.Count + 1;
            _verifyResult = result;
            _verifyError = null;

            string url = baseUrl;
            _verifyTask = Task.Run(() =>
            {
                try
                {
                    HotUpdateDeployer.VerifyHttp(plan, url,
                        (done, total) =>
                        {
                            _jobDone = done;
                            _jobTotal = total;
                        }, result);
                }
                catch (Exception e)
                {
                    _verifyError = e.Message;
                }
            });
        }

        private static void PollVerify()
        {
            if (!_verifyTask.IsCompleted)
            {
                return;
            }
            Exception exception = _verifyTask.Exception;
            _verifyTask = null;
            _jobDone = 0;
            _jobTotal = 0;
            HotUpdateVerifyResult result = _verifyResult;
            _verifyResult = null;

            if (exception != null)
            {
                Fail("HTTP 校验异常：" + exception.GetBaseException().Message);
                return;
            }
            if (!string.IsNullOrEmpty(_verifyError))
            {
                Fail("HTTP 校验异常：" + _verifyError);
                return;
            }
            if (result == null)
            {
                Fail("HTTP 校验结果丢失。");
                return;
            }

            HotUpdateLog.Line(result.Describe());
            if (!result.Ok)
            {
                Fail("本地运行验证未通过：\n" + result.Describe());
                return;
            }

            Advance("PlaySmokeStart");
        }

        // ------------------------------------------------------------------
        // ⑨ Play 冒烟（可选）：进 Main 场景跑 8 秒，统计错误日志
        // ------------------------------------------------------------------

        private static void TickPlaySmokeStart()
        {
            HotUpdateOptions options = GetOptions();
            if (!options.play)
            {
                HotUpdateLog.Line("⑨ 跳过 Play 冒烟（未启用）。");
                Advance("Finish");
                return;
            }
            if (EditorApplication.isPlaying)
            {
                HotUpdateLog.Line("⑨ 已在 Play 模式，跳过自动冒烟。");
                Advance("Finish");
                return;
            }

            // 不替用户保存场景：有未保存改动就跳过，避免"自动保存/丢弃"这种不可逆操作。
            // 注意要检查**所有已加载场景**（可能开了 additive），只看 active 会漏。
            for (int i = 0; i < EditorSceneManager.sceneCount; i++)
            {
                UnityEngine.SceneManagement.Scene scene = EditorSceneManager.GetSceneAt(i);
                if (scene.isDirty)
                {
                    HotUpdateLog.Warn("场景「" + scene.name +
                        "」有未保存修改，跳过 Play 冒烟（避免丢失改动）。保存后可单独进 Play 验证。");
                    Advance("Finish");
                    return;
                }
            }

            string sceneFull = HotUpdatePaths.Resolve(MainScenePath);
            if (!File.Exists(sceneFull))
            {
                HotUpdateLog.Warn("找不到 Main 场景（" + MainScenePath + "），跳过 Play 冒烟。");
                Advance("Finish");
                return;
            }

            SessionState.SetInt(PlayErrorsKey, 0);
            SessionState.SetInt(PlayIgnoredKey, 0);
            SessionState.SetString(PlayEnterKey, NowSeconds().ToString("R", CultureInfo.InvariantCulture));
            SessionState.SetString(PlayStartKey, "");

            EditorSceneManager.OpenScene(MainScenePath, OpenSceneMode.Single);

            // 先推进阶段再进 Play：进 Play 会触发域重载，方法栈会被杀掉
            SetPhase("PlaySmokeWait");
            HotUpdateLog.Line("⑨ 进入 Play（Main 场景），观察 8 秒 …");
            EditorApplication.isPlaying = true;
        }

        private static void TickPlaySmokeWait()
        {
            double now = NowSeconds();
            if (!EditorApplication.isPlaying)
            {
                double enter = ParseSeconds(SessionState.GetString(PlayEnterKey, ""));
                if (enter > 0 && now - enter > 20)
                {
                    HotUpdateLog.Warn("20 秒内没有进入 Play（可能存在编译错误），跳过冒烟。");
                    Advance("Finish");
                }
                return;
            }

            double start = ParseSeconds(SessionState.GetString(PlayStartKey, ""));
            if (start <= 0)
            {
                SessionState.SetString(PlayStartKey, now.ToString("R", CultureInfo.InvariantCulture));
                return;
            }
            if (now - start < 8)
            {
                return;
            }

            int errors = SessionState.GetInt(PlayErrorsKey, 0);
            int ignored = SessionState.GetInt(PlayIgnoredKey, 0);
            EditorApplication.isPlaying = false;

            if (errors > 0)
            {
                HotUpdateLog.Warn(string.Format(
                    "Play 冒烟：8 秒内出现 {0} 条错误/异常日志（详见 Console；这不一定阻断热更，但上线前应清掉）。", errors));
            }
            else
            {
                HotUpdateLog.Line("Play 冒烟通过（8 秒内无错误/异常日志）"
                    + (ignored > 0 ? string.Format("；已忽略 {0} 条编辑器环境噪音", ignored) : "") + "。");
            }
            Advance("Finish");
        }

        // ------------------------------------------------------------------
        // ⑩ 收尾
        // ------------------------------------------------------------------

        private static void TickFinish()
        {
            string version = CurrentVersion;
            string started = StartedAt;
            double cost = 0;
            DateTime startTime;
            if (DateTime.TryParse(started, out startTime))
            {
                cost = (DateTime.Now - startTime).TotalSeconds;
            }

            SetPhase("Done");
            WriteStatus("DONE OK version=" + version + (cost > 0 ? string.Format(" cost={0:F0}s", cost) : ""));

            HotUpdateLog.Line(string.Format(
                "✔ 一键热更完成：v{0} · {1} 个文件 · 耗时 {2:F0}s\n  服务器根：{3}\n  日志：{4}",
                version,
                _plan != null ? _plan.Files.Count : SessionState.GetInt(FileCountKey, 0),
                cost,
                HotUpdatePaths.CdnRoot,
                HotUpdatePaths.LogFile));

            StopServerIfStartedByPipeline();
            _plan = null;
            _jobDone = 0;
            _jobTotal = 0;
        }

        // ------------------------------------------------------------------
        // 失败 / 状态
        // ------------------------------------------------------------------

        private static void Fail(string message)
        {
            string phase = GetPhase();
            SessionState.SetString(FailPhaseKey, phase);
            SessionState.SetString(LastErrorKey, message);
            SetPhase("Fail");

            HotUpdateLog.Error("✘ 流水线中断（阶段：" + phase + "）：\n" + message);
            WriteStatus("DONE FAIL " + OneLine(message));

            _plan = null;
            _verifyTask = null;
            _uploadTask = null;
            _verifyResult = null;
            _jobDone = 0;
            _jobTotal = 0;
            StopServerIfStartedByPipeline();
        }

        private static void StopServerIfStartedByPipeline()
        {
            if (_serverStartedByPipeline)
            {
                HotUpdateLocalServer.Stop();
                _serverStartedByPipeline = false;
            }
        }

        private static string OneLine(string message)
        {
            if (string.IsNullOrEmpty(message))
            {
                return "";
            }
            string one = message.Replace("\r", " ").Replace("\n", " ");
            if (one.Length > 180)
            {
                one = one.Substring(0, 180);
            }
            return one;
        }

        private static void WriteStatus(string line)
        {
            try
            {
                File.AppendAllText(HotUpdatePaths.StatusFile,
                    DateTime.Now.ToString("HH:mm:ss") + " " + line + "\n", new UTF8Encoding(false));
            }
            catch (Exception e)
            {
                Debug.LogWarning("[HotUpdate] 状态文件写入失败：" + e.Message);
            }
        }

        private static void Advance(string nextPhase)
        {
            WriteStatus("PHASE " + GetPhase() + " ok");
            SetPhase(nextPhase);
        }

        private static string GetPhase()
        {
            return SessionState.GetString(PhaseKey, "Idle");
        }

        private static void SetPhase(string phase)
        {
            SessionState.SetString(PhaseKey, phase);
        }

        private static HotUpdateOptions GetOptions()
        {
            string json = SessionState.GetString(OptionsKey, "");
            if (!string.IsNullOrEmpty(json))
            {
                try
                {
                    HotUpdateOptions options = JsonUtility.FromJson<HotUpdateOptions>(json);
                    if (options != null)
                    {
                        return options;
                    }
                }
                catch (Exception)
                {
                }
            }
            return HotUpdateOptions.FromSettings(false);
        }

        private static bool IsPlanFromCdn()
        {
            return SessionState.GetBool(PlanFromCdnKey, false);
        }

        /// <summary>
        /// 惰性构建清单：域重载后 static 字段会丢，这里按阶段语义重新算一次
        /// （只读磁盘 + 算 md5，幂等）。
        /// </summary>
        private static HotUpdatePlan EnsurePlan()
        {
            if (_plan != null)
            {
                return _plan;
            }

            EditorUtil.Report report = new EditorUtil.Report();
            string version = CurrentVersion;
            if (IsPlanFromCdn())
            {
                if (string.IsNullOrEmpty(version))
                {
                    version = HotUpdateVersionUtil.GetDeployedVersion();
                    // 仅验证模式开始时不写版本（那时还不知道要验哪一版）；
                    // 这里定下来后补写，保证后续状态文件 / 日志 / 面板都能显示版本号。
                    SessionState.SetString(VersionKey, version);
                }
                _plan = HotUpdateDeployer.BuildPlanFromCdn(version, HotUpdatePaths.CdnRoot,
                    HotUpdatePaths.DllDir, HotUpdatePaths.PlatformFolder, report);
            }
            else
            {
                _plan = HotUpdateDeployer.BuildPlan(version, HotUpdatePaths.BuildDir(version),
                    HotUpdatePaths.DllDir, HotUpdatePaths.PlatformFolder, report);
            }

            if (report.Errors > 0)
            {
                _plan = null;
                Fail("生成热更清单失败：\n" + report.Text);
                return null;
            }

            HotUpdateLog.Line(report.Text);
            return _plan;
        }

        // ------------------------------------------------------------------
        // Play 冒烟的错误统计 / 时间工具
        // ------------------------------------------------------------------

        private static void OnLogMessage(string condition, string stackTrace, LogType type)
        {
            if (GetPhase() != "PlaySmokeWait")
            {
                return;
            }
            if (type != LogType.Error && type != LogType.Exception && type != LogType.Assert)
            {
                return;
            }
            // 本流水线自己的日志不计入（否则"跳过/警告"会把自己判成失败）
            if (!string.IsNullOrEmpty(condition) && condition.StartsWith("[HotUpdate]", StringComparison.Ordinal))
            {
                return;
            }
            // 编辑器环境噪音（Unity Remote 设备检查等）：单独计数，不算冒烟失败
            if (!string.IsNullOrEmpty(condition))
            {
                for (int i = 0; i < PlayLogIgnorePatterns.Length; i++)
                {
                    if (condition.IndexOf(PlayLogIgnorePatterns[i], StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        SessionState.SetInt(PlayIgnoredKey, SessionState.GetInt(PlayIgnoredKey, 0) + 1);
                        return;
                    }
                }
            }
            SessionState.SetInt(PlayErrorsKey, SessionState.GetInt(PlayErrorsKey, 0) + 1);
        }

        private static double NowSeconds()
        {
            return DateTime.UtcNow.Ticks / (double)TimeSpan.TicksPerSecond;
        }

        private static double ParseSeconds(string text)
        {
            double value;
            if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out value))
            {
                return value;
            }
            return 0;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 一键热更链路里所有路径/文件名的**唯一来源**。
    ///
    /// 【为什么集中一份】这条链路横跨 4 个目录：
    ///   · 编译产物   HybridCLRData/HotUpdateDlls/&lt;平台&gt;/      （HybridCLR 生成）
    ///   · 随包 dll   Assets/StreamingAssets/HybridCLR/          （dll 热更的"原点"）
    ///   · AB 构建    Bundles/&lt;平台&gt;/FreeTower/&lt;版本&gt;/       （YooAsset 输出）
    ///   · 服务器根   HotUpdateServer/release.json               （最后激活的指针）
    ///   · 不可变内容 releases/{id}/                             （完整 DLL + AB）
    /// 客户端固定同一 release 的 resourceVersion、manifestMd5 和 DLL 校验值。
    /// 不再把根目录 FreeTower.version 或 Android/HybridCLR 当作新启动协议入口。
    /// </summary>
    public static class HotUpdatePaths
    {
        /// <summary>YooAsset 包裹名（= AB 输出目录名，改了热更必失效）。</summary>
        public const string PackageName = "FreeTower";

        /// <summary>随包 dll 子目录（运行时按此路径读）。</summary>
        public const string DllFolderName = "HybridCLR";

        /// <summary>YooAsset 版本文件名（位于不可变 release 内；旧部署探测也可读取）。</summary>
        public const string VersionFileName = "FreeTower.version";

        /// <summary>本地热更服务器根（git 忽略，各机自建；HTTP 8000 指向它）。</summary>
        public const string CdnRootRelative = "HotUpdateServer";

        /// <summary>构建记录/历史目录（git 忽略，只本机用）。</summary>
        public const string StateDirRelative = "Library/FT_HotUpdate";

        /// <summary>外部轮询用状态文件（MCP / CI 读它判断流水线进度）。</summary>
        public const string StatusFileRelative = "Library/FT_HotUpdateStatus.txt";

        /// <summary>本次运行日志（面板展示 + 失败时贴给同事）。</summary>
        public const string LogFileRelative = "Logs/HotUpdate/last_run.log";

        /// <summary>部署到服务器根的清单文件名（服务端可读，客户端不读）。</summary>
        public const string ManifestFileName = "hotupdate_manifest.json";

        /// <summary>工程根（不依赖进程工作目录：batchmode 的 cwd 未必是工程根）。</summary>
        public static string ProjectRoot
        {
            get { return Path.GetDirectoryName(Application.dataPath); }
        }

        /// <summary>把工程内相对路径转成绝对路径（分隔符统一）。</summary>
        public static string Resolve(string relative)
        {
            if (string.IsNullOrEmpty(relative))
            {
                return ProjectRoot;
            }
            return Path.Combine(ProjectRoot, relative.Replace('/', Path.DirectorySeparatorChar));
        }

        public static string CdnRoot { get { return Resolve(CdnRootRelative); } }

        /// <summary>随包 dll 目录（md5 清单也在这里）。</summary>
        public static string DllDir
        {
            get { return Path.Combine(Application.dataPath, "StreamingAssets", DllFolderName); }
        }

        public static string StateDir { get { return Resolve(StateDirRelative); } }

        public static string StatusFile { get { return Resolve(StatusFileRelative); } }

        public static string LogFile { get { return Resolve(LogFileRelative); } }

        /// <summary>当前构建目标的平台目录名（Android / iOS / StandaloneWindows64 …）。</summary>
        public static string PlatformFolder
        {
            get { return EditorUserBuildSettings.activeBuildTarget.ToString(); }
        }

        /// <summary>AB 构建根：Bundles/&lt;平台&gt;/&lt;包裹&gt;（YooAsset 默认输出根）。</summary>
        public static string BuildRoot(BuildTarget target)
        {
            return Path.Combine(ProjectRoot, "Bundles", target.ToString(), PackageName);
        }

        public static string BuildRoot()
        {
            return BuildRoot(EditorUserBuildSettings.activeBuildTarget);
        }

        /// <summary>某版本的 AB 输出目录：Bundles/&lt;平台&gt;/&lt;包裹&gt;/&lt;版本&gt;。</summary>
        public static string BuildDir(BuildTarget target, string version)
        {
            return Path.Combine(BuildRoot(target), version);
        }

        public static string BuildDir(string version)
        {
            return BuildDir(EditorUserBuildSettings.activeBuildTarget, version);
        }

        /// <summary>仅供旧工具识别历史布局；新发布使用 release.contentRoot + /HybridCLR。</summary>
        public static string DllServerRelative
        {
            get { return PlatformFolder + "/" + DllFolderName; }
        }
    }

    /// <summary>
    /// 一键热更的可调项。
    ///
    /// 【存哪】EditorPrefs（机器级）。理由：
    ///   · 远端上传地址/凭据是**本机环境**，不该进 git（进 git 会随仓库泄给所有人）；
    ///   · 版本号覆盖、是否 Play 冒烟属于"这次想怎么跑"，跨会话记住比每次重填省事。
    /// 单次运行的快照另外写进 SessionState（域重载后不丢），见 <see cref="HotUpdateOptions"/>。
    /// </summary>
    public static class HotUpdateSettings
    {
        private const string Prefix = "FT.HotUpdate.";

        /// <summary>① 部署到本地 HotUpdateServer（默认开：模拟器/真机都靠它）。</summary>
        public static bool DeployLocal
        {
            get { return EditorPrefs.GetBool(Prefix + "DeployLocal", true); }
            set { EditorPrefs.SetBool(Prefix + "DeployLocal", value); }
        }

        /// <summary>② 上传到远端资源服务器（默认关：没配地址时不要误触发）。</summary>
        public static bool UploadRemote
        {
            get { return EditorPrefs.GetBool(Prefix + "UploadRemote", false); }
            set { EditorPrefs.SetBool(Prefix + "UploadRemote", value); }
        }

        /// <summary>远端根地址，如 https://cdn.example.com/freedomtower（不带结尾斜杠）。</summary>
        public static string RemoteBaseUrl
        {
            get { return EditorPrefs.GetString(Prefix + "RemoteBaseUrl", ""); }
            set { EditorPrefs.SetString(Prefix + "RemoteBaseUrl", (value ?? "").Trim()); }
        }

        /// <summary>可选附加请求头，格式 "Name: Value"（如 Authorization: Bearer xxx）。</summary>
        public static string RemoteHeader
        {
            get { return EditorPrefs.GetString(Prefix + "RemoteHeader", ""); }
            set { EditorPrefs.SetString(Prefix + "RemoteHeader", (value ?? "").Trim()); }
        }

        /// <summary>③ 构建完成后做本地运行验证（文件完整性 + HTTP 链路）。</summary>
        public static bool VerifyAfterBuild
        {
            get { return EditorPrefs.GetBool(Prefix + "Verify", true); }
            set { EditorPrefs.SetBool(Prefix + "Verify", value); }
        }

        /// <summary>④ 验证后进入 Play 观察 8 秒（默认关：会占用编辑器）。</summary>
        public static bool PlaySmoke
        {
            get { return EditorPrefs.GetBool(Prefix + "PlaySmoke", false); }
            set { EditorPrefs.SetBool(Prefix + "PlaySmoke", value); }
        }

        /// <summary>⑤ 彻底重建 AB（清空 SBP 缓存与整个包裹根），默认关。</summary>
        public static bool FullRebuild
        {
            get { return EditorPrefs.GetBool(Prefix + "FullRebuild", false); }
            set { EditorPrefs.SetBool(Prefix + "FullRebuild", value); }
        }

        /// <summary>手动指定版本号（留空 = 自动递增）。</summary>
        public static string VersionOverride
        {
            get { return EditorPrefs.GetString(Prefix + "Version", ""); }
            set { EditorPrefs.SetString(Prefix + "Version", (value ?? "").Trim()); }
        }

        /// <summary>本地验证用的端口（与 HotUpdateServer 的 HTTP 端口一致，默认 8000）。</summary>
        public static int VerifyPort
        {
            get { return EditorPrefs.GetInt(Prefix + "Port", 8000); }
            set { EditorPrefs.SetInt(Prefix + "Port", value); }
        }
    }

    /// <summary>
    /// 单次运行的选项快照（进 SessionState，域重载后继续按原选项跑）。
    ///
    /// 【为什么不用 static 字段】HybridCLR Generate/All 会重写 AOTGenericReferences.cs，
    /// 触发编译 + 域重载；static 字段会被清空，流水线就会"忘了自己要部署到哪"。
    /// </summary>
    [Serializable]
    public class HotUpdateOptions
    {
        public bool local;
        public bool remote;
        public bool verify;
        public bool play;
        public bool fullRebuild;
        public bool verifyOnly;
        public string remoteUrl;
        public string remoteHeader;
        public string versionOverride;

        public static HotUpdateOptions FromSettings(bool verifyOnly)
        {
            HotUpdateOptions o = new HotUpdateOptions();
            o.verifyOnly = verifyOnly;
            o.local = HotUpdateSettings.DeployLocal;
            o.remote = HotUpdateSettings.UploadRemote;
            o.verify = HotUpdateSettings.VerifyAfterBuild;
            o.play = HotUpdateSettings.PlaySmoke && !verifyOnly;
            o.fullRebuild = HotUpdateSettings.FullRebuild && !verifyOnly;
            o.remoteUrl = HotUpdateSettings.RemoteBaseUrl;
            o.remoteHeader = HotUpdateSettings.RemoteHeader;
            o.versionOverride = verifyOnly ? "" : HotUpdateSettings.VersionOverride;
            return o;
        }

        /// <summary>写回 EditorPrefs（只写"下次也想要"的项，verifyOnly 是单次语义）。</summary>
        public void SaveToSettings()
        {
            HotUpdateSettings.DeployLocal = local;
            HotUpdateSettings.UploadRemote = remote;
            HotUpdateSettings.RemoteBaseUrl = remoteUrl;
            HotUpdateSettings.RemoteHeader = remoteHeader;
            HotUpdateSettings.VerifyAfterBuild = verify;
            HotUpdateSettings.PlaySmoke = play;
            HotUpdateSettings.FullRebuild = fullRebuild;
            HotUpdateSettings.VersionOverride = versionOverride;
        }
    }

    /// <summary>
    /// 资源包版本号的解析 / 扫描 / 自增。
    ///
    /// 【为什么"自增"要三处取最大】历史实现只扫 Bundles 目录（BuildApkFull / ReporterHotfixBuild
    /// 都一样）。但 Bundles 是 git 忽略的构建产物，换机、清缓存、或只 pull 了别人出的包时，
    /// 本地目录可能比服务器旧 → 直接扫会**撞回一个已经发布过的版本号**，客户端因为
    /// "版本号没变"而完全不下载（表现为"改了代码但真机没反应"）。
    /// 因此这里取三者最大：①本地已构建的版本 ②服务器 release.json ③上次构建记录。
    /// </summary>
    public static class HotUpdateVersionUtil
    {
        public static bool TryParse(string version, out int major, out int minor, out int patch)
        {
            major = minor = patch = 0;
            if (string.IsNullOrEmpty(version))
            {
                return false;
            }
            string[] parts = version.Trim().Split('.');
            if (parts.Length != 3)
            {
                return false;
            }
            return int.TryParse(parts[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out major)
                && int.TryParse(parts[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out minor)
                && int.TryParse(parts[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out patch);
        }

        public static bool IsValid(string version)
        {
            int a, b, c;
            return TryParse(version, out a, out b, out c);
        }

        public static string Bump(string version)
        {
            int major, minor, patch;
            if (!TryParse(version, out major, out minor, out patch))
            {
                return "1.0.0";
            }
            return string.Format(CultureInfo.InvariantCulture, "{0}.{1}.{2}", major, minor, patch + 1);
        }

        private static int Compare(string a, string b)
        {
            int am, an, ap, bm, bn, bp;
            if (!TryParse(a, out am, out an, out ap)) return -1;
            if (!TryParse(b, out bm, out bn, out bp)) return 1;
            if (am != bm) return am.CompareTo(bm);
            if (an != bn) return an.CompareTo(bn);
            return ap.CompareTo(bp);
        }

        /// <summary>已激活 release.json 的资源版本；无新协议指针时兼容旧版本文件。</summary>
        public static string GetDeployedVersion()
        {
            try
            {
                string pointer = Path.Combine(HotUpdatePaths.CdnRoot, "release.json");
                if (File.Exists(pointer))
                {
                    var release = JsonUtility.FromJson<FTProject.AOT.BootRelease>(File.ReadAllText(pointer));
                    return release != null && IsValid(release.resourceVersion) ? release.resourceVersion : "";
                }
                string file = Path.Combine(HotUpdatePaths.CdnRoot, HotUpdatePaths.VersionFileName);
                if (File.Exists(file))
                {
                    return File.ReadAllText(file).Trim();
                }
            }
            catch (Exception)
            {
                // 读不到不算错误：下面还有两个来源兜底
            }
            return "";
        }

        /// <summary>上次通过本面板构建的版本（Library/FT_Hot_update/last_version.txt）。</summary>
        public static string GetRecordedVersion()
        {
            try
            {
                string file = Path.Combine(HotUpdatePaths.StateDir, "last_version.txt");
                if (File.Exists(file))
                {
                    return File.ReadAllText(file).Trim();
                }
            }
            catch (Exception)
            {
            }
            return "";
        }

        /// <summary>本地已构建过的版本号（Bundles/&lt;平台&gt;/FreeTower 下的 x.y.z 目录）。</summary>
        public static List<string> ListBuiltVersions()
        {
            List<string> list = new List<string>();
            string root = HotUpdatePaths.BuildRoot();
            if (!Directory.Exists(root))
            {
                return list;
            }
            foreach (string dir in Directory.GetDirectories(root))
            {
                string name = Path.GetFileName(dir);
                if (IsValid(name))
                {
                    list.Add(name);
                }
            }
            return list;
        }

        /// <summary>本机/服务器上的最大版本（没有则空串）。</summary>
        public static string GetMaxKnownVersion()
        {
            string best = "";
            foreach (string v in ListBuiltVersions())
            {
                if (best.Length == 0 || Compare(v, best) > 0)
                {
                    best = v;
                }
            }
            string deployed = GetDeployedVersion();
            if (IsValid(deployed) && (best.Length == 0 || Compare(deployed, best) > 0))
            {
                best = deployed;
            }
            string recorded = GetRecordedVersion();
            if (IsValid(recorded) && (best.Length == 0 || Compare(recorded, best) > 0))
            {
                best = recorded;
            }
            return best;
        }

        /// <summary>下一个要用的版本号（自动递增）。</summary>
        public static string Next()
        {
            string best = GetMaxKnownVersion();
            return best.Length == 0 ? "1.0.0" : Bump(best);
        }

        /// <summary>面板上显示的一行摘要（"本地最高 1.0.4 · 服务器 1.0.2 · 下一个 1.0.5"）。</summary>
        public static string Describe()
        {
            string deployed = GetDeployedVersion();
            string built = "";
            foreach (string v in ListBuiltVersions())
            {
                if (built.Length == 0 || Compare(v, built) > 0)
                {
                    built = v;
                }
            }
            return string.Format(
                "本地最高 {0} · 服务器 {1} · 下一个 {2}",
                built.Length == 0 ? "（无）" : built,
                deployed.Length == 0 ? "（无）" : deployed,
                Next());
        }
    }

    /// <summary>文件杂项（md5 / 大小 / 写文件 / 链接目录判定）。</summary>
    public static class HotUpdateFileUtil
    {
        /// <summary>流式计算 md5（32 位小写）。大 bundle 也不吃内存。</summary>
        public static string Md5(string path)
        {
            using (MD5 md5 = MD5.Create())
            using (FileStream stream = File.OpenRead(path))
            {
                byte[] hash = md5.ComputeHash(stream);
                StringBuilder sb = new StringBuilder(hash.Length * 2);
                for (int i = 0; i < hash.Length; i++)
                {
                    sb.Append(hash[i].ToString("x2"));
                }
                return sb.ToString();
            }
        }

        public static string FormatSize(long bytes)
        {
            if (bytes < 1024) return bytes + " B";
            if (bytes < 1024 * 1024) return (bytes / 1024f).ToString("F1") + " KB";
            if (bytes < 1024L * 1024 * 1024) return (bytes / 1024f / 1024f).ToString("F2") + " MB";
            return (bytes / 1024f / 1024f / 1024f).ToString("F2") + " GB";
        }

        public static void WriteText(string path, string text)
        {
            string dir = Path.GetDirectoryName(path);
            if (!string.IsNullOrEmpty(dir))
            {
                Directory.CreateDirectory(dir);
            }
            File.WriteAllText(path, text, new UTF8Encoding(false));
        }

        /// <summary>
        /// 目录是否是"链接/联接"（本项目 HotUpdateServer/Android/HybridCLR 是指向
        /// StreamingAssets/HybridCLR 的 junction）。往 junction 里拷 = 往源目录拷，
        /// 源和目标是同一批文件时会抛 IOException，必须先判定再跳过。
        /// 用 FileAttributes.ReparsePoint 判定（.NET Standard 2.1 没有 ResolveLinkTarget）。
        /// </summary>
        public static bool IsReparsePoint(string dir)
        {
            try
            {
                if (!Directory.Exists(dir))
                {
                    return false;
                }
                FileAttributes attr = File.GetAttributes(dir);
                return (attr & FileAttributes.ReparsePoint) == FileAttributes.ReparsePoint;
            }
            catch (Exception)
            {
                return false;
            }
        }

        /// <summary>
        /// 是否是 YooAsset 的"裸哈希特殊包"文件名（unitymonos / unityshaders）。
        /// 这两个包文件名 = 32 位小写哈希、**不带 .bundle**，漏拷会导致跨版本加载场景 404。
        /// </summary>
        public static bool IsBareHashFile(string fileName)
        {
            if (string.IsNullOrEmpty(fileName) || fileName.Length != 32)
            {
                return false;
            }
            for (int i = 0; i < fileName.Length; i++)
            {
                char c = fileName[i];
                bool hex = (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
                if (!hex)
                {
                    return false;
                }
            }
            return true;
        }

        /// <summary>递归删除目录（不存在时静默）。</summary>
        public static void DeleteDirectory(string dir)
        {
            try
            {
                if (Directory.Exists(dir))
                {
                    Directory.Delete(dir, true);
                }
            }
            catch (Exception)
            {
            }
        }
    }
}

using System;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 一键热更面板：**一个按钮**跑完
    /// 重编 dll ▸ 同步 dll+md5 ▸ Ab（版本自增） ▸ 清单 ▸ 部署 ▸ 上传 ▸ 本地验证 ▸（可选）Play 冒烟。
    ///
    /// ==================================================================
    /// 【为什么做成窗口而不是只有一个菜单项】
    ///   这条链路要跑几分钟，过程中最需要知道三件事：
    ///     ① 现在到第几步了（哪一步最慢/最可疑）
    ///     ② 这一步之后还剩什么（部署/上传/验证是否被跳过）
    ///     ③ 失败了到底卡在哪（红字 + 日志尾）
    ///   只有 Console 的话，第 ① ② 都看不出来；所以窗口里给步骤条 + 进度条 + 日志尾。
    ///
    /// 【不弹任何确认框】项目约定：编辑器脚本弹 DisplayDialog 会阻塞 MCP / CI 主线程。
    ///   有风险的项（远端上传、Play 冒烟）改成**显式勾选**，勾了才做。
    ///
    /// 【菜单】
    ///   10.  打开面板
    ///   10a. 按上次选项立即执行
    ///   10b. 仅本地验证（不构建，校验服务器上当前这一版）
    ///   10c. 本地热更服务器 起/停（真机前手动开着的那个 HTTP 服务）
    /// ==================================================================
    /// </summary>
    public class HotUpdateWindow : EditorWindow
    {
        private const string MenuRoot = "Tools/塔防/";
        private const string MenuOpen = MenuRoot + "10. 一键热更…（DLL▸AB▸部署▸验证）";
        private const string MenuRun = MenuRoot + "10a. 一键热更·立即执行（按上次选项）";
        private const string MenuVerify = MenuRoot + "10b. 本地运行验证（不构建，校验当前部署）";
        private const string MenuServer = MenuRoot + "10c. 本地热更服务器（起/停）";

        private Vector2 _logScroll;
        private Vector2 _stepScroll;
        private bool _showOptions = true;
        private string _logText = "";
        private double _logReadAt;
        private string _versionSummary = "";
        private double _versionReadAt;
        private double _nextRepaint;

        // ------------------------------------------------------------------
        // 菜单
        // ------------------------------------------------------------------

        [MenuItem(MenuOpen, false, 114)]
        public static void Open()
        {
            HotUpdateWindow window = GetWindow<HotUpdateWindow>(false, "一键热更", true);
            window.minSize = new Vector2(620f, 560f);
            window.Show();
        }

        [MenuItem(MenuRun, false, 115)]
        public static void RunNow()
        {
            HotUpdatePipeline.StartFull();
        }

        [MenuItem(MenuVerify, false, 116)]
        public static void VerifyNow()
        {
            HotUpdatePipeline.StartVerifyOnly();
        }

        [MenuItem(MenuServer, false, 117)]
        public static void ToggleServer()
        {
            if (HotUpdateLocalServer.IsRunning)
            {
                HotUpdateLocalServer.Stop();
                Debug.Log("[HotUpdate] 本地热更服务器已停止。");
                return;
            }

            string error;
            if (HotUpdateLocalServer.Start(HotUpdatePaths.CdnRoot, HotUpdateSettings.VerifyPort, out error))
            {
                Debug.Log("[HotUpdate] 本地热更服务器：" + HotUpdateLocalServer.Url +
                          "（模拟器用 http://10.0.2.2:" + HotUpdateSettings.VerifyPort + "，真机请用 python 脚本绑 0.0.0.0）");
            }
            else
            {
                Debug.LogError("[HotUpdate] 本地热更服务器启动失败：" + error);
            }
        }

        // ------------------------------------------------------------------
        // 生命周期
        // ------------------------------------------------------------------

        private void OnEnable()
        {
            EditorApplication.update += OnEditorUpdate;
        }

        private void OnDisable()
        {
            EditorApplication.update -= OnEditorUpdate;
        }

        private void OnEditorUpdate()
        {
            if (!HotUpdatePipeline.IsRunning)
            {
                return;
            }
            if (EditorApplication.timeSinceStartup < _nextRepaint)
            {
                return;
            }
            _nextRepaint = EditorApplication.timeSinceStartup + 0.2;
            Repaint();
        }

        // ------------------------------------------------------------------
        // 绘制
        // ------------------------------------------------------------------

        private void OnGUI()
        {
            DrawTitle();
            DrawStatus();
            EditorGUILayout.Space();

            DrawSteps();
            EditorGUILayout.Space();

            DrawProgress();
            EditorGUILayout.Space();

            _showOptions = EditorGUILayout.Foldout(_showOptions, "选项（勾选项会直接记住）", true);
            if (_showOptions)
            {
                DrawOptions();
            }

            EditorGUILayout.Space();
            DrawButtons();
            EditorGUILayout.Space();

            DrawLog();
        }

        private void DrawTitle()
        {
            EditorGUILayout.LabelField("一键热更", EditorStyles.boldLabel);
            EditorGUILayout.LabelField(
                "重编 dll ▸ 同步 dll+md5 ▸ 构建 AB（版本自增） ▸ 清单 ▸ 部署 ▸ 上传 ▸ 本地验证 ▸ Play 冒烟",
                EditorStyles.miniLabel);
        }

        private void DrawStatus()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);

            EditorGUILayout.LabelField("当前平台",
                HotUpdatePaths.PlatformFolder + "（构建目标 " +
                EditorUserBuildSettings.activeBuildTarget + "）");

            EditorGUILayout.LabelField("本地服务器根", HotUpdatePaths.CdnRoot);
            EditorGUILayout.LabelField("随包 dll 目录", HotUpdatePaths.DllDir);

            if (string.IsNullOrEmpty(_versionSummary) || EditorApplication.timeSinceStartup - _versionReadAt > 2.0)
            {
                _versionSummary = HotUpdateVersionUtil.Describe();
                _versionReadAt = EditorApplication.timeSinceStartup;
            }
            EditorGUILayout.LabelField("版本号", _versionSummary);

            bool serverRunning = HotUpdateLocalServer.IsRunning;
            EditorGUILayout.LabelField("本地热更服务器",
                serverRunning
                    ? HotUpdateLocalServer.Url + "（已服务 " + HotUpdateLocalServer.ServedCount + " 个请求）"
                    : "未启动（点 10c 或面板按钮启动）");

            string phase = HotUpdatePipeline.CurrentPhase;
            string phaseText;
            if (HotUpdatePipeline.IsRunning)
            {
                phaseText = "运行中 · " + PhaseTitle(phase) + (string.IsNullOrEmpty(HotUpdatePipeline.JobText)
                    ? "" : " · " + HotUpdatePipeline.JobText);
            }
            else if (phase == "Done")
            {
                phaseText = "上一次已完成 · v" + HotUpdatePipeline.CurrentVersion;
            }
            else if (phase == "Fail")
            {
                phaseText = "上一次失败 · v" + HotUpdatePipeline.CurrentVersion;
            }
            else
            {
                phaseText = "空闲";
            }
            EditorGUILayout.LabelField("流水线", phaseText);

            if (phase == "Fail" && !string.IsNullOrEmpty(HotUpdatePipeline.LastError))
            {
                EditorGUILayout.HelpBox(HotUpdatePipeline.LastError, MessageType.Error);
            }

            if (EditorApplication.isPlaying)
            {
                EditorGUILayout.HelpBox("编辑器在 Play 模式：热更与构建都不可用，请先退出。", MessageType.Warning);
            }
            else if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                EditorGUILayout.HelpBox("编辑器正在编译 / 导入资源，流水线会自动等待。", MessageType.Info);
            }
            else if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                EditorGUILayout.HelpBox("当前构建目标不是 Android：热更 dll / AB 会打到错误平台。", MessageType.Warning);
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawSteps()
        {
            EditorGUILayout.LabelField("步骤", EditorStyles.boldLabel);

            _stepScroll = EditorGUILayout.BeginScrollView(_stepScroll, GUILayout.Height(200f));
            for (int i = 0; i < HotUpdatePipeline.Phases.Length - 1; i++) // 最后一项 Done 不单独画
            {
                string phase = HotUpdatePipeline.Phases[i];
                string title = HotUpdatePipeline.PhaseTitles[i];
                string detail = StepDetail(phase);

                Color old = GUI.color;
                GUI.color = StepColor(i);
                EditorGUILayout.LabelField(StepIcon(i) + "  " + (i + 1) + ". " + title +
                                           (string.IsNullOrEmpty(detail) ? "" : "    " + detail),
                    EditorStyles.miniLabel);
                GUI.color = old;
            }
            EditorGUILayout.EndScrollView();
        }

        private void DrawProgress()
        {
            Rect rect = EditorGUILayout.GetControlRect(false, 20f);
            float value = HotUpdatePipeline.Progress01;
            string label;
            if (HotUpdatePipeline.IsRunning)
            {
                string job = HotUpdatePipeline.JobText;
                if (!string.IsNullOrEmpty(job) && HotUpdatePipeline.JobProgress01 > 0f)
                {
                    // 异步阶段（上传/校验）用"文件级"进度，比阶段进度更细
                    label = job;
                    value = Mathf.Lerp(value, HotUpdatePipeline.JobProgress01, 0.6f);
                }
                else
                {
                    label = PhaseTitle(HotUpdatePipeline.CurrentPhase);
                }
            }
            else
            {
                label = HotUpdatePipeline.CurrentPhase == "Done" ? "完成" : "就绪";
                value = HotUpdatePipeline.CurrentPhase == "Done" ? 1f : 0f;
            }
            EditorGUI.ProgressBar(rect, value, label);
        }

        private void DrawOptions()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);

            HotUpdateSettings.DeployLocal = EditorGUILayout.ToggleLeft(
                "① 部署到本地资源服务器（HotUpdateServer，模拟器 / 真机联调用）",
                HotUpdateSettings.DeployLocal);

            HotUpdateSettings.VerifyAfterBuild = EditorGUILayout.ToggleLeft(
                "② 构建后本地运行验证（文件完整性 + HTTP 链路，失败即中断）",
                HotUpdateSettings.VerifyAfterBuild);

            HotUpdateSettings.PlaySmoke = EditorGUILayout.ToggleLeft(
                "③ 验证后进入 Play 冒烟（Main 场景跑 8 秒，统计错误日志）",
                HotUpdateSettings.PlaySmoke);

            HotUpdateSettings.FullRebuild = EditorGUILayout.ToggleLeft(
                "④ 彻底重建 AB（清空 SBP 缓存与整个包裹根目录，慢）",
                HotUpdateSettings.FullRebuild);

            EditorGUILayout.Space();
            HotUpdateSettings.UploadRemote = EditorGUILayout.ToggleLeft(
                "⑤ 上传到远端资源服务器（HTTP PUT）",
                HotUpdateSettings.UploadRemote);
            using (new EditorGUI.DisabledScope(!HotUpdateSettings.UploadRemote))
            {
                HotUpdateSettings.RemoteBaseUrl = EditorGUILayout.TextField(
                    new GUIContent("远端根地址", "例如 https://cdn.example.com/freedomtower（不带结尾斜杠）"),
                    HotUpdateSettings.RemoteBaseUrl);
                HotUpdateSettings.RemoteHeader = EditorGUILayout.TextField(
                    new GUIContent("附加请求头", "格式 Name: Value，例如 Authorization: Bearer xxx（可留空）"),
                    HotUpdateSettings.RemoteHeader);
                EditorGUILayout.LabelField("",
                    string.IsNullOrEmpty(HotUpdateSettings.RemoteBaseUrl)
                        ? "未配置地址 → 勾了也会在预检后中断（不会静默跳过）"
                        : "上传顺序：AB 文件 → dll → 清单；任一失败即中断",
                    EditorStyles.miniLabel);
            }

            EditorGUILayout.Space();
            HotUpdateSettings.VersionOverride = EditorGUILayout.TextField(
                new GUIContent("版本号覆盖", "留空 = 自动递增（本地最高/服务器版本/上次记录三者取最大 +1）"),
                HotUpdateSettings.VersionOverride);
            HotUpdateSettings.VerifyPort = EditorGUILayout.IntField(
                new GUIContent("本地验证端口", "与 HotUpdateServer 的 HTTP 端口一致，默认 8000"),
                HotUpdateSettings.VerifyPort);

            EditorGUILayout.EndVertical();
        }

        private void DrawButtons()
        {
            EditorGUILayout.BeginHorizontal();

            using (new EditorGUI.DisabledScope(HotUpdatePipeline.IsRunning || EditorApplication.isPlaying
                                               || EditorApplication.isCompiling || EditorApplication.isUpdating))
            {
                if (GUILayout.Button("开始一键热更", GUILayout.Height(30f)))
                {
                    HotUpdatePipeline.StartFull();
                }
                if (GUILayout.Button("仅本地验证", GUILayout.Height(30f), GUILayout.Width(110f)))
                {
                    HotUpdatePipeline.StartVerifyOnly();
                }
            }

            using (new EditorGUI.DisabledScope(!HotUpdatePipeline.IsRunning))
            {
                if (GUILayout.Button("取消", GUILayout.Height(30f), GUILayout.Width(70f)))
                {
                    HotUpdatePipeline.Cancel();
                }
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.BeginHorizontal();
            if (GUILayout.Button("打开服务器目录", GUILayout.Height(22f)))
            {
                Reveal(HotUpdatePaths.CdnRoot);
            }
            if (GUILayout.Button("打开构建输出", GUILayout.Height(22f)))
            {
                string dir = HotUpdatePaths.BuildDir(HotUpdatePipeline.CurrentVersion);
                Reveal(Directory.Exists(dir) ? dir : HotUpdatePaths.BuildRoot());
            }
            if (GUILayout.Button("打开日志", GUILayout.Height(22f)))
            {
                Reveal(File.Exists(HotUpdateLog.FilePath) ? HotUpdateLog.FilePath : HotUpdatePaths.StateDir);
            }
            if (GUILayout.Button(HotUpdateLocalServer.IsRunning ? "停止本地服务" : "启动本地服务",
                    GUILayout.Height(22f)))
            {
                ToggleServer();
            }
            EditorGUILayout.EndHorizontal();
        }

        private void DrawLog()
        {
            EditorGUILayout.LabelField("日志（Logs/HotUpdate/last_run.log）", EditorStyles.boldLabel);

            if (EditorApplication.timeSinceStartup - _logReadAt > 0.4)
            {
                _logText = HotUpdateLog.Tail(7000);
                _logReadAt = EditorApplication.timeSinceStartup;
            }

            using (EditorGUILayout.ScrollViewScope scroll = new EditorGUILayout.ScrollViewScope(
                       _logScroll, GUILayout.Height(180f), GUILayout.ExpandWidth(true)))
            {
                _logScroll = scroll.scrollPosition;
                if (string.IsNullOrEmpty(_logText))
                {
                    EditorGUILayout.LabelField("（还没有运行记录）", EditorStyles.miniLabel);
                }
                else
                {
                    EditorGUILayout.LabelField(_logText, EditorStyles.wordWrappedMiniLabel);
                }
            }
        }

        // ------------------------------------------------------------------
        // 小工具
        // ------------------------------------------------------------------

        private static string PhaseTitle(string phase)
        {
            int index = Array.IndexOf(HotUpdatePipeline.Phases, phase);
            if (index < 0)
            {
                return phase;
            }
            return HotUpdatePipeline.PhaseTitles[index];
        }

        /// <summary>0=待执行 1=进行中 2=成功 3=跳过 4=失败。</summary>
        private static int StepState(int index)
        {
            string phase = HotUpdatePipeline.CurrentPhase;
            HotUpdateOptions options = HotUpdatePipeline.Options;

            // 仅验证模式：前面的构建阶段都不做
            if (options.verifyOnly && index < Array.IndexOf(HotUpdatePipeline.Phases, "Verify"))
            {
                return 3;
            }

            // 未勾选的阶段：显示为跳过（避免"跑完了但什么都没做"的误解）
            string id = HotUpdatePipeline.Phases[index];
            if ((id == "DeployLocal" && !options.local)
                || (id == "UploadRemote" && !options.remote)
                || (id == "Verify" && !options.verify)
                || ((id == "PlaySmokeStart" || id == "PlaySmokeWait") && !options.play))
            {
                return 3;
            }

            if (phase == "Done")
            {
                return 2;
            }

            int current = HotUpdatePipeline.StepIndex;
            if (phase == "Fail")
            {
                if (index < current) return 2;
                if (index == current) return 4;
                return 0;
            }
            if (index < current) return 2;
            if (index == current) return 1;
            return 0;
        }

        private static string StepIcon(int index)
        {
            switch (StepState(index))
            {
                case 1: return "▶";
                case 2: return "✔";
                case 3: return "·";
                case 4: return "✘";
                default: return "○";
            }
        }

        private static Color StepColor(int index)
        {
            switch (StepState(index))
            {
                case 1: return new Color(0.45f, 0.75f, 1f);
                case 2: return new Color(0.45f, 0.85f, 0.45f);
                case 4: return new Color(1f, 0.45f, 0.45f);
                case 3: return new Color(0.6f, 0.6f, 0.6f);
                default: return Color.gray;
            }
        }

        private static string StepDetail(string phase)
        {
            int index = Array.IndexOf(HotUpdatePipeline.Phases, phase);
            int state = StepState(index);
            HotUpdateOptions options = HotUpdatePipeline.Options;

            if (state == 3)
            {
                if (options.verifyOnly && index < Array.IndexOf(HotUpdatePipeline.Phases, "Verify"))
                {
                    return "（仅验证模式跳过）";
                }
                return "（未启用）";
            }
            if (state == 1 && !string.IsNullOrEmpty(HotUpdatePipeline.JobText))
            {
                return "（" + HotUpdatePipeline.JobText + "）";
            }
            if (phase == "AbBuild" && !string.IsNullOrEmpty(HotUpdatePipeline.CurrentVersion))
            {
                return "（v" + HotUpdatePipeline.CurrentVersion + "）";
            }
            return "";
        }

        private static void Reveal(string path)
        {
            if (string.IsNullOrEmpty(path))
            {
                return;
            }
            if (File.Exists(path) || Directory.Exists(path))
            {
                EditorUtility.RevealInFinder(path);
            }
            else
            {
                Debug.LogWarning("[HotUpdate] 路径还不存在：" + path);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// HybridCLR 热更产物搬运工具。
    ///
    /// ==================================================================
    /// 【为什么需要这个工具】
    ///   `HybridCLR ▸ Generate ▸ All` 把热更 dll 编译到
    ///      HybridCLRData/HotUpdateDlls/{平台}/
    ///   这个目录**不在 Assets 下**，不会被 Unity 打进包体，运行时的
    ///   `Application.streamingAssetsPath` 里根本没有这些 dll。
    ///
    ///   所以需要在打包前把它们拷进 `Assets/StreamingAssets/HybridCLR/`，
    ///   运行时由 HotUpdateAssembler.ReadDllBytes 的 ② 分支读到。
    ///
    /// 【为什么 dll 名单从这个文件里来，而不是再写一份】
    ///   热更 dll 名单在运行时侧是 `FTProject.AOT.HotUpdateAssembler.HotUpdateAssemblies`，
    ///   编辑器侧**不能直接引用它**（会引入 FTProject.AOT 依赖，且它是 AOT 程序集，
    ///   编辑器工具引用它虽然可以，但会绕开"编辑器工具只依赖 Runtime"的既有分层）。
    ///   所以这里用菜单交互时**从磁盘扫描**：把 HybridCLRData 里编译出来的、
    ///   且属于本工程热更集的 dll 拷过去。
    ///   判定依据 = HybridCLRSettings.asset 的 hotUpdateAssemblies 列表（唯一权威来源）。
    /// ==================================================================
    /// </summary>
    public static class HybridCLRDllCopier
    {
        /// <summary>拷入 StreamingAssets 后的子目录名（运行时按此路径读）。</summary>
        private const string DestSubDir = "HybridCLR";

        [MenuItem("Tools/塔防/HybridCLR/1. 拷贝热更 dll 到 StreamingAssets", false, 300)]
        public static void CopyFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            Copy(report);
            AssetDatabase.Refresh();
            // 【为什么不弹 DisplayDialog】弹窗会阻塞自动化脚本（MCP / CI）的继续执行。
            // 结果全部打进 Console 即可，需要看细节时去 Console 查。
            if (report.Errors > 0)
            {
                Debug.LogError("[HybridCLR] 拷贝热更 dll 失败：\n" + report.Text);
            }
            else
            {
                Debug.Log("[HybridCLR] 拷贝热更 dll：\n" + report.Text);
            }
        }

        public static void Copy(EditorUtil.Report report)
        {
            report.Head("拷贝 HybridCLR 热更 dll");

            // ① 取当前 build target 对应的编译输出目录
            BuildTarget target = EditorUserBuildSettings.activeBuildTarget;
            string srcDir = Path.Combine("HybridCLRData/HotUpdateDlls", target.ToString());

            if (!Directory.Exists(srcDir))
            {
                report.Error("找不到热更 dll 编译目录：" + srcDir
                    + "（请先执行菜单「HybridCLR ▸ Generate ▸ All」）");
                return;
            }

            // ② 取热更程序集名单（权威来源 = HybridCLRSettings.asset）
            List<string> names = GetHotUpdateAssemblyNames(report);
            if (names == null || names.Count == 0)
            {
                report.Error("HybridCLRSettings.asset 里 hotUpdateAssemblies 为空，" +
                    "请先在「HybridCLR ▸ Settings」里配置热更程序集。");
                return;
            }

            // ③ 拷贝热更 dll
            string dstDir = Path.Combine(Application.dataPath, "StreamingAssets", DestSubDir);
            Directory.CreateDirectory(dstDir);

            int hotCopied = 0;
            for (int i = 0; i < names.Count; i++)
            {
                string dllName = names[i] + ".dll";
                string src = Path.Combine(srcDir, dllName);
                if (!File.Exists(src))
                {
                    report.Error("缺少 dll：" + src + "（该程序集可能未被编译，检查 HybridCLRSettings 是否写错名字）");
                    continue;
                }

                string dst = Path.Combine(dstDir, dllName);
                File.Copy(src, dst, true);

                long size = new FileInfo(dst).Length;
                report.Ok(string.Format("  [热更] {0}  ({1:N0} 字节)", dllName, size));
                hotCopied++;
            }

            report.Ok(string.Format(
                "  目标目录：Assets/StreamingAssets/{0}/（热更 {1} 个 dll）",
                DestSubDir, hotCopied));

            // ④ 拷贝 AOT 补充元数据 dll（★ 必须做，否则 AOT 泛型缺失）
            //    源 = HybridCLRData/AssembliesPostIl2CppStrip/{平台}/，也是 Generate/All 的产物。
            CopyAOTMeta(report, target, dstDir);

            // ⑤ 顺带核对名单同步（名单写岔 = 真机泛型缺失且报错晦涩）
            CheckAOTMetaSync(report);
        }

        /// <summary>
        /// AOT 补充元数据 dll 的运行期名单（与 HotUpdateAssembler.AOTMetaAssemblies 一致）。
        ///
        /// 【为什么编辑器侧要再写一份】编辑器工具不能引用 `FTProject.AOT`（AOT 程序集），
        ///   否则会绕开"编辑器工具只依赖 Runtime"的分层约定。
        ///   → 两份名单必须手工同步，所以下面 CheckAOTMetaSync 会主动比对
        ///     `AOTGenericReferences.cs` 里的 PatchedAOTAssemblyList，不一致就报警。
        ///
        /// ⚠️ 改这里 / 改 HotUpdateAssembler 时必须两边一起改。
        /// </summary>
        private static readonly string[] AOTMetaAssemblies =
        {
            "System.Core.dll",
            "UnityEngine.AssetBundleModule.dll",
            "UnityEngine.CoreModule.dll",
            "UnityEngine.JSONSerializeModule.dll",
            "YooAsset.dll",
            "mscorlib.dll",
        };

        private static void CopyAOTMeta(EditorUtil.Report report, BuildTarget target, string dstDir)
        {
            report.Head("拷贝 HybridCLR AOT 补充元数据 dll");

            string srcDir = Path.Combine("HybridCLRData/AssembliesPostIl2CppStrip", target.ToString());
            if (!Directory.Exists(srcDir))
            {
                report.Warn("找不到 AOT 裁剪产物目录：" + srcDir
                    + "（需先执行「HybridCLR ▸ Generate ▸ All」）");
                return;
            }

            int copied = 0;
            for (int i = 0; i < AOTMetaAssemblies.Length; i++)
            {
                string dllName = AOTMetaAssemblies[i];
                string src = Path.Combine(srcDir, dllName);
                if (!File.Exists(src))
                {
                    report.Warn("AOT 元数据 dll 缺失（名单写了但 Generate/All 未产出）：" + dllName
                        + "  —— 请核对名单是否与 AOTGenericReferences.cs 一致");
                    continue;
                }

                File.Copy(src, Path.Combine(dstDir, dllName), true);
                report.Ok(string.Format("  [AOT ] {0}  ({1:N0} 字节)",
                    dllName, new FileInfo(src).Length));
                copied++;
            }

            report.Ok(string.Format("  AOT 补充元数据：{0}/{1} 个已就位",
                copied, AOTMetaAssemblies.Length));
        }

        /// <summary>
        /// 核对本工具的 AOTMetaAssemblies 与 `AOTGenericReferences.cs` 的
        /// `PatchedAOTAssemblyList` 是否一致。不一致 = 真机泛型缺失风险。
        /// </summary>
        private static void CheckAOTMetaSync(EditorUtil.Report report)
        {
            const string refPath = "Assets/HybridCLRGenerate/AOTGenericReferences.cs";
            string full = Path.Combine(Directory.GetCurrentDirectory(), refPath);
            if (!File.Exists(full))
            {
                report.Warn("找不到 " + refPath + "（需先执行「HybridCLR ▸ Generate ▸ All」）");
                return;
            }

            string text;
            try
            {
                text = File.ReadAllText(full);
            }
            catch (Exception e)
            {
                report.Warn("读取 " + refPath + " 失败：" + e.Message);
                return;
            }

            // 抓 PatchedAOTAssemblyList = new List<string> { "a", "b", ... } 里的字符串
            List<string> expected = new List<string>();
            int listStart = text.IndexOf("PatchedAOTAssemblyList", StringComparison.Ordinal);
            if (listStart >= 0)
            {
                int braceOpen = text.IndexOf('{', listStart);
                int braceClose = braceOpen >= 0 ? text.IndexOf('}', braceOpen) : -1;
                if (braceOpen >= 0 && braceClose > braceOpen)
                {
                    string body = text.Substring(braceOpen + 1, braceClose - braceOpen - 1);
                    int p = 0;
                    while (true)
                    {
                        int q1 = body.IndexOf('"', p);
                        if (q1 < 0) break;
                        int q2 = body.IndexOf('"', q1 + 1);
                        if (q2 < 0) break;
                        expected.Add(body.Substring(q1 + 1, q2 - q1 - 1));
                        p = q2 + 1;
                    }
                }
            }

            if (expected.Count == 0)
            {
                report.Warn("未能从 " + refPath + " 解析出 PatchedAOTAssemblyList（格式可能变了）");
                return;
            }

            // 双向差集
            List<string> onlyInRef = new List<string>();
            List<string> onlyInCode = new List<string>();
            for (int i = 0; i < expected.Count; i++)
            {
                if (Array.IndexOf(AOTMetaAssemblies, expected[i]) < 0) onlyInRef.Add(expected[i]);
            }
            for (int i = 0; i < AOTMetaAssemblies.Length; i++)
            {
                if (expected.IndexOf(AOTMetaAssemblies[i]) < 0) onlyInCode.Add(AOTMetaAssemblies[i]);
            }

            if (onlyInRef.Count == 0 && onlyInCode.Count == 0)
            {
                report.Ok(string.Format(
                    "  AOT 元数据名单与 AOTGenericReferences.cs 一致（{0} 项）", expected.Count));
            }
            else
            {
                if (onlyInRef.Count > 0)
                {
                    report.Warn("AOTGenericReferences 里有、但本工具/加载器名单里没有（会导致泛型缺失）："
                        + string.Join(", ", onlyInRef.ToArray()));
                }
                if (onlyInCode.Count > 0)
                {
                    report.Warn("本工具/加载器名单里有、但 AOTGenericReferences 里没有（多余项）："
                        + string.Join(", ", onlyInCode.ToArray()));
                }
                report.Warn("请同步 HotUpdateAssembler.AOTMetaAssemblies 与 AOTMetaAssemblies（本文件）");
            }
        }

        [MenuItem("Tools/塔防/HybridCLR/3. 拷贝 AOT 补充元数据 dll 到 StreamingAssets", false, 302)]
        public static void CopyAOTMetaFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            BuildTarget target = EditorUserBuildSettings.activeBuildTarget;
            string dstDir = Path.Combine(Application.dataPath, "StreamingAssets", DestSubDir);
            Directory.CreateDirectory(dstDir);
            CopyAOTMeta(report, target, dstDir);
            CheckAOTMetaSync(report);
            AssetDatabase.Refresh();

            if (report.Errors > 0)
            {
                Debug.LogError("[HybridCLR] 拷贝 AOT 补充元数据失败：\n" + report.Text);
            }
            else
            {
                Debug.Log("[HybridCLR] 拷贝 AOT 补充元数据：\n" + report.Text);
            }
        }

        /// <summary>
        /// 从 HybridCLRSettings.asset 读热更程序集名（不含 .dll）。
        /// 用反射读字段，避免编辑器工具直接依赖 HybridCLR.Editor 的命名空间
        /// （这样即使 HybridCLR 包临时缺失，本文件也不会编译不过）。
        /// </summary>
        private static List<string> GetHotUpdateAssemblyNames(EditorUtil.Report report)
        {
            string path = "ProjectSettings/HybridCLRSettings.asset";
            UnityEngine.Object[] objs =
                UnityEditorInternal.InternalEditorUtility.LoadSerializedFileAndForget(path);
            if (objs == null || objs.Length == 0)
            {
                report.Error("读不到 " + path);
                return null;
            }

            System.Reflection.FieldInfo f = objs[0].GetType().GetField("hotUpdateAssemblies");
            if (f == null)
            {
                report.Error("HybridCLRSettings 里找不到 hotUpdateAssemblies 字段");
                return null;
            }

            string[] arr = f.GetValue(objs[0]) as string[];
            List<string> list = new List<string>();
            if (arr != null)
            {
                for (int i = 0; i < arr.Length; i++)
                {
                    if (!string.IsNullOrEmpty(arr[i]))
                    {
                        list.Add(arr[i]);
                    }
                }
            }
            return list;
        }

        [MenuItem("Tools/塔防/HybridCLR/2. 查看热更 dll 状态", false, 301)]
        public static void ReportStatus()
        {
            BuildTarget target = EditorUserBuildSettings.activeBuildTarget;
            string srcDir = Path.Combine("HybridCLRData/HotUpdateDlls", target.ToString());
            string dstDir = Path.Combine(Application.dataPath, "StreamingAssets", DestSubDir);

            Debug.Log(string.Format(
                "[HybridCLR] 热更 dll 状态\n" +
                "  当前平台：{0}\n" +
                "  编译输出：{1}（{2}）\n" +
                "  已拷入包：{3}（{4}）",
                target,
                srcDir, Directory.Exists(srcDir) ? "存在" : "缺失",
                dstDir, Directory.Exists(dstDir) ? "存在" : "缺失"));
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 生成热更 dll 的 **md5 校验清单**（`md5.txt`），供运行时
    /// <c>FTProject.AOT.HotUpdateDllDownloader</c> 做完整性校验与新版本判定。
    ///
    /// ==================================================================
    /// 【为什么必须有这个文件】
    ///   运行时的 dll 热更链需要回答两个问题，都依赖 md5：
    ///     ① "本地这个 dll 是不是已经和服务器一致？" → 一致就不下载（省流量）
    ///     ② "下下来的这个 dll 是完好的吗？"        → 校验通过才原子替换
    ///   没有清单，这两个问题都无法回答 —— 下载器会**直接放弃更新**
    ///   （宁可这次不更新，也不盲写坏文件）。
    ///
    /// 【产物放哪、怎么上传】
    ///   生成位置：`Assets/StreamingAssets/HybridCLR/md5.txt`
    ///     —— 与 dll 同目录，这样它既随包分发（首包自带，无需联网也能自校验），
    ///        又是"要上传到服务器的那一份"的原点。
    ///   上传方式：把 `Assets/StreamingAssets/HybridCLR/` 下的 **全部文件**
    ///     （11 个 dll + md5.txt）上传到服务器的
    ///     `{服务器根}/{平台}/HybridCLR/` 目录，覆盖旧文件即可。
    ///   例（Android）：
    ///     http://192.168.43.100:8000/Android/HybridCLR/md5.txt
    ///     http://192.168.43.100:8000/Android/HybridCLR/FTProject.Runtime.dll
    ///
    /// 【清单格式】（与运行时 ParseMd5List 严格对应）
    ///     # 由 FTProject 编辑器工具生成，勿手工编辑
    ///     # 平台: Android
    ///     # 生成时间: 2026-10-11T16:40:00Z
    ///     d41d8cd98f00b204e9800998ecf8427e  FTProject.Runtime.dll
    ///     ...
    ///   —— 32 位小写 md5 + **两个空格** + 文件名（兼容 `md5sum` 的习惯格式）。
    ///
    /// 【为什么不扫整个目录，而按名单生成】
    ///   名单来源 = `HybridCLRSettings.asset` 的 hotUpdateAssemblies
    ///   + 本工具的 AOTMetaAssemblies —— 与 HybridCLRDllCopier 完全一致。
    ///   扫目录会把 `.meta`、临时文件之类也扫进去，且无法保证与运行时预期一致。
    /// ==================================================================
    /// </summary>
    public static class HybridCLRMd5Generator
    {
        /// <summary>与 HybridCLRDllCopier / 运行时一致的目录名。</summary>
        private const string DllSubDir = "HybridCLR";

        /// <summary>清单文件名（运行时按此名请求）。</summary>
        private const string Md5FileName = "md5.txt";

        /// <summary>
        /// AOT 补充元数据 dll 的运行期名单。
        /// ⚠️ 与 `HotUpdateAssembler.AOTMetaAssemblies`、
        ///    `HybridCLRDllCopier.AOTMetaAssemblies` **三处必须一致** ——
        ///    编辑器工具不能引用 AOT 程序集，只能手写。
        /// </summary>
        private static readonly string[] AOTMetaAssemblies =
        {
            "System.Core.dll",
            "UnityEngine.AssetBundleModule.dll",
            "UnityEngine.CoreModule.dll",
            "UnityEngine.JSONSerializeModule.dll",
            "YooAsset.dll",
            "mscorlib.dll",
        };

        [MenuItem("Tools/塔防/HybridCLR/4. 生成 md5 校验清单（上传服务器用）", false, 303)]
        public static void GenerateFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            Generate(report);
            AssetDatabase.Refresh();

            // 【为什么不弹 DisplayDialog】会阻塞 MCP / CI（见 EditorUtil 约定）
            if (report.Errors > 0)
            {
                Debug.LogError("[HybridCLR] 生成 md5 清单失败：\n" + report.Text);
            }
            else
            {
                Debug.Log("[HybridCLR] 生成 md5 清单完成：\n" + report.Text);
            }
        }

        public static void Generate(EditorUtil.Report report)
        {
            report.Head("生成热更 dll 的 md5 校验清单");

            BuildTarget target = EditorUserBuildSettings.activeBuildTarget;
            string dllDir = Path.Combine(Application.dataPath, "StreamingAssets", DllSubDir);

            if (Directory.Exists(dllDir) == false)
            {
                report.Error("找不到目录：" + dllDir
                    + "（请先执行菜单「Tools ▸ 塔防 ▸ HybridCLR ▸ 1. 拷贝热更 dll 到 StreamingAssets」）");
                return;
            }

            // ---------- ① 汇总要纳入清单的文件名 ----------
            List<string> names = new List<string>();

            List<string> hotNames = GetHotUpdateAssemblyNames(report);
            if (hotNames == null || hotNames.Count == 0)
            {
                report.Error("HybridCLRSettings.asset 里 hotUpdateAssemblies 为空，" +
                    "无法确定要纳入清单的热更 dll。");
                return;
            }
            for (int i = 0; i < hotNames.Count; i++)
            {
                names.Add(hotNames[i] + ".dll");
            }
            for (int i = 0; i < AOTMetaAssemblies.Length; i++)
            {
                names.Add(AOTMetaAssemblies[i]);
            }

            // ---------- ② 逐个算 md5 ----------
            var lines = new List<string>();
            lines.Add("# 由 FTProject 编辑器工具生成，勿手工编辑");
            lines.Add("# 平台: " + target);
            lines.Add("# 生成时间: " + DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ"));
            lines.Add("# 格式: <32位小写md5><两个空格><文件名>");

            int okCount = 0;
            int missingCount = 0;

            for (int i = 0; i < names.Count; i++)
            {
                string name = names[i];
                string path = Path.Combine(dllDir, name);

                if (File.Exists(path) == false)
                {
                    // 缺失不写成错误：可能是该平台没编出这个 dll（例如 AOT 元数据没 Generate/All）。
                    // 但必须**显式告警**，否则运行时会出现"清单里没有 → 跳过更新"的静默行为。
                    report.Warn("清单跳过（文件不存在）：" + name);
                    missingCount++;
                    continue;
                }

                string md5;
                long size;
                try
                {
                    md5 = ComputeMd5(path);
                    size = new FileInfo(path).Length;
                }
                catch (Exception e)
                {
                    report.Error("计算 md5 失败 " + name + "：" + e.Message);
                    continue;
                }

                lines.Add(md5 + "  " + name);
                report.Ok(string.Format("  {0}  {1}  ({2:N0} 字节)", md5, name, size));
                okCount++;
            }

            if (okCount == 0)
            {
                report.Error("没有任何 dll 被纳入清单，未生成 " + Md5FileName);
                return;
            }

            // ---------- ③ 写入 ----------
            string outPath = Path.Combine(dllDir, Md5FileName);
            try
            {
                // 统一用 \n 换行：运行时解析会 Trim 掉 \r，但保持跨平台一致更好读
                File.WriteAllText(outPath, string.Join("\n", lines.ToArray()) + "\n",
                    new UTF8Encoding(false));
            }
            catch (Exception e)
            {
                report.Error("写入 " + outPath + " 失败：" + e.Message);
                return;
            }

            report.Ok(string.Format("  已生成：Assets/StreamingAssets/{0}/{1}（{2} 条记录）",
                DllSubDir, Md5FileName, okCount));
            if (missingCount > 0)
            {
                report.Warn(string.Format("  有 {0} 个 dll 缺失未纳入清单（见上方 Warning）", missingCount));
            }

            // ---------- ④ 上传指引 ----------
            string platformFolder = target.ToString();
            report.Ok("  —— 上传指引 ——");
            report.Ok(string.Format("  把 Assets/StreamingAssets/{0}/ 下的 dll 与 {1} 一起上传到服务器：",
                DllSubDir, Md5FileName));
            report.Ok(string.Format("    {{服务器根}}/{0}/{1}/", platformFolder, DllSubDir));
            report.Ok(string.Format("  ⚠️ 只传 dll 不传 {0} → 客户端会放弃更新（宁可不动也不盲写）。", Md5FileName));
        }

        /// <summary>
        /// 读 HybridCLRSettings.asset 里的 hotUpdateAssemblies（反射读取，不直接依赖 HybridCLR.Editor）。
        /// 与 HybridCLRDllCopier 的实现保持一致 —— 若要改，两处一起改。
        /// </summary>
        private static List<string> GetHotUpdateAssemblyNames(EditorUtil.Report report)
        {
            string path = "ProjectSettings/HybridCLRSettings.asset";
            UnityEngine.Object[] objs =
                UnityEditorInternal.InternalEditorUtility.LoadSerializedFileAndForget(path);
            if (objs == null || objs.Length == 0)
            {
                report.Error("读不到 " + path);
                return null;
            }

            System.Reflection.FieldInfo f = objs[0].GetType().GetField("hotUpdateAssemblies");
            if (f == null)
            {
                report.Error("HybridCLRSettings 里找不到 hotUpdateAssemblies 字段");
                return null;
            }

            string[] arr = f.GetValue(objs[0]) as string[];
            var list = new List<string>();
            if (arr != null)
            {
                for (int i = 0; i < arr.Length; i++)
                {
                    if (!string.IsNullOrEmpty(arr[i]))
                    {
                        list.Add(arr[i]);
                    }
                }
            }
            return list;
        }

        /// <summary>流式计算文件 md5，返回 32 位小写十六进制。</summary>
        private static string ComputeMd5(string path)
        {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(path))
            {
                byte[] hash = md5.ComputeHash(stream);
                var sb = new StringBuilder(hash.Length * 2);
                for (int i = 0; i < hash.Length; i++)
                {
                    sb.Append(hash[i].ToString("x2"));
                }
                return sb.ToString();
            }
        }
    }
}

using System.Collections.Generic;
