        // ------------------------------------------------------------------
        // ★ 一键写入：读页面 → 写 xlsx → Luban 重导 → 回读校验
        // ------------------------------------------------------------------

        private void OneClickWrite()
        {
            LogReset();
            LogSkip("一键写入开始：读页面 → 写 xlsx → Luban 重导 → 回读");

            // ── ① 页面数据自检。不合格就直接停，一个文件都不碰
            int buildable, pathLen;
            List<string> problems = CollectProblems(out buildable, out pathLen);
            if (problems.Count > 0)
            {
                LogErr("页面数据未通过自检，已中止（没有改动任何文件）：");
                for (int i = 0; i < problems.Count; i++)
                {
                    _log.Add("      · " + problems[i]);
                }
                FlushStatus(true);
                return;
            }
            LogOk(string.Format("页面数据自检通过：{0}×{1}，可建造格 {2}，最短路径 {3} 格",
                _cols, _rows, buildable, pathLen));

            string root = Directory.GetCurrentDirectory();

            // ── ② 读页面数据 → 导出中转 json
            string exportErr;
            if (!WriteExportFile(out exportErr))
            {
                LogErr(exportErr);
                FlushStatus(true);
                return;
            }
            LogOk("已读取页面数据 → " + ExportRelPath);

            // ── ③ 定位 Python（必须有 openpyxl，否则写不了 xlsx）
            string python, pyNote;
            if (!ResolvePython(out python, out pyNote))
            {
                LogErr("找不到可用（装了 openpyxl）的 Python 解释器，已中止。");
                if (!string.IsNullOrEmpty(pyNote))
                {
                    // note 里的换行是"探测轨迹"，逐行加上缩进再入日志，别让多行文本挤成一坨
                    string[] trail = pyNote.Split('\n');
                    for (int i = 0; i < trail.Length; i++)
                    {
                        _log.Add("      " + trail[i]);
                    }
                }
                _log.Add("      · 在窗口顶部「Python」栏填入解释器完整路径，或执行：");
                _log.Add("        <python> -m pip install openpyxl");
                FlushStatus(true);
                return;
            }
            LogSkip("Python = " + python + (string.IsNullOrEmpty(pyNote) ? "" : "（" + pyNote + "）"));

            string script = Path.Combine(root, ApplierRelPath.Replace('/', Path.DirectorySeparatorChar));
            if (!File.Exists(script))
            {
                LogErr("找不到写表脚本：" + ApplierRelPath);
                FlushStatus(true);
                return;
            }

            // ── ④ 写回 LevelMap.xlsx
            // 【为什么先给初值】out 实参在 try/finally 里赋值时，确定赋值（CS0165）的判定
            //   依赖编译器对 finally 控制流的分析；这里显式初始化，把"能不能编过"变成确定的事。
            string outp = null, errp = null;
            int code = -3;
            EditorUtility.DisplayProgressBar("一键写入 xlsx", "正在写回 Luban/Config/Datas/Levels/Lxx/LevelMap.xlsx …", 0.33f);
            try
            {
                code = RunProcess(python, "\"" + script + "\"", root, out outp, out errp, ApplierTimeoutMs);
            }
            finally
            {
                EditorUtility.ClearProgressBar();
            }

            if (!string.IsNullOrEmpty(outp)) UnityEngine.Debug.Log("[地图编辑器] 写表输出：\n" + outp.TrimEnd());
            if (!string.IsNullOrEmpty(errp)) UnityEngine.Debug.LogWarning("[地图编辑器] 写表 stderr：\n" + errp.TrimEnd());

            if (code != 0)
            {
                LogErr(string.Format("写表脚本返回非 0（exitCode={0}），该关 LevelMap.xlsx 未改动。", code));
                AppendToolTail(outp, errp);
                FlushStatus(true);
                return;
            }
            LogOk("已写回该关 LevelMap.xlsx" + ExtractBackupHint(outp));
            LogSkip(ExtractSceneHint(outp));

            // ── ⑤ Luban 重导（这一步把 xlsx 变成运行时真正读的 tblevelmap.json）
            EditorUtil.Report luban = new EditorUtil.Report();
            bool lubanOk = LubanExporter.ExportInternal(luban);
            UnityEngine.Debug.Log("[地图编辑器] Luban：\n" + luban.Text);
            if (!lubanOk)
            {
                LogErr("Luban 重导失败 —— xlsx 已改好，但没有生成到 Assets/ConfigJson（细节见 Console）。");
                FlushStatus(true);
                return;
            }
            LogOk("已重新导入配置表（Assets/ConfigJson）");

            // ── ⑥ 回读校验：把"写表成功"升级成"往返一致"
            AssetDatabase.Refresh();
            string drawn = BuildCellsString();
            LoadLevel(_levelId, true);
            string back = BuildCellsString();
            if (back == drawn)
            {
                LogOk(string.Format("回读一致：重导后的 tblevelmap.json 与页面数据逐格相同（{0}×{1}）", _cols, _rows));
            }
            else
            {
                LogWarn("回读不一致 —— Luban 可能对 cells 做了规范化，请对照棋盘核对（页面已按重导结果重载）");
            }

            LogOk("一键写入完成。");
            FlushStatus(true);
        }

        /// <summary>从脚本输出里摘出备份目录，直接展示给用户，方便回滚。</summary>
        private static string ExtractBackupHint(string text)
        {
            string line = FindLine(text, "已备份到");
            return string.IsNullOrEmpty(line) ? "" : "（" + line + "）";
        }

        /// <summary>脚本提示"SceneInfo 里没登记这一关"时，把它抬到窗口上（否则只在 Console 里）。</summary>
        private static string ExtractSceneHint(string text)
        {
            string line = FindLine(text, "[提示]");
            return string.IsNullOrEmpty(line) ? "" : line;
        }

        private static string FindLine(string text, string keyword)
        {
            if (string.IsNullOrEmpty(text))
            {
                return null;
            }
            string[] lines = text.Replace("\r\n", "\n").Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                string s = lines[i].Trim();
                if (s.Length > 0 && s.StartsWith(keyword))
                {
                    return s;
                }
            }
            return null;
        }

        /// <summary>失败时把工具输出的头几行贴进状态框，省得用户还要去翻 Console。</summary>
        private void AppendToolTail(string outp, string errp)
        {
            string t = errp == null ? "" : errp.Trim();
            if (t.Length == 0)
            {
                t = outp == null ? "" : outp.Trim();
            }
            if (t.Length == 0)
            {
                return;
            }
            string[] lines = t.Replace("\r\n", "\n").Split('\n');
            int n = Mathf.Min(lines.Length, 8);
            for (int i = 0; i < n; i++)
            {
                _log.Add("      | " + lines[i]);
            }
        }

        // ------------------------------------------------------------------
        // 数据
        // ------------------------------------------------------------------

        /// <summary>保证 _cells 存在且尺寸与 _cols/_rows 一致（第一次打开、或载入失败时兜底）。</summary>
        private void EnsureCells()
        {
            if (_cells == null || _cells.GetLength(0) != _rows || _cells.GetLength(1) != _cols)
            {
                Resize(_cols, _rows);
            }
        }

        private void Resize(int cols, int rows)
        {
            char[,] next = new char[rows, cols];
            for (int r = 0; r < rows; r++)
            {
                for (int c = 0; c < cols; c++)
                {
                    next[r, c] = (_cells != null && r < _rows && c < _cols) ? _cells[r, c] : '.';
                }
            }
            _cols = cols;
            _rows = rows;
            _cells = next;
        }

        private void Fill(char ch)
        {
            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c < _cols; c++)
                {
                    _cells[r, c] = ch;
                }
            }
        }

        private void LoadLevel(int levelId)
        {
            LoadLevel(levelId, false);
        }

        /// <summary>
        /// 从 Luban 产物 tblevelmap.json 载入本关棋盘。
        /// silent=true 时不写状态框（"一键写入"的回读校验要用，免得覆盖流程日志）。
        /// 【要点】棋盘数据全部读完之后才提交到字段，避免中途失败留下半截棋盘。
        /// </summary>
        private void LoadLevel(int levelId, bool silent)
        {
            string path = Path.Combine(Directory.GetCurrentDirectory(), LocalJsonRelPath.Replace('/', Path.DirectorySeparatorChar));
            if (!File.Exists(path))
            {
                if (!silent)
                {
                    SetStatus("找不到 " + LocalJsonRelPath + " —— 请先跑一次 Luban 导出", true);
                }
                return;
            }

            try
            {
                JSONNode root = JSONNode.Parse(File.ReadAllText(path, Encoding.UTF8));
                if (root == null || !root.IsArray)
                {
                    if (!silent) SetStatus(LocalJsonRelPath + " 不是数组，格式异常", true);
                    return;
                }

                for (int i = 0; i < root.Count; i++)
                {
                    JSONNode row = root[i];
                    if (row == null || row["id"] == null || row["id"].AsInt != levelId)
                    {
                        continue;
                    }

                    int cols = row["cols"] != null ? row["cols"].AsInt : 16;
                    int rows = row["rows"] != null ? row["rows"].AsInt : 9;
                    int useCols = Mathf.Clamp(cols, 1, MaxCols);
                    int useRows = Mathf.Clamp(rows, 1, MaxRows);

                    char[,] next = new char[useRows, useCols];
                    for (int r = 0; r < useRows; r++)
                    {
                        for (int c = 0; c < useCols; c++)
                        {
                            next[r, c] = '.';
                        }
                    }
                    JSONNode cells = row["cells"];
                    if (cells != null && cells.IsArray)
                    {
                        for (int r = 0; r < useRows && r < cells.Count; r++)
                        {
                            string line = cells[r].Value;
                            for (int c = 0; c < useCols && line != null && c < line.Length; c++)
                            {
                                next[r, c] = line[c];
                            }
                        }
                    }

                    _levelId = levelId;
                    _cols = useCols;
                    _rows = useRows;
                    _cells = next;
                    _desc = row["desc"] != null ? row["desc"].Value : "";

                    if (!silent)
                    {
                        SetStatus(string.Format("已载入关卡 {0}（{1}×{2}）", levelId, _cols, _rows), false);
                    }
                    return;
                }

                if (!silent)
                {
                    SetStatus(string.Format("tblevelmap.json 里没有 id={0} 的棋盘（新图请先设好行列再画）", levelId), false);
                }
            }
            catch (System.Exception ex)
            {
                if (!silent)
                {
                    SetStatus("解析 " + LocalJsonRelPath + " 失败：" + ex.Message, true);
                }
            }
        }

        private string[] BuildCellLines()
        {
            string[] lines = new string[_rows];
            StringBuilder sb = new StringBuilder(_cols);
            for (int r = 0; r < _rows; r++)
            {
                sb.Length = 0;
                for (int c = 0; c < _cols; c++)
                {
                    sb.Append(_cells[r, c]);
                }
                lines[r] = sb.ToString();
            }
            return lines;
        }

        /// <summary>xlsx 里 cells 列的格式：(list#sep=|),string —— 用 | 分隔每一行</summary>
        private string BuildCellsString()
        {
            return string.Join("|", BuildCellLines());
        }

        // ------------------------------------------------------------------
        // 校验
        // ------------------------------------------------------------------

        private void ValidateAndReport()
        {
            LogReset();
            int buildable, pathLen;
            List<string> problems = CollectProblems(out buildable, out pathLen);

            if (problems.Count > 0)
            {
                LogErr("校验未通过：");
                for (int i = 0; i < problems.Count; i++)
                {
                    _log.Add("      · " + problems[i]);
                }
            }
            else
            {
                LogOk(string.Format("校验通过：棋盘 {0}×{1}，可建造格 {2}，最短路径 {3} 格",
                    _cols, _rows, buildable, pathLen));
                LogSkip("参考：可建造格越少越难（当前 8 张图是 142→70 递减）");
            }
            FlushStatus(false);
        }

        /// <summary>
        /// 收集页面数据的全部问题（顺带返回可建造格数与最短路径）。
        /// 【注意】这里和 Python 脚本里的自检是**同一套口径**：
        /// 窗口先挡一遍是为了"不合格就别白跑外部进程"，脚本再挡一遍是因为导出文件可能被手改。
        /// </summary>
        private List<string> CollectProblems(out int buildable, out int pathLen)
        {
            List<string> problems = new List<string>();
            int sCount = 0, eCount = 0;
            buildable = 0;

            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c < _cols; c++)
                {
                    char ch = _cells[r, c];
                    if (ch == 'S') sCount++;
                    else if (ch == 'E') eCount++;
                    else if (ch == '.') buildable++;
                }
            }

            pathLen = -1;
            if (sCount != 1) problems.Add(string.Format("起点 S 有 {0} 个（必须恰好 1 个）", sCount));
            if (eCount != 1) problems.Add(string.Format("终点 E 有 {0} 个（必须恰好 1 个）", eCount));

            if (sCount == 1 && eCount == 1)
            {
                pathLen = BfsPathLength();
                if (pathLen < 0)
                {
                    problems.Add("S 到 E 不可达 —— 障碍把路封死了（这是最致命的一条，进关会直接卡住）");
                }
            }
            return problems;
        }

        /// <summary>BFS 求最短路径长度（障碍与空洞不可通行）。不可达返回 -1。</summary>
        private int BfsPathLength()
        {
            int sr = -1, sc = -1, er = -1, ec = -1;
            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c < _cols; c++)
                {
                    if (_cells[r, c] == 'S') { sr = r; sc = c; }
                    else if (_cells[r, c] == 'E') { er = r; ec = c; }
                }
            }
            if (sr < 0 || er < 0)
            {
                return -1;
            }

            int[,] dist = new int[_rows, _cols];
            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c < _cols; c++)
                {
                    dist[r, c] = -1;
                }
            }
            Queue<int> q = new Queue<int>();
            dist[sr, sc] = 0;
            q.Enqueue(sr * _cols + sc);
            int[] dr = { 1, -1, 0, 0 };
            int[] dc = { 0, 0, 1, -1 };
            while (q.Count > 0)
            {
                int cur = q.Dequeue();
                int r = cur / _cols;
                int c = cur % _cols;
                if (r == er && c == ec)
                {
                    return dist[r, c];
                }
                for (int k = 0; k < 4; k++)
                {
                    int nr = r + dr[k];
                    int nc = c + dc[k];
                    if (nr < 0 || nr >= _rows || nc < 0 || nc >= _cols)
                    {
                        continue;
                    }
                    if (dist[nr, nc] >= 0)
                    {
                        continue;
                    }
                    char ch = _cells[nr, nc];
                    if (ch == '#' || ch == 'X')
                    {
                        continue;
                    }
                    dist[nr, nc] = dist[r, c] + 1;
                    q.Enqueue(nr * _cols + nc);
                }
            }
            return -1;
        }

        // ------------------------------------------------------------------
        // 导出（读页面数据 → 中转 json）
        // ------------------------------------------------------------------

        private void ExportAndReport()
        {
            LogReset();
            string err;
            if (WriteExportFile(out err))
            {
                LogOk("已读取页面数据并导出到 " + ExportRelPath);
                LogSkip("接着点「一键写入 xlsx」即可自动写表 + 重导");
            }
            else
            {
                LogErr(err);
            }
            FlushStatus(false);
        }

        /// <summary>把页面当前关卡的数据写成中转 json（无 BOM，Python 侧按 UTF-8 读）。</summary>
        private bool WriteExportFile(out string error)
        {
            error = null;
            try
            {
                string full = Path.Combine(Directory.GetCurrentDirectory(),
                    ExportRelPath.Replace('/', Path.DirectorySeparatorChar));
                string dir = Path.GetDirectoryName(full);
                if (!string.IsNullOrEmpty(dir))
                {
                    Directory.CreateDirectory(dir);
                }

                StringBuilder sb = new StringBuilder();
                sb.Append("{\n");
                sb.Append("  \"levelId\": ").Append(_levelId).Append(",\n");
                sb.Append("  \"cols\": ").Append(_cols).Append(",\n");
                sb.Append("  \"rows\": ").Append(_rows).Append(",\n");
                sb.Append("  \"desc\": ").Append(JsonStr(_desc)).Append(",\n");
                sb.Append("  \"cells\": [");
                string[] lines = BuildCellLines();
                for (int i = 0; i < lines.Length; i++)
                {
                    if (i > 0) sb.Append(", ");
                    sb.Append(JsonStr(lines[i]));
                }
                sb.Append("]\n}\n");

                File.WriteAllText(full, sb.ToString(), new UTF8Encoding(false));
                return true;
            }
            catch (System.Exception ex)
            {
                error = "导出失败：" + ex.Message;
                return false;
            }
        }

        private static string JsonStr(string s)
        {
            if (s == null)
            {
                return "\"\"";
            }
            return "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
        }

        // ------------------------------------------------------------------
        // 外部进程
        // ------------------------------------------------------------------

        /// <summary>
        /// 定位一个"装了 openpyxl"的 Python 解释器，顺带把结果记进 EditorPrefs。
        /// 【为什么必须探测而不是直接用 "python"】openpyxl 是第三方库，
        /// PATH 上的 python 大概率没装；直接调用会在写表那一步才失败，
        /// 报出来的还是一串 import 错误，远不如在这里就明确挡住。
        /// 顺序：已记住 → 工程内 venv → 本机已装（venv/常见安装目录）→ PATH。
        /// 【为什么"本机已装"要排在 PATH 前面】PATH 上的裸 python 命中"能跑但没装 openpyxl"
        /// 的概率很高，把已知带 openpyxl 的绝对路径先试一遍，能少一次必然失败的进程启动。
        /// </summary>
        private bool ResolvePython(out string python, out string note)
        {
            note = "";
            string saved = EditorPrefs.GetString(PythonPrefKey, "");
            if (!string.IsNullOrEmpty(saved))
            {
                // 记住的是绝对路径但文件没了（换机器 / 工程跟 EditorPrefs 不同步）就别白跑一次进程
                bool isAbsPath = saved.IndexOf('/') >= 0 || saved.IndexOf('\\') >= 0;
                if (isAbsPath && !File.Exists(saved))
                {
                    note = "已记住的解释器不存在，重新探测";
                }
                else if (ProbePython(saved))
                {
                    python = saved;
                    note = "已记住";
                    return true;
                }
                else
                {
                    note = "已记住的解释器不可用，重新探测";
                }
            }

            string root = Directory.GetCurrentDirectory();
            List<string> probeTrail = new List<string>();

            for (int i = 0; i < PythonRelCandidates.Length; i++)
            {
                string p = Path.Combine(root, PythonRelCandidates[i].Replace('/', Path.DirectorySeparatorChar));
                if (!File.Exists(p))
                {
                    continue;
                }
                if (ProbePython(p))
                {
                    return AcceptPython(p, out python);
                }
                probeTrail.Add(p);
            }

            List<string> absCandidates = BuildAbsFallbackCandidates();
            for (int i = 0; i < absCandidates.Count; i++)
            {
                if (ProbePython(absCandidates[i]))
                {
                    note = "本机兜底";
                    return AcceptPython(absCandidates[i], out python);
                }
                probeTrail.Add(absCandidates[i]);
            }

            for (int i = 0; i < PythonPathCandidates.Length; i++)
            {
                if (ProbePython(PythonPathCandidates[i]))
                {
                    note = "来自 PATH";
                    return AcceptPython(PythonPathCandidates[i], out python);
                }
                probeTrail.Add(PythonPathCandidates[i] + "（PATH）");
            }

            // 全失败时把试过的路都带上 —— 只报"找不到"用户不知道该填哪个路径进来
            if (probeTrail.Count == 0)
            {
                note = "未发现任何 Python（工程内 venv / 本机安装 / PATH 都为空）";
            }
            else
            {
                StringBuilder sb = new StringBuilder();
                sb.Append("已试 ").Append(probeTrail.Count).Append(" 个候选均无 openpyxl：");
                int show = probeTrail.Count < 5 ? probeTrail.Count : 5;
                for (int i = 0; i < show; i++)
                {
                    sb.Append("\n  · ").Append(probeTrail[i]);
                }
                if (probeTrail.Count > show)
                {
                    sb.Append("\n  · …另有 ").Append(probeTrail.Count - show).Append(" 个");
                }
                note = sb.ToString();
            }

            python = null;
            return false;
        }

        /// <summary>探测成功后统一落地：记住到 EditorPrefs + 回填窗口输入框。</summary>
        private bool AcceptPython(string exe, out string python)
        {
            python = exe;
            EditorPrefs.SetString(PythonPrefKey, exe);
            _pythonPath = exe;
            return true;
        }

        /// <summary>跑一次 `python -c "import openpyxl"`，退出码为 0 才算可用。</summary>
        private static bool ProbePython(string exe)
        {
            // py 是 Windows 启动器，必须显式指定大版本，否则可能落到 Python 2
            string args = (exe == "py") ? "-3 -c \"import openpyxl\"" : "-c \"import openpyxl\"";
            string outp, errp;
            int code = RunProcess(exe, args, Directory.GetCurrentDirectory(), out outp, out errp, ProbeTimeoutMs);
            return code == 0;
        }

        /// <summary>
        /// 同步跑一个进程并收回输出。
        /// 【要点】用 BeginOutputReadLine 异步读 —— 顺序 ReadToEnd 在"子进程边写边等"时会死锁。
        /// 【要点】两次 WaitForExit：第一次等退出，第二次等异步读取回调把剩余行刷完，
        /// 少第二次会丢结尾几行（恰恰是最关键的报错）。
        /// </summary>
        private static int RunProcess(string fileName, string arguments, string workDir,
                                      out string stdout, out string stderr, int timeoutMs)
        {
            stdout = "";
            stderr = "";
            StringBuilder so = new StringBuilder();
            StringBuilder se = new StringBuilder();

            System.Diagnostics.ProcessStartInfo psi = new System.Diagnostics.ProcessStartInfo();
            psi.FileName = fileName;
            psi.Arguments = arguments;
            psi.WorkingDirectory = workDir;
            psi.UseShellExecute = false;
            psi.RedirectStandardOutput = true;
            psi.RedirectStandardError = true;
            psi.CreateNoWindow = true;
            // Python 侧已把 stdout 切到 UTF-8，这里必须同样按 UTF-8 解，否则中文全乱码
            psi.StandardOutputEncoding = new UTF8Encoding(false);
            psi.StandardErrorEncoding = new UTF8Encoding(false);

            try
            {
                using (System.Diagnostics.Process p = System.Diagnostics.Process.Start(psi))
                {
                    p.OutputDataReceived += delegate(object s, System.Diagnostics.DataReceivedEventArgs e)
                    {
                        if (e.Data != null) { lock (so) { so.AppendLine(e.Data); } }
                    };
                    p.ErrorDataReceived += delegate(object s, System.Diagnostics.DataReceivedEventArgs e)
                    {
                        if (e.Data != null) { lock (se) { se.AppendLine(e.Data); } }
                    };
                    p.BeginOutputReadLine();
                    p.BeginErrorReadLine();

                    if (!p.WaitForExit(timeoutMs))
                    {
                        try { p.Kill(); }
                        catch (System.Exception) { }
                        stdout = so.ToString();
                        stderr = se.ToString() + "\n[超时] 超过 " + (timeoutMs / 1000) + " 秒未结束，已终止";
                        return -1;
                    }
                    p.WaitForExit();
                    stdout = so.ToString();
                    stderr = se.ToString();
                    return p.ExitCode;
                }
            }
            catch (System.Exception ex)
            {
                stdout = so.ToString();
                stderr = ex.Message;
                return -2;
            }
        }

        // ------------------------------------------------------------------
        // 状态日志
        // ------------------------------------------------------------------

        private void LogReset()
        {
            _log.Clear();
            _logHasError = false;
        }

        private void LogOk(string msg) { _log.Add("[OK] " + msg); }
        private void LogSkip(string msg) { if (!string.IsNullOrEmpty(msg)) _log.Add("[--] " + msg); }

        private void LogWarn(string msg)
        {
            _log.Add("[! ] " + msg);
        }

        private void LogErr(string msg)
        {
            _log.Add("[X ] " + msg);
            _logHasError = true;
        }

        private void FlushStatus(bool alsoLogConsole)
        {
            _status = string.Join("\n", _log.ToArray());
            _statusIsError = _logHasError;
            if (alsoLogConsole)
            {
                UnityEngine.Debug.Log("[地图编辑器] 一键写入日志：\n" + _status);
            }
            Repaint();
        }
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 把工程里所有 UI 预制体的**静态文案**节点批量挂上 <see cref="TextLocalizer"/>。
    ///
    /// 【为什么需要"批量挂"】
    ///   多语言组件是**挂在节点上的行为组件**，必须逐个组装进 prefab 才有意义。
    ///   手工一个个挂既慢又容易漏 —— 本工具让"代码改完"和"prefab 生效"一步到位。
    ///
    /// 【key 留空是刻意设计】
    ///   TextLocalizer 的 key 留空时会**自动拿节点上序列化的英文原文当 key**去查表
    ///   （表的主键就是英文原文本身）。所以挂上去即可用，无需在 Inspector 里再抄一遍 key，
    ///   也避免"key 抄岔 → 多语言静默失效"的老坑。
    ///
    /// 【幂等】已有 TextLocalizer 的节点跳过，不会重复挂。
    ///
        /// 【排除规则：运行时动态文本绝不挂】
        ///   这类节点的内容由 View 代码用 Localization.Get(key, args) / SetText 主动赋值，
        ///   挂了本地化组件反而会在切语言时把代码算好的内容冲掉。
        ///   判据 = 见 <see cref="DynamicNames"/>（按节点名，宁少挂不多挂）
        ///     + BindOne 里的两处结构性特判：TMP_Dropdown 内部文本（语言下拉框）、
        ///       MuteBtn/Label（"静音 / 取消静音"两态文本）。
    /// </summary>
    public static class LocalizationPrefabBinder
    {
        /// <summary>要处理的全部 UI 预制体（与 UIPrefabBuilder 的输出一一对应）。</summary>
        private static readonly string[] TargetPrefabs =
        {
            "Assets/Prefabs/UI/HudView.prefab",
            "Assets/Prefabs/UI/TipsView.prefab",
            "Assets/Prefabs/UI/TowerInfoView.prefab",
            "Assets/Prefabs/UI/SelectView.prefab",
            "Assets/Prefabs/UI/SelectLevelItem.prefab",
            "Assets/Prefabs/UI/PauseView.prefab",
            "Assets/Prefabs/UI/SettingView.prefab",
            "Assets/Prefabs/UI/LevelClearView.prefab",
            "Assets/Prefabs/UI/MainMenuView.prefab",
            "Assets/Prefabs/UI/LevelDetailView.prefab",
            "Assets/Prefabs/UI/SellConfirmView.prefab",
            "Assets/Prefabs/UI/ConfirmView.prefab",
            "Assets/Prefabs/UI/TowerCodexView.prefab",
            "Assets/Prefabs/UI/TowerCodexItem.prefab",
            // 游戏介绍弹窗（2026-10-14）：BackBtn/CloseBtn 的 Label 是静态文案
            "Assets/Prefabs/UI/GameIntroView.prefab",
            "Assets/HotUpdateUI/SplashView.prefab",
            "Assets/HotUpdateUI/LoadingView.prefab",
        };

        /// <summary>
        /// **运行时动态文本**节点名（View 代码会覆盖内容）→ 不挂本地化组件。
        ///
        /// 逐条依据（对照各 View 的代码）：
        ///   · GoldText / HpText / RoundText — HudView 每帧 SetText
        ///   · PriceText  — HudView 刷新塔价
        ///   · Title      — 除 MainMenu/Pause/Setting 的"页面标题"外，多数被 View SetText；
        ///                  这里统一排除（这些页面标题另有 CodexTitle/HotTitle/SellTitle 等直挂）
        ///   · Stats / StarDetail / RecordTip / LevelName / BestStarText — 结算/详情 View 带参查表
        ///   · Info1..6 / EnemyLabel / Summary / ClearText / StarText — 同上
        ///   · RefundValue / TowerName / WarnText / BodyText — 出售确认/通用确认 Setup 注入
        ///   · TypeName / Role / DescText / DpsRow / RangeRow / SpeedRow / PriceRow — 图鉴条目 Setup
        ///   · PageText — 图鉴页码
        ///   · StatusText / PercentText / TipText / PhaseText / SizeText / SpeedText /
        ///     DetailText / FailText / LoadingDots / VolumeText — 启动链与设置的运行时刷新
        ///   · Title(空串占位) — 骨架空标题
        /// </summary>
        private static readonly HashSet<string> DynamicNames = new HashSet<string>
        {
            "GoldText", "HpText", "RoundText", "PriceText",
            "Title",
            "Stats", "StarDetail", "RecordTip", "LevelName", "BestStarText",
            "Info1", "Info2", "Info3", "Info4", "Info5", "Info6",
            "EnemyLabel", "Summary", "ClearText", "StarText", "Stars",
            "RefundValue", "TowerName", "WarnText", "BodyText",
            "TypeName", "Role", "DescText", "DpsRow", "RangeRow", "SpeedRow", "PriceRow",
            "PageText",
            "StatusText", "PercentText", "TipText", "PhaseText", "SizeText", "SpeedText",
            "DetailText", "FailText", "LoadingDots", "VolumeText",
        };

        /// <summary>
        /// 这些节点名下的 TMP **是静态文案**，即便内容此刻为空也照样挂
        /// （挂上去后运行时按语言填；为空说明生成器给了空占位）。
        /// 主要是各页面的主标题，它们的名字与 View 的"动态 Title"区分开了。
        /// </summary>
        private static readonly HashSet<string> ForceStaticNames = new HashSet<string>
        {
            "CodexTitle", "HotTitle", "SellTitle", "GameTitle", "Subtitle",
        };

        [MenuItem("Tools/塔防/高级（单步重建）/批量挂多语言组件（TextLocalizer）", false, 308)]
        public static void BindFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            int files = BindAll(report);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log(report.Errors > 0
                ? string.Format("[多语言挂载] 有错误（处理 {0} 个预制体）：\n{1}", files, report.Text)
                : string.Format("[多语言挂载] 完成（处理 {0} 个预制体）：\n{1}", files, report.Text));
        }

        /// <summary>供向导调用（不弹窗）。返回处理的预制体数量。</summary>
        public static int BindAll(EditorUtil.Report report)
        {
            report.Head("批量挂 TextLocalizer（key 留空 → 用英文原文当 key）");
            int count = 0;
            for (int i = 0; i < TargetPrefabs.Length; i++)
            {
                if (BindOne(TargetPrefabs[i], report))
                {
                    count++;
                }
            }
            return count;
        }

        private static bool BindOne(string path, EditorUtil.Report report)
        {
            GameObject root = PrefabUtility.LoadPrefabContents(path);
            if (root == null)
            {
                report.Skip(System.IO.Path.GetFileName(path) + " 不存在，跳过");
                return false;
            }

            TextMeshProUGUI[] texts = root.GetComponentsInChildren<TextMeshProUGUI>(true);
            int added = 0;
            int skipped = 0;
            for (int i = 0; i < texts.Length; i++)
            {
                TextMeshProUGUI t = texts[i];
                if (t == null)
                {
                    continue;
                }
                string nm = t.gameObject.name;

                // SpeedButton/Label 是倍速显示（HudView.SetSpeedLabel 运行时覆盖），不本地化
                if (t.transform.parent != null && t.transform.parent.name == "SpeedButton")
                {
                    skipped++;
                    continue;
                }

                // MuteBtn/Label 是"静音 / 取消静音"两态文本（SettingView.Refresh 按存档状态写），
                // 挂了本地化组件会在切语言时被"按 prefab 原文 Mute"刷新、把 Unmute 状态冲掉。
                if (t.transform.parent != null && t.transform.parent.name == "MuteBtn")
                {
                    skipped++;
                    continue;
                }

                // Btn_Pause/Label 是"暂停 / 继续"两态文本（HudView.RefreshPauseLabel 按 GameClock.IsPaused 写），
                // 与 MuteBtn 同理：挂了本地化组件会在切语言时被"按 prefab 原文 Pause"刷回，
                // 把暂停态的 Continue 冲掉。该节点由 HudView 在语言切换时自己重算文案。
                if (t.transform.parent != null && t.transform.parent.name == "Btn_Pause")
                {
                    skipped++;
                    continue;
                }

                // TMP_Dropdown 内部的文本（设置界面的语言下拉框）一律跳过：
                //   · caption 与列表项由 TMP_Dropdown 运行时按当前语言自显名填充；
                //   · 挂了本地化组件后，切语言时会把它们按"占位原文"冲掉，表现为文案错乱。
                //   含未激活的 Template（弹出的列表模板）在内 —— includeInactive=true 覆盖。
                if (t.GetComponentInParent<TMP_Dropdown>(true) != null)
                {
                    skipped++;
                    continue;
                }

                // 纯符号文本（箭头 < > 等）：语言无关，不挂（挂了也会因表里没有而回退原文）
                if (IsSymbolOnly(t.text))
                {
                    skipped++;
                    continue;
                }

                if (DynamicNames.Contains(nm) && !ForceStaticNames.Contains(nm))
                {
                    skipped++;
                    continue;
                }
                if (t.GetComponent<TextLocalizer>() != null)
                {
                    continue;   // 幂等：已挂
                }
                bool force = ForceStaticNames.Contains(nm);
                if (!force && string.IsNullOrEmpty(t.text))
                {
                    continue;   // 空文本没 key 可查
                }
                t.gameObject.AddComponent<TextLocalizer>();
                added++;
            }

            if (added > 0)
            {
                PrefabUtility.SaveAsPrefabAsset(root, path);
            }
            PrefabUtility.UnloadPrefabContents(root);

            report.Ok(string.Format("{0}：新增 {1} 个 TextLocalizer（动态文本跳过 {2} 个）",
                System.IO.Path.GetFileName(path), added, skipped));
            return true;
        }

        /// <summary>
        /// 纯符号文本判定（箭头 `&lt;` `&gt;`、星号、乘号等）——语言无关，无需本地化。
        /// 只要**不含任何字母或汉字**就认为无需翻译。
        /// </summary>
        private static bool IsSymbolOnly(string s)
        {
            if (string.IsNullOrEmpty(s))
            {
                return true;
            }
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (char.IsLetter(c))
                {
                    return false;
                }
            }
            return true;
        }
    }
}

using TMPro;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 清理：把**运行时动态文本**节点上误挂的 <see cref="TextLocalizer"/> 移除。
    ///
    /// 【为什么单独一个菜单】批量挂载工具白名单外扩时，很容易把
    ///   "View 运行时会覆盖内容"的节点也挂上 —— 那会在切语言时把代码算好的
    ///   内容冲掉。本菜单按**节点名黑名单**兜底清理，幂等、可反复跑。
    /// </summary>
    public static class LocalizationPrefabCleaner
    {
        private static readonly string[] TargetPrefabs =
        {
            "Assets/Prefabs/UI/HudView.prefab",
            "Assets/Prefabs/UI/TipsView.prefab",
            "Assets/Prefabs/UI/TowerInfoView.prefab",
            "Assets/Prefabs/UI/SelectView.prefab",
            "Assets/Prefabs/UI/SelectLevelItem.prefab",
            "Assets/Prefabs/UI/PauseView.prefab",
            "Assets/Prefabs/UI/SettingView.prefab",
            "Assets/Prefabs/UI/LevelClearView.prefab",
            "Assets/Prefabs/UI/MainMenuView.prefab",
            "Assets/Prefabs/UI/LevelDetailView.prefab",
            "Assets/Prefabs/UI/SellConfirmView.prefab",
            "Assets/Prefabs/UI/ConfirmView.prefab",
            "Assets/Prefabs/UI/TowerCodexView.prefab",
            "Assets/Prefabs/UI/TowerCodexItem.prefab",
            // 游戏介绍弹窗（2026-10-14）
            "Assets/Prefabs/UI/GameIntroView.prefab",
            "Assets/HotUpdateUI/SplashView.prefab",
            "Assets/HotUpdateUI/LoadingView.prefab",
        };

        private static readonly System.Collections.Generic.HashSet<string> DynamicNames =
            new System.Collections.Generic.HashSet<string>
        {
            "GoldText", "HpText", "RoundText", "PriceText",
            "Title",
            "Stats", "StarDetail", "RecordTip", "LevelName", "BestStarText",
            "Info1", "Info2", "Info3", "Info4", "Info5", "Info6",
            "EnemyLabel", "Summary", "ClearText", "StarText", "Stars",
            "RefundValue", "TowerName", "WarnText", "BodyText",
            "TypeName", "Role", "DescText", "DpsRow", "RangeRow", "SpeedRow", "PriceRow",
            "PageText",
            "StatusText", "PercentText", "TipText", "PhaseText", "SizeText", "SpeedText",
            "DetailText", "FailText", "LoadingDots", "VolumeText",
        };

        [MenuItem("Tools/塔防/高级（单步重建）/清理误挂的多语言组件", false, 309)]
        public static void CleanFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            report.Head("清理动态文本节点上误挂的 TextLocalizer");
            int removed = 0;
            for (int i = 0; i < TargetPrefabs.Length; i++)
            {
                removed += CleanOne(TargetPrefabs[i], report);
            }
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            report.Ok(string.Format("共移除 {0} 个误挂组件", removed));
            Debug.Log("[多语言清理] 完成：\n" + report.Text);
        }

        private static int CleanOne(string path, EditorUtil.Report report)
        {
            GameObject root = PrefabUtility.LoadPrefabContents(path);
            if (root == null)
            {
                return 0;
            }
            TextLocalizer[] all = root.GetComponentsInChildren<TextLocalizer>(true);
            int removed = 0;
            for (int i = 0; i < all.Length; i++)
            {
                TextLocalizer tl = all[i];
                if (tl == null)
                {
                    continue;
                }
                if (DynamicNames.Contains(tl.gameObject.name) || IsSymbolOnly(TMPTextOf(tl)))
                {
                    Object.DestroyImmediate(tl, true);
                    removed++;
                }
            }
            if (removed > 0)
            {
                PrefabUtility.SaveAsPrefabAsset(root, path);
                report.Ok(System.IO.Path.GetFileName(path) + "：移除 " + removed + " 个");
            }
            PrefabUtility.UnloadPrefabContents(root);
            return removed;
        }

        private static string TMPTextOf(TextLocalizer tl)
        {
            TextMeshProUGUI t = tl.GetComponent<TextMeshProUGUI>();
            return t != null ? t.text : null;
        }

        /// <summary>纯符号文本（箭头 &lt; &gt; 等）：语言无关，不该挂本地化。</summary>
        private static bool IsSymbolOnly(string s)
        {
            if (string.IsNullOrEmpty(s))
            {
                return true;
            }
            for (int i = 0; i < s.Length; i++)
            {
                if (char.IsLetter(s[i]))
                {
                    return false;
                }
            }
            return true;
        }
    }
}

using System.Diagnostics;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 在 Unity 内直接导出配置表（Luban），不必再去双击 Luban\gen_code_json.bat。
    ///
    /// 【为什么不能直接调 bat】bat 末尾有 `pause`，用 Process 调它会在"请按任意键继续"处
    /// 永久挂起。所以这里直接调 Luban 的 exe，并把 bat 里的关键设置复刻过来：
    ///   · 环境变量 DOTNET_ROLL_FORWARD=LatestMajor（本机只有 .NET 8/10 时必需）
    ///   · `-j cfg -c .cache.meta --` 的参数顺序（job 参数必须在 `--` 之后，
    ///     否则报 "unknown argument:-d"）
    ///   · 数据输出到 Assets/ConfigJson（原因见 gen_code_json.bat 顶部注释）
    ///
    /// 导出成功后会自动 AssetDatabase.Refresh()，让新表立刻生效。
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 3. 导出配置表（Luban）
    /// </summary>
    public static class LubanExporter
    {
        private const string LubanExe = "Luban/Tools/Luban.ClientServer/Luban.ClientServer.exe";
        private const string CacheMeta = "Luban/.cache.meta";
        private const string RootXml = "Luban/Config/Defines/__root__.xml";
        private const string DataDir = "Luban/Config/Datas";
        private const string OutCodeDir = "Assets/Gen";
        private const string OutDataDir = "Assets/ConfigJson";

        /// <summary>Luban 正常 1~2 秒跑完，给 120 秒兜底（首次可能要预热）</summary>
        private const int TimeoutMs = 120000;

        /// <summary>
        /// 导出代码目录里**不由 Luban 生成、但必须保留**的文件（相对 OutCodeDir）。
        ///
        /// 【为什么需要】Luban 在写 --output_code_dir 时会**清掉目录里它不认识的旧文件**。
        /// 而 `FTProject.Gen.asmdef` 是手工放进 `Assets/Gen/` 的程序集定义（把 Gen 钉成独立热更集），
        /// Luban 不认识它 → 每次导出都会被删除，导致 Gen 的脚本掉回 Assembly-CSharp、
        /// 破坏 HybridCLR 的程序集划分。这里在导出前后自动备份/还原它们。
        /// </summary>
        private static readonly string[] KeepFilesInCodeDir = { "FTProject.Gen.asmdef", "FTProject.Gen.asmdef.meta" };

        [MenuItem("Tools/塔防/3. 导出配置表（Luban）", false, 103)]
        public static void ExportFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            bool ok = ExportInternal(report);
            AssetDatabase.Refresh();

            if (ok)
            {
                UnityEngine.Debug.Log("[Luban] 导出成功：\n" + report.Text);
            }
            else
            {
                UnityEngine.Debug.LogError("[Luban] 导出失败：\n" + report.Text);
            }
        }

        /// <summary>供一键向导调用（不弹窗）。失败返回 false 并已写入 report。</summary>
        public static bool ExportInternal(EditorUtil.Report report)
        {
            report.Head("导出配置表（Luban）");

            string projectRoot = System.IO.Directory.GetParent(Application.dataPath).FullName;
            string exe = System.IO.Path.Combine(projectRoot, LubanExe.Replace('/', '\\'));

            // 前置校验：工具 / 定义 / 源表目录，缺一个都不用往下走
            if (!System.IO.File.Exists(exe))
            {
                report.Error("找不到 Luban 工具：" + LubanExe);
                return false;
            }
            if (!System.IO.File.Exists(System.IO.Path.Combine(projectRoot, RootXml.Replace('/', '\\'))))
            {
                report.Error("找不到配置定义文件：" + RootXml);
                return false;
            }
            if (!System.IO.Directory.Exists(System.IO.Path.Combine(projectRoot, DataDir.Replace('/', '\\'))))
            {
                report.Error("找不到配置源表目录：" + DataDir);
                return false;
            }
            System.IO.Directory.CreateDirectory(System.IO.Path.Combine(projectRoot, OutDataDir.Replace('/', '\\')));

            string args = string.Format(
                "-j cfg -c \"{0}\" -- -d \"{1}\" --input_data_dir \"{2}\" --output_code_dir \"{3}\" " +
                "--output_data_dir \"{4}\" --gen_types code_cs_unity_json,data_json -s all",
                System.IO.Path.Combine(projectRoot, CacheMeta.Replace('/', '\\')),
                System.IO.Path.Combine(projectRoot, RootXml.Replace('/', '\\')),
                System.IO.Path.Combine(projectRoot, DataDir.Replace('/', '\\')),
                System.IO.Path.Combine(projectRoot, OutCodeDir.Replace('/', '\\')),
                System.IO.Path.Combine(projectRoot, OutDataDir.Replace('/', '\\')));

            StringBuilder output = new StringBuilder();
            ProcessStartInfo psi = new ProcessStartInfo();
            psi.FileName = exe;
            psi.Arguments = args;
            psi.WorkingDirectory = projectRoot;
            psi.UseShellExecute = false;
            psi.RedirectStandardOutput = true;
            psi.RedirectStandardError = true;
            psi.CreateNoWindow = true;
            // 本机若只装了 .NET 8/10，没有这个变量 Luban 会报 "You must install .NET"
            psi.EnvironmentVariables["DOTNET_ROLL_FORWARD"] = "LatestMajor";

            // --- 保护 OutCodeDir 里非 Luban 产物（见 KeepFilesInCodeDir 说明）---
            string outCodeAbs = System.IO.Path.Combine(projectRoot, OutCodeDir.Replace('/', '\\'));
            var kept = new System.Collections.Generic.Dictionary<string, string>();
            foreach (string name in KeepFilesInCodeDir)
            {
                string p = System.IO.Path.Combine(outCodeAbs, name);
                if (System.IO.File.Exists(p))
                {
                    kept[p] = System.IO.File.ReadAllText(p);
                }
            }

            EditorUtility.DisplayProgressBar("导出配置表", "正在运行 Luban…", 0.5f);
            int exitCode;
            try
            {
                using (Process p = Process.Start(psi))
                {
                    p.OutputDataReceived += delegate(object s, DataReceivedEventArgs e)
                    {
                        if (e.Data != null)
                        {
                            lock (output) { output.AppendLine(e.Data); }
                        }
                    };
                    p.ErrorDataReceived += delegate(object s, DataReceivedEventArgs e)
                    {
                        if (e.Data != null)
                        {
                            lock (output) { output.AppendLine(e.Data); }
                        }
                    };
                    p.BeginOutputReadLine();
                    p.BeginErrorReadLine();

                    if (!p.WaitForExit(TimeoutMs))
                    {
                        p.Kill();
                        report.Error("导出超时（超过 " + (TimeoutMs / 1000) + " 秒），已终止进程");
                        return false;
                    }
                    exitCode = p.ExitCode;
                }
            }
            catch (System.Exception ex)
            {
                report.Error("启动 Luban 失败：" + ex.Message);
                return false;
            }
            finally
            {
                EditorUtility.ClearProgressBar();

                // 还原被 Luban 清掉的受保护文件（并补回 .meta，避免 Unity 重新分配 GUID）
                foreach (var kv in kept)
                {
                    if (!System.IO.File.Exists(kv.Key))
                    {
                        System.IO.File.WriteAllText(kv.Key, kv.Value);
                    }
                }
            }

            // 工具的输出对排查很有用（表缺列、类型不匹配都会在这里），全部落到 Console
            string text = output.ToString();
            if (!string.IsNullOrEmpty(text))
            {
                UnityEngine.Debug.Log("[Luban] 工具输出：\n" + text.TrimEnd());
            }

            if (exitCode != 0)
            {
                report.Error(string.Format("Luban 返回非 0（exitCode={0}），请看上方 [Luban] 工具输出", exitCode));
                return false;
            }

            // 产物自检：各表必须都在，且能被当作 TextAsset 读到
            int ok = 0;
            string[] tables = { "tbenemydata", "tbtowerinfo", "tbenemylist", "tbrounddata",
                                "tbsceneinfo", "tbbulletdata", "tblevelmap", "tbglobal", "tblocalization", "tblevelrating" };
            for (int i = 0; i < tables.Length; i++)
            {
                string path = OutDataDir + "/" + tables[i] + ".json";
                if (AssetDatabase.LoadAssetAtPath<TextAsset>(path) == null)
                {
                    report.Error("产物缺失：" + path);
                }
                else
                {
                    ok++;
                }
            }

            if (ok < tables.Length)
            {
                report.Error(string.Format("只产出 {0}/{1} 张表", ok, tables.Length));
                return false;
            }

            AssetDatabase.Refresh();
            report.Ok(string.Format("导出成功：代码 → {0}，数据 → {1}（{2} 张表）",
                OutCodeDir, OutDataDir, ok));
            return true;
        }
    }
}

using System.IO;
using System.Text;
