        [MenuItem("Tools/塔防/0. 自检（先跑这个）", false, 9)]
        public static void SelfCheck()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            RunSelfCheckInternal(report);

            Debug.Log(report.Errors > 0
                ? string.Format("[M0] 自检发现 {0} 个阻塞项：\n{1}", report.Errors, report.Text)
                : string.Format("[M0] 自检完成（错误 {0} · 警告 {1}）：\n{2}",
                    report.Errors, report.Warnings, report.Text));
        }

        /// <summary>
        /// 无弹窗自检（供 Unity MCP / 批处理调用）。
        /// 【为什么单开一个】带 EditorUtility.DisplayDialog 的菜单会**阻塞编辑器**，自动化会卡死。
        /// </summary>
        [MenuItem("Tools/塔防/自动化（无弹窗）/0. 自检", false, 903)]
        public static void SelfCheckNoDialog()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            RunSelfCheckInternal(report);
            Debug.Log(report.Errors > 0
                ? string.Format("[M0] 自检报告（错误 {0} · 警告 {1}）：\n{2}",
                    report.Errors, report.Warnings, report.Text)
                : string.Format("[M0] 自检报告（通过，警告 {0}）：\n{1}",
                    report.Warnings, report.Text));
        }

        private static void RunSelfCheckInternal(EditorUtil.Report report)
        {
            report.Head("M0 交付自检（" + System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "）");

            CheckConfigJson(report);
            CheckResources(report);
            CheckPrefabs(report);
            CheckScene(report);
            CheckProjectSettings(report);
            CheckSorting(report);
            CheckBundles(report);

            report.Head("结论");
            if (report.Errors == 0 && report.Warnings == 0)
            {
                report.Ok("全部检查通过，可以直接 Play 试跑。");
            }
            else if (report.Errors == 0)
            {
                report.Ok(string.Format("无阻塞项，但有 {0} 条提醒（多数不影响运行）。", report.Warnings));
            }
            else
            {
                report.Error(string.Format("发现 {0} 个阻塞项，请按上面的 ✘ 逐条修复。", report.Errors));
            }
        }

