        private static void CheckConfigJson(EditorUtil.Report report)
        {
            report.Head("① 配置表");
            string dir = BuildAssetBundles.ConfigDir;
            string[] expected =
            {
                "tbenemydata", "tbtowerinfo", "tbbulletdata", "tbenemylist",
                "tbrounddata", "tbsceneinfo", "tblevelmap", "tbglobal", "tbaudio", "tblocalization", "tblevelrating"
            };

            for (int i = 0; i < expected.Length; i++)
            {
                string path = dir + "/" + expected[i] + ".json";
                string full = Path.Combine(Directory.GetCurrentDirectory(), path);
                if (!File.Exists(full))
                {
                    report.Error(string.Format(
                        "{0}.json 缺失 —— 请执行 Luban/gen_code_json.bat 导出配置表", expected[i]));
                    continue;
                }
                try
                {
                    JSONNode node = JSONNode.Parse(File.ReadAllText(full, Encoding.UTF8));
                    int count = node != null && node.IsArray ? node.Count : (node != null && node.Count > 0 ? 1 : 0);
                    if (count == 0)
                    {
                        report.Warn(string.Format("{0}.json 没有任何记录", expected[i]));
                    }
                    else
                    {
                        report.Ok(string.Format("{0,-14} {1,3} 条", expected[i], count));
                    }
                }
                catch (System.Exception ex)
                {
                    report.Error(string.Format("{0}.json 解析失败：{1}", expected[i], ex.Message));
                }
            }
        }

        private static void CheckResources(EditorUtil.Report report)
        {
            report.Head("② 资源地址表（ResTable）");
            int total = 0;
            int missing = 0;

            foreach (System.Collections.Generic.KeyValuePair<string, ResAddress> kv in ResTable.All)
            {
                total++;
                ResAddress addr = kv.Value;

                // 配置表用 TextAsset 类型查：只有这样才真实反映"运行时能否读到内容"。
                // （踩过的坑：StreamingAssets 下的 .json 用 Object 查得到、用 TextAsset 查不到）
                bool exists = addr.Bundle == ResBundle.Config
                    ? AssetDatabase.LoadAssetAtPath<TextAsset>(addr.EditorPath) != null
                    : AssetDatabase.LoadAssetAtPath<Object>(addr.EditorPath) != null;

                if (!exists)
                {
                    missing++;
                    report.Error(string.Format("「{0}」指向的文件不存在或类型不对：{1}",
                        kv.Key, addr.EditorPath));
                }
            }

            if (missing == 0)
            {
                report.Ok(string.Format("登记 {0} 条资源全部就绪", total));
            }
        }

        private static void CheckPrefabs(EditorUtil.Report report)
        {
            report.Head("③ 关键预制体与组件");

            // 塔：逐个等级检查（Normal 1 个 + Power 3 级 + Retard 3 级）
            // 每个都必须：世界空间（无 RectTransform）+ SpriteRenderer + barbette/Img_gun + 根组件继承 BaseTower
            // 清单来自 TowerPrefabConverter.TowerResNames（与 tbtowerinfo.json 的 resName 一一对应）
            for (int i = 0; i < TowerPrefabConverter.TowerResNames.Length; i++)
            {
                CheckOneTower(TowerPrefabConverter.TowerResNames[i], report);
            }

            // 子弹
            GameObject bullet = AssetDatabase.LoadAssetAtPath<GameObject>(BattlePrefabBuilder.BulletPath);
            if (bullet == null)
            {
                report.Error("子弹预制体不存在：" + BattlePrefabBuilder.BulletPath);
            }
            else if (bullet.GetComponentInChildren<SpriteRenderer>(true) == null)
            {
                report.Error("Bullet_Normal.prefab 没有 SpriteRenderer");
            }
            else if (!HasScript(bullet, "BaseBullet"))
            {
                report.Error("Bullet_Normal.prefab 上没有挂 BaseBullet 脚本");
            }
            else
            {
                report.Ok("Bullet_Normal.prefab：SpriteRenderer + BaseBullet");
            }

            // 怪物：119 个逐个报太啰嗦 → 全量存在性检查 + 抽样结构检查
            int monsterTotal = MonsterCatalog.Count;
            int monsterMissing = 0;
            string firstMissing = null;
            for (int i = 0; i < monsterTotal; i++)
            {
                if (AssetDatabase.LoadAssetAtPath<GameObject>(MonsterCatalog.PrefabPath(i)) == null)
                {
                    monsterMissing++;
                    if (firstMissing == null)
                    {
                        firstMissing = MonsterCatalog.PrefabPath(i);
                    }
                }
            }
            if (monsterMissing > 0)
            {
                report.Error(string.Format(
                    "{0}/{1} 个怪物战斗预制体不存在（例：{2}）\n" +
                    "      修复：执行「Tools ▸ 塔防 ▸ 高级（单步重建）▸ 导入全部怪物」",
                    monsterMissing, monsterTotal, firstMissing));
            }
            else
            {
                report.Ok(string.Format("{0} 个怪物战斗预制体全部存在", monsterTotal));
            }

            // 抽样检查结构（第 1 个 + 随机一个，避免只对第一个成立）
            if (monsterMissing == 0 && monsterTotal > 0)
            {
                CheckMonsterSample(report, 0);
                CheckMonsterSample(report, monsterTotal / 2);
                CheckMonsterSample(report, monsterTotal - 1);
            }
            // UI
            // ★ 文本节点是芯片底的子节点（路径两段式）：Bg_Gold/GoldText 等。
            //   塔按钮当前只有三颗（穿透/激光已从 HUD 撤下，见 UIPrefabBuilder.TowerButtons）。
            CheckUiPrefab(report, UIPrefabBuilder.HudPath, "HudView",
                new[] { "Bg_Gold/GoldText", "Bg_Hp/HpText", "Bg_Round/RoundText",
                        "StartButton", "SpeedButton",
                        "Btn_Tower_Normal", "Btn_Tower_Power", "Btn_Tower_Retard",
                        "Btn_Pause", "Btn_Intro" });
            // ★ TipText 是底条 TipBar 的子节点（两段式路径），2026-10-15 手工版移入。
            CheckUiPrefab(report, UIPrefabBuilder.TipsPath, "TipsView", new[] { "TipBar/TipText" });
            CheckUiPrefab(report, UIPrefabBuilder.TowerInfoPath, "TowerInfoView", new[] { "Bg", "Panel" });
            CheckUiPrefab(report, UIPrefabBuilder.SelectPath, "SelectView", new[] { "Bg", "Panel" });
            CheckUiPrefab(report, UIPrefabBuilder.PausePath, "PauseView", new[] { "Bg", "Panel" });
            CheckUiPrefab(report, UIPrefabBuilder.SettingPath, "SettingView", new[] { "Bg", "Panel" });
            // 关卡结算弹窗：没有它，通关后玩家看不到任何结算界面
            // （深一层的节点契约由 .workbuddy/tools/check_ui_contract.py 校验）
            CheckUiPrefab(report, UIPrefabBuilder.LevelClearPath, "LevelClearView", new[] { "Bg", "Panel" });
            // 游戏介绍弹窗（2026-10-14）
            CheckUiPrefab(report, UIPrefabBuilder.GameIntroPath, "GameIntroView", new[] { "Bg", "Panel" });
        }

        /// <summary>
        /// 单个塔 prefab 自检：世界空间（无 RectTransform）+ SpriteRenderer + barbette/Img_gun + 根组件继承 BaseTower。
        /// Normal 与 Power/Retard 各等级共用同一套结构，逐一调用。
        /// </summary>
        private static void CheckOneTower(string resName, EditorUtil.Report report)
        {
            string path = TowerPrefabConverter.TowerPath(resName);
            GameObject tower = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (tower == null)
            {
                report.Error(resName + ".prefab 不存在：" + path +
                             "（请执行「高级（单步重建）▸ 转换防御塔预制体」）");
                return;
            }
            if (tower.GetComponent<RectTransform>() != null)
            {
                report.Error(resName + ".prefab 仍是 UGUI（带 RectTransform），" +
                             "请执行「高级（单步重建）▸ 转换防御塔预制体」");
                return;
            }
            if (tower.GetComponentInChildren<SpriteRenderer>(true) == null)
            {
                report.Error(resName + ".prefab 里没有 SpriteRenderer，无法显示");
                return;
            }
            if (tower.transform.Find("barbette/Img_gun") == null)
            {
                report.Error(resName + ".prefab 缺少 barbette/Img_gun 节点，" +
                             "BaseTower 找不到炮管，塔不会转向");
                return;
            }
            if (tower.transform.Find("barbette/Img_gun/BarrelPoint") == null)
            {
                report.Warn(resName + ".prefab：炮管下没有 BarrelPoint，子弹会从塔中心而不是枪口发出（不影响玩法）");
            }
            else
            {
                report.Ok(resName + ".prefab：世界空间 SpriteRenderer + 炮管 + 出膛点");
            }

            // 根组件必须是 BaseTower 的派生（三塔子类功能等价，只校验基类存在）
            if (tower.GetComponent<BaseTower>() == null)
            {
                report.Error(resName + ".prefab 上没有挂 BaseTower 及其子类脚本");
            }
        }

        /// <summary>抽样检查某个怪物的战斗预制体结构</summary>
        private static void CheckMonsterSample(EditorUtil.Report report, int index)
        {
            string path = MonsterCatalog.PrefabPath(index);
            GameObject go = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (go == null)
            {
                return;
            }
            string tag = System.IO.Path.GetFileName(path);

            if (!HasScript(go, "BaseEnemy"))
            {
                report.Error(tag + " 上没有挂 BaseEnemy 脚本");
            }
            if (go.GetComponentInChildren<Collider2D>(true) != null ||
                go.GetComponentInChildren<Collider>(true) != null ||
                go.GetComponentInChildren<Rigidbody2D>(true) != null ||
                go.GetComponentInChildren<Rigidbody>(true) != null)
            {
                report.Error(tag + " 上仍有物理组件（Collider/Rigidbody），" +
                             "请执行「导入全部怪物」或「清理全部战斗预制体的物理组件」（均在「高级（单步重建）」下）");
            }
            else if (go.transform.Find("HpBar/Fill") == null)
            {
                report.Error(tag + " 缺少 HpBar/Fill 节点，血条不会显示");
            }
            else
            {
                report.Ok(tag + "：BaseEnemy / 无物理组件 / HpBar 均就绪（抽样）");
            }
        }

        /// <summary>按类型名判断预制体上是否挂了某个脚本（不直接依赖运行时代码的类型，避免编辑器程序集耦合）</summary>
        private static bool HasScript(GameObject prefab, string typeName)
        {
            MonoBehaviour[] comps = prefab.GetComponentsInChildren<MonoBehaviour>(true);
            for (int i = 0; i < comps.Length; i++)
            {
                if (comps[i] != null && comps[i].GetType().Name == typeName)
                {
                    return true;
                }
            }
            return false;
        }

        private static void CheckUiPrefab(EditorUtil.Report report, string path, string rootName, string[] childNames)
        {
            GameObject go = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (go == null)
            {
                report.Error("UI 预制体不存在：" + path + "（请执行「高级（单步重建）▸ 生成 UI 预制体」）");
                return;
            }
            if (!HasScript(go, rootName))
            {
                report.Error(path + " 上没有挂 " + rootName + " 脚本");
            }
            int missing = 0;
            for (int i = 0; i < childNames.Length; i++)
            {
                if (go.transform.Find(childNames[i]) == null)
                {
                    missing++;
                    report.Error(string.Format(
                        "{0} 缺少子节点「{1}」—— {2}.cs 用 transform.Find 查找它，名字必须一致",
                        path, childNames[i], rootName));
                }
            }
            if (missing == 0)
            {
                report.Ok(Path.GetFileName(path) + "：节点齐备（" + string.Join(" / ", childNames) + "）");
            }

            // 【字体组件口径】全工程统一 TextMeshPro：prefab 里不允许再出现 UGUI Text。
            //   这条一旦回归，症状是"文字在移动包成方块 / 工程里两套字体并存"，
            //   很难从运行日志看出来，所以在自检里显式拦住。
            UnityEngine.UI.Text legacy = go.GetComponentInChildren<UnityEngine.UI.Text>(true);
            if (legacy != null)
            {
                report.Error(string.Format(
                    "{0} 仍含 UGUI Text 组件（节点「{1}」）—— 请执行「高级（单步重建）▸ 把 UI 预制体的 Text 迁移为 TextMeshPro」",
                    Path.GetFileName(path), legacy.gameObject.name));
            }
            else if (go.GetComponentInChildren<TMPro.TMP_Text>(true) == null)
            {
                report.Warn(Path.GetFileName(path) + " 里没有任何 TMP 文本组件（若该界面本就没有文字可忽略）");
            }
            else
            {
                report.Ok(Path.GetFileName(path) + "：文本全部使用 TextMeshPro");
            }
        }

        private static void CheckScene(EditorUtil.Report report)
        {
            report.Head("④ 主场景");
            string path = SceneMainBuilder.MainScenePath;
            string full = Path.Combine(Directory.GetCurrentDirectory(), path);
            if (!File.Exists(full))
            {
                report.Error("主场景不存在：" + path + "（请执行「高级（单步重建）▸ 重建 main 场景」）");
                return;
            }

            // 【注意】场景 YAML 里脚本引用是 GUID，不出现类名；能匹配的只有 GameObject 的
            // m_Name 与 m_TagString。所以这里只检查**对象名**，并用 "m_Name: X" 精确匹配，
            // 避免"Camera"这种词在别处偶然命中造成假通过。
            string text = File.ReadAllText(full, Encoding.UTF8);
            string[] requiredObjects =
            {
                "Camera", "EventSystem", "Launcher", "UICanvas",
                "BgPanel", "NormalPanel", "TipsPanel",
                "BattleRoot", "Background", "BoardRoot", "PathRoot",
                "TowerRoot", "EnemyRoot", "BulletRoot",
                "GameFlow", "GameSceneLauncher"
            };
            int missing = 0;
            for (int i = 0; i < requiredObjects.Length; i++)
            {
                if (!text.Contains("m_Name: " + requiredObjects[i]))
                {
                    missing++;
                    report.Error(path + " 中缺少对象「" + requiredObjects[i] + "」");
                }
            }
            if (missing == 0)
            {
                report.Ok(string.Format("场景包含全部 {0} 个必需对象", requiredObjects.Length));
            }

            // Canvas 的 Tag 必须真的写进了场景（UIManager 靠它查找）
            if (text.Contains("m_TagString: " + ProjectSettingsConfigurator.UiCanvasTag))
            {
                report.Ok("UICanvas 的 Tag 已正确写入场景");
            }
            else
            {
                report.Error("场景里没有任何对象带 Tag「" + ProjectSettingsConfigurator.UiCanvasTag +
                             "」，UIManager 找不到根 Canvas，UI 打不开");
            }
        }

        private static void CheckProjectSettings(EditorUtil.Report report)
        {
            report.Head("⑤ 工程设置");

            // Tag
            Object[] tagAssets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset");
            bool hasTag = false;
            if (tagAssets != null && tagAssets.Length > 0)
            {
                SerializedObject so = new SerializedObject(tagAssets[0]);
                SerializedProperty tags = so.FindProperty("tags");
                if (tags != null)
                {
                    for (int i = 0; i < tags.arraySize; i++)
                    {
                        if (tags.GetArrayElementAtIndex(i).stringValue == ProjectSettingsConfigurator.UiCanvasTag)
                        {
                            hasTag = true;
                            break;
                        }
                    }
                }
            }
            if (hasTag)
            {
                report.Ok("Tag「UICanvas」已存在（UIManager 靠它找根 Canvas）");
            }
            else
            {
                report.Error("Tag「UICanvas」缺失，UI 打不开。请执行「2. 配置工程设置」");
            }

            // 渲染排序
            Object[] gsAssets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset");
            bool sortOk = false;
            if (gsAssets != null && gsAssets.Length > 0)
            {
                SerializedObject so = new SerializedObject(gsAssets[0]);
                SerializedProperty mode = so.FindProperty("m_TransparencySortMode");
                SerializedProperty axis = so.FindProperty("m_TransparencySortAxis");
                if (mode != null && axis != null && mode.intValue == 3 &&
                    Mathf.Approximately(axis.vector3Value.y, -1f))
                {
                    sortOk = true;
                }
            }
            if (sortOk)
            {
                report.Ok("Transparency Sort Mode = Custom Axis (0,-1,0)（塔怪能按 Y 正确遮挡）");
            }
            else
            {
                report.Warn("Transparency Sort Mode 未设为 Custom Axis (0,-1,0)，" +
                            "塔与怪的前后遮挡关系会不可控。请执行「2. 配置工程设置」");
            }

            // Build Settings
            EditorBuildSettingsScene[] scenes = EditorBuildSettings.scenes;
            if (scenes == null || scenes.Length == 0)
            {
                report.Error("Build Settings 里没有任何场景，打包会失败");
            }
            else if (scenes.Length > 1)
            {
                report.Warn(string.Format("Build Settings 里有 {0} 个场景，M0 只需要 main.unity", scenes.Length));
            }
            else if (scenes[0].path != SceneMainBuilder.MainScenePath)
            {
                report.Warn("Build Settings 的首个场景不是 main.unity：" + scenes[0].path);
            }
            else
            {
                report.Ok("Build Settings：仅 main.unity");
            }
        }

        /// <summary>
        /// 渲染层级自检（2026-10-21 新增）。
        ///
        /// 判定逻辑复用 <see cref="SortingLayerNormalizer.AuditFindings"/>，与「校验 ▸ 渲染层级体检」
        /// 完全同源 —— 目的不是重复检查，而是让**每一次标准自检**都能发现"某个重建脚本把层级冲掉"：
        /// 怪必须是 Main/300、塔必须是 Main/200（永远怪压塔）、血条组内 500/501、排序层只剩 Bg/Main/Pop。
        /// </summary>
        private static void CheckSorting(EditorUtil.Report report)
        {
            report.Head("⑥ 渲染层级（怪压塔 / Bg-Main-Pop）");
            var details = new StringBuilder();
            int issues = SortingLayerNormalizer.AuditFindings(details);
            if (issues == 0)
            {
                report.Ok("层级与约定一致：怪 300 > 塔 200；血条组内 500/501；伤害飘字在 Pop 层；飘字压住一切");
            }
            else
            {
                report.Error(string.Format(
                    "发现 {0} 处层级偏差，跑「高级（单步重建）▸ 标准化渲染层级（预置体+场景）」可一键修复：\n{1}",
                    issues, details));
            }
        }

        private static void CheckBundles(EditorUtil.Report report)
        {
            report.Head("⑦ AssetBundle（编辑器试跑不需要，出包/验证 AB 时才需要）");
            string dir = ResPathUtil.BuildOutputRoot;
            if (!Directory.Exists(dir))
            {
                report.Warn("尚未打包过 AB（" + dir + "）。编辑器下走直读模式可以正常试跑，" +
                            "但出真机包之前必须执行「5. 打包 AssetBundle」");
                return;
            }

            for (int i = 0; i < ResBundle.All.Length; i++)
            {
                string file = Path.Combine(dir, ResBundle.All[i]);
                if (File.Exists(file))
                {
                    report.Ok(string.Format("{0,-16} {1,8:F1} KB", ResBundle.All[i],
                        new FileInfo(file).Length / 1024f));
                }
                else
                {
                    // 降级为提示：编辑器试跑走直读模式，不需要 AB；
                    // 而且新增了 16 个怪物家族包后，旧的一次打包结果必然"缺"它们。
                    report.Warn("包缺失：" + ResBundle.All[i] +
                                "（出真机包前重新执行「5. 打包 AssetBundle」即可全部产出）");
                }
            }
            string manifest = Path.Combine(dir, ResPathUtil.ManifestBundleName);
            if (!File.Exists(manifest))
            {
                report.Error("主清单缺失：" + ResPathUtil.ManifestBundleName);
            }
        }
    }
}

//------------------------------------------------------------------------------
// 预制体 Missing Script 批量清理工具（核心逻辑）
//
// 功能：选中一个（或多个）文件夹后，递归遍历其下所有 .prefab，
//       移除每个预制体上（含所有子物体、含未激活物体）的 Missing Script 组件。
//
// 入口见文件底部的 MenuItem 区域，也可从 MissingScriptCleanerWindow 面板调用。
//------------------------------------------------------------------------------
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Text;
using UnityEditor;
using UnityEngine;
using Debug = UnityEngine.Debug;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 单个预制体的处理结果
    /// </summary>
    public class CleanResult
    {
        /// <summary>预制体资源路径（Assets/...xxx.prefab）</summary>
        public string AssetPath;

        /// <summary>本次移除的 Missing Script 组件数量</summary>
        public int RemovedCount;

        /// <summary>失败原因，为空表示成功</summary>
        public string Error;

        /// <summary>是否被跳过（例如 FBX 模型预制体不可编辑）</summary>
        public bool IsSkipped;

        /// <summary>跳过原因</summary>
        public string SkipReason;

        /// <summary>是否为预制体变体（Prefab Variant），保存后建议在版本控制中复核差异</summary>
        public bool IsVariant;

        /// <summary>是否属于“需要关注”的条目（有改动或出错）</summary>
        public bool HasChange { get { return RemovedCount > 0 || !string.IsNullOrEmpty(Error); } }
    }

    /// <summary>
    /// 一次批量清理任务的汇总报告
    /// </summary>
    public class CleanReport
    {
        /// <summary>是否为预览模式（只扫描不修改）</summary>
        public bool DryRun;

        /// <summary>是否被用户中途取消</summary>
        public bool Canceled;

        /// <summary>实际扫描到的预制体数量</summary>
        public int Scanned;

        /// <summary>被修改并保存的预制体数量</summary>
        public int Modified;

        /// <summary>累计移除的 Missing Script 组件数量</summary>
        public int RemovedTotal;

        /// <summary>处理失败的预制体数量</summary>
        public int Failed;

        /// <summary>被跳过的预制体数量</summary>
        public int Skipped;

        /// <summary>耗时（毫秒）</summary>
        public double ElapsedMs;

        /// <summary>扫描的根路径（用于展示）</summary>
        public readonly List<string> Roots = new List<string>();

        /// <summary>明细列表（含改动项、失败项、跳过项）</summary>
        public readonly List<CleanResult> Details = new List<CleanResult>();

        /// <summary>生成一段人类可读的汇总文案</summary>
        public string Describe()
        {
            var sb = new StringBuilder();
            sb.AppendLine(string.Format("模式：{0}", DryRun ? "预览扫描（未修改任何文件）" : "执行清理（已写回磁盘）"));
            if (Roots.Count > 0)
            {
                sb.AppendLine(string.Format("扫描范围：{0}", string.Join("，", Roots.ToArray())));
            }
            sb.AppendLine(string.Format("扫描预制体：{0} 个", Scanned));
            sb.AppendLine(string.Format("发现 Missing Script：{0} 个", RemovedTotal));
            sb.AppendLine(string.Format("受影响预制体：{0} 个", Modified));
            if (Skipped > 0) sb.AppendLine(string.Format("跳过：{0} 个", Skipped));
            if (Failed > 0) sb.AppendLine(string.Format("失败：{0} 个", Failed));
            if (Canceled) sb.AppendLine("提示：任务被手动取消，未处理的预制体保持原样。");
            sb.AppendLine(string.Format("耗时：{0:F0} ms", ElapsedMs));
            return sb.ToString().TrimEnd();
        }
    }

    /// <summary>
    /// 预制体 Missing Script 清理器
    /// </summary>
    public static class MissingScriptCleaner
    {
        /// <summary>上一次执行的结果，供结果面板读取</summary>
        public static CleanReport LastReport;

        #region 菜单入口

        [MenuItem("Tools/资源工具/清理预制体 Missing Script/打开清理面板", false, 0)]
        public static void OpenWindow()
        {
            MissingScriptCleanerWindow.ShowWindow();
        }

        /// <summary>菜单入口一：清理 Project 窗口中选中的文件夹（支持多选）</summary>
        [MenuItem("Tools/资源工具/清理预制体 Missing Script/清理 Project 窗口中选中的文件夹", false, 10)]
        public static void CleanFromSelection()
        {
            List<string> paths = GetSelectedAssetPaths();
            if (paths.Count == 0)
            {
                Debug.LogWarning("[MissingScript清理] 未选中文件夹：请先在 Project 窗口中选中一个（或多个）文件夹，再执行该命令。");
                return;
            }
            RunAndReport(paths, false, true, false);
        }

        [MenuItem("Tools/资源工具/清理预制体 Missing Script/清理 Project 窗口中选中的文件夹", true)]
        private static bool ValidateCleanFromSelection()
        {
            return GetSelectedAssetPaths().Count > 0;
        }

        /// <summary>
        /// 菜单入口二：Project 窗口右键菜单（对选中的文件夹 / 预制体直接生效）
        /// </summary>
        [MenuItem("Assets/清理选中项中的 Missing Script", false, 1000)]
        public static void CleanFromContextMenu()
        {
            List<string> paths = GetSelectedAssetPaths();
            if (paths.Count == 0)
            {
                Debug.LogWarning("[MissingScript清理] 未选中资源：请在 Project 窗口中选中需要处理的文件夹或预制体。");
                return;
            }
            RunAndReport(paths, false, true, false);
        }

        [MenuItem("Assets/清理选中项中的 Missing Script", true)]
        private static bool ValidateCleanFromContextMenu()
        {
            return GetSelectedAssetPaths().Count > 0;
        }

        /// <summary>
        /// 菜单入口三：只扫描不修改，用于执行前评估影响范围
        /// </summary>
        [MenuItem("Tools/资源工具/清理预制体 Missing Script/预览扫描（不修改文件）", false, 11)]
        public static void PreviewFromSelection()
        {
            List<string> paths = GetSelectedAssetPaths();
            if (paths.Count == 0)
            {
                Debug.LogWarning("[MissingScript清理] 未选中文件夹：请先在 Project 窗口中选中一个（或多个）文件夹，再执行该命令。");
                return;
            }
            RunAndReport(paths, true, true, false);
        }

        #endregion

        #region 对外调用接口

        /// <summary>
        /// 带确认弹窗地执行清理。**仅用于人工交互**，自动化不得调用（会阻塞编辑器）。
        /// 自动化请直接用 <see cref="RunAndReport"/>（把 showDialog 传 false）。
        /// </summary>
        public static void RunWithConfirm(List<string> assetPaths, bool dryRun, bool showResultDialog)
        {
            string message = dryRun
                ? "即将递归遍历所选范围下的全部预制体，统计其中的 Missing Script 组件数量。\n\n此过程不会修改任何文件。是否继续？"
                : "即将递归遍历所选范围下的全部预制体，并移除其中的 Missing Script 组件。\n\n"
                  + "该操作会直接写回 .prefab 文件，且无法通过 Ctrl+Z 撤销，建议先提交一次版本控制。\n\n是否继续？";

            if (!EditorUtility.DisplayDialog(dryRun ? "预览扫描" : "确认清理", message, "开始执行", "取消"))
            {
                return;
            }
            RunAndReport(assetPaths, dryRun, true, showResultDialog);
        }

        /// <summary>
        /// 执行清理，并把汇总结果打到 Console。
        /// </summary>
        /// <param name="assetPaths">文件夹路径或 .prefab 资源路径（可混合）</param>
        /// <param name="dryRun">true = 只扫描统计，不写回文件</param>
        /// <param name="verbose">是否输出每个预处理文件的日志</param>
        /// <param name="openDetailWindow">结束后是否直接打开结果面板（人工交互用；自动化传 false）</param>
        public static CleanReport RunAndReport(List<string> assetPaths, bool dryRun, bool verbose, bool openDetailWindow)
        {
            CleanReport report = Run(assetPaths, dryRun, verbose);
            LastReport = report;

            // 【为什么不再弹窗】带 DisplayDialog 的菜单会阻塞编辑器，自动化调用直接卡死。
            // 汇总一律打日志；需要看明细时由人主动点「打开清理面板」。
            Debug.Log(string.Format("[MissingScript清理] {0}：\n{1}",
                dryRun ? "预览扫描完成（未修改任何文件）" : "清理完成（已写回磁盘）",
                report.Describe()));

            if (openDetailWindow)
            {
                MissingScriptCleanerWindow.ShowWindow();
            }
            return report;
        }

        /// <summary>
        /// 核心执行逻辑：收集预制体 → 逐个处理 → 生成报告
        /// </summary>
        public static CleanReport Run(List<string> assetPaths, bool dryRun, bool verbose)
        {
            CleanReport report = new CleanReport();
            report.DryRun = dryRun;

            Stopwatch watch = Stopwatch.StartNew();

            if (assetPaths == null || assetPaths.Count == 0)
            {
                watch.Stop();
                report.ElapsedMs = watch.Elapsed.TotalMilliseconds;
                Debug.LogWarning("[MissingScript清理] 没有传入任何路径，任务结束。");
                return report;
            }

            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                Debug.LogWarning("[MissingScript清理] 当前处于运行模式，建议退出 Play 模式后再执行，以免资源被运行时占用。");
            }

            // 收集（去重 + 排序，保证结果稳定可复现）
            List<string> prefabPaths = CollectPrefabPaths(assetPaths, report);

            report.Scanned = prefabPaths.Count;
            Debug.Log(string.Format("[MissingScript清理] 开始{0}，共 {1} 个预制体。",
                dryRun ? "预览扫描" : "清理", report.Scanned));

            try
            {
                ProcessAllPrefabs(prefabPaths, report, dryRun, verbose);
            }
            finally
            {
                // 无论成功、失败还是被用户取消，都必须收起进度条
                EditorUtility.ClearProgressBar();
            }

            if (!dryRun && report.Modified > 0)
            {
                AssetDatabase.SaveAssets();
                AssetDatabase.Refresh();
            }

            watch.Stop();
            report.ElapsedMs = watch.Elapsed.TotalMilliseconds;

            // 汇总日志（content 末尾附带 Console 可点击的上下文对象）
            Debug.Log(string.Format("[MissingScript清理] ===== 任务结束 =====\n{0}", report.Describe()));

            return report;
        }

        /// <summary>
        /// 逐个处理预制体并写入报告（进度条由调用方统一收起）
        /// </summary>
        private static void ProcessAllPrefabs(List<string> prefabPaths, CleanReport report, bool dryRun, bool verbose)
        {
            int index = 0;
            foreach (string path in prefabPaths)
            {
                index++;

                // 可取消的进度条，避免大批量处理时界面假死
                bool canceled = EditorUtility.DisplayCancelableProgressBar(
                    dryRun ? "预览扫描 Missing Script" : "清理 Missing Script",
                    string.Format("{0}/{1}  {2}", index, report.Scanned, path),
                    (float)index / Mathf.Max(1, report.Scanned));

                if (canceled)
                {
                    report.Canceled = true;
                    Debug.LogWarning(string.Format("[MissingScript清理] 已被手动取消，已处理 {0}/{1} 个预制体。",
                        index - 1, report.Scanned));
                    break;
                }

                CleanResult result = ProcessPrefab(path, dryRun);
                report.Details.Add(result);

                if (result.IsSkipped)
                {
                    report.Skipped++;
                    if (verbose && !string.IsNullOrEmpty(result.SkipReason))
                    {
                        Debug.Log(string.Format("[MissingScript清理] 已跳过（{0}）：{1}", result.SkipReason, path));
                    }
                    continue;
                }

                if (!string.IsNullOrEmpty(result.Error))
                {
                    report.Failed++;
                    Debug.LogError(string.Format("[MissingScript清理] 处理失败：{0}\n原因：{1}", path, result.Error),
                        AssetDatabase.LoadAssetAtPath<GameObject>(path));
                    continue;
                }

                if (result.RemovedCount > 0)
                {
                    report.Modified++;
                    report.RemovedTotal += result.RemovedCount;

                    if (dryRun)
                    {
                        Debug.LogWarning(string.Format("[MissingScript清理] 预览：该预制体存在 {0} 个 Missing Script（未修改）",
                            result.RemovedCount), AssetDatabase.LoadAssetAtPath<GameObject>(path));
                    }
                    else
                    {
                        Debug.LogWarning(string.Format("[MissingScript清理] 已移除 {0} 个 Missing Script",
                            result.RemovedCount), AssetDatabase.LoadAssetAtPath<GameObject>(path));
                    }
                }
                else if (verbose)
                {
                    Debug.Log(string.Format("[MissingScript清理] 干净，无需处理：{0}", path));
                }
            }
        }

        #endregion

        #region 内部实现

        /// <summary>
        /// 把“文件夹 + 预制体文件”的混合输入展开为去重后的预制体路径列表
        /// </summary>
        private static List<string> CollectPrefabPaths(List<string> assetPaths, CleanReport report)
        {
            HashSet<string> set = new HashSet<string>();

            foreach (string raw in assetPaths)
            {
                if (string.IsNullOrEmpty(raw))
                {
                    continue;
                }

                string path = raw.Replace('\\', '/').TrimEnd('/');

                if (AssetDatabase.IsValidFolder(path))
                {
                    if (!report.Roots.Contains(path))
                    {
                        report.Roots.Add(path);
                    }

                    // FindAssets 默认递归搜索子文件夹
                    string[] guids = AssetDatabase.FindAssets("t:Prefab", new string[] { path });
                    foreach (string guid in guids)
                    {
                        string assetPath = AssetDatabase.GUIDToAssetPath(guid);
                        if (IsPrefabFile(assetPath))
                        {
                            set.Add(assetPath);
                        }
                    }
                }
                else if (IsPrefabFile(path))
                {
                    string folder = System.IO.Path.GetDirectoryName(path).Replace('\\', '/');
                    if (!report.Roots.Contains(folder))
                    {
                        report.Roots.Add(folder);
                    }
                    set.Add(path);
                }
                else
                {
                    Debug.LogWarning(string.Format("[MissingScript清理] 忽略无效路径：{0}", raw));
                }
            }

            List<string> list = new List<string>(set);
            list.Sort(StringComparer.OrdinalIgnoreCase);
            return list;
        }

        /// <summary>判断是否为 .prefab 资源</summary>
        private static bool IsPrefabFile(string assetPath)
        {
            return !string.IsNullOrEmpty(assetPath)
                   && assetPath.EndsWith(".prefab", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>
        /// 处理单个预制体：加载内容 → 统计 → 移除 → 保存
        /// </summary>
        private static CleanResult ProcessPrefab(string path, bool dryRun)
        {
            CleanResult result = new CleanResult { AssetPath = path };

            // 模型预制体（FBX 导入产生）属于只读资源，无法就地编辑，直接跳过
            GameObject asset = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (asset == null)
            {
                result.IsSkipped = true;
                result.SkipReason = "资源缺失或无法加载";
                return result;
            }

            PrefabAssetType assetType = PrefabUtility.GetPrefabAssetType(asset);
            if (assetType == PrefabAssetType.Model)
            {
                result.IsSkipped = true;
                result.SkipReason = "模型预制体（FBX 导入，只读）";
                return result;
            }
            if (assetType == PrefabAssetType.NotAPrefab || assetType == PrefabAssetType.MissingAsset)
            {
                result.IsSkipped = true;
                result.SkipReason = "不是有效的预制体资源";
                return result;
            }
            result.IsVariant = assetType == PrefabAssetType.Variant;

            GameObject contents = null;
            try
            {
                // 以“预制体内容”方式打开，可直接修改并写回资源文件
                contents = PrefabUtility.LoadPrefabContents(path);

                int before = CountMissingScripts(contents);

                if (dryRun)
                {
                    result.RemovedCount = before;
                    return result;
                }

                if (before == 0)
                {
                    result.RemovedCount = 0;
                    return result;
                }

                // 官方 API：按 GameObject 逐个清理，含未激活物体
                Transform[] all = contents.GetComponentsInChildren<Transform>(true);
                for (int i = 0; i < all.Length; i++)
                {
                    GameObjectUtility.RemoveMonoBehavioursWithMissingScript(all[i].gameObject);
                }

                int after = CountMissingScripts(contents);
                result.RemovedCount = Mathf.Max(0, before - after);

                if (result.RemovedCount > 0)
                {
                    bool success;
                    PrefabUtility.SaveAsPrefabAsset(contents, path, out success);
                    if (!success)
                    {
                        result.Error = "保存预制体失败（SaveAsPrefabAsset 返回 false），文件可能被版本控制锁定或只读。";
                    }
                    else if (result.IsVariant)
                    {
                        Debug.LogWarning(string.Format(
                            "[MissingScript清理] 该资源是预制体变体（Variant），已就地保存，建议在版本控制中复核其与基预制体的继承关系是否正常：{0}",
                            path), AssetDatabase.LoadAssetAtPath<GameObject>(path));
                    }
                }
            }
            catch (Exception ex)
            {
                result.Error = ex.Message;
            }
            finally
            {
                // 必须配对释放，否则会在预览场景中泄漏对象
                if (contents != null)
                {
                    PrefabUtility.UnloadPrefabContents(contents);
                }
            }

            return result;
        }

        /// <summary>
        /// 统计 GameObject 及其所有子物体上的 Missing Script 数量。
        /// 通过 SerializedObject 遍历 m_Component 数组，遇到空引用即为残留脚本，
        /// 该方式不依赖具体 Unity 版本，比反射更稳定。
        /// </summary>
        private static int CountMissingScripts(GameObject root)
        {
            int count = 0;
            Transform[] all = root.GetComponentsInChildren<Transform>(true);

            for (int i = 0; i < all.Length; i++)
            {
                SerializedObject so = new SerializedObject(all[i].gameObject);
                SerializedProperty components = so.FindProperty("m_Component");
                if (components == null)
                {
                    continue;
                }
                for (int j = 0; j < components.arraySize; j++)
                {
                    SerializedProperty element = components.GetArrayElementAtIndex(j);
                    if (element.objectReferenceValue == null)
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        /// <summary>
        /// 读取 Project 窗口中当前选中的资源路径（文件夹与预制体均可）
        /// </summary>
        public static List<string> GetSelectedAssetPaths()
        {
            List<string> list = new List<string>();
            UnityEngine.Object[] selected = Selection.GetFiltered(typeof(UnityEngine.Object), SelectionMode.Assets);
            foreach (UnityEngine.Object obj in selected)
            {
                string path = AssetDatabase.GetAssetPath(obj);
                if (!string.IsNullOrEmpty(path) && (AssetDatabase.IsValidFolder(path) || IsPrefabFile(path)))
                {
                    list.Add(path);
                }
            }
            return list;
        }

        #endregion
    }
}

//------------------------------------------------------------------------------
// 预制体 Missing Script 批量清理工具（可视化面板）
//
// 提供：拖拽选择文件夹、预览/执行切换、结果列表与一键定位。
//------------------------------------------------------------------------------
using System.Collections.Generic;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 清理工具面板：选择文件夹 → 扫描/清理 → 查看结果
    /// </summary>
    public class MissingScriptCleanerWindow : EditorWindow
    {
        /// <summary>待处理的目标（文件夹或预制体）</summary>
        private UnityEngine.Object _target;

        /// <summary>true = 只扫描不修改</summary>
        private bool _dryRun = true;

        /// <summary>是否输出每个文件的详细日志</summary>
        private bool _verbose = false;

        /// <summary>结果列表是否只展示有改动/有错误的条目</summary>
        private bool _onlyChanged = true;

        private Vector2 _scroll;

        // GUIStyle 必须在 OnGUI 期间按需创建，避免在静态构造 / 序列化阶段触发 Unity 警告
        private GUIStyle _titleStyle;
        private GUIStyle _itemStyle;

        /// <summary>打开面板（若已存在则聚焦）</summary>
        public static void ShowWindow()
        {
            MissingScriptCleanerWindow win = GetWindow<MissingScriptCleanerWindow>("Missing Script 清理");
            win.minSize = new Vector2(560f, 480f);
            win.Show();
        }

        private void OnEnable()
        {
            // 打开面板时自动带入 Project 窗口的选中项
            PickFromSelection();
        }

        private void EnsureStyles()
        {
            if (_titleStyle == null)
            {
                _titleStyle = new GUIStyle(EditorStyles.boldLabel);
                _titleStyle.fontSize = 13;
                _titleStyle.margin = new RectOffset(0, 0, 6, 4);
            }
            if (_itemStyle == null)
            {
                _itemStyle = new GUIStyle(EditorStyles.label);
                _itemStyle.richText = true;
                _itemStyle.wordWrap = false;
                _itemStyle.padding = new RectOffset(4, 4, 2, 2);
            }
        }

        private void OnGUI()
        {
            EnsureStyles();

            DrawHeader();
            EditorGUILayout.Space();

            DrawTargetField();
            EditorGUILayout.Space();

            DrawOptions();
            EditorGUILayout.Space();

            DrawActionButtons();
            EditorGUILayout.Space();

            DrawReport();
        }

        #region 界面分区

        private void DrawHeader()
        {
            EditorGUILayout.LabelField("预制体 Missing Script 批量清理", _titleStyle);
            EditorGUILayout.HelpBox(
                "选择目标文件夹后，工具会递归遍历其中全部 .prefab（含子文件夹、子物体与未激活物体），"
                + "移除残留的 Missing Script 组件。\n"
                + "建议先点“预览扫描”确认影响范围，再执行清理；该操作会写回资源文件且无法 Ctrl+Z 撤销，请先提交版本控制。",
                MessageType.Info);
        }

        private void DrawTargetField()
        {
            EditorGUILayout.LabelField("目标文件夹 / 预制体", EditorStyles.boldLabel);

            EditorGUI.BeginChangeCheck();
            _target = EditorGUILayout.ObjectField(_target, typeof(UnityEngine.Object), false);
            if (EditorGUI.EndChangeCheck())
            {
                ValidateTarget();
            }

            using (new EditorGUILayout.HorizontalScope())
            {
                if (GUILayout.Button("使用 Project 窗口选中项", GUILayout.Height(22f)))
                {
                    PickFromSelection();
                }
                if (GUILayout.Button("清空目标", GUILayout.Height(22f), GUILayout.Width(90f)))
                {
                    _target = null;
                }
            }

            string path = _target != null ? AssetDatabase.GetAssetPath(_target) : null;
            if (_target == null)
            {
                EditorGUILayout.HelpBox("请拖入一个文件夹（或预制体），也可以先在 Project 窗口中选中后点击上方按钮。",
                    MessageType.Warning);
            }
            else if (!AssetDatabase.IsValidFolder(path) && !path.EndsWith(".prefab"))
            {
                EditorGUILayout.HelpBox("目标必须是文件夹或 .prefab 文件。", MessageType.Error);
            }
            else
            {
                EditorGUILayout.LabelField("解析路径", path, EditorStyles.miniLabel);
            }
        }

        private void DrawOptions()
        {
            EditorGUILayout.LabelField("执行选项", EditorStyles.boldLabel);
            _dryRun = EditorGUILayout.ToggleLeft("预览模式（只扫描统计，不修改任何文件）", _dryRun);
            _verbose = EditorGUILayout.ToggleLeft("输出详细日志（包含无变化的预制体）", _verbose);
            _onlyChanged = EditorGUILayout.ToggleLeft("结果列表仅显示有改动 / 有错误的条目", _onlyChanged);
        }

        private void DrawActionButtons()
        {
            bool valid = IsTargetValid();

            using (new EditorGUI.DisabledScope(!valid))
            {
                using (new EditorGUILayout.HorizontalScope())
                {
                    Color old = GUI.backgroundColor;
                    GUI.backgroundColor = _dryRun ? new Color(0.75f, 0.9f, 1f) : new Color(1f, 0.85f, 0.75f);

                    string label = _dryRun ? "预览扫描" : "开始清理";
                    if (GUILayout.Button(label, GUILayout.Height(30f)))
                    {
                        List<string> paths = new List<string> { AssetDatabase.GetAssetPath(_target) };
                        MissingScriptCleaner.RunAndReport(paths, _dryRun, _verbose, false);
                    }

                    GUI.backgroundColor = old;

                    if (GUILayout.Button(_dryRun ? "预览并弹窗确认" : "弹窗确认后清理",
                            GUILayout.Height(30f), GUILayout.Width(150f)))
                    {
                        List<string> paths = new List<string> { AssetDatabase.GetAssetPath(_target) };
                        MissingScriptCleaner.RunWithConfirm(paths, _dryRun, true);
                    }
                }
            }
        }

        private void DrawReport()
        {
            CleanReport report = MissingScriptCleaner.LastReport;
            if (report == null)
            {
                return;
            }

            EditorGUILayout.Space();
            EditorGUILayout.LabelField("执行结果", _titleStyle);

            using (new EditorGUILayout.VerticalScope(EditorStyles.helpBox))
            {
                EditorGUILayout.LabelField(string.Format(
                    "扫描 {0} 个 · 发现 Missing Script {1} 个 · 受影响 {2} 个 · 跳过 {3} 个 · 失败 {4} 个 · 耗时 {5:F0}ms",
                    report.Scanned, report.RemovedTotal, report.Modified, report.Skipped, report.Failed, report.ElapsedMs));

                if (report.DryRun)
                {
                    EditorGUILayout.LabelField("（预览模式：以上为预估结果，未修改任何文件）", EditorStyles.miniLabel);
                }
                if (report.Canceled)
                {
                    EditorGUILayout.LabelField("（任务被手动取消，未处理项保持原样）", EditorStyles.miniLabel);
                }
            }

            using (new EditorGUILayout.HorizontalScope())
            {
                if (GUILayout.Button("复制报告到剪贴板", GUILayout.Height(22f)))
                {
                    EditorGUIUtility.systemCopyBuffer = BuildReportText(report);
                    Debug.Log("[MissingScript清理] 报告已复制到剪贴板。");
                }
                if (GUILayout.Button("清空结果", GUILayout.Height(22f), GUILayout.Width(90f)))
                {
                    MissingScriptCleaner.LastReport = null;
                }
            }

            EditorGUILayout.Space();
            _scroll = EditorGUILayout.BeginScrollView(_scroll, GUILayout.MinHeight(180f));

            int shown = 0;
            foreach (CleanResult item in report.Details)
            {
                if (_onlyChanged && !item.HasChange)
                {
                    continue;
                }
                shown++;
                DrawResultRow(item);
            }

            if (shown == 0)
            {
                EditorGUILayout.LabelField(_onlyChanged ? "没有需要关注的条目，全部干净。" : "无明细数据。",
                    EditorStyles.miniLabel);
            }

            EditorGUILayout.EndScrollView();
        }

        private void DrawResultRow(CleanResult item)
        {
            using (new EditorGUILayout.HorizontalScope(EditorStyles.helpBox))
            {
                string tag;
                if (!string.IsNullOrEmpty(item.Error))
                {
                    tag = "<color=#c0392b>[失败]</color>";
                }
                else if (item.IsSkipped)
                {
                    tag = "<color=#7f8c8d>[跳过]</color>";
                }
                else
                {
                    tag = "<color=#d35400>[清理]</color>";
                }

                string info = item.IsSkipped
                    ? string.Format("{0} {1}  <color=#7f8c8d>({2})</color>", tag, item.AssetPath, item.SkipReason)
                    : string.Format("{0} 移除 {1} 个  {2}", tag, item.RemovedCount, item.AssetPath);

                EditorGUILayout.LabelField(info, _itemStyle);

                if (GUILayout.Button("定位", GUILayout.Width(52f)))
                {
                    GameObject asset = AssetDatabase.LoadAssetAtPath<GameObject>(item.AssetPath);
                    if (asset != null)
                    {
                        // 先改选中，再 Ping，否则选中动作会清掉高亮
                        Selection.activeObject = asset;
                        EditorGUIUtility.PingObject(asset);
                    }
                    else
                    {
                        Debug.LogWarning(string.Format("[MissingScript清理] 无法加载资源（可能已被移动或删除）：{0}",
                            item.AssetPath));
                    }
                }
            }
        }

        #endregion

        #region 辅助方法

        private bool IsTargetValid()
        {
            if (_target == null)
            {
                return false;
            }
            string path = AssetDatabase.GetAssetPath(_target);
            return AssetDatabase.IsValidFolder(path) || path.EndsWith(".prefab");
        }

        private void ValidateTarget()
        {
            if (_target != null)
            {
                string path = AssetDatabase.GetAssetPath(_target);
                if (!AssetDatabase.IsValidFolder(path) && !path.EndsWith(".prefab"))
                {
                    Debug.LogWarning("[MissingScript清理] 目标无效：请选择文件夹或 .prefab 文件。");
                    _target = null;
                }
            }
        }

        private void PickFromSelection()
        {
            UnityEngine.Object active = Selection.activeObject;
            if (active == null)
            {
                return;
            }
            string path = AssetDatabase.GetAssetPath(active);
            if (AssetDatabase.IsValidFolder(path) || path.EndsWith(".prefab"))
            {
                _target = active;
                Repaint();
            }
        }

        private static string BuildReportText(CleanReport report)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("===== 预制体 Missing Script 清理报告 =====");
            sb.AppendLine(report.Describe());
            sb.AppendLine();
            sb.AppendLine("----- 明细 -----");
            foreach (CleanResult item in report.Details)
            {
                if (item.IsSkipped)
                {
                    sb.AppendLine(string.Format("[跳过] {0} （{1}）", item.AssetPath, item.SkipReason));
                }
                else if (!string.IsNullOrEmpty(item.Error))
                {
                    sb.AppendLine(string.Format("[失败] {0} ：{1}", item.AssetPath, item.Error));
                }
                else if (item.RemovedCount > 0)
                {
                    sb.AppendLine(string.Format("[清理] 移除 {0} 个 · {1}", item.RemovedCount, item.AssetPath));
                }
            }
            return sb.ToString();
        }

        #endregion
    }
}

using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 批量把 `Assets/_UIAssets/Monsters/**` 下的**全部**怪物转成战斗预制体。
    ///
    /// 源 prefab 是"美术包"形态：分部件 2D 骨骼式结构（Body/Head/腿/尾/Shadow + Anchor），
    /// 自带 Animator 与 SortingGroup，但**带着 CapsuleCollider2D**（v1.0 用来做 OnTriggerEnter）。
    /// 本工具把它转成"战斗形态"：
    ///   ① 去掉全部物理组件（需求 8：去物理化）
    ///   ② 挂 BaseEnemy
    ///   ③ 加 HpBar（Bg + Fill），位置与宽度**按实测渲染包围盒自适应**
    ///      —— 不同怪物体型差很多（猴子 vs 巨魔），写死坐标必然对不齐
    ///
    /// 产物：`Assets/Prefabs/Enemy/Enemy_<怪名>.prefab`（名字与打包规则见 MonsterCatalog）
    ///
    /// 动画不用管：源 prefab 的 Animator 已经引用了自己的 Controller
    ///（`_Common/Animations/<怪名>/Controller.controller`），克隆时会一并带过来。
    /// 所以配置表的 `animController` 可以留空，BaseEnemy 会沿用 prefab 自带的。
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建）▸ 导入全部怪物（生成战斗预制体）
    /// </summary>
    public static class MonsterPrefabBuilder
    {
        public const string OutputDir = "Assets/Prefabs/Enemy";

        /// <summary>血条世界宽度 = 怪物世界宽度 × 此比例。
        /// 0.6 太宽（大怪的血条几乎横跨整个屏幕），0.5 是视觉上比较搭的值</summary>
        private const float BarWidthRatio = 0.5f;
        private const float BarMinWorldWidth = 0.35f;
        private const float BarMaxWorldWidth = 2.2f;
        /// <summary>血条世界高度（固定值，不随怪物宽度放大）。
        /// 之前让高度跟随宽度（宽的 1/5），大怪的血条高得像一块板，视觉上很突兀；
        /// 固定成一个薄条的厚度，所有怪物看起来才一致</summary>
        private const float BarWorldHeight = 0.11f;
        /// <summary>血条与头顶的间距 = 怪物世界高度 × 此比例（随体型缩放）</summary>
        private const float BarTopMarginRatio = 0.14f;
        private static readonly Color HpFillColor = new Color(0.35f, 0.90f, 0.35f, 1f);

        /// <summary>
        /// 菜单入口：批量导入全部怪物（生成战斗预制体）。直接执行、不弹窗（自动化友好）；
        /// 需要执行前二次确认的走「带确认」菜单。
        /// </summary>
        [MenuItem("Tools/塔防/高级（单步重建）/导入全部怪物（生成战斗预制体）", false, 306)]
        public static void BuildAllFromMenu()
        {
            BuildAllInternal_NoDialog();
        }

        /// <summary>
        /// 「带确认」入口，等价于旧菜单 + 执行前确认弹窗。**仅用于人工交互**，
        /// 自动化不得调用（会阻塞编辑器）。
        /// </summary>
        [MenuItem("Tools/塔防/高级（单步重建）/强制执行：导入全部怪物（带确认）", false, 316)]
        public static void BuildAllFromMenuConfirm()
        {
            if (!EditorUtility.DisplayDialog("导入全部怪物",
                    string.Format("将处理 {0} 个怪物，为每个生成：\n" +
                                  "  Assets/Prefabs/Enemy/Enemy_<怪名>.prefab\n\n" +
                                  "每个会：去掉物理组件、挂 BaseEnemy、按体型自适应添加血条。\n\n" +
                                  "数量较多，可能需要十几秒到一分钟。是否继续？",
                        MonsterCatalog.Count),
                    "开始导入", "取消"))
            {
                return;
            }
            BuildAllInternal_NoDialog();
        }

        private static void BuildAllInternal_NoDialog()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            BuildAllInternal(report);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log(report.Errors > 0
                ? string.Format("[怪物导入] 有错误（{0} 项 · 警告 {1} 项）：\n{2}",
                    report.Errors, report.Warnings, report.Text)
                : string.Format("[怪物导入] 完成（警告 {0} 项）：\n{1}",
                    report.Warnings, report.Text));
        }

        /// <summary>供一键向导调用（不弹窗）</summary>
        public static void BuildAllInternal(EditorUtil.Report report)
        {
            report.Head(string.Format("导入全部怪物 → {0}/（共 {1} 个）",
                OutputDir, MonsterCatalog.Count));

            // 血条贴图是前置依赖，缺了就没必要逐个跑
            Sprite barBg = AssetDatabase.LoadAssetAtPath<Sprite>(
                EditorUtil.GeneratedArtDir + "/HP_Bar_Bg.png");
            Sprite barFill = AssetDatabase.LoadAssetAtPath<Sprite>(
                EditorUtil.GeneratedArtDir + "/HP_Bar_Fill.png");
            if (barBg == null || barFill == null)
            {
                report.Error("找不到血条贴图（HP_Bar_Bg / HP_Bar_Fill）。" +
                             "请先执行「高级（单步重建）▸ 生成占位美术」");
                return;
            }

            EditorUtil.EnsureFolder(OutputDir);

            int built = 0;
            int noPhysics = 0;
            int failed = 0;
            int headOk = 0;
            int missingScripts = 0;
            float barMinY = float.MaxValue;
            float barMaxY = float.MinValue;
            float minW = float.MaxValue;
            float maxW = 0f;

            for (int i = 0; i < MonsterCatalog.Count; i++)
            {
                string src = MonsterCatalog.SourcePaths[i];
                string dst = MonsterCatalog.PrefabPath(i);
                GameObject source = AssetDatabase.LoadAssetAtPath<GameObject>(src);
                if (source == null)
                {
                    failed++;
                    report.Error(string.Format("源预制体不存在：{0}", src));
                    continue;
                }

                Bounds bounds;
                GameObject clone = Object.Instantiate(source);
                clone.name = System.IO.Path.GetFileNameWithoutExtension(dst);
                // ★ 必须紧跟克隆：美术源包的 SortingGroup 序不统一，不归一化就会整组错位
                NormalizeSortingGroup(clone);
                try
                {
                    int removed = PhysicsComponentCleaner.StripPhysics(clone);
                    if (removed == 0)
                    {
                        noPhysics++;
                    }

                    // 清掉"缺失脚本"：美术包原本带一个接收动画事件的脚本，
                    // 但它从来没进过这个项目 → 预制体上留着一条 Missing 引用，
                    // 每次实例化都会刷 "The referenced script (Unknown) on this Behaviour is missing!"
                    //（这正是我们补 MonsterAnimEventReceiver 的原因）
                    int missing = UnityEditor.GameObjectUtility.RemoveMonoBehavioursWithMissingScript(clone);
                    if (missing > 0)
                    {
                        missingScripts += missing;
                    }

                    if (clone.GetComponent<BaseEnemy>() == null)
                    {
                        clone.AddComponent<BaseEnemy>();
                    }

                    RestoreMissingParticleMaterials(clone);

                    float barWorldY = AttachHpBar(clone, barBg, barFill);
                    if (barWorldY > -1000f)
                    {
                        if (barWorldY < barMinY) barMinY = barWorldY;
                        if (barWorldY > barMaxY) barMaxY = barWorldY;
                    }
                    if (AttachAnimEventReceiver(clone, MonsterCatalog.AtlasPaths[i]))
                    {
                        headOk++;
                    }
                    bool hasDirections = EnemyDirectionPrefabBuilder.ApplyIfConfigured(clone, MonsterCatalog.AtlasPaths[i]);
                    MeasureBodyBounds(clone, out bounds);

                    // Preserve the installed directional prefab's GUID when regenerating from source.
                    if (!hasDirections) AssetDatabase.DeleteAsset(dst);
                    GameObject saved = PrefabUtility.SaveAsPrefabAsset(clone, dst);
                    if (saved == null)
                    {
                        failed++;
                        report.Error("保存失败：" + dst);
                        continue;
                    }
                    built++;

                    // 记录世界宽度，用于最后给出"要不要调 scale"的量化建议
                    Vector3 sc = clone.transform.localScale;
                    float w = bounds.size.x * Mathf.Abs(sc.x);
                    if (w > 0.0001f)
                    {
                        minW = Mathf.Min(minW, w);
                        maxW = Mathf.Max(maxW, w);
                    }
                }
                finally
                {
                    // 与 Instantiate 严格配对，避免预览场景泄漏对象
                    Object.DestroyImmediate(clone);
                }
            }

            report.Ok(string.Format("成功生成 {0} 个战斗预制体", built));
            if (failed > 0)
            {
                report.Error(string.Format("{0} 个失败（见上方明细）", failed));
            }
            if (noPhysics > 0)
            {
                report.Warn(string.Format("{0} 个源预制体上没有物理组件（若美术包更新后加回了 Collider，这里会提示）",
                    noPhysics));
            }
            if (built > 0 && maxW > 0f)
            {
            report.Ok(string.Format("实测显示宽度范围：{0:F2} ~ {1:F2} 世界单位（格子 1.0）",
                minW, maxW));
            if (barMaxY > float.MinValue)
            {
                report.Ok(string.Format(
                    "血条世界高度范围：{0:F2} ~ {1:F2}（应与各怪物的体型上限接近；\n" +
                    "  若某个怪的血条明显偏高/偏低，把怪名发我，我针对它的预制体结构单独看）",
                    barMinY, barMaxY));
            }
                report.Ok("体型差异来自美术（每个 prefab 自带缩放），所以相对大小不用手动调；" +
                          "若整体偏大/偏小，改 EnemyData.xlsx 的 scale 列");
            }
            report.Ok(string.Format(
                "{0}/{1} 个怪物的动画事件接收者已挂好并预填了头部贴图" +
                "（美术包的 Attack/Death 动画靠它切换 正常/愤怒/死亡 头，缺了会刷 " +
                "\"has no receiver\" 警告）", headOk, built));
            if (missingScripts > 0)
            {
                report.Ok(string.Format(
                    "已清除 {0} 个缺失脚本引用（美术包自带的动画事件脚本没进项目，\n" +
                    "  留着会每次实例化都刷 \"The referenced script (Unknown) is missing!\"）",
                    missingScripts));
            }
            report.Ok("下一步：执行「8a. 打 AssetBundle 标记」，让这些怪物按家族进入 enemy_<家族> 资源包");
        }

        /// <summary>
        /// 把根节点的 SortingGroup 统一成「Main 层 + BoardSorting.Enemy」。
        ///
        /// 【为什么必须做】战斗预制体是直接 Instantiate 美术源包得来的，源包的组序并不统一：
        ///   实测 119 个里 88 个是 200，其余 31 个是 0/1/2/3/4、100–104、201–204。
        ///   不归一化的话：0–4 的整组会掉到格子(0)/路径箭头(10)/射程圈(100)之下；
        ///   100–104 的永远被 200 组盖住；201–204 的永远盖住所有怪（Y 排序失效）。
        /// </summary>
        private static void NormalizeSortingGroup(GameObject root)
        {
            SortingGroup group = root.GetComponent<SortingGroup>();
            if (group == null)
            {
                group = root.AddComponent<SortingGroup>();
            }
            group.sortingLayerName = BoardSorting.LayerMain;
            group.sortingOrder = BoardSorting.Enemy;
        }

        // Some source art prefabs refer to a particle material absent from the pack.
        // Keep the installed battle-prefab repair when regenerating from those sources.
        private static void RestoreMissingParticleMaterials(GameObject root)
        {
            foreach (var renderer in root.GetComponentsInChildren<ParticleSystemRenderer>(true))
            {
                Material[] materials = renderer.sharedMaterials;
                bool changed = false;
                for (int i = 0; i < materials.Length; i++)
                {
                    if (materials[i] != null) continue;
                    Material fallback = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/EnemyParticles.mat");
                    if (fallback == null) throw new System.InvalidOperationException("Missing battle particle material: Assets/Materials/EnemyParticles.mat");
                    materials[i] = fallback;
                    changed = true;
                }
                if (changed) renderer.sharedMaterials = materials;
            }
        }

        // ------------------------------------------------------------------
        // 血条
        // ------------------------------------------------------------------

        /// <summary>
        /// 加血条。结构固定为 HpBar → Bg / Fill（BaseEnemy 按名字查找）。
        ///
        /// 位置与宽度按**实测渲染包围盒**推算，并用 InverseTransformPoint
        /// 把世界坐标换算回根节点本地（正确处理 66 个怪预制体根节点自带的位移、
        /// 以及全部 119 个的非均匀缩放）。
        /// 返回值：血条的世界 Y（用于报告里核对是否离谱）；失败返回 float.MinValue。
        /// </summary>
        private static float AttachHpBar(GameObject root, Sprite barBg, Sprite barFill)
        {
            Transform old = root.transform.Find("HpBar");
            if (old != null)
            {
                Object.DestroyImmediate(old.gameObject);
            }

            // 用"身体包围盒"而不是"全部渲染器包围盒"：
            // 部分美术预制体带未激活部件或远处的装饰节点，会把包围盒撑大，
            // 血条就被顶到离怪物很远的地方（这是实际反馈到的问题）
            Bounds b;
            bool hasBounds = MeasureBodyBounds(root, out b);
            Vector3 sc = root.transform.localScale;
            float sx = Mathf.Max(0.0001f, Mathf.Abs(sc.x));
            float sy = Mathf.Max(0.0001f, Mathf.Abs(sc.y));
            // 注意：sx/sy 只在没有包围盒时做兜底用；正常路径走 InverseTransformPoint

            // 【统一用世界尺寸思考，再换算回根节点本地】
            // 血条世界宽 = 怪物世界宽 × 比例；顶部 = 包围盒顶 + 怪物高 × 比例。
            //
            // 【换算必须用 InverseTransformPoint，不能"除以根缩放"】
            // 实测 119 个怪物预制体里：
            //   · 66 个的根节点 **localPosition 不为 0**（美术摆放时留了偏移）
            //   · 119 个全是 **非均匀缩放**（x/y 不相等）
            // 直接 `bounds.max.y / rootScaleY` 会**漏掉根节点自身的位移**，
            // 于是这 66 个怪的血条整体偏移一大截 —— 这正是
            // "大多数怪正常、少数怪（尤其某几个家族）偏得特别厉害"的原因。
            // InverseTransformPoint 会一次性正确处理 位移 + 缩放 + 旋转。
            Transform rt = root.transform;
            float worldW = hasBounds ? b.size.x : 1f;
            float worldH = hasBounds ? b.size.y : 1f;
            float barWorldW = Mathf.Clamp(worldW * BarWidthRatio, BarMinWorldWidth, BarMaxWorldWidth);
            float barWorldTop = (hasBounds ? b.max.y : 1f) + worldH * BarTopMarginRatio;

            // 位置：把"血条顶部"这个世界点换算到根节点本地空间
            // （必须用 InverseTransformPoint，理由见上）
            float topLocal = rt.InverseTransformPoint(
                new Vector3(b.center.x, barWorldTop, b.center.z)).y;

            // 尺寸：直接用根缩放把"期望的世界尺寸"换算成本地缩放
            //   渲染世界宽 = localScale.x × 根sx × 精灵原生宽(1.0)
            //   渲染世界高 = localScale.y × 根sy × 精灵原生高(0.2)
            // 宽度随怪物体型按比例；高度固定成一个薄条，所有怪物观感一致
            // （之前高度跟随宽度，大怪的血条高得像一块板，视觉上很突兀）
            float barLocalW = barWorldW / sx;
            float barLocalH = BarWorldHeight / (sy * 0.2f);

            GameObject bar = new GameObject("HpBar");
            bar.transform.SetParent(root.transform, false);
            bar.transform.localPosition = new Vector3(0f, topLocal, 0f);
            // 宽/高分开定标：宽度随怪物体型，高度固定为薄条
            // （Bg/Fill 保持在 1，这样 BaseEnemy 里的 _hpBarWidth 就是精灵原生宽度 1.0，
            //   左对齐计算最简单；血条的镜像补偿也只作用于 X）
            bar.transform.localScale = new Vector3(barLocalW, barLocalH, 1f);

            GameObject bgGo = new GameObject("Bg");
            bgGo.transform.SetParent(bar.transform, false);
            SpriteRenderer bgSr = bgGo.AddComponent<SpriteRenderer>();
            bgSr.sprite = barBg;
            // ★ 组内相对序号（不是全局 500）：血条挂在带 SortingGroup 的根下面，
            //   子渲染器的 order 只在组内比大小，写多少都越不出组。取 500/501 是因为
            //   必须压过美术包的所有部件（实测最大 99：BugQueen/MossQueen；蝎子 40~70）。
            bgSr.sortingLayerName = BoardSorting.LayerMain;
            bgSr.sortingOrder = BoardSorting.EnemyHpBarBack;
            bgSr.color = new Color(1f, 1f, 1f, 0.9f);

            GameObject fillGo = new GameObject("Fill");
            fillGo.transform.SetParent(bar.transform, false);
            SpriteRenderer fillSr = fillGo.AddComponent<SpriteRenderer>();
            fillSr.sprite = barFill;
            fillSr.sortingLayerName = BoardSorting.LayerMain;
            fillSr.sortingOrder = BoardSorting.EnemyHpBarFill;
            fillSr.color = HpFillColor;

            // 返回血条的世界 Y，供调用方统计（报告里用来核对有没有离谱的偏移）
            return bar.transform.position.y;
        }

        /// <summary>
        /// 测"给血条定位用"的身体包围盒。
        ///
        /// 【为什么不能直接用全部 Renderer】实测发现部分怪物的血条位置明显偏高/偏斜，
        /// 原因是这些预制体里带**未激活**的部件（例如未启用的武器/特效），
        /// 或者位置很远的装饰节点；它们会把包围盒撑大。
        /// 所以只统计：**激活中**（includeInactive=false）+ **renderer.enabled** +
        /// 名字不像装饰（shadow/ground/fx/effect/glow/hit）的渲染器。
        /// </summary>
        private static bool MeasureBodyBounds(GameObject go, out Bounds bounds)
        {
            bounds = new Bounds(Vector3.zero, Vector3.zero);
            Renderer[] rs = go.GetComponentsInChildren<Renderer>(false);
            bool has = false;
            for (int i = 0; i < rs.Length; i++)
            {
                Renderer r = rs[i];
                if (r == null || !r.enabled)
                {
                    continue;
                }
                if (IsDecorativeRenderer(r.gameObject.name))
                {
                    continue;
                }
                if (!has)
                {
                    bounds = r.bounds;
                    has = true;
                }
                else
                {
                    bounds.Encapsulate(r.bounds);
                }
            }
            return has;
        }

        /// <summary>名字像装饰/特效/阴影的渲染器（不参与血条定位）</summary>
        private static bool IsDecorativeRenderer(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            string n = name.ToLowerInvariant();
            return n.Contains("shadow") || n.Contains("ground") || n.Contains("fx")
                || n.Contains("effect") || n.Contains("glow") || n.Contains("hit");
        }


        // ------------------------------------------------------------------
        // 动画事件接收者
        // ------------------------------------------------------------------

        /// <summary>
        /// 挂上动画事件接收者，并预填三个头部贴图。
        ///
        /// 【为什么必须挂】美术包的 Attack/Death 动画里内置了 `SetHead(int)` / `Event(string)`
        /// 的 AnimationEvent，但包里没有提供接收脚本，运行时 Console 会刷
        /// "AnimationEvent 'SetHead' … has no receiver!"。
        ///
        /// 【必须挂在 Animator 所在的 GameObject】Unity 把 AnimationEvent 发给
        /// 播放动画的那个 Animator 所属的 GameObject，挂错了收不到。
        /// </summary>
        private static bool AttachAnimEventReceiver(GameObject root, string atlasPath)
        {
            Animator anim = root.GetComponentInChildren<Animator>(true);
            GameObject host = anim != null ? anim.gameObject : root;

            MonsterAnimEventReceiver recv = host.GetComponent<MonsterAnimEventReceiver>();
            if (recv == null)
            {
                recv = host.AddComponent<MonsterAnimEventReceiver>();
            }

            recv.HeadRenderer = FindHeadRenderer(root);
            recv.HeadSprites = ResolveHeadSprites(atlasPath);
            return recv.HeadSprites != null && recv.HeadRenderer != null;
        }

        /// <summary>找名字含 "Head" 的渲染器（各家族节点名可能有差异，所以按名字模糊匹配）</summary>
        private static SpriteRenderer FindHeadRenderer(GameObject root)
        {
            SpriteRenderer[] rs = root.GetComponentsInChildren<SpriteRenderer>(true);
            for (int i = 0; i < rs.Length; i++)
            {
                if (rs[i] != null &&
                    rs[i].name.IndexOf("head", System.StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return rs[i];
                }
            }
            return null;
        }

        /// <summary>
        /// 从图集里解析三个头部精灵。
        ///
        /// 【为什么必须在编辑期做】运行期拿到一个 Sprite 之后无法反查同一图集里的兄弟精灵
        ///（Sprite 不暴露这个信息），所以这里用 AssetDatabase 枚举图集全部子资产，
        /// 按名字取出来预填到组件上。
        ///
        /// 命名回退链覆盖实测到的几种美术包差异（118/120 图集有 Head 系命名）：
        ///   正常  HeadNormal → Head      → HeadAngry → HeadAttack
        ///   愤怒  HeadAngry  → HeadAttack→ HeadNormal→ Head
        ///   死亡  HeadDead   → HeadNormal→ Head
        /// </summary>
        private static Sprite[] ResolveHeadSprites(string atlasPath)
        {
            if (string.IsNullOrEmpty(atlasPath))
            {
                return null;
            }
            Object[] all = AssetDatabase.LoadAllAssetsAtPath(atlasPath);
            if (all == null || all.Length == 0)
            {
                return null;
            }

            System.Collections.Generic.Dictionary<string, Sprite> byName =
                new System.Collections.Generic.Dictionary<string, Sprite>(all.Length);
            for (int i = 0; i < all.Length; i++)
            {
                Sprite s = all[i] as Sprite;
                if (s != null && !byName.ContainsKey(s.name))
                {
                    byName[s.name] = s;
                }
            }
            if (byName.Count == 0)
            {
                return null;
            }

            string[][] chains =
            {
                new[] { "HeadNormal", "Head", "HeadAngry", "HeadAttack" },
                new[] { "HeadAngry", "HeadAttack", "HeadNormal", "Head" },
                new[] { "HeadDead", "HeadNormal", "Head" },
            };

            Sprite[] result = new Sprite[chains.Length];
            int found = 0;
            for (int i = 0; i < chains.Length; i++)
            {
                for (int k = 0; k < chains[i].Length; k++)
                {
                    Sprite s;
                    if (byName.TryGetValue(chains[i][k], out s))
                    {
                        result[i] = s;
                        found++;
                        break;
                    }
                }
            }
            return found > 0 ? result : null;
        }
    }
}

using System.Collections.Generic;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 移除预制体上的物理组件（P0-4 / 需求 8）。
    ///
    /// 【为什么要删】
    ///   v1.0 的命中判定靠 `OnTriggerEnter`，因此塔和怪身上都挂着 Collider / Rigidbody2D。
    ///   物理系统的宽相与窄相在低端机上是主要 CPU 开销，而且触发器会把
    ///   "谁打中了谁"变成不可控的时序问题。
    ///   v2.1 改成 EnemyGrid 空间哈希 + 距离判定 + 集中式 tick，物理系统完全不再需要。
    ///
    ///   验收标准（DoD）：Profiler 里 Physics / Physics2D 分区恒为 0。
    ///
    /// 菜单：
    ///   Tools ▸ 塔防 ▸ 高级（单步重建）▸ 清理选中预制体的物理组件
    ///   Tools ▸ 塔防 ▸ 高级（单步重建）▸ 清理全部战斗预制体的物理组件
    /// </summary>
    public static class PhysicsComponentCleaner
    {
        /// <summary>战斗预制体所在目录（批量清理用）</summary>
        private static readonly string[] BattlePrefabFolders =
        {
            "Assets/Prefabs/Tower",
            "Assets/Prefabs/Bullet",
            "Assets/Prefabs/Enemy",
        };

        [MenuItem("Tools/塔防/高级（单步重建）/清理选中预制体的物理组件", false, 303)]
        public static void CleanSelected()
        {
            Object[] selection = Selection.objects;
            if (selection == null || selection.Length == 0)
            {
                Debug.LogWarning("[M0] 清理物理组件：请先在 Project 窗口选中至少一个预制体。");
                return;
            }

            int totalRemoved = 0;
            int fileCount = 0;
            List<string> touched = new List<string>();

            for (int i = 0; i < selection.Length; i++)
            {
                string path = AssetDatabase.GetAssetPath(selection[i]);
                if (string.IsNullOrEmpty(path) || !path.EndsWith(".prefab"))
                {
                    continue;
                }
                int n = StripPhysicsFromAsset(path);
                if (n > 0)
                {
                    totalRemoved += n;
                    fileCount++;
                    touched.Add(string.Format("  · {0}：移除 {1} 个", path, n));
                }
            }

            AssetDatabase.SaveAssets();
            Debug.Log(string.Format("[M0] 物理组件清理完成：{0} 个预制体共移除 {1} 个组件\n{2}",
                fileCount, totalRemoved, string.Join("\n", touched.ToArray())));
        }

        [MenuItem("Tools/塔防/高级（单步重建）/清理全部战斗预制体的物理组件", false, 304)]
        public static void CleanAllBattlePrefabs()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            CleanAllInternal(report);
            AssetDatabase.SaveAssets();
            Debug.Log(report.Errors > 0
                ? "[M0] 全量物理组件清理有错误：\n" + report.Text
                : "[M0] 全量物理组件清理完成：\n" + report.Text);
        }

        /// <summary>供一键向导调用（不弹窗）</summary>
        public static void CleanAllInternal(EditorUtil.Report report)
        {
            report.Head("清理战斗预制体的物理组件");
            int files = 0;
            int total = 0;

            for (int d = 0; d < BattlePrefabFolders.Length; d++)
            {
                string folder = BattlePrefabFolders[d];
                if (!AssetDatabase.IsValidFolder(folder))
                {
                    continue;
                }
                string[] guids = AssetDatabase.FindAssets("t:Prefab", new[] { folder });
                for (int i = 0; i < guids.Length; i++)
                {
                    string path = AssetDatabase.GUIDToAssetPath(guids[i]);
                    // 跳过备份目录里的 UGUI 源文件
                    if (path.Contains("/_UI_Source/"))
                    {
                        continue;
                    }
                    int n = StripPhysicsFromAsset(path);
                    if (n > 0)
                    {
                        files++;
                        total += n;
                        report.Ok(string.Format("{0}：移除 {1} 个", path, n));
                    }
                }
            }

            if (total == 0)
            {
                report.Ok("没有发现需要清理的物理组件（说明已是干净状态）");
            }
            else
            {
                report.Ok(string.Format("共 {0} 个文件、{1} 个组件", files, total));
            }
        }

        /// <summary>从某个预制体资产上移除物理组件，返回移除数量</summary>
        public static int StripPhysicsFromAsset(string assetPath)
        {
            GameObject contents = PrefabUtility.LoadPrefabContents(assetPath);
            if (contents == null)
            {
                return 0;
            }
            try
            {
                int n = StripPhysics(contents);
                if (n > 0)
                {
                    PrefabUtility.SaveAsPrefabAsset(contents, assetPath);
                }
                return n;
            }
            finally
            {
                // 与 LoadPrefabContents 严格配对，否则预览场景会泄漏对象
                PrefabUtility.UnloadPrefabContents(contents);
            }
        }

        /// <summary>
        /// 就地移除层级下所有物理组件（含未激活子物体），返回移除数量。
        /// 不涉及 UnityEditor API，可被 Editor 脚本直接调用。
        /// </summary>
        public static int StripPhysics(GameObject root)
        {
            if (root == null)
            {
                return 0;
            }
            int removed = 0;
            // GetComponentsInChildren 不保证顺序，先把待删清单收集完再删，避免边遍历边改
            Component[] comps = root.GetComponentsInChildren<Component>(true);
            List<Component> toRemove = new List<Component>(8);
            for (int i = 0; i < comps.Length; i++)
            {
                Component c = comps[i];
                if (c == null)
                {
                    continue;
                }
                if (IsPhysicsComponent(c))
                {
                    toRemove.Add(c);
                }
            }
            for (int i = 0; i < toRemove.Count; i++)
            {
                Object.DestroyImmediate(toRemove[i]);
                removed++;
            }
            return removed;
        }

        private static bool IsPhysicsComponent(Component c)
        {
            return c is Collider
                || c is Collider2D
                || c is Rigidbody
                || c is Rigidbody2D
                || c is Joint
                || c is Joint2D
                || c is CharacterController;
        }
    }
}

using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 程序化生成棋盘与战斗的占位美术（P0-4）。
    ///
    /// 为什么要程序生成而不是找美术要图：
    ///   1. 这些是"功能验证用"的图（格子、箭头、血条、子弹点），美术风格定了还要换
    ///   2. 让程序生成可以随格子尺寸 / 配色随时重跑，不占用美术排期
    ///   3. 关掉"美术没到位"这个最常见的阻塞项 —— 符合需求 5「功能缺失不应阻塞实现」
    ///
    /// 全部按 PPU=100 生成，与现有美术（塔/怪物）保持一致。
    /// 输出目录：Assets/Art/Generated/　逻辑名见 ResTable（Cell_Ground / Path_Arrow / ...）
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建）▸ 生成占位美术
    /// </summary>
    public static class PlaceholderArtGenerator
    {
        private const string Dir = EditorUtil.GeneratedArtDir;

        // 配色：深色科幻令牌（GameDesign §6）—— 战场 #10141D / 格线 #1C2532 / 青 #35E0FF / 红 #FF4D5E
        private static readonly Color GroundFill = new Color(0.102f, 0.133f, 0.188f, 1f);
        private static readonly Color GroundBorder = new Color(1f, 1f, 1f, 0.06f);
        private static readonly Color BlockedFill = new Color(0.051f, 0.067f, 0.098f, 1f);
        private static readonly Color BlockedBorder = new Color(0f, 0f, 0f, 0.45f);
        private static readonly Color SpawnFill = new Color(0.063f, 0.188f, 0.227f, 1f);
        private static readonly Color SpawnBorder = new Color(0.208f, 0.878f, 1f, 0.85f);
        private static readonly Color EndFill = new Color(0.227f, 0.086f, 0.125f, 1f);
        private static readonly Color EndBorder = new Color(1f, 0.302f, 0.369f, 0.85f);
        /// <summary>
        /// 路径箭头贴图色：**纯白**，颜色一律交给运行时 `SpriteRenderer.color` 决定。
        /// 【为什么不能画成青色】贴图色与 renderer.color 是**相乘**关系：
        ///   白图 × 任意颜色 = 该颜色；青图 × 红色 = 暗红偏青（红分量被青图的 R=0.21 压掉大半）。
        ///   真实路径（白 0.75 alpha）与预览路径（红）共用这张图，只有白图才能让两边都还原成预期颜色。
        /// 与 `HP_Bar_Fill.png` 同一条约定（见下方血条注释）。
        /// </summary>
        private static readonly Color PathArrowColor = Color.white;
        private static readonly Color RangeRingColor = new Color(0.208f, 0.878f, 1f, 0.80f);

        [MenuItem("Tools/塔防/高级（单步重建）/生成占位美术", false, 300)]
        public static void Generate()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            GenerateInternal(report);
            AssetDatabase.Refresh();

            Debug.Log("[M0] 占位美术生成完成 → " + Dir + "：\n" + report.Text);
        }

        /// <summary>
        /// 无弹窗入口（供 Unity MCP / 批处理调用）。
        /// 【为什么单开一个】带 EditorUtility.DisplayDialog 的菜单会**阻塞编辑器**，
        /// 自动化调用会直接卡死；自动化一律走本入口，只往 Console 打日志。
        /// </summary>
        [MenuItem("Tools/塔防/自动化（无弹窗）/生成占位美术", false, 901)]
        public static void GenerateNoDialog()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            GenerateInternal(report);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log("[M0] 占位美术生成完成：\n" + report.Text);
        }

        /// <summary>供一键向导调用（不弹窗）</summary>
        public static void GenerateInternal(EditorUtil.Report report)
        {
            report.Head("生成占位美术 → " + Dir);
            EditorUtil.EnsureFolder(Dir);

            // ---- 棋盘格子（128px，带 3px 内描边，便于目视看清格线）----
            WriteTile(report, "Cell_Ground", GroundFill, GroundBorder);
            WriteTile(report, "Cell_Blocked", BlockedFill, BlockedBorder);
            WriteTile(report, "Cell_Spawn", SpawnFill, SpawnBorder);
            WriteTile(report, "Cell_End", EndFill, EndBorder);

            // ---- 路径箭头（朝上，运行时按角度 -90° 旋转）----
            {
                Texture2D tex = EditorUtil.NewTexture(64, 64);
                EditorUtil.FillTriangleUp(tex,
                    new Vector2(32f, 58f), new Vector2(14f, 9f), new Vector2(50f, 9f), PathArrowColor);
                EditorUtil.WriteSprite(Dir + "/Path_Arrow.png", tex);
                report.Ok("Path_Arrow.png  (64×64 朝上三角)");
            }

            // ---- 子弹点 ----
            {
                Texture2D tex = EditorUtil.NewTexture(24, 24);
                EditorUtil.FillCircle(tex, 12f, 12f, 9f, Color.white);
                EditorUtil.WriteSprite(Dir + "/Bullet_Dot.png", tex);
                report.Ok("Bullet_Dot.png  (24×24 圆点)");
            }

            // ---- 血条 ----
            // 100×20 px → PPU100 下原生 1.0 × 0.2 世界单位，
            // 血条 prefab 里把 scale 设成 0.6 即得 0.6 × 0.12 的条
            {
                Texture2D bg = EditorUtil.NewTexture(100, 20);
                EditorUtil.FillRect(bg, 0, 0, 100, 20,
                    new Color(0.06f, 0.06f, 0.08f, 0.85f), new Color(0f, 0f, 0f, 0.9f), 2);
                EditorUtil.WriteSprite(Dir + "/HP_Bar_Bg.png", bg);
                report.Ok("HP_Bar_Bg.png   (100×20 深底)");

                // Fill 用纯白，颜色交给 prefab 的 SpriteRenderer.color 决定
                // （这样以后要做"低血变红"只需改颜色，不用重新出图）
                Texture2D fill = EditorUtil.NewTexture(100, 20);
                EditorUtil.FillRect(fill, 0, 0, 100, 20, Color.white, Color.white, 0);
                EditorUtil.WriteSprite(Dir + "/HP_Bar_Fill.png", fill);
                report.Ok("HP_Bar_Fill.png (100×20 纯白，运行时着色)");
            }

            // ---- 射程提示圈 ----
            // 256×256、环宽 6px → PPU100 下原生 2.56 世界单位。
            // 运行时按"目标直径 / 原生直径"折算 localScale（与 CellView.Setup 同一套做法），
            // 所以以后换分辨率或换美术都不用改代码。
            {
                const int size = 256;
                Texture2D tex = EditorUtil.NewTexture(size, size);
                float half = size * 0.5f;
                EditorUtil.FillRing(tex, half, half, half - 2f, half - 8f, RangeRingColor);
                EditorUtil.WriteSprite(Dir + "/Range_Ring.png", tex);
                report.Ok("Range_Ring.png (256×256 圆环，运行时按射程缩放)");
            }

            // ---- 世界层背景（就地覆盖 Paper.png，见 GenerateBackground 注释）----
            GenerateBackground(report);

            AssetDatabase.SaveAssets();
        }

        private static void WriteTile(EditorUtil.Report report, string name, Color fill, Color border)
        {
            const int size = 128;
            Texture2D tex = EditorUtil.NewTexture(size, size);
            EditorUtil.FillRect(tex, 0, 0, size, size, fill, border, 3);
            EditorUtil.WriteSprite(Dir + "/" + name + ".png", tex);
            report.Ok(name + ".png  (" + size + "×" + size + ")");
        }

        // ------------------------------------------------------------------
        // 世界层背景（★ 就地覆盖 Paper.png，不改任何场景/配置）
        // ------------------------------------------------------------------

        /// <summary>
        /// 背景贴图路径。**刻意沿用原文件名 Paper.png**：
        /// 它已经被 `ResTable["Background"]` 与主场景的 Background 物件引用，
        /// 就地覆盖内容即可让两边同时生效 —— 换文件名反而要动 ResTable + 场景 + AB 打标三处。
        /// </summary>
        private const string BackgroundPath = "Assets/_UIAssets/Backgrounds/Paper.png";

        /// <summary>
        /// 生成深色科幻背景（替换掉与整体风格不符的"米色纸张"占位图）。
        ///
        /// 【为什么值得单独做一张】背景占满整个屏幕，它的色相决定了整个游戏的第一印象：
        ///   原本的米黄色纸张把"深色科幻"直接拉成了"手账风"，选关/战斗/结算全部界面都受影响。
        ///
        /// 【尺寸为什么是 1950×1300】与原图一致 ⇒ PPU=100 下仍是 19.5×13 世界单位，
        ///   背景物件在场景里的缩放（1.6）与 BackgroundParallax 的视差算法都不用改。
        ///
        /// 【固定随机种子】星点位置每次生成都相同 ⇒ 便于 diff 与复现（不会一跑一个样）。
        /// </summary>
        private static void GenerateBackground(EditorUtil.Report report)
        {
            const int W = 1950;
            const int H = 1300;

            // 深色科幻令牌（GameDesign §6）
            Color baseCol = new Color(0.063f, 0.078f, 0.114f, 1f);   // #10141D 战场底
            Color edgeCol = new Color(0.043f, 0.055f, 0.078f, 1f);   // #0B0E14 暗角
            Color gridCol = new Color(0.110f, 0.145f, 0.196f, 1f);   // #1C2532 格线
            Color cyanCol = new Color(0.208f, 0.878f, 1f, 1f);       // #35E0FF
            Color starCol = new Color(0.910f, 0.941f, 0.980f, 1f);   // #E8F0FA

            Color[] buf = new Color[W * H];
            float cx = (W - 1) * 0.5f;
            float cy = (H - 1) * 0.5f;

            // ① 底 + 径向暗角（中心亮、四角压暗，与界面暗角同一套观感）
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float dx = (x - cx) / cx;
                    float dy = (y - cy) / cy;
                    float r = Mathf.Clamp01(Mathf.Sqrt(dx * dx + dy * dy) / 1.10f);
                    buf[y * W + x] = Color.Lerp(baseCol, edgeCol, r * r);
                }
            }

            // ② 淡格线（130px ≈ 1.3 世界单位，纯装饰性纵深）
            const int step = 130;
            for (int x = 0; x < W; x += step)
            {
                for (int y = 0; y < H; y++)
                {
                    buf[y * W + x] = Color.Lerp(buf[y * W + x], gridCol, 0.35f);
                }
            }
            for (int y = 0; y < H; y += step)
            {
                for (int x = 0; x < W; x++)
                {
                    buf[y * W + x] = Color.Lerp(buf[y * W + x], gridCol, 0.35f);
                }
            }

            // ③ 中段一条极淡的青色辉光带（把视线往棋盘中心引）
            int bandY = Mathf.RoundToInt(H * 0.52f);
            int bandH = Mathf.Max(1, Mathf.RoundToInt(H * 0.10f));
            for (int y = bandY - bandH; y <= bandY + bandH; y++)
            {
                if (y < 0 || y >= H)
                {
                    continue;
                }
                float t = 1f - Mathf.Abs(y - bandY) / (float)bandH;
                float a = t * t * 0.06f;
                for (int x = 0; x < W; x++)
                {
                    buf[y * W + x] = Color.Lerp(buf[y * W + x], cyanCol, a);
                }
            }

            // ④ 星点（固定种子 → 结果可复现）
            System.Random rnd = new System.Random(20261008);
            for (int i = 0; i < 900; i++)
            {
                int sx = rnd.Next(W);
                int sy = rnd.Next(H);
                bool isCyan = rnd.NextDouble() < 0.25;
                float a = 0.10f + (float)rnd.NextDouble() * 0.30f;
                float rad = rnd.NextDouble() < 0.15 ? 1.6f : 0.8f;
                Dot(buf, W, H, sx, sy, rad, isCyan ? cyanCol : starCol, a);
            }

            Texture2D tex = EditorUtil.NewTexture(W, H);
            tex.SetPixels(buf);
            EditorUtil.WriteSprite(BackgroundPath, tex);
            report.Ok("Paper.png  (" + W + "×" + H + " 深色科幻背景：暗角 + 星点 + 淡格线)");
        }

        /// <summary>在像素缓冲上画一个软边圆点（星点用）。越界自动裁剪。</summary>
        private static void Dot(Color[] buf, int w, int h, float px, float py, float radius, Color col, float alpha)
        {
            int x0 = Mathf.Max(0, Mathf.FloorToInt(px - radius - 1f));
            int x1 = Mathf.Min(w - 1, Mathf.CeilToInt(px + radius + 1f));
            int y0 = Mathf.Max(0, Mathf.FloorToInt(py - radius - 1f));
            int y1 = Mathf.Min(h - 1, Mathf.CeilToInt(py + radius + 1f));
            for (int y = y0; y <= y1; y++)
            {
                for (int x = x0; x <= x1; x++)
                {
                    float dx = x - px;
                    float dy = y - py;
                    float d = Mathf.Sqrt(dx * dx + dy * dy);
                    float a = Mathf.Clamp01((radius - d) / Mathf.Max(0.0001f, radius)) * alpha;
                    if (a <= 0f)
                    {
                        continue;
                    }
                    buf[y * w + x] = Color.Lerp(buf[y * w + x], col, a);
                }
            }
        }
    }
}

using System.IO;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 程序合成"选关界面"BGM 的占位音源（P3）。
    ///
    /// 【为什么需要它】外部素材里只有 1 首战斗音乐（Tracks/Track1），而规格要求 2 首 BGM
    ///   （选关 / 战斗）。与其等美术或冒版权风险去下歌，不如按"程序生成占位美术"的同一思路
    ///   合成一段**能听、可循环、无版权**的环境铺底。
    ///
    /// 【为什么"无缝循环"不是靠淡化】把正弦频率**吸附到 1/loopLength 的整数倍**，
    ///   整个波形在循环点天然连续（相位对齐），不需要淡入淡出。
    ///   和弦切换用循环互淡（第 4 个和弦的尾巴淡向第 1 个和弦），跨循环点也连续。
    ///
    /// 输出：Assets/Audio/BGM/bgm_select.wav（12s / 44.1kHz / 单声道 16bit）
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建）▸ 生成占位 BGM
    /// </summary>
    public static class PlaceholderBgmGenerator
    {
        private const string OutPath = "Assets/Audio/BGM/bgm_select.wav";
        private const int SampleRate = 44100;
        private const float LoopSeconds = 12f;

        [MenuItem("Tools/塔防/高级（单步重建）/生成占位 BGM（选关）", false, 307)]
        public static void GenerateFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            GenerateAll(report);
            Debug.Log("[BGM] 占位 BGM 生成完成 → " + OutPath + "：\n" + report.Text);
        }

        [MenuItem("Tools/塔防/自动化（无弹窗）/生成占位 BGM（选关）", false, 904)]
        public static void GenerateNoDialog()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            GenerateAll(report);
            Debug.Log("[BGM] 占位 BGM 生成结果：\n" + report.Text);
        }

        public static void GenerateAll(EditorUtil.Report report)
        {
            report.Head("生成占位 BGM → " + OutPath);
            EditorUtil.EnsureFolderOfFile(OutPath);

            float[] pcm = Synthesize();
            WriteWav(OutPath, pcm, SampleRate);
            AssetDatabase.ImportAsset(OutPath, ImportAssetOptions.ForceUpdate);

            report.Ok(string.Format("bgm_select.wav  ({0:0.0}s / {1}Hz / 单声道 16bit / 无缝循环)",
                LoopSeconds, SampleRate));
        }

        // 四个和弦：Am - F - C - G（每个 3 秒）
        private static readonly float[][] ChordNotes =
        {
            new[] { 220.00f, 261.63f, 329.63f },   // Am
            new[] { 174.61f, 220.00f, 261.63f },   // F
            new[] { 261.63f, 329.63f, 392.00f },   // C
            new[] { 196.00f, 246.94f, 293.66f },   // G
        };

        private static readonly float[] ChordBass = { 110.00f, 87.31f, 130.81f, 98.00f };

        private static float[] Synthesize()
        {
            int total = Mathf.RoundToInt(SampleRate * LoopSeconds);
            float[] data = new float[total];

            float grid = 1f / LoopSeconds;          // 频率吸附网格
            float chordLen = LoopSeconds / ChordNotes.Length;
            const float xf = 0.55f;                 // 和弦互淡时长（秒）
            float lfo = 3f * grid;                  // 0.25Hz 颤音，恰好 3 个周期 → 循环相位对齐
            float twoPi = Mathf.PI * 2f;

            for (int n = 0; n < total; n++)
            {
                float t = n / (float)SampleRate;
                float p = t / chordLen;
                int idx = Mathf.FloorToInt(p) % ChordNotes.Length;
                float frac = p - Mathf.Floor(p);

                // 循环互淡：靠近结尾时把权重交给下一个和弦（首尾都在网格上，故跨界连续）
                float wNext = 0f;
                if (frac > (1f - xf / chordLen))
                {
                    wNext = (frac - (1f - xf / chordLen)) / (xf / chordLen);
                }
                int next = (idx + 1) % ChordNotes.Length;

                float v = (1f - wNext) * ChordValue(idx, t, grid, twoPi)
                        + wNext * ChordValue(next, t, grid, twoPi);

                // 颤音（周期性）
                v *= 0.82f + 0.18f * Mathf.Sin(twoPi * lfo * t);

                data[n] = v;
            }

            // 归一化到 -0.85，避免削波
            float peak = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                peak = Mathf.Max(peak, Mathf.Abs(data[i]));
            }
            if (peak > 0.0001f)
            {
                float g = 0.85f / peak;
                for (int i = 0; i < data.Length; i++)
                {
                    data[i] *= g;
                }
            }
            return data;
        }

        /// <summary>单个和弦在 t 时刻的采样值（三和音 + 低音）</summary>
        private static float ChordValue(int idx, float t, float grid, float twoPi)
        {
            float v = 0f;
            float[] notes = ChordNotes[idx];
            for (int i = 0; i < notes.Length; i++)
            {
                // 频率吸附到 1/loopLength 的整数倍 → 波形在循环点相位连续
                float f = Snap(notes[i], grid);
                float detune = Snap(notes[i] * 1.0035f, grid);   // 轻微失谐，pad 更厚
                v += 0.30f * Mathf.Sin(twoPi * f * t + i * 0.7f);
                v += 0.18f * Mathf.Sin(twoPi * detune * t + i * 1.9f);
            }
            float bass = Snap(ChordBass[idx], grid);
            v += 0.42f * Mathf.Sin(twoPi * bass * t);
            return v * 0.5f;
        }

        private static float Snap(float freq, float grid)
        {
            float k = Mathf.Max(1f, Mathf.Round(freq / grid));
            return k * grid;
        }

        // ------------------------------------------------------------------
        // WAV 写出（RIFF / PCM 16bit 单声道）
        // ------------------------------------------------------------------

        private static void WriteWav(string path, float[] samples, int sampleRate)
        {
            using (MemoryStream ms = new MemoryStream())
            using (BinaryWriter w = new BinaryWriter(ms))
            {
                int dataBytes = samples.Length * 2;

                w.Write(new[] { 'R', 'I', 'F', 'F' });
                w.Write(36 + dataBytes);
                w.Write(new[] { 'W', 'A', 'V', 'E' });
                w.Write(new[] { 'f', 'm', 't', ' ' });
                w.Write(16);                       // fmt chunk size
                w.Write((short)1);                 // PCM
                w.Write((short)1);                 // 单声道
                w.Write(sampleRate);
                w.Write(sampleRate * 2);           // byte rate = rate * channels * bits/8
                w.Write((short)2);                 // block align
                w.Write((short)16);                // bits per sample
                w.Write(new[] { 'd', 'a', 't', 'a' });
                w.Write(dataBytes);

                for (int i = 0; i < samples.Length; i++)
                {
                    short s = (short)Mathf.Clamp(Mathf.RoundToInt(samples[i] * 32767f), -32768, 32767);
                    w.Write(s);
                }
                w.Flush();
                File.WriteAllBytes(path, ms.ToArray());
            }
        }
    }
}

using System.Collections.Generic;
using UnityEditor;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 一次性配好工程级设置（P0-4）。
    ///
    /// 这些设置**必须**在跑游戏之前配好，否则会以很隐晦的方式出错：
    ///
    ///  ① Transparency Sort Mode = Custom Axis (0,-1,0)
    ///     这是 2D 游戏"靠下的物体盖住靠上的"的实现方式。
    ///     不设的话，怪物和塔之间谁盖谁完全看渲染顺序（不可控），
    ///     典型症状是"怪走到塔前面却被塔挡住了"。
    ///
    ///  ② Tag: UICanvas
    ///     UIManager 通过 GameObject.FindGameObjectWithTag("UICanvas") 找根 Canvas。
    ///     没有这个 Tag 会直接报错、整个 UI 打不开。
    ///
    ///  ③ Build Settings 只保留 main.unity
    ///     原工程指向已删除的 Launcher/Start/Main 三个场景，打包会失败。
    ///
    ///  ④ 关闭物理自动模拟（Physics / Physics2D）
    ///     我们已经完全不用物理，关掉可以让 Profiler 的 Physics 分区稳定为 0，
    ///     这就是需求 8 的量化验收标准。
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 2. 配置工程设置
    /// </summary>
    public static class ProjectSettingsConfigurator
    {
        public const string MainScenePath = "Assets/Scenes/main.unity";
        public const string UiCanvasTag = "UICanvas";

        [MenuItem("Tools/塔防/2. 配置工程设置", false, 102)]
        public static void Configure()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            ConfigureInternal(report);
            AssetDatabase.SaveAssets();

            Debug.Log(report.Errors > 0
                ? "[M0] 工程设置配置有错误：\n" + report.Text
                : "[M0] 工程设置配置完成：\n" + report.Text);
        }

        /// <summary>供一键向导调用（不弹窗）</summary>
        public static void ConfigureInternal(EditorUtil.Report report)
        {
            report.Head("配置工程设置");

            EnsureTag(UiCanvasTag, report);
            ConfigureTransparencySort(report);
            ConfigureBuildSettings(report);
            ConfigurePhysics(report);
            ConfigurePlayerSettings(report);
        }

        /// <summary>
        /// 确保 UICanvas Tag 存在。
        /// 单独暴露出来是因为 SceneMainBuilder 要给 Canvas 赋这个 Tag，
        /// 而**给未定义的 Tag 赋值会直接抛 UnityException**，
        /// 所以搭场景之前必须先过这一关（哪怕用户没单独点过「6. 配置工程设置」）。
        /// </summary>
        public static void EnsureUiCanvasTag()
        {
            EditorUtil.Report tmp = new EditorUtil.Report();
            EnsureTag(UiCanvasTag, tmp);
        }

        // ------------------------------------------------------------------
        // Tag
        // ------------------------------------------------------------------

        private static void EnsureTag(string tag, EditorUtil.Report report)
        {
            Object[] assets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset");
            if (assets == null || assets.Length == 0)
            {
                report.Error("读不到 ProjectSettings/TagManager.asset，无法添加 Tag");
                return;
            }
            SerializedObject so = new SerializedObject(assets[0]);
            SerializedProperty tags = so.FindProperty("tags");
            if (tags == null)
            {
                report.Error("TagManager 里找不到 tags 数组");
                return;
            }

            for (int i = 0; i < tags.arraySize; i++)
            {
                if (tags.GetArrayElementAtIndex(i).stringValue == tag)
                {
                    report.Ok("Tag「" + tag + "」已存在，跳过");
                    return;
                }
            }

            tags.InsertArrayElementAtIndex(tags.arraySize);
            tags.GetArrayElementAtIndex(tags.arraySize - 1).stringValue = tag;
            so.ApplyModifiedProperties();
            report.Ok("已添加 Tag「" + tag + "」");
        }

        // ------------------------------------------------------------------
        // 渲染排序
        // ------------------------------------------------------------------

        private static void ConfigureTransparencySort(EditorUtil.Report report)
        {
            Object[] assets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset");
            if (assets == null || assets.Length == 0)
            {
                report.Error("读不到 ProjectSettings/GraphicsSettings.asset");
                return;
            }
            SerializedObject so = new SerializedObject(assets[0]);
            SerializedProperty mode = so.FindProperty("m_TransparencySortMode");
            SerializedProperty axis = so.FindProperty("m_TransparencySortAxis");

            if (mode == null || axis == null)
            {
                report.Warn("找不到 m_TransparencySortMode/m_TransparencySortAxis，" +
                            "请手动设置：Project Settings ▸ Graphics ▸ Transparency Sort Mode = Custom Axis (0,-1,0)");
                return;
            }

            mode.intValue = 3;   // TransparencySortMode.CustomAxis
            axis.vector3Value = new Vector3(0f, -1f, 0f);
            so.ApplyModifiedProperties();
            report.Ok("Transparency Sort Mode = Custom Axis (0,-1,0)（Y 越小越靠前，实现前后遮挡）");
        }

        // ------------------------------------------------------------------
        // 构建场景
        // ------------------------------------------------------------------

        private static void ConfigureBuildSettings(EditorUtil.Report report)
        {
            if (AssetDatabase.LoadAssetAtPath<Object>(MainScenePath) == null)
            {
                report.Warn("主场景不存在（稍后由「搭建 main 场景」生成）：" + MainScenePath);
                return;
            }

            List<EditorBuildSettingsScene> scenes = new List<EditorBuildSettingsScene>();
            // 只保留 main.unity —— 其余场景文件已被删除，留着会让打包直接失败
            scenes.Add(new EditorBuildSettingsScene(MainScenePath, true));
            EditorBuildSettings.scenes = scenes.ToArray();
            report.Ok("Build Settings 已设为仅 " + MainScenePath);
        }

        // ------------------------------------------------------------------
        // 物理
        // ------------------------------------------------------------------

        private static void ConfigurePhysics(EditorUtil.Report report)
        {
            // 2D：属性名 m_AutoSimulation
            bool ok2d = TrySetBool("ProjectSettings/Physics2DSettings.asset", "m_AutoSimulation", false);
            if (ok2d)
            {
                report.Ok("已关闭 Physics2D 自动模拟（战斗判定不依赖物理，Profiler 的 Physics2D 分区将为 0）");
            }
            else
            {
                report.Warn("未能自动关闭 Physics2D 自动模拟，可手动设置：" +
                            "Project Settings ▸ Physics 2D ▸ 取消勾选 Simulate（或用 Simulation Mode = Script）");
            }

            // 3D：属性名同样是 m_AutoSimulation
            bool ok3d = TrySetBool("ProjectSettings/DynamicsManager.asset", "m_AutoSimulation", false);
            if (ok3d)
            {
                report.Ok("已关闭 Physics(3D) 自动模拟");
            }
            else
            {
                report.Warn("未能自动关闭 3D 物理自动模拟（项目里已无任何 3D 碰撞体，可忽略）");
            }
        }

        private static bool TrySetBool(string settingsAssetPath, string propertyName, bool value)
        {
            Object[] assets = AssetDatabase.LoadAllAssetsAtPath(settingsAssetPath);
            if (assets == null || assets.Length == 0)
            {
                return false;
            }
            SerializedObject so = new SerializedObject(assets[0]);
            SerializedProperty prop = so.FindProperty(propertyName);
            if (prop == null || prop.propertyType != SerializedPropertyType.Boolean)
            {
                return false;
            }
            prop.boolValue = value;
            so.ApplyModifiedProperties();
            return true;
        }

        // ------------------------------------------------------------------
        // Player Settings
        // ------------------------------------------------------------------

        private static void ConfigurePlayerSettings(EditorUtil.Report report)
        {
            PlayerSettings.defaultScreenWidth = 1920;
            PlayerSettings.defaultScreenHeight = 1080;
            PlayerSettings.resizableWindow = true;
            PlayerSettings.runInBackground = true;
            // 横屏（2D 塔防的棋盘是宽大于高的）
            PlayerSettings.defaultInterfaceOrientation = UIOrientation.LandscapeLeft;
            report.Ok("Player Settings：默认窗口 1920×1080、可调整大小、允许后台运行、横屏");
        }
    }
}

using System.IO;
using UnityEditor;
using UnityEngine;
using HybridCLR.Editor.Commands;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 【无人值守构建】纯热更流水线：热更 dll ▸ 拷贝+md5 ▸ 收集器登记 ▸ 资源包（不含 APK）。
    ///
    /// 用途：命令行 batchmode 驱动（Unity MCP 不可用时的替代通道），产出物可被
    /// HotUpdateServer（junction → StreamingAssets/HybridCLR + Bundles/Android/FreeTower）
    /// 直接下发到模拟器/真机：
    ///   ① HybridCLR Generate/All —— 重编热更 dll（与「7. 一键完整构建」同源）
    ///   ② 拷贝热更 dll + AOT 元数据到 StreamingAssets/HybridCLR/ + 生成 md5 清单
    ///   ③ 收集器登记真机必需资源（Main 场景 / BootUI / Reporter 图标，幂等）
    ///   ④ YooAsset 资源包构建（版本自动递增）
    ///
    /// 【与菜单 7（BuildApkFull）的区别】跳过 APK 构建 —— 纯热更场景不需要出包，
    /// 也不占用 IL2CPP 打包的几十分钟。
    ///
    /// 【命令行】
    ///   Unity.exe -batchmode -projectPath E:\MyTowerGame ^
    ///     -executeMethod FTProject.EditorTools.ReporterHotfixBuild.Start ^
    ///     -logFile E:\MyTowerGame\Logs\reporter_build.log
    ///   注意：**不加 -quit** —— 流水线由 update tick 驱动，完成/失败都会写状态文件
    ///   Library/FTReporterBuildStatus.txt（START / PHASE / DONE OK / DONE FAIL），
    ///   外部轮询到 DONE 后结束编辑器进程即可。
    ///
    /// 【为什么用状态机】Generate/All 会重写 AOTGenericReferences.cs，可能触发脚本
    /// 编译与域重载 —— 正在执行的方法栈会被直接杀掉。所以阶段存 SessionState
    /// （域重载后保留），由 [InitializeOnLoad] 重新挂上的 Tick 继续推进；
    /// 每个阶段的"推进"放在**执行成功之后**：若域重载打断了执行，下一轮会原地
    /// 重跑该阶段（幂等），宁可多花几分钟也绝不静默使用旧产物。
    /// </summary>
    [InitializeOnLoad]
    public static class ReporterHotfixBuild
    {
        private const string PhaseKey = "FTReporterBuild.Phase";

        /// <summary>SessionState 键：dll-only 模式（只重编+同步热更 dll，跳过收集器与 AB）。</summary>
        private const string DllOnlyKey = "FTReporterBuild.DllOnly";

        private const string StatusFileRelative = "Library/FTReporterBuildStatus.txt";

        /// <summary>YooAsset 包裹名（= AB 输出目录名，与 BuildApkFull 的约定一致）。</summary>
        private const string YooPackageName = "FreeTower";

        /// <summary>
        /// 工程根目录。**不依赖进程工作目录** —— batchmode 命令行启动时 cwd 未必是
        /// 工程根（GUI 下由 Hub 启动才会是），所以一律从 Application.dataPath 推。
        /// </summary>
        private static string ProjectRoot
        {
            get { return Path.GetDirectoryName(Application.dataPath); }
        }

        private static string StatusFilePath
        {
            get { return Path.Combine(ProjectRoot, StatusFileRelative); }
        }

        /// <summary>
        /// 编辑器内入口：Unity 编辑器开着时用（命令行 batchmode 会被工程锁挡住）。
        /// 与命令行 Start 完全同一套状态机；点击后全自动跑完 dll+AB（参考状态文件
        /// Library/FTReporterBuildStatus.txt 与 Console 日志）。
        /// </summary>
        [MenuItem("Tools/塔防/9. Reporter 修复构建（纯热更 dll+AB，不含 APK）", false, 112)]
        public static void StartFromMenu()
        {
            Start();
        }

        /// <summary>
        /// 【dll-only 模式】只跑 ① Generate ② Copy+md5，跳过收集器与 AB。
        /// 用于"资源包没变、只重编热更 dll"的场景 —— 典型是**编译宏变更**后
        /// （宏在热更 dll 编译期生效，改了宏必须重编 dll 才能让运行时分支出新行为）。
        /// </summary>
        [MenuItem("Tools/塔防/9a. 仅重编热更 dll（宏变更后同步用）", false, 113)]
        public static void StartDllOnlyFromMenu()
        {
            StartDllOnly();
        }

        /// <summary>dll-only 的 batchmode 入口。</summary>
        public static void StartDllOnly()
        {
            string phase = GetPhase();
            if (phase != "Idle" && phase != "Done" && phase != "Fail")
            {
                Debug.LogWarning("[ReporterBuild] 已有流水线在跑（" + phase + "），忽略本次 StartDllOnly。");
                return;
            }

            try { File.Delete(StatusFilePath); }
            catch (System.Exception) { }

            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                Fail("当前构建目标不是 Android（" + EditorUserBuildSettings.activeBuildTarget + "），中止。");
                return;
            }

            SessionState.SetString(DllOnlyKey, "1");
            SetPhase("Generate");
            WriteStatus("START DLL-ONLY " + System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            Debug.Log("[ReporterBuild] 开始（dll-only）：Generate ▸ Copy ▸ md5（跳过收集器与 AB）");
        }

        /// <summary>batchmode 入口（-executeMethod 只认无参静态方法）。</summary>
        public static void Start()
        {
            string phase = GetPhase();
            if (phase != "Idle" && phase != "Done" && phase != "Fail")
            {
                Debug.LogWarning("[ReporterBuild] 已有流水线在跑（" + phase + "），忽略本次 Start。");
                return;
            }

            // 清掉上一次的轮询状态（外部以"本次启动后新出现的 DONE 行"为准）
            try { File.Delete(StatusFilePath); }
            catch (System.Exception) { }

            SessionState.SetString(DllOnlyKey, "");   // 防串：完整流程不带 dll-only 标志

            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                Fail("当前构建目标不是 Android（" + EditorUserBuildSettings.activeBuildTarget +
                     "），热更 dll / AB 会打到错误平台。请先在编辑器里切到 Android 再跑本流水线。");
                return;
            }

            SetPhase("Generate");
            WriteStatus("START REPORTER-HOTFIX " + System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            Debug.Log("[ReporterBuild] 开始：dll ▸ 拷贝+md5 ▸ 收集器 ▸ AB（纯热更，不含 APK）");
        }

        static ReporterHotfixBuild()
        {
            // 【InitializeOnLoad】每次域重载后重新挂上驱动器，流水线从 SessionState 断点继续。
            EditorApplication.update += Tick;
        }

        private static void Tick()
        {
            string phase = GetPhase();
            if (phase == "Idle" || phase == "Done" || phase == "Fail" || phase == "AbBusy")
            {
                return;
            }
            // 编译 / 导入中一律等待（状态机会在空闲后自动继续）
            if (EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                return;
            }

            try
            {
                switch (phase)
                {
                    case "Generate": TickGenerate(); break;
                    case "Copy": TickCopy(); break;
                    case "Collector": TickCollector(); break;
                    case "AbBuild": TickAbBuild(); break;
                }
            }
            catch (System.Exception e)
            {
                Fail(phase + " 阶段异常：" + e);
            }
        }

        // ------------------------------------------------------------------
        // ① HybridCLR Generate/All
        // ------------------------------------------------------------------

        private static void TickGenerate()
        {
            Debug.Log("[ReporterBuild] ① HybridCLR Generate/All …");
            // 直接调包内 API（与菜单「HybridCLR/Generate/All」同一实现），
            // 不依赖 batchmode 下菜单系统的可用性。
            PrebuildCommand.GenerateAll();
            AssetDatabase.Refresh();

            // 执行成功后才推进阶段：若上面触发了域重载，重载回来的 Tick 会原地重跑
            // 本阶段（此时产物已是最新，第二次跑通常不再触发重载，代价可接受）。
            SetPhase("Copy");
            WriteStatus("PHASE generate ok");
            Debug.Log("[ReporterBuild] ① 完成。");
        }

        // ------------------------------------------------------------------
        // ② 拷贝热更 dll + 生成 md5 清单
        // ------------------------------------------------------------------

        private static void TickCopy()
        {
            Debug.Log("[ReporterBuild] ② 拷贝 dll + 生成 md5 …");

            EditorUtil.Report report = new EditorUtil.Report();
            HybridCLRDllCopier.Copy(report);
            if (report.Errors > 0)
            {
                Fail("② 拷贝热更 dll 失败：\n" + report.Text);
                return;
            }

            EditorUtil.Report md5Report = new EditorUtil.Report();
            HybridCLRMd5Generator.Generate(md5Report);
            if (md5Report.Errors > 0)
            {
                Fail("② 生成 md5 清单失败：\n" + md5Report.Text);
                return;
            }

            AssetDatabase.Refresh();   // StreamingAssets 新增文件，刷新一次

            // dll-only 模式：Copy 之后直接收工（不碰收集器与 AB —— 它们没有变化）
            if (SessionState.GetString(DllOnlyKey, "") == "1")
            {
                SessionState.SetString(DllOnlyKey, "");
                SetPhase("Done");
                WriteStatus("PHASE copy ok");
                WriteStatus("DONE OK (dll-only)");
                Debug.Log("[ReporterBuild] ✔ dll-only 完成（跳过收集器登记与 AB 构建）。");
                return;
            }

            SetPhase("Collector");
            WriteStatus("PHASE copy ok");
            Debug.Log("[ReporterBuild] ② 完成。");
        }

        // ------------------------------------------------------------------
        // ③ 收集器登记（幂等）
        // ------------------------------------------------------------------

        private static void TickCollector()
        {
            Debug.Log("[ReporterBuild] ③ 收集器登记 …");
            string error;
            if (!AddMainSceneCollector.Ensure(out error))
            {
                Fail("③ 收集器登记失败：" + error);
                return;
            }

            AssetDatabase.SaveAssets();
            SetPhase("AbBuild");
            WriteStatus("PHASE collector ok");
            Debug.Log("[ReporterBuild] ③ 完成。");
        }

        // ------------------------------------------------------------------
        // ④ YooAsset 资源包构建（版本自动递增）
        // ------------------------------------------------------------------

        private static void TickAbBuild()
        {
            // 防重入标记：AbBusy 状态下 Tick 不再进入任何分支（构建是同步阻塞的，
            // 正常路径执行完会直接推进到 Done；这里只防御理论上不可能发生的域重载重入）。
            SetPhase("AbBusy");

            string version = NextVersion();
            WriteStatus("PHASE ab building version=" + version);
            Debug.Log("[ReporterBuild] ④ 构建资源包，版本 " + version + " …");

#if USE_YOOASSET
            EditorUtil.Report report = new EditorUtil.Report();
            bool ok = FTYooAssetSetupWizard.BuildRealBundlesCore(version, false, report);
            if (!ok)
            {
                Fail("④ YooAsset 资源包构建失败：\n" + report.Text);
                return;
            }
            Debug.Log("[ReporterBuild] ④ AB 构建成功：\n" + report.Text);
            WriteStatus("PHASE ab ok version=" + version);
#else
            Fail("④ 当前未启用 USE_YOOASSET 宏，本流水线只支持 YooAsset 链路。");
            return;
#endif

            SetPhase("Done");
            WriteStatus("DONE OK version=" + version);
            Debug.Log("[ReporterBuild] ✔ 全部完成（dll + AB v" + version + "）。可结束编辑器进程。");
        }

        /// <summary>
        /// 自动选下一个资源包版本号：扫 Bundles/&lt;平台&gt;/&lt;包裹&gt;/ 下已有的
        /// "x.y.z" 目录，取最大版本把 patch 位 +1；没有任何历史版本则从 1.0.0 起。
        /// （与 BuildApkFull 同算法，两边必须一致，否则两套流水线会撞版本号。）
        /// </summary>
        private static string NextVersion()
        {
            string root = Path.Combine(ProjectRoot, "Bundles",
                EditorUserBuildSettings.activeBuildTarget.ToString(), YooPackageName);

            int major = 1, minor = 0, patch = -1;
            if (Directory.Exists(root))
            {
                foreach (string dir in Directory.GetDirectories(root))
                {
                    string name = Path.GetFileName(dir);
                    string[] parts = name.Split('.');
                    if (parts.Length != 3) continue;
                    int a, b, c;
                    if (!int.TryParse(parts[0], out a) || !int.TryParse(parts[1], out b)
                        || !int.TryParse(parts[2], out c)) continue;
                    if (a > major || (a == major && (b > minor || (b == minor && c > patch))))
                    {
                        major = a; minor = b; patch = c;
                    }
                }
            }

            if (patch < 0)
            {
                return "1.0.0";
            }
            return major + "." + minor + "." + (patch + 1);
        }

        // ------------------------------------------------------------------
        // 通用
        // ------------------------------------------------------------------

        private static void Fail(string message)
        {
            SetPhase("Fail");
            Debug.LogError("[ReporterBuild] ✘ 流水线失败：" + message);

            string oneLine = message.Replace("\r", " ").Replace("\n", " ");
            if (oneLine.Length > 160)
            {
                oneLine = oneLine.Substring(0, 160);
            }
            WriteStatus("DONE FAIL " + oneLine);
        }

        private static string GetPhase()
        {
            return SessionState.GetString(PhaseKey, "Idle");
        }

        private static void SetPhase(string phase)
        {
            SessionState.SetString(PhaseKey, phase);
        }

        /// <summary>往状态文件追加一行（外部轮询用；失败不影响流水线）</summary>
        private static void WriteStatus(string line)
        {
            try
            {
                File.AppendAllText(StatusFilePath,
                    System.DateTime.Now.ToString("HH:mm:ss") + " " + line + "\n");
            }
            catch (System.Exception e)
            {
                Debug.LogWarning("[ReporterBuild] 状态文件写入失败：" + e.Message);
            }
        }
    }
}

using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 在 main.unity 里搭出完整可运行的战斗场景（P0-2 / 需求 6）。
    ///
    /// 【为什么用脚本搭场景而不是让人手工拖】
    ///   手工搭场景的问题不是"慢"，而是**不可复现**：漏连一个引用、名字打错一个字符，
    ///   都要到运行时以 NullReference 的形式暴露，排查成本极高。
    ///   脚本搭场景 + GameSceneLauncher 启动时校验，能把这类问题在点下 Play 之前就报出来。
    ///
    /// 【本脚本会重建整个场景】执行前会把原 main.unity 备份到 Assets/Scenes/_Backup/。
    ///
    /// 目标层级：
    ///   Camera(+CameraController)      正交相机，半径由 CameraController.FitBoard 按棋盘算
    ///   EventSystem                    UGUI 事件系统（按钮点击必需）
    ///   Launcher                       全局启动器（注册并初始化各管理器）
    ///   UICanvas  [tag=UICanvas]       Canvas(ScreenSpaceOverlay) + CanvasScaler(1920×1080)
    ///     ├── BgPanel                  背景层
    ///     ├── NormalPanel              常规面板层（HudView 挂这里）
    ///     └── TipsPanel                浮层提示层（TipsView 挂这里）
    ///   BattleRoot                     战斗棋盘根
    ///     ├── Background               Paper.png 世界空间背景
    ///     ├── BoardRoot    (BoardView)      格子
    ///     ├── PathRoot     (PathArrowView)  路径箭头
    ///     ├── TowerRoot    (TowerPlacement) 塔 + 放置预览
    ///     ├── EnemyRoot                     怪物
    ///     └── BulletRoot                    子弹
    ///   GameFlow          (GameFlowManager)     关卡流程总控
    ///   GameSceneLauncher (GameSceneLauncher)   组合根：校验并注入引用
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建）▸ 重建 main 场景
    /// </summary>
    public static class SceneMainBuilder
    {
        public const string MainScenePath = ProjectSettingsConfigurator.MainScenePath;
        private const string BackupPath = "Assets/Scenes/_Backup/main_before_builder.unity";
        private const string BackgroundSpritePath = "Assets/_UIAssets/Backgrounds/Paper.png";

        /// <summary>
        /// 背景基准缩放：Paper.png 是 19.5×13 世界单位。
        /// 2026-10-16：1.6 → 2.2（×视差 oversize 1.4 = 3.08×）—— 适配相机最大缩小档：
        ///   1.6 旧值在 19.5:9 起会露出黑边；2.2 覆盖 16:9 全缩放档、19.5:9 至约 2.3× 缩档。
        /// 同值会写入 BackgroundParallax.baseScale（运行时自举也用它）。
        /// </summary>
        private const float BackgroundScale = 2.2f;

        /// <summary>
        /// 菜单入口：**危险**，会重建整个 main.unity（原文件先备份）。
        /// 直接执行、不弹窗（自动化友好）；需要执行前二次确认的走「带确认」菜单。
        /// </summary>
        [MenuItem("Tools/塔防/高级（单步重建）/重建 main 场景（危险：会清空重建）", false, 307)]
        public static void Build()
        {
            BuildInternal_NoDialog();
        }

        /// <summary>
        /// 「带确认」入口，等价于旧菜单 + 执行前确认弹窗。**仅用于人工交互**，
        /// 自动化不得调用（会阻塞编辑器）。
        /// </summary>
        [MenuItem("Tools/塔防/高级（单步重建）/强制执行：重建 main 场景（带确认）", false, 317)]
        public static void BuildConfirm()
        {
            if (!EditorUtility.DisplayDialog("重建 main 场景",
                    "此操作会**清空并重建** main.unity 的全部根对象，" +
                    "你在场景里的手工接线会丢失（原文件会先备份到\n" +
                    BackupPath + "）。\n\n确认继续？",
                    "重建", "取消"))
            {
                return;
            }
            BuildInternal_NoDialog();
        }

        private static void BuildInternal_NoDialog()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            bool ok = BuildInternal(report);
            Debug.Log(ok
                ? "[M0] 场景重建完成，已打开 main.unity：\n" + report.Text
                : "[M0] 场景重建有错误：\n" + report.Text);
        }

        /// <summary>
        /// 安全入口（供一键补齐向导调用）：场景已存在则**跳过**，只在缺失时搭建。
        /// 这样"跑一次向导"不会抹掉手工接线。
        /// </summary>
        public static bool EnsureOrBuildInternal(EditorUtil.Report report)
        {
            report.Head("main 场景（安全模式：缺失才搭建）");
            if (AssetDatabase.LoadAssetAtPath<Object>(MainScenePath) != null)
            {
                report.Ok("main.unity 已存在，跳过重建（保住手工接线）。需要重建请走「高级（单步重建）」");
                return true;
            }
            return BuildInternal(report);
        }

        /// <summary>供一键向导调用（不弹窗，会重建）</summary>
        public static bool BuildInternal(EditorUtil.Report report)
        {
            report.Head("搭建 main 场景 → " + MainScenePath);

            // ① 保存用户当前改动（否则切场景会丢）
            if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())
            {
                report.Warn("用户取消了「保存当前场景」，搭建中止");
                return false;
            }

            bool existed = AssetDatabase.LoadAssetAtPath<Object>(MainScenePath) != null;
            if (existed)
            {
                BackupScene(report);
            }

            // ② 打开（或新建）主场景
            Scene scene;
            if (existed)
            {
                scene = EditorSceneManager.OpenScene(MainScenePath, OpenSceneMode.Single);
                // 清空所有根对象，保证结果可复现
                GameObject[] roots = scene.GetRootGameObjects();
                for (int i = 0; i < roots.Length; i++)
                {
                    Object.DestroyImmediate(roots[i]);
                }
                report.Ok(string.Format("已清空原场景的 {0} 个根对象", roots.Length));
            }
            else
            {
                EditorUtil.EnsureFolderOfFile(MainScenePath);
                scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
                report.Ok("主场景不存在，已新建空场景");
            }

            // ③ 逐步搭建
            CameraController camera = BuildCamera(report);
            BuildEventSystem(report);
            BuildLauncher(report);
            BuildUiCanvas(report);
            Transform battleRoot = BuildBattleRoot(report, out BoardView boardView,
                out PathArrowView arrowView, out TowerPlacement placement);
            GameFlowManager flow = BuildGameFlow(report);

            // ④ 组合根接线
            BuildSceneLauncher(report, flow, boardView, arrowView, placement, battleRoot);

            EditorSceneManager.MarkSceneDirty(scene);
            bool saved = EditorSceneManager.SaveScene(scene, MainScenePath);
            if (!saved)
            {
                report.Error("保存场景失败：" + MainScenePath);
                return false;
            }
            report.Ok("场景已保存");
            if (camera == null)
            {
                report.Warn("相机未创建，运行时将无法取景");
            }
            return true;
        }

        private static void BackupScene(EditorUtil.Report report)
        {
            EditorUtil.EnsureFolderOfFile(BackupPath);
            AssetDatabase.DeleteAsset(BackupPath);
            if (AssetDatabase.CopyAsset(MainScenePath, BackupPath))
            {
                report.Ok("原场景已备份到 " + BackupPath);
            }
            else
            {
                report.Warn("原场景备份失败（不影响搭建）：" + BackupPath);
            }
        }

        // ------------------------------------------------------------------
        // 相机
        // ------------------------------------------------------------------

        private static CameraController BuildCamera(EditorUtil.Report report)
        {
            GameObject go = new GameObject("Camera");
            Camera cam = go.AddComponent<Camera>();
            cam.tag = "MainCamera";                 // Camera.main 依赖这个 Tag
            cam.orthographic = true;
            cam.orthographicSize = 5.5f;            // 运行时由 CameraController.FitBoard 覆盖
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.09f, 0.10f, 0.13f, 1f);
            cam.nearClipPlane = 0.1f;
            cam.farClipPlane = 100f;
            go.transform.position = new Vector3(0f, 0f, CameraController.DefaultZ);
            go.transform.rotation = Quaternion.identity;

            CameraController ctrl = go.AddComponent<CameraController>();
            report.Ok("相机：正交、Tag=MainCamera、位置 (0,0,-10)，半径运行时按棋盘自适应");
            return ctrl;
        }

        // ------------------------------------------------------------------
        // 事件系统 / 启动器
        // ------------------------------------------------------------------

        private static void BuildEventSystem(EditorUtil.Report report)
        {
            GameObject go = new GameObject("EventSystem");
            go.AddComponent<EventSystem>();
            go.AddComponent<StandaloneInputModule>();
            report.Ok("EventSystem（UGUI 按钮点击必需；注意 TowerPlacement 用 " +
                      "EventSystem.IsPointerOverGameObject() 避免点 UI 时误放塔）");
        }

        private static void BuildLauncher(EditorUtil.Report report)
        {
            GameObject go = new GameObject("Launcher");
            go.AddComponent<Launcher>();
            report.Ok("Launcher（注册各管理器 → 初始化资源加载 → 加载 8 张配置表）");
        }

        // ------------------------------------------------------------------
        // UI
        // ------------------------------------------------------------------

        private static void BuildUiCanvas(EditorUtil.Report report)
        {
            GameObject go = new GameObject("UICanvas");
            Canvas canvas = go.AddComponent<Canvas>();
            // Overlay 而不是 ScreenSpaceCamera：HUD 不受相机缩放/平移影响
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = 100;

            CanvasScaler scaler = go.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            // 0.5 = 宽高各占一半权重，横竖屏切换时不会一边被拉爆
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;

            go.AddComponent<GraphicRaycaster>();
            // 先确保 Tag 已存在：给未定义的 Tag 赋值会抛 UnityException
            ProjectSettingsConfigurator.EnsureUiCanvasTag();
            go.tag = ProjectSettingsConfigurator.UiCanvasTag;

            CreatePanel(go.transform, "BgPanel");
            CreatePanel(go.transform, "NormalPanel");
            CreatePanel(go.transform, "TipsPanel");

            report.Ok("UICanvas（ScreenSpaceOverlay，1920×1080，Match 0.5）+ 三层 Panel");
        }

        private static void CreatePanel(Transform parent, string name)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);
            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = Vector2.zero;
            rt.sizeDelta = Vector2.zero;
            rt.localScale = Vector3.one;
        }

        // ------------------------------------------------------------------
        // 战斗根节点
        // ------------------------------------------------------------------

        private static Transform BuildBattleRoot(EditorUtil.Report report,
            out BoardView boardView, out PathArrowView arrowView, out TowerPlacement placement)
        {
            GameObject root = new GameObject("BattleRoot");

            // 背景
            Sprite bg = AssetDatabase.LoadAssetAtPath<Sprite>(BackgroundSpritePath);
            GameObject bgGo = new GameObject("Background");
            bgGo.transform.SetParent(root.transform, false);
            bgGo.transform.localPosition = Vector3.zero;
            bgGo.transform.localScale = new Vector3(BackgroundScale, BackgroundScale, 1f);
            SpriteRenderer bgSr = bgGo.AddComponent<SpriteRenderer>();
            bgSr.sprite = bg;
            bgSr.sortingLayerName = BoardSorting.LayerBg;   // Bg 层：层优先级已保证在棋盘之下
            bgSr.sortingOrder = BoardSorting.Background;
            bgSr.color = new Color(1f, 1f, 1f, 0.55f);
            // M4-4：背景视差。Init 必须在设完缩放与颜色之后调用 —— 它要记住这两者的基准值。
            BackgroundParallax parallax = bgGo.AddComponent<BackgroundParallax>();
            parallax.baseScale = BackgroundScale;   // 与场景缩放同源；Init 幂等（编辑/运行各调一次）
            parallax.Init();
            if (bg == null)
            {
                report.Warn("背景贴图未找到或未导入为 Sprite：" + BackgroundSpritePath);
            }

            // 格子
            GameObject boardGo = new GameObject("BoardRoot");
            boardGo.transform.SetParent(root.transform, false);
            boardView = boardGo.AddComponent<BoardView>();

            // 路径箭头
            GameObject pathGo = new GameObject("PathRoot");
            pathGo.transform.SetParent(root.transform, false);
            arrowView = pathGo.AddComponent<PathArrowView>();

            // 塔（放置控制器与塔的父节点同一个对象，预览体也挂在它下面）
            GameObject towerGo = new GameObject("TowerRoot");
            towerGo.transform.SetParent(root.transform, false);
            placement = towerGo.AddComponent<TowerPlacement>();

            // 怪物 / 子弹（纯容器，实例由对象池创建并挂进来）
            GameObject enemyGo = new GameObject("EnemyRoot");
            enemyGo.transform.SetParent(root.transform, false);
            GameObject bulletGo = new GameObject("BulletRoot");
            bulletGo.transform.SetParent(root.transform, false);

            report.Ok("BattleRoot → Background / BoardRoot(BoardView) / PathRoot(PathArrowView) " +
                      "/ TowerRoot(TowerPlacement) / EnemyRoot / BulletRoot");
            return root.transform;
        }

        private static GameFlowManager BuildGameFlow(EditorUtil.Report report)
        {
            GameObject go = new GameObject("GameFlow");
            GameFlowManager flow = go.AddComponent<GameFlowManager>();
            flow.startLevelId = 0;   // 0 = 用配置表里第一个关卡
            report.Ok("GameFlow（GameFlowManager，startLevelId=0 → 取 TBSceneInfo 第一行）");
            return flow;
        }

        // ------------------------------------------------------------------
        // 组合根
        // ------------------------------------------------------------------

        private static void BuildSceneLauncher(EditorUtil.Report report,
            GameFlowManager flow, BoardView boardView, PathArrowView arrowView,
            TowerPlacement placement, Transform battleRoot)
        {
            GameObject go = new GameObject("GameSceneLauncher");
            GameSceneLauncher launcher = go.AddComponent<GameSceneLauncher>();

            launcher.flowManager = flow;
            launcher.boardView = boardView;
            launcher.pathArrowView = arrowView;
            launcher.boardRoot = battleRoot.Find("BoardRoot");
            launcher.pathRoot = battleRoot.Find("PathRoot");
            launcher.towerRoot = battleRoot.Find("TowerRoot");
            launcher.enemyRoot = battleRoot.Find("EnemyRoot");
            launcher.bulletRoot = battleRoot.Find("BulletRoot");

            // placement 与 towerRoot 是同一个对象，GameSceneLauncher 不持有它的引用：
            // TowerPlacement 自己从 Inspector 取父节点即可，少一处可漏连的引用
            if (placement == null)
            {
                report.Warn("TowerPlacement 未创建，将无法建塔");
            }

            report.Ok("GameSceneLauncher（组合根：启动时校验并注入全部场景引用）");
        }
    }
}

using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 渲染层级标准化 / 体检（2026-10-21）。
    ///
    /// 【为什么需要这个工具】
    ///   层级约定写在 <see cref="BoardSorting"/> 里，但**资产是另一套事实**：
    ///   敌人预制体是从美术包 Instantiate 来的，源包自带的 SortingGroup 序并不统一
    ///   （实测 119 个里 88 个是 200，其余 31 个是 0/1/2/3/4、100–104、201–204），
    ///   塔预制体则根本没有 SortingGroup。只看代码会以为层级是对的。
    ///   所以约定必须能被"跑一次菜单"落到资产上，并且能被独立校验。
    ///
    /// 【约定（与 BoardSorting 一一对应）】
    ///   排序层：Bg < Main < Pop（层优先级高于层内 sortingOrder）
    ///   Main 层：Cell 0 → PathArrow 10 → RangeIndicator 100 → Tower 200 → Enemy 300 → Bullet 400
    ///   塔：根 SortingGroup = 200；组内 barbette 0 / Img_gun 1 / 枪口焰 2
    ///   怪：根 SortingGroup = 300；组内血条 Bg 500 / Fill 501（必须压过美术部件，最大 99）
    ///   背景：Bg 层，序 0
    ///
    /// 【为什么怪必须大于塔】
    ///   塔防刚需：怪走到塔下方（更靠近镜头）时必须盖住塔。
    ///   塔在上会表现为"怪的头被塔底座吃掉"——2026-10-21 定案：永远怪压塔。
    /// </summary>
    public static class SortingLayerNormalizer
    {
        private const string EnemyDir = "Assets/Prefabs/Enemy";
        private const string TowerDir = "Assets/Prefabs/Tower";
        private const string TowerBackupDir = "Assets/Prefabs/Tower/_UI_Source";
        private const string BulletPath = "Assets/Prefabs/Bullet/Bullet_Normal.prefab";
        private const string MainScenePath = "Assets/Scenes/Main.unity";
        private const string BackgroundName = "Background";

        // ------------------------------------------------------------------
        // 菜单：标准化（会改资产）
        // ------------------------------------------------------------------

        /// <summary>
        /// 菜单入口：把全部敌人/塔/子弹预制体与主场景背景的排序落到约定值上。
        /// **幂等**：已经正确的资产不会被改动（内部仍会重存一次，值不变）。
        /// 不弹窗（工程规范：编辑器脚本走 Debug.Log）。
        /// </summary>
        [MenuItem("Tools/塔防/高级（单步重建）/标准化渲染层级（预置体+场景）", false, 318)]
        public static void Normalize()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                Debug.LogError("[Sorting] 请先退出 Play Mode 再执行：播放态下改预制体会在退出时被丢弃。");
                return;
            }

            var log = new StringBuilder();
            int enemies = NormalizeEnemies(log);
            int towers = NormalizeTowers(log);
            bool bullet = NormalizeBullet(log);
            bool scene = NormalizeScene(log);

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log(string.Format(
                "[Sorting] 标准化完成：敌人 {0} 个 / 塔 {1} 个 / 子弹 {2} / 场景背景 {3}\n{4}",
                enemies, towers, bullet ? "已改" : "无需改", scene ? "已改" : "无需改", log));
        }

        private static int NormalizeEnemies(StringBuilder log)
        {
            int count = 0;
            string[] paths = CollectPrefabs(EnemyDir);
            for (int i = 0; i < paths.Length; i++)
            {
                string path = paths[i];
                GameObject root = PrefabUtility.LoadPrefabContents(path);
                try
                {
                    SortingGroup group = root.GetComponent<SortingGroup>();
                    if (group == null)
                    {
                        group = root.AddComponent<SortingGroup>();
                        log.AppendLine("  + 补 SortingGroup：" + path);
                    }
                    if (group.sortingOrder != BoardSorting.Enemy || group.sortingLayerName != BoardSorting.LayerMain)
                    {
                        log.AppendLine(string.Format("  ~ {0} 组序 {1}/{2} → {3}/{4}",
                            System.IO.Path.GetFileName(path), group.sortingLayerName, group.sortingOrder,
                            BoardSorting.LayerMain, BoardSorting.Enemy));
                    }
                    group.sortingLayerName = BoardSorting.LayerMain;
                    group.sortingOrder = BoardSorting.Enemy;

                    // 组内渲染器统一到 Main（组本来就覆盖层，但显式写死便于人看与后续拆组）
                    SpriteRenderer[] renderers = root.GetComponentsInChildren<SpriteRenderer>(true);
                    for (int r = 0; r < renderers.Length; r++)
                    {
                        renderers[r].sortingLayerName = BoardSorting.LayerMain;
                    }

                    Transform bar = root.transform.Find("HpBar");
                    if (bar == null)
                    {
                        log.AppendLine("  ! 找不到 HpBar：" + path);
                    }
                    else
                    {
                        SetSpriteOrder(bar, "Bg", BoardSorting.EnemyHpBarBack);
                        SetSpriteOrder(bar, "Fill", BoardSorting.EnemyHpBarFill);
                    }

                    PrefabUtility.SaveAsPrefabAsset(root, path);
                    count++;
                }
                finally
                {
                    PrefabUtility.UnloadPrefabContents(root);
                }
            }
            return count;
        }

        private static int NormalizeTowers(StringBuilder log)
        {
            int count = 0;
            string[] paths = CollectPrefabs(TowerDir);
            for (int i = 0; i < paths.Length; i++)
            {
                string path = paths[i];
                if (path.Replace('\\', '/').StartsWith(TowerBackupDir)) continue;

                GameObject root = PrefabUtility.LoadPrefabContents(path);
                try
                {
                    SortingGroup group = root.GetComponent<SortingGroup>();
                    if (group == null)
                    {
                        group = root.AddComponent<SortingGroup>();
                        log.AppendLine("  + 补 SortingGroup：" + path);
                    }
                    group.sortingLayerName = BoardSorting.LayerMain;
                    group.sortingOrder = BoardSorting.Tower;

                    SpriteRenderer[] renderers = root.GetComponentsInChildren<SpriteRenderer>(true);
                    for (int r = 0; r < renderers.Length; r++)
                    {
                        renderers[r].sortingLayerName = BoardSorting.LayerMain;
                    }

                    // 组内相对序号：炮座在下、炮管在上（枪口焰运行时挂到 BarrelPoint，序 2）
                    Transform barbette = root.transform.Find("barbette");
                    if (barbette == null)
                    {
                        log.AppendLine("  ! 找不到 barbette：" + path);
                    }
                    else
                    {
                        SetSpriteOrder(barbette, null, BoardSorting.TowerBody);
                        SetSpriteOrder(barbette, "Img_gun", BoardSorting.TowerBarrel);
                    }

                    PrefabUtility.SaveAsPrefabAsset(root, path);
                    count++;
                }
                finally
                {
                    PrefabUtility.UnloadPrefabContents(root);
                }
            }
            return count;
        }

        private static bool NormalizeBullet(StringBuilder log)
        {
            if (AssetDatabase.LoadAssetAtPath<GameObject>(BulletPath) == null)
            {
                log.AppendLine("  ! 子弹预制体不存在：" + BulletPath);
                return false;
            }

            GameObject root = PrefabUtility.LoadPrefabContents(BulletPath);
            try
            {
                SpriteRenderer sr = root.GetComponent<SpriteRenderer>();
                if (sr == null)
                {
                    log.AppendLine("  ! 子弹根节点没有 SpriteRenderer：" + BulletPath);
                    return false;
                }
                bool changed = sr.sortingLayerName != BoardSorting.LayerMain
                               || sr.sortingOrder != BoardSorting.Bullet;
                sr.sortingLayerName = BoardSorting.LayerMain;
                sr.sortingOrder = BoardSorting.Bullet;
                if (changed) PrefabUtility.SaveAsPrefabAsset(root, BulletPath);
                return changed;
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        /// <summary>
        /// 背景改用 Bg 排序层。
        /// **不强制打开场景**：Main.unity 没打开就以 Additive 方式临时打开、改完保存再关掉，
        /// 避免把用户正在编辑的其它场景挤掉。
        /// </summary>
        private static bool NormalizeScene(StringBuilder log)
        {
            Scene scene = SceneManager.GetSceneByPath(MainScenePath);
            bool openedHere = false;
            if (!scene.IsValid() || !scene.isLoaded)
            {
                scene = EditorSceneManager.OpenScene(MainScenePath, OpenSceneMode.Additive);
                openedHere = true;
            }
            if (!scene.IsValid())
            {
                log.AppendLine("  ! 打不开主场景：" + MainScenePath);
                return false;
            }

            bool changed = false;
            try
            {
                GameObject[] roots = scene.GetRootGameObjects();
                for (int i = 0; i < roots.Length; i++)
                {
                    SpriteRenderer[] renderers = roots[i].GetComponentsInChildren<SpriteRenderer>(true);
                    for (int r = 0; r < renderers.Length; r++)
                    {
                        SpriteRenderer sr = renderers[r];
                        if (sr.gameObject.name != BackgroundName) continue;
                        if (sr.sortingLayerName == BoardSorting.LayerBg
                            && sr.sortingOrder == BoardSorting.Background) continue;
                        sr.sortingLayerName = BoardSorting.LayerBg;
                        sr.sortingOrder = BoardSorting.Background;
                        changed = true;
                        log.AppendLine("  ~ 场景背景 → " + BoardSorting.LayerBg + "/" + BoardSorting.Background);
                    }
                }
                if (changed) EditorSceneManager.SaveScene(scene);
            }
            finally
            {
                if (openedHere) EditorSceneManager.CloseScene(scene, true);
            }
            return changed;
        }

        // ------------------------------------------------------------------
        // 菜单：体检（只读）
        // ------------------------------------------------------------------

        /// <summary>
        /// 只读体检：把资产与 <see cref="BoardSorting"/> 的偏差逐条打到 Console。
        /// </summary>
        [MenuItem("Tools/塔防/校验/渲染层级体检（只读）", false, 401)]
        public static void Audit()
        {
            var problems = new StringBuilder();
            int issue = AuditFindings(problems);
            if (issue == 0) Debug.Log("[Sorting] 体检通过，无层级偏差。\n" + problems);
            else Debug.LogWarning(string.Format("[Sorting] 体检发现 {0} 处偏差：\n{1}", issue, problems));
        }

        /// <summary>
        /// 体检的核心：偏差写进 <paramref name="sb"/>，返回问题数。
        /// 同时供「校验 ▸ 渲染层级体检」与「0. 自检」调用 —— 任何重建脚本把层级冲掉，
        /// 标准自检都会报出来。只在内存里读预制体，不实例化、不保存。
        /// </summary>
        public static int AuditFindings(StringBuilder sb)
        {
            int issue = 0;

            SortingLayer[] layers = SortingLayer.layers;
            var names = new StringBuilder();
            for (int i = 0; i < layers.Length; i++)
            {
                if (i > 0) names.Append(" < ");
                names.Append(layers[i].name);
            }
            sb.AppendLine("  排序层（低 → 高）：" + names);

            if (layers.Length != 4)
            {
                sb.AppendLine(string.Format("  ! 排序层应为 4 个（Default/Bg/Main/Pop），实际 {0} 个", layers.Length));
                issue++;
            }

            // 敌人
            string[] enemies = CollectPrefabs(EnemyDir);
            int badGroup = 0, badBar = 0;
            for (int i = 0; i < enemies.Length; i++)
            {
                GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(enemies[i]);
                if (prefab == null) continue;
                SortingGroup group = prefab.GetComponent<SortingGroup>();
                if (group == null || group.sortingOrder != BoardSorting.Enemy
                    || group.sortingLayerName != BoardSorting.LayerMain)
                {
                    badGroup++;
                    if (badGroup <= 12) sb.AppendLine("  ! 组序不对：" + enemies[i] + " = " + Describe(group));
                }
                Transform bar = prefab.transform.Find("HpBar");
                if (bar == null) { badBar++; continue; }
                if (!OrderIs(bar, "Bg", BoardSorting.EnemyHpBarBack)
                    || !OrderIs(bar, "Fill", BoardSorting.EnemyHpBarFill)) badBar++;
            }
            if (badGroup > 0) issue += badGroup;
            if (badBar > 0) issue += badBar;
            sb.AppendLine(string.Format("  敌人：{0} 个，组序错 {1}，血条序错 {2}", enemies.Length, badGroup, badBar));

            // 塔
            string[] towers = CollectPrefabs(TowerDir);
            int badTower = 0, towerCount = 0;
            for (int i = 0; i < towers.Length; i++)
            {
                if (towers[i].Replace('\\', '/').StartsWith(TowerBackupDir)) continue;
                towerCount++;
                GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(towers[i]);
                if (prefab == null) continue;
                SortingGroup group = prefab.GetComponent<SortingGroup>();
                if (group == null || group.sortingOrder != BoardSorting.Tower
                    || group.sortingLayerName != BoardSorting.LayerMain)
                {
                    badTower++;
                    if (badTower <= 12) sb.AppendLine("  ! 塔组序不对：" + towers[i] + " = " + Describe(group));
                    continue;
                }
                Transform barbette = prefab.transform.Find("barbette");
                if (barbette == null || !OrderIs(barbette, null, BoardSorting.TowerBody)
                    || !OrderIs(barbette, "Img_gun", BoardSorting.TowerBarrel))
                {
                    badTower++;
                    if (badTower <= 12) sb.AppendLine("  ! 塔内序不对：" + towers[i]);
                }
            }
            if (badTower > 0) issue += badTower;
            sb.AppendLine(string.Format("  塔：{0} 个，有问题 {1}", towerCount, badTower));

            // 子弹
            GameObject bullet = AssetDatabase.LoadAssetAtPath<GameObject>(BulletPath);
            if (bullet != null)
            {
                SpriteRenderer sr = bullet.GetComponent<SpriteRenderer>();
                if (sr == null || sr.sortingOrder != BoardSorting.Bullet
                    || sr.sortingLayerName != BoardSorting.LayerMain)
                {
                    issue++;
                    sb.AppendLine("  ! 子弹层级不对：" + Describe(sr));
                }
            }

            // 场景背景（仅当 Main 已加载）
            Scene scene = SceneManager.GetSceneByPath(MainScenePath);
            if (scene.IsValid() && scene.isLoaded)
            {
                GameObject[] roots = scene.GetRootGameObjects();
                bool found = false;
                for (int i = 0; i < roots.Length; i++)
                {
                    SpriteRenderer[] rs = roots[i].GetComponentsInChildren<SpriteRenderer>(true);
                    for (int r = 0; r < rs.Length; r++)
                    {
                        if (rs[r].gameObject.name != BackgroundName) continue;
                        found = true;
                        if (rs[r].sortingLayerName != BoardSorting.LayerBg
                            || rs[r].sortingOrder != BoardSorting.Background)
                        {
                            issue++;
                            sb.AppendLine("  ! 场景背景层级不对：" + Describe(rs[r]));
                        }
                    }
                }
                if (!found) sb.AppendLine("  · 场景里没找到 Background（可能重建过场景）");
            }
            else
            {
                sb.AppendLine("  · Main.unity 未打开，跳过场景背景检查");
            }

            return issue;
        }

        // ------------------------------------------------------------------
        // 工具方法
        // ------------------------------------------------------------------

        private static string[] CollectPrefabs(string dir)
        {
            string[] guids = AssetDatabase.FindAssets("t:Prefab", new[] { dir });
            var paths = new string[guids.Length];
            for (int i = 0; i < guids.Length; i++)
            {
                paths[i] = AssetDatabase.GUIDToAssetPath(guids[i]);
            }
            return paths;
        }

        /// <summary>childName 传 null 表示 parent 自身。</summary>
        private static void SetSpriteOrder(Transform parent, string childName, int order)
        {
            Transform t = childName == null ? parent : parent.Find(childName);
            if (t == null)
            {
                Debug.LogWarning("[Sorting] 缺少节点：" + parent.name + "/" + childName);
                return;
            }
            SpriteRenderer sr = t.GetComponent<SpriteRenderer>();
            if (sr == null) return;
            sr.sortingLayerName = BoardSorting.LayerMain;
            sr.sortingOrder = order;
        }

        private static bool OrderIs(Transform parent, string childName, int order)
        {
            Transform t = childName == null ? parent : parent.Find(childName);
            if (t == null) return false;
            SpriteRenderer sr = t.GetComponent<SpriteRenderer>();
            return sr != null && sr.sortingOrder == order;
        }

        private static string Describe(SortingGroup g)
        {
            return g == null ? "无 SortingGroup" : g.sortingLayerName + "/" + g.sortingOrder;
        }

        private static string Describe(SpriteRenderer sr)
        {
            return sr == null ? "无 SpriteRenderer" : sr.sortingLayerName + "/" + sr.sortingOrder;
        }
    }
}

using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 把防御塔预制体从 **UGUI** 转成 **世界空间 SpriteRenderer**（P0-4 / M-2）。
    ///
    /// 【为什么要转】
    ///   原工程：塔是 UGUI（RectTransform + Image，Layer 5），怪物是 SpriteRenderer。
    ///   两套渲染体系混用会导致三个硬伤：
    ///     ① 塔和怪无法按 Y 坐标互相遮挡（塔防的刚需：怪走到塔下方应盖住塔）
    ///     ② 坐标要维护"UI 局部坐标"与"世界坐标"双轨，任何换算都会成为 bug 温床
    ///     ③ 点击/拖拽交互要写两套实现
    ///   而 119 个怪物 prefab 是分部件骨骼式结构，转 UGUI 成本高且无收益；
    ///   塔只有少量 prefab，转 SpriteRenderer 成本低。故统一到 SpriteRenderer。
    ///
    /// 【M-2 改进（相对 M0 版）】
    ///   1. 覆盖全部塔型（Normal / Power / Retard），不再只处理 Tower_Normal
    ///   2. **已合规的塔直接跳过**：检测根节点是否已是 SpriteRenderer 结构 → 是则不改
    ///   3. **备份只做一次**：原来每个塔都尝试备份，现在统一在开头扫一遍，已有的跳过
    ///
    /// 【产物层级】（BaseTower 依赖的名字，不能改）
    ///   Tower_<Type>                     根，挂 <Type>Tower + SortingGroup(序 200, Main 层)，scale 0.8
    ///   └── barbette                     炮座（SpriteRenderer, 组内序 0）
    ///       └── Img_gun                  炮管（SpriteRenderer, 组内序 1）
    ///           └── BarrelPoint          出膛点（BaseTower 取它作为子弹出生位置）
    ///
    /// 【为什么要有 SortingGroup】
    ///   组序 200 把整座塔当成一个排序单位，组内 0/1 只决定炮座与炮管的相对前后。
    ///   没有组时炮管的 301 会越过别的塔的 300（全局序号），远处塔的炮管会压住近处塔的炮座。
    ///   2026-10-21 起塔的组序是 200（小于怪的 300）——**永远怪压塔**，不允许塔盖住怪。
    ///
    /// 【原 UGUI 版会先备份】到 Assets/Prefabs/Tower/_UI_Source/，便于回退对照。
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建） ▸ 转换防御塔预制体
    /// </summary>
    public static class TowerPrefabConverter
    {
        private const string TowerDir = "Assets/Prefabs/Tower";
        private const string BackupDir = "Assets/Prefabs/Tower/_UI_Source";

        /// <summary>
        /// 全部塔等级 prefab 的逻辑名（= ResTable 逻辑名 = prefab 文件名）。
        ///
        /// 【M-3 起改为分等级清单】三种塔各 3 个独立 prefab，一级一套美术：
        ///   Normal0|1|2（turret[_mkii|_mkiii]_base|barrel_128）、Power0|1|2、Retard0|1|2。
        /// 这些名字必须与 tbtowerinfo.json 的 resName 逐行一致，自检失败即表示两边分叉。
        /// </summary>
        public static readonly string[] TowerResNames =
        {
            "Tower_Normal0", "Tower_Normal1", "Tower_Normal2",
            "Tower_Power0", "Tower_Power1", "Tower_Power2",
            "Tower_Retard0", "Tower_Retard1", "Tower_Retard2",
        };

        /// <summary>
        /// 按逻辑名取塔 prefab 资产路径（供自检等外部调用，勿再写死单塔常量）。
        /// 分等级 prefab 放在与其塔型同名的子目录下（Normal / Power / Retard）。
        /// </summary>
        public static string TowerPath(string resName)
        {
            if (resName.StartsWith("Tower_Normal"))
            {
                return TowerDir + "/Normal/" + resName + ".prefab";
            }
            if (resName.StartsWith("Tower_Power"))
            {
                return TowerDir + "/Power/" + resName + ".prefab";
            }
            if (resName.StartsWith("Tower_Retard"))
            {
                return TowerDir + "/Retard/" + resName + ".prefab";
            }
            return TowerDir + "/" + resName + ".prefab";
        }

        /// <summary>塔根节点缩放：128px 贴图 = 1.28 世界单位，0.8 后约 1.02，正好一格</summary>
        private const float RootScale = 0.8f;

        /// <summary>炮管出膛点相对炮管中心的距离（炮管本地单位）</summary>
        private const float MuzzleOffset = 0.6f;

        /// <summary>
        /// 单座塔的生成规格。
        /// ResName 既作 prefab 文件名，也作 ResTable 逻辑名（M-2 起三塔统一命名）。
        /// 【贴图名不统一】三座塔的美术文件名各不相同，必须逐塔指定，不能靠拼字符串：
        ///   Normal: turret_base|barrel_128.png / turret_mkii_*_128.png / turret_mkiii_*_128.png
        ///   Power : tower_base[_lv2|_lv3].png      / tower_barrel[_lv2|_lv3].png
        ///   Retard: slowtower_base[_lv2|_lv3].png  / slowtower_crystal[_lv2|_lv3].png
        ///           （目录名是小写 retard，且美术已按等级提供 3 套）
        /// </summary>
        private struct TowerSpec
        {
            public string ResName;         // Tower_Normal / Tower_Power0..2 / Tower_Retard0..2
            public string ArtDir;          // 美术目录（注意 retard 是小写）
            public string BaseSprite;      // 炮座贴图文件名
            public string BarrelSprite;    // 炮管贴图文件名
            public string RootName;        // 根节点名（= ResName）
            /// <summary>根组件类型（NormalTower / PowerTower / RetardTower）</summary>
            public System.Type Behaviour;
        }

        private static TowerSpec[] Specs()
        {
            return new TowerSpec[]
            {
                // ---- 普通塔：3 个等级各有独立 prefab 与美术（M-3 起同 Power/Retard 口径）----
                new TowerSpec
                {
                    ResName = "Tower_Normal0", ArtDir = "Normal",
                    BaseSprite = "turret_base_128.png", BarrelSprite = "turret_barrel_128.png",
                    RootName = "Tower_Normal0", Behaviour = typeof(NormalTower),
                },
                new TowerSpec
                {
                    ResName = "Tower_Normal1", ArtDir = "Normal",
                    BaseSprite = "turret_mkii_base_128.png", BarrelSprite = "turret_mkii_barrel_128.png",
                    RootName = "Tower_Normal1", Behaviour = typeof(NormalTower),
                },
                new TowerSpec
                {
                    ResName = "Tower_Normal2", ArtDir = "Normal",
                    BaseSprite = "turret_mkiii_base_128.png", BarrelSprite = "turret_mkiii_barrel_128.png",
                    RootName = "Tower_Normal2", Behaviour = typeof(NormalTower),
                },
                // ---- 强力塔：3 个等级各有独立 prefab 与美术 ----
                new TowerSpec
                {
                    ResName = "Tower_Power0", ArtDir = "Power",
                    BaseSprite = "tower_base.png", BarrelSprite = "tower_barrel.png",
                    RootName = "Tower_Power0", Behaviour = typeof(PowerTower),
                },
                new TowerSpec
                {
                    ResName = "Tower_Power1", ArtDir = "Power",
                    BaseSprite = "tower_base_lv2.png", BarrelSprite = "tower_barrel_lv2.png",
                    RootName = "Tower_Power1", Behaviour = typeof(PowerTower),
                },
                new TowerSpec
                {
                    ResName = "Tower_Power2", ArtDir = "Power",
                    BaseSprite = "tower_base_lv3.png", BarrelSprite = "tower_barrel_lv3.png",
                    RootName = "Tower_Power2", Behaviour = typeof(PowerTower),
                },
                // ---- 减速塔：同上 ----
                new TowerSpec
                {
                    ResName = "Tower_Retard0", ArtDir = "retard",
                    BaseSprite = "slowtower_base.png", BarrelSprite = "slowtower_crystal.png",
                    RootName = "Tower_Retard0", Behaviour = typeof(RetardTower),
                },
                new TowerSpec
                {
                    ResName = "Tower_Retard1", ArtDir = "retard",
                    BaseSprite = "slowtower_base_lv2.png", BarrelSprite = "slowtower_crystal_lv2.png",
                    RootName = "Tower_Retard1", Behaviour = typeof(RetardTower),
                },
                new TowerSpec
                {
                    ResName = "Tower_Retard2", ArtDir = "retard",
                    BaseSprite = "slowtower_base_lv3.png", BarrelSprite = "slowtower_crystal_lv3.png",
                    RootName = "Tower_Retard2", Behaviour = typeof(RetardTower),
                },
            };
        }

        [MenuItem("Tools/塔防/高级（单步重建）/转换防御塔预制体", false, 301)]
        public static void Convert()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            bool ok = ConvertInternal(report);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log(ok
                ? "[M2] 防御塔转换完成：\n" + report.Text
                : "[M2] 防御塔转换有错误：\n" + report.Text);
        }

        /// <summary>供一键向导调用（不弹窗）</summary>
        public static bool ConvertInternal(EditorUtil.Report report)
        {
            report.Head("转换防御塔预制体（全部塔型）");

            TowerSpec[] specs = Specs();
            int converted = 0;
            int skipped = 0;
            bool allOk = true;

            for (int i = 0; i < specs.Length; i++)
            {
                TowerSpec spec = specs[i];
                string targetPath = TowerPath(spec.ResName);

                // 已合规 → 跳过（★ 不删不建，保住美术/手工调过的内容）
                if (IsAlreadyConverted(targetPath))
                {
                    report.Ok("跳过（已是 SpriteRenderer 结构）：" + spec.ResName);
                    skipped++;
                    continue;
                }

                if (!ConvertOne(spec, targetPath, report))
                {
                    allOk = false;
                    continue;
                }
                converted++;
            }

            report.Ok(string.Format("完成：新转换 {0} 座，跳过 {1} 座", converted, skipped));
            return allOk;
        }

        /// <summary>
        /// 判定某塔 prefab 是否已经是"世界空间 SpriteRenderer 版"。
        /// 依据：根下存在 barbette，且 barbette 上挂着 SpriteRenderer。
        /// 满足即认为已经转换过 —— 不重复重建（保住手工改动）。
        ///
        /// 【为什么不再校验根组件的子类】实测 Tower_Power0/1/2、Tower_Retard0/1/2 挂的都是 NormalTower，
        /// 但三个子类都是 BaseTower 的空派生，功能上完全等价（差异全在配置表驱动）。
        /// 为这点"类名一致性"去重建 prefab，反而会抹掉美术/手工微调 —— 不划算，改为只提示。
        /// </summary>
        private static bool IsAlreadyConverted(string prefabPath)
        {
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            if (prefab == null)
            {
                return false;
            }
            Transform barbette = prefab.transform.Find("barbette");
            if (barbette == null)
            {
                return false;
            }
            return barbette.GetComponent<SpriteRenderer>() != null;
        }

        private static bool ConvertOne(TowerSpec spec, string targetPath, EditorUtil.Report report)
        {
            report.Head("转换 → " + targetPath);

            if (AssetDatabase.LoadAssetAtPath<GameObject>(targetPath) == null)
            {
                report.Error("找不到源预制体：" + targetPath);
                return false;
            }

            string baseSpritePath = "Assets/_UIAssets/Tower/" + spec.ArtDir + "/" + spec.BaseSprite;
            string barrelSpritePath = "Assets/_UIAssets/Tower/" + spec.ArtDir + "/" + spec.BarrelSprite;
            Sprite baseSprite = AssetDatabase.LoadAssetAtPath<Sprite>(baseSpritePath);
            Sprite barrelSprite = AssetDatabase.LoadAssetAtPath<Sprite>(barrelSpritePath);
            if (baseSprite == null || barrelSprite == null)
            {
                report.Error(string.Format(
                    "{0} 塔身贴图缺失或未被导入为 Sprite：\n    base={1}\n    barrel={2}",
                    spec.ResName, baseSpritePath, barrelSpritePath));
                return false;
            }

            BackupSource(spec.ResName, targetPath, report);

            // ---- 先删旧资产再重建，避免残留子节点 ----
            AssetDatabase.DeleteAsset(targetPath);
            EditorUtil.EnsureFolderOfFile(targetPath);

            GameObject root = new GameObject(spec.RootName);
            root.transform.localScale = new Vector3(RootScale, RootScale, 1f);
            // 整座塔作为一个排序单位（组序 200 < 怪的 300 → 永远怪压塔）
            SortingGroup group = root.AddComponent<SortingGroup>();
            group.sortingLayerName = BoardSorting.LayerMain;
            group.sortingOrder = BoardSorting.Tower;

            GameObject barbette = new GameObject("barbette");
            barbette.transform.SetParent(root.transform, false);
            AddSprite(barbette, baseSprite, BoardSorting.TowerBody);

            // 炮管挂在炮座下：炮座不动，炮管绕自身 pivot 旋转（美术把 pivot 定在炮管旋转中心）
            GameObject gun = new GameObject("Img_gun");
            gun.transform.SetParent(barbette.transform, false);
            AddSprite(gun, barrelSprite, BoardSorting.TowerBarrel);

            // 出膛点：必须在炮管贴图**原生指向**的那一端。
            // 【为什么是 +Y 而不是 +X】炮管贴图（turret_barrel_128.png）是**竖着画**的：
            //   上窄下宽、枪口在图像顶部 ⇒ 本地 +Y 方向。之前放在 (+MuzzleOffset, 0)
            //   是按"炮管朝 +X"的假设写的，结果子弹从炮管侧面冒出来，
            //   与炮管指向差了 90°（和 BaseTower.BarrelNativeAngle 是同一件事的两面）。
            // 炮管旋转时 BarrelPoint 作为子节点跟着转，所以这里只要放对本地位置即可。
            GameObject muzzle = new GameObject("BarrelPoint");
            muzzle.transform.SetParent(gun.transform, false);
            muzzle.transform.localPosition = new Vector3(0f, MuzzleOffset, 0f);

            if (spec.Behaviour != null)
            {
                root.AddComponent(spec.Behaviour);
            }

            GameObject saved = PrefabUtility.SaveAsPrefabAsset(root, targetPath);
            Object.DestroyImmediate(root);

            if (saved == null)
            {
                report.Error("保存预制体失败：" + targetPath);
                return false;
            }

            report.Ok(spec.ResName + " 已生成世界空间版（根 scale " + RootScale +
                      "，SortingGroup 200 / barbette 0 / Img_gun 1）");

            Bounds b;
            if (EditorUtil.TryMeasureBounds(saved, out b))
            {
                report.Ok(string.Format("{0} 实测显示尺寸：宽 {1:F2} × 高 {2:F2} 世界单位（格子 1.0）",
                    spec.ResName, b.size.x, b.size.y));
            }
            return true;
        }

        /// <summary>把原 UGUI 版另存一份，便于回退与对照。已备份过则跳过。</summary>
        private static void BackupSource(string resName, string targetPath, EditorUtil.Report report)
        {
            string backupPath = BackupDir + "/" + resName + "_UI.prefab";
            if (AssetDatabase.LoadAssetAtPath<GameObject>(backupPath) != null)
            {
                report.Ok("原 UGUI 版备份已存在，跳过：" + backupPath);
                return;
            }
            if (!AssetDatabase.CopyAsset(targetPath, backupPath))
            {
                report.Warn("原 UGUI 版备份失败（不影响转换）：" + backupPath);
                return;
            }
            report.Ok("原 UGUI 版已备份到 " + backupPath);
        }

        private static void AddSprite(GameObject go, Sprite sprite, int sortingOrder)
        {
            SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
            sr.sprite = sprite;
            sr.sortingLayerName = BoardSorting.LayerMain;
            sr.sortingOrder = sortingOrder;
            sr.color = Color.white;
        }
    }
}

