        private static void ApplySlicedSkin(Image img, string spriteName, Color fallbackColor)
        {
            Sprite sp = LoadUiSprite(spriteName);
            if (sp != null)
            {
                img.sprite = sp;
                img.type = Image.Type.Sliced;
                img.color = Color.white;
            }
            else
            {
                img.color = fallbackColor;
            }
        }

