        private static void BuildHud(EditorUtil.Report report)
        {
            report.Head("生成 HUD → " + HudPath);

            // ★ 安全护栏：prefab 里若有生成器不认识的节点，说明有人手工改过，中止而不是抹掉
            string extra;
            if (!EditorUtil.IsSafeToRebuild(HudPath, HudChildren, out extra))
            {
                report.Error("HudView.prefab 检测到生成器不识别的节点：" + extra +
                             "　→ 已中止，未做任何修改。请把手工节点纳入 HudChildren 或手工维护该 prefab。");
                return;
            }

            DeleteUiPrefab(HudPath);
            EditorUtil.EnsureFolderOfFile(HudPath);

            GameObject root = new GameObject("HudView", typeof(RectTransform));
            Stretch((RectTransform)root.transform);
            root.AddComponent<HudView>();

            // 芯片底（先建，保证在文本之下）：金币 / 生命 / 回合
            // ★ create 返回芯片底的 Transform，文本挂到它下面（层级见类注释）。
            //   Bg_Round 加宽到 580：回合文案会出现「第 N 波 · 进行中」这种长句，320 装不下。
            Transform goldChip = CreateChip(root.transform, "Bg_Gold", new Vector2(0f, 1f), new Vector2(40f, -30f),
                new Vector2(268f, 52f), "UI_Chip_Gold");
            Transform hpChip = CreateChip(root.transform, "Bg_Hp", new Vector2(0f, 1f), new Vector2(40f, -84f),
                new Vector2(268f, 52f), "UI_Chip_HP");
            Transform roundChip = CreateChip(root.transform, "Bg_Round", new Vector2(0.5f, 1f), new Vector2(0f, -30f),
                new Vector2(580f, 56f), "UI_Chip_Neutral");

            // 文本内嵌在芯片底之下：全拉伸锚点铺满芯片，不再单独定位/定尺寸
            // （芯片挪位置，文本自然跟随；也不会因分辨率变化而漂移）
            // ★ 2026-10-15 手工版口径：三个芯片文本统一**居中对齐 + 开自动字号**
            //   （Gold/Hp 原为左对齐；中英日文案长度差异大，靠自动字号在 18~72 内收放）。
            SetAutoSize(CreateChipText(goldChip, "GoldText", "Gold 0", TextAnchor.MiddleCenter, SmallFontSize));
            SetAutoSize(CreateChipText(hpChip, "HpText", "HP 0/0", TextAnchor.MiddleCenter, SmallFontSize));
            SetAutoSize(CreateChipText(roundChip, "RoundText", "In Progress", TextAnchor.MiddleCenter, BigFontSize));

            // 底部：三颗塔按钮 + 倍速 + 开始
            for (int i = 0; i < TowerButtons.Length; i++)
            {
                CreateTowerButton(root.transform, TowerButtons[i]);
            }
            // 左=倍速（工具类，次要）、右=开始（主 CTA）—— 与"原设计里 倍速在左、开始在右"一致。
            // 2026-10-16 多分辨率适配：改"贴屏幕左侧/右侧边缘"锚定（见 SideBtnEdgeX/Y 注释）。
            CreateButton(root.transform, "SpeedButton", "×1", new Vector2(0f, 0f), new Vector2(SideBtnEdgeX, SideBtnEdgeY));
            CreateButton(root.transform, "StartButton", "Start", new Vector2(1f, 0f), new Vector2(-SideBtnEdgeX, SideBtnEdgeY), true);

            // 右上角：暂停开关 / 暂停菜单（2026-10-14；2026-10-18 职责重划）
            //   Btn_Pause = 暂停/继续开关（不弹窗）；Btn_Intro = 打开展停菜单（不暂停）
            CreateHudCornerButton(root.transform, "Btn_Pause", "Pause", HudPausePos, HudCornerBtnSize);
            CreateHudCornerButton(root.transform, "Btn_Intro", "Menu", HudIntroPos, HudCornerBtnSize);

            GameObject saved = SaveUiPrefab(root, HudPath);
            Object.DestroyImmediate(root);

            if (saved == null)
            {
                report.Error("保存失败：" + HudPath);
                return;
            }
            report.Ok("HudView.prefab（Bg_Gold+GoldText / Bg_Hp+HpText / Bg_Round+RoundText / " +
                      "Btn_Tower_Normal·Power·Retard / StartButton / SpeedButton / Btn_Pause / Btn_Intro）");
        }

        /// <summary>HUD 上的"芯片底"（金币/生命/回合），不吃点击。返回其 Transform 供挂子文本。</summary>
        private static Transform CreateChip(Transform parent, string name, Vector2 anchor, Vector2 anchoredPos,
            Vector2 size, string spriteName)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);
            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = anchor;
            rt.anchorMax = anchor;
            rt.pivot = new Vector2(anchor.x, anchor.y);
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = size;
            Image img = go.AddComponent<Image>();
            img.raycastTarget = false;
            ApplySlicedSkin(img, spriteName, new Color(0.12f, 0.16f, 0.24f, 0.85f));
            return go.transform;
        }

        // ---- HUD 右上角工具按钮（暂停 / 游戏介绍，2026-10-14）----
        // 锚点 = 画布右上角 (1,1)、轴心 (1,1)，anchoredPosition 取负值向内缩。
        // 右边距 40 与左上角三颗芯片的左边距 40 对齐；两颗上下排、间距 14。
        private static readonly Vector2 HudCornerBtnSize = new Vector2(180f, 56f);
        private static readonly Vector2 HudPausePos = new Vector2(-40f, -30f);
        private static readonly Vector2 HudIntroPos = new Vector2(-40f, -100f);

        /// <summary>
        /// 芯片底内嵌的文本：**全拉伸铺满父芯片**，不单独定位。
        ///
        /// 【为什么和 CreateText 分开】CreateText 用"以锚点为准的定位 + 固定 size"，
        ///   适合自由摆放；芯片文本必须严丝合缝地填满芯片（且芯片一动就跟着动），
        ///   用固定 pos/size 反而会漂。所以这里单开一个"填满父节点"的版本。
        /// </summary>
        private static TextMeshProUGUI CreateChipText(Transform chip, string name, string content,
            TextAnchor align, int fontSize)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(chip, false);

            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = Vector2.zero;
            rt.sizeDelta = Vector2.zero;

            TextMeshProUGUI t = go.AddComponent<TextMeshProUGUI>();
            TMP_FontAsset font = EditorUtil.GetDefaultTmpFont();
            if (font != null)
            {
                t.font = font;
            }
            t.text = content;
            t.fontSize = fontSize;
            t.alignment = ToTmpAlignment(align);
            t.color = TextColor;
            t.raycastTarget = false;
            Material outlineMat = GetOrCreateOutlineMaterial(font);
            if (outlineMat != null)
            {
                t.fontSharedMaterial = outlineMat;
            }
            t.enableWordWrapping = false;
            t.overflowMode = TextOverflowModes.Overflow;
            return t;
        }

        /// <summary>
        /// 打开 TMP 自动字号（手工版 2026-10-15 定下的排版口径）。
        /// 【为什么】中 / 英 / 日文案长度差别很大：固定字号下长文案溢出、短文案留白；
        ///   开自动字号后由 TMP 在 [fontSizeMin, fontSizeMax] 内自行收放。
        ///   落盘到 prefab 的 m_fontSize 只是"当下算出来的那个值"（会带小数），
        ///   生成器只需把"开"与区间写对，具体数值由 TMP 重算。
        /// </summary>
        private static void SetAutoSize(TextMeshProUGUI t, float min = 18f, float max = 72f)
        {
            t.enableAutoSizing = true;
            t.fontSizeMin = min;
            t.fontSizeMax = max;
        }

        /// <summary>
        /// 生成一个文本节点，锚点可分别指定 min/max（用于"四边拉伸"或"横向拉伸"等自适应框）。
        /// 与 <see cref="CreateText"/> 的区别：后者锚点 min==max（定尺寸框），本方法可以给
        /// 出 min≠max 的拉伸框（如 anchorMin=(0,0.5) / anchorMax=(1,0.5) 横向跟随父级宽度）。
        /// 【为什么单独加】手工版对 TipText / BodyTitle / SellTitle 等用了"拉伸框"口径，
        ///   通用 CreateText 表达不了，硬凑会在下次重生成时被冲回定尺寸框。
        /// </summary>
        private static TextMeshProUGUI CreateTextStretched(Transform parent, string name, string content,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 anchoredPos, Vector2 size,
            TextAnchor align, int fontSize)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = size;

            TextMeshProUGUI t = go.AddComponent<TextMeshProUGUI>();
            TMP_FontAsset font = EditorUtil.GetDefaultTmpFont();
            if (font != null)
            {
                t.font = font;
            }
            t.text = content;
            t.fontSize = fontSize;
            t.alignment = ToTmpAlignment(align);
            t.color = TextColor;
            t.raycastTarget = false;
            Material outlineMat = GetOrCreateOutlineMaterial(font);
            if (outlineMat != null)
            {
                t.fontSharedMaterial = outlineMat;
            }
            t.enableWordWrapping = false;
            t.overflowMode = TextOverflowModes.Overflow;
            return t;
        }

        private static void BuildTips(EditorUtil.Report report)
        {
            report.Head("生成提示层 → " + TipsPath);

            DeleteUiPrefab(TipsPath);
            EditorUtil.EnsureFolderOfFile(TipsPath);

            GameObject root = new GameObject("TipsView", typeof(RectTransform));
            Stretch((RectTransform)root.transform);
            CanvasGroup cg = root.AddComponent<CanvasGroup>();
            cg.alpha = 1f;              // 保留当前资源的预览状态；运行时由 TipsView 管理显隐
            cg.blocksRaycasts = false;
            cg.interactable = false;
            root.AddComponent<TipsView>();

            // 提示条跟随安全区顶部；与现有资源一致，避免重建恢复成屏幕居中。
            GameObject bar = new GameObject("TipBar", typeof(RectTransform));
            bar.transform.SetParent(root.transform, false);
            RectTransform brt = (RectTransform)bar.transform;
            brt.anchorMin = new Vector2(0.5f, 1f);
            brt.anchorMax = new Vector2(0.5f, 1f);
            brt.pivot = new Vector2(0.5f, 0.5f);
            brt.anchoredPosition = new Vector2(0f, -263f);
            brt.sizeDelta = new Vector2(1160f, 84f);
            Image barImg = bar.AddComponent<Image>();
            barImg.raycastTarget = false;
            ApplySlicedSkin(barImg, "UI_Tip_Bar", new Color(0.06f, 0.09f, 0.13f, 0.72f));

            // ★ 2026-10-15 手工版微调：TipText 由「root 直挂 + 横向拉伸（高 100、中心略高）」改为
            //   **挂到 TipBar 之下并四边拉伸**（锚点 0,0/1,1、位置 0、尺寸 0）——
            //   于是文字恒随提示条居中/位移，条与文字不再各自定位。改层级必须与 TipsView.cs 的
            //   Find 路径成对改（现为 "TipBar/TipText"）。
            TextMeshProUGUI tip = CreateTextStretched(bar.transform, "TipText", string.Empty,
