            GameObject root = CreateDialogShell("GameIntroView", "Game Intro",
                new Vector2(980f, 660f), report, out panel);
            root.AddComponent<GameIntroView>();

            // 正文四行：等间距纵排，开自动换行（中文文案 20~30 字，860 宽 30 号够一行，超了折行）
