                report.Error("保存失败：" + SettingPath);
                return;
            }
            report.Ok("SettingView.prefab（Bg / Panel( Title / VolumeText / VolumeSlider / LanguageText / LanguageDropdown / MuteBtn / ResetBtn / CloseBtn )）");
        }

        // ------------------------------------------------------------------
        // 关卡结算弹窗（通关 / 失败）
        //
        // 【节点契约】与 Assets/Scripts/UI/LevelClearView.cs 的 FindText/FindButton 一一对应，
        //   改这里必须同步改那里（两边都写死了节点名，没有中间映射层）。
        // ------------------------------------------------------------------

        private static void BuildLevelClear(EditorUtil.Report report)
        {
            report.Head("生成关卡结算界面 → " + LevelClearPath);
            if (SyncExistingRatingView(LevelClearPath, false, report)) return;
            string extra;
            if (!EditorUtil.IsSafeToRebuild(LevelClearPath, LevelClearChildren, out extra))
            {
                report.Error("LevelClearView.prefab 检测到生成器不识别的节点：" + extra + "　→ 已中止");
                return;
            }
            DeleteUiPrefab(LevelClearPath);
            EditorUtil.EnsureFolderOfFile(LevelClearPath);

            GameObject panel;
            GameObject root = CreateDialogShell("LevelClearView", "Level Clear!",
                new Vector2(1040f, 980f), report, out panel, -1f, new Vector2(900f, 56f));
            root.AddComponent<LevelClearView>();

            CreateText(panel.transform, "LevelName", "Level 1",
                new Vector2(0.5f, 0.5f), new Vector2(0f, 380f), new Vector2(900f, 48f),
                TextAnchor.MiddleCenter, SmallFontSize);

            // 本次星级是弹窗的主角，字号明显大于其它文本
            CreateText(panel.transform, "Stars", "☆☆☆☆☆",
                new Vector2(0.5f, 0.5f), new Vector2(0f, 298f), new Vector2(900f, 86f),
                TextAnchor.MiddleCenter, StarFontSize);

            // 「本次」与「历史最高」并排 —— 存档里的星级是只升不降的合并值，
            // 不分开显示的话，二次通关打出低分反而会看到高分。
            CreateText(panel.transform, "StarDetail", "This ☆☆☆☆☆　　Best ☆☆☆☆☆",
                new Vector2(0.5f, 0.5f), new Vector2(0f, 220f), new Vector2(900f, 44f),
                TextAnchor.MiddleCenter, SmallFontSize);

            // 新纪录提示：默认隐藏，由 LevelClearView.Show 依据数据决定是否点亮
            TextMeshProUGUI recordTip = CreateText(panel.transform, "RecordTip",
                "★ New Record! Best stars improved",
                new Vector2(0.5f, 0.5f), new Vector2(0f, 170f), new Vector2(900f, 32f),
                TextAnchor.MiddleCenter, SmallFontSize);
            recordTip.gameObject.SetActive(false);

            CreateText(panel.transform, "Stats", "HP 0/0　　Kills 0　　Leaks 0",
                new Vector2(0.5f, 0.5f), new Vector2(0f, 118f), new Vector2(900f, 44f),
                TextAnchor.MiddleCenter, SmallFontSize);

            CreateText(panel.transform, "RatingContext", string.Empty,
                new Vector2(0.5f, 0.5f), new Vector2(0f, 60f), new Vector2(900f, 60f), TextAnchor.MiddleCenter, 24);
            CreateText(panel.transform, "RatingTimes", string.Empty,
                new Vector2(0.5f, 0.5f), new Vector2(0f, 0f), new Vector2(900f, 54f), TextAnchor.MiddleCenter, 24);
            CreateText(panel.transform, "RatingReasons", string.Empty,
                new Vector2(0.5f, 0.5f), new Vector2(0f, -120f), new Vector2(900f, 154f), TextAnchor.MiddleCenter, 24);

            // 按钮加宽到 420：Label 文案含关卡名（"下一关：雪原前哨"），
            // 而 CreateText 关掉了自动换行，320 宽会溢出到面板外。其余两枚回 320（规范口径）。
            CreatePanelButton(panel.transform, "NextBtn", "Next Level", new Vector2(0f, -255f), 560f, true);
            CreatePanelButton(panel.transform, "RetryBtn", "Replay", new Vector2(0f, -335f), 420f);
            CreatePanelButton(panel.transform, "SelectBtn", "Back to Levels", new Vector2(0f, -415f), 420f);

            ConfigureRatingText(panel.transform.Find("RatingContext"), 24);
            ConfigureRatingText(panel.transform.Find("RatingTimes"), 24);
            ConfigureRatingText(panel.transform.Find("RatingReasons"), 24);

            GameObject saved = SaveUiPrefab(root, LevelClearPath);
            Object.DestroyImmediate(root);
            if (saved == null)
            {
                report.Error("保存失败：" + LevelClearPath);
                return;
            }
            report.Ok("LevelClearView.prefab（Bg / Panel( Title / LevelName / Stars / StarDetail / RecordTip / Stats / NextBtn / RetryBtn / SelectBtn )）");
        }

        /// <summary>
        /// 面板内按钮：居中锚点、固定尺寸，带 Label 子节点。
        /// <paramref name="width"/> 默认 320；结算界面要放"下一关：关卡名"这类较长文案，
        /// 会显式传更宽的值（TMP 此处关掉了自动换行，宽度不够会直接溢出到面板外）。
        /// <paramref name="height"/> / <paramref name="fontSize"/> 默认是"标准按钮"口径（72 高 / 32 号），
        /// 关卡选择的左右翻页箭头会传更高、更大的值（132×160、72 号）。
        /// </summary>
        /// <summary>
        /// 面板内按钮（默认 320×72，画布中心锚）。
        /// 2026-10-16：可选 anchor/pivot 参数支持"边缘锚定"（贴屏幕左/右/底边的箭头与关闭钮）；
        ///   不传时行为与旧版完全一致（中心锚 (0.5,0.5)）。
        /// </summary>
        private static void CreatePanelButton(Transform parent, string name, string label, Vector2 anchoredPos,
            float width = 320f, bool primary = false, float height = 72f, int fontSize = 0,
            Vector2? anchor = null, Vector2? pivot = null)
        {
            if (fontSize <= 0)
            {
                fontSize = SmallFontSize;
            }

            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            Vector2 a = anchor ?? new Vector2(0.5f, 0.5f);
            rt.anchorMin = a;
            rt.anchorMax = a;
            rt.pivot = pivot ?? new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = new Vector2(width, height);

            Image img = go.AddComponent<Image>();
            ApplySlicedSkin(img, primary ? "UI_Btn_Primary" : "UI_Btn_Secondary", ButtonColor);

            Button btn = go.AddComponent<Button>();
            btn.targetGraphic = img;
            ColorBlock cb = btn.colors;
            cb.normalColor = Color.white;
            cb.highlightedColor = new Color(1.15f, 1.15f, 1.15f, 1f);
            cb.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);
            cb.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.6f);
            btn.colors = cb;

            TextMeshProUGUI t = CreateText(go.transform, "Label", label,
                new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(width, height),
                TextAnchor.MiddleCenter, fontSize);
            RectTransform lrt = (RectTransform)t.transform;
            lrt.anchorMin = Vector2.zero;
            lrt.anchorMax = Vector2.one;
            lrt.pivot = new Vector2(0.5f, 0.5f);
            lrt.anchoredPosition = Vector2.zero;
            lrt.sizeDelta = Vector2.zero;
        }

        /// <summary>
        /// 生成一个可直接使用的 uGUI Slider（对应 SettingView 的 Panel/VolumeSlider）。
        /// 结构与 Unity 内置 DefaultControls.CreateSlider 一致：
        /// Background / Fill Area→Fill / Handle Slide Area→Handle，
        /// 皮肤走工程自带 sprite（ApplySlicedSkin），缺失时用纯色兜底。
        /// </summary>
        private static void CreateSlider(Transform parent, string name, Vector2 anchoredPos,
            Vector2 size, float value)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = new Vector2(0.5f, 0.5f);
            rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = size;

            // 背景：整条轨道（必须可接收射线 —— Slider 根节点没有 Graphic，拖拽事件靠它命中）
            Image trackBg = CreateSliderLeaf(go.transform, "Background",
                new Vector2(0f, 0.25f), new Vector2(1f, 0.75f), Vector2.zero, Vector2.zero,
                img => ApplySlicedSkin(img, "UI_Btn_Secondary", new Color(0.25f, 0.25f, 0.28f, 1f)));
            trackBg.raycastTarget = true;

            // 已填充部分：Fill Area → Fill
            Image fill = CreateSliderLeaf(go.transform, "Fill Area",
                new Vector2(0f, 0.25f), new Vector2(1f, 0.75f), new Vector2(7f, 0f), new Vector2(-7f, 0f),
                img => ApplySlicedSkin(img, "UI_Btn_Primary", new Color(0.35f, 0.65f, 0.45f, 1f)),
                "Fill");
            fill.rectTransform.anchorMin = new Vector2(0f, 0f);
            fill.rectTransform.anchorMax = new Vector2(0f, 1f);
            fill.rectTransform.offsetMin = Vector2.zero;
            fill.rectTransform.offsetMax = Vector2.zero;

            // 滑块：Handle Slide Area → Handle（宽度 24，高度撑满）
            Image handle = CreateSliderLeaf(go.transform, "Handle Slide Area",
                new Vector2(0f, 0.25f), new Vector2(1f, 0.75f), new Vector2(10f, 0f), new Vector2(-10f, 0f),
                img => ApplySlicedSkin(img, "UI_Btn_Primary", new Color(0.92f, 0.92f, 0.92f, 1f)),
                "Handle");
            handle.rectTransform.anchorMin = new Vector2(0f, 0f);
            handle.rectTransform.anchorMax = new Vector2(0f, 1f);
            handle.rectTransform.sizeDelta = new Vector2(24f, 0f);

            Slider slider = go.AddComponent<Slider>();
            slider.fillRect = fill.rectTransform;
            slider.handleRect = handle.rectTransform;
            slider.targetGraphic = handle;
            slider.direction = Slider.Direction.LeftToRight;
            slider.minValue = 0f;
            slider.maxValue = 1f;
            slider.wholeNumbers = false;
            slider.SetValueWithoutNotify(Mathf.Clamp01(value));
        }

        /// <summary>
        /// 生成一个可直接使用的 TMP_Dropdown（对应 SettingView 的 Panel/LanguageDropdown）。
        ///
        /// 【结构对齐官方模板】与 TMP 内置的 `TMP_DefaultControls.CreateDropdown` 同构 ——
        ///   运行时 TMP_Dropdown.Show() 会按这套层级找部件，换层级/改名会静默失效：
        ///   LanguageDropdown                      Image + TMP_Dropdown（整块即点击面）
        ///   ├── Label                             captionText：显示当前选项
        ///   ├── Arrow                             下拉指示（ASCII "v"，同选关页 "< >" 口径）
        ///   └── Template（★ 默认 SetActive(false)）  template：运行时被克隆成弹出的列表
        ///       └── Viewport                      Mask 裁剪窗口
        ///           └── Content                   ScrollRect 的内容容器（高度运行时重算）
        ///               └── Item                  ★ 必须挂 Toggle —— TMP 靠"模板里的 Toggle"识别列表项
        ///                   ├── Item Background   item 底色（Toggle 的 targetGraphic）
        ///                   ├── Item Checkmark    选中标记（Toggle 的 graphic）
        ///                   └── Item Label        itemText：列表项文本
        ///
        /// 【为什么不给 Item 挂 TMP_Dropdown.DropdownItem】它在运行时 Show()→SetupTemplate()
        ///   里由 TMP 自己 AddComponent 补挂（官方同款路径），生成器不抢跑。
        /// 【为什么所有文本留空】列表项与 caption 的文案由 SettingView 运行时按语言填；
        ///   留空还能让「批量挂 TextLocalizer」（菜单 308）自然跳过这些节点（空文本跳过规则），
        ///   免得本地化组件在切语言时把运行时填好的选项文案冲掉。
        /// </summary>
        /// <param name="itemHeight">列表项行高（与 32 号字匹配的 56）。</param>
        /// <param name="templateRows">模板设计为几行高（3 = 三种语言恰好放下；更多语言会自动走滚动）。</param>
        private static void CreateDropdown(Transform parent, string name, Vector2 anchoredPos,
            Vector2 size, float itemHeight, int templateRows)
        {
            // ---- 根：点击面 + TMP_Dropdown ----
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = new Vector2(0.5f, 0.5f);
            rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = size;

            Image bgImg = go.AddComponent<Image>();
            ApplySlicedSkin(bgImg, "UI_Btn_Secondary", ButtonColor);

            TMP_Dropdown dropdown = go.AddComponent<TMP_Dropdown>();
            dropdown.targetGraphic = bgImg;
            ColorBlock cb = dropdown.colors;
            cb.normalColor = Color.white;
            cb.highlightedColor = new Color(1.15f, 1.15f, 1.15f, 1f);
            cb.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);
            cb.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.6f);
            dropdown.colors = cb;

            // ---- caption（当前选项）：横向拉伸、左对齐、右侧给箭头留位 ----
            TextMeshProUGUI caption = CreateTextStretched(go.transform, "Label", "",
                new Vector2(0f, 0f), new Vector2(1f, 1f), Vector2.zero, Vector2.zero,
                TextAnchor.MiddleLeft, SmallFontSize);
            RectTransform captionRT = (RectTransform)caption.transform;
            captionRT.offsetMin = new Vector2(20f, 0f);
            captionRT.offsetMax = new Vector2(-64f, 0f);

            // ---- Arrow：下拉指示 ----
            // 【为什么用 ASCII "v" 而不是 ▼】中文字体（思源宋体）不保证有几何箭头码位，
            //   缺字形只会渲染成空白且不报错 —— 与选关页左右箭头选 "< >" 是同一个理由。
            TextMeshProUGUI arrow = CreateText(go.transform, "Arrow", "v",
                new Vector2(1f, 0.5f), new Vector2(-32f, 0f), new Vector2(40f, 50f),
                TextAnchor.MiddleCenter, SmallFontSize);
            arrow.color = TextSecondary;

            // ---- Template：弹出的列表模板（默认隐藏）----
            GameObject template = new GameObject("Template", typeof(RectTransform));
            template.transform.SetParent(go.transform, false);
            RectTransform trt = (RectTransform)template.transform;
            // 官方口径：贴根节点底边、向下展开；运行时若越出画布会自动翻转到上方（TMP 内部处理）
            trt.anchorMin = new Vector2(0f, 0f);
            trt.anchorMax = new Vector2(1f, 0f);
            trt.pivot = new Vector2(0.5f, 1f);
            trt.anchoredPosition = new Vector2(0f, 2f);
            trt.sizeDelta = new Vector2(0f, itemHeight * templateRows + 8f);

            Image templateImg = template.AddComponent<Image>();
            ApplySlicedSkin(templateImg, "UI_Panel_Cyan", new Color(0.12f, 0.16f, 0.24f, 0.98f));

            // ---- Viewport：裁剪窗口（showMaskGraphic=false，只当裁剪框用）----
            GameObject viewport = new GameObject("Viewport", typeof(RectTransform));
            viewport.transform.SetParent(template.transform, false);
            RectTransform vrt = (RectTransform)viewport.transform;
            vrt.anchorMin = Vector2.zero;
            vrt.anchorMax = Vector2.one;
            vrt.pivot = new Vector2(0f, 1f);
            vrt.anchoredPosition = Vector2.zero;
            vrt.sizeDelta = Vector2.zero;
            Image viewportImg = viewport.AddComponent<Image>();
            viewportImg.color = Color.white;    // 不被渲染（showMaskGraphic=false），只是 Mask 的载体
            Mask mask = viewport.AddComponent<Mask>();
            mask.showMaskGraphic = false;

            // ---- Content：ScrollRect 的内容容器（高度由 TMP 运行时按列表项数量重算）----
            GameObject content = new GameObject("Content", typeof(RectTransform));
            content.transform.SetParent(viewport.transform, false);
            RectTransform crt = (RectTransform)content.transform;
            crt.anchorMin = new Vector2(0f, 1f);
            crt.anchorMax = new Vector2(1f, 1f);
            crt.pivot = new Vector2(0.5f, 1f);
            crt.anchoredPosition = Vector2.zero;
            crt.sizeDelta = new Vector2(0f, itemHeight + 8f);

            // ---- Item：★ 必须挂 Toggle（TMP 靠它识别列表项模板）----
            GameObject item = new GameObject("Item", typeof(RectTransform));
            item.transform.SetParent(content.transform, false);
            RectTransform irt = (RectTransform)item.transform;
            irt.anchorMin = new Vector2(0f, 0.5f);
            irt.anchorMax = new Vector2(1f, 0.5f);
            irt.pivot = new Vector2(0.5f, 0.5f);
            irt.anchoredPosition = Vector2.zero;
            irt.sizeDelta = new Vector2(0f, itemHeight);

            // item 底色（Toggle 的 targetGraphic：悬停/按下靠它出反馈）
            GameObject itemBg = new GameObject("Item Background", typeof(RectTransform));
            itemBg.transform.SetParent(item.transform, false);
            RectTransform itemBgRT = (RectTransform)itemBg.transform;
            itemBgRT.anchorMin = Vector2.zero;
            itemBgRT.anchorMax = Vector2.one;
            itemBgRT.pivot = new Vector2(0.5f, 0.5f);
            itemBgRT.anchoredPosition = Vector2.zero;
            itemBgRT.sizeDelta = Vector2.zero;
            Image itemBgImg = itemBg.AddComponent<Image>();
            ApplySlicedSkin(itemBgImg, "UI_Btn_Secondary", new Color(1f, 1f, 1f, 0.06f));

            // 选中标记：小菱形（45° 方块）—— 工程无 checkmark 素材，纯色几何不依赖字体码位
            GameObject check = new GameObject("Item Checkmark", typeof(RectTransform));
            check.transform.SetParent(item.transform, false);
            RectTransform checkRT = (RectTransform)check.transform;
            checkRT.anchorMin = new Vector2(0f, 0.5f);
            checkRT.anchorMax = new Vector2(0f, 0.5f);
            checkRT.pivot = new Vector2(0.5f, 0.5f);
            checkRT.anchoredPosition = new Vector2(30f, 0f);
            checkRT.sizeDelta = new Vector2(22f, 22f);
            checkRT.localRotation = Quaternion.Euler(0f, 0f, 45f);
            Image checkImg = check.AddComponent<Image>();
            checkImg.color = Cyan;
            checkImg.raycastTarget = false;     // 点击由整行 Toggle 处理

            // 列表项文本：拉伸铺满（左侧给菱形留位），TMP 运行时按选项填
            TextMeshProUGUI itemLabel = CreateTextStretched(item.transform, "Item Label", "",
                Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero,
                TextAnchor.MiddleLeft, SmallFontSize);
            RectTransform itemLabelRT = (RectTransform)itemLabel.transform;
            itemLabelRT.offsetMin = new Vector2(50f, 0f);
            itemLabelRT.offsetMax = new Vector2(-10f, 0f);

            Toggle toggle = item.AddComponent<Toggle>();
            toggle.targetGraphic = itemBgImg;
            toggle.graphic = checkImg;
            toggle.isOn = true;     // 官方模板同款：模板态默认勾选（运行时由 TMP 逐项设 isOn）
            ColorBlock tcb = toggle.colors;
            tcb.normalColor = Color.white;
            tcb.highlightedColor = new Color(1.3f, 1.3f, 1.3f, 1f);
            tcb.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);
            tcb.selectedColor = new Color(1.15f, 1.15f, 1.15f, 1f);
            toggle.colors = tcb;

            // ---- ScrollRect：挂在 Template 上（官方口径），3 项以内无需滚动条 ----
            ScrollRect scrollRect = template.AddComponent<ScrollRect>();
            scrollRect.content = crt;
            scrollRect.viewport = vrt;
            scrollRect.horizontal = false;
            scrollRect.movementType = ScrollRect.MovementType.Clamped;

            // ---- 绑定 TMP_Dropdown 的部件引用（缺一个都会让运行时列表展开失败）----
            dropdown.template = trt;
            dropdown.captionText = caption;
            dropdown.itemText = itemLabel;

            // 模板默认隐藏：设置界面上只显示 caption，点开时 TMP 克隆它生成弹出列表
            template.SetActive(false);
        }

        /// <summary>
        /// Slider 的两层子节点（Area 容器 + 内层 Image），返回内层 Image 供 Slider 引用。
        /// innerName 指定内层节点名（Fill / Handle / Background）；area 的锚点由调用方传。
        /// </summary>
        private static Image CreateSliderLeaf(Transform parent, string areaName,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 offsetMin, Vector2 offsetMax,
            System.Action<Image> skin, string innerName = "Img")
        {
            GameObject area = new GameObject(areaName, typeof(RectTransform));
            area.transform.SetParent(parent, false);
            RectTransform art = (RectTransform)area.transform;
            art.anchorMin = anchorMin;
            art.anchorMax = anchorMax;
            art.pivot = new Vector2(0.5f, 0.5f);
            art.offsetMin = offsetMin;
            art.offsetMax = offsetMax;

            GameObject inner = new GameObject(innerName, typeof(RectTransform));
            inner.transform.SetParent(art, false);
            RectTransform irt = (RectTransform)inner.transform;
            irt.anchorMin = Vector2.zero;
            irt.anchorMax = Vector2.one;
            irt.pivot = new Vector2(0.5f, 0.5f);
            irt.offsetMin = Vector2.zero;
            irt.offsetMax = Vector2.zero;

            Image img = inner.AddComponent<Image>();
            img.raycastTarget = false;
            if (skin != null) skin(img);
            return img;
        }

        // ==================================================================
        // UI 补全 P1：启动链三界面（Splash / Loading / HotUpdate）
        // ==================================================================
        // 【三者的共同点】都是**整页**（stretchInset = 0），都自带深色底。
        // 【为什么标题不用 CreateDialogShell 的 Title】骨架给整页标题的规格是
        //   "64 号、距顶 64"（那是给"Select Level""Tower Codex"这类页面标题用的）；
        //   而这三个界面要的是自己的主视觉（开屏 96 号品牌名 / 加载与热更新是"居中构图"）。
        //   硬把标题挪过去会让骨架方法的语义变模糊，所以这里传空标题，
        //   再各自建自己的文本节点 —— 骨架的 Title 仍然存在（空串，不可见），不破坏契约。

        private static void BuildSplash(EditorUtil.Report report)
        {
            report.Head("生成开屏页 → " + SplashPath);
            string extra;
            if (!EditorUtil.IsSafeToRebuild(SplashPath, SplashChildren, out extra))
            {
                report.Error("SplashView.prefab 检测到生成器不识别的节点：" + extra + "　→ 已中止");
                return;
            }

            DeleteUiPrefab(SplashPath);
            EditorUtil.EnsureFolderOfFile(SplashPath);

            GameObject panel;
            GameObject root = CreateDialogShell("SplashView", "", Vector2.zero, report, out panel, 0f);

            // 自带 CanvasGroup：本界面要自己控制整屏淡入（UIManager.EnsureFadeIn 会因此跳过它）
            root.AddComponent<CanvasGroup>();
            root.AddComponent<SplashView>();

