            title.color = Cyan;

            // 副标题基线 y_svg 540 → Y=0；26 号 → 盒中心 ≈ −9
            // ★ 手工版把副标题**隐藏**了（与 GameTitle 内容重复，版面更干净）。
            //   用 SetActive(false) 而不是删节点：将来想恢复只需在 prefab 里勾回来，
