                TextAnchor.MiddleCenter, 30);      // ★ 2026-10-15 手工版：左对齐 → 居中 + 自动字号
            star.color = Gold;
            SetAutoSize(star);

            TextMeshProUGUI clear = CreateText(statBg, "ClearText", "Cleared 0/0",
                new Vector2(0f, 1f), new Vector2(24f, -64.1f), new Vector2(368f, 40f),
                TextAnchor.MiddleCenter, 28);      // ★ 2026-10-15 手工版：左对齐 → 居中 + 自动字号
            clear.color = TextSecondary;
            SetAutoSize(clear);

            // 四颗入口按钮：中心 Y 依次 −66 / −184 / −302 / −420（对应 y_svg 606/724/842/960）
            CreatePanelButton(panel.transform, "StartBtn", "Start Game", new Vector2(0f, -66f), 480f, true, 92f, 34);
            CreatePanelButton(panel.transform, "CodexBtn", "Tower Codex", new Vector2(0f, -184f), 480f, false, 92f, 32);
            CreatePanelButton(panel.transform, "SettingBtn", "Settings", new Vector2(0f, -302f), 480f, false, 92f, 32);
            // 2026-10-16 多分辨率适配：退出键改"贴屏幕底边"（原中心锚 -420 在 ≥21.5:9 会碰底）；
            // 16:9 换算：原下缘 = 540−420−46 = 74 → 像素级同款。
            CreatePanelButton(panel.transform, "QuitBtn", "Quit Game", new Vector2(0f, 74f), 480f, false, 92f, 32,
                new Vector2(0.5f, 0f), new Vector2(0.5f, 0f));

            // 版本行：**底部中间**（2026-10-14 需求："主界面底部中间显示当前版本号"）。
            // 原先在右下角（anchor(1,0) pos(-48,38) 右对齐），移到底边水平居中。
            // 文字内容由 MainMenuView.cs 在运行时填充（VersionInfo.BuildDisplayVersion：
            // "v1.0.0 · r2026101501"），prefab 里留空 —— 版本号绝不能硬编码进 prefab。
            // 宽度给 700：够放"应用版本 + 资源版本"两段，居中锚点保证任意屏宽都居中。
            TextMeshProUGUI ver = CreateText(panel.transform, "Version", string.Empty,
                new Vector2(0.5f, 0f), new Vector2(0f, 30f), new Vector2(700f, 32f),
                TextAnchor.MiddleCenter, 22);
            ver.color = TextTertiary;

