                return;
            }

            // 卡片先建：下面的 LoopListView2 要引用这份 prefab 资产
            GameObject itemPrefab = BuildTowerCodexItemPrefab(report);
            if (itemPrefab == null)
            {
                report.Error("塔图鉴卡片生成失败，TowerCodexView 未重建（避免产出「列表里没有条目」的空壳）");
                return;
