            LoopListView2 lv = list.AddComponent<LoopListView2>();
            ConfigureLoopListView(lv, itemPrefab, CodexItemGap, 2);

            // 左右箭头（ASCII < >，与选关界面同一理由：中文 SDF 不保证有 ◀▶ 码位）
