                TextAnchor.MiddleCenter, 28);

            // 关闭按钮改"贴屏幕底边"（原中心锚 -430 在 ≥21.3:9 高屏会被裁）
            CreatePanelButton(panel.transform, "CloseBtn", "Back", new Vector2(0f, PanelCloseBtnBottomY), 340f, true, 84f, 32,
