        /// <summary>把生成出来的某个子节点置为初始隐藏（由 View 在运行期按状态切换）。</summary>
        private static void SetNodeActive(Transform root, string path, bool active)
        {
            Transform t = root.Find(path);
            if (t != null && t.gameObject.activeSelf != active)
            {
                t.gameObject.SetActive(active);
            }
        }

        // ------------------------------------------------------------------
        // 构件
        // ------------------------------------------------------------------

        private static TextMeshProUGUI CreateText(Transform parent, string name, string content,
            Vector2 anchor, Vector2 anchoredPos, Vector2 size, TextAnchor align, int fontSize)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            // 用左上/顶部为轴心的锚点，避免不同分辨率下位置漂移
            rt.anchorMin = anchor;
            rt.anchorMax = anchor;
            rt.pivot = new Vector2(anchor.x, anchor.y);
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = size;

            // 【为什么用 TextMeshProUGUI（UGUI 版 TMP）而不是 TextMeshPro】
            //   TextMeshProUGUI 才是 Canvas 下渲染的组件；TextMeshPro 是世界空间网格版。
            //   UI 层的所有文本都必须用 TextMeshProUGUI，否则不会出现在 Canvas 里。
            TextMeshProUGUI t = go.AddComponent<TextMeshProUGUI>();
            TMP_FontAsset font = EditorUtil.GetDefaultTmpFont();
            if (font != null)
            {
                t.font = font;
            }
            t.text = content;
            t.fontSize = fontSize;
            t.alignment = ToTmpAlignment(align);
            t.color = TextColor;
            t.raycastTarget = false;    // 文本不吃点击，避免挡住按钮

            // 描边：背景是浅色纸张纹理时纯白字会看不清。
            // 【TMP 不支持 UGUI 的 Outline 组件】UGUI 描边是靠复制顶点实现的组件；
            //   TMP 的描边是**材质属性**（_OutlineWidth / _OutlineColor），必须给文本
            //   指定一份开启了 outline 的材质预设。这里在生成期取/建该材质并赋上。
            //   取不到字体时不设置材质，退化为无描边（不影响功能）。
            Material outlineMat = GetOrCreateOutlineMaterial(font);
            if (outlineMat != null)
            {
                t.fontSharedMaterial = outlineMat;
            }

            // 不自动换行 + 溢出可见：与旧版 UGUI Text 默认行为一致，
            // 需要换行的少数节点（Tips / Stats / 关卡按钮）再单独打开 enableWordWrapping。
            t.enableWordWrapping = false;
            t.overflowMode = TextOverflowModes.Overflow;
            return t;
        }

        /// <summary>
        /// 取一份"开启描边"的 TMP 字体材质（预设资产）。
        ///
        /// 【为什么要落到资产文件】TMP 的材质是资产；若每个文本都 new 一份材质，
        ///   ① 会产生大量运行时材质实例、破坏合批 ② 存进 prefab 后会变成内嵌资产，
        ///   一堆重复。所以这里统一建一份共享材质资产，所有文本引用同一份。
        /// 首次调用时创建，之后直接复用（幂等）。
        /// </summary>
        private static Material GetOrCreateOutlineMaterial(TMP_FontAsset font)
        {
            if (font == null)
            {
                return null;
            }
            Material cached = AssetDatabase.LoadAssetAtPath<Material>(OutlineMaterialPath);
            if (cached != null)
            {
                return cached;
            }

            // 以字体自带的默认材质为模板复制一份，开启 outline
            Material mat = new Material(font.material);
            mat.name = "SiYuanSongTi SDF - Outline";
            mat.SetColor(ShaderUtilities.ID_OutlineColor, OutlineColor);
            mat.SetFloat(ShaderUtilities.ID_OutlineWidth, 0.12f);
            mat.EnableKeyword(ShaderUtilities.Keyword_Outline);

            EditorUtil.EnsureFolderOfFile(OutlineMaterialPath);
            AssetDatabase.CreateAsset(mat, OutlineMaterialPath);
            AssetDatabase.SaveAssets();

            // 描边材质被所有 UI 预制体共享引用（和字体一样是共享依赖）。
            // 【为什么在这里不直接设 AB 名】AB 名由 ResTable → ABNameSetter 统一写入
            //   （唯一权威来源）。ResTable 已登记 "Font_Outline_Mat" → bundle "font"，
            //   故此处只需保证资产存在，随后向导里的 ABNameSetter 步骤会赋名，避免重复逻辑。
            return mat;
        }

        /// <summary>统一的中文字体描边材质资产路径</summary>
        private const string OutlineMaterialPath = "Assets/Font/SiYuanSongTi SDF - Outline.mat";

        /// <summary>
        /// UGUI `TextAnchor` → TMP `TextAlignmentOptions` 的映射。
        ///
        /// 【为什么需要显式映射】TMP 用 (水平+垂直) 两位组合的枚举，UGUI 用九宫格 TextAnchor；
        ///   二者无隐式转换。这里逐项翻译，保持生成器接口签名不变（调用点二十多处）。
        /// </summary>
        private static TextAlignmentOptions ToTmpAlignment(TextAnchor a)
        {
            switch (a)
            {
                case TextAnchor.UpperLeft:    return TextAlignmentOptions.TopLeft;
                case TextAnchor.UpperCenter:  return TextAlignmentOptions.Top;
                case TextAnchor.UpperRight:   return TextAlignmentOptions.TopRight;
                case TextAnchor.MiddleLeft:   return TextAlignmentOptions.Left;
                case TextAnchor.MiddleCenter: return TextAlignmentOptions.Center;
                case TextAnchor.MiddleRight:  return TextAlignmentOptions.Right;
                case TextAnchor.LowerLeft:    return TextAlignmentOptions.BottomLeft;
                case TextAnchor.LowerCenter:  return TextAlignmentOptions.Bottom;
                case TextAnchor.LowerRight:   return TextAlignmentOptions.BottomRight;
                default:                      return TextAlignmentOptions.Center;
            }
        }

        /// <summary>
        /// 220×72 的通用小按钮（SpeedButton/StartButton）。
        /// 2026-10-16：支持"角落锚定"—— anchor 与 pivot 取同一角落，
        ///   anchoredPos 即"该角落到屏幕边缘的距离"（如 (64,77) = 左缘 64 / 下缘 77），
        ///   任意分辨率都不出画；旧调用点等价于原来的"底边中点锚"。
        /// </summary>
        private static void CreateButton(Transform parent, string name, string label,
            Vector2 anchor, Vector2 anchoredPos, bool primary = false)
        {
            GameObject go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            rt.anchorMin = anchor;
            rt.anchorMax = anchor;
            rt.pivot = anchor;
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = new Vector2(220f, 72f);

            Image img = go.AddComponent<Image>();
            ApplySlicedSkin(img, primary ? "UI_Btn_Primary" : "UI_Btn_Secondary", ButtonColor);

            Button btn = go.AddComponent<Button>();
            btn.targetGraphic = img;    // ★ 必须显式指定，否则按钮没有按下反馈
            ColorBlock cb = btn.colors;
            cb.normalColor = Color.white;
            cb.highlightedColor = new Color(1.15f, 1.15f, 1.15f, 1f);
            cb.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);
            cb.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.6f);
            btn.colors = cb;

            TextMeshProUGUI t = CreateText(go.transform, "Label", label,
                new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(220f, 72f),
                TextAnchor.MiddleCenter, SmallFontSize);
            // Label 要铺满按钮，单独设一次
            RectTransform lrt = (RectTransform)t.transform;
            lrt.anchorMin = Vector2.zero;
            lrt.anchorMax = Vector2.one;
            lrt.pivot = new Vector2(0.5f, 0.5f);
            lrt.anchoredPosition = Vector2.zero;
            lrt.sizeDelta = Vector2.zero;
        }

        /// <summary>
        /// 生成一颗塔按钮（128×128），带一个 Image 子节点用于承载塔图标（占位期留空）。
        /// 结构与手工版一致：Btn_Tower_* → Image(TowerIcon)，点击靠按钮自身，文字走 Label。
        /// </summary>
        private static void CreateTowerButton(Transform parent, TowerButtonSpec spec)
        {
            GameObject go = new GameObject(spec.NodeName, typeof(RectTransform));
            go.transform.SetParent(parent, false);

            RectTransform rt = (RectTransform)go.transform;
            // 【2026-10-16 多分辨率适配：中心锚（y=-427）→ 底边锚（下缘距底 49px）】
            //   中心锚在 19.2:9 以上的高屏会顶出屏幕下缘（19.5:9 裁 2px、21:9 裁 20px）；
            //   底边锚在任何高度都稳。x 仍按"画布中心坐标系"的槽位（-548/-274/0，见 TowerButtons）。
            //   ★ 16:9 换算：原底缘 = 540−427−64 = 49 → 像素级同款（基准零位移）。
            //   ★ 反例警告（历史回归）：曾把锚点搬去"画布左下角"导致整排飞到画布外、无法建塔——
            //     改锚点务必保持 x 用中心系、只把 y 落到屏幕底边。
            rt.anchorMin = new Vector2(0.5f, 0f);
            rt.anchorMax = new Vector2(0.5f, 0f);
            rt.pivot = new Vector2(0.5f, 0f);
            rt.anchoredPosition = new Vector2(spec.Pos.x, TowerBtnBottomY);
            rt.sizeDelta = new Vector2(128f, 128f);

            Image img = go.AddComponent<Image>();
            ApplySlicedSkin(img, "UI_TowerBtn_Frame", ButtonColor);

            Button btn = go.AddComponent<Button>();
            btn.targetGraphic = img;
            ColorBlock cb = btn.colors;
            cb.normalColor = Color.white;
            cb.highlightedColor = new Color(1.15f, 1.15f, 1.15f, 1f);
            cb.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);
            cb.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.6f);
            btn.colors = cb;

            // 图标子节点：占据按钮**上部**，底部留给价格签。
            // 【为什么不是铺满整格】铺满会与底部的价格芯片重叠，数字直接压在图标上。
            GameObject icon = new GameObject("Image", typeof(RectTransform));
            icon.transform.SetParent(go.transform, false);
            RectTransform irt = (RectTransform)icon.transform;
            irt.anchorMin = new Vector2(0.5f, 1f);
            irt.anchorMax = new Vector2(0.5f, 1f);
            irt.pivot = new Vector2(0.5f, 1f);
            irt.anchoredPosition = new Vector2(0f, -4f);
            // ★ 2026-10-15 手工版微调：84 → 96，与正式美术 96×96 塔图标同尺寸。
            //   代价：图标底边 (top −4 −96 = −100，即中心坐标 −36) 会压过价格签顶边
            //   (底 128−34 −2 = 92，即中心坐标 −28) —— 下缘重叠 8px。价格芯片绘制在图标之上、
            //   两者都 raycastTarget=false，不影响点击，视觉上图标更大更醒目。
            irt.sizeDelta = new Vector2(96f, 96f);
            Image iconImg = icon.AddComponent<Image>();
            iconImg.color = new Color(1f, 1f, 1f, 0.85f);
            iconImg.raycastTarget = false;  // 不吃点击，点击交给父级 Button
            Sprite sprite = LoadIcon(spec.TowerType);
            if (sprite != null)
            {
                iconImg.sprite = sprite;
                iconImg.color = Color.white;
            }

            // 价格签底（可选节点，HudView 视为可选）
            GameObject priceBg = new GameObject("PriceBg", typeof(RectTransform));
            priceBg.transform.SetParent(go.transform, false);
            RectTransform pbrt = (RectTransform)priceBg.transform;
            pbrt.anchorMin = new Vector2(0.5f, 0f);
            pbrt.anchorMax = new Vector2(0.5f, 0f);
            pbrt.pivot = new Vector2(0.5f, 0f);
            pbrt.anchoredPosition = new Vector2(0f, 2f);
            pbrt.sizeDelta = new Vector2(96f, 34f);
            Image priceBgImg = priceBg.AddComponent<Image>();
            priceBgImg.raycastTarget = false;
            ApplySlicedSkin(priceBgImg, "UI_Chip_Neutral", new Color(0.08f, 0.11f, 0.16f, 0.8f));

            // 【契约】塔按钮**不配 Label**（Docs/HudView_Sync_and_TowerUI_Plan.md §2）：
            // 需要显示价格时用 PriceText 子节点，不要复用 Label —— 否则"按钮上的文字"
            // 会同时承担"塔名"和"价格"两种语义，将来加角标或换图标栏时必然打架。
            // 本轮只建节点、文案留空，由 HudView 按当前配置表价格刷新。
            TextMeshProUGUI pt = CreateText(go.transform, "PriceText", string.Empty,
                new Vector2(0.5f, 0f), new Vector2(0f, 4f), new Vector2(128f, 36f),
                TextAnchor.LowerCenter, 24);   // 24 号才塞得进 96×34 的价格芯片（32 号会溢出）
            pt.raycastTarget = false;   // 不吃点击，点击交给父级 Button
        }

        /// <summary>
        /// 按塔型取建造栏图标。
        /// 【生成期只在编辑器里跑，直接走 AssetDatabase 读塔身贴图，不依赖运行时 ResLoader/AB】
        /// 资源未齐时返回 null → 按钮自动退化为纯色块，不影响逻辑联调。
        /// 【贴图名不统一】三塔美术文件名各异，逐塔指定（见 TowerPrefabConverter.Specs）
        /// </summary>
        private static Sprite LoadIcon(int towerType)
        {
            // ① 优先用程序生成的深色科幻塔图标（UISkinArtGenerator 产出）
            Sprite ui = LoadUiSprite(TowerIconSpriteName(towerType));
            if (ui != null)
            {
                return ui;
            }

            // ② 退化为塔身贴图
            string path;
            switch (towerType)
            {
                case 2: path = "Assets/_UIAssets/Tower/Power/tower_base.png"; break;
                case 3: path = "Assets/_UIAssets/Tower/retard/slowtower_base.png"; break;
                // 穿透塔 / 激光塔：专属美术未到位，暂时复用普通塔图标。
                // 【为什么不干脆留空退化成纯色块】纯色块在五连排里看不出是哪一种塔，
                // 联调"点对按钮了吗"反而更难判断；复用现有图标至少可区分"这是塔按钮"。
                case 4:
                case 5:
                default: path = "Assets/_UIAssets/Tower/Normal/turret_base_128.png"; break;
            }
            // 资源还没到 —— 不是错误，静默退化为纯色块
            return AssetDatabase.LoadAssetAtPath<Sprite>(path);
        }

        // The same definition is applied by the in-place migration and every generation entry.
        private static GameObject SaveUiPrefab(GameObject root, string path)
        {
            UIResolutionLayout.Apply(root);
            string output = LayoutOutputPath(path);
            EditorUtil.EnsureFolderOfFile(output);
            return PrefabUtility.SaveAsPrefabAsset(root, output);
        }

        private static string LayoutOutputPath(string path)
        {
            return _layoutPreviewFolder == null ? path : _layoutPreviewFolder + "/" + System.IO.Path.GetFileName(path);
        }

        private static bool DeleteUiPrefab(string path)
        {
            return AssetDatabase.DeleteAsset(LayoutOutputPath(path));
        }
        private static void Stretch(RectTransform rt)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = Vector2.zero;
            rt.sizeDelta = Vector2.zero;
            rt.localScale = Vector3.one;
        }
    }
}

using System;
using System.IO;
using TMPro;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject.EditorTools
{
    /// <summary>Shared layout definitions for new prefabs and non-destructive updates to existing assets.</summary>
    public static class UIResolutionLayout
    {
        [MenuItem("Tools/塔防/高级（单步重建）/同步 UI 分辨率布局（保留现有资源）", false, 330)]
        public static void SyncExisting()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode) throw new InvalidOperationException("Stop Play Mode before updating UI assets.");
            int count = 0;
            foreach (string path in Directory.GetFiles("Assets/Prefabs/UI", "*.prefab"))
            {
                string assetPath = path.Replace('\\', '/');
                GameObject root = PrefabUtility.LoadPrefabContents(assetPath);
                try
                {
                    Apply(root);
                    PrefabUtility.SaveAsPrefabAsset(root, assetPath);
                    count++;
                }
                finally { PrefabUtility.UnloadPrefabContents(root); }
            }
            Debug.Log("[UIResolution] Updated " + count + " UI prefabs, retaining their GUIDs and existing components.");
        }

        public static void Apply(GameObject root)
        {
            string name = root.name;
            if (name == "TowerCodexItem")
            {
                FitText(root, "Body/TypeName", 28f, 40f, false);
                FitText(root, "Body/Role", 20f, 26f, false);
                foreach (string row in new[] { "DpsRow", "RangeRow", "SpeedRow", "PriceRow" })
                    FitText(root, "Body/" + row, 20f, 26f, false);
                FitText(root, "Body/DescText", 16f, 24f, true);
                RectTransform description = root.transform.Find("Body/DescText") as RectTransform;
                description.anchoredPosition = new Vector2(0f, -275f);
                description.sizeDelta = new Vector2(380f, 70f);
                return;
            }
            // Item roots belong to LoopListView2; boot screens retain their existing layout.
            if (!name.EndsWith("View", StringComparison.Ordinal) || name == "SplashView" || name == "LoadingView" || name == "HotUpdateView") return;
            RectTransform bg = root.transform.Find("Bg") as RectTransform;
            if (bg != null)
            {
                Stretch(bg);
                Ensure<UIFullScreenBackground>(bg.gameObject);
            }
            RectTransform panel = root.transform.Find("Panel") as RectTransform;
            if (panel != null && panel.anchorMin == panel.anchorMax)
            {
                Ensure<UIFitInParent>(panel.gameObject);
                // Convert each dialog button without changing its baseline rectangle.
                foreach (Transform child in panel)
                {
                    RectTransform rect = child as RectTransform;
                    if (rect == null || child.GetComponent<Button>() == null || rect.anchorMin != rect.anchorMax) continue;
                    Reanchor(rect, new Vector2(rect.anchorMin.x, 0f), panel.sizeDelta);
                }
            }
            if (name == "TipsView")
            {
                RectTransform bar = root.transform.Find("TipBar") as RectTransform;
                if (bar != null)
                {
                    bar.anchorMin = bar.anchorMax = new Vector2(0.5f, 1f);
                    bar.pivot = new Vector2(0.5f, 0.5f);
                    bar.anchoredPosition = new Vector2(0f, -263f);
                }
            }
            else if (name == "MainMenuView") Ensure<UIResponsivePage>(root).Configure(UIResponsivePage.PageKind.MainMenu);
            else if (name == "SelectView") Ensure<UIResponsivePage>(root).Configure(UIResponsivePage.PageKind.Select);
            else if (name == "TowerCodexView")
            {
                Ensure<UIResponsivePage>(root).Configure(UIResponsivePage.PageKind.TowerCodex);
                RectTransform title = panel.Find("CodexTitle") as RectTransform;
                title.anchorMin = title.anchorMax = new Vector2(0.5f, 1f);
                title.pivot = new Vector2(0.5f, 0.5f);
                title.anchoredPosition = new Vector2(0f, -68f);
                RectTransform viewport = panel.Find("List/Viewport") as RectTransform;
                viewport.anchorMin = viewport.anchorMax = new Vector2(0.5f, 0.5f);
                viewport.pivot = new Vector2(0f, 0.5f);
                viewport.anchoredPosition = new Vector2(-230f, 0f);
                viewport.sizeDelta = new Vector2(460f, 640f);
                RectTransform page = panel.Find("PageText") as RectTransform;
                page.anchorMin = page.anchorMax = new Vector2(0.5f, 0f);
                page.pivot = new Vector2(0.5f, 0.5f);
                page.anchoredPosition = new Vector2(0f, 184f);
            }
            else if (name == "SellConfirmView")
            {
                FitText(root, "Panel/TowerName", 28f, 36f, false);
                FitText(root, "Panel/WarnText", 24f, 30f, true);
                ((RectTransform)panel.Find("TowerName")).sizeDelta = new Vector2(740f, 52f);
                ((RectTransform)panel.Find("WarnText")).sizeDelta = new Vector2(700f, 88f);
            }
            else if (name == "GameIntroView")
            {
                for (int i = 1; i <= 4; i++) FitText(root, "Panel/Info" + i, 24f, 30f, true);
            }
            else if (name == "TowerInfoView") FitText(root, "Panel/Title", 28f, 40f, false);
        }

        private static void FitText(GameObject root, string path, float minimum, float maximum, bool wrap)
        {
            TMP_Text text = root.transform.Find(path).GetComponent<TMP_Text>();
            text.enableWordWrapping = wrap;
            text.enableAutoSizing = true;
            text.fontSizeMin = minimum;
            text.fontSizeMax = maximum;
            text.overflowMode = TextOverflowModes.Overflow;
        }

        private static T Ensure<T>(GameObject go) where T : Component
        {
            T component = go.GetComponent<T>();
            return component != null ? component : go.AddComponent<T>();
        }

        private static void Reanchor(RectTransform rect, Vector2 anchor, Vector2 parentSize)
        {
            Vector2 position = rect.anchoredPosition + Vector2.Scale(rect.anchorMin - anchor, parentSize);
            rect.anchorMin = rect.anchorMax = anchor;
            rect.anchoredPosition = position;
        }

        private static void Stretch(RectTransform rect)
        {
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = rect.offsetMax = Vector2.zero;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using SimpleJSON;
using SuperScrollView;
using TMPro;
using UnityEditor;
