        // ------------------------------------------------------------------
        // 星（48×48）
        // ------------------------------------------------------------------

        private static void WriteStar(string name, bool on, EditorUtil.Report report)
        {
            const int S = 48;
            Texture2D tex = EditorUtil.NewTexture(S, S);
            float cx = S * 0.5f, cy = S * 0.5f;
            float outer = 21f, inner = 8.5f;

            if (on)
            {
                SoftGlow(tex, cx, cy, 22f, Gold, 0.45f);
            }
            Color starStroke = on ? Hex("B96E1B") : StrokeC;
            for (int y = 0; y < S; y++)
            {
                for (int x = 0; x < S; x++)
                {
                    float dx = (x + 0.5f) - cx;
                    float dy = (y + 0.5f) - cy;
                    float d = Mathf.Sqrt(dx * dx + dy * dy);
                    float ang = Mathf.Atan2(dy, dx) * Mathf.Rad2Deg;
                    float rr = StarRadius(ang, outer, inner);
                    float sd = d - rr;
                    float cov = Mathf.Clamp01(0.5f - sd);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = on ? Gold : SlateDeep;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                    // 描边
                    float band = Mathf.Clamp01((sd + 2f) / 2f);
                    if (band > 0f)
                    {
                        Color sc = starStroke;
                        sc.a *= band * cov;
                        BlendAt(tex, x, y, sc);
                    }
                }
            }
            EditorUtil.WriteSprite(UiArtDir + "/" + name + ".png", tex);
            report.Ok(name + ".png  (" + S + "×" + S + (on ? " 亮星" : " 暗星") + ")");
        }

        /// <summary>五角星在角度 ang 处的半径（尖角朝上）</summary>
        private static float StarRadius(float angDeg, float outer, float inner)
        {
            float a = Mathf.Repeat(angDeg + 90f, 72f) / 72f;   // 0..1
            float tri = 1f - Mathf.Abs(2f * a - 1f);           // 0→1→0
            return inner + (outer - inner) * tri;
        }

        // ------------------------------------------------------------------
        // 基础绘制原语（全部作用在 Texture2D，坐标原点左下）
        // ------------------------------------------------------------------

        private static void BlendAt(Texture2D tex, int x, int y, Color src)
        {
            if (src.a <= 0f || x < 0 || y < 0 || x >= tex.width || y >= tex.height)
            {
                return;
            }
            Color dst = tex.GetPixel(x, y);
            float a = src.a + dst.a * (1f - src.a);
            if (a <= 0.0001f)
            {
                tex.SetPixel(x, y, new Color(0f, 0f, 0f, 0f));
                return;
            }
            Color r = new Color(
                (src.r * src.a + dst.r * dst.a * (1f - src.a)) / a,
                (src.g * src.a + dst.g * dst.a * (1f - src.a)) / a,
                (src.b * src.a + dst.b * dst.a * (1f - src.a)) / a,
                a);
            tex.SetPixel(x, y, r);
        }

        /// <summary>径向柔光（中心最亮，向外平方衰减）</summary>
        private static void SoftGlow(Texture2D tex, float cx, float cy, float radius, Color color, float strength)
        {
            int W = tex.width, H = tex.height;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float dx = x + 0.5f - cx;
                    float dy = y + 0.5f - cy;
                    float d = Mathf.Sqrt(dx * dx + dy * dy);
                    if (d >= radius)
                    {
                        continue;
                    }
                    float g = 1f - d / radius;
                    Color c = color;
                    c.a *= g * g * strength;
                    BlendAt(tex, x, y, c);
                }
            }
        }

        private static void FillDisc(Texture2D tex, float cx, float cy, float radius, Color fill, Color stroke, float strokeW)
        {
            int W = tex.width, H = tex.height;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float dx = x + 0.5f - cx;
                    float dy = y + 0.5f - cy;
                    float sd = Mathf.Sqrt(dx * dx + dy * dy) - radius;
                    float cov = Mathf.Clamp01(0.5f - sd);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = fill;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                    if (strokeW > 0f)
                    {
                        float band = Mathf.Clamp01((sd + strokeW) / strokeW);
                        if (band > 0f)
                        {
                            Color sc = stroke;
                            sc.a *= band * cov;
                            BlendAt(tex, x, y, sc);
                        }
                    }
                }
            }
        }

        private static void DrawRing(Texture2D tex, float cx, float cy, float radius, float width, Color color)
        {
            int W = tex.width, H = tex.height;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float dx = x + 0.5f - cx;
                    float dy = y + 0.5f - cy;
                    float sd = Mathf.Abs(Mathf.Sqrt(dx * dx + dy * dy) - radius) - width * 0.5f;
                    float cov = Mathf.Clamp01(0.5f - sd);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = color;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                }
            }
        }

        private static void FillEllipse(Texture2D tex, float cx, float cy, float rx, float ry, Color color)
        {
            int W = tex.width, H = tex.height;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float nx = (x + 0.5f - cx) / rx;
                    float ny = (y + 0.5f - cy) / ry;
                    float q = Mathf.Sqrt(nx * nx + ny * ny);
                    float cov = Mathf.Clamp01((1f - q) * Mathf.Min(rx, ry) + 0.5f);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = color;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                }
            }
        }

        /// <summary>轴对齐矩形（x0,y0)-(x1,y1)，含可选内描边</summary>
        private static void FillBoxRect(Texture2D tex, float x0, float y0, float x1, float y1,
            Color fill, Color stroke, float strokeW)
        {
            int W = tex.width, H = tex.height;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float px = x + 0.5f, py = y + 0.5f;
                    float sd = Mathf.Max(Mathf.Max(x0 - px, px - x1), Mathf.Max(y0 - py, py - y1));
                    float cov = Mathf.Clamp01(0.5f - sd);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = fill;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                    if (strokeW > 0f)
                    {
                        float band = Mathf.Clamp01((sd + strokeW) / strokeW);
                        if (band > 0f)
                        {
                            Color sc = stroke;
                            sc.a *= band * cov;
                            BlendAt(tex, x, y, sc);
                        }
                    }
                }
            }
        }

        /// <summary>绕中心旋转的矩形（用于炮管）</summary>
        private static void FillRotRect(Texture2D tex, float cx, float cy, float halfLen, float halfThick,
            float angleDeg, Color fill, Color stroke, float strokeW)
        {
            int W = tex.width, H = tex.height;
            float rad = angleDeg * Mathf.Deg2Rad;
            float cos = Mathf.Cos(rad), sin = Mathf.Sin(rad);
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float dx = x + 0.5f - cx;
                    float dy = y + 0.5f - cy;
                    // 逆旋转到矩形局部坐标
                    float lx = dx * cos + dy * sin;
                    float ly = -dx * sin + dy * cos;
                    float sd = Mathf.Max(Mathf.Abs(lx) - halfLen, Mathf.Abs(ly) - halfThick);
                    float cov = Mathf.Clamp01(0.5f - sd);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = fill;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                    if (strokeW > 0f)
                    {
                        float band = Mathf.Clamp01((sd + strokeW) / strokeW);
                        if (band > 0f)
                        {
                            Color sc = stroke;
                            sc.a *= band * cov;
                            BlendAt(tex, x, y, sc);
                        }
                    }
                }
            }
        }

        /// <summary>
        /// 凸多边形填充（顶点顺序任意）。逐边算"归一化到像素距离"的有向距离：
        /// 全部同号 = 在内部，取最接近 0 的一条作为深度；符号不一致 = 在外部。
        /// 【为什么不用 EditorUtil.FillTriangleUp】那个函数把 max(cross) 当作外测距离，
        /// 与内部点的正号约定相反，实测画不出三角形 —— 这里用自洽的写法。
        /// </summary>
        private static void FillConvexPoly(Texture2D tex, Vector2[] pts, Color fill, Color stroke, float strokeW)
        {
            int n = pts.Length;
            if (n < 3)
            {
                return;
            }
            int W = tex.width, H = tex.height;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float px = x + 0.5f, py = y + 0.5f;
                    float dmin = float.MaxValue, dmax = float.MinValue;
                    for (int i = 0; i < n; i++)
                    {
                        Vector2 a = pts[i];
                        Vector2 b = pts[(i + 1) % n];
                        float ex = b.x - a.x, ey = b.y - a.y;
                        float elen = Mathf.Max(0.0001f, Mathf.Sqrt(ex * ex + ey * ey));
                        float cross = (ex * (py - a.y) - ey * (px - a.x)) / elen;
                        dmin = Mathf.Min(dmin, cross);
                        dmax = Mathf.Max(dmax, cross);
                    }
                    float sd = Mathf.Max(dmin, -dmax);   // >=0 内部
                    float cov = Mathf.Clamp01(sd + 0.5f);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = fill;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                    if (strokeW > 0f)
                    {
                        // 距离边缘 strokeW 以内画描边
                        float band = Mathf.Clamp01((strokeW - sd) / strokeW);
                        if (band > 0f)
                        {
                            Color sc = stroke;
                            sc.a *= band * cov;
                            BlendAt(tex, x, y, sc);
                        }
                    }
                }
            }
        }

        /// <summary>抗锯齿线段（带宽）</summary>
        private static void DrawLine(Texture2D tex, float x0, float y0, float x1, float y1, Color color, float width)
        {
            int W = tex.width, H = tex.height;
            float ex = x1 - x0, ey = y1 - y0;
            float len2 = Mathf.Max(0.0001f, ex * ex + ey * ey);
            float half = width * 0.5f;
            for (int y = 0; y < H; y++)
            {
                for (int x = 0; x < W; x++)
                {
                    float px = x + 0.5f - x0, py = y + 0.5f - y0;
                    float t = Mathf.Clamp01((px * ex + py * ey) / len2);
                    float qx = px - ex * t, qy = py - ey * t;
                    float d = Mathf.Sqrt(qx * qx + qy * qy);
                    float cov = Mathf.Clamp01(half - d + 0.5f);
                    if (cov <= 0f)
                    {
                        continue;
                    }
                    Color c = color;
                    c.a *= cov;
                    BlendAt(tex, x, y, c);
                }
            }
        }

        private static Color Hex(string hex)
        {
            Color c;
            if (ColorUtility.TryParseHtmlString("#" + hex, out c))
            {
                return c;
            }
            return Color.magenta;
        }
    }
}

using TMPro;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 一次性迁移工具：把 UI 预制体里的 **UGUI Text 组件就地替换为 TextMeshProUGUI**。
    ///
    /// 【为什么需要它，而不是直接跑 UIPrefabBuilder 重建】
    ///   UIPrefabBuilder 是「DeleteAsset + 重建」——重建会抹掉人在编辑器里手工做的一切
    ///   （历史上 HudView 手工加过塔按钮、手工调过坐标）。
    ///   本工具是**就地替换组件**：不动节点树、不动 RectTransform、不动按钮与事件，
    ///   只把每个 `Text` 换成 `TextMeshProUGUI`，于是手工成果 100% 保留。
    ///
    /// 【为什么 YAML 手改不行、必须在编辑器里跑】
    ///   Text 与 TextMeshProUGUI 的序列化字段完全不同：
    ///   前者引用 Font + 一堆 horizontalOverflow 字段，后者引用 TMP_FontAsset + 材质；
    ///   且换了组件类型后 m_Script guid 也要换。手工拼 YAML 极易漏字段导致
    ///   "组件丢失 / 字不显示 / prefab 报错"。走 Unity API（AddComponent / DestroyImmediate +
    ///   CopySerializableValues）才是可靠路径。
    ///
    /// 【转移的字段】文本内容、字号、颜色、对齐、是否 raycast —— 视觉尽量等价；
    ///   UGUI 的 Outline 描边组件无法 1:1 转移（TMP 描边是材质属性），
    ///   这里统一给迁移后的文本挂上项目的中文字体描边材质（若存在）。
    ///
    /// 【幂等】已是 TMP 的节点会跳过；重复执行安全。
    ///
    /// 菜单：Tools ▸ 塔防 ▸ 高级（单步重建） ▸ 把 UI 预制体的 Text 迁移为 TextMeshPro
    /// </summary>
    public static class UiTmpMigrator
    {
        /// <summary>需要迁移的 UI 预制体（与 UIPrefabBuilder 生成的六个一致）</summary>
        private static readonly string[] TargetPrefabs =
        {
            "Assets/Prefabs/UI/HudView.prefab",
            "Assets/Prefabs/UI/TipsView.prefab",
            "Assets/Prefabs/UI/TowerInfoView.prefab",
            "Assets/Prefabs/UI/SelectView.prefab",
            "Assets/Prefabs/UI/PauseView.prefab",
            "Assets/Prefabs/UI/SettingView.prefab",
        };

        /// <summary>统一的中文字体描边材质（由 UIPrefabBuilder 生成；不存在则跳过描边）</summary>
        private const string OutlineMaterialPath = "Assets/Font/SiYuanSongTi SDF - Outline.mat";

        [MenuItem("Tools/塔防/高级（单步重建）/把 UI 预制体的 Text 迁移为 TextMeshPro", false, 306)]
        public static void MigrateFromMenu()
        {
            EditorUtil.Report report = new EditorUtil.Report();
            int files = MigrateAll(report);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log(report.Errors > 0
                ? string.Format("[TMP 迁移] 有错误（处理 {0} 个预制体）：\n{1}", files, report.Text)
                : string.Format("[TMP 迁移] 完成（处理 {0} 个预制体）：\n{1}", files, report.Text));
        }

        /// <summary>供向导调用（不弹窗）。返回处理的预制体数量。</summary>
        public static int MigrateAll(EditorUtil.Report report)
        {
            report.Head("Text → TextMeshPro 迁移（就地替换组件）");
            int count = 0;
            for (int i = 0; i < TargetPrefabs.Length; i++)
            {
                if (MigrateOne(TargetPrefabs[i], report))
                {
                    count++;
                }
            }
            return count;
        }

        private static bool MigrateOne(string path, EditorUtil.Report report)
        {
            GameObject root = PrefabUtility.LoadPrefabContents(path);
            if (root == null)
            {
                report.Skip(path + " 不存在，跳过");
                return false;
            }

            TMP_FontAsset font = EditorUtil.GetDefaultTmpFont();
            Material outlineMat = AssetDatabase.LoadAssetAtPath<Material>(OutlineMaterialPath);

            // 收集全部 Text（含隐藏节点：模板按钮通常是 SetActive(false) 的）
            Text[] texts = root.GetComponentsInChildren<Text>(true);
            if (texts.Length == 0)
            {
                PrefabUtility.UnloadPrefabContents(root);
                report.Skip(System.IO.Path.GetFileName(path) + " 没有 UGUI Text，跳过");
                return false;
            }

            int converted = 0;
            for (int i = 0; i < texts.Length; i++)
            {
                Text old = texts[i];
                if (old == null)
                {
                    continue;
                }
                if (ConvertOne(old, font, outlineMat))
                {
                    converted++;
                }
            }

            PrefabUtility.SaveAsPrefabAsset(root, path);
            PrefabUtility.UnloadPrefabContents(root);

            report.Ok(string.Format("{0}：迁移 {1} 个文本组件为 TextMeshProUGUI",
                System.IO.Path.GetFileName(path), converted));
            return true;
        }

        /// <summary>
        /// 把单个 UGUI Text 就地替换为 TextMeshProUGUI。
        /// 【为什么先读旧值再删】删完 old 后访问它会抛异常，所有拷贝必须在 DestoryImmediate 之前完成。
        /// </summary>
        private static bool ConvertOne(Text old, TMP_FontAsset font, Material outlineMat)
        {
            GameObject go = old.gameObject;

            // ---- 先读出旧组件的所有要保留的属性 ----
            string content = old.text;
            int fontSize = old.fontSize;
            Color color = old.color;
            TextAnchor anchor = old.alignment;
            bool raycast = old.raycastTarget;
            FontStyle style = old.fontStyle;

            // ---- 删掉旧的 Text 与它可能带的 Outline（TMP 不支持 UGUI Outline）----
            Object.DestroyImmediate(old, true);
            Outline outline = go.GetComponent<Outline>();
            if (outline != null)
            {
                Object.DestroyImmediate(outline, true);
            }

            // ---- 挂 TMP 组件 ----
            TextMeshProUGUI t = go.GetComponent<TextMeshProUGUI>();
            if (t == null)
            {
                t = go.AddComponent<TextMeshProUGUI>();
            }
            if (font != null)
            {
                t.font = font;
            }
            if (outlineMat != null)
            {
                t.fontSharedMaterial = outlineMat;
            }
            t.text = content;
            t.fontSize = fontSize;
            t.color = color;
            t.alignment = ToTmpAlignment(anchor);
            t.raycastTarget = raycast;
            t.enableWordWrapping = false;
            t.overflowMode = TextOverflowModes.Overflow;

            // 粗体/斜体在 TMP 里是 fontStyles（位标志）；这里显式取或再赋值，
            // 不用 |=（枚举属性上的复合赋值可读性差，也易被误认为原地修改）。
            FontStyles fs = t.fontStyle;
            if ((style & FontStyle.Bold) != 0)
            {
                fs |= FontStyles.Bold;
            }
            if ((style & FontStyle.Italic) != 0)
            {
                fs |= FontStyles.Italic;
            }
            t.fontStyle = fs;

            return true;
        }

        private static TextAlignmentOptions ToTmpAlignment(TextAnchor a)
        {
            switch (a)
            {
                case TextAnchor.UpperLeft:    return TextAlignmentOptions.TopLeft;
                case TextAnchor.UpperCenter:  return TextAlignmentOptions.Top;
                case TextAnchor.UpperRight:   return TextAlignmentOptions.TopRight;
                case TextAnchor.MiddleLeft:   return TextAlignmentOptions.Left;
                case TextAnchor.MiddleCenter: return TextAlignmentOptions.Center;
                case TextAnchor.MiddleRight:  return TextAlignmentOptions.Right;
                case TextAnchor.LowerLeft:    return TextAlignmentOptions.BottomLeft;
                case TextAnchor.LowerCenter:  return TextAlignmentOptions.Bottom;
                case TextAnchor.LowerRight:   return TextAlignmentOptions.BottomRight;
                default:                      return TextAlignmentOptions.Center;
            }
        }
    }
}

using UnityEditor;
using UnityEngine;
using YooAsset;
using YooAsset.Editor;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 把 Main.unity 加入 YooAsset 收集器（一次性工具，幂等）。
    ///
    /// 【为什么需要】HybridCLR 真机上，**挂了热更脚本的场景打进 Build Settings 会
    /// 被烘焙成空壳**（热更程序集在打包的 IFilterBuildAssemblies 阶段被剔除），
    /// 运行时报 "missing script / serialization layout"。
    /// HybridCLR 官方工作流：这类场景必须打包成 AssetBundle，并在热更 dll 加载后加载。
    /// 本工具把 Assets/Scenes/Main.unity 收进 FreeTower 包裹（Scene 组），
    /// 由 HotUpdateEntry.EnterMainScene 在运行时经 YooAsset SceneHandle 加载。
    ///
    /// 【菜单】Tools ▸ 塔防 ▸ YooAsset 接入 ▸ 5. 把 Main.unity 加入收集器
    /// （入口序号 214，跟在 FTYooAssetDefine 的 3/4 之后）
    /// </summary>
    public static class AddMainSceneCollector
    {
        private const string ScenePath = "Assets/Scenes/Main.unity";

        /// <summary>收集计划：路径 → 组名（幂等，已存在的自动跳过）。</summary>
        private static readonly string[][] Plan =
        {
            new[] { ScenePath, "Scene" },
            new[] { "Assets/HotUpdateUI", "BootUI" },
            new[] { "Assets/Localization", "Localization" },
            // 【2026-10-14】Reporter 运行时图标：Reporter 为运行时动态挂载，
            // Initialize 时经 ResTable Reporter_* 逻辑名动态加载图片，必须被 AB 覆盖
            // （真机从热更服务器下发；见 GameSceneLauncher.EnsureReporter 说明）。
            new[] { "Assets/Reporter/Images", "ReporterData" },
        };

        [MenuItem("Tools/塔防/YooAsset 接入/5. 把 Main.unity 加入收集器（真机场景 AB）", false, 214)]
        public static void Run()
        {
            string error;
            Ensure(out error);   // 成败日志均在 Ensure 内输出
        }

        /// <summary>
        /// 幂等登记全部计划项；返回 false 时 error 为可读原因。
        /// 菜单入口只是外壳 —— 无人值守流水线（ReporterHotfixBuild）靠返回值判断成败。
        /// </summary>
        public static bool Ensure(out string error)
        {
            error = string.Empty;
            try
            {
                BundleCollectorPackage package = FindFreeTowerPackage();
                if (package == null)
                {
                    error = "找不到 FreeTower 包裹 —— 请先跑接入向导生成收集器配置。";
                    Debug.LogError("[YooAsset] " + error);
                    return false;
                }

                int added = 0;
                int skipped = 0;

                for (int i = 0; i < Plan.Length; i++)
                {
                    string path = Plan[i][0];
                    string groupName = Plan[i][1];

                    // 幂等：路径已在收集器里直接跳过
                    bool exists = false;
                    foreach (BundleCollectorGroup g in package.Groups)
                    {
                        foreach (BundleCollector c in g.Collectors)
                        {
                            if (c.CollectPath == path)
                            {
                                exists = true;
                                break;
                            }
                        }
                        if (exists) break;
                    }
                    if (exists)
                    {
                        skipped++;
                        continue;
                    }

                    BundleCollectorGroup group = FindOrCreateGroup(package, groupName);
                    BundleCollector collector = new BundleCollector();
                    collector.CollectPath = path;
                    collector.CollectorGUID = AssetDatabase.AssetPathToGUID(path);
                    collector.CollectorType = ECollectorType.MainAssetCollector;
                    // 可寻址已关闭 → 定位地址 = 资源路径，地址规则名字只是占位。
                    collector.AddressRuleName = nameof(AddressByFileName);
                    collector.PackRuleName = nameof(FTBundlePackRule);
                    collector.FilterRuleName = nameof(CollectAll);
                    collector.AssetTags = string.Empty;
                    collector.UserData = string.Empty;
                    group.Collectors.Add(collector);
                    added++;
                    Debug.Log("[YooAsset] 已加入收集器：" + path + "（组 " + groupName + "）");
                }

                if (added > 0)
                {
                    BundleCollectorSettingData.SaveFile();
                    AssetDatabase.SaveAssets();
                }

                Debug.Log(string.Format(
                    "[YooAsset] 收集器更新完成：新增 {0} 个，已有 {1} 个。场景、引导期 UI 与 Reporter 图标均从 AB 加载（HybridCLR 真机要求）。",
                    added, skipped));
                return true;
            }
            catch (System.Exception e)
            {
                error = e.ToString();
                Debug.LogError("[YooAsset] 收集器更新失败：" + e);
                return false;
            }
        }

        /// <summary>按组名找组，没有就创建（与 FTYooAssetSetupWizard.FindOrCreateGroup 同语义）。</summary>
        private static BundleCollectorGroup FindOrCreateGroup(BundleCollectorPackage package, string groupName)
        {
            foreach (BundleCollectorGroup g in package.Groups)
            {
                if (g.GroupName == groupName)
                {
                    return g;
                }
            }

            BundleCollectorGroup newGroup = new BundleCollectorGroup();
            newGroup.GroupName = groupName;
            newGroup.GroupDesc = "HybridCLR 真机：挂热更脚本的资源必须从 AB 加载";
            newGroup.ActiveRuleName = nameof(EnableGroup);
            package.Groups.Add(newGroup);
            return newGroup;
        }

        /// <summary>找名为 FreeTower 的包裹（与 YooAssetResLoader.PackageName 对应），找不到退回第一个。</summary>
        private static BundleCollectorPackage FindFreeTowerPackage()
        {
            BundleCollectorPackage first = null;
            foreach (BundleCollectorPackage p in BundleCollectorSettingData.Setting.Packages)
            {
                if (p.PackageName == "FreeTower")
                {
                    return p;
                }
                if (first == null)
                {
                    first = p;
                }
            }
            return first;
        }
    }
}

#if USE_YOOASSET
using System;
using System.Collections.Generic;
using YooAsset.Editor;

namespace FTProject.EditorTools
{
    /// <summary>
    /// 塔防分包规则：**按 ResTable 决定每个资源进哪个资源包**。
    ///
    /// 【为什么不能直接用 YooAsset 的目录规则】
    ///   本工程的分包是**跨目录按玩法语义**分的，任何"按目录"的规则都复现不出来：
    ///     - `enemy_rats` 同时含 `Assets/Prefabs/Enemy/Enemy_Rat.prefab`
    ///       与 `Assets/_UIAssets/Monsters/Rats/Rat/Rat.png`（prefab 与图集分居两棵树）；
    ///     - `tower_normal` 同时含 `Assets/Prefabs/Tower/Normal/*` 与
    ///       `Assets/_UIAssets/Tower/Normal/*`。
    ///   而 ResTable 已经把"哪个资源属于哪个包"写死了（Bundle 字段），
    ///   所以这里直接读它 —— 保持"ResTable 是唯一寻址源"这条工程铁律，
    ///   与既有 `ABNameSetter` 用的是同一份数据，不会出现两套规则分叉。
    ///
    /// 【未登记资源怎么办】按三级降级，且**全部记入报告**（向导会打出来）：
    ///   ① 同目录已有登记资源 → 跟随它（图集、材质等依赖自然落进同一个包）
    ///   ② 向上找最近的"有登记资源的祖先目录" → 跟随它
    ///   ③ 都没有 → `misc_<顶层目录名>` 兜底
    ///   注意：ResTable 只登记"要主动加载"的资源，而 YooAsset 收集的是整个目录树，
    ///   所以①/②命中是常态（例如字体图集、怪物源预制体），③是真正的异常信号。
    ///
    /// ⚠️ 本类被 YooAsset 通过 `TypeCache.GetTypesDerivedFrom(IBundlePackRule)` 自动发现，
    ///    不需要注册；但**必须在收集器的"打包规则"列里选中它**（向导生成的配置已经选好）。
    /// </summary>
    [DisplayName("塔防：按 ResTable 分包（enemy_xxx / tower_normal …）")]
    public class FTBundlePackRule : IBundlePackRule
    {
        /// <summary>兜底包名前缀</summary>
        public const string FallbackPrefix = "misc_";

        /// <summary>资源路径 → 资源包名（来自 ResTable，精确匹配优先）</summary>
        private static Dictionary<string, string> s_byAssetPath;

        /// <summary>目录 → 资源包名（用于"跟随同目录已登记资源"）</summary>
        private static Dictionary<string, string> s_byDirectory;

        /// <summary>本次收集期间遇到的"ResTable 里没登记"的资源：资源路径 → 「去向 + 原因」</summary>
        private static readonly Dictionary<string, string> s_unregistered =
            new Dictionary<string, string>(StringComparer.Ordinal);

        // ==================================================================
        // 报告（向导读取）
        // ==================================================================

        /// <summary>清空未登记报告。每次校验/构建前调用一次。</summary>
        public static void ResetReport()
        {
            s_unregistered.Clear();
        }

        /// <summary>未登记资源条目数</summary>
        public static int UnregisteredCount
        {
            get { return s_unregistered.Count; }
        }

        /// <summary>未登记资源报告（按路径排序，便于比对）</summary>
        public static List<string> GetUnregisteredReport()
        {
            List<string> lines = new List<string>(s_unregistered.Count);
            foreach (KeyValuePair<string, string> kv in s_unregistered)
            {
                lines.Add(kv.Key + "  →  " + kv.Value);
            }
            lines.Sort(StringComparer.Ordinal);
            return lines;
        }

        // ==================================================================
        // IBundlePackRule
        // ==================================================================

        public BundlePackRuleResult GetPackRuleResult(BundlePackRuleData data)
        {
            string bundle = ResolveBundle(data.AssetPath);
            return new BundlePackRuleResult(bundle, DefaultBundlePackRule.AssetBundleFileExtension);
        }

        /// <summary>
        /// 给定资源路径，算出应该进哪个资源包。
        /// 公开是为了让接入向导能"离线复算一遍"并与 ResTable 比对（见静态校验）。
        /// </summary>
        public static string ResolveBundle(string assetPath)
        {
            EnsureIndex();

            string path = Normalize(assetPath);
            if (path.Length == 0)
            {
                return FallbackPrefix + "unknown";
            }

            string bundle;
            if (s_byAssetPath.TryGetValue(path, out bundle))
            {
                return bundle;
            }

            // ① / ② 跟随同目录、或最近的有登记资源的祖先目录
            string dir = GetDirectory(path);
            while (dir.Length > 0)
            {
                if (s_byDirectory.TryGetValue(dir, out bundle))
                {
                    Record(path, bundle, "跟随同树已登记资源所在包（" + dir + "）");
                    return bundle;
                }

                string parent = GetDirectory(dir);
                if (parent.Length == 0 || string.Equals(parent, dir, StringComparison.Ordinal))
                {
                    break;
                }
                dir = parent;
            }

            // ③ 兜底
            bundle = FallbackPrefix + Sanitize(TopFolder(path));
            Record(path, bundle, "无已登记资源可跟随，按顶层目录兜底");
            return bundle;
        }

        // ==================================================================
        // 索引
        // ==================================================================

        private static void EnsureIndex()
        {
            if (s_byAssetPath != null)
            {
                return;
            }

            s_byAssetPath = new Dictionary<string, string>(1024, StringComparer.Ordinal);
            s_byDirectory = new Dictionary<string, string>(512, StringComparer.Ordinal);

            foreach (KeyValuePair<string, ResAddress> kv in ResTable.All)
            {
                string path = Normalize(kv.Value.EditorPath);
                if (path.Length == 0 || string.IsNullOrEmpty(kv.Value.Bundle))
                {
                    continue;
                }

                // 同一个资源可能被多个逻辑名指向（如 Cell_Buildable 与 Cell_Ground 同文件），
                // 只要包名一致就无歧义；真出现不一致时保留先登记的，并在向导报告里体现不出来 ——
                // 这种情况属于 ResTable 配置错误，跑 verify 的"包名一致性"检查会报出来。
                if (s_byAssetPath.ContainsKey(path) == false)
                {
                    s_byAssetPath.Add(path, kv.Value.Bundle);
                }

                string dir = GetDirectory(path);
                if (dir.Length > 0 && s_byDirectory.ContainsKey(dir) == false)
                {
                    s_byDirectory.Add(dir, kv.Value.Bundle);
                }
            }
        }

        private static void Record(string assetPath, string bundle, string reason)
        {
            if (s_unregistered.ContainsKey(assetPath))
            {
                return;
            }
            s_unregistered.Add(assetPath, bundle + "（" + reason + "）");
        }

        // ==================================================================
        // 路径小工具
        // ==================================================================

        private static string Normalize(string path)
        {
            if (string.IsNullOrEmpty(path))
            {
                return string.Empty;
            }
            return path.Replace('\\', '/');
        }

        private static string GetDirectory(string assetPath)
        {
            int idx = assetPath.LastIndexOf('/');
            return idx <= 0 ? string.Empty : assetPath.Substring(0, idx);
        }

        private static string TopFolder(string assetPath)
        {
            const string prefix = "Assets/";
            if (assetPath.StartsWith(prefix, StringComparison.Ordinal))
            {
                string rest = assetPath.Substring(prefix.Length);
                int idx = rest.IndexOf('/');
                return idx < 0 ? "root" : rest.Substring(0, idx);
            }
            return "external";
        }

        /// <summary>包名只保留字母数字下划线并转小写（与 ResBundle 的命名规范一致）。</summary>
        private static string Sanitize(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return "unknown";
            }

            char[] chars = name.ToCharArray();
            for (int i = 0; i < chars.Length; i++)
            {
                char c = chars[i];
                bool ok = (c >= 'a' && c <= 'z')
                          || (c >= 'A' && c <= 'Z')
                          || (c >= '0' && c <= '9')
                          || c == '_';
                if (ok == false)
                {
                    chars[i] = '_';
                }
            }

            string result = new string(chars).Trim('_').ToLowerInvariant();
            return result.Length == 0 ? "unknown" : result;
        }
    }
}
#endif

using System;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.Build;
using UnityEngine;

namespace FTProject.EditorTools
{
    /// <summary>
    /// YooAsset 编译宏 <c>USE_YOOASSET</c> 的开关。
    ///
    /// 【为什么单独一个文件、且刻意不套宏 —— 这是一个"鸡生蛋"问题】
    ///   工程约定"新依赖一律加宏"，于是 <c>YooAssetResLoader</c>、YooAsset 打包规则、
    ///   接入向导全部包在 <c>#if USE_YOOASSET</c> 里。但那样一来，宏本身就没法靠这些
    ///   代码去打开。所以宏开关单独放这里，**不引用任何 YooAsset 类型**，
    ///   保证在宏关闭（= 包没拉下来 / 想回退旧链路）时本文件依然能编译、能执行。
    ///
    /// 【为什么一次写多个平台】编译宏是**按平台组**存的，不是全局的。
    ///   只给当前平台加，换平台出包时会静默失效，运行时才发现"换回了旧加载器"。
    ///
    /// 【与既有 FORCE_AB 的关系】两者是独立的开关，叠在一起的含义见 ResLoader.cs：
    ///   USE_YOOASSET 决定"用不用 YooAsset"；FORCE_AB 决定 YooAsset 内部走
    ///   "编辑器模拟模式"还是"真资源包（离线模式）"。
    /// </summary>
    public static class FTYooAssetDefine
    {
        /// <summary>编译宏名。运行时适配器与编辑器工具都以此为准。</summary>
        public const string Symbol = "USE_YOOASSET";

        /// <summary>
        /// 热更编译宏名。打开后 YooAsset 走 HostPlayMode（联机模式），
        /// 启动时去 <c>ResServerConfig.ServerUrl</c> 比对版本并下载差异。
        ///
        /// 【为什么与 USE_YOOASSET 分开两个宏】
        ///   两者正交：
        ///     USE_YOOASSET → "用不用 YooAsset 这套资源系统"
        ///     FT_HOTUPDATE → "用 YooAsset 时，从本地包读还是从远端下载"
        ///   合并成一个宏的话，"想在编辑器里验证离线包"与"真机走热更"就无法共存了。
        /// </summary>
        public const string HotUpdateSymbol = "FT_HOTUPDATE";

        /// <summary>
        /// 一并处理的平台组。工程实际出包是 Standalone + Android，iOS/WebGL 顺带写上，
        /// 避免将来新增平台时漏配。
        /// </summary>
        private static readonly NamedBuildTarget[] Targets =
        {
            NamedBuildTarget.Standalone,
            NamedBuildTarget.Android,
            NamedBuildTarget.iOS,
            NamedBuildTarget.WebGL,
        };

        // ==================================================================
        // 菜单
        // ==================================================================

        [MenuItem("Tools/塔防/YooAsset 接入/1. 启用 USE_YOOASSET 宏", false, 210)]
        public static void Enable()
        {
            Apply(true);
        }

        [MenuItem("Tools/塔防/YooAsset 接入/2. 停用 USE_YOOASSET 宏（回退原链路）", false, 211)]
        public static void Disable()
        {
            Apply(false);
        }

        // ------------------------------------------------------------------
        // 热更宏（FT_HOTUPDATE）
        // ------------------------------------------------------------------

        [MenuItem("Tools/塔防/YooAsset 接入/3. 启用 FT_HOTUPDATE 宏（真机热更）", false, 212)]
        public static void EnableHotUpdate()
        {
            ApplySymbol(HotUpdateSymbol, true);
        }

        [MenuItem("Tools/塔防/YooAsset 接入/4. 停用 FT_HOTUPDATE 宏（离线模式）", false, 213)]
        public static void DisableHotUpdate()
        {
            ApplySymbol(HotUpdateSymbol, false);
        }

        [MenuItem("Tools/塔防/YooAsset 接入/0. 查看宏状态", false, 209)]
        public static void ReportStatus()
        {
            List<string> on = new List<string>();
            List<string> off = new List<string>();
            List<string> hotOn = new List<string>();
            List<string> hotOff = new List<string>();

            for (int i = 0; i < Targets.Length; i++)
            {
                NamedBuildTarget target = Targets[i];
                try
                {
                    string symbols = PlayerSettings.GetScriptingDefineSymbols(target);
                    if (HasSymbol(symbols, Symbol))
                    {
                        on.Add(target.TargetName);
                    }
                    else
                    {
                        off.Add(target.TargetName);
                    }

                    if (HasSymbol(symbols, HotUpdateSymbol))
                    {
                        hotOn.Add(target.TargetName);
                    }
                    else
                    {
                        hotOff.Add(target.TargetName);
                    }
                }
                catch (Exception e)
                {
                    off.Add(target.TargetName + "(读取失败:" + e.GetType().Name + ")");
                    hotOff.Add(target.TargetName + "(读取失败:" + e.GetType().Name + ")");
                }
            }

            Debug.Log(string.Format(
                "[YooAsset] 宏状态\n" +
                "  USE_YOOASSET 已启用平台：{0}\n" +
                "  USE_YOOASSET 未启用平台：{1}\n" +
                "  FT_HOTUPDATE 已启用平台：{2}\n" +
                "  FT_HOTUPDATE 未启用平台：{3}\n" +
                "  当前加载器实现：{4}\n" +
                "  当前平台：{5}\n" +
                "  热更服务器地址：{6}（ResServerConfig 常量，编辑器下仅供参考；\n" +
                "    真机以 APK 内打包的值 + persistentDataPath/server.txt 覆盖为准）",
                on.Count == 0 ? "（无）" : string.Join("、", on.ToArray()),
                off.Count == 0 ? "（无）" : string.Join("、", off.ToArray()),
                hotOn.Count == 0 ? "（无）" : string.Join("、", hotOn.ToArray()),
                hotOff.Count == 0 ? "（无）" : string.Join("、", hotOff.ToArray()),
                ResLoader.ImplName,
                EditorUserBuildSettings.activeBuildTarget,
                ResServerConfig.ServerUrl));
        }

        // ==================================================================
        // 实现
        // ==================================================================

        /// <summary>当前在 Build Settings 里选中的平台是否已启用宏（向导状态面板用）。</summary>
        public static bool IsEnabledForActiveTarget()
        {
            try
            {
                // 用 selectedBuildTargetGroup 而不是 BuildPipeline.GetBuildTargetGroup：
                // 后者在 Unity 2022 的官方 API 文档里已经查不到（即将废弃）。
                NamedBuildTarget target = NamedBuildTarget.FromBuildTargetGroup(
                    EditorUserBuildSettings.selectedBuildTargetGroup);
                return HasSymbol(PlayerSettings.GetScriptingDefineSymbols(target), Symbol);
            }
            catch (Exception)
            {
                return false;
            }
        }

        private static void Apply(bool enable)
        {
            ApplySymbol(Symbol, enable);
        }

        /// <summary>
        /// 在全部目标平台上开关一个宏。
        /// 【为什么要按平台组遍历】编译宏是按平台组存的；只改当前平台会静默失效。
        /// 【为什么异常要跳过而不是中断】iOS/WebGL 等平台组在部分环境下不可读写，
        ///   中断会导致"改到一半"，其余平台漏改 —— 统一收集后一并告警更清晰。
        /// </summary>
        private static void ApplySymbol(string symbol, bool enable)
        {
            List<string> changed = new List<string>();
            List<string> skipped = new List<string>();

            for (int i = 0; i < Targets.Length; i++)
            {
                NamedBuildTarget target = Targets[i];
                string name = target.TargetName;

                try
                {
                    string before = PlayerSettings.GetScriptingDefineSymbols(target);
                    string after = Toggle(before, symbol, enable);

                    if (string.Equals(before ?? string.Empty, after, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    PlayerSettings.SetScriptingDefineSymbols(target, after);
                    changed.Add(string.Format("  {0}：{1} → {2}",
                        name,
                        string.IsNullOrEmpty(before) ? "(空)" : before,
                        string.IsNullOrEmpty(after) ? "(空)" : after));
                }
                catch (Exception e)
                {
                    // 某些平台组在当前环境不可读写；跳过而不是中断，其余平台照常处理。
                    skipped.Add(string.Format("  {0}：跳过（{1}）", name, e.GetType().Name));
                }
            }

            AssetDatabase.Refresh();

            string action = enable ? "启用" : "停用";
            if (changed.Count == 0)
            {
                Debug.Log(string.Format("[YooAsset] {0} 在所有目标平台上都已是「{1}」状态，无需改动。", symbol, action));
            }
            else
            {
                Debug.Log(string.Format("[YooAsset] 已{0} {1}，改动 {2} 个平台：\n{3}\n" +
                    "  Unity 正在重新编译；编译完成后菜单「Tools ▸ 塔防 ▸ YooAsset 接入 ▸ 接入向导」才可用。",
                    action, symbol, changed.Count, string.Join("\n", changed.ToArray())));
            }

            if (skipped.Count > 0)
            {
                Debug.LogWarning("[YooAsset] 以下平台未能读写（若确实需要，请在 Player Settings 里手工添加）:\n"
                    + string.Join("\n", skipped.ToArray()));
            }
        }

        /// <summary>在分号分隔的宏列表里增删一个宏；保持原有顺序，不产生空项。</summary>
        private static string Toggle(string symbols, string symbol, bool enable)
        {
            List<string> list = new List<string>();
            if (string.IsNullOrEmpty(symbols) == false)
            {
                string[] parts = symbols.Split(';');
                for (int i = 0; i < parts.Length; i++)
                {
                    string s = parts[i].Trim();
                    if (s.Length == 0)
                    {
                        continue;
                    }
                    if (string.Equals(s, symbol, StringComparison.Ordinal))
                    {
                        continue;
                    }
                    if (list.Contains(s) == false)
                    {
                        list.Add(s);
                    }
                }
            }

            if (enable && list.Contains(symbol) == false)
            {
                list.Add(symbol);
            }

            return string.Join(";", list.ToArray());
        }

        private static bool HasSymbol(string symbols, string symbol)
        {
            if (string.IsNullOrEmpty(symbols))
            {
                return false;
            }

            string[] parts = symbols.Split(';');
            for (int i = 0; i < parts.Length; i++)
            {
                if (string.Equals(parts[i].Trim(), symbol, StringComparison.Ordinal))
                {
                    return true;
                }
            }
            return false;
        }
    }
}

