                Bytes[WriterIndex + 1] = (byte)(x >> 16);
                Bytes[WriterIndex] = (byte)((x >> 24) | 0xe0);
                WriterIndex += 4;
            }
            else
            {
                EnsureWrite(5);
                Bytes[WriterIndex] = 0xf0;
                Bytes[WriterIndex + 4] = (byte)x;
                Bytes[WriterIndex + 3] = (byte)(x >> 8);
                Bytes[WriterIndex + 2] = (byte)(x >> 16);
                Bytes[WriterIndex + 1] = (byte)(x >> 24);
                WriterIndex += 5;
            }
