                WriterIndex += 2;
            }
            else if (x < 0x200000) // 110 1 1111, -,-
            {
                EnsureWrite(3);

                fixed (byte* wb = &Bytes[WriterIndex])
                {
                    *(uint*)(wb) = (x << 3 | 0b011);
                }
                WriterIndex += 3;
            }
            else if (x < 0x10000000) // 1110 1111,-,-,-
            {
                EnsureWrite(4);
                fixed (byte* wb = &Bytes[WriterIndex])
                {
