                    ReaderIndex += 4;
                    return (*(uint*)rb) >> 4;
                }
            }
            else
            {
                EnsureRead(5);
                fixed (byte* rb = &Bytes[ReaderIndex])
                {
                    ReaderIndex += 5;
                    return (*(uint*)rb) >> 5;
                }
            }
