            unsafe
            {
                fixed (byte* b = &Bytes[WriterIndex])
                {
#if !CPU_SUPPORT_MEMORY_NOT_ALIGN
                    if ((long)b % 4 == 0)
                    {
                        *(float*)b = x;
                    }
                    else
                    {
                        Copy4(b, (byte*)&x);
                    }
#else
                    *(float*)b = x;
#endif
                }
            }

            //if (!BitConverter.IsLittleEndian)
            //{
            //    Array.Reverse(data, endPos, 4);
