        public float ReadFloat()
        {
            EnsureRead(4);
            //if (!BitConverter.IsLittleEndian)
            //{
            //    Array.Reverse(data, beginPos, 4);
            //}
            float x;
            unsafe
            {
                fixed (byte* b = &Bytes[ReaderIndex])
                {
#if !CPU_SUPPORT_MEMORY_NOT_ALIGN
                    if ((long)b % 4 == 0)
                    {
                        x = *(float*)b;
                    }
                    else
                    {
                        *((int*)&x) = (b[0]) | (b[1] << 8) | (b[2] << 16) | (b[3] << 24);
                    }
#else
                    x = *(float*)b;
#endif
                }
            }

            ReaderIndex += 4;
            return x;
        }

