	#region #5 Tween Steps

	IEnumerator TweenDelay(){
		delayStarted = Time.time;
		yield return new WaitForSeconds (delay);
		if(wasPaused){
			wasPaused=false;
			TweenStart();	
		}
	}	

	void TweenStart(){		
		CallBack("onstart");

		if(!loop){//only if this is not a loop
			ConflictCheck();
			GenerateTargets();
		}

		//run stab:
		if(type == "stab"){
			audioSource.PlayOneShot(audioSource.clip);
		}

		//toggle isKinematic for iTweens that may interfere with physics:
		if (type == "move" || type=="scale" || type=="rotate" || type=="punch" || type=="shake" || type=="curve" || type=="look") {
			EnableKinematic();
		}

		isRunning = true;
	}

	IEnumerator TweenRestart(){
		if(delay > 0){
			delayStarted = Time.time;
			yield return new WaitForSeconds (delay);
		}
		loop=true;
		TweenStart();
	}	

	void TweenUpdate(){
		apply();
		CallBack("onupdate");
		UpdatePercentage();		
	}

	void TweenComplete(){
		isRunning=false;

		//dial in percentage to 1 or 0 for final run:
		if(percentage>.5f){
			percentage=1f;
		}else{
			percentage=0;	
		}

		//apply dial in and final run:
		apply();
		if(type == "value"){
			CallBack("onupdate"); //CallBack run for ValueTo since it only calculates and applies in the update callback
		}

		//loop or dispose?
		if(loopType==LoopType.none){
			Dispose();
		}else{
			TweenLoop();
		}

		CallBack("oncomplete");
	}

	void TweenLoop(){
		DisableKinematic(); //give physics control again
		switch(loopType){
			case LoopType.loop:
				//rewind:
				percentage=0;
				runningTime=0;
				apply();

				//replay:
				StartCoroutine("TweenRestart");
				break;
			case LoopType.pingPong:
				reverse = !reverse;
				runningTime=0;

				//replay:
				StartCoroutine("TweenRestart");
				break;
		}
	}	

