using System.Collections.Generic;
using AStar;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// A* 寻路管理器（v2.1 的 2D 版）。
    ///
    /// 相对 v1.0 的改动：
    ///   - **只建数据**：不再生成任何 GameObject / LineRenderer（格子由 BoardView 生成）
    ///   - 地图来源从 `StreamingAssets/Map/Map*.txt` 改为 **TBLevelMap 配置表**
    ///   - 新增路径重算节流（RequestRefresh / ProcessRefresh），避免布塔时集中重算卡顿
    ///   - 每次搜索前重置节点的 G/H/Parent —— v1.0 未重置，复用网格时会被上次结果污染
    ///   - GetAStarPath 增加**迭代上限**，杜绝 Parent 链断裂导致的死循环
    ///
    /// 坐标：(row, col) → 世界坐标由 BoardGeometry 统一换算，Center 缓存在 Point 上。
    /// </summary>
    public class AStarManager : BaseManager<AStarManager>
    {
        /// <summary>网格宽度（= 列数 cols，即 X 方向的长度）</summary>
        public int MapWidth { get; private set; }

        /// <summary>网格高度（= 行数 rows，即 Y 方向的长度）</summary>
        public int MapHeight { get; private set; }

        /// <summary>
        /// 网格。
        /// 【索引约定】**`map[col, row]`**，即第一维是列、第二维是行。
        ///
        /// 这个约定不是随意定的，而是**必须服从 AStarWrapper 插件**：
        /// 它内部用 `Point.X` 表示横轴（用 `mapWidth` 做边界判断）、
        /// `Point.Y` 表示纵轴（用 `mapHeight` 做边界判断），并直接 `map[point.X, point.Y]`。
        /// 也就是说 **X = 列、Y = 行**。
        ///
        /// 【踩过的坑】最初写成 `new Point[rows, cols]` 且 `Point(row, col)`（X=行、Y=列），
        /// 两个轴的语义同时反了。后果是插件的边界判断 `point.X &lt; mapWidth - 1`
        /// 实际变成 `row &lt; 15`（恒真），于是 `map[row + 1, col]` 在最后一行越界，
        /// 抛出 IndexOutOfRangeException —— 而该异常又会被事件系统的 try/catch 吞掉，
        /// 表现为"地图生成了、但既没有路径、也没有 HUD、也没有怪物"。
        /// </summary>
        public Point[,] Map { get; private set; }

        public Point StartPoint { get; private set; }
        public Point TargetPoint { get; private set; }

        public bool IsGridReady { get { return Map != null; } }

        /// <summary>当前最短路径的世界坐标（含首尾），供路径箭头渲染</summary>
        public Vector3[] CurrentPathWorld { get; private set; }

        /// <summary>
        /// 放置预览路径的世界坐标（"如果在这一格建塔，怪物会改走哪里"）。null = 当前没有预览。
        ///
        /// ★ 必须与 <see cref="CurrentPathWorld"/> 严格分开：
        ///   CurrentPathWorld 是**已生效**的路径，怪物行走与路径箭头都读它；
        ///   PreviewPathWorld 只是玩家在棋盘上滑动时的**推演结果**，
        ///   怪物逻辑一行都不读 —— 预览期间怪物继续按旧路径走，松手建成后才改道。
        /// </summary>
        public Vector3[] PreviewPathWorld { get; private set; }

        private bool _refreshRequested;
        private int _lastPathHash = -1;
        private readonly List<Point> _pathBuffer = new List<Point>(512);

        public override void OnInit()
        {
            base.OnInit();
        }

        public override void OnDestroy()
        {
            base.OnDestroy();
            Map = null;
            StartPoint = null;
            TargetPoint = null;
            CurrentPathWorld = null;
            PreviewPathWorld = null;
        }

        // ------------------------------------------------------------------
        // 网格构建
        // ------------------------------------------------------------------

        /// <summary>
        /// 按配置构建寻路网格（只建数据，不生成任何物件）。
        /// </summary>
        public void BuildGrid(LevelMapConfig map, float cellSize, Vector2 origin)
        {
            if (map == null)
            {
                Debug.LogError("[AStar] BuildGrid 收到 null 配置，寻路不可用");
                return;
            }

            MapWidth = map.Cols;      // X 方向 = 列数
            MapHeight = map.Rows;     // Y 方向 = 行数
            // 第一维是列、第二维是行（必须与 AStarWrapper 的 map[point.X, point.Y] 一致）
            Map = new Point[MapWidth, MapHeight];
            StartPoint = null;
            TargetPoint = null;

            for (int r = 0; r < MapHeight; r++)
            {
                for (int c = 0; c < MapWidth; c++)
                {
                    char ch = map.GetCell(r, c);
                    CellType type = BoardGeometry.ParseCell(ch);

                    // Point(X=列, Y=行)
                    Point p = new Point(c, r);
                    p.IsWall = !BoardGeometry.IsWalkable(type);
                    p.Center = BoardGeometry.CellCenter(r, c, cellSize, origin);
                    Map[c, r] = p;

                    if (type == CellType.Spawn)
                    {
                        StartPoint = p;
                    }
                    else if (type == CellType.End)
                    {
                        TargetPoint = p;
                    }
                }
            }

            // 自检：数组维度必须与插件使用的 mapWidth/mapHeight 匹配，
            // 否则边界判断会失效并导致越界（这正是之前的故障原因）
            if (Map.GetLength(0) != MapWidth || Map.GetLength(1) != MapHeight)
            {
                Debug.LogError(string.Format(
                    "[AStar] 网格维度与声明不一致：数组 [{0},{1}] vs mapWidth={2} mapHeight={3}",
                    Map.GetLength(0), Map.GetLength(1), MapWidth, MapHeight));
            }

            if (StartPoint == null || TargetPoint == null)
            {
                Debug.LogError("[AStar] 网格缺少起点(S)或终点(E)，无法寻路");
            }

            _lastPathHash = -1;
            // 换关/重开时旧关的预览必须作废，否则新地图上会飘着上一关的箭头
            PreviewPathWorld = null;
            RecomputePath(force: true);
        }

        /// <summary>把某格设为/取消占位（建塔时临时校验用）</summary>
        public void SetWall(int row, int col, bool isWall)
        {
            Point p = GetPoint(row, col);
            if (p != null)
            {
                p.IsWall = isWall;
            }
        }

        public Point GetPoint(int row, int col)
        {
            if (Map == null || row < 0 || row >= MapHeight || col < 0 || col >= MapWidth)
            {
                return null;
            }
            return Map[col, row];   // 第一维是列
        }

        public Point GetEndPoint()
        {
            return TargetPoint;
        }

        // ------------------------------------------------------------------
        // 寻路
        // ------------------------------------------------------------------

        /// <summary>起点到终点是否连通（建塔校验用）</summary>
        public bool IsFindPath()
        {
            return IsFindPath(StartPoint, TargetPoint);
        }

        public bool IsFindPath(Point from, Point to)
        {
            if (Map == null || from == null || to == null)
            {
                return false;
            }
            ResetAllSearchState();
            return AStarWrapper.Instance.FindPath(from, to, Map, MapWidth, MapHeight);
        }

        /// <summary>
        /// 起点 → 终点的完整路径（**含首尾**）。
        /// 注意与 v1.0 的差异：v1.0 的 GetAStarPath 不含起点，需要额外处理；此处直接给全。
        /// </summary>
        public List<Point> GetPath()
        {
            return GetAStarPath(StartPoint, TargetPoint);
        }

        /// <summary>从某个敌人当前所在格重新寻路到终点</summary>
        public List<Point> UpdatePathByEnemyPoint(Point from)
        {
            if (from == null)
            {
                return null;
            }
            return GetAStarPath(from, TargetPoint);
        }

        /// <summary>
        /// 回溯 Parent 链得到路径（含起点与终点）。
        /// 带迭代上限，防止 Parent 链断裂时死循环。
        /// </summary>
        public List<Point> GetAStarPath(Point from, Point to)
        {
            List<Point> result = new List<Point>(256);
            if (Map == null || from == null || to == null)
            {
                return result;
            }

            ResetAllSearchState();
            if (!AStarWrapper.Instance.FindPath(from, to, Map, MapWidth, MapHeight))
            {
                return result;
            }

            // 回溯：[to, ..., from]，随后反转
            int guard = MapWidth * MapHeight + 2;
            Point cur = to;
            while (cur != null && guard-- > 0)
            {
                result.Add(cur);
                if (cur == from)
                {
                    break;
                }
                cur = cur.Parent;
            }

            if (guard <= 0)
            {
                Debug.LogError("[AStar] 路径回溯超出迭代上限，Parent 链可能已断裂");
                result.Clear();
                return result;
            }
            if (cur != from)
            {
                // Parent 链没走到起点，说明路径不完整
                result.Clear();
                return result;
            }

            result.Reverse();
            return result;
        }

        /// <summary>每次搜索前重置所有节点的寻路状态</summary>
        private void ResetAllSearchState()
        {
            if (Map == null)
            {
                return;
            }
            for (int r = 0; r < MapHeight; r++)
            {
                for (int c = 0; c < MapWidth; c++)
                {
                    Point p = Map[c, r];
                    if (p != null)
                    {
                        p.ResetSearchState();
                    }
                }
            }
        }

        // ------------------------------------------------------------------
        // 放置预览（只推演，不落地）
        // ------------------------------------------------------------------

        /// <summary>
        /// 推演"临时把 (row, col) 设为墙"之后，起点 → 终点的完整路径。
        ///
        /// 【只读语义 —— 这是"预览不作用于怪物"的全部实现依据】
        ///   进来时记下该格原本的 IsWall，算完**立刻还原**（try/finally 保证异常路径也还原）；
        ///   全程不写 CurrentPathWorld、不动 _lastPathHash、不置 _refreshRequested、
        ///   也不发 RefreshPathEvent。所以玩家在棋盘上怎么滑，怪物都不会改道，
        ///   路径箭头（读 CurrentPathWorld）也保持原样。
        ///
        /// 【为什么预览一定等于落地后的真实路径】
        ///   落地时（`TowerManager.TryBuildInternal`）做的是同一件事：该格 IsWall 置真 → 跑一次 A*。
        ///   两边共用同一个网格、同一套搜索、同一对起终点（StartPoint → TargetPoint），
        ///   唯一区别只是"算完要不要把墙标记留下"。没有第二套算法，也就没有"预览和实际不一样"的可能。
        ///
        /// 【返回值】世界坐标路径（含首尾）；null = 这格建上去会让起点到终点不可达（= 会堵死路径），
        /// 或网格尚未就绪。调用方据此判定"不可建造"。
        /// </summary>
        public Vector3[] ComputePathWithExtraWall(int row, int col)
        {
            if (Map == null || StartPoint == null || TargetPoint == null)
            {
                return null;
            }
            Point point = GetPoint(row, col);
            // 已经是墙的格子没有"临时设墙"的语义，直接判为不可用
            if (point == null || point.IsWall)
            {
                return null;
            }

            bool oldWall = point.IsWall;
            Vector3[] world;
            try
            {
                point.IsWall = true;
                world = ToWorldPath(GetPath());
            }
            finally
            {
                // ★ 必须还原：预览是"假设"，地图绝不能因为玩家滑过就被改坏
                point.IsWall = oldWall;
            }
            return world != null && world.Length >= 2 ? world : null;
        }

        /// <summary>
        /// 显示放置预览路径（只驱动箭头显示，不驱动怪物）。
        /// 每次悬停格变化调用一次；长度 &lt; 2 时等价于 <see cref="ClearPreviewPath"/>。
        /// </summary>
        public void ShowPreviewPath(Vector3[] world)
        {
            if (world == null || world.Length < 2)
            {
                ClearPreviewPath();
                return;
            }
            PreviewPathWorld = world;
            EventDispatcher.TriggerEvent(EventName.PreviewPathEvent);
        }

        /// <summary>清掉放置预览（退出放置态 / 悬停到不可建格 / 建塔落地后调用）。</summary>
        public void ClearPreviewPath()
        {
            if (PreviewPathWorld == null)
            {
                return;
            }
            PreviewPathWorld = null;
            EventDispatcher.TriggerEvent(EventName.PreviewPathEvent);
        }

        /// <summary>把寻路结果转成世界坐标数组（渲染用）</summary>
        private static Vector3[] ToWorldPath(List<Point> path)
        {
            if (path == null)
            {
                return null;
            }
            Vector3[] world = new Vector3[path.Count];
            for (int i = 0; i < path.Count; i++)
            {
                world[i] = new Vector3(path[i].Center.x, path[i].Center.y, 0f);
            }
            return world;
        }

        // ------------------------------------------------------------------
        // 路径刷新节流
        // ------------------------------------------------------------------

        /// <summary>请求重算路径（建塔/拆塔后调用）。只置脏标记，真正重算在下一次 ProcessRefresh。</summary>
        public void RequestRefresh()
        {
            _refreshRequested = true;
        }

        /// <summary>
        /// 每帧由 CombatSystem 调用，最多重算 Configs.Global.CheckOfflinePerFrame 次。
        /// 路径发生变化时广播 RefreshPathEvent，敌人据此改道。
        /// </summary>
        public void ProcessRefresh()
        {
            if (!_refreshRequested || Map == null)
            {
                return;
            }
            _refreshRequested = false;
            RecomputePath(force: false);
        }

        private void RecomputePath(bool force)
        {
            _pathBuffer.Clear();
            List<Point> path = GetPath();

            if (path.Count == 0)
            {
                Debug.LogWarning("[AStar] 起点到终点不可达！可能是配置表里存在完全阻断，或建塔把路堵死了。");
                CurrentPathWorld = null;
                _lastPathHash = -1;
                return;
            }

            int hash = ComputePathHash(path);
            bool changed = force || hash != _lastPathHash;
            _lastPathHash = hash;

            // 缓存世界坐标供路径箭头渲染
            CurrentPathWorld = ToWorldPath(path);

            if (changed)
            {
                EventDispatcher.TriggerEvent(EventName.RefreshPathEvent);
            }
        }

        private static int ComputePathHash(List<Point> path)
        {
            unchecked
            {
                int h = 17;
                for (int i = 0; i < path.Count; i++)
                {
                    h = h * 31 + path[i].X * 397 + path[i].Y;
                }
                return h;
            }
        }

        /// <summary>当前路径长度（格），用于自检日志</summary>
        public int CurrentPathLength
        {
            get { return CurrentPathWorld != null ? CurrentPathWorld.Length : 0; }
        }

        /// <summary>把路径打印成 (row,col) 序列，便于排查配置</summary>
        public string DescribeCurrentPath()
        {
            if (Map == null || StartPoint == null)
            {
                return "(未建网格)";
            }
            List<Point> path = GetPath();
            if (path.Count == 0)
            {
                return "(不可达)";
            }
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.Append("路径 ").Append(path.Count).Append(" 格：");
            for (int i = 0; i < path.Count; i++)
            {
                if (i > 0)
                {
                    sb.Append(" → ");
                }
                sb.Append('(').Append(path[i].Row).Append(',').Append(path[i].Col).Append(')');
            }
            return sb.ToString();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace AStar {

    /// <summary>
    /// A星寻路的单例封装
    /// 实现原理
    /// 1、首先有一张一定宽高的地图 （定义好 Point 点的地图，其中 Point 中有 IsWall 属性）
    /// 2、设定开始点，和目标点
    /// 3、传入 FindPath 开始寻找较短路径，找到返回true，否则 false
    /// 4、为 true 就可以通过 目标点的父亲点的父亲点的父亲点，直到父亲点为开始点，这些点集合即是路径
    /// 5、FindPath 寻找原理
    /// 1）开列表，关列表初始化
    /// 2）添加开始点到开列表，然后获得周围点集合，接着又把开始点从开列表中移除，并添加到关列表
    /// 3）判断这些周围点集合是否已经在开列表中，不在则更新这些点的F 和 父亲点，并添加到开列表；再则重新计算G值，G较小则更新GF 和父亲点
    /// 4）从周围点集合中找到 F 最小的点，然后获得周围点集合，接着又把找到 F 最小的点从开列表中移除，并添加到关列表
    /// 5）接着执行第 3） 步骤
    /// 6）直到目标点被添加到开列表中，则路径找到
    /// 7）否则，直到开列表中没有了数据，则说明没有合适路径
    /// </summary>
    public class AStarWrapper : Singleton<AStarWrapper>
    {
        /// <summary>
        /// 根据开始点和结束点，取得较短路径
        /// </summary>
        /// <param name="start">开始位置</param>
        /// <param name="end">结束位置</param>
        /// <param name="map">地图</param>
        /// <param name="mapWidth">地图宽</param>
        /// <param name="mapHeight">地图高</param>
        /// <returns>bool 找到路线/false 没有</returns>
        public bool FindPath(Point start, Point end, Point[,] map, int mapWidth, int mapHeight)
        {
            // 开列表（周围的点列表），关列表（每次比较后得到的最小 F 的点列表）
            List<Point> openList = new List<Point>();
            List<Point> closeList = new List<Point>();

            // 首先开始点添加进开列表
            openList.Add(start);
            while (openList.Count > 0)
            {
                // 寻找开列表中最小的 F 值
                Point point = FindMinFOfPoint(openList);

                // 把得到的 F 最小的点移除 开列表，添加到关列表中
                openList.Remove(point);
                closeList.Add(point);

                // 获取当前最小 F 点周围的点集合 
                List<Point> surroundPoints = GetSurroundPoints(point, map, mapWidth, mapHeight);

                // 过滤掉关列表中的数据
                PointFilter(surroundPoints, closeList);

                // 遍历获得的周围点
                foreach (Point item in surroundPoints)
                {
                    // 已存在开列表中的话
                    if (openList.IndexOf(item) > -1)
                    {
                        // 计算 G 值
                        float nowG = CalcG(item, point);

                        // 得到的 G 值小的话，更新 G 值和点的父节点
                        if (nowG < item.G)
                        {
                            item.UpdateParent(point, nowG);
                        }
                    }
                    else // 不在开列表中
                    {
                        //把 最小 F 点，设置为他的父节点
                        item.Parent = point;
                        // 计算更新 item的 FGH
                        CalcF(item, end);
                        // 添加到 开列表
                        openList.Add(item);
                    }

                }

                // 判断 end 是否在 开列表中，即找到路径结束
                if (openList.IndexOf(end) > -1)
                {
                    return true;
                }
            }

            // 开列表没有了点，说明找不到路径
            return false;
        }


        /// <summary>
        /// 把关列表中的点从周围点集合中过滤掉
        /// </summary>
        /// <param name="src">周围点集合</param>
        /// <param name="closeList">关列表</param>
        private void PointFilter(List<Point> src, List<Point> closeList)
        {
            // 遍历，存在则移除
            foreach (Point item in closeList)
            {
                if (src.IndexOf(item) > -1)
                {
                    src.Remove(item);
                }

            }
        }

        /// <summary>
        /// 获得当前最小 F 的周围点
        /// </summary>
        /// <param name="point">当前最小 F 点</param>
        /// <param name="map">地图点集合</param>
        /// <param name="mapWidth">地图宽</param>
        /// <param name="mapHeight">地图高</param>
        /// <returns>返回获得的周围点集合</returns>
        private List<Point> GetSurroundPoints(Point point, Point[,] map, int mapWidth, int mapHeight)
        {
            // 一个点一般会有上、下、左、右，左上、左下、右上、右下 八个点
            Point up = null, down = null, left = null, right = null;

            // 如果 点 Y 小于 mapHeight - 1，则表明不是最顶端，有上点
            if (point.Y < mapHeight - 1)
            {
                up = map[point.X, point.Y + 1];
            }
            // 如果 点 Y 大于 0，则表明不是最下端，有下点
            if (point.Y > 0)
            {
                down = map[point.X, point.Y - 1];
            }
            // 如果 点 X 小于 mapWidth - 1，则表明不是最右端，有右点
            if (point.X < mapWidth - 1)
            {
                right = map[point.X + 1, point.Y];
            }
            // 如果 点 X 大于 0，则表明不是最左端，有左点
            if (point.X > 0)
            {
                left = map[point.X - 1, point.Y];
            }

            // 边角点
            // 有上点和左点，说明有左上点
            //if (up != null && left != null)
            //{
            //    lu = map[point.X - 1, point.Y + 1];
            //}
            //// 有上点和右点，说明有右上点
            //if (up != null && right != null)
            //{
            //    ru = map[point.X + 1, point.Y + 1];
            //}
            //// 有下点和左点，说明有左下点
            //if (down != null && left != null)
            //{
            //    ld = map[point.X - 1, point.Y - 1];
            //}
            //// 有下点和右点，说明有右下点
            //if (down != null && right != null)
            //{
            //    rd = map[point.X + 1, point.Y - 1];
            //}

            // 新建一个列表
            List<Point> list = new List<Point>();
            // 把点添加到列表
            // 上点不为空，且不是障碍物，则添加到返回列表中，下面同理
            if (up != null && up.IsWall == false)
            {
                list.Add(up);
            }
            if (down != null && down.IsWall == false)
            {
                list.Add(down);
            }
            if (left != null && left.IsWall == false)
            {
                list.Add(left);
            }
            if (right != null && right.IsWall == false)
            {
                list.Add(right);
            }

            //// 添加边角到列表
            //// 左上点不为空且不是障碍物，并且 左点和上点都不是障碍物，则添加到返回列表，以下同理
            //if (lu != null && lu.IsWall == false && left.IsWall == false && up.IsWall == false)
            //{
            //    list.Add(lu);
            //}
            //if (ru != null && ru.IsWall == false && right.IsWall == false && up.IsWall == false)
            //{
            //    list.Add(ru);
            //}
            //if (ld != null && ld.IsWall == false && left.IsWall == false && down.IsWall == false)
            //{
            //    list.Add(ld);
            //}
            //if (rd != null && rd.IsWall == false && right.IsWall == false && down.IsWall == false)
            //{
            //    list.Add(rd);
            //}

            // 返回列表
            return list;

        }


        /// <summary>
        /// 比较开列表中所有点的 F 值，获得当前列表中最小的点
        /// </summary>
        /// <param name="openList">开列表</param>
        /// <returns></returns>
        private Point FindMinFOfPoint(List<Point> openList)
        {
            float f = float.MaxValue;
            Point tmp = null;

            foreach (Point p in openList)
            {
                if (p.F < f)
                {
                    tmp = p;
                    f = p.F;
                }
            }

            return tmp;

        }

        /// <summary>
        /// 计算 G 值
        /// </summary>
        /// <param name="now">当前点</param>
        /// <param name="parent">当前点的父节点</param>
        /// <returns></returns>
        private float CalcG(Point now, Point parent)
        {
            return Vector2.Distance(new Vector2(now.X, now.Y), new Vector2(parent.X, parent.Y)) + parent.G;
        }

        /// <summary>
        /// 计算 F 值
        /// </summary>
        /// <param name="now">当前点</param>
        /// <param name="end">结束点</param>
        private void CalcF(Point now, Point end)
        {
            // F = G + H
            // H 值的计算方式不唯一，有意义就行，这里是结束点X和Y的和
            float h = Mathf.Abs(end.X - now.X) + Mathf.Abs(end.Y - now.Y);
            float g = 0;
            if (now.Parent == null)
            {
                g = 0;
            }
            else
            {
                // 当前点和父节点的距离
                g = Vector2.Distance(new Vector2(now.X, now.Y), new Vector2(now.Parent.X, now.Parent.Y)) + now.Parent.G;
            }

            // 更新当前点FGH的值
            float f = g + h;
            now.F = f;
            now.G = g;
            now.H = h;
        }
    }
}

using UnityEngine;

namespace AStar
{
    /// <summary>
    /// A* 寻路节点（v2.1 的 2D 版）。
    ///
    /// 相对 v1.0 的改动：
    ///   - **移除** GameObject / Transform 强引用（数据与视图解耦，便于单元测试）
    ///   - position(Vector3) → Center(Vector2)，坐标体系改为 2D 世界坐标
    ///   - 保留 X / Y 字段名：AStarWrapper 依赖它们，X 为行、Y 为列
    ///
    /// 注意：AStarWrapper 只用到 F / G / H / Parent / UpdateParent / X / Y / IsWall，
    /// 不涉及任何 Unity 对象引用。
    /// </summary>
    [System.Serializable]
    public class Point
    {
        /// <summary>父节点（回溯路径用）</summary>
        public Point Parent { get; set; }

        public float F { get; set; }
        public float G { get; set; }
        public float H { get; set; }

        /// <summary>
        /// 横轴坐标 —— **列索引 col**。
        ///
        /// 【为什么 X 是列】AStarWrapper 插件把 X 当横轴（用 mapWidth 判断边界）、
        /// Y 当纵轴（用 mapHeight 判断边界），并直接以 `map[X, Y]` 访问网格。
        /// 所以数组必须声明为 `new Point[cols, rows]`。
        /// 这套命名沿用了原插件的字段名，改名的代价大于保留（插件是第三方代码，不宜改）。
        /// </summary>
        public int X { get; set; }

        /// <summary>纵轴坐标 —— **行索引 row**。详见 X 的说明。</summary>
        public int Y { get; set; }

        /// <summary>是否为墙（障碍格 或 被塔占用）</summary>
        public bool IsWall;

        /// <summary>格子中心的世界坐标（2D），由 AStarManager.BuildGrid 写入</summary>
        public Vector2 Center;

        /// <summary>行索引（本项目代码一律用 Row/Col，避免 X/Y 的轴歧义）</summary>
        public int Row { get { return Y; } }

        /// <summary>列索引</summary>
        public int Col { get { return X; } }

        public Point(int x, int y, Point parent = null)
        {
            X = x;
            Y = y;
            Parent = parent;
            IsWall = false;
        }

        /// <summary>更新 G / F 值与父节点</summary>
        public void UpdateParent(Point parent, float g)
        {
            Parent = parent;
            G = g;
            F = G + H;
        }

        /// <summary>重置寻路状态（重用节点时调用，避免上次的 G/H/Parent 残留）</summary>
        public void ResetSearchState()
        {
            Parent = null;
            F = 0f;
            G = 0f;
            H = 0f;
        }

        public override string ToString()
        {
            return string.Format("Point(row={0}, col={1}, wall={2})", Row, Col, IsWall);
        }
    }
}

public class Singleton<T> where T :class,new()
{
    private static T instance;
    private static readonly object locker = new object();
    public static T Instance {
        get {

            lock (locker) {

                if (instance == null) {
                    instance = new T();
                }

                return instance;
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    public enum BulletState { None = 0, Fire, Idle }

    /// <summary>
    /// 子弹基类（v2.1 的 2D 版，M2 补齐范围 / 减速 / 持续伤害）。
    ///
    /// 相对 v1.0 的关键改动：
    ///   - **移除 OnTriggerEnter 命中判定**，改为每帧「与目标的距离 ≤ hitRadius + 怪物体半径」判定
    ///   - 不再用 transform.Translate(Vector3.forward)，改为 Vector2 方向位移
    ///   - 伤害由发射塔注入（v1.0 硬编码 Hurt(1)）
    ///   - 复用时必须完整重置状态，否则会出现"带着上次目标飞出去"的经典池化 Bug
    ///
    /// 【M2 修复的真实缺陷】AOE 每次命中 new List（每跳一次 GC）：缓冲改为实例字段复用。
    ///
    /// 【2026-10-14 三塔型收敛】穿透机制（pierce 字段与"一发连穿多敌"逻辑）
    ///   随穿透塔一并删除；现在子弹命中一次即回收。
    ///   _hitSet 保留为防御机制：保证同一发子弹不会重复命中同一个目标。
    ///
    /// 【命中效果的口径】以**子弹的 effectType** 为准（见 EffectType 枚举注释）；
    ///   强度 effectValue 由塔覆盖（塔里填了正数就用塔的），这样减速塔三级各不相同。
    /// </summary>
    public class BaseBullet : MonoBehaviour
    {
        public BulletState State { get; private set; }

        /// <summary>配置里没填 resName 时的兜底逻辑名（BulletManager 与归还逻辑共用，避免两处写死不一致）</summary>
        public const string FallbackResName = "Bullet_Normal";

        /// <summary>本发子弹所属的对象池 key（= 配置的 resName）。归还时用它找对池子。</summary>
        public string ResName { get; private set; }

        /// <summary>
        /// 减速持续时长（秒）。做成常数而不是配置列：当前只有一种减速弹，
        /// 加一列只会让表更宽；真要做"不同时长"时再加列即可。
        /// 【public】塔侧即时命中（BaseTower.ApplyHitEffect）共用同一时长，唯一权威在这里。
        /// </summary>
        public const float SlowDurationSec = 2f;

        /// <summary>持续伤害的持续时间（秒），同上。</summary>
        public const float DotDurationSec = 3f;

        /// <summary>
        /// 空间哈希查询的额外半径余量，用来覆盖"怪物受击半径"。
        /// 取 1.0 世界单位，远大于当前所有怪的 bodyRadius（默认 0.4）；
        /// 多查出来的候选会被随后的精确距离判定过滤掉，只是多几次比较。
        /// </summary>
        private const float QueryPad = 1.0f;

        private BaseEnemy _target;
        private Vector2 _dir = Vector2.right;
        private float _speed;
        private float _hitRadius;
        private float _lifeTime;
        private float _lifeTimer;
        private float _damage;
        private float _aoeRadius;
        private EffectType _effect;
        private float _effectValue;
        private SpriteRenderer _sr;

        // ---- AOE 专用（见 Init 里的说明）----
        /// <summary>是否为 AOE 弹：飞向**发射瞬间锁定的落点**，到达即引爆，不追尾。</summary>
        private bool _isAoe;
        /// <summary>AOE 落点（世界坐标，发射瞬间确定，之后不再改变）</summary>
        private Vector2 _aoeTargetPos;
        /// <summary>引爆判定的到达阈值（世界单位）。取小值：让弹体基本飞到落点才炸。</summary>
        private const float AoeArriveEpsilon = 0.08f;
        /// <summary>命中判定 / AOE 的候选缓冲。实例字段复用 → 命中过程零 GC。</summary>
        private readonly List<BaseEnemy> _queryBuf = new List<BaseEnemy>(32);

        /// <summary>已被**这一发**子弹打过的敌人（防御机制：同一发不重复命中同一目标）。</summary>
        private readonly HashSet<BaseEnemy> _hitSet = new HashSet<BaseEnemy>();

        /// <summary>
        /// 初始化一发子弹。
        /// </summary>
        /// <param name="towerEffectValue">
        /// 发射塔的 effectValue。&gt; 0 时覆盖子弹自己的值（减速塔三级强度因此不同）。
        /// </param>
        public void Init(BaseEnemy target, float damage, BulletConfig cfg, float towerEffectValue)
        {
            _target = target;
            _damage = damage;
            _speed = cfg.Speed;
            _hitRadius = cfg.HitRadius;
            _lifeTime = cfg.LifeTimeSec;
            _aoeRadius = cfg.AoeRadius;
            _effect = cfg.Effect;
            _effectValue = towerEffectValue > 0f ? towerEffectValue : cfg.EffectValue;
            ResName = string.IsNullOrEmpty(cfg.ResName) ? FallbackResName : cfg.ResName;
            _lifeTimer = 0f;
            _hitSet.Clear();
            State = BulletState.Fire;

            // includeInactive=true：对象池归还时会 SetActive(false)，
            // 而 Init 发生在"取出后、激活前"，默认参数会漏掉未激活的子物体
            if (_sr == null)
            {
                _sr = GetComponentInChildren<SpriteRenderer>(true);
            }
            if (_sr != null)
            {
                _sr.sortingLayerName = BoardSorting.LayerMain;
                _sr.sortingOrder = BoardSorting.Bullet;
                transform.localScale = Vector3.one * cfg.Scale;
            }

            // AOE 弹：目标不是"要打中的那只怪"，而是"要炸掉的落点"。
            //   落点在发射瞬间就锁定（怪物死了/飞走了都不改），弹体直飞到落点引爆 ——
            //   这才是"范围攻击"；若仍追着怪跑，就退化成了单体攻击（哪怕炸开有溅射）。
            _isAoe = _aoeRadius > 0f;
            if (_isAoe)
            {
                _aoeTargetPos = target != null ? target.Position : (Vector2)transform.position;
            }

            // 初始朝向：AOE 朝落点，普通弹朝目标当前位置
            Vector2 aimAt = _isAoe ? _aoeTargetPos : (target != null ? target.Position : (Vector2)transform.position);
            Vector2 d = aimAt - (Vector2)transform.position;
            if (d.sqrMagnitude > 0.000001f)
            {
                _dir = d.normalized;
            }
            gameObject.SetActive(true);
        }

        /// <summary>由 CombatSystem 每帧调用</summary>
        public void Tick(float dt)
        {
            if (State != BulletState.Fire)
            {
                return;
            }

            // ① 制导：
            //    - AOE 弹**不追踪**，直飞落点（见 Init）；到达即引爆。
            //    - 普通弹只在"还没打中任何敌人"时制导。一旦打中过，
            //      就保持最后方向直线飞行 —— 否则子弹会拐回去追已被打过的那只。
            if (_isAoe)
            {
                Vector2 toPos = _aoeTargetPos - (Vector2)transform.position;
                // 到达（或越过）落点 → 引爆
                if (toPos.sqrMagnitude <= AoeArriveEpsilon * AoeArriveEpsilon)
                {
                    transform.position = new Vector3(_aoeTargetPos.x, _aoeTargetPos.y, 0f);
                    Explode(_aoeTargetPos);
                    return;
                }
            }
            else if (_hitSet.Count == 0 && _target != null && _target.IsAlive)
            {
                Vector2 d = _target.Position - (Vector2)transform.position;
                if (d.sqrMagnitude > 0.000001f)
                {
                    _dir = d.normalized;
                }
            }

            // ② 位移
            Vector2 pos = transform.position;
            pos += _dir * (_speed * dt);
            transform.position = new Vector3(pos.x, pos.y, 0f);

            // ③ AOE 弹位移后可能正好跨过落点：再判一次（高速弹 + 大 dt 时必需），
            //    到达即引爆并回收，不做穿透/命中扫描。
            if (_isAoe)
            {
                Vector2 after = _aoeTargetPos - pos;
                if (after.sqrMagnitude <= AoeArriveEpsilon * AoeArriveEpsilon
                    || Vector2.Dot(_aoeTargetPos - pos, _dir) <= 0f)   // 已越过落点
                {
                    transform.position = new Vector3(_aoeTargetPos.x, _aoeTargetPos.y, 0f);
                    Explode(_aoeTargetPos);
                    return;
                }
                // 飞行中未到达：只走超时回收
                _lifeTimer += dt;
                if (_lifeTimer >= _lifeTime)
                {
                    Explode(Position);   // 超时也别白飞：就地炸掉
                }
                return;
            }

            // ③′ 普通弹命中判定：找最近的、本发子弹还没打过的敌人
            BaseEnemy hit = FindHit(pos);
            if (hit != null)
            {
                OnHit(hit);
                if (State != BulletState.Fire)
                {
                    return;   // 已回收，后面的逻辑不能再碰 transform
                }
            }

            // ④ 超时回收（防止"追不上的子弹"永久存在）
            _lifeTimer += dt;
            if (_lifeTimer >= _lifeTime)
            {
                Recycle();
            }
        }

        /// <summary>
        /// 找当前位置能命中的敌人（最近优先）。
        /// 空间哈希已经把候选压到常数级，这里再精确过滤即可。
        /// </summary>
        private BaseEnemy FindHit(Vector2 pos)
        {
            CombatSystem cs = CombatSystem.Instance;
            if (cs == null || cs.Grid == null)
            {
                return null;
            }

            _queryBuf.Clear();
            cs.Grid.QueryCircle(pos, _hitRadius + QueryPad, _queryBuf);

            BaseEnemy best = null;
            float bestSqr = float.MaxValue;
            for (int i = 0; i < _queryBuf.Count; i++)
            {
                BaseEnemy e = _queryBuf[i];
                if (e == null || !e.IsAlive || _hitSet.Contains(e))
                {
                    continue;
                }
                // 命中面 ≈ 怪物身体轮廓：只用子弹半径的话，怪物越大反而越难打中
                float hitR = _hitRadius + e.BodyRadius;
                float sqr = (e.Position - pos).sqrMagnitude;
                if (sqr > hitR * hitR)
                {
                    continue;   // 网格查询会带出范围外元素，这里精确过滤
                }
                if (sqr < bestSqr)
                {
                    bestSqr = sqr;
                    best = e;
                }
            }
            return best;
        }

        private void OnHit(BaseEnemy e)
        {
            e.Hurt(_damage);
            ApplyEffect(e);
            _hitSet.Add(e);

            // AOE 弹：理论上走不到这里（Tick 里到达落点就直接 Explode 了），
            // 但保留此分支作为兜底 —— 万一飞行途中撞到别的怪，也应当就地炸开。
            if (_aoeRadius > 0f)
            {
                Explode(Position);
                return;
            }

            Recycle();
        }

        /// <summary>
        /// 在 <paramref name="center"/> 处引爆：对半径 _aoeRadius 内的**全部**存活敌人
        /// 造成伤害并施加效果，然后回收自身。
        ///
        /// AOE 的口径是"范围攻击"而非"单体 + 溅射"：伤害范围从落点算，
        /// 与落点上是否站怪无关 —— 怪死了/没打中，只要在范围内一样吃伤害。
        /// </summary>
        private void Explode(Vector2 center)
        {
            // 屏幕震动（UI 补全 C3）：范围攻击爆炸是最"有分量"的打击反馈。
            // 系数 0.3 —— 爆炸发生得很频繁，按漏怪的 1.0 会晃到没法玩。
            if (CameraController.Instance != null && Configs.Global != null)
            {
                CameraController.Instance.Shake(
                    Configs.Global.ShakeAmplitude * 0.3f, Configs.Global.ShakeDurationSec);
            }

            CombatSystem cs = CombatSystem.Instance;
            if (cs != null && cs.Grid != null && _aoeRadius > 0f)
            {
                _queryBuf.Clear();
                cs.Grid.QueryCircle(center, _aoeRadius, _queryBuf);
                float r2 = _aoeRadius * _aoeRadius;
                for (int i = 0; i < _queryBuf.Count; i++)
                {
                    BaseEnemy other = _queryBuf[i];
                    if (other == null || !other.IsAlive)
                    {
                        continue;
                    }
                    if ((other.Position - center).sqrMagnitude <= r2)
                    {
                        other.Hurt(_damage);
                        ApplyEffect(other);
                    }
                }
            }
            Recycle();
        }

        /// <summary>
        /// 施加命中效果。effectType 以子弹为准（见 EffectType 注释）。
        /// Aoe 不在子弹侧额外处理：由 aoeRadius 分支完成。
        /// </summary>
        private void ApplyEffect(BaseEnemy e)
        {
            switch (_effect)
            {
                case EffectType.Slow:
                    e.ApplySlow(_effectValue, SlowDurationSec);
                    break;
                case EffectType.Dot:
                    e.ApplyDot(_effectValue, DotDurationSec);
                    break;
                default:
                    break;
            }
        }

        public Vector2 Position
        {
            get { Vector2 p = transform.position; return p; }
        }

        public void Recycle()
        {
            BulletManager.Instance.RecycleBullet(this);
        }

        /// <summary>对象池归还时调用，必须清空全部跨帧状态</summary>
        public void OnRecycle()
        {
            State = BulletState.Idle;
            _target = null;
            _dir = Vector2.right;
            _lifeTimer = 0f;
            _damage = 0f;
            _aoeRadius = 0f;
            _isAoe = false;
            _aoeTargetPos = Vector2.zero;
            _effect = EffectType.None;
            _effectValue = 0f;
            _hitSet.Clear();
            _queryBuf.Clear();
            gameObject.SetActive(false);
        }
    }

    /// <summary>
    /// 子弹管理器（池化）。
    ///
    /// 【为什么按 resName 分池】不同子弹将来会有不同外观（爆炸弹/腐蚀弹…），
    ///   TBBulletData.resName 已经能表达这件事。现在所有子弹都还指向 Bullet_Normal，
    ///   所以实际只有一个池；但接口先按多池设计，将来换美术时不用再改这里。
    /// </summary>
    public class BulletManager : BaseManager<BulletManager>
    {
        public Transform BulletParent { get; private set; }

        /// <summary>兜底资源名：配置里没填 resName 时用它</summary>
        private readonly Dictionary<string, ObjectPool<BaseBullet>> _pools =
            new Dictionary<string, ObjectPool<BaseBullet>>();

        private int _maxPoolSize = 256;
        private bool _inited;
        /// <summary>RecycleAll 的复用缓冲</summary>
        private readonly List<BaseBullet> _clearBuf = new List<BaseBullet>(256);

        public override void OnInit()
        {
            base.OnInit();

            // 幂等保护：重复初始化会新建对象池，之前发出去的池化对象就再也回不来了
            if (_inited)
            {
                Debug.LogWarning("[Bullet] OnInit 被重复调用，已忽略（管理器应只初始化一次）");
                return;
            }
            _inited = true;

            int prewarm = Configs.Global != null ? Configs.Global.BulletPoolSize : 128;
            _maxPoolSize = Mathf.Max(16, prewarm * 2);
        }

        public override void OnDestroy()
        {
            base.OnDestroy();
            foreach (KeyValuePair<string, ObjectPool<BaseBullet>> kv in _pools)
            {
                ObjectPool<BaseBullet> pool = kv.Value;
                if (pool != null)
                {
                    pool.Clear(b =>
                    {
                        if (b != null && b.gameObject != null)
                        {
                            Object.Destroy(b.gameObject);
                        }
                    });
                }
            }
            _pools.Clear();
        }

        public void SetParent(Transform parent)
        {
            BulletParent = parent;
        }

        private ObjectPool<BaseBullet> GetPool(string resName)
        {
            ObjectPool<BaseBullet> pool;
            if (_pools.TryGetValue(resName, out pool))
            {
                return pool;
            }
            if (!_inited)
            {
                Debug.LogError("[Bullet] 管理器尚未初始化，无法创建子弹");
                return null;
            }
            string captured = resName;
            pool = new ObjectPool<BaseBullet>(
                create: () => CreateBullet(captured),
                reset: b => b.OnRecycle(),
                maxSize: _maxPoolSize,
                prewarm: 0);
            _pools[resName] = pool;
            return pool;
        }

        private BaseBullet CreateBullet(string resName)
        {
            if (BulletParent == null)
            {
                GameObject root = GameObject.Find("BulletRoot");
                BulletParent = root != null ? root.transform : null;
            }
            GameObject go = ResLoader.Instance.Instantiate(resName, BulletParent);
            if (go == null)
            {
                return null;
            }
            BaseBullet b = go.GetComponent<BaseBullet>();
            if (b == null)
            {
                b = go.AddComponent<BaseBullet>();
            }
            CombatSystem.Instance.RegisterBullet(b);
            go.SetActive(false);
            return b;
        }

        /// <summary>
        /// 发射一颗子弹。
        /// </summary>
        /// <param name="towerEffectValue">发射塔的 effectValue（&gt;0 时覆盖子弹的，见 BaseBullet.Init）</param>
        public void Fire(BaseEnemy target, float damage, Vector2 fromPos, BulletConfig cfg, float towerEffectValue)
        {
            if (target == null || cfg == null)
            {
                return;
            }
            string resName = string.IsNullOrEmpty(cfg.ResName) ? BaseBullet.FallbackResName : cfg.ResName;
            ObjectPool<BaseBullet> pool = GetPool(resName);
            if (pool == null)
            {
                return;
            }
            BaseBullet b = pool.Get();
            if (b == null)
            {
                Debug.LogError("[Bullet] 子弹创建失败，请检查 ResTable 中的 " + resName + " 是否就绪");
                return;
            }
            b.transform.SetParent(BulletParent, false);
            b.transform.position = new Vector3(fromPos.x, fromPos.y, 0f);
            b.Init(target, damage, cfg, towerEffectValue);

            if (CombatSystem.Instance != null)
            {
                CombatSystem.Instance.AddFireCount(1);
            }
        }

        /// <summary>兼容旧调用点：不带塔效果参数（等价于 effectValue=0，用子弹自己的值）。</summary>
        public void Fire(BaseEnemy target, float damage, Vector2 fromPos, BulletConfig cfg)
        {
            Fire(target, damage, fromPos, cfg, 0f);
        }

        public void RecycleBullet(BaseBullet b)
        {
            if (b == null)
            {
                return;
            }
            string resName = string.IsNullOrEmpty(b.ResName) ? BaseBullet.FallbackResName : b.ResName;
            ObjectPool<BaseBullet> pool;
            if (!_pools.TryGetValue(resName, out pool) || pool == null)
            {
                // 找不到原池（理论上不会）：直接销毁，避免对象泄漏在场景里
                Object.Destroy(b.gameObject);
                return;
            }
            pool.Release(b);
        }

        /// <summary>
        /// 回收全部在场子弹（切关 / 重开用）。
        /// 【为什么必须走 RecycleBullet 而不是直接 OnRecycle】
        /// 只有走对象池的 Release 才会把 reset 回调跑全、并把对象真正放回池子；
        /// 直接调 OnRecycle 会让子弹"看起来回收了、其实既不在场上也不在池里"，下次开火凭空少一发。
        /// </summary>
        public void RecycleAll()
        {
            _clearBuf.Clear();
            if (CombatSystem.Instance != null)
            {
                CombatSystem.Instance.CopyBullets(_clearBuf);
            }
            for (int i = _clearBuf.Count - 1; i >= 0; i--)
            {
                BaseBullet b = _clearBuf[i];
                if (b != null && b.State == BulletState.Fire)
                {
                    RecycleBullet(b);
                }
            }
            _clearBuf.Clear();
        }

        /// <summary>空闲子弹总数（自检/调试用）</summary>
        public int PooledCount
        {
            get
            {
                int n = 0;
                foreach (KeyValuePair<string, ObjectPool<BaseBullet>> kv in _pools)
                {
                    if (kv.Value != null)
                    {
                        n += kv.Value.IdleCount;
                    }
                }
                return n;
            }
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 2D 正交相机控制（v2.1 重写）。
    ///
    /// 相对 v1.0 的改动：
    ///   - **删掉全部 Physics.Raycast / Touch 旋转逻辑**（需求 8：去物理化）
    ///   - 原实现用 `Physics.Raycast(..., 3)` 拾取塔，且引用已删除的 TowerInfoView，
    ///     还挂在 EventName.OperateDown/Up（这两个事件名已不存在）→ 无法编译
    ///   - 固定俯视 2D：相机永远看向 +Z，只在 XY 平面平移与缩放
    ///
    /// 【坐标换算约定】正交相机下 `ScreenToWorldPoint` 的 z 必须传
    /// `-camera.transform.position.z`，否则算出的世界坐标落在错误的深度平面。
    /// BoardView 与 TowerPlacement 都遵循这个约定。
    /// </summary>
    [RequireComponent(typeof(Camera))]
    public class CameraController : MonoBehaviour
    {
        /// <summary>默认相机 z（正交下只影响裁剪与换算深度）</summary>
        public const float DefaultZ = -10f;

        [Header("缩放")]
        [Tooltip("滚轮缩放速度")]
        public float zoomSpeed = 2f;
        [Tooltip("相对自适应尺寸的最大放大倍数")]
        public float maxZoomInFactor = 2.5f;
        [Tooltip("相对自适应尺寸的最大缩小倍数")]
        public float maxZoomOutFactor = 2f;

        /// <summary>
        /// 全局唯一实例（供战斗侧触发震动）。
        /// 【为什么允许为 null 调用】场景没相机时不应该让"漏怪扣血"这种核心逻辑崩掉，
        /// 调用方统一写成 if (CameraController.Instance != null)。
        /// </summary>
        public static CameraController Instance { get; private set; }

        [Header("平移（M4-2）")]
        [Tooltip("中键拖拽的灵敏度（1 = 跟手）")]
        public float panDragFactor = 1f;
        [Tooltip("键盘（WASD / 方向键）平移速度系数，会按当前缩放折算")]
        public float panKeySpeed = 1.2f;
        [Tooltip("鼠标贴到屏幕边缘时自动平移。放置/选中塔时会自动禁用，避免误触")]
        public bool enableEdgeScroll = true;
        [Tooltip("边缘触发带宽度（像素）")]
        public float edgeBandPx = 18f;

        [Header("棋盘取景留白（单位：格，2026-10-16 多分辨率适配）")]
        [Tooltip("棋盘底边留白（格）——为底部 HUD 建造栏/倍速按钮让位")]
        public float bottomMarginCells = 2f;
        [Tooltip("棋盘顶边留白（格）——为顶部 HUD 芯片让位")]
        public float topMarginCells = 1f;
        [Tooltip("棋盘左右留白（格）")]
        public float sideMarginCells = 1f;
        [Tooltip("是否把屏幕安全区（刘海/挖孔）内缩计入取景留白")]
        public bool fitSafeArea = true;

        private Camera _cam;
        private float _fitSize = 5f;
        private Vector2 _boardCenter = Vector2.zero;

        // ---- 多分辨率适配（2026-10-16）----
        /// <summary>最近一次 FitBoard 的棋盘参数（分辨率/安全区变化时重算用）</summary>
        private int _boardRows;
        private int _boardCols;
        private float _boardCellSize;
        /// <summary>取景归位点（含底边留白偏移后的相机位置；空格键/重算回位用）</summary>
        private Vector3 _homePos;
        /// <summary>平移夹取框（棋盘 + 四周留白；视口大于框时锁定框中心）</summary>
        private float _frameMinX, _frameMaxX, _frameMinY, _frameMaxY;
        private bool _hasFit;
        private int _lastPixW = -1, _lastPixH = -1;
        private Rect _lastSafeArea;

        // ---- 屏幕震动（M2-W5）----
        private Vector3 _shakeOffset;
        private float _shakeTimer;
        private float _shakeAmplitude;
        private float _shakeDuration;

        private void Awake()
        {
            Instance = this;
            _cam = GetComponent<Camera>();
            _cam.orthographic = true;
            _cam.transform.position = new Vector3(0f, 0f, DefaultZ);
        }

        private void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        /// <summary>
        /// 触发一次屏幕震动。
        ///
        /// 【为什么不叠加而是取更强的一次】连续漏怪时如果每次都叠加，
        /// 相机振幅会迅速累积到看不清操作 —— 震动是反馈，不该变成惩罚。
        /// 【为什么在 LateUpdate 施加偏移】Update 里 FitBoard / 缩放改的是"真实位置"，
        /// 偏移必须最后叠加，否则会被它们覆盖掉（或者反过来污染真实位置）。
        /// </summary>
        public void Shake(float amplitude, float durationSec)
        {
            if (amplitude <= 0f || durationSec <= 0f)
            {
                return;
            }
            _shakeAmplitude = Mathf.Max(_shakeAmplitude, amplitude);
            _shakeDuration = Mathf.Max(_shakeDuration, durationSec);
            _shakeTimer = Mathf.Max(_shakeTimer, durationSec);
        }

        private void LateUpdate()
        {
            // 先把上一帧的偏移减掉，还原出"真实位置"
            Vector3 basePos = transform.position - _shakeOffset;

            if (_shakeTimer > 0f)
            {
                _shakeTimer -= Time.deltaTime;
                if (_shakeTimer <= 0f)
                {
                    _shakeTimer = 0f;
                    _shakeAmplitude = 0f;
                    _shakeDuration = 0f;
                    _shakeOffset = Vector3.zero;
                }
                else
                {
                    float k = _shakeDuration > 0.0001f ? _shakeTimer / _shakeDuration : 0f;
                    Vector2 r = Random.insideUnitCircle * (_shakeAmplitude * k);
                    _shakeOffset = new Vector3(r.x, r.y, 0f);
                }
            }
            else
            {
                _shakeOffset = Vector3.zero;
            }

            transform.position = basePos + _shakeOffset;
        }

        /// <summary>
        /// 让整块棋盘完整落入视野（含 HUD 避让与安全区留白，2026-10-16 重写）。
        ///
        /// 留白策略（单位 = 格）：
        ///   · 底边 bottomMarginCells（默认 2）——为底部 HUD（建造栏下缘 49 / 上缘 177 @1080 基准）让位；
        ///   · 顶边 topMarginCells（默认 1）——为顶部 HUD 芯片让位；
        ///   · 左右 sideMarginCells（默认 1）+（可选）屏幕安全区内缩。
        /// 相机不再居中于棋盘，而是**下移**若干，使底边留白恰好等于 bottomMarginCells。
        ///
        /// 【为什么底边要比顶边大】按 16:9 的"屏幕像素预算"算平：
        ///   顶部 HUD ≤86px、底部 HUD ≤177px（1080 设计基准）；
        ///   棋盘高 9 格 + 底 2 格 + 顶 1 格 = 12 格 ≈ 1080px（每格 90px）→ 底 180 / 顶 90，
        ///   正好包住两头 HUD 且不浪费视野（旧版四边各 1 格时，建造栏会压住棋盘底行约 80% 行高）。
        /// </summary>
        /// <param name="rows">行数</param>
        /// <param name="cols">列数</param>
        /// <param name="cellSize">格子边长（世界单位）</param>
        /// <param name="boardCenter">棋盘几何中心的世界坐标</param>
        public void FitBoard(int rows, int cols, float cellSize, Vector2 boardCenter)
        {
            if (_cam == null)
            {
                _cam = GetComponent<Camera>();
            }
            _boardRows = rows;
            _boardCols = cols;
            _boardCellSize = cellSize;
            _boardCenter = boardCenter;
            _hasFit = true;
            ApplyBoardFit();
        }

        /// <summary>按当前屏幕比例/安全区重算取景（FitBoard 与运行期分辨率变化共用）。</summary>
        private void ApplyBoardFit()
        {
            if (_cam == null || !_hasFit || _boardRows <= 0 || _boardCols <= 0)
            {
                return;
            }

            float halfHBoard = _boardRows * _boardCellSize * 0.5f;
            float halfWBoard = _boardCols * _boardCellSize * 0.5f;

            float padB = Mathf.Max(0f, bottomMarginCells) * _boardCellSize;
            float padT = Mathf.Max(0f, topMarginCells) * _boardCellSize;
            float padL = Mathf.Max(0f, sideMarginCells) * _boardCellSize;
            float padR = padL;

            float aspect = _cam.aspect > 0.0001f ? _cam.aspect : (16f / 9f);
            // 正交尺寸是"半高"，所以要同时满足高度与宽度（宽度需按宽高比折算）
            float ortho = Mathf.Max(halfHBoard + 0.5f * (padB + padT),
                                    (halfWBoard + Mathf.Max(padL, padR)) / aspect);

            // 安全区（刘海/挖孔）内缩换算成世界单位。像素↔世界换算依赖 ortho，
            // 先估一版再折算一次即可收敛（留白变化 → 视野变化很小，一遍足够）。
            if (fitSafeArea && Screen.width > 0 && Screen.height > 0 && _cam.pixelHeight > 0)
            {
                Rect sa = Screen.safeArea;
                float pxPerUnit = _cam.pixelHeight / (2f * ortho);
                if (pxPerUnit > 0.0001f)
                {
                    padL += sa.xMin / pxPerUnit;
                    padR += (Screen.width - sa.xMax) / pxPerUnit;
                    padB += sa.yMin / pxPerUnit;
                    padT += (Screen.height - sa.yMax) / pxPerUnit;
                    ortho = Mathf.Max(halfHBoard + 0.5f * (padB + padT),
                                      (halfWBoard + Mathf.Max(padL, padR)) / aspect);
                }
            }

            _fitSize = ortho;
            _cam.orthographicSize = ortho;

            // 相机位置：底边留白精确 = padB（顶边余量 = 2·ortho − 棋盘高 − padB ≥ padT 恒成立）
            float camY = (_boardCenter.y - halfHBoard) - padB + ortho;
            _homePos = new Vector3(_boardCenter.x, camY, DefaultZ);

            // 平移夹取框 = 棋盘 + 四周留白（取景归位时视口恰好贴合该框 → 锁定中心）
            _frameMinX = _boardCenter.x - halfWBoard - padL;
            _frameMaxX = _boardCenter.x + halfWBoard + padR;
            _frameMinY = (_boardCenter.y - halfHBoard) - padB;
            _frameMaxY = (_boardCenter.y + halfHBoard) + padT;

            transform.position = _homePos;
            // 归位时清掉震动状态：否则上一关结束前触发的震动会带进新关卡，
            // 表现为"刚进关画面还在抖"。偏移必须清，计时与幅度也要清，
            // 不然 LateUpdate 会在下一帧按旧幅度重新生成偏移。
            _shakeOffset = Vector3.zero;
            _shakeTimer = 0f;
            _shakeAmplitude = 0f;
            _shakeDuration = 0f;

            _lastPixW = _cam.pixelWidth;
            _lastPixH = _cam.pixelHeight;
            _lastSafeArea = Screen.safeArea;
        }

        private void Update()
        {
            RefitOnScreenChange();
            HandleZoom();
            HandlePan();
        }

        /// <summary>
        /// 分辨率 / 安全区变化时重算取景（2026-10-16）：折叠屏展开、分屏、编辑器切 Game View
        /// 比例等场景下，旧实现只在建关时算一次，比例变了不会重算（棋盘按旧比例取景）。
        /// 只在数值变化时触发，常态零开销；重算会复位视图（缩放/平移回到自适应档）。
        /// </summary>
        private void RefitOnScreenChange()
        {
            if (_cam == null || !_hasFit)
            {
                return;
            }
            if (_cam.pixelWidth == _lastPixW && _cam.pixelHeight == _lastPixH
                && Screen.safeArea == _lastSafeArea)
            {
                return;
            }
            ApplyBoardFit();
            Debug.Log(string.Format(
                "[Camera] 屏幕/安全区变化（{0}×{1}），重算棋盘取景 ortho={2:F2}",
                _cam.pixelWidth, _cam.pixelHeight, _fitSize));
        }

        /// <summary>
        /// 平移：中键拖拽 / WASD·方向键 / 鼠标贴屏幕边缘。
        ///
        /// 【为什么用中键而不是右键】右键已经被 TowerPlacement 用作"取消放置 / 取消选中"。
        ///
        /// 【为什么速度要乘 orthographicSize】放大之后，同样的像素拖拽对应的世界距离更小。
        /// 按视口高度折算，才能做到"不管缩放多少，推起来手感一致"。
        /// </summary>
        private void HandlePan()
        {
            if (_cam == null || Time.timeScale <= 0f)
            {
                return;   // 暂停时不平移
            }

            float dt = Time.deltaTime;
            float speed = _cam.orthographicSize * panKeySpeed;
            Vector3 delta = Vector3.zero;

            // ① 键盘
            float h = Input.GetAxisRaw("Horizontal");
            float v = Input.GetAxisRaw("Vertical");
            if (Mathf.Abs(h) > 0.01f || Mathf.Abs(v) > 0.01f)
            {
                delta += new Vector3(h, v, 0f).normalized * (speed * dt);
            }

            // ② 中键拖拽
            if (Input.GetMouseButton(2))
            {
                delta += new Vector3(-Input.GetAxisRaw("Mouse X"), -Input.GetAxisRaw("Mouse Y"), 0f)
                         * (_cam.orthographicSize * 0.05f * panDragFactor);
            }

            // ③ 边缘自动平移（放置/选中塔时禁用，否则拖塔到边缘会把镜头一起带走）
            if (enableEdgeScroll && !IsInteractingWithTower())
            {
                Vector3 m = Input.mousePosition;
                if (m.x >= 0f && m.x <= Screen.width && m.y >= 0f && m.y <= Screen.height)
                {
                    Vector2 dir = Vector2.zero;
                    if (m.x < edgeBandPx) dir.x -= 1f;
                    else if (m.x > Screen.width - edgeBandPx) dir.x += 1f;
                    if (m.y < edgeBandPx) dir.y -= 1f;
                    else if (m.y > Screen.height - edgeBandPx) dir.y += 1f;
                    if (dir.sqrMagnitude > 0.01f)
                    {
                        delta += (Vector3)(dir.normalized * (speed * dt));
                    }
                }
            }

            if (delta.sqrMagnitude <= 0f)
            {
                return;
            }
            transform.position = ClampToBoard(transform.position + delta);
        }

        private static bool IsInteractingWithTower()
        {
            TowerPlacement tp = TowerPlacement.Instance;
            return tp != null && (tp.IsPlacing || tp.SelectedTower != null);
        }

        /// <summary>
        /// 把相机位置夹在"棋盘 + 留白"的取景框内（框由 FitBoard/ApplyBoardFit 预算）。
        ///
        /// 【为什么不是简单夹到棋盘矩形】正交相机看到的是一个矩形视口：
        /// 当视野比取景框还大（缩到最远）时，"把中心夹进框内"反而会导致画面抖动。
        /// 正确做法是夹取半径 = 框半尺寸 − 视野半尺寸；差值为负时直接锁死在框中心
        /// （Mathf.Clamp 在 min &gt; max 时行为未定义，必须显式处理）。
        /// 2026-10-16：框取代了原来的"棋盘矩形"——含 HUD 避让与安全区留白。
        /// </summary>
        private Vector3 ClampToBoard(Vector3 pos)
        {
            if (_cam == null || !_hasFit)
            {
                return pos;
            }
            float halfH = _cam.orthographicSize;
            float halfW = halfH * _cam.aspect;

            float cx = (_frameMaxX - _frameMinX) > 2f * halfW
                ? Mathf.Clamp(pos.x, _frameMinX + halfW, _frameMaxX - halfW)
                : 0.5f * (_frameMinX + _frameMaxX);
            float cy = (_frameMaxY - _frameMinY) > 2f * halfH
                ? Mathf.Clamp(pos.y, _frameMinY + halfH, _frameMaxY - halfH)
                : 0.5f * (_frameMinY + _frameMaxY);
            return new Vector3(cx, cy, DefaultZ);
        }

        private void HandleZoom()
        {
            float scroll = Input.GetAxis("Mouse ScrollWheel");
            if (Mathf.Abs(scroll) < 0.0001f)
            {
                if (Input.GetKeyDown(KeyCode.Space))
                {
                    // 一键回到自适应视野（归位点 = FitBoard 算出的 _homePos，含底边留白偏移）
                    _cam.orthographicSize = _fitSize;
                    _shakeOffset = Vector3.zero;
                    transform.position = ClampToBoard(_homePos);
                }
                return;
            }

            float min = _fitSize / Mathf.Max(1.01f, maxZoomOutFactor);
            float max = _fitSize * Mathf.Max(1.01f, maxZoomInFactor);
            float next = Mathf.Clamp(_cam.orthographicSize - scroll * zoomSpeed, min, max);
            _cam.orthographicSize = next;
            // 缩放后视野变了，原来的位置可能已经越界 —— 立刻夹一次
            transform.position = ClampToBoard(transform.position - _shakeOffset);
        }

        /// <summary>屏幕坐标 → 世界坐标（z 取相机所在深度平面）</summary>
        public Vector3 ScreenToWorld(Vector2 screenPos)
        {
            return _cam.ScreenToWorldPoint(new Vector3(screenPos.x, screenPos.y, -transform.position.z));
        }

        /// <summary>世界坐标 → 屏幕坐标</summary>
        public Vector3 WorldToScreen(Vector3 world)
        {
            return _cam.WorldToScreenPoint(world);
        }
    }
}

