using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 集中式战斗系统 —— v2.1 去物理化改造的核心。
    ///
    /// 为什么要有它：
    ///   v1.0 里每个塔/怪/子弹都各自 `EventDispatcher.AddEventListener(UpdateEvent, ...)`，
    ///   每帧全局分发给 N 个监听者，且调用顺序不可控（塔可能比怪先更新，导致索敌基于上一帧位置）。
    ///
    /// 本类做到：
    ///   1. **全局唯一**的 UpdateEvent 订阅者
    ///   2. 固定更新顺序：怪先动 → 塔再索敌 → 子弹最后判定（消除一帧延迟）
    ///   3. 倒序遍历 + 顺手清理失效引用（不再依赖 OnDestroy 回调时序）
    ///   4. 驱动 EnemyGrid 同步与路径重算节流
    ///   5. 同屏怪物上限保护
    ///
    /// 【性能目标】Profiler 中 Physics/Physics2D 分区恒为 0；本类 OnUpdate 的 GC Alloc 为 0 B。
    /// </summary>
    public class CombatSystem : BaseManager<CombatSystem>
    {
        private readonly List<BaseEnemy> _enemies = new List<BaseEnemy>(256);
        private readonly List<BaseTower> _towers = new List<BaseTower>(64);
        private readonly List<BaseBullet> _bullets = new List<BaseBullet>(256);
        /// <summary>TickEnemies 的遍历快照：避免 Tick 期间列表被回调修改导致索引失效</summary>
        private readonly List<BaseEnemy> _tickSnapshot = new List<BaseEnemy>(256);

        /// <summary>空间哈希（供塔索敌查询）</summary>
        public EnemyGrid Grid { get; private set; }

        /// <summary>存活怪物数（回合完成判定用，按 IsAlive 过滤）</summary>
        public int AliveEnemyCount { get; private set; }

        // 自检计数（DoD 要求：无目标时塔的空放次数必须为 0）
        public int StatSearchCount { get; private set; }
        public int StatFireCount { get; private set; }
        public int StatHitCount { get; private set; }
        public int StatIdleFireAttempt { get; private set; }

        private float _statTimer;
        private float _statInterval = 5f;
        /// <summary>空放告警只报一次，避免刷屏（报一次就足够定位问题了）</summary>
        private bool _idleFireReported;
        /// <summary>是否已初始化（防止 OnInit 重复订阅事件）</summary>
        private bool _inited;

        public override void OnInit()
        {
            base.OnInit();

            // 幂等保护：OnInit 重复调用会导致 UpdateEvent 被重复订阅，
            // 表现为"每帧被 tick 两次"（怪物速度翻倍、子弹判定重复）。
            if (_inited)
            {
                Debug.LogWarning("[Combat] OnInit 被重复调用，已忽略（管理器应只初始化一次）");
                return;
            }
            _inited = true;

            CreateGrid();

            // ★ 全局唯一订阅
            EventDispatcher.AddEventListener(EventName.UpdateEvent, OnUpdate);
            // ★ 路径重算后让所有存活怪物改道 —— 这是《坚守阵地》的核心机制
            EventDispatcher.AddEventListener(EventName.RefreshPathEvent, OnRefreshPath);
        }

        private void CreateGrid()
        {
            float cellSize = Configs.Global != null ? Configs.Global.CellSize : 1f;
            // 邻域尺寸取 2 格：塔半径 3~6 格时，查询会覆盖 3×3 ~ 7×7 个格子
            Grid = new EnemyGrid(cellSize * 2f, 256);
        }

        /// <summary>
        /// 按最终配置重建空间哈希。
        /// 【为什么需要】Launcher 在 Awake 里就 OnInit 了各管理器，那时配置表还没加载，
        /// `Configs.Global` 为 null，网格尺寸会退回默认的 1；等配置到位必须重建一次，
        /// 否则格子划分与真实世界单位不一致，索敌范围会整体偏差。
        /// </summary>
        public void RebuildGridFromConfig()
        {
            if (Grid != null)
            {
                Grid.Clear();
            }
            CreateGrid();
            Debug.Log(string.Format("[Combat] 空间哈希已按配置重建：{0}", Grid.DumpDebugInfo()));
        }

        public override void OnDestroy()
        {
            base.OnDestroy();
            EventDispatcher.RemoveEventListener(EventName.UpdateEvent, OnUpdate);
            EventDispatcher.RemoveEventListener(EventName.RefreshPathEvent, OnRefreshPath);
            UnregisterAll();
            if (Grid != null)
            {
                Grid.Clear();
            }
        }

        // ------------------------------------------------------------------
        // 路径重算 → 怪物改道
        // ------------------------------------------------------------------

        /// <summary>
        /// 路径发生变化时，让场上所有存活怪物从各自当前格重新寻路。
        /// 【为什么必须做】"建塔改变敌人行进路线"是《坚守阵地》的核心玩法。
        /// 原实现只把新路径算给 AStarManager 后就没人用了 —— 怪物会继续沿旧路径走到终点，
        /// 塔摆了等于白摆。这个回调就是把"路径变了"传导到每一只怪身上。
        ///
        /// 开销：仅在路径**确实变化**时触发（AStarManager 用路径哈希判重），
        /// 每次触发是 O(怪数 × 单次 A*)，16×9 网格下可忽略。
        /// </summary>
        private void OnRefreshPath()
        {
            if (_enemies.Count == 0)
            {
                return;
            }
            int rerouted = 0;
            for (int i = 0; i < _enemies.Count; i++)
            {
                BaseEnemy e = _enemies[i];
                if (e != null && e.IsAlive)
                {
                    e.RefreshPath();
                    rerouted++;
                }
            }
            if (rerouted > 0 && Configs.Global != null && Configs.Global.ShowDebugLog)
            {
                Debug.Log(string.Format("[Combat] 路径已变化，{0} 只怪物改道", rerouted));
            }
        }

        // ------------------------------------------------------------------
        // 供建塔流程用
        // ------------------------------------------------------------------

        /// <summary>
        /// 让"正站在 (row, col) 这一格上、或剩余路径会经过这一格"的存活地面怪**立刻**重新寻路。
        ///
        /// 【什么时候需要】2026-10-22 起放置规则允许"怪物脚下建塔"（只要不堵死路径）。
        /// 建好的瞬间，那只怪就被墙包在格子里，而它手上的路径是建塔**之前**算的。
        /// 通常 RequestRefresh → RefreshPathEvent 会让所有怪改道，但那条链用"路径哈希判重"：
        /// 若主路径（起点→终点）恰好没变，就不会广播，脚下那只怪会沿着旧路径穿塔而过。
        /// 这里点对点补一次，把"允许脚下建塔"的行为钉死。
        ///
        /// 【为什么按"格"而不是按"半径"挑怪】早先的实现用 `QueryCircle(格心, CellSize*0.5)`：
        ///   格子是边长 CellSize 的方块，从格心到角落有 0.707×CellSize ——
        ///   半径只取半格时，站在格子四角附近的怪会被漏掉（它明明就在塔格里，却不会改道）。
        ///   改成"当前所在格 == 目标格，或剩余路径含目标格"就没有这个几何漏洞，
        ///   而且顺带覆盖了"下一格就要踏进新塔"的怪（旧实现完全管不到）。
        ///
        /// 【跳过飞行单位】它们走直线，重新寻路反而会把它们从直线拽回地面路线。
        /// </summary>
        /// <returns>实际改道的怪物数（自检/日志用）</returns>
        public int RerouteEnemiesThrough(int row, int col)
        {
            if (_enemies.Count == 0)
            {
                return 0;
            }
            BoardView board = BoardView.Instance;
            int rerouted = 0;
            for (int i = 0; i < _enemies.Count; i++)
            {
                BaseEnemy e = _enemies[i];
                if (e == null || !e.IsAlive || e.Config == null || e.Config.IsFlying)
                {
                    continue;
                }
                bool onCell = false;
                if (board != null)
                {
                    int er, ec;
                    if (board.WorldToCell(e.Position, out er, out ec))
                    {
                        onCell = er == row && ec == col;
                    }
                }
                // RefreshPath 内部只做 A* 与自身路径重设，不会增删 _enemies，可以安全地边遍历边改道
                if (onCell || e.RemainingPathTouches(row, col))
                {
                    e.RefreshPath();
                    rerouted++;
                }
            }
            return rerouted;
        }

        // ------------------------------------------------------------------
        // 注册 / 注销
        // ------------------------------------------------------------------

        public void RegisterEnemy(BaseEnemy e)
        {
            if (e != null && !_enemies.Contains(e))
            {
                _enemies.Add(e);
            }
        }

        public void UnregisterEnemy(BaseEnemy e)
        {
            if (e == null)
            {
                return;
            }
            _enemies.Remove(e);
            if (Grid != null)
            {
                Grid.Remove(e);
            }
        }

        public void RegisterTower(BaseTower t)
        {
            if (t != null && !_towers.Contains(t))
            {
                _towers.Add(t);
                t.SearchCount = 0;
                t.FireCount = 0;
            }
        }

        public void UnregisterTower(BaseTower t)
        {
            if (t != null)
            {
                _towers.Remove(t);
            }
        }

        public void RegisterBullet(BaseBullet b)
        {
            if (b != null && !_bullets.Contains(b))
            {
                _bullets.Add(b);
            }
        }

        public void UnregisterBullet(BaseBullet b)
        {
            if (b != null)
            {
                _bullets.Remove(b);
            }
        }

        private void UnregisterAll()
        {
            _enemies.Clear();
            _towers.Clear();
            _bullets.Clear();
        }

        // ------------------------------------------------------------------
        // 主循环
        // ------------------------------------------------------------------

        private void OnUpdate()
        {
            float dt = GameClock.DeltaTime;

            // ① 怪物移动 → 同步空间哈希
            TickEnemies(dt);

            // ② 塔索敌与开火
            TickTowers(dt);

            // ③ 子弹推进与命中判定
            TickBullets(dt);

            // ④ 路径重算节流（建塔/拆塔后置脏标记，这里统一处理）
            AStarManager.Instance.ProcessRefresh();

            TickStats(dt);
        }

        private void TickEnemies(float dt)
        {
            // 【为什么用快照遍历，而不是直接按索引倒序边遍历边删】
            // e.Tick() 内部会经由
            //   MoveAlongPath → OnReachEnd → EnemyManager.RecycleEnemy → UnregisterEnemy
            // 把元素从 _enemies 里删掉；也可能一次删掉多个（例如漏怪同时触发失败流程）。
            // 那样外层循环持有的索引就失效了，随后的 RemoveAt(i) 会
            // ArgumentOutOfRangeException —— 这是真实踩到的崩溃（行 279）。
            //
            // 改成"先快照遍历、再单独清理"：遍历期间完全不碰 _enemies，索引自然安全；
            // 清理趟只做纯数据操作（不调用外部代码），不会引发二次修改。
            _tickSnapshot.Clear();
            _tickSnapshot.AddRange(_enemies);
            for (int i = 0; i < _tickSnapshot.Count; i++)
            {
                BaseEnemy e = _tickSnapshot[i];
                // 已彻底回收的跳过；死亡动画播放中的仍要 Tick（它靠 Tick 推进回收倒计时）
                if (e == null || e.IsFullyRecycled)
                {
                    continue;
                }
                e.Tick(dt);
            }

            // 清理趟：统计存活数、移除空引用与已彻底回收的
            AliveEnemyCount = 0;
            for (int i = _enemies.Count - 1; i >= 0; i--)
            {
                BaseEnemy e = _enemies[i];
                if (e == null || (!e.IsAlive && e.IsFullyRecycled))
                {
                    _enemies.RemoveAt(i);
                    continue;
                }
                if (e.IsAlive)
                {
                    AliveEnemyCount++;
                    Grid.Update(e, e.Position);
                }
            }
        }

        private void TickTowers(float dt)
        {
            for (int i = _towers.Count - 1; i >= 0; i--)
            {
                BaseTower t = _towers[i];
                if (t == null)
                {
                    _towers.RemoveAt(i);
                    continue;
                }
#if UNITY_EDITOR
                if (BaseTower.EvidenceTrackReentry)
                    for (int k = 0; k < _enemies.Count; k++)
                        if (_enemies[k] != null) t.ObserveEvidenceRange(_enemies[k]);
#endif
                t.TickAttack(dt);
                t.TickVisual(dt);   // 光环脉冲渐隐等纯表现，必须每帧推进
            }
        }

        private void TickBullets(float dt)
        {
            for (int i = _bullets.Count - 1; i >= 0; i--)
            {
                BaseBullet b = _bullets[i];
                if (b == null)
                {
                    _bullets.RemoveAt(i);
                    continue;
                }
                b.Tick(dt);
            }
        }

        private void TickStats(float dt)
        {
            // ① 「无目标开火」是**正确性不变量**，与调试开关无关：一旦发生就必须报出来。
            //    正常应恒为 0；不为 0 说明塔的开火条件写错了。只报一次，不刷屏。
            if (StatIdleFireAttempt > 0 && !_idleFireReported)
            {
                _idleFireReported = true;
                Debug.LogError(string.Format(
                    "[Combat] 检测到 {0} 次「无目标开火」—— 塔在没有目标时开了火，\n" +
                    "  请检查 BaseTower.TickAttack 的开火条件（正常应为 0）", StatIdleFireAttempt));
            }

            // ② 周期性汇总：只在开了调试日志时输出
            if (Configs.Global == null || !Configs.Global.ShowDebugLog)
            {
                return;
            }
            _statTimer += dt;
            if (_statTimer < _statInterval)
            {
                return;
            }
            _statTimer = 0f;

            // 场上什么都没有就不打 —— 否则空闲期每 5 秒一条，会把 Console 刷满
            // （日志被刷屏会掩盖真正的错误，这是实际踩过的坑）
            if (_enemies.Count == 0 && _towers.Count == 0 && _bullets.Count == 0)
            {
                return;
            }

            int statSearch = 0;
            int statFire = 0;
            for (int i = 0; i < _towers.Count; i++)
            {
                if (_towers[i] != null)
                {
                    statSearch += _towers[i].SearchCount;
                    statFire += _towers[i].FireCount;
                }
            }

            Debug.Log(string.Format(
                "[Combat] 怪={0}(存活{1}) 塔={2} 弹={3} | 索敌次数={4} 开火次数={5} 命中={6} 空放尝试={7} | {8}",
                _enemies.Count, AliveEnemyCount, _towers.Count, _bullets.Count,
                statSearch, statFire, StatHitCount, StatIdleFireAttempt,
                Grid.DumpDebugInfo()));
            // （空放检查已移到本方法开头，且与调试开关无关，不在这里重复）
        }

        public void ResetStats()
        {
            StatSearchCount = 0;
            StatFireCount = 0;
            StatHitCount = 0;
            StatIdleFireAttempt = 0;
            // 一次性告警的"已报过"标志也要复位 —— 否则切到新关卡后即使真的再次出现
            // 无目标开火，也不会再报（那个报错是正确性不变量，不能只报全局一次）。
            _idleFireReported = false;
        }

        /// <summary>由塔内部统计（集中上报，便于自检）</summary>
        public void AddSearchCount(int n) { StatSearchCount += n; }
        public void AddFireCount(int n) { StatFireCount += n; }
        public void AddHitCount(int n) { StatHitCount += n; }
        public void AddIdleFireAttempt(int n) { StatIdleFireAttempt += n; }

        /// <summary>
        /// 把在场塔复制到 dst（切关时统一清理用）。
        /// 【为什么给快照而不是暴露内部列表】直接暴露 _towers 会让调用方在遍历时改到它 ——
        /// 本项目在 TickEnemies 里已经因为同类问题崩过一次（见那里的长注释）。
        /// </summary>
        public void CopyTowers(List<BaseTower> dst)
        {
            dst.Clear();
            dst.AddRange(_towers);
        }

        /// <summary>把在场子弹复制到 dst（切关时统一回收用）</summary>
        public void CopyBullets(List<BaseBullet> dst)
        {
            dst.Clear();
            dst.AddRange(_bullets);
        }

        public int TowerCount { get { return _towers.Count; } }
        public int BulletCount { get { return _bullets.Count; } }
        public int EnemyCount { get { return _enemies.Count; } }

        public string DumpDebugInfo()
        {
            return string.Format("[Combat] 怪 {0}（存活 {1}）/ 塔 {2} / 弹 {3}\n{4}",
                _enemies.Count, AliveEnemyCount, _towers.Count, _bullets.Count,
                Grid != null ? Grid.DumpDebugInfo() : "(Grid 未初始化)");
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 均匀网格空间哈希（Uniform Grid Spatial Hash）。
    ///
    /// 用途：替代 v1.0 的 `SphereCollider + OnTriggerEnter` 索敌方案。
    /// 原方案的复杂度是 O(塔数 × 敌人数) 的物理触发器对，低端机上物理宽相/窄相是主要开销。
    /// 本方案把空间查询接管过来：
    ///   - 敌人移动时更新所在格子：**未跨格则零开销**（关键优化）
    ///   - 塔索敌只查询邻域格子，复杂度 O(邻域常数)，与全场怪物总数无关
    ///
    /// cellSize 建议取值 ≈ 最大索敌半径，这样邻域在 3×3 ~ 7×7 个格子之间。
    /// </summary>
    public class EnemyGrid
    {
        private readonly Dictionary<int, List<BaseEnemy>> _cells;
        private readonly float _cellSize;
        private readonly int _cols;   // 用于把 (cx, cy) 压成一维 key

        public EnemyGrid(float cellSize, int cols)
        {
            _cellSize = Mathf.Max(0.1f, cellSize);
            _cols = Mathf.Max(1, cols);
            _cells = new Dictionary<int, List<BaseEnemy>>(256);
        }

        public float CellSize { get { return _cellSize; } }

        private int Key(int cx, int cy)
        {
            // 允许负坐标（棋盘左上为原点时 cy 可能为负）
            return (cy + 4096) * 8192 + (cx + 4096);
        }

        private void CellCoord(Vector2 pos, out int cx, out int cy)
        {
            cx = Mathf.FloorToInt(pos.x / _cellSize);
            cy = Mathf.FloorToInt(pos.y / _cellSize);
        }

        /// <summary>
        /// 同步一个敌人的位置。若未跨越格子则**直接返回**（这是本类最重要的优化）。
        /// </summary>
        public void Update(BaseEnemy e, Vector2 pos)
        {
            if (e == null)
            {
                return;
            }
            int cx, cy;
            CellCoord(pos, out cx, out cy);
            int key = Key(cx, cy);
            if (e.GridKey == key)
            {
                return;
            }
            Remove(e);
            List<BaseEnemy> list;
            if (!_cells.TryGetValue(key, out list))
            {
                list = new List<BaseEnemy>(8);
                _cells[key] = list;
            }
            list.Add(e);
            e.GridKey = key;
        }

        /// <summary>把敌人从它所在格子移除（回收/死亡时调用）</summary>
        public void Remove(BaseEnemy e)
        {
            if (e == null || e.GridKey == 0)
            {
                return;
            }
            List<BaseEnemy> list;
            if (_cells.TryGetValue(e.GridKey, out list))
            {
                list.Remove(e);
                if (list.Count == 0)
                {
                    _cells.Remove(e.GridKey);
                }
            }
            e.GridKey = 0;
        }

        /// <summary>
        /// 查询圆形范围覆盖到的所有格子，把候选敌人追加进 result。
        /// 注意：返回的是**候选集**（含少量范围外的元素），调用方必须再用精确距离过滤。
        /// </summary>
        public void QueryCircle(Vector2 center, float radius, List<BaseEnemy> result)
        {
            if (result == null)
            {
                return;
            }
            int minX = Mathf.FloorToInt((center.x - radius) / _cellSize);
            int maxX = Mathf.FloorToInt((center.x + radius) / _cellSize);
            int minY = Mathf.FloorToInt((center.y - radius) / _cellSize);
            int maxY = Mathf.FloorToInt((center.y + radius) / _cellSize);

            for (int cy = minY; cy <= maxY; cy++)
            {
                for (int cx = minX; cx <= maxX; cx++)
                {
                    List<BaseEnemy> list;
                    if (_cells.TryGetValue(Key(cx, cy), out list))
                    {
                        result.AddRange(list);
                    }
                }
            }
        }

        /// <summary>清理已失效（回收/销毁）的引用，返回清理掉的数量</summary>
        public int CleanupInvalid()
        {
            int removed = 0;
            List<int> emptyKeys = null;
            foreach (KeyValuePair<int, List<BaseEnemy>> kv in _cells)
            {
                List<BaseEnemy> list = kv.Value;
                for (int i = list.Count - 1; i >= 0; i--)
                {
                    BaseEnemy e = list[i];
                    if (e == null || !e.IsAlive)
                    {
                        list.RemoveAt(i);
                        if (e != null)
                        {
                            e.GridKey = 0;
                        }
                        removed++;
                    }
                }
                if (list.Count == 0)
                {
                    if (emptyKeys == null)
                    {
                        emptyKeys = new List<int>();
                    }
                    emptyKeys.Add(kv.Key);
                }
            }
            if (emptyKeys != null)
            {
                for (int i = 0; i < emptyKeys.Count; i++)
                {
                    _cells.Remove(emptyKeys[i]);
                }
            }
            return removed;
        }

        public void Clear()
        {
            _cells.Clear();
        }

        /// <summary>占用格子数（诊断用）</summary>
        public int UsedCellCount { get { return _cells.Count; } }

        public string DumpDebugInfo()
        {
            int total = 0;
            foreach (KeyValuePair<int, List<BaseEnemy>> kv in _cells)
            {
                total += kv.Value.Count;
            }
            return string.Format("EnemyGrid: cells={0}, enemies={1}, cellSize={2}",
                _cells.Count, total, _cellSize);
        }
    }
}

namespace FTProject
{
    /// <summary>
    /// 怪物类型。
    ///
    /// 【v2.1 说明】类型标签只用于分类展示与筛选（例如后续做"只攻击地面单位"的塔），
    /// **不再驱动资源选择** —— 资源一律由 TBEnemyData.resName 决定，
    /// 这样新增一种怪只需加一行配置，不用改代码、不用加枚举。
    ///
    /// 原来的 PointType / BulletType / EnemyState / TowerBuildState / BulletState 已移除：
    ///   - PointType/TowerBuildState 属于已废弃的 Node/Obstacle 3D 节点体系
    ///   - BulletState 定义在 BaseBullet.cs（与使用处相邻，便于维护）
    ///   - EnemyState 与新的 EnemyAnimState（Animator 的 int 参数 State）语义重复
    /// </summary>
    public enum EnemyType
    {
        NONE = 0,
        /// <summary>普通地面单位</summary>
        Normal = 1,
        /// <summary>快速单位</summary>
        Quick = 2,
        /// <summary>重甲单位</summary>
        Armored = 3,
        /// <summary>飞行单位（M0 未启用）</summary>
        Flying = 4,
        /// <summary>Boss</summary>
        Boss = 5,
    }

    /// <summary>
    /// 特殊效果类型。**塔表与子弹表共用这一套编号**（图例写在两张 xlsx 的第 3 行注释里）。
    ///
    /// 【为什么塔和子弹共用一个枚举】两处各写一套编号，迟早会出现
    /// "表里填 2 以为在说 AOE、代码里 2 却当成持续伤害"这类只有运行时才暴露的错。
    /// 共用一个枚举 + 一份图例，是这个项目里成本最低的一致性保障。
    ///
    /// 【谁说了算】真正的**命中效果**以子弹的 effectType 为准；
    /// 塔的 effectType 目前只用于①分类展示（塔型级的行为差异改由 TowerType 判定）。
    /// 效果**强度**：塔的 effectValue > 0 时覆盖子弹的 effectValue，否则用子弹自己的。
    ///
    /// 【减速塔（TowerType.Slow / 美术名 Retard）是例外】它不走"命中"这条路：
    ///   M3 起改为**范围光环**——射程内所有敌人持续减速，不发射子弹、不索敌。
    ///   其 effectValue 直接就是减速比例（0.5/0.6/0.7），由 BaseTower.TickSlowAura 使用；
    ///   塔表里保留 effectType=1 只为让 UI 分类与图例口径一致，**不参与运行时判定**
    ///   （判定用 TowerConfig.IsSlowAura，即 Type==3）。
    ///
    /// 【2026-10-14 三塔型收敛】原 Laser(4) 已随激光塔一并删除，编号不回收不复用。
    /// </summary>
    public enum EffectType
    {
        /// <summary>无特殊效果</summary>
        None = 0,
        /// <summary>减速：effectValue = 减速比例 0~1（实际速度 = 原速 × (1 - effectValue)）</summary>
        Slow = 1,
        /// <summary>持续伤害：effectValue = 每秒伤害</summary>
        Dot = 2,
        /// <summary>范围伤害：半径由子弹的 aoeRadius 决定</summary>
        Aoe = 3,
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{

    /// <summary>
    /// 由EventDispatcher持有，请不用直接使用此类。
    /// </summary>
    public class EventController
    {
        /// <summary>
        /// //永久性的消息，在Cleanup的时候，这些消息的响应是不会被清理的。
        /// </summary>
        private List<string> m_permanentEvents = new List<string>();
        private Dictionary<string, Delegate> m_theRouter = new Dictionary<string, Delegate>();

        public void AddEventListener(string eventType, Action handler)
        {
            this.OnListenerAdding(eventType, handler);
            this.m_theRouter[eventType] = (Action)Delegate.Combine((Action)this.m_theRouter[eventType], handler);
        }

        public void AddEventListener<T>(string eventType, Action<T> handler)
        {
            this.OnListenerAdding(eventType, handler);
            this.m_theRouter[eventType] = (Action<T>)Delegate.Combine((Action<T>)this.m_theRouter[eventType], handler);
        }
        public void AddEventListener<T, U>(string eventType, Action<T, U> handler)
        {
            this.OnListenerAdding(eventType, handler);
            this.m_theRouter[eventType] = (Action<T, U>)Delegate.Combine((Action<T, U>)this.m_theRouter[eventType], handler);
        }
        public void AddEventListener<T, U, V>(string eventType, Action<T, U, V> handler)
        {
            this.OnListenerAdding(eventType, handler);
            this.m_theRouter[eventType] = (Action<T, U, V>)Delegate.Combine((Action<T, U, V>)this.m_theRouter[eventType], handler);
        }
        public void AddEventListener<T, U, V, W>(string eventType, Action<T, U, V, W> handler)
        {
            this.OnListenerAdding(eventType, handler);
            this.m_theRouter[eventType] = (Action<T, U, V, W>)Delegate.Combine((Action<T, U, V, W>)this.m_theRouter[eventType], handler);
        }
        public void Cleanup()
        {
            List<string> list = new List<string>();
            foreach (KeyValuePair<string, Delegate> pair in this.m_theRouter)
            {
                bool flag = false;
                foreach (string str in this.m_permanentEvents)
                {
                    if (pair.Key == str)
                    {
                        flag = true;
                        break;
                    }
                }
                if (!flag)
                {
                    list.Add(pair.Key);
                }
            }
            foreach (string str in list)
            {
                this.m_theRouter.Remove(str);
            }
        }
        public bool ContainsEvent(string eventType)
        {
            return this.m_theRouter.ContainsKey(eventType);
        }
        public void MarkAsPermanent(string eventType)
        {
            this.m_permanentEvents.Add(eventType);
        }



        private void OnListenerAdding(string eventType, Delegate listenerBeingAdded)
        {
            if (!this.m_theRouter.ContainsKey(eventType))
            {
                this.m_theRouter.Add(eventType, null);
            }
            Delegate delegate2 = this.m_theRouter[eventType];
            if ((delegate2 != null) && (delegate2.GetType() != listenerBeingAdded.GetType()))
            {
                //throw new EventException(string.Format("Try to add not correct event {0}. Current type is {1}, adding type is {2}.", eventType, delegate2.GetType().Name, listenerBeingAdded.GetType().Name));
                Debug.LogError("something error here");
            }
        }

        private void OnListenerRemoved(string eventType)
        {
            if (this.m_theRouter.ContainsKey(eventType) && (this.m_theRouter[eventType] == null))
            {
                this.m_theRouter.Remove(eventType);
            }
        }

        private bool OnListenerRemoving(string eventType, Delegate listenerBeingRemoved)
        {
            if (!this.m_theRouter.ContainsKey(eventType))
            {
                return false;
            }
            Delegate delegate2 = this.m_theRouter[eventType];
            if ((delegate2 != null) && (delegate2.GetType() != listenerBeingRemoved.GetType()))
            {
                //throw new EventException(string.Format("Remove listener {0}\" failed, Current type is {1}, adding type is {2}.", eventType, delegate2.GetType(), listenerBeingRemoved.GetType()));
                Debug.LogError("something error here");

            }
            return true;
        }


