        /// 【为什么带阶段文案】LoadingView 的 StatusText 要随阶段变（"正在初始化资源系统..." → "正在加载配置表..."），
        /// 只给一个 0~1 数字无法表达"当前在做什么"，玩家会觉得进度条在空转。</summary>
        public const string LoadingProgressEvent = "LoadingProgressEvent";

        /// <summary>热更新阶段文案，参数：string（"正在检查更新..." / "正在下载资源..." / "已暂停" ...）。
        /// 【为什么与进度分成两个事件】EventDispatcher 的泛型重载最多 4 个类型参数，
        /// 而本界面需要"文案 + 文件数 + 字节数"共 5 项信息。
        /// 拆成"文案"与"数值"两个事件，既绕开上限，也让语义更清楚（文案变化远比进度稀疏）。</summary>
        public const string HotUpdatePhaseEvent = "HotUpdatePhaseEvent";

        /// <summary>热更新进度，参数：(int 已下载文件数, int 总文件数, long 已下载字节, long 总字节)</summary>
        public const string HotUpdateProgressEvent = "HotUpdateProgressEvent";

        /// <summary>热更新失败，参数：string 失败原因（HotUpdateView 显示红字并给"重试"）</summary>
        public const string HotUpdateFailedEvent = "HotUpdateFailedEvent";

        /// <summary>热更新完成（无论是否真的更新过内容），Launcher 据此继续走配置表加载</summary>
        public const string HotUpdateFinishedEvent = "HotUpdateFinishedEvent";

        // ------------------------------------------------------------------
        // 主菜单与图鉴（UI 补全 B1/B2/B3/B4）
        // ------------------------------------------------------------------

        /// <summary>请求打开主菜单</summary>
        public const string OpenMainMenuRequestEvent = "OpenMainMenuRequestEvent";

        /// <summary>主菜单点「开始游戏」请求进入选关</summary>
        public const string StartGameRequestEvent = "StartGameRequestEvent";

        /// <summary>请求打开图鉴，参数：bool（true=塔图鉴，false=怪物图鉴）</summary>
        public const string OpenCodexRequestEvent = "OpenCodexRequestEvent";

        /// <summary>请求打开关卡详情弹窗，参数：int 关卡 id</summary>
        public const string OpenLevelDetailRequestEvent = "OpenLevelDetailRequestEvent";

        // ------------------------------------------------------------------
        // 出售二次确认（UI 补全 C1）
        // ------------------------------------------------------------------

        /// <summary>出售已在 SellConfirmView 里被确认，参数：BaseTower。
        /// 【与 TowerSellRequestEvent 的区别】后者是"玩家点了出售按钮"（意图），
        /// 本事件是"玩家在确认弹窗里点了确认"（决定）。GameFlowManager 只监听本事件真正执行出售，
        /// 这样"取消"永远不可能误卖。</summary>
        public const string TowerSellConfirmEvent = "TowerSellConfirmEvent";
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 全局模拟时钟（P2b 新增）——**全工程唯一的速度源**。
    ///
    /// 【为什么要一个独立的速度参数，而不是直接用 Time.timeScale】
    ///   `Time.timeScale` 在本工程里语义已经被**收窄为"暂停开关"**（只允许 0 / 1）。
    ///   若拿它做倍速，会连带影响所有 unscaled 之外的系统：UI 动画、相机震动、
    ///   对象池回收倒计时…… 全都会一起变快，而它们本该是"实时"的。
    ///   所以倍速走独立的 <see cref="Speed"/> 参数，只有真正参与"模拟推进"的系统
    ///   才消费 <see cref="DeltaTime"/>（消费清单见策划案 §7.3.1）。
    ///
    /// 【同帧同值：DeltaTime 必须只有一份】
    ///   如果各系统各自写 `Time.deltaTime * GameClock.Speed`，同一帧里不同系统读到的
    ///   Speed 可能不同（改档恰好发生在两帧之间），表现为"怪物走一步、塔的 CD 少两格"。
    ///   因此 DeltaTime 按**帧号**缓存：同帧内无论谁先取、谁取几次，拿到的都是同一个值。
    ///
    /// 【为什么用帧号惰性缓存，而不是只靠 Tick() 主动刷新】
    ///   Unity 不保证 `Launcher.Update`（驱动 CombatSystem）与 `GameFlowManager.Update`
    ///   的先后顺序。若只靠 GameFlowManager.Update 里调 Tick()，一旦它的 Update 排在后面，
    ///   本帧的模拟就会用到上一帧的缓存值（首帧甚至可能是 0）。
    ///   用帧号做键后，"谁先取谁负责算"，执行顺序就完全无关紧要了 —— Tick() 仍然保留，
    ///   当作一个"提前算好"的显式入口（也满足程序案里对 Tick() 的要求）。
    ///
    /// 【暂停怎么走】暂停仍然靠 `Time.timeScale = 0`：此时 `Time.deltaTime` 为 0，
    ///   于是 DeltaTime 也为 0，全部模拟自然停摆 —— 倍速与暂停是两条互不写入的通道。
    ///   2026-10-18 起，暂停的**唯一写入口**是 <see cref="SetPaused"/>（由 GameFlowManager 调），
    ///   UI 不再各自写 timeScale（旧 PauseView 在 OnEnable/OnDisable 里写，已移除）。
    /// </summary>
    public static class GameClock
    {
        /// <summary>
        /// 合法档位。**只有这里定义一次**：HudView 的"循环切档"与 GameFlowManager 的
        /// "档位合法性校验"都读它，避免两处各写一份 1/2/3 而改一处漏一处。
        /// 需要"降档"（例如 ×3 帧率不达标改 ×2.5）时，只改这里一个数字即可，结构不变。
        /// </summary>
        public static readonly float[] Tiers = { 1f, 2f, 3f };

        private static float _speed = 1f;

        private static float _cachedDelta;
        private static int _cachedFrame = -1;

        // 关卡计时（UI 补全 B4「最佳用时」的数据源）
        private static double _levelElapsed;
        private static double _combatElapsed;
        private static bool _combatTimerRunning;
        private static bool _background;
#if UNITY_EDITOR
        private static bool _manualSimulation;
        public static bool IsManualSimulation { get { return _manualSimulation; } }
        private sealed class ManualSimulationScope : System.IDisposable
        {
            public void Dispose() { _manualSimulation = false; _cachedFrame = -1; _cachedDelta = 0f; }
        }
        public static System.IDisposable BeginManualSimulation()
        {
            if (_manualSimulation) throw new System.InvalidOperationException("Manual simulation is already active");
            _manualSimulation = true; _cachedDelta = 0f;
            return new ManualSimulationScope();
        }
        public static void StepManualFrame(double unscaledDelta)
        {
            if (!_manualSimulation) throw new System.InvalidOperationException("BeginManualSimulation must be called first");
            // Preserve the requested fixed simulation step when replay divides it
            // by 3x speed; round once, at the same float DeltaTime boundary as play.
            _cachedDelta = _background || Time.timeScale <= 0f ? 0f : (float)(System.Math.Max(0d, unscaledDelta) * _speed);
            if (_levelTimerRunning) _levelElapsed += _cachedDelta;
            if (_combatTimerRunning) _combatElapsed += _cachedDelta;
        }
#endif
        private static bool _levelTimerRunning;

        /// <summary>
        /// 当前模拟速度倍率（默认 1）。
        /// 设 0 或负数会静默回落到 1 —— 0 会让整个世界无声冻结，是极难排查的状态，
        /// 宁可忽略这次非法写入。
        /// </summary>
        public static float Speed
        {
            get { return _speed; }
            set { _speed = value > 0f ? value : 1f; }
        }

        /// <summary>
        /// 当前是否处于暂停态（只认 `Time.timeScale &lt;= 0` 这一种口径）。
        /// 【为什么把暂停也收到这里】timeScale 在本工程语义收窄为"暂停开关"，
        ///   而它是全局唯一的一份状态；散在 UI / 流程层各写一次必然出现
        ///   "界面关了但还停着"或"点了继续其实没恢复"这类互相打架的状态。
        ///   所以暂停的**写入口**只有 <see cref="SetPaused"/> 一个（GameFlowManager 调用）。
        /// </summary>
        public static bool IsPaused
        {
            get { return Time.timeScale <= 0f; }
        }

        /// <summary>
        /// 暂停 / 继续的唯一写入口。
        /// 【为什么要把帧缓存作废】暂停那一帧之前可能已经算过 `_cachedDelta`，
        ///   恢复当帧若沿用旧值，会让模拟多吃一帧（表现为"继续后怪物瞬移一小步"）。
        /// </summary>
        public static void SetPaused(bool paused)
        {
            Time.timeScale = paused ? 0f : 1f;
            _cachedFrame = -1;
        }

        /// <summary>
        /// 本帧的模拟步长 = `Time.deltaTime × Speed`。同帧内恒为同一个值。
        /// 所有"参与模拟推进"的系统都从这里取时间，而不是自己乘 Speed。
        /// </summary>
        public static float DeltaTime
        {
            get
            {
                RefreshFrame(Time.frameCount, Time.deltaTime);
                return _cachedDelta;
            }
        }

        /// <summary>
        /// 本关已进行的**游戏内时间**（秒）。进关时归零，见 <see cref="ResetLevelTimer"/>。
        /// 【语义】不是墙钟时间：×3 倍速下 1 秒墙钟 = 3 秒计时。
        /// </summary>
        public static float LevelElapsedSec
        {
            get { return (float)_levelElapsed; }
        }
        public static double LevelElapsedSeconds { get { return _levelElapsed; } }
        public static double CombatElapsedSeconds { get { return _combatElapsed; } }
        public static bool IsLevelTimerRunning { get { return _levelTimerRunning; } }
        public static long CombatElapsedMs { get { return LevelRunMetrics.ToMilliseconds(_combatElapsed); } }
        public static long LevelElapsedMs { get { return LevelRunMetrics.ToMilliseconds(_levelElapsed); } }

        /// <summary>开始/重开一关：归零并启动计时（GameFlowManager.InitLevel 调用）。</summary>
        public static void ResetLevelTimer()
        {
            _levelElapsed = 0d;
            _combatElapsed = 0d;
            _levelTimerRunning = false;
            _combatTimerRunning = false;
            _background = false;
        }
        public static void StartLevelTimer() { RefreshFrame(Time.frameCount, Time.deltaTime); _levelTimerRunning = true; }
        public static void SetCombatRunning(bool running) { RefreshFrame(Time.frameCount, Time.deltaTime); _combatTimerRunning = running; }
        public static void SetBackground(bool background) { _background = background; }
        public static void RestoreTimers(double combatSeconds, double levelSeconds, bool levelStarted)
        {
            _combatElapsed = combatSeconds; _levelElapsed = levelSeconds;
            _combatTimerRunning = false; _levelTimerRunning = levelStarted;
            _cachedFrame = Time.frameCount;
        }

        /// <summary>停止计时（结算/退出对局时调用；停止后 LevelElapsedSec 保留最后值供结算读取）。</summary>
        public static void StopLevelTimer()
        {
            _levelTimerRunning = false;
            _combatTimerRunning = false;
        }

        /// <summary>显式刷新本帧缓存值（调用时机不敏感，见类注释）。</summary>
        public static void Tick()
        {
            RefreshFrame(Time.frameCount, Time.deltaTime);
        }
        // Public deterministic frame seam also lets EditMode tests verify ordering and speed.
        public static void RefreshFrame(int frame, float scaledDeltaSeconds)
        {
#if UNITY_EDITOR
            if (_manualSimulation) return;
#endif
            if (_cachedFrame == frame) return;
            _cachedFrame = frame;
            _cachedDelta = _background ? 0f : Mathf.Max(0f, scaledDeltaSeconds) * _speed;
            if (_levelTimerRunning) _levelElapsed += _cachedDelta;
            if (_combatTimerRunning) _combatElapsed += _cachedDelta;
        }

        /// <summary>回到 ×1（GameOver / 重开 / 回选关 / 进 Loading 时必须调用）。</summary>
        public static void Reset()
        {
            _speed = 1f;
            _cachedFrame = -1;   // 强制下一次取值重算，避免残留上一帧缓存
        }

        /// <summary>是否是一个合法档位（用于校验来自 UI 的请求，防止越界值）。</summary>
        public static bool IsValidTier(float value)
        {
            for (int i = 0; i < Tiers.Length; i++)
            {
                if (Mathf.Approximately(Tiers[i], value))
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>取当前档位的下一档（循环：×1→×2→×3→×1）。当前值不在档位表里时回落到第一档。</summary>
        public static float NextTier(float current)
        {
            for (int i = 0; i < Tiers.Length; i++)
            {
                if (Mathf.Approximately(Tiers[i], current))
                {
                    return Tiers[(i + 1) % Tiers.Length];
                }
            }
            return Tiers[0];
        }
    }
}

using System;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// BGM 交叉淡入淡出驱动（M4-W7）。
    ///
    /// 【为什么要单独一个 MonoBehaviour】
    ///   `AudioManager` 继承 `BaseManager&lt;T&gt;`，是**纯 C# 单例，没有 Update**。
    ///   而淡入淡出必须逐帧推进。所以把"逐帧的那部分"抽成本组件，
    ///   挂在 AudioRoot 上（它挂在 Launcher 下，DontDestroyOnLoad，跨场景常驻）。
    ///
    /// 【为什么只保存"系数"而不是直接改 AudioSource.volume】
    ///   实际音量 = 基准音量(TBAudio) × 本驱动的淡入淡出系数 × 主音量 × (静音?0:1)。
    ///   如果本驱动直接写 `AudioSource.volume`，那么玩家在设置里调音量 / 切静音时，
    ///   会和正在进行的淡化**互相覆盖**（表现为"调了音量又自己弹回去"）。
    ///   所以本驱动只维护 0~1 的系数，绝对音量统一由 AudioManager 计算 —— 单一写入方。
    ///
    /// 【两个槽】A/B 两槽分别对应换曲前的旧曲与换曲后的新曲：
    ///   新曲 0→1、旧曲 1→0 同时进行，就是"交叉淡化"；任一时刻最多只有两首在播。
    ///
    /// 【时间口径】用 `unscaledDeltaTime`：暂停界面把 `Time.timeScale` 设成 0，
    ///   若用缩放时间，淡化会连同游戏一起冻住（音量卡在半途，恢复时听感突兀）。
    /// </summary>
    public class AudioFadeDriver : MonoBehaviour
    {
        /// <summary>交叉淡化用的槽数（旧曲 / 新曲）。</summary>
        public const int Slots = 2;

        private readonly float[] _cur = new float[Slots];
        private readonly float[] _from = new float[Slots];
        private readonly float[] _target = new float[Slots];

        private float _elapsed;
        private float _duration;
        private bool _running;

        /// <summary>系数发生变化时触发，AudioManager 借此重算实际音量。</summary>
        public event Action Changed;

        /// <summary>一次过渡结束时触发（用于停掉旧槽、完成 StopBgm）。</summary>
        public event Action Finished;

        /// <summary>当前过渡是否在进行中。</summary>
        public bool Running { get { return _running; } }

        /// <summary>取某槽当前的淡入淡出系数（0~1）。越界返回 1（不淡）。</summary>
        public float Scale(int slot)
        {
            return (slot >= 0 && slot < Slots) ? _cur[slot] : 1f;
        }

        /// <summary>
        /// 直接把某槽设成给定系数，**不产生过渡**。
        /// 用途：新曲开始播放前先归零，避免它以上一次的残留音量"闪一下"。
        /// </summary>
        public void Prime(int slot, float value)
        {
            if (slot < 0 || slot >= Slots)
            {
                return;
            }
            value = Mathf.Clamp01(value);
            _cur[slot] = value;
            _from[slot] = value;
            _target[slot] = value;
            RaiseChanged();
        }

        /// <summary>
        /// 开始一次过渡：所有槽在 duration 秒内平滑趋近各自目标。
        /// duration ≤ 0 时立即到位并同步触发 Finished（调用方无需区分零时长）。
        /// </summary>
        public void Begin(float target0, float target1, float duration)
        {
            _from[0] = _cur[0];
            _from[1] = _cur[1];
            _target[0] = Mathf.Clamp01(target0);
            _target[1] = Mathf.Clamp01(target1);
            _elapsed = 0f;
            _duration = Mathf.Max(0f, duration);

            if (_duration <= 0.0001f)
            {
                _cur[0] = _target[0];
                _cur[1] = _target[1];
                _running = false;
                RaiseChanged();
                RaiseFinished();
                return;
            }

            _running = true;
        }

        /// <summary>放弃当前过渡（保持当前系数，不再推进）。</summary>
        public void Cancel()
        {
            _running = false;
        }

        private void Update()
        {
            if (!_running)
            {
                return;
            }

            _elapsed += Time.unscaledDeltaTime;
            float t = Mathf.Clamp01(_elapsed / _duration);
            float s = t * t * (3f - 2f * t);   // SmoothStep：两端速度为 0，听感更自然

            _cur[0] = Mathf.Lerp(_from[0], _target[0], s);
            _cur[1] = Mathf.Lerp(_from[1], _target[1], s);
            RaiseChanged();

            if (t >= 1f)
            {
                _cur[0] = _target[0];
                _cur[1] = _target[1];
                _running = false;
                RaiseChanged();
                RaiseFinished();
            }
        }

        private void RaiseChanged()
        {
            if (Changed != null)
            {
                Changed();
            }
        }

        private void RaiseFinished()
        {
            if (Finished != null)
            {
                Finished();
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 音效 / 背景乐管理器（M2-W6 建系统，M4-W7 补 BGM）。
    ///
    /// 【设计口径：没有文件时完全静默、不影响玩法】
    ///   三段式查找任一环节缺失都只是"跳过 + 限流警告一次"，
    ///   绝不抛异常、绝不阻塞流程 —— 音效是最不该阻塞玩法的功能。
    ///   文件到位后**不改一行代码就能发声**（把文件丢进 Assets/Audio/ 跑生成器即可）。
    ///
    /// 【三段式查找】Play(logicalName) →
    ///   ① Configs.GetAudio 取音量/音高/循环（TBAudio 表）
    ///   ② ResLoader 取 Audio_&lt;logicalName&gt; 的 AudioClip（ResTable，由 AudioCatalog 生成）
    ///   ③ 从 AudioSource 池取一个播放
    ///
    /// 【为什么警告要限流】没有音频文件时，每次开火都会走到"取不到 Clip"这一支。
    ///   不限流的话 Console 会被瞬间刷爆，反而把真正的错误淹掉 ——
    ///   这是本项目已经踩过的坑（见 CombatSystem.TickStats 的注释）。
    ///
    /// 【音效 与 BGM 是两套通道】
    ///   音效：池化（12 个源）、点完即弃、可 3D。
    ///   BGM：**固定 2 个源**（A/B 槽做交叉淡化）、常驻循环、只能 2D。
    ///   两者分开的原因：BGM 是长音且唯一，扔进池里会被"顶掉最旧的一个"逻辑误杀。
    ///
    /// ⚠️ 本类继承 BaseManager&lt;T&gt;，是**纯 C# 单例，没有 Update**；
    ///    BGM 的逐帧淡化由挂在 AudioRoot 上的 <see cref="AudioFadeDriver"/> 负责。
    /// </summary>
    public class AudioManager : BaseManager<AudioManager>
    {
        /// <summary>音效 AudioSource 池大小。同一帧最多这么多音效同时播放，超出则复用最旧的一个。</summary>
        private const int SourcePoolSize = 12;

        /// <summary>最多打印多少条"缺资源"警告（每种逻辑名最多一条）</summary>
        private const int MaxWarnings = 8;

        /// <summary>换 BGM / 停止 BGM 的默认交叉淡化时长（秒）。</summary>
        private const float BgmCrossFadeSec = 0.8f;

        private AudioSource[] _sources;
        private int _next;
        private bool _inited;
        private readonly HashSet<string> _warned = new HashSet<string>();
        private int _warnCount;

        // ---- BGM 通道 ----
        private AudioSource[] _bgmSources;
        private readonly float[] _bgmBase = new float[AudioFadeDriver.Slots];
        private AudioFadeDriver _fadeDriver;
        private int _bgmActive = -1;          // 当前在播的槽；-1 = 无 BGM
        private string _currentBgm;           // 当前曲目的逻辑名
        private bool _pendingStop;            // 正在"淡出后停止"

        public override void OnInit()
        {
            base.OnInit();

            // 幂等：重复初始化会再建一池 AudioSource，之前正在播的引用就找不回来了
            if (_inited)
            {
                Debug.LogWarning("[Audio] OnInit 被重复调用，已忽略");
                return;
            }
            _inited = true;

            GameObject root = new GameObject("AudioRoot");
            // 挂在 Launcher 下（它已 DontDestroyOnLoad），跨场景不会被销毁
            if (Launcher.Instance != null)
            {
                root.transform.SetParent(Launcher.Instance.transform, false);
            }
            // 【只在完全没有 Listener 时才加】场景相机通常自带一个；
            // 无脑再加一个会让 Unity 持续报 "There are 2 audio listeners in the scene"，
            // 这种刷屏警告会掩盖真正的错误。
            if (Object.FindObjectOfType<AudioListener>() == null)
            {
                root.AddComponent<AudioListener>();
            }

            // ① 音效池
            _sources = new AudioSource[SourcePoolSize];
            for (int i = 0; i < SourcePoolSize; i++)
            {
                AudioSource src = root.AddComponent<AudioSource>();
                src.playOnAwake = false;
                src.loop = false;
                src.spatialBlend = 0f;
                _sources[i] = src;
            }

            // ② BGM 池（固定 2 槽，交叉淡化用）
            _bgmSources = new AudioSource[AudioFadeDriver.Slots];
            for (int i = 0; i < _bgmSources.Length; i++)
            {
                AudioSource src = root.AddComponent<AudioSource>();
                src.playOnAwake = false;
                src.loop = true;
                src.spatialBlend = 0f;
                src.volume = 0f;
                _bgmSources[i] = src;
            }

            // ③ 淡化驱动：只保存 0~1 系数，绝对音量统一由本类算（单一写入方）
            _fadeDriver = root.AddComponent<AudioFadeDriver>();
            _fadeDriver.Changed += ApplyBgmVolume;
            _fadeDriver.Finished += OnBgmFadeFinished;
        }

        public override void OnDestroy()
        {
            base.OnDestroy();

            if (_fadeDriver != null)
            {
                _fadeDriver.Changed -= ApplyBgmVolume;
                _fadeDriver.Finished -= OnBgmFadeFinished;
                _fadeDriver = null;
            }
            if (_bgmSources != null)
            {
                for (int i = 0; i < _bgmSources.Length; i++)
                {
                    if (_bgmSources[i] != null)
                    {
                        _bgmSources[i].Stop();
                        _bgmSources[i] = null;
                    }
                }
                _bgmSources = null;
            }
            _bgmActive = -1;
            _currentBgm = null;

            if (_sources != null)
            {
                for (int i = 0; i < _sources.Length; i++)
                {
                    if (_sources[i] != null)
                    {
                        _sources[i].Stop();
                        _sources[i] = null;
                    }
                }
            }
            _inited = false;
        }

        // ------------------------------------------------------------------
        // 对外接口 · 音效
        // ------------------------------------------------------------------

        /// <summary>播放一个 2D 全局音效（UI、提示类）</summary>
        public void Play(string logicalName)
        {
            PlayInternal(logicalName, Vector3.zero, false);
        }

        /// <summary>在指定世界坐标播放一个音效（战斗类）</summary>
        public void PlayAt(string logicalName, Vector3 worldPos)
        {
            PlayInternal(logicalName, worldPos, true);
        }

        // ------------------------------------------------------------------
        // 对外接口 · BGM
        // ------------------------------------------------------------------

        /// <summary>当前正在播放的 BGM 逻辑名；没有则 null。</summary>
        public string CurrentBgm { get { return _currentBgm; } }

        /// <summary>
        /// 播放背景乐（循环）。
        /// 【幂等】同一首正在播则直接返回，不会"重头再放一遍" ——
        ///   否则每次重开选关界面音乐都会跳回开头，听感很糟。
        /// 【换曲】用交叉淡化：新曲 0→1 的同时旧曲 1→0，中途不会有静音空档。
        /// </summary>
        public void PlayBgm(string logicalName)
        {
            PlayBgm(logicalName, BgmCrossFadeSec);
        }

        /// <summary>播放背景乐，可指定淡化时长（0 = 立即切换）。</summary>
        public void PlayBgm(string logicalName, float fadeSeconds)
        {
            if (string.IsNullOrEmpty(logicalName) || !_inited || _bgmSources == null || _fadeDriver == null)
            {
                return;
            }

            // 幂等：同一首且确实还在播 → 什么都不做
            if (_currentBgm == logicalName && _bgmActive >= 0 &&
                _bgmSources[_bgmActive] != null && _bgmSources[_bgmActive].isPlaying)
            {
                return;
            }

            AudioConfig cfg = Configs.GetAudio(logicalName);
            if (cfg == null)
            {
                WarnOnce(logicalName, "TBAudio 表中没有这一行");
                return;
            }

            AudioClip clip = ResLoader.Instance.Load<AudioClip>("Audio_" + logicalName);
            if (clip == null)
            {
                WarnOnce(logicalName, "找不到音频资源（把文件放进 Assets/Audio/ 并重跑 gen_audio_catalog.py）");
                return;
            }

            // 取"另一槽"承载新曲：_bgmActive 为 -1 时用 0 号槽
            int next = (_bgmActive < 0) ? 0 : (1 - _bgmActive);
            AudioSource src = _bgmSources[next];
            if (src == null)
            {
                return;
            }

            src.clip = clip;
            src.loop = true;
            src.pitch = cfg.Pitch;
            src.spatialBlend = 0f;
            _bgmBase[next] = cfg.Volume;
            _currentBgm = logicalName;
            _pendingStop = false;

            // 新曲从 0 起步，避免以上一次的残留音量"闪一下"
            _fadeDriver.Prime(next, 0f);
            src.Play();

            _bgmActive = next;
            float target0 = (next == 0) ? 1f : 0f;
            float target1 = (next == 1) ? 1f : 0f;
            _fadeDriver.Begin(target0, target1, fadeSeconds);
            ApplyBgmVolume();   // 立即应用一次，避免零时长时依赖事件时序
        }

        /// <summary>淡出并停止当前 BGM（默认 0.8 秒）。</summary>
        public void StopBgm()
        {
            StopBgm(BgmCrossFadeSec);
        }

        /// <summary>淡出并停止当前 BGM，可指定淡化时长（0 = 立即停止）。</summary>
        public void StopBgm(float fadeSeconds)
        {
            if (!_inited || _fadeDriver == null || _bgmActive < 0)
            {
                _currentBgm = null;
                _bgmActive = -1;
                return;
            }
            _pendingStop = true;
            _fadeDriver.Begin(0f, 0f, fadeSeconds);
        }

        // ------------------------------------------------------------------
        // 音量 / 静音
        // ------------------------------------------------------------------

        private bool _muted;

        /// <summary>
        /// 静音开关（由设置界面写入）。
        /// 【为什么可以把 BGM 音量直接压成 0 而不是停止播放】停止/重播会有明显断点；
        ///   压成 0 后再次取消静音是"无缝恢复"，体验更好。
        /// </summary>
        public bool Muted
        {
            get { return _muted; }
            set
            {
                if (_muted == value)
                {
                    return;
                }
                _muted = value;
                ApplyBgmVolume();   // BGM 是长音，必须立刻生效
            }
        }

        private float _masterVolume = 1f;

        /// <summary>
        /// 主音量 0~1（由设置界面写入）。
        /// 【为什么乘在每条音效自己的 volume 上，而不是去改 AudioListener.volume】
        /// 改全局 Listener 音量会连带影响以后可能加入的其它音频来源；
        /// 乘在这里则"每条音效的相对轻重"保持不变，符合玩家的直觉。
        /// </summary>
        public float MasterVolume
        {
            get { return _masterVolume; }
            set
            {
                _masterVolume = value;
                ApplyBgmVolume();   // BGM 立即跟随；音效是短音，下次播放时自然带上新值
            }
        }

        /// <summary>
        /// 重算两条 BGM 源的实际音量。
        /// 实际音量 = 该曲基准音量 × 淡化系数 × 主音量 × (静音 ? 0 : 1)。
        /// **本方法是 BGM 音量的唯一写入方** —— 淡化驱动只改系数、从不直接写 volume，
        /// 这样"设置里调音量"和"正在进行的淡化"不会互相覆盖。
        /// </summary>
        private void ApplyBgmVolume()
        {
            if (_bgmSources == null || _fadeDriver == null)
            {
                return;
            }
            float master = _muted ? 0f : Mathf.Clamp01(_masterVolume);
            for (int i = 0; i < _bgmSources.Length; i++)
            {
                AudioSource src = _bgmSources[i];
                if (src == null)
                {
                    continue;
                }
                float scale = _fadeDriver.Scale(i);
                src.volume = _bgmBase[i] * scale * master;
            }
        }

        /// <summary>一次淡化结束时收拾残局：停旧槽或完成"淡出停止"。</summary>
        private void OnBgmFadeFinished()
        {
            if (_bgmSources == null)
            {
                return;
            }

            if (_pendingStop)
            {
                _pendingStop = false;
                for (int i = 0; i < _bgmSources.Length; i++)
                {
                    StopSlot(i);
                }
                _bgmActive = -1;
                _currentBgm = null;
                ApplyBgmVolume();
                return;
            }

            // 交叉淡化结束：把非当前槽（旧曲）停掉并清引用，释放它的资源
            for (int i = 0; i < _bgmSources.Length; i++)
            {
                if (i == _bgmActive)
                {
                    continue;
                }
                StopSlot(i);
            }
        }

        private void StopSlot(int index)
        {
            if (_bgmSources == null || index < 0 || index >= _bgmSources.Length)
            {
                return;
            }
            AudioSource src = _bgmSources[index];
            if (src != null)
            {
                src.Stop();
                src.clip = null;
            }
            _bgmBase[index] = 0f;
        }

        // ------------------------------------------------------------------
        // 内部 · 音效
        // ------------------------------------------------------------------

        private void PlayInternal(string logicalName, Vector3 worldPos, bool atPosition)
        {
            if (Muted || string.IsNullOrEmpty(logicalName) || !_inited)
            {
                return;
            }

            // ① 配置
            AudioConfig cfg = Configs.GetAudio(logicalName);
            if (cfg == null)
            {
                WarnOnce(logicalName, "TBAudio 表中没有这一行");
                return;
            }

            // ② 资源（AudioCatalog 生成 → ResTable 登记）
            AudioClip clip = ResLoader.Instance.Load<AudioClip>("Audio_" + logicalName);
            if (clip == null)
            {
                WarnOnce(logicalName, "找不到音频资源（把文件放进 Assets/Audio/ 并重跑 gen_audio_catalog.py）");
                return;
            }

            // ③ 播放
            AudioSource src = TakeSource();
            if (src == null)
            {
                return;
            }
            src.clip = clip;
            src.volume = cfg.Volume * (_muted ? 0f : Mathf.Clamp01(_masterVolume));
            src.pitch = cfg.Pitch;
            src.loop = cfg.Loop;
            src.spatialBlend = cfg.Is3d ? 1f : 0f;
            if (atPosition)
            {
                src.transform.position = new Vector3(worldPos.x, worldPos.y, 0f);
            }
            src.Play();
        }

        /// <summary>优先取"空闲"的源；都在播就轮转顶掉最旧的一个。</summary>
        private AudioSource TakeSource()
        {
            if (_sources == null || _sources.Length == 0)
            {
                return null;
            }
            for (int i = 0; i < _sources.Length; i++)
            {
                int idx = (_next + i) % _sources.Length;
                if (_sources[idx] != null && !_sources[idx].isPlaying)
                {
                    _next = (idx + 1) % _sources.Length;
                    return _sources[idx];
                }
            }
            AudioSource fallback = _sources[_next];
            _next = (_next + 1) % _sources.Length;
            return fallback;
        }

        private void WarnOnce(string logicalName, string reason)
        {
            if (_warned.Contains(logicalName))
            {
                return;
            }
            _warned.Add(logicalName);
            if (_warnCount >= MaxWarnings)
            {
                return;
            }
            _warnCount++;
            Debug.LogWarning(string.Format(
                "[Audio] 「{0}」{1} —— 已跳过（不影响玩法）。\n" +
                "  补齐方式：把音频文件放进 Assets/Audio/ 并执行 .workbuddy/tools/gen_audio_catalog.py，" +
                "无需改动任何代码。", logicalName, reason));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 管理器单例基类。
    ///
    /// 【访问约定】**只能通过 `XxxManager.Instance` 访问，绝不要 `new`。**
    ///
    /// 为什么要把这条写进注释并加运行时检测：`Instance` 是**懒创建**的，
    /// 一旦某处 `new` 了一个管理器，就会同时存在两份实例 ——
    /// 一份被注册进主循环（被 tick），另一份承载数据（被各处写入）。
    /// 症状极具迷惑性：**没有报错，逻辑就是不生效**。
    /// 本项目真实踩过：`Launcher` 用 `new` 创建管理器，于是
    /// "怪物生成了但不会移动、也不计入存活数、回合空转完成"。
    ///
    /// 所以下面的构造函数会统计创建次数，出现第二份就报 Error。
    /// </summary>
    public class BaseManager<T> : IManagerInterface where T : class, new()
    {
        /// <summary>
        /// 标记"当前正在由 Instance 的 getter 构造单例"。
        /// 唯一的合法构造路径就是 getter，所以构造时这个标记必须是 true。
        /// </summary>
        private static bool s_creatingSingleton;

        /// <summary>单例是否已创建（仅用于日志措辞，不影响逻辑）</summary>
        private static bool s_singletonCreated;

        public BaseManager()
        {
            if (s_creatingSingleton)
            {
                s_singletonCreated = true;
                return;
            }

            // 走到这里说明有人直接 `new` 了一个管理器。
            // 这是**真问题**：随后 .Instance 还会再建一个，两份实例分别承担
            // "被 tick" 与 "承载数据"，逻辑会静默失效且不报错。
            Debug.LogError(string.Format(
                "[Manager] 检测到直接 new {0}()。\n" +
                "  管理器必须统一通过 {0}.Instance 访问 —— 出现两份实例会导致" +
                "「一处写数据、另一处被 tick」的静默故障（例如怪物生成了却不移动）。\n" +
                "  请把 `new {0}()` 改成 `{0}.Instance`。",
                typeof(T).Name));
        }

        public virtual void OnInit()
        {
            //Debug.LogError("##################");
        }

        public virtual void OnDestroy()
        {

        }

        private static T instance;
        public static T Instance
        {
            get
            {
                if (instance == null)
                {
                    s_creatingSingleton = true;
                    try
                    {
                        instance = new T();
                    }
                    finally
                    {
                        s_creatingSingleton = false;
                    }
                }

                return instance;
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace FTProject
