using System.Text;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 性能探针（M5-3）：滚动统计帧时间，随时打印一份可读报告。
    ///
    /// 【它解决什么问题】设计文档 M5 要求"低端机 200 怪 + 50 塔稳定 60fps"，
    /// 而那必须真机跑。但没有度量就没法判断"够不够快" ——
    /// 本探针把"手感"变成数字（p50 / p95 / p99 / 最差帧 / GC 增量），
    /// 于是压测只需要：真机跑一局 → 按 F3 → 把日志贴出来。
    ///
    /// 【为什么用环形缓冲而不是 List】每帧 Add 会持续分配；
    /// 固定数组 + 覆盖写是零分配的，也不会有"跑久了内存越来越大"的问题。
    ///
    /// 【为什么用 unscaledDeltaTime】暂停时 timeScale=0，用 scaled 时间会得到一堆 0 帧，
    /// 把统计彻底污染（而那恰好是玩家最可能按 F3 的时刻之一）。
    ///
    /// 快捷键：F3 打印报告（由 GameFlowManager 绑定）
    /// </summary>
    public class PerfProbe : MonoBehaviour
    {
        public static PerfProbe Instance { get; private set; }

        /// <summary>采样窗口：600 帧 ≈ 60fps 下的 10 秒</summary>
        private const int Capacity = 600;

        /// <summary>自动打印间隔（秒）。0 = 只在按 F3 时打印。</summary>
        public float autoReportIntervalSec = 0f;

        private readonly float[] _frameMs = new float[Capacity];
        private readonly float[] _scratch = new float[Capacity];
        private int _idx;
        private int _count;
        private float _autoTimer;
        private long _lastGcBytes;
        private long _gcDelta;
        private float _worstSinceReport;

        public static PerfProbe Ensure()
        {
            if (Instance != null)
            {
                return Instance;
            }
            GameObject go = new GameObject("PerfProbe");
            if (Launcher.Instance != null)
            {
                go.transform.SetParent(Launcher.Instance.transform, false);
            }
            return go.AddComponent<PerfProbe>();
        }

        private void Awake()
        {
            Instance = this;
            _lastGcBytes = System.GC.GetTotalMemory(false);
        }

        private void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        private void Update()
        {
            float ms = Time.unscaledDeltaTime * 1000f;
            _frameMs[_idx] = ms;
            _idx = (_idx + 1) % Capacity;
            if (_count < Capacity)
            {
                _count++;
            }
            if (ms > _worstSinceReport)
            {
                _worstSinceReport = ms;
            }

            if (autoReportIntervalSec > 0f)
            {
                _autoTimer += Time.unscaledDeltaTime;
                if (_autoTimer >= autoReportIntervalSec)
                {
                    _autoTimer = 0f;
                    Debug.Log(Report());
                }
            }
        }

        /// <summary>生成一份报告。排序用的是复用数组，调用本身不产生垃圾。</summary>
        public string Report()
        {
            if (_count == 0)
            {
                return "[Perf] 还没有采到帧";
            }

            System.Array.Copy(_frameMs, _scratch, _count);
            System.Array.Sort(_scratch, 0, _count);

            float p50 = _scratch[Mathf.Clamp(Mathf.RoundToInt(_count * 0.50f) - 1, 0, _count - 1)];
            float p95 = _scratch[Mathf.Clamp(Mathf.RoundToInt(_count * 0.95f) - 1, 0, _count - 1)];
            float p99 = _scratch[Mathf.Clamp(Mathf.RoundToInt(_count * 0.99f) - 1, 0, _count - 1)];
            float worst = _scratch[_count - 1];

            float sum = 0f;
            for (int i = 0; i < _count; i++)
            {
                sum += _scratch[i];
            }
            float avg = sum / _count;

            long now = System.GC.GetTotalMemory(false);
            _gcDelta = now - _lastGcBytes;
            _lastGcBytes = now;

            CombatSystem cs = CombatSystem.Instance;
            StringBuilder sb = new StringBuilder(320);
            sb.Append("[Perf] 采样 ").Append(_count).Append(" 帧");
            sb.Append("\n  平均 ").Append(avg.ToString("F2")).Append(" ms（").Append((1000f / Mathf.Max(0.01f, avg)).ToString("F1")).Append(" fps）");
            sb.Append("\n  p50 ").Append(p50.ToString("F2")).Append(" / p95 ").Append(p95.ToString("F2"))
              .Append(" / p99 ").Append(p99.ToString("F2")).Append(" / 最差 ").Append(worst.ToString("F2")).Append(" ms");
            sb.Append("\n  本轮最差 ").Append(_worstSinceReport.ToString("F2")).Append(" ms");
            sb.Append("\n  托管堆增量 ").Append((_gcDelta / 1024f).ToString("F0")).Append(" KB");
            if (cs != null)
            {
                sb.Append("\n  战斗：怪 ").Append(cs.EnemyCount).Append("（存活 ").Append(cs.AliveEnemyCount)
                  .Append("） 塔 ").Append(cs.TowerCount).Append(" 弹 ").Append(cs.BulletCount);
                sb.Append("\n  自检：索敌 ").Append(cs.StatSearchCount).Append(" 开火 ").Append(cs.StatFireCount)
                  .Append(" 命中 ").Append(cs.StatHitCount).Append(" 空放 ").Append(cs.StatIdleFireAttempt)
                  .Append("（空放必须为 0）");
            }
            sb.Append("\n  判定：p95 ≤ 16.7ms 才算稳 60fps；托管堆增量接近 0 才算无泄漏式分配");

            _worstSinceReport = 0f;
            return sb.ToString();
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 玩家数据（金币 / 生命 / 统计）。
    ///
    /// 【规则】所有金币变更**必须**走 TrySpend / AddGold，禁止直接改字段，
    /// 以保证事件与 UI 始终一致。
    ///
    /// 相对 v1.0 的补齐：
    ///   - v1.0 只有显示文本，建塔不扣费、击杀无奖励 → 经济循环不存在
    ///   - v1.0 漏怪直接回收不扣血、无失败判定 → 玩家永不失败
    /// </summary>
    public class PlayerDataManager : BaseManager<PlayerDataManager>
    {
        public int Gold { get; private set; }
        public int Hp { get; private set; }
        public int MaxHp { get; private set; }
        public int TotalKilled { get; private set; }
        public int TotalLeaked { get; private set; }
        public int CurrentLevelId { get; private set; }
        public bool IsGameOver { get; private set; }

        public override void OnInit()
        {
            base.OnInit();
            Gold = 0;
            Hp = 0;
            MaxHp = 0;
            IsGameOver = false;
        }

        /// <summary>按关卡配置初始化经济与生命</summary>
        public void InitFromLevel(LevelConfig level)
        {
            if (level == null)
            {
                Gold = 100;
                Hp = 10;
            }
            else
            {
                Gold = level.InitialGold;
                Hp = level.InitialHp;
                CurrentLevelId = level.Id;
            }
            MaxHp = Hp;
            TotalKilled = 0;
            TotalLeaked = 0;
            IsGameOver = false;

            EventDispatcher.TriggerEvent<int, int>(EventName.GoldChangeEvent, Gold, Gold);
            EventDispatcher.TriggerEvent<int, int>(EventName.PlayerHpChangeEvent, Hp, Hp);
            EventDispatcher.TriggerEvent(EventName.PlayerStateInitEvent);

            Debug.Log(string.Format("[Player] 关卡初始化：金币 {0}，生命 {1}", Gold, Hp));
        }

        /// <summary>
        /// 从局内快照恢复（M3-5）。
        /// 【为什么不复用 InitFromLevel】那个方法会把金币/生命重置成关卡初始值并清空统计，
        /// 而恢复的场景恰恰相反 —— 要**保留**玩家打到一半的状态。
        /// </summary>
        public void RestoreState(int levelId, int gold, int hp, int maxHp, int killed = 0, int leaked = 0)
        {
            CurrentLevelId = levelId;
            Gold = Mathf.Max(0, gold);
            MaxHp = Mathf.Max(1, maxHp);
            Hp = Mathf.Clamp(hp, 0, MaxHp);
            IsGameOver = false;
            TotalKilled = killed;
            TotalLeaked = leaked;

            EventDispatcher.TriggerEvent<int, int>(EventName.GoldChangeEvent, Gold, 0);
            EventDispatcher.TriggerEvent<int, int>(EventName.PlayerHpChangeEvent, Hp, 0);
            EventDispatcher.TriggerEvent(EventName.PlayerStateInitEvent);

            Debug.Log(string.Format("[Player] 从快照恢复：金币 {0}，生命 {1}/{2}", Gold, Hp, MaxHp));
        }

        /// <summary>
        /// 只读检查余额是否够（不扣除）。
        /// 塔放置预览需要每帧判断能否建造，用这个而不是 TrySpend —— 后者会产生副作用。
        /// </summary>
        public bool TryPeek(int amount)
        {
            return amount <= 0 || Gold >= amount;
        }

        /// <summary>尝试消费；余额不足返回 false 且不扣除</summary>
        public bool TrySpend(int amount)
        {
            if (amount <= 0)
            {
                return true;
            }
            if (Gold < amount)
            {
                return false;
            }
            Gold -= amount;
            EventDispatcher.TriggerEvent<int, int>(EventName.GoldChangeEvent, Gold, -amount);
            return true;
        }

        public void AddGold(int amount)
        {
            if (amount <= 0)
            {
                return;
            }
            Gold += amount;
            EventDispatcher.TriggerEvent<int, int>(EventName.GoldChangeEvent, Gold, amount);
        }

        /// <summary>击杀敌人（由 BaseEnemy.Die 调用，奖励已在外部结算）</summary>
        public void OnEnemyKilled()
        {
            TotalKilled++;
        }

        /// <summary>漏怪扣血；归零则判定失败</summary>
        public void LoseHp(int amount)
        {
            if (amount <= 0 || IsGameOver)
            {
                return;
            }
            Hp = Mathf.Max(0, Hp - amount);
            TotalLeaked++;
            EventDispatcher.TriggerEvent<int, int>(EventName.PlayerHpChangeEvent, Hp, -amount);

            if (Hp <= 0)
            {
                IsGameOver = true;
                Debug.Log("[Player] 生命归零，判定失败");
                if (AudioManager.Instance != null)
                {
                    AudioManager.Instance.Play(AudioName.Defeat);
                }
                EventDispatcher.TriggerEvent<bool>(EventName.GameOverEvent, false);
            }
        }

        /// <summary>通关（由回合流程调用）</summary>
        public void Win()
        {
            if (IsGameOver)
            {
                return;
            }
            IsGameOver = true;
            Debug.Log("[Player] 全部回合完成，判定胜利");
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.Play(AudioName.Victory);
            }
            EventDispatcher.TriggerEvent<bool>(EventName.GameOverEvent, true);
        }

        public string DumpDebugInfo()
        {
            return string.Format("[Player] 金币={0} 生命={1}/{2} 击杀={3} 漏怪={4} 结束={5}",
                Gold, Hp, MaxHp, TotalKilled, TotalLeaked, IsGameOver);
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 存档管理器（业务门面）：关卡解锁与星级、玩家设置、局内快照、通用键值。
    ///
    /// ==================================================================
    /// 【本次改造：从"自己写 JSON"变成"委托给数据层"】
    ///   改造前：本类自己拼 JsonUtility + File.WriteAllText，存储格式与业务逻辑是同一块代码。
    ///   改造后：本类只表达业务意图（"这一关通了，记 2 星"），
    ///           落库、加密、事务、资源释放全部下沉到 <see cref="ISaveStorage"/> 实现里。
    ///
    ///   **对外的公开成员一字未改** —— SelectView / SettingView / GameFlowManager
    ///   等调用方不需要任何改动，这是"替换现有逻辑但保证数据流转正常"的关键：
    ///   接口稳定，实现替换。
    ///
    /// 【为什么内存里还留一份 SaveData】
    ///   星级、总星数这类查询在 UI 上会被频繁读取（每次刷新关卡列表都读一遍）。
    ///   保留内存副本后这些读取是纯内存操作；写入时**同时**更新内存与存储（写穿透），
    ///   两边不会不一致 —— 因为它俩的唯一写入口就是本类的这几个 Set/Record 方法。
    ///
    /// 【失败时的行为：一律当作"没有存档"，绝不抛异常】
    ///   存档损坏、目录只读、磁盘满 —— 这些都不该让玩家连游戏都进不去。
    ///   所有存储调用在数据层内部已做了异常收敛，本类只在最后兜一层。
    ///
    /// 【硬约束：与编辑器 API 完全解耦】
    ///   本类及其依赖的数据层都不得引用 UnityEditor —— 否则打包必炸
    ///   （本项目历史上踩过 `JsonDataManager` 顶层 using UnityEditor 的坑）。
    /// ==================================================================
    /// </summary>
    public class SaveManager : BaseManager<SaveManager>
    {
        private ISaveStorage _storage;
        private SaveData _data;
        private bool _loaded;
        public const int MaxStars = LevelRatingEvaluator.MaxStars;
        public static bool IsTestStorage { get { return !string.IsNullOrEmpty(SaveStorageFactory.ActiveTestContextId); } }
        private sealed class StorageScope : IDisposable
        {
            private readonly SaveManager owner;
            private readonly string previous;
            private bool disposed;
            public StorageScope(SaveManager manager, string prior) { owner = manager; previous = prior; }
            public void Dispose() { if (disposed) return; disposed = true; owner.SwitchStorage(previous); }
        }
        public IDisposable SetTestStorageContext(string contextId)
        {
            if (string.IsNullOrEmpty(contextId)) throw new ArgumentException("A test storage identity is required");
            string previous = SaveStorageFactory.TestContextId;
            SwitchStorage(contextId);
            return new StorageScope(this, previous);
        }
        private void SwitchStorage(string contextId)
        {
            if (_storage != null) { _storage.Flush(); _storage.Dispose(); }
            SaveStorageFactory.TestContextId = contextId; _storage = null; _data = null; _loaded = false;
            EnsureLoaded();
        }

        // ------------------------------------------------------------------
        // 只读信息（自检 / 日志 / 排查用）
        // ------------------------------------------------------------------

        /// <summary>当前后端标识，例如 "SQLite 3.50.2" / "JSON 文件（SQLite 回退）"</summary>
        public string BackendName
        {
            get { EnsureLoaded(); return _storage != null ? _storage.BackendName : "未初始化"; }
        }

        /// <summary>存档落盘位置</summary>
        public string StorageLocation
        {
            get { EnsureLoaded(); return _storage != null ? _storage.Location : null; }
        }

        /// <summary>敏感字段是否真的在加密</summary>
        public bool EncryptionEnabled
        {
            get { EnsureLoaded(); return _storage != null && _storage.IsEncrypted; }
        }

        /// <summary>
        /// 存档文件完整路径（兼容旧调用点；排查问题时打印它最快）。
        /// 注意：实际位置以后端为准，用 <see cref="StorageLocation"/> 更准确。
        /// </summary>
        public static string FilePath
        {
            get { return SaveStorageFactory.DatabasePath; }
        }

        public SaveData Data
        {
            get
            {
                EnsureLoaded();
                return _data;
            }
        }

        // ------------------------------------------------------------------
        // 生命周期
        // ------------------------------------------------------------------

        public override void OnInit()
        {
            base.OnInit();
            EnsureLoaded();
        }

        public override void OnDestroy()
        {
            base.OnDestroy();
            if (_storage != null)
            {
                try
                {
                    _storage.Flush();
                    _storage.Dispose();
                }
                catch (Exception ex)
                {
                    Debug.LogWarning("[Save] 关闭存储时出错（可忽略）：" + ex.Message);
                }
            }
        }

        /// <summary>懒初始化：即使有人没等 Launcher 就访问存档，也能正常拿到数据。</summary>
        private void EnsureLoaded()
        {
            if (_loaded)
            {
                return;
            }
            _loaded = true;
            _data = new SaveData();
            _storage = null;

            try
            {
                _storage = SaveStorageFactory.Create();

                _data.settings = _storage.LoadSettings() ?? new GameSettings();
                _data.levels = _storage.LoadLevels() ?? new List<LevelProgress>();
                _data.snapshot = _storage.LoadSnapshot() ?? new LevelSnapshot();
                if (_data.settings == null) _data.settings = new GameSettings();
                if (_data.levels == null) _data.levels = new List<LevelProgress>();
                if (_data.snapshot == null) _data.snapshot = new LevelSnapshot();
                if (_data.snapshot.towers == null) _data.snapshot.towers = new List<TowerSnapshot>();
                _data.settings.Clamp();
            }
            catch (Exception ex)
            {
                // 连存储都建不起来时，用一个内存存档把游戏跑起来（本局有效、退出即失）。
                Debug.LogError("[Save] 存档存储初始化失败，本次运行将使用内存存档（不会落盘）：" + ex.Message);
                _data = new SaveData();
            }
        }

        // ------------------------------------------------------------------
        // 读 / 写（存储层）
        // ------------------------------------------------------------------

        /// <summary>
        /// 把内存里的存档整体写盘。
        /// 【什么时候需要它】正常改设置/记成绩都会即时写穿透，一般不需要手工调用；
        /// 保留它是为了给"批量改了很多字段后一次性提交"留一个明确入口（例如调试命令）。
        /// </summary>
        public void Save()
        {
            EnsureLoaded();
            if (_storage == null)
            {
                return;
            }
            try
            {
                _storage.SaveSettings(_data.settings);
                for (int i = 0; i < _data.levels.Count; i++)
                {
                    _storage.SaveLevel(_data.levels[i]);
                }
                _storage.SaveSnapshot(_data.snapshot);
                _storage.Flush();
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[Save] 写档失败：" + ex.Message);
            }
        }

        /// <summary>清空存档（设置界面用）。表结构/后端实例保留，只清业务数据。</summary>
        public void ResetAll()
        {
            EnsureLoaded();
            _data = new SaveData();
            _loaded = true;
            if (_storage == null)
            {
                return;
            }
            try
            {
                _storage.ResetAll();
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[Save] 重置存档失败：" + ex.Message);
            }
        }

        /// <summary>把缓冲区刷到磁盘（切后台 / 退出前调用）。</summary>
        public void Flush()
        {
            EnsureLoaded();
            if (_storage == null)
            {
                return;
            }
            try
            {
                _storage.Flush();
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[Save] 刷盘失败（可忽略）：" + ex.Message);
            }
        }

        /// <summary>单关写穿透：把内存中的某关进度落库。</summary>
        private void PersistLevel(int levelId)
        {
            if (_storage == null)
            {
                return;
            }
            LevelProgress p = _data.Find(levelId);
            if (p != null)
            {
                _storage.SaveLevel(p);
            }
        }

        private void PersistSettings()
        {
            if (_storage != null)
            {
                _storage.SaveSettings(_data.settings);
            }
        }

        private void PersistSnapshot()
        {
            if (_storage != null)
            {
                _storage.SaveSnapshot(_data.snapshot);
            }
        }

        // ------------------------------------------------------------------
        // 关卡解锁与星级
        // ------------------------------------------------------------------

#if UNITY_EDITOR
        /// <summary>
        /// 编辑器内是否**无视破关进度、全部关卡直接可进**。
        ///
        /// 【为什么需要】调新地图时不该为了看第 15 关先把中间每一关挨个通关；
        ///   选关界面 / 关卡详情页 / 「下一关」都只看 IsUnlocked，所以一处开关就够。
        ///
        /// 【为什么不影响真机】整段包在 #if UNITY_EDITOR 里，玩家构建连这个字段都不存在，
        ///   真机仍然走下面"前一关通关才解锁下一关"的正常逻辑。
        /// 想在编辑器里验证锁定态（比如检查锁图标）时，把它改成 false 即可。
        /// 【为什么不用 const】const true 会让编译器把后面的正常逻辑判成"不可达代码"并报 CS0162，
        ///   static readonly 不参与常量折叠，编译干净。
        /// </summary>
        private static readonly bool UnlockAllLevelsInEditor = true;
        private static bool _testProductionUnlockRules;
        private sealed class UnlockRuleScope : IDisposable
        {
            private readonly bool previous;
            public UnlockRuleScope(bool prior) { previous = prior; }
            public void Dispose() { _testProductionUnlockRules = previous; }
        }
        /// <summary>Exercise the actual player unlock path against isolated test storage only.</summary>
        public IDisposable UseProductionUnlockRulesForTest()
        {
            if (!IsTestStorage) throw new InvalidOperationException("Unlock tests require isolated storage");
            bool prior = _testProductionUnlockRules;
            _testProductionUnlockRules = true;
            return new UnlockRuleScope(prior);
        }
#endif

        /// <summary>
        /// 关卡是否已解锁。
        /// 【规则】第 1 关永远开放；其余关卡需要**前一关至少通关一次**。
        /// 用"关卡 id 排序后的前一个"而不是 id-1，这样以后中间插关卡也不会把解锁链弄断。
        /// 【编辑器例外】见 UnlockAllLevelsInEditor：仅编辑器内全解锁，真机不受影响。
        /// </summary>
        public bool IsUnlocked(int levelId)
        {
#if UNITY_EDITOR
            if (UnlockAllLevelsInEditor && !_testProductionUnlockRules)
            {
                return true;
            }
#endif
            EnsureLoaded();
            int prev = PreviousLevelId(levelId);
            if (prev <= 0)
            {
                return true;   // 第一关
            }
            LevelProgress p = _data.Find(prev);
            return p != null && p.Cleared;
        }

        /// <summary>取"排序上紧邻的前一关"的 id；没有则返回 0。</summary>
        private int PreviousLevelId(int levelId)
        {
            if (Configs.LevelTable == null || Configs.LevelTable.DataList == null)
            {
                return levelId <= 1 ? 0 : levelId - 1;
            }
            int best = 0;
            for (int i = 0; i < Configs.LevelTable.DataList.Count; i++)
            {
                cfg.SceneInfo s = Configs.LevelTable.DataList[i];
                if (s != null && s.Id < levelId && s.Id > best)
                {
                    best = s.Id;
                }
            }
            return best;
        }

        public int GetStars(int levelId)
        {
            EnsureLoaded();
            EnsureRatingVersion(levelId);
            LevelProgress p = _data.Find(levelId);
            return IsCurrentRating(p, levelId) ? p.stars : 0;
        }

        /// <summary>
        /// 历史**最快**通关用时（游戏内毫秒）。0 = 尚无记录（未通关 / 老存档）。
        /// 【展示约定】调用方把 0 显示成 `--:--`，不要显示 `00:00` ——
        /// "没有记录"和"0 秒通关"必须一眼分得开。
        /// </summary>
        public int GetBestTimeMs(int levelId)
        {
            EnsureLoaded();
            EnsureRatingVersion(levelId);
            LevelProgress p = _data.Find(levelId);
            return IsCurrentRating(p, levelId) ? p.bestTimeMs : 0;
        }

        /// <summary>历史最好成绩（剩余生命），仅用于展示。0 = 无记录。</summary>
        public int GetBestHpLeft(int levelId)
        {
            EnsureLoaded();
            EnsureRatingVersion(levelId);
            LevelProgress p = _data.Find(levelId);
            return IsCurrentRating(p, levelId) ? p.bestHpLeft : 0;
        }
        private static bool IsCurrentRating(LevelProgress progress, int levelId)
        {
            var profile = Configs.GetLevelRating(levelId);
            return progress != null && Configs.RatingContentVerified && profile != null && profile.IsValid && progress.ratingVersionKey == profile.versionKey;
        }
        public int GetBestCombatTimeMs(int levelId) { EnsureLoaded(); EnsureRatingVersion(levelId); var p = _data.Find(levelId); return IsCurrentRating(p, levelId) ? p.bestCombatTimeMs : 0; }
        public int GetLegacyStars(int levelId)
        {
            EnsureLoaded(); EnsureRatingVersion(levelId); var p = _data.Find(levelId); int result = 0;
            if (p != null && !IsCurrentRating(p, levelId)) result = p.stars;
            if (p != null && p.legacy != null) foreach (var old in p.legacy) result = Math.Max(result, old.stars);
            return result;
        }
        public bool IsCurrentVersionRated(int levelId) { return GetStars(levelId) > 0; }
        public bool IsRunCommitted(int levelId, string runId)
        {
            EnsureLoaded(); var p = _data.Find(levelId);
            return p != null && p.committedRunIds != null && p.committedRunIds.Contains(runId);
        }
        /// <summary>Back up first, then archive and change the current content identity. Re-entry is idempotent.</summary>
        public void EnsureRatingVersion(int levelId)
        {
            EnsureLoaded();
            LevelRatingProfile profile = Configs.GetLevelRating(levelId);
            if (!Configs.RatingContentVerified || profile == null || !profile.IsValid) return;
            LevelProgress p = _data.Find(levelId);
            if (p == null || p.ratingVersionKey == profile.versionKey) return;
            if (_storage == null) return;
            string oldKey = string.IsNullOrEmpty(p.ratingVersionKey) ? "legacy-v1-three-stars" : p.ratingVersionKey;
            string backupKey = "rating-backup/" + levelId + "/" + oldKey;
            string backup;
            string originalJson = JsonUtility.ToJson(p);
            if (_storage != null)
            {
                if (!_storage.TryGetValue(backupKey, out backup)) { _storage.SetValue(backupKey, originalJson, true); _storage.Flush(); }
                if (!_storage.TryGetValue(backupKey, out backup) || string.IsNullOrEmpty(backup)) { Debug.LogWarning("[Save] Rating migration deferred: legacy backup could not be persisted"); return; }
            }
            var candidate = JsonUtility.FromJson<LevelProgress>(originalJson);
            SaveProgressMigration.ArchiveForVersion(candidate, profile.versionKey);
            if (_storage != null && !_storage.CommitClear(candidate)) { Debug.LogWarning("[Save] Rating migration deferred: archive could not be persisted"); return; }
            _data.levels[_data.levels.IndexOf(p)] = candidate;
            _data.snapshot = new LevelSnapshot();
            if (_storage != null) { _storage.SetValue("rating-migrated/" + levelId, profile.versionKey, true); _storage.Flush(); }
        }
        public bool RecordClear(int levelId, LevelRatingResult result)
        {
            EnsureLoaded();
            if (_storage == null || result == null || !result.valid || !result.victory || result.stars <= 0 || result.metrics == null || result.metrics.debugOverride) return false;
            var current = Configs.GetLevelRating(levelId);
            if (current == null || current.versionKey != result.versionKey) return false;
            result = LevelRatingEvaluator.Evaluate(current, result.metrics);
            if (!result.valid || !result.victory || result.stars <= 0) return false;
            EnsureRatingVersion(levelId);
            var existing = _data.Find(levelId);
            if (existing != null && existing.ratingVersionKey != current.versionKey) return false;
            LevelProgress original = existing ?? new LevelProgress { levelId = levelId, ratingVersionKey = current.versionKey };
            if (IsRunCommitted(levelId, result.metrics.runId)) return true;
            LevelProgress p = JsonUtility.FromJson<LevelProgress>(JsonUtility.ToJson(original));
            if (p.committedRunIds == null) p.committedRunIds = new List<string>();
            p.ratingVersionKey = result.versionKey;
            if (result.stars > p.stars) { p.stars = Mathf.Clamp(result.stars, 0, MaxStars); p.bestRating = result; }
            p.bestHpLeft = Math.Max(p.bestHpLeft, result.metrics.hp);
            int levelMs = (int)Math.Min(int.MaxValue, result.metrics.levelElapsedMs), combatMs = (int)Math.Min(int.MaxValue, result.metrics.combatElapsedMs);
            if (p.bestTimeMs <= 0 || levelMs < p.bestTimeMs) p.bestTimeMs = levelMs;
            if (p.bestCombatTimeMs <= 0 || combatMs < p.bestCombatTimeMs) p.bestCombatTimeMs = combatMs;
            p.clearCount++; p.committedRunIds.Add(result.metrics.runId);
            int index = _data.levels.IndexOf(original);
            if (_storage != null && !_storage.CommitClear(p)) return false;
            if (index < 0) _data.levels.Add(p); else _data.levels[index] = p;
            _data.snapshot = new LevelSnapshot();
            if (_storage != null) _storage.Flush();
            return true;
        }

        /// <summary>把毫秒格式化成 `m:ss` 或 `--:--`（无记录）。UI 与日志共用一处口径。</summary>
        public static string FormatTime(int timeMs)
        {
            if (timeMs <= 0)
            {
                return "--:--";
            }
            int totalSec = timeMs / 1000;
            return string.Format("{0}:{1:00}", totalSec / 60, totalSec % 60);
        }

        /// <summary>已通关的关卡数（关卡选择界面顶部汇总用）</summary>
        public int ClearedCount
        {
            get
            {
                EnsureLoaded();
                int n = 0;
                for (int i = 0; i < _data.levels.Count; i++)
                {
                    if (_data.levels[i] != null && _data.levels[i].Cleared)
                    {
                        n++;
                    }
                }
                return n;
            }
        }

        /// <summary>累计星数（用于"12/24 星"这类展示）</summary>
        public int TotalStars
        {
            get
            {
                EnsureLoaded();
                int n = 0;
                for (int i = 0; i < _data.levels.Count; i++)
                {
                    if (_data.levels[i] != null)
                    {
                        n += GetStars(_data.levels[i].levelId);
                    }
                }
                return n;
            }
        }

        // ------------------------------------------------------------------
        // 设置
        // ------------------------------------------------------------------

        public GameSettings Settings
        {
            get
            {
                EnsureLoaded();
                return _data.settings;
            }
        }

        public void SetVolume(float v)
        {
            EnsureLoaded();
            _data.settings.volume = Mathf.Clamp01(v);
            ApplyToAudio();
            PersistSettings();
            if (_storage != null) _storage.Flush();
        }

        public void SetMuted(bool muted)
        {
            EnsureLoaded();
            _data.settings.muted = muted;
            ApplyToAudio();
            PersistSettings();
            if (_storage != null) _storage.Flush();
        }

        /// <summary>
        /// 读玩家显式选择的语言。从未选择过返回 false（此时应回退到配置里的默认语言）。
        /// </summary>
        public bool TryGetLanguage(out Language lang)
        {
            EnsureLoaded();
            string code = _data.settings != null ? _data.settings.language : null;
            if (string.IsNullOrEmpty(code))
            {
                lang = Language.English;
                return false;
            }
            lang = LanguageUtil.FromCode(code);
            return true;
        }

        /// <summary>写玩家选择的语言并落盘。</summary>
        public void SetLanguage(Language lang)
        {
            EnsureLoaded();
            _data.settings.language = lang.ToCode();
            PersistSettings();
            if (_storage != null) _storage.Flush();
        }

        /// <summary>把设置推给音频系统。AudioManager 可能还没初始化，所以判空。</summary>
        public void ApplyToAudio()
        {
            EnsureLoaded();
            AudioManager am = AudioManager.Instance;
            if (am == null)
            {
                return;
            }
            am.Muted = _data.settings.muted;
            am.MasterVolume = _data.settings.volume;
        }

        // ------------------------------------------------------------------
        // 局内快照
        // ------------------------------------------------------------------

        public bool HasSnapshot
        {
            get
            {
                EnsureLoaded();
                return _data.snapshot != null && _data.snapshot.valid;
            }
        }

        public LevelSnapshot Snapshot
        {
            get
            {
                EnsureLoaded();
                return _data.snapshot;
            }
        }

        /// <summary>写入局内快照并立刻落盘（回合结束时由 GameFlowManager 调用）。</summary>
        public void SetSnapshot(LevelSnapshot snap)
        {
            TrySetSnapshot(snap);
        }

        /// <summary>Publish a checkpoint only after storage confirms the complete write.</summary>
        public bool TrySetSnapshot(LevelSnapshot snap)
        {
            EnsureLoaded();
            if (_storage == null) return false;
            var candidate = snap != null ? JsonUtility.FromJson<LevelSnapshot>(JsonUtility.ToJson(snap)) : new LevelSnapshot();
            try
            {
                _storage.SaveSnapshot(candidate);
                _storage.Flush();
                if (!string.IsNullOrEmpty(_storage.LastError)) return false;
                LevelSnapshot persisted = _storage.LoadSnapshot();
                if (!string.IsNullOrEmpty(_storage.LastError) || persisted == null || JsonUtility.ToJson(persisted) != JsonUtility.ToJson(candidate)) return false;
                _data.snapshot = persisted;
                return true;
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[Save] Checkpoint was not published: " + ex.Message);
                return false;
            }
        }

        /// <summary>Keep the previous resumable boundary if durable invalidation fails.</summary>
        public bool TryClearSnapshot()
        {
            return TrySetSnapshot(new LevelSnapshot());
        }

        /// <summary>开始新一局时作废快照。</summary>
        public void ClearSnapshot(bool save)
        {
            EnsureLoaded();
            if (save) TryClearSnapshot();
            else _data.snapshot = new LevelSnapshot();
        }

        // ------------------------------------------------------------------
        // 通用键值（给其它模块存取零散本地数据用）
        // ------------------------------------------------------------------

        /// <summary>
        /// 读一个自定义键值。不存在返回 false。
        /// 【用途】设置项、新手引导进度、上次选择等"不值得单独建表"的数据。
        /// </summary>
        public bool TryGetUserValue(string key, out string value)
        {
            EnsureLoaded();
            value = null;
            if (_storage == null)
            {
                return false;
            }
            return _storage.TryGetValue(key, out value);
        }

        /// <summary>
        /// 写一个自定义键值。<paramref name="sensitive"/>=true 时该值会加密后落库。
        /// 【怎么选】凡是"改了能占便宜"或"属于用户隐私"的内容（货币、昵称、内购凭证）
        ///   一律传 true；纯粹的界面偏好（音量以外的开关、窗口位置）可以传 false，
        ///   这样在"密钥不可用"的降级场景下这些偏好仍然可读。
        /// </summary>
        public void SetUserValue(string key, string value, bool sensitive)
        {
            EnsureLoaded();
            if (_storage == null || string.IsNullOrEmpty(key))
            {
                return;
            }
            _storage.SetValue(key, value, sensitive);
            _storage.Flush();
        }

        public void DeleteUserValue(string key)
        {
            EnsureLoaded();
            if (_storage == null || string.IsNullOrEmpty(key))
            {
                return;
            }
            _storage.DeleteValue(key);
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 通用对象池。
    ///
    /// 设计要点：
    ///   1. 用「生产工厂 + 归还清理」委托把池与具体业务解耦
    ///   2. 归还时执行 reset 委托，解决"池化对象带着上次状态复用"这一经典 Bug
    ///   3. 不依赖 GameObject.SetActive 的实现细节，隐藏方式由业务决定
    ///
    /// 用法：
    ///   var pool = new ObjectPool&lt;BaseEnemy&gt;(
    ///       create: () =&gt; { ... return enemy; },
    ///       reset:  e  =&gt; e.OnRecycle(),   // 必须清空目标/计时/位置等状态
    ///       maxSize: 64);
    ///   var e = pool.Get();
    ///   pool.Release(e);
    /// </summary>
    public class ObjectPool<T> where T : class
    {
        private readonly Func<T> _create;
        private readonly Action<T> _reset;
        private readonly int _maxSize;
        private readonly Stack<T> _idle;

        /// <summary>池内空闲数量</summary>
        public int IdleCount { get { return _idle.Count; } }

        /// <summary>历史创建总数（含已销毁，用于诊断）</summary>
        public int CreatedTotal { get; private set; }

        public ObjectPool(Func<T> create, Action<T> reset = null, int maxSize = 128, int prewarm = 0)
        {
            if (create == null)
            {
                throw new ArgumentNullException("create");
            }
            _create = create;
            _reset = reset;
            _maxSize = maxSize > 0 ? maxSize : 128;
            _idle = new Stack<T>(64);

            for (int i = 0; i < prewarm; i++)
            {
                T item = _create();
                CreatedTotal++;
                if (item != null)
                {
                    _idle.Push(item);
                }
            }
        }

        /// <summary>取一个对象；池空则新建</summary>
        public T Get()
        {
            while (_idle.Count > 0)
            {
                T item = _idle.Pop();
                if (item != null)
                {
                    return item;
                }
            }
            CreatedTotal++;
            return _create();
        }

        /// <summary>归还一个对象；超出上限则丢弃（由调用方销毁或交给 GC）</summary>
        public void Release(T item)
        {
            if (item == null)
            {
                return;
            }
            if (_reset != null)
            {
                _reset(item);
            }
            if (_idle.Count < _maxSize)
            {
                _idle.Push(item);
            }
        }

        /// <summary>清空池（切关卡时调用）；onDiscard 用于销毁被丢弃的对象</summary>
        public void Clear(Action<T> onDiscard = null)
        {
            while (_idle.Count > 0)
            {
                T item = _idle.Pop();
                if (item != null && onDiscard != null)
                {
                    onDiscard(item);
                }
            }
        }

        public string DumpDebugInfo()
        {
            return string.Format("ObjectPool<{0}>: idle={1}, created={2}, max={3}",
                typeof(T).Name, _idle.Count, CreatedTotal, _maxSize);
        }
    }
}

using System;
using System.Collections;
using UnityEngine;
using FTProject.AOT;

namespace FTProject
{
    public static class BootHotUpdateGate
    {
        public static bool Completed { get; private set; }
        private static bool _running;
        public static void Run(Action onComplete)
        {
            if (_running) throw new InvalidOperationException("Resource gate already running");
            if (Completed) { onComplete?.Invoke(); return; }
            _running = true;
            ResLoaderRunner.Start(RunCo(onComplete));
        }
        private static IEnumerator RunCo(Action onComplete)
        {
            try
            {
                while (true)
                {
                    bool done = false, retry = false;
                    string error = null;
                    int count = 0, total = 0;
                    long bytes = 0, totalBytes = 0;
                    var hot = ResLoader.HotUpdate;
                    if (hot == null) { error = "No resource update/verification provider"; }
                    else hot.StartCheckUpdate(
                        phase => BootUpdateSession.Report(BootReleaseStore.Offline ? "Offline" : "Resources", .45f, -1),
                        (cur, all) => { count = cur; total = all; BootUpdateSession.Progress(count, total, bytes, totalBytes); },
                        (cur, all) => { bytes = cur; totalBytes = all; BootUpdateSession.Progress(count, total, bytes, totalBytes); },
                        reason => error = reason,
                        updated => done = true);
                    while (!done && error == null)
                    {
                        BootUpdateSession.Controls(hot.IsDownloading && !hot.IsPaused ? (Action)(() => { hot.PauseDownload(); BootUpdateSession.Paused = true; }) : null,
                            hot.IsDownloading && hot.IsPaused ? (Action)(() => { hot.ResumeDownload(); BootUpdateSession.Paused = false; }) : null);
                        yield return null;
                    }
                    BootUpdateSession.Controls(); BootUpdateSession.Paused = false;
                    if (done)
                    {
                        try
                        {
                            if (!LanguageManager.PrepareStartup()) throw new Exception("Current localization table or settings missing");
                            if (ResLoader.Instance.Load<GameObject>("LoadingView") == null
                                || ResLoader.Instance.Load<GameObject>("SplashView") == null)
                                throw new Exception("Startup views missing from the pinned resource release");
                            Completed = true;
                        }
                        catch (Exception e) { error = e.Message; }
                        if (Completed)
                        {
                            BootUpdateSession.Report("Ready", 1f, 1f);
                            Debug.Log("[BootSequence] ResourcesVerified");
                            onComplete?.Invoke();
                            yield break;
                        }
                    }
                    Debug.LogWarning("[Boot] Resource verification failed: " + error);
                    BootUpdateSession.Report("Failed", .45f, -1, error);
                    BootUpdateSession.Controls(retry: () => retry = true);
                    while (!retry) yield return null;
                    BootUpdateSession.Controls();
                    BootReleaseStore.RetryPinnedOnline();
                    // The descriptor stays pinned after DLL load. Retry only this resource version.
                }
            }
            finally { _running = false; BootUpdateSession.Controls(); }
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.SceneManagement;

namespace FTProject
{
    /// <summary>
    /// AssetBundle 真机加载实现（P0-3）。
    ///
    /// 职责：
    ///   1. 启动时加载主清单（AssetBundleManifest），之后所有依赖查询由它回答
    ///   2. 按「包」为单位做引用计数 —— 粒度是关卡，不是单个资源
    ///      （单个资源频繁 ±1 会让 Unload 时机极难把握，是 AB 项目的经典坑）
    ///   3. 依赖自动补齐：加载 A 包前先把它的依赖全部加载
    ///   4. 常驻包（ResBundle.Persistent）永不卸载
    ///
    /// 【为什么不用 Assets/Resources】AB 支持热更、支持按需下载、启动快，
    /// 且能精确控制卸载时机；Resources 目录会被全量打进包体且无法增量更新。
    ///
    /// 【为什么编辑器下默认不用它】改一张图都要重新打 AB，开发效率不可接受。
    /// 编辑器走 EditorResLoader（AssetDatabase 直读），
    /// 需要验证真 AB 链路时在 Scripting Define Symbols 加 FORCE_AB。
    /// </summary>
    public class BundleResLoader : IResLoader, IHotUpdateLoader
    {
        // ---- 包运行时状态 ----
        private readonly Dictionary<string, AssetBundle> _loaded = new Dictionary<string, AssetBundle>(32);
        /// <summary>包的"关卡引用"计数。只有 Preload 会 +1，ReleaseBundle 会 -1。</summary>
        private readonly Dictionary<string, int> _refCount = new Dictionary<string, int>(32);
        /// <summary>正在加载中的包（并发合并：同一包被多次请求只加载一次）</summary>
        private readonly HashSet<string> _loading = new HashSet<string>();

        // ---- 资源缓存 ----
        private readonly Dictionary<string, UnityEngine.Object> _assetCache =
            new Dictionary<string, UnityEngine.Object>(128);

        private AssetBundle _manifestBundle;
        private AssetBundleManifest _manifest;
        private bool _ready;

        /// <summary>异步加载失败时回调此事件（供 UI 提示）</summary>
        public static event Action<string> OnLoadError;

        public bool IsReady { get { return _ready; } }

        // ==================================================================
        // 初始化
        // ==================================================================

        public void Init(Action onDone)
        {
            Init(null, onDone);
        }

        public void Init(Action<float> onProgress, Action onDone)
        {
            if (_ready)
            {
                if (onProgress != null) onProgress(1f);
                if (onDone != null)
                {
                    onDone();
                }
                return;
            }
            if (onProgress != null) onProgress(0f);
            ResLoaderRunner.Start(InitCo(onProgress, onDone));
        }

        private IEnumerator InitCo(Action<float> onProgress, Action onDone)
        {
            // ① 主清单包：包名与平台目录同名
            string manifestName = ResPathUtil.ManifestBundleName;
            yield return LoadBundleInternalCo(manifestName, null);

            _manifestBundle = GetLoaded(manifestName);
            if (_manifestBundle == null)
            {
                Fail(string.Format(
                    "[Res] 主清单加载失败：{0}\n" +
                    "  排查：①是否已执行「Tools ▸ 资源工具 ▸ 打包 AssetBundle」" +
                    "②平台子目录名是否与当前平台一致（当前应为 {1}）",
                    ResPathUtil.BundlePath(manifestName), ResPathUtil.PlatformFolder));
                if (onProgress != null) onProgress(1f);
                if (onDone != null)
                {
                    onDone();
                }
                yield break;
            }

            _manifest = _manifestBundle.LoadAsset<AssetBundleManifest>("AssetBundleManifest");
            if (_manifest == null)
            {
                Fail("[Res] 主清单包内找不到 AssetBundleManifest 资产，包可能已损坏");
                if (onProgress != null) onProgress(1f);
                if (onDone != null)
                {
                    onDone();
                }
                yield break;
            }

            // 主清单就绪 = 走完一半（A2 进度条：0.5 之后是常驻包落地）
            if (onProgress != null) onProgress(0.5f);

            // ② 常驻包（config / core_art）开机即加载
            for (int i = 0; i < ResBundle.Persistent.Length; i++)
            {
                AcquireBundle(ResBundle.Persistent[i]);
            }
            // 等所有正在加载的包落地
            while (_loading.Count > 0)
            {
                yield return null;
            }

            _ready = true;
            Debug.Log(string.Format(
                "[Res] AssetBundle 模式初始化完成。平台={0}，已加载包 {1} 个，常驻包 {2} 个。",
                ResPathUtil.PlatformFolder, _loaded.Count, ResBundle.Persistent.Length));

            if (onProgress != null) onProgress(1f);
            if (onDone != null)
            {
                onDone();
            }
        }

        // ==================================================================
        // 包管理
        // ==================================================================

        /// <summary>
        /// 获取一个包的"关卡引用"：引用计数 +1，并确保包与其全部依赖已加载。
        /// 与 <see cref="ReleaseBundle"/> 严格配对。
        /// </summary>
        public void AcquireBundle(string bundleName)
        {
            if (string.IsNullOrEmpty(bundleName))
            {
                return;
            }
            int c;
            _refCount.TryGetValue(bundleName, out c);
            _refCount[bundleName] = c + 1;

            if (_loaded.ContainsKey(bundleName) || _loading.Contains(bundleName))
            {
                return;
            }
            ResLoaderRunner.Start(LoadBundleWithDepsCo(bundleName));
        }

        /// <summary>加载一个包及其全部依赖（依赖先加载）</summary>
        private IEnumerator LoadBundleWithDepsCo(string bundleName)
        {
            string[] deps = GetDependencies(bundleName);
            for (int i = 0; i < deps.Length; i++)
            {
                // 依赖包也计入引用，避免被提前卸载
                int c;
                _refCount.TryGetValue(deps[i], out c);
                _refCount[deps[i]] = c + 1;

                if (!_loaded.ContainsKey(deps[i]) && !_loading.Contains(deps[i]))
                {
                    yield return LoadBundleInternalCo(deps[i], null);
                }
            }
            yield return LoadBundleInternalCo(bundleName, null);
        }

        private string[] GetDependencies(string bundleName)
        {
            if (_manifest == null)
            {
                return new string[0];
            }
            string[] deps = _manifest.GetAllDependencies(bundleName);
            return deps ?? new string[0];
        }

        private AssetBundle GetLoaded(string bundleName)
        {
            AssetBundle b;
            return _loaded.TryGetValue(bundleName, out b) ? b : null;
        }

        /// <summary>真正加载一个包（不含依赖处理）。同一包并发请求会被合并。</summary>
        private IEnumerator LoadBundleInternalCo(string bundleName, Action<AssetBundle> onDone)
        {
            if (_loaded.ContainsKey(bundleName))
            {
                if (onDone != null)
                {
                    onDone(_loaded[bundleName]);
                }
                yield break;
            }
            if (_loading.Contains(bundleName))
            {
                // 合并并发请求：等别人加载完
                while (_loading.Contains(bundleName))
                {
                    yield return null;
                }
                if (onDone != null)
                {
                    onDone(GetLoaded(bundleName));
                }
                yield break;
            }

            _loading.Add(bundleName);
            AssetBundle bundle = null;

            if (ResPathUtil.NeedWebRequest)
            {
                // Android：StreamingAssets 在 APK 内，必须走 UnityWebRequest
                using (UnityWebRequest req = UnityWebRequestAssetBundle.GetAssetBundle(
                           ResPathUtil.BundleUrl(bundleName)))
                {
                    yield return req.SendWebRequest();
                    if (req.result == UnityWebRequest.Result.Success)
                    {
                        bundle = DownloadHandlerAssetBundle.GetContent(req);
                    }
                    else
                    {
                        Fail(string.Format("[Res] 包「{0}」下载失败：{1}", bundleName, req.error));
                    }
                }
            }
            else
            {
                string path = ResPathUtil.BundlePath(bundleName);
                if (!File.Exists(path))
                {
                    Fail(string.Format(
                        "[Res] 包文件不存在：{0}\n  排查：是否已执行「Tools ▸ 资源工具 ▸ 打包 AssetBundle」",
                        path));
                }
                else
                {
                    AssetBundleCreateRequest req = AssetBundle.LoadFromFileAsync(path);
                    yield return req;
                    bundle = req.assetBundle;
                    if (bundle == null)
                    {
                        Fail(string.Format("[Res] 包「{0}」加载返回 null，文件可能损坏：{1}", bundleName, path));
                    }
                }
            }

            if (bundle != null)
            {
                _loaded[bundleName] = bundle;
            }
            _loading.Remove(bundleName);

            if (onDone != null)
            {
                onDone(bundle);
            }
        }

        /// <summary>
        /// 同步阻塞加载一个包及其依赖。**只应在调用方漏了 Preload 时作为兜底使用**，
        /// 正常流程一律走异步。
        /// </summary>
        private void LoadBundleBlocking(string bundleName)
        {
            if (_loaded.ContainsKey(bundleName))
            {
                return;
            }
            string[] deps = GetDependencies(bundleName);
            for (int i = 0; i < deps.Length; i++)
            {
                LoadSingleBundleBlocking(deps[i]);
            }
            LoadSingleBundleBlocking(bundleName);
        }

        private void LoadSingleBundleBlocking(string bundleName)
        {
            if (_loaded.ContainsKey(bundleName))
            {
                return;
            }
            if (ResPathUtil.NeedWebRequest)
            {
                Fail(string.Format(
                    "[Res] 包「{0}」在本平台只能异步加载（StreamingAssets 位于包内），" +
                    "请改用 LoadAsync/Preload。", bundleName));
                return;
            }
            string path = ResPathUtil.BundlePath(bundleName);
            if (!File.Exists(path))
            {
                Fail(string.Format("[Res] 包文件不存在：{0}", path));
                return;
            }
            AssetBundle bundle = AssetBundle.LoadFromFile(path);
            if (bundle == null)
            {
                Fail(string.Format("[Res] 包「{0}」同步加载失败：{1}", bundleName, path));
                return;
            }
            _loaded[bundleName] = bundle;
        }

        // ==================================================================
        // 加载接口
        // ==================================================================

        public T Load<T>(string logicalName) where T : UnityEngine.Object
        {
            UnityEngine.Object cached;
            if (_assetCache.TryGetValue(logicalName, out cached) && cached != null)
            {
                return cached as T;
            }

            ResAddress addr = ResTable.Get(logicalName);
            if (!addr.IsValid)
            {
                return null;
            }

            AssetBundle bundle = GetLoaded(addr.Bundle);
            if (bundle == null)
            {
                // 同步兜底：调用方漏了 Preload。这里会阻塞主线程，
                // 所以一定要打警告把它暴露出来，而不是静默接受。
                Debug.LogWarning(string.Format(
                    "[Res] 包「{0}」尚未加载，正在同步阻塞加载（应在进关卡前 Preload，否则会掉帧）：{1}",
                    addr.Bundle, logicalName));
                LoadBundleBlocking(addr.Bundle);
                bundle = GetLoaded(addr.Bundle);
            }
            if (bundle == null)
            {
                return null;
            }

            return LoadFromBundle<T>(logicalName, addr, bundle);
        }

        private T LoadFromBundle<T>(string logicalName, ResAddress addr, AssetBundle bundle) where T : UnityEngine.Object
        {
            T asset = bundle.LoadAsset<T>(addr.Asset);
            if (asset == null)
            {
                // 兜底：资产名可能带扩展名，用全量资产表再找一次
                UnityEngine.Object[] all = bundle.LoadAllAssets();
                for (int i = 0; i < all.Length; i++)
                {
                    if (all[i] != null && all[i].name == addr.Asset)
                    {
                        asset = all[i] as T;
                        break;
                    }
                }
            }
            if (asset == null)
            {
                Fail(string.Format(
                    "[Res] 包内找不到资产：包={0} 资产={1}（逻辑名 {2}）\n" +
                    "  排查：ABNameSetter 是否把该资源打进了正确的包、asset 名是否与文件名一致",
                    addr.Bundle, addr.Asset, logicalName));
                return null;
            }
            _assetCache[logicalName] = asset;
            return asset;
        }

        public void LoadAsync<T>(string logicalName, Action<T> onDone) where T : UnityEngine.Object
        {
            ResLoaderRunner.Start(LoadAsyncCo<T>(logicalName, onDone));
        }

        private IEnumerator LoadAsyncCo<T>(string logicalName, Action<T> onDone) where T : UnityEngine.Object
        {
            UnityEngine.Object cached;
            if (_assetCache.TryGetValue(logicalName, out cached) && cached != null)
            {
                yield return null;
                if (onDone != null)
                {
                    onDone(cached as T);
                }
                yield break;
            }

            ResAddress addr = ResTable.Get(logicalName);
            if (!addr.IsValid)
            {
                if (onDone != null)
                {
                    onDone(null);
                }
                yield break;
            }

            AcquireBundle(addr.Bundle);
            while (_loading.Count > 0)
            {
                yield return null;
            }

            AssetBundle bundle = GetLoaded(addr.Bundle);
            T asset = bundle != null ? LoadFromBundle<T>(logicalName, addr, bundle) : null;
            // 与编辑器实现保持一致：至少延迟一帧再回调，避免业务写出依赖同步返回的代码
            yield return null;
            if (onDone != null)
            {
                onDone(asset);
            }
        }

        public GameObject Instantiate(string logicalName, Transform parent = null)
        {
            GameObject prefab = Load<GameObject>(logicalName);
            if (prefab == null)
            {
                return null;
            }
            GameObject go = UnityEngine.Object.Instantiate(prefab);
            go.name = go.name.Replace("(Clone)", string.Empty);
            AttachTo(go, parent);
            return go;
        }

        public void InstantiateAsync(string logicalName, Transform parent, Action<GameObject> onDone)
        {
            LoadAsync<GameObject>(logicalName, prefab =>
            {
                GameObject go = null;
                if (prefab != null)
                {
                    go = UnityEngine.Object.Instantiate(prefab);
                    go.name = go.name.Replace("(Clone)", string.Empty);
                    AttachTo(go, parent);
                }
                if (onDone != null)
                {
                    onDone(go);
                }
            });
        }

        private static void AttachTo(GameObject go, Transform parent)
        {
            if (parent == null)
            {
                return;
            }
            // 【绝不能重置 localScale】预制体根节点的缩放是美术调好的
            //（怪物包是 0.5、塔是 0.8）。重置成 1 会让怪物大 2 倍，
            // 也会让"配置表的 scale=1 表示保持美术原样"这一语义失效。
            go.transform.SetParent(parent, false);
            go.transform.localPosition = Vector3.zero;
            go.transform.localRotation = Quaternion.identity;
        }

        public void ReleaseInstance(string logicalName, GameObject instance)
        {
            if (instance == null)
            {
                return;
            }
            if (Application.isPlaying)
            {
                UnityEngine.Object.Destroy(instance);
            }
            else
            {
                UnityEngine.Object.DestroyImmediate(instance);
            }
        }

        /// <summary>
        /// 释放单个资源的缓存引用（**不卸载包**）。
        /// 包级生命周期由 ReleaseBundle 管理，见接口注释。
        /// </summary>
        public void Release(string logicalName)
        {
            _assetCache.Remove(logicalName);
        }

        /// <summary>
        /// 整包释放：引用计数 -1，归零后 Unload(false)。
        /// 依赖包的引用也一并归还。
        /// </summary>
        public void ReleaseBundle(string bundleName)
        {
            if (string.IsNullOrEmpty(bundleName))
            {
                return;
            }
            if (IsPersistent(bundleName))
            {
                return;   // 常驻包不参与卸载
            }

            ReleaseRef(bundleName);

            string[] deps = GetDependencies(bundleName);
            for (int i = 0; i < deps.Length; i++)
            {
                ReleaseRef(deps[i]);
            }

            // 清理该包下资源的缓存引用（包卸载后这些 Object 必然失效）
            List<string> keys = ResTable.GetKeysByBundle(bundleName);
            for (int i = 0; i < keys.Count; i++)
            {
                _assetCache.Remove(keys[i]);
            }

            Resources.UnloadUnusedAssets();
        }

        private void ReleaseRef(string bundleName)
        {
            int c;
            if (!_refCount.TryGetValue(bundleName, out c))
            {
                return;
            }
            c--;
            if (c > 0)
            {
                _refCount[bundleName] = c;
                return;
            }
            _refCount.Remove(bundleName);

            if (IsPersistent(bundleName))
            {
                return;
            }

            AssetBundle bundle;
            if (_loaded.TryGetValue(bundleName, out bundle))
            {
                _loaded.Remove(bundleName);
                if (bundle != null)
                {
                    // ★ unloadAllLoadedObjects 必须为 false：
                    // 传 true 会把仍在场景中使用的 Texture/Mesh 一起销毁，导致花屏/丢失
                    bundle.Unload(false);
                }
            }
        }

        private static bool IsPersistent(string bundleName)
        {
            for (int i = 0; i < ResBundle.Persistent.Length; i++)
            {
                if (ResBundle.Persistent[i] == bundleName)
                {
                    return true;
                }
            }
            return false;
        }

        public void Preload(string[] logicalNames, Action onDone)
        {
            Preload(logicalNames, null, onDone);
        }

        public void Preload(string[] logicalNames, Action<float> onProgress, Action onDone)
        {
            ResLoaderRunner.Start(PreloadCo(logicalNames, onProgress, onDone));
        }

        private IEnumerator PreloadCo(string[] logicalNames, Action<float> onProgress, Action onDone)
        {
            if (logicalNames != null)
            {
                // 收集涉及的包（去重），逐一取得关卡引用
                HashSet<string> bundles = new HashSet<string>();
                for (int i = 0; i < logicalNames.Length; i++)
                {
                    ResAddress addr = ResTable.Get(logicalNames[i]);
                    if (addr.IsValid)
                    {
                        bundles.Add(addr.Bundle);
                    }
                    else
                    {
                        Fail(string.Format("[Res] 预加载发现未登记的逻辑名：{0}", logicalNames[i]));
                    }
                }
                foreach (string b in bundles)
                {
                    AcquireBundle(b);
                }
                // 包加载阶段占前一半进度
                if (onProgress != null) onProgress(0.5f);
                while (_loading.Count > 0)
                {
                    yield return null;
                }

                // 预热资产（避免首次访问卡顿）
                int ok = 0;
                for (int i = 0; i < logicalNames.Length; i++)
                {
                    string name = logicalNames[i];
                    ResAddress addr;
                    if (!ResTable.TryGet(name, out addr))
                    {
                        if (onProgress != null) onProgress(0.5f + (i + 1) / (float)logicalNames.Length * 0.5f);
                        continue;
                    }
                    AssetBundle bundle = GetLoaded(addr.Bundle);
                    if (bundle != null && bundle.LoadAsset(addr.Asset) != null)
                    {
                        ok++;
                    }
                    if (onProgress != null) onProgress(0.5f + (i + 1) / (float)logicalNames.Length * 0.5f);
                }
                Debug.Log(string.Format("[Res] 预加载完成：{0}/{1} 个资源就绪。", ok, logicalNames.Length));
            }

            if (onProgress != null) onProgress(1f);
            if (onDone != null)
            {
                onDone();
            }
        }

        // ==================================================================
        // 热更新（IHotUpdateLoader）
        // ==================================================================
        // 纯 AssetBundle 链路是"整包资源随游戏一起发"的模型，**没有远端版本比对与差异下载**。
        // 如实判定为"无需更新"：不假装有一个假的下载进度（那会在真机上变成骗人的假进度条）。
        // 需要热更新时请启用 USE_YOOASSET（见 YooAssetResLoader）。

        public void StartCheckUpdate(
            Action<string> onPhase,
            Action<int, int> onProgress,
            Action<long, long> onBytes,
            Action<string> onError,
            Action<bool> onDone)
        {
            Debug.Log("[Res] BundleResLoader 无热更新能力（整包资源），跳过资源更新检查。");
            if (onPhase != null) onPhase("当前模式：无需更新资源");
            ResLoaderRunner.NextFrame(() =>
            {
                if (onDone != null) onDone(false);
            });
        }

        public void PauseDownload()
        {
            // 无下载可暂停
        }

        public void ResumeDownload()
        {
            // 无下载可继续
        }

        public bool IsDownloading { get { return false; } }

        public bool IsPaused { get { return false; } }

        /// <summary>整包 AB 没有资源版本概念（IHotUpdateLoader 实现），恒 null。</summary>
        public string CurrentResourceVersion { get { return null; } }

        private void Fail(string message)
        {
            Debug.LogError(message);
            if (OnLoadError != null)
            {
                OnLoadError(message);
            }
        }

        // ==================================================================
        // 诊断
        // ==================================================================

        /// <summary>
        /// 旧 AB 链路（未启用 YooAsset 时）的场景加载。
        /// ⚠️ 本实现按场景名走 SceneManager —— 要求场景在 Build Settings 里；
        /// HybridCLR 真机上"包体场景挂热更脚本"会 missing，正式热更链路请用
        /// YooAssetResLoader（场景从 AB 加载）。本实现只是让接口在旧链路下编译通过、
        /// 并保持"无热更组件的场景"可用。
        /// </summary>
        public void LoadSceneAsync(string location, Action<bool, string> onResult)
        {
            AsyncOperation op = SceneManager.LoadSceneAsync(location, LoadSceneMode.Single);
            if (op == null)
            {
                Debug.LogError(string.Format("[Res] BundleResLoader 场景加载失败：{0}", location));
                if (onResult != null) onResult(false, "场景加载失败：" + location);
                return;
            }

            ResLoaderRunner.Start(WaitSceneOpCo(location, op, onResult));
        }

        private static IEnumerator WaitSceneOpCo(string location, AsyncOperation op, Action<bool, string> onResult)
        {
            while (!op.isDone)
            {
                yield return null;
            }

            if (onResult != null) onResult(true, null);
        }

        public string DumpDebugInfo()
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.AppendLine(string.Format("[Res] BundleResLoader：已加载 {0} 个包，缓存 {1} 个资源",
                _loaded.Count, _assetCache.Count));
            foreach (KeyValuePair<string, AssetBundle> kv in _loaded)
            {
                int c;
                _refCount.TryGetValue(kv.Key, out c);
                sb.AppendLine(string.Format("  · {0,-18} ref={1}{2}",
                    kv.Key, c, IsPersistent(kv.Key) ? "（常驻）" : string.Empty));
            }
            return sb.ToString();
        }

        /// <summary>引用计数是否全部归零（除常驻包外）—— 泄漏自检用</summary>
        public bool HasLeak()
        {
            foreach (KeyValuePair<string, int> kv in _refCount)
            {
                if (kv.Value > 0 && !IsPersistent(kv.Key))
                {
                    return true;
                }
            }
            return false;
        }
    }
}

#if UNITY_EDITOR
using System;
using System.Collections;
using System.Text;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEditor;

namespace FTProject
{
    /// <summary>
    /// 编辑器专用资源加载实现：直接用 AssetDatabase 读工程内资源。
    ///
    /// 为什么需要它：如果开发期也走真 AB，改一张图都要重新打一次包，
    /// 开发效率会崩。这是业界通行的"编辑器模拟模式"。
    ///
    /// 【时序约定】LoadAsync 也延迟一帧回调，与 BundleResLoader 行为一致。
    /// </summary>
    public class EditorResLoader : IResLoader, IHotUpdateLoader
    {
        private bool _ready;

        public bool IsReady
        {
            get { return _ready; }
        }

        public void Init(Action onDone)
        {
            Init(null, onDone);
        }

        public void Init(Action<float> onProgress, Action onDone)
        {
            // 编辑器直读模式没有任何"打包清单/依赖"要加载，初始化是**瞬时**的 ——
            // 如实回报 0 → 1，而不是编造一段假进度（假进度在真机上会露出马脚）。
            if (onProgress != null)
            {
                onProgress(0f);
            }
            _ready = true;
            Debug.Log("[Res] 使用编辑器直读模式（EditorResLoader）。如需验证真 AB 链路，" +
                      "请在 Player Settings 的 Scripting Define Symbols 中加入 FORCE_AB。");
            if (onProgress != null)
            {
                onProgress(1f);
            }
            ResLoaderRunner.NextFrame(onDone);
        }

        // ------------------------------------------------------------------
        // 加载
        // ------------------------------------------------------------------

        public T Load<T>(string logicalName) where T : UnityEngine.Object
        {
            ResAddress addr = ResTable.Get(logicalName);
            if (!addr.IsValid)
            {
                return null;
            }

            T asset = AssetDatabase.LoadAssetAtPath<T>(addr.EditorPath);
            if (asset == null)
            {
                LogLoadFailure<T>(logicalName, addr);
            }
            return asset;
        }

        public void LoadAsync<T>(string logicalName, Action<T> onDone) where T : UnityEngine.Object
        {
            T asset = Load<T>(logicalName);
            ResLoaderRunner.NextFrame(() =>
            {
                if (onDone != null)
                {
                    onDone(asset);
                }
            });
        }

        public GameObject Instantiate(string logicalName, Transform parent = null)
        {
            GameObject prefab = Load<GameObject>(logicalName);
            if (prefab == null)
            {
                return null;
            }

            GameObject go = UnityEngine.Object.Instantiate(prefab);
            go.name = go.name.Replace("(Clone)", string.Empty);
            AttachTo(go, parent);
            return go;
        }

        public void InstantiateAsync(string logicalName, Transform parent, Action<GameObject> onDone)
        {
            LoadAsync<GameObject>(logicalName, prefab =>
            {
                GameObject go = null;
                if (prefab != null)
                {
                    go = UnityEngine.Object.Instantiate(prefab);
                    go.name = go.name.Replace("(Clone)", string.Empty);
                    AttachTo(go, parent);
                }
                if (onDone != null)
                {
                    onDone(go);
                }
            });
        }

        private static void AttachTo(GameObject go, Transform parent)
        {
            if (parent == null)
            {
                return;
            }
            // 【绝不能重置 localScale】预制体根节点的缩放是美术调好的
            //（怪物包是 0.5、塔是 0.8）。把它重置成 1 会让怪物直接大 2 倍，
            // 而且会让"配置表的 scale=1 表示保持美术原样"这个语义失效。
            // SetParent(parent, false) 本身已保留 local 值，不需要额外归一化。
            go.transform.SetParent(parent, false);
            go.transform.localPosition = Vector3.zero;
            go.transform.localRotation = Quaternion.identity;
        }

        // ------------------------------------------------------------------
        // 生命周期（编辑器直读无包概念，均为空操作）
        // ------------------------------------------------------------------

        public void ReleaseInstance(string logicalName, GameObject instance)
        {
            if (instance == null)
            {
                return;
            }
            if (Application.isPlaying)
            {
                UnityEngine.Object.Destroy(instance);
            }
            else
            {
                UnityEngine.Object.DestroyImmediate(instance);
            }
        }

        public void Release(string logicalName)
        {
            // 编辑器直读模式无引用计数，空操作
        }

        public void ReleaseBundle(string bundleName)
        {
            // 编辑器直读模式无包概念，空操作
        }

        public void Preload(string[] logicalNames, Action onDone)
        {
            Preload(logicalNames, null, onDone);
        }

        public void Preload(string[] logicalNames, Action<float> onProgress, Action onDone)
        {
            if (logicalNames != null)
            {
                StringBuilder missing = new StringBuilder();
                int okCount = 0;
                for (int i = 0; i < logicalNames.Length; i++)
                {
                    string name = logicalNames[i];
                    ResAddress addr = ResTable.Get(name);
                    if (!addr.IsValid)
                    {
                        missing.Append("\n  · 未登记：" + name);
                        if (onProgress != null)
                        {
                            onProgress((i + 1) / (float)logicalNames.Length);
                        }
                        continue;
                    }
                    if (AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(addr.EditorPath) == null)
                    {
                        missing.Append("\n  · 文件不存在：" + name + "  →  " + addr.EditorPath);
                        if (onProgress != null)
                        {
                            onProgress((i + 1) / (float)logicalNames.Length);
                        }
                        continue;
                    }
                    okCount++;
                    if (onProgress != null)
                    {
                        onProgress((i + 1) / (float)logicalNames.Length);
                    }
                }

                if (missing.Length > 0)
                {
                    Debug.LogError(string.Format(
                        "[Res] 预加载自检发现 {0} 个资源不可用（可用 {1} 个）：{2}",
                        logicalNames.Length - okCount, okCount, missing));
                }
                else
                {
                    Debug.Log(string.Format("[Res] 预加载自检通过，共 {0} 个资源全部就绪。", okCount));
                }
            }
            // 空清单/全部跳过时上面循环一次都没回报，这里兜底到 100%（幂等，不违反单调）
            if (onProgress != null)
            {
                onProgress(1f);
            }
            ResLoaderRunner.NextFrame(onDone);
        }

        public string DumpDebugInfo()
        {
            return string.Format("[Res] EditorResLoader：共登记 {0} 条资源地址（编辑器直读，无 AB 加载）。",
                CountKeys());
        }

        // ------------------------------------------------------------------
        // 场景加载（IResLoader.LoadSceneAsync）
        // ------------------------------------------------------------------

        /// <summary>
        /// 编辑器 Play 模式直接按场景名加载（编辑器不受 BuildSettings 限制，
        /// 工程内任意场景都能 LoadScene —— 与真机的 AB 限制不同）。
        /// </summary>
        public void LoadSceneAsync(string location, Action<bool, string> onResult)
        {
            AsyncOperation op = SceneManager.LoadSceneAsync(location, LoadSceneMode.Single);
            if (op == null)
            {
                Debug.LogError(string.Format("[Res] 编辑器场景加载失败：{0}（场景名是否存在？）", location));
                if (onResult != null) onResult(false, "编辑器场景加载失败：" + location);
                return;
            }

            // 保证"至少延迟一帧回调"，与 LoadAsync 的既定约定一致
            ResLoaderRunner.Start(WaitSceneOpCo(location, op, onResult));
        }

        private static IEnumerator WaitSceneOpCo(string location, AsyncOperation op, Action<bool, string> onResult)
        {
            while (!op.isDone)
            {
                yield return null;
            }

            if (onResult != null) onResult(true, null);
        }

        // ------------------------------------------------------------------
        // 热更新（IHotUpdateLoader）—— 编辑器直读没有远端概念
        // ------------------------------------------------------------------

        /// <summary>
        /// 编辑器直读模式没有"远端版本/差异下载"，直接判定为"无需更新"。
        /// 【为什么也要实现】不实现的话 UI 侧必须写 `#if USE_YOOASSET`，
        /// 一旦漏写就是"编辑器能跑、打包编译不过"。
        /// </summary>
        public void StartCheckUpdate(
            Action<string> onPhase,
            Action<int, int> onProgress,
            Action<long, long> onBytes,
            Action<string> onError,
            Action<bool> onDone)
        {
            Debug.Log("[Res] EditorResLoader 无热更新能力（编辑器直读），跳过资源更新检查。");
            if (onPhase != null) onPhase("编辑器模式：无需更新资源");
            ResLoaderRunner.NextFrame(() =>
            {
                if (onDone != null) onDone(false);
            });
        }

        public void PauseDownload()
        {
            // 无下载可暂停
        }

        public void ResumeDownload()
        {
            // 无下载可继续
        }

        public bool IsDownloading { get { return false; } }

        public bool IsPaused { get { return false; } }

        /// <summary>编辑器直读没有资源版本概念（IHotUpdateLoader 实现），恒 null。</summary>
        public string CurrentResourceVersion { get { return null; } }

        // ------------------------------------------------------------------
        // 工具
        // ------------------------------------------------------------------

        private static int CountKeys()
        {
            int n = 0;
            foreach (string unused in ResTable.AllKeys)
            {
                n++;
            }
            return n;
        }

        private static void LogLoadFailure<T>(string logicalName, ResAddress addr) where T : UnityEngine.Object
        {
            string typeName = typeof(T).Name;

            // 对 Sprite 给出更有针对性的排查提示
            if (typeof(T) == typeof(Sprite))
            {
                Texture2D tex = AssetDatabase.LoadAssetAtPath<Texture2D>(addr.EditorPath);
                if (tex != null)
                {
                    Debug.LogError(string.Format(
                        "[Res] 资源「{0}」是图片，但未以 Sprite 形式导入，无法作为 Sprite 加载。\n" +
                        "  路径：{1}\n" +
                        "  修复：选中该图片 → Inspector 顶部 Texture Type 改为「Sprite (2D and UI)」→ Apply",
                        logicalName, addr.EditorPath));
                    return;
                }
            }

            if (typeof(T) == typeof(TextAsset))
            {
                // 踩过的坑：StreamingAssets 下的文件被 Unity 当作"原始文件"处理，
                // 不导入成 TextAsset —— LoadAssetAtPath<Object> 能拿到，<TextAsset> 拿不到。
                bool inStreamingAssets = addr.EditorPath.StartsWith("Assets/StreamingAssets/");
                Debug.LogError(string.Format(
                    "[Res] 文本资源「{0}」加载失败。\n" +
                    "  路径：{1}\n" +
                    "  常见原因：\n" +
                    "   ① 文件扩展名不是 .json/.txt/.bytes，或未被识别为 TextAsset\n" +
                    "   ② {2}\n" +
                    "  修复：确认该路径在普通 Assets 目录下（配置表应为 Assets/ConfigJson/，\n" +
                    "        由 Luban/gen_code_json.bat 导出）",
                    logicalName, addr.EditorPath,
                    inStreamingAssets
                        ? "★该文件在 StreamingAssets 下 —— 这类文件不会被导入成 TextAsset，必须移到普通 Assets 目录"
                        : "文件不存在（先执行对应的生成脚本）"));
                return;
            }

            Debug.LogError(string.Format(
                "[Res] 加载失败：逻辑名「{0}」→ 类型 {1}\n  期望路径：{2}\n" +
                "  排查：①文件是否存在 ②类型是否匹配 ③是否已被移出 Assets 目录",
                logicalName, typeName, addr.EditorPath));
        }
    }
}
