#if USE_YOOASSET
using System.Collections.Generic;
using YooAsset;

namespace FTProject
{
    /// <summary>
    /// YooAsset 远端服务实现：把 YooAsset 要的文件名翻译成真实下载 URL。
    ///
    /// ==================================================================
    /// 【YooAsset 什么时候会调它】
    ///   只在 **HostPlayMode（联机运行模式）** 下才会问远端地址：
    ///     · 请求包裹版本  → 要 `&lt;平台&gt;/&lt;包裹&gt;/&lt;版本&gt;/&lt;包裹&gt;.version`
    ///     · 加载包裹清单  → 要 `.../&lt;包裹&gt;_&lt;版本&gt;.bytes`（清单文件）
    ///     · 下载资源      → 要 `.../&lt;哈希&gt;.bundle`
    ///   离线 / 编辑器模拟模式下**根本不会走到这里**（那是本地文件系统的事）。
    ///
    /// 【为什么返回值是"列表"而不是单个字符串】
    ///   YooAsset 3.0.x 的接口设计成支持**多候选/多 CDN 备份**：
    ///   按优先级依次尝试，前一个失败会自动换下一个。本工程目前只配一个地址，
    ///   但保留了"主地址 + 备用地址"的扩展位，将来加 CDN 备份不用改接口。
    ///
    /// 【YooAsset 给的 fileName 长什么样】
    ///   **已经包含了相对路径**，形如 `Android/FreeTower/1.0.1/FreeTower.version`。
    ///   所以这里只需要做一个简单的"根地址 + / + 相对路径"拼接，
    ///   ★ 千万不要再自己拼平台名 —— 会变成 `.../Android/Android/...` 而 404。
    /// ==================================================================
    /// </summary>
    public class FTRemoteService : IRemoteService
    {
        /// <summary>服务器根地址（构造时固定下来，避免下载中途被改）</summary>
        private readonly string _root;

        public FTRemoteService(string root)
        {
            _root = string.IsNullOrEmpty(root) ? string.Empty : root.TrimEnd('/');
        }

        /// <summary>当前使用的根地址（诊断用）</summary>
        public string Root { get { return _root; } }

        public IReadOnlyList<string> GetRemoteUrls(string fileName)
        {
            var urls = new List<string>(2);

            if (string.IsNullOrEmpty(_root) || string.IsNullOrEmpty(fileName))
            {
                // 返回空列表 = 没有可用地址。YooAsset 会据此报"找不到远端地址"，
                // 这比返回一个错误 URL 更好定位问题（错误 URL 会报 404，看起来像服务器配错了）。
                return urls;
            }

            // 主地址：服务器根 + '/' + 相对路径
            // fileName 在 YooAsset 里用的是 '/' 分隔，不需要做平台相关的路径转换。
            string relative = fileName.TrimStart('/');
            urls.Add(_root + "/" + relative);

            return urls;
        }
    }
}
#endif

using System;

namespace FTProject
{
    /// <summary>
    /// 资源热更新能力（UI 补全 A3 / HotUpdateView 的数据源）。
    ///
    /// ==================================================================
    /// 【为什么单独抽一个接口，而不是直接调 YooAssetResLoader】
    ///   只有 YooAsset 那套实现才真的有"远端版本比对 + 差异下载"。
    ///   编辑器直读 / 纯 AssetBundle 两套没有远端概念，但**也必须实现本接口**，
    ///   否则 UI 侧就得写 `#if USE_YOOASSET`，一处漏写就是"编辑器能跑、打包编译不过"。
    ///   统一口径：没有远端能力时立刻回调 onDone(false)（= 无需更新），界面照常往下走。
    ///
    /// 【为什么是"启动式"而不是返回 IEnumerator】
    ///   本工程运行时协程统一由 ResLoaderRunner 驱动（见 ResLoaderRunner.cs），
    ///   UI 层不应该拿到 IEnumerator（它不知道谁来推进，很容易写出"永远不执行"的协程）。
    ///   所以这里只暴露"启动 + 回调"。
    /// ==================================================================
    /// </summary>
    public interface IHotUpdateLoader
    {
        /// <summary>
        /// 启动一次"检查更新 → 必要时下载"。
        /// <paramref name="onDone"/> 的参数 = **本次是否真的下载过内容**。
        /// 失败只回调 <paramref name="onError"/>（不回调 onDone），由界面决定是否重试。
        /// 所有回调都在主线程、逐帧推进中触发。
        /// </summary>
        void StartCheckUpdate(
            Action<string> onPhase,
            Action<int, int> onProgress,
            Action<long, long> onBytes,
            Action<string> onError,
            Action<bool> onDone);

        /// <summary>暂停下载（无下载进行中时空操作）。</summary>
        void PauseDownload();

        /// <summary>
        /// 当前**已激活**的资源清单版本（供日志与主菜单版本行显示）。
        /// 【各实现的口径】YooAsset 返回激活清单版本（Init 成功后才有值，
        /// 热更完成后 = 远端最新版本）；编辑器直读 / 纯 AB 链路没有版本概念，
        /// 恒返回 null —— 调用方必须容忍 null，显示时自动省略。
        /// </summary>
        string CurrentResourceVersion { get; }

        /// <summary>继续下载（无下载进行中时空操作）。</summary>
        void ResumeDownload();

        /// <summary>是否正在下载。</summary>
        bool IsDownloading { get; }

        /// <summary>是否已暂停。</summary>
        bool IsPaused { get; }
    }
}

using System;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 统一资源加载接口。
    /// 业务代码**只依赖本接口**，不感知底层是 AssetDatabase 还是 AssetBundle。
    ///
    /// 两个实现：
    ///   - EditorResLoader：编辑器下用 AssetDatabase 直读，改完资源即时生效，无需打 AB
    ///   - BundleResLoader：真机/发布用 AssetBundle，含依赖与引用计数
    /// 由 ResLoader.Instance 按编译宏自动选择。
    /// </summary>
    public interface IResLoader
    {
        /// <summary>是否已初始化完成</summary>
        bool IsReady { get; }

        /// <summary>
        /// 初始化（真机实现会加载 AB 总清单；编辑器实现为空操作）。
        /// 完成后回调，之后才能调用其它接口。
        /// </summary>
        void Init(Action onDone);

        /// <summary>
        /// 带进度的初始化（UI 补全 A2：LoadingView 的进度条数据源）。
        /// <paramref name="onProgress"/> 收 0~1 的**归一化**进度，实现方保证**单调不减**；
        /// 允许实现方只在少数几个离散点回报（例如每个包裹一次），界面侧负责补间。
        /// 【为什么不改旧签名】三套实现 + 既有调用方都在用 <see cref="Init(Action)"/>，
        /// 改签名会一次性波及全部；加重载则旧路径零成本保留。
        /// </summary>
        void Init(Action<float> onProgress, Action onDone);

        /// <summary>同步加载单个资源（返回 null 表示加载失败，已打印错误）</summary>
        T Load<T>(string logicalName) where T : UnityEngine.Object;

        /// <summary>
        /// 异步加载单个资源。
        /// 【注意】即使编辑器实现也要保证"至少延迟一帧回调"，
        /// 以免业务代码写出"依赖同步返回"的写法，在真机上才暴露问题。
        /// </summary>
        void LoadAsync<T>(string logicalName, Action<T> onDone) where T : UnityEngine.Object;

        /// <summary>
        /// 实例化预制体（从已加载的 bundle 取资产并实例化）。
        /// 【引用计数约定】本方法**不改变** bundle 引用计数 —— bundle 的生命周期
        /// 由 <see cref="Preload"/> 与 <see cref="ReleaseBundle"/> 按"关卡"粒度管理。
        /// 对象自身的复用请交给游戏侧的对象池，不要与 AB 生命周期混在一起。
        /// 失败返回 null。
        /// </summary>
        GameObject Instantiate(string logicalName, Transform parent = null);

        /// <summary>异步实例化预制体</summary>
        void InstantiateAsync(string logicalName, Transform parent, Action<GameObject> onDone);

        /// <summary>
        /// 销毁一个由 Instantiate 创建、且不参与对象池的实例。
        /// 池化对象请由对象池管理，不要调用本方法。
        /// 【引用计数约定】本方法**不改变** bundle 引用计数。
        /// </summary>
        void ReleaseInstance(string logicalName, GameObject instance);

        /// <summary>
        /// 释放某个逻辑资源在加载器内部的缓存引用。
        /// 一般不需要手动调用（关卡结束用 <see cref="ReleaseBundle"/> 整包释放即可）。
        /// </summary>
        void Release(string logicalName);

        /// <summary>
        /// 整包释放：bundle 引用计数 -1，归零时 Unload(false) + UnloadUnusedAssets。
        /// 切关卡时对不再需要的包调用。**常驻包（ResBundle.Persistent）不会被真正卸载。**
        /// </summary>
        void ReleaseBundle(string bundleName);

        /// <summary>
        /// 预加载一批逻辑资源（进关卡前预热）。
        /// 内部会对涉及的每个 bundle 获取一次"关卡引用"（引用计数 +1），
        /// 与 ReleaseBundle 配对使用。
        /// </summary>
        void Preload(string[] logicalNames, Action onDone);

        /// <summary>
        /// 异步加载场景（Single 模式，加载完成即切换，当前场景自动卸载）。
        /// 【为什么放加载器里】HybridCLR 真机上，**挂了热更脚本的场景必须从 AssetBundle
        /// 加载**（打进 BuildSettings 的场景在打包时热更程序集被剔除，组件会烘焙成
        /// 空壳 → 运行时 "missing script / serialization layout" 错误）。
        /// YooAsset 实现走 SceneHandle（离线模式读随包 bundle，联机模式读沙盒）。
        /// <paramref name="location"/> = 收集器地址（AddressByFileName 规则 = 不带扩展名的文件名）。
        /// onResult(ok, err)：ok=false 时 err 为可读错误。回调在主线程。
        /// </summary>
        void LoadSceneAsync(string location, Action<bool, string> onResult);

        /// <summary>
        /// 带进度的预加载（按"已处理逻辑名个数 / 总数"回报 0~1）。
        /// 与 <see cref="Init(Action, Action)"/> 同理：只加重载，不动旧签名。
        /// </summary>
        void Preload(string[] logicalNames, Action<float> onProgress, Action onDone);

        /// <summary>诊断信息（打印当前已加载的包与引用计数）</summary>
        string DumpDebugInfo();
    }
}

namespace FTProject
{
    /// <summary>
    /// 一条资源地址：逻辑名 → (AB 包名, 包内资产名, 编辑器路径)。
    ///
    /// 【重要】这是资源寻址的**唯一数据源**，三处共用同一份数据：
    ///   1. EditorResLoader（编辑器）用 EditorPath 直读
    ///   2. ABNameSetter（Editor 工具）用 EditorPath 给资源自动打 AssetBundle 标记
    ///   3. BundleResLoader（真机）用 Bundle + Asset 异步加载
    ///
    /// 之所以强调"唯一数据源"：编辑器路径规则与 AB 打标规则一旦分叉，
    /// 就会出现"编辑器能跑、真机丢资源"这种最难排查的问题。
    ///
    /// 【配置表为什么不放 StreamingAssets】见 ResTable 里 config 段的注释 ——
    /// StreamingAssets 下的文件不会被导入成 TextAsset，编辑器读不到内容。
    /// </summary>
    public struct ResAddress
    {
        /// <summary>AssetBundle 名，如 "tower_normal"</summary>
        public string Bundle;

        /// <summary>包内资产名，如 "Tower_Normal0"</summary>
        public string Asset;

        /// <summary>编辑器下的资源路径（相对工程根），如 "Assets/Prefabs/Tower/Normal/Tower_Normal0.prefab"</summary>
        public string EditorPath;

        public ResAddress(string bundle, string asset, string editorPath)
        {
            Bundle = bundle;
            Asset = asset;
            EditorPath = editorPath;
        }

        public bool IsValid
        {
            get { return !string.IsNullOrEmpty(EditorPath); }
        }

        public override string ToString()
        {
            return string.Format("bundle={0}, asset={1}, path={2}", Bundle, Asset, EditorPath);
        }
    }
}

using System.Collections.Generic;

namespace FTProject
{
    /// <summary>
    /// AssetBundle 名常量表。
    ///
    /// 命名规范：全小写下划线，禁止带平台或版本号（由构建脚本按平台分目录）。
    ///
    /// 【怪物分包】怪物按**家族**分包（`enemy_rats` / `enemy_dogs` …），
    /// 包名由 MonsterCatalog 生成代码提供（见 .workbuddy/tools/gen_monster_catalog.py）。
    /// 这样做的意义：119 个怪物若打成一个包，进关卡就要整体加载；
    /// 按家族分包后，只加载**本关波次真正用到的**几个家族，启动与内存都更可控。
    ///
    /// 【为什么 All 是属性而不是常量数组】它要合并"固定包"与"生成的家族包"，
    /// 后者随怪物清单变化，不能在编译期写死。
    /// </summary>
    public static class ResBundle
    {
        /// <summary>配置表 JSON（TextAsset），常驻不卸载</summary>
        public const string Config = "config";

        /// <summary>程序生成的占位美术（格子/箭头/血条/子弹点），常驻不卸载</summary>
        public const string CoreArt = "core_art";

        /// <summary>防御塔：普通（type=1）</summary>
        public const string TowerNormal = "tower_normal";

        /// <summary>防御塔：强力（type=2）</summary>
        public const string TowerPower = "tower_power";

        /// <summary>防御塔：减速（type=3）</summary>
        public const string TowerRetard = "tower_retard";

        /// <summary>子弹</summary>
        public const string BulletNormal = "bullet_normal";

        /// <summary>战斗 HUD 与提示</summary>
        public const string UiHud = "ui_hud";

        /// <summary>
        /// 引导期界面（SplashView / LoadingView / HotUpdateView，资产在 Assets/Resources/BootUI/）。
        ///
        /// 【为什么这些 prefab 也要进 AB】它们挂的 View 脚本在**热更程序集**里，
        /// 真机上 Resources 直接加载必然 "missing script"（HybridCLR 官方：挂热更脚本的
        /// 资源必须 AB 打包）。真机时序下 main 场景加载前 ResLoader.Init 已完成
        /// （见 HotUpdateEntry.EnterMainScene），所以 UIManager.Open 能走 ResTable 正常链路。
        /// Assets/Resources/BootUI 的 Resources 兜底仅剩"编辑器未 Init"一种场景。
        /// </summary>
        public const string BootUi = "boot_ui";

        /// <summary>
        /// Reporter 调试控制台图标（Assets/Reporter/Images，收集器 ReporterData 组）。
        ///
        /// 【为什么单独一个包】Reporter 界面图片由运行时动态装配（见
        /// GameSceneLauncher.EnsureReporter 的说明），走 ResTable Reporter_* 逻辑名，
        /// 与游戏 UI 资源解耦；单独成包便于整包管理与将来按需扩展。
        /// </summary>
        public const string Reporter = "reporter";

        /// <summary>
        /// 字体（TMP 字体资产与描边材质）。
        ///
        /// 【为什么要单独分包】全工程 UI 文本统一用 TextMeshPro，字体资产
        /// （`SiYuanSongTi SDF.asset` + 它的图集贴图 + 描边材质）是**所有 UI prefab 的共享依赖**。
        ///   若不给它单独打包，Unity 会把它**隐式复制进每一个引用了它的包**（ui_hud 等），
        ///   字体图集较大，重复打包既浪费包体又是内存隐患。
        ///   单独成包后，各 UI 包只是"引用"它，运行时加载一次即可。
        /// </summary>
        public const string Font = "font";

        /// <summary>
        /// 音效（M2）。逻辑名 Audio_&lt;文件名&gt;，文件来自 Assets/Audio/。
        /// 【注意】该包只在真的存在音频文件时才进入 All（见下面），
        /// 否则打 AB 时会多出一个空包，自检里也会一直提示"包为空"。
        /// </summary>
        public const string Audio = "audio";

        /// <summary>不随怪物清单变化的固定包</summary>
        public static readonly string[] Fixed =
        {
            Config, CoreArt, Font, TowerNormal, TowerPower, TowerRetard, BulletNormal, UiHud, BootUi, Reporter
        };

        /// <summary>常驻包：初始化后不参与卸载</summary>
        public static readonly string[] Persistent =
        {
            Config, CoreArt, Font, BootUi, Reporter
        };

        private static string[] _all;

        /// <summary>全部包名（固定包 + 生成的怪物家族包）</summary>
        public static string[] All
        {
            get
            {
                if (_all == null)
                {
                    List<string> list = new List<string>(Fixed.Length + MonsterCatalog.Bundles.Length + 1);
                    list.AddRange(Fixed);
                    // 有音频文件才把 audio 包纳入（见 Audio 常量注释）
                    if (AudioCatalog.Count > 0 && !list.Contains(Audio))
                    {
                        list.Add(Audio);
                    }
                    for (int i = 0; i < MonsterCatalog.Bundles.Length; i++)
                    {
                        if (!list.Contains(MonsterCatalog.Bundles[i]))
                        {
                            list.Add(MonsterCatalog.Bundles[i]);
                        }
                    }
                    _all = list.ToArray();
                }
                return _all;
            }
        }

        /// <summary>怪物家族包数量（自检报告用）</summary>
        public static int MonsterBundleCount
        {
            get { return MonsterCatalog.Bundles.Length; }
        }
    }
}

namespace FTProject
{
    /// <summary>
    /// 资源加载统一入口。按编译宏自动选择实现：
    ///   - 定义了 USE_YOOASSET        → YooAssetResLoader（YooAsset 第三方资源系统）
    ///   - 编辑器 且 未定义 FORCE_AB  → EditorResLoader（AssetDatabase 直读，改完即可运行）
    ///   - 编辑器 且 定义了 FORCE_AB  → BundleResLoader（用于验证真 AB 链路）
    ///   - 打包后（Player）          → BundleResLoader
    ///
    /// 用法：ResLoader.Instance.Instantiate("Tower_Normal0", parent)
    ///
    /// 想验证真 AB 链路时，在 Player Settings → Other Settings → Scripting Define Symbols
    /// 里加上 FORCE_AB 即可，无需改代码。
    ///
    /// 想切到 YooAsset 时，在同一个位置加上 USE_YOOASSET（见 YooAssetResLoader.cs）。
    /// 它优先于上面两个分支；去掉宏即完全回到原链路。之所以做成宏而不是直接换实现：
    /// YooAsset 是 UPM 包，拉不下来时**整个工程会编译不过**，加宏才能保证"没装也能构建"。
    /// 注意：YooAssetResLoader 内部也复用 FORCE_AB 来区分"编辑器模拟模式 / 离线模式"，
    /// 所以两个宏同时定义时的语义是「用 YooAsset 且走真资源包」。
    ///
    /// 【注意】协程宿主 ResLoaderRunner 单独放在 ResLoaderRunner.cs ——
    /// 它是 MonoBehaviour，Unity 要求类名与文件名一致。
    /// </summary>
    public static class ResLoader
    {
#if USE_YOOASSET
        private static readonly IResLoader _instance = new YooAssetResLoader();
#elif UNITY_EDITOR && !FORCE_AB
        private static readonly IResLoader _instance = new EditorResLoader();
#else
        private static readonly IResLoader _instance = new BundleResLoader();
#endif

        public static IResLoader Instance
        {
            get { return _instance; }
        }

        /// <summary>
        /// 热更新能力入口（UI 补全 A3）。
        /// 【为什么可能为 null】三套实现都实现了 <see cref="IHotUpdateLoader"/>，
        /// 所以正常情况下不为 null；用 `as` + 判空是为了给"将来新增第四套实现却忘了实现本接口"
        /// 留一条降级通路 —— 界面拿到 null 就当"无需更新"直接往下走，而不是空引用崩溃。
        /// </summary>
        public static IHotUpdateLoader HotUpdate
        {
            get { return _instance as IHotUpdateLoader; }
        }

        /// <summary>当前使用的实现名（日志与 UI 自检用）</summary>
        public static string ImplName
        {
            get { return _instance.GetType().Name; }
        }
    }
}

using System;
using System.Collections;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 协程宿主。用于把异步回调统一延迟到下一帧，
    /// 使编辑器实现与真机实现的时序行为完全一致
    ///（否则容易写出"编辑器同步返回能跑、真机异步就崩"的代码）。
    /// </summary>
    public static class ResLoaderRunner
    {
        private static ResLoaderRunnerBehaviour _host;

        private static ResLoaderRunnerBehaviour Host
        {
            get
            {
                if (_host == null)
                {
                    GameObject go = new GameObject("[ResLoaderRunner]");
                    UnityEngine.Object.DontDestroyOnLoad(go);
                    go.hideFlags = HideFlags.HideAndDontSave;
                    _host = go.AddComponent<ResLoaderRunnerBehaviour>();
                }
                return _host;
            }
        }

        /// <summary>
        /// 延迟到下一帧执行回调。
        /// 编辑模式（未运行）下协程不会推进，退化为立即执行 —— 这是有意为之，
        /// 保证 Editor 工具脚本也能正常拿到结果。
        /// </summary>
        public static void NextFrame(Action action)
        {
            if (action == null)
            {
                return;
            }
            if (!Application.isPlaying)
            {
                action();
                return;
            }
            Host.StartCoroutine(NextFrameCo(action));
        }

        private static IEnumerator NextFrameCo(Action action)
        {
            yield return null;
            action();
        }

        /// <summary>
        /// 在共享宿主上启动一个协程（BundleResLoader 的异步加载用）。
        /// 非运行态返回 null —— 编辑模式的资源加载由 EditorResLoader 承担，
        /// 不会走到这里。
        /// </summary>
        public static Coroutine Start(IEnumerator routine)
        {
            if (routine == null || !Application.isPlaying)
            {
                return null;
            }
            return Host.StartCoroutine(routine);
        }
    }
}

