        /// <summary>
        /// 异步加载场景（Single 模式）。
        /// 【为什么必须在 YooAssetResLoader 里做】HybridCLR 真机上，挂了热更脚本的
        /// 场景只能从 AssetBundle 加载 —— 包体 BuildSettings 场景在打包时热更程序集
        /// 被剔除，组件烘焙成空壳。YooAsset 的 SceneHandle 走"内置/沙盒"文件系统，
        /// 离线模式读随包 bundle，联机模式读下载后的沙盒，两者都覆盖。
        /// </summary>
        public void LoadSceneAsync(string location, Action<bool, string> onResult)
        {
            if (!_ready)
            {
                Fail("[Res] 场景加载失败：资源系统尚未初始化完成（Init 未成功）");
                if (onResult != null) onResult(false, "资源系统未初始化");
                return;
            }

            SceneHandle handle = _package.LoadSceneAsync(location, LoadSceneMode.Single);
            if (handle == null)
            {
                Fail(string.Format("[Res] 场景加载无法启动：{0}", location));
                if (onResult != null) onResult(false, "场景加载无法启动：" + location);
                return;
            }

            ResLoaderRunner.Start(WaitSceneCo(location, handle, onResult));
        }

        private IEnumerator WaitSceneCo(string location, SceneHandle handle, Action<bool, string> onResult)
        {
            yield return handle;

            if (handle.Status != EOperationStatus.Succeeded)
            {
                string err = string.Format("场景「{0}」加载失败：{1}", location, handle.Error);
                Fail("[Res] " + err);
                if (onResult != null) onResult(false, err);
                yield break;
            }

            Debug.Log(string.Format("[Res] 场景「{0}」加载完成", location));
            if (onResult != null) onResult(true, null);
        }

        private IEnumerator PreloadCo(string[] logicalNames, Action<float> onProgress, Action onDone)
        {
            if (logicalNames != null && logicalNames.Length > 0)
            {
                // ① 对涉及的包取"关卡引用"，与 ReleaseBundle 严格配对
                HashSet<string> bundles = new HashSet<string>();
                for (int i = 0; i < logicalNames.Length; i++)
                {
                    ResAddress addr;
                    if (ResTable.TryGet(logicalNames[i], out addr) && addr.IsValid)
                    {
                        bundles.Add(addr.Bundle);
                    }
                    else
                    {
                        Fail(string.Format("[Res] 预加载发现未登记的逻辑名：{0}", logicalNames[i]));
                    }
                }
                foreach (string bundle in bundles)
                {
                    AcquireRef(bundle);
                }

                // ② 逐个预热并汇总失败清单（一次性打印，不逐条刷屏）
                //
                // 【为什么用 UnityEngine.Object 作预热类型】ResTable 不记资源类型，
                // 这里只求"把物理包拉进内存"这个大头成本（后续按具体类型加载时，
                // 包已常驻，只是再建一个 provider，代价很小）。YooAsset 自己的
                // LoadAssetSync(location) 同理，内部用的就是 typeof(UnityEngine.Object)。
                StringBuilder missing = new StringBuilder();
                int okCount = 0;
                for (int i = 0; i < logicalNames.Length; i++)
                {
                    string name = logicalNames[i];
                    ResolveResult result = Resolve(name, typeof(UnityEngine.Object));
                    if (result.Ok == false)
                    {
                        missing.Append("\n  · " + name);
                        if (onProgress != null) onProgress((i + 1) / (float)logicalNames.Length);
                        continue;
                    }
                    if (result.FromCache)
                    {
                        okCount++;
                        if (onProgress != null) onProgress((i + 1) / (float)logicalNames.Length);
                        continue;
                    }

                    string startError;
                    AssetHandle handle = TryLoadAsync(result.Location, typeof(UnityEngine.Object), out startError);
                    if (handle == null)
                    {
                        missing.Append("\n  · " + name + "  →  " + startError);
                        if (onProgress != null) onProgress((i + 1) / (float)logicalNames.Length);
                        continue;
                    }

                    while (handle.IsDone == false)
                    {
                        yield return null;
                    }

                    if (handle.Status != EOperationStatus.Succeeded)
                    {
                        missing.Append("\n  · " + name + "  →  " + handle.Error);
                        if (handle.IsValid)
                        {
                            handle.Release();
                        }
                        if (onProgress != null) onProgress((i + 1) / (float)logicalNames.Length);
                        continue;
                    }

                    _handles[name] = handle;
                    okCount++;
                    if (onProgress != null) onProgress((i + 1) / (float)logicalNames.Length);
                }

                if (missing.Length > 0)
                {
                    Fail(string.Format(
                        "[Res] YooAsset 预加载：{0}/{1} 个资源就绪，以下不可用：{2}",
                        okCount, logicalNames.Length, missing));
                }
                else
                {
                    Debug.Log(string.Format(
                        "[Res] YooAsset 预加载完成：{0} 个资源全部就绪。", okCount));
                }
            }

            if (onProgress != null) onProgress(1f);
            if (onDone != null)
            {
                onDone();
            }
        }

        // ==================================================================
        // 热更新（UI 补全 A3）—— 唯一的上线阻塞项
        // ==================================================================
        // ⚠️【与手册骨架的关键差异，别照抄网上 2.x 教程】
        //   手册 §7.2 的骨架用了 `UpdatePackageVersionAsync` + `CreateResourceDownloader(...)`
        //   + `OnDownloadProgressCallback` + `BeginDownload()`，那是 **YooAsset 2.x** 的 API。
        //   本工程是 **3.0.6**：`UpdatePackageVersionAsync` / `UpdatePackageManifestAsync` 已废弃，
        //   只在 Compatibility 层留了 [Obsolete] 包装。3.0.x 的正确对应关系是：
        //     · 「取最新版本」      = `RequestPackageVersionAsync()`（它本来就查远端最新）
        //     · 「更新/加载清单」   = `LoadPackageManifestAsync(version)` —— 即已有的第③步，
        //                             它会下载并激活新清单，**不再有独立的 Update 步骤**
        //     · 「下载进度」        = `DownloadProgressChanged` 事件（不是 OnDownloadProgressCallback）
        //     · 「开始下载」        = `StartDownload()`（不是 BeginDownload）
        //   ⚠️ 三步初始化契约不变：Init 里仍是 初始化 → 请求版本 → 加载清单（最后 SetActiveManifest）。
        //      本方法在 **Init 之后**调用，复用同一个 _package，绝不重复初始化。

        /// <summary>
        /// IHotUpdateLoader 入口：把 CheckUpdateCo 交给本工程的协程宿主驱动。
        /// 【为什么必须交给 ResLoaderRunner】UI 层拿不到（也不该拿）IEnumerator，
        /// 统一由 ResLoaderRunner 启动，保证"运行态逐帧推进、非运行态当场跑完"两条路径一致。
        /// </summary>
        public void StartCheckUpdate(
            Action<string> onPhase,
            Action<int, int> onProgress,
            Action<long, long> onBytes,
            Action<string> onError,
            Action<bool> onDone)
        {
            if (_checking) { onError?.Invoke("Resource check already running"); return; }
            _checking = true;
            ResLoaderRunner.Start(CheckUpdateGuarded(onPhase, onProgress, onBytes, onError, onDone));
        }

        /// <summary>
        /// 检查并执行资源热更新。协程，需由 ResLoaderRunner.Start 驱动。
        /// 回调语义：<paramref name="onDone"/> 的参数 = **本次是否真的下载过内容**。
        /// 出错时只调 <paramref name="onError"/>（不调 onDone），由界面决定是否重试。
        /// </summary>
        private bool _checking;
        private IEnumerator CheckUpdateGuarded(Action<string> phase, Action<int, int> progress, Action<long, long> bytes, Action<string> error, Action<bool> done)
        {
            // Reset before terminal callbacks: a caller may schedule a retry from that callback.
            try { yield return CheckUpdateCo(phase, progress, bytes, value => { _checking = false; error?.Invoke(value); }, value => { _checking = false; done?.Invoke(value); }); }
            finally { _checking = false; }
        }

        public IEnumerator CheckUpdateCo(
            Action<string> onPhase,
            Action<int, int> onProgress,
            Action<long, long> onBytes,
            Action<string> onError,
            Action<bool> onDone)
        {
            if (_package == null || !_ready)
            {
                if (onError != null)
                {
                    onError("资源系统尚未初始化完成，无法检查更新");
                }
                yield break;
            }

            // Editor simulate skips transfer; players always verify the complete pinned manifest.
#if UNITY_EDITOR && !FORCE_AB
            if (onPhase != null) onPhase("Editor resources");
            if (onDone != null) onDone(false);
            yield break;
#else
            var release = FTProject.AOT.BootReleaseStore.Selected;
            if (release == null || _package.GetPackageVersion() != release.resourceVersion)
            {
                onError?.Invoke("Resource version does not match the loaded DLL release. Restart required.");
                yield break;
            }
            string latestVersion = release.resourceVersion;
            string currentVersion = _package.GetPackageVersion();
            if (onPhase != null) onPhase("Verifying all resource bundles and dependencies");
            ResourceDownloaderOperation downloader;
            try
            {
                // YooAsset 3.0.6 走 options 结构（2.x 的 `CreateResourceDownloader(并发, 重试)` 已移除）
                var options = new ResourceDownloaderOptions(10, 3);   // 并发 10，失败重试 3
                downloader = _package.CreateResourceDownloader(options);
            }
            catch (System.Exception ex)
            {
                if (onError != null) onError("创建下载任务失败：" + ex.Message);
                yield break;
            }

            if (downloader == null || downloader.TotalDownloadCount == 0)
            {
                // 版本号变了但没有需要下载的资源（例如只改了清单里的哈希）→ 视为"无需下载"
                if (onPhase != null) onPhase("资源已是最新");
                Debug.Log(string.Format(
                    "[Version][Res] 无需下载资源，更新后资源版本={0}（与远端一致）。",
                    string.IsNullOrEmpty(latestVersion) ? "(未知)" : latestVersion));
                if (onDone != null) onDone(false);
                yield break;
            }

            if (FTProject.AOT.BootReleaseStore.Offline)
            {
                onError?.Invoke("Offline resources incomplete: " + downloader.TotalDownloadCount + " bundles missing. Restore the server and restart.");
                yield break;
            }
            if (onPhase != null) onPhase("正在下载资源...");

            _downloader = downloader;
            IsPaused = false;
            string lastError = null;
            bool timedOut = false;

            downloader.DownloadProgressChanged += args =>
            {
                if (onProgress != null) onProgress(args.CurrentDownloadCount, args.TotalDownloadCount);
                if (onBytes != null) onBytes(args.CurrentDownloadBytes, args.TotalDownloadBytes);
            };
            downloader.DownloadError += args =>
            {
                lastError = string.IsNullOrEmpty(args.FileName)
                    ? args.ErrorInfo
                    : args.FileName + "：" + args.ErrorInfo;
            };

            downloader.StartDownload();

            // Incomplete downloads never enter Main. Verified partial files remain available for retry.
            float deadline = Time.realtimeSinceStartup + TotalDownloadTimeoutSeconds;

            while (downloader.IsDone == false)
            {
                if (IsPaused) deadline += Time.unscaledDeltaTime;
                if (Time.realtimeSinceStartup >= deadline && timedOut == false)
                {
                    timedOut = true;
                    Debug.LogWarning(string.Format(
                        "[Res] 资源下载超过总超时 {0} 秒，取消本次下载（已下载部分保留，下次续传）。",
                        TotalDownloadTimeoutSeconds));
                    try
                    {
                        downloader.CancelDownload();
                    }
                    catch (System.Exception ex)
                    {
                        Debug.LogWarning("[Res] 取消下载时抛异常（忽略）：" + ex.Message);
                    }
                }
                yield return null;
            }

            _downloader = null;

            if (timedOut)
            {
                // 超时走错误通道：界面可据此提示"网络较慢，可稍后重试"，而不是假装成功。
                if (onError != null)
                {
                    onError(string.Format(
                        "资源下载超时（超过 {0} 秒）。已下载部分已保留，请恢复网络后重试。",
                        TotalDownloadTimeoutSeconds));
                }
                yield break;
            }

            if (downloader.Status != EOperationStatus.Succeeded)
            {
                if (onError != null)
                {
                    onError(string.IsNullOrEmpty(lastError) ? downloader.Error : lastError);
                }
                yield break;
            }

            Debug.Log(string.Format("[Res] 热更新完成，共下载 {0} 个文件。", downloader.TotalDownloadCount));

            // 【版本日志】更新完成后再取一次激活版本 —— 清单已在 ③ 换成远端最新，
            // 这条就是用户要的"更新完后的版本号"（与上面"当前资源版本"成对出现）。
            string updatedVersion;
            try
            {
                updatedVersion = _package.GetPackageVersion();
            }
            catch (Exception)
            {
                updatedVersion = "(未知)";
            }
            Debug.Log(string.Format(
                "[Version][Res] 资源热更新完成，更新后资源版本={0}（更新前={1}）。",
                updatedVersion, string.IsNullOrEmpty(currentVersion) ? "(未知)" : currentVersion));

            if (onPhase != null) onPhase("更新完成");
            if (onDone != null) onDone(true);
#endif
        }

        /// <summary>
        /// 整批资源下载的总超时（秒）。超过则取消本次下载并走错误通道。
        /// 需求第 5 条要求整个更新流程有总超时；YooAsset 只提供看门狗（卡死检测），
        /// 不提供批次总上限，所以在这里自己算。
        /// </summary>
        private const float TotalDownloadTimeoutSeconds = 300f;

        /// <summary>暂停当前下载（无进行中的下载时空操作）。</summary>
        public void PauseDownload()
        {
            IsPaused = true;
            if (_downloader != null)
            {
                _downloader.PauseDownload();
            }
        }

        /// <summary>继续当前下载（无进行中的下载时空操作）。</summary>
        public void ResumeDownload()
        {
            IsPaused = false;
            if (_downloader != null)
            {
                _downloader.ResumeDownload();
            }
        }

        /// <summary>是否正在下载（界面按钮状态用）。</summary>
        public bool IsDownloading
        {
            get { return _downloader != null && _downloader.IsDone == false; }
        }

        /// <summary>
        /// 是否处于"已暂停"。
        /// 【为什么自己记一个标记】YooAsset 的下载器没有暴露"暂停中"查询，
        /// 而界面必须能区分"正在下载"与"已暂停"（按钮要在"暂停/继续"之间切换）。
        /// 由本类的 PauseDownload/ResumeDownload 维护，不依赖底层实现。
        /// </summary>
        public bool IsPaused { get; private set; }

        /// <summary>
        /// 当前激活的资源清单版本（IHotUpdateLoader 实现）。
        /// 【为什么 try/catch】清单未激活（Init 失败/进行中）时 YooAsset 会抛异常；
        /// 版本号是展示性信息，取不到就返回 null，绝不让 UI/日志因为取版本而炸。
        /// </summary>
        public string CurrentResourceVersion
        {
            get
            {
                if (_package == null || !_ready)
                {
                    return null;
                }
                try
                {
                    return _package.GetPackageVersion();
                }
                catch (Exception)
                {
                    return null;
                }
            }
        }

        /// <summary>
        /// 最近一次初始化/加载失败的完整原因（2026-10-16 新增）。
        /// Boot 阶段的"初始化失败自动重试"界面会展示它（见 HotUpdateEntry.EnterMainCo）；
        /// 成功不清零，仅作诊断参考。
        /// </summary>
        public string LastInitError { get; private set; }

        /// <summary>
        /// 初始化失败后的"重试准备"——第一步：发起包裹的**异步销毁**（2026-10-16）。
        ///
        /// 【正确的重建流程】YooAsset 3.x 要求：`DestroyPackageAsync()` 完成之后
        ///   才能 `YooAssets.RemovePackage()`（否则会抛 "has not been destroyed.
        ///   Call DestroyPackageAsync before removing it."——实测教训）。
        ///   由于销毁是异步操作，拆成两步以便调用方（协程）在中间让帧推进：
        ///     ① BeginRetryDestroy() → 等操作 IsDone
        ///     ② CompleteRetryRebuild()
        ///
        /// 【为什么需要重建】失败后 package 停留在"已创建但未完成初始化"的状态；
        ///   在更深的失败态（如清单阶段失败）直接重跑 InitializePackageAsync 有撞
        ///   重复初始化检测的风险 —— 销毁重建是最确定的复位方式。
        /// </summary>
        /// <returns>异步销毁操作（无需销毁时返回 null）</returns>
        public DestroyPackageOperation BeginRetryDestroy()
        {
            if (_package == null)
            {
                return null;
            }
            try
            {
                return _package.DestroyPackageAsync();
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[Res] 重建前发起包裹销毁异常（忽略，将直接重建）：" + ex.Message);
                return null;
            }
        }

        /// <summary>
        /// 初始化失败后的"重试准备"——第二步：从全局移除已销毁的包裹（2026-10-16）。
        /// 与 <see cref="BeginRetryDestroy"/> 配对使用；全程容错（失败降级为
        /// "旧包裹存在时直接重跑 Init"——实测该降级路径也可工作）。
        /// </summary>
        public void CompleteRetryRebuild()
        {
            try
            {
                if (_package != null)
                {
                    // YooAsset 3.x 的 API 名是 RemovePackage（2.x 的 DestroyPackage 已移除）
                    YooAssets.RemovePackage(PackageName);
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[Res] 重建前的包裹移除异常（忽略）：" + ex.Message);
            }
            _package = null;
            _initProgress = null;
            _ready = false;
        }

        private void Fail(string message)
        {
            Debug.LogError(message);
            LastInitError = message;
            if (OnLoadError != null)
            {
                OnLoadError(message);
            }
        }

        // ==================================================================
        // 诊断
        // ==================================================================

        public string DumpDebugInfo()
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine(string.Format(
                "[Res] YooAssetResLoader：包裹={0}，持有句柄 {1} 个，引用记录 {2} 个包，定位地址缓存 {3} 条",
                PackageName, _handles.Count, _refCount.Count, _locations.Count));
            foreach (KeyValuePair<string, int> kv in _refCount)
            {
                sb.AppendLine(string.Format("  · {0,-18} ref={1}{2}",
                    kv.Key, kv.Value, IsPersistent(kv.Key) ? "（常驻）" : string.Empty));
            }
            return sb.ToString();
        }

        /// <summary>引用计数是否全部归零（除常驻包外）—— 泄漏自检用</summary>
        public bool HasLeak()
        {
            foreach (KeyValuePair<string, int> kv in _refCount)
            {
                if (kv.Value > 0 && IsPersistent(kv.Key) == false)
                {
                    return true;
                }
            }
            return false;
        }
    }
}
#endif

using System.Collections;
using System.Collections.Generic;
using System.Text;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace FTProject
{
    /// <summary>
    /// 【真机诊断】运行时"缺失脚本（missing script）"扫描器。
    ///
    /// 背景：AB 资源里的脚本引用（GUID）若在运行时无法解析，Unity 会逐条打
    /// “The referenced script on this Behaviour (Game Object '…') is missing!”。
    /// 海量警告里很难看出"到底哪个对象挂了 missing"，尤其 GameObject 显示为 '&lt;null&gt;'
    /// 时（StateMachineBehaviour 等不属于任何 GameObject 的行为）。
    /// 本扫描器在关卡初始化完成后延时扫一遍场景对象树，把结果**汇总成一条日志**：
    ///   - 无缺失 → “[Audit] 缺失脚本扫描：0”；
    ///   - 有缺失 → 列出 对象完整路径 + 缺失槽位数（路径可直接在 Hierarchy 里定位）。
    ///
    /// 检测原理：GameObject.GetComponents&lt;Component&gt;() 返回的数组里，
    /// 缺失脚本的槽位为 null —— 出现 null 即该对象上有 missing script。
    ///
    /// 【为什么延时扫描】关卡初始化（UI 打开 / 资源实例化 / 快照恢复）是分帧完成的，
    /// 立即扫描会漏掉当帧之后才实例化的对象；默认延迟 1 秒覆盖整个启动窗口。
    ///
    /// 【开销】每关一次、数百对象 × GetComponents，毫秒级；无缺失时只打一行 OK。
    /// </summary>
    public static class RuntimeMissingScriptAudit
    {
        /// <summary>延时扫描入口（host 用 GameFlowManager 自身即可）。</summary>
        public static void RunDeferred(MonoBehaviour host, float delaySec = 1f)
        {
            if (host == null)
            {
                return;
            }
            host.StartCoroutine(RunCo(delaySec));
        }

        private static IEnumerator RunCo(float delaySec)
        {
            yield return new WaitForSecondsRealtime(delaySec);

            int missingObjects = 0;
            int missingSlots = 0;
            StringBuilder detail = null;

            // 场景根对象树（含 DontDestroyOnLoad 场景——SceneManager 会一并列出）
            List<GameObject> roots = new List<GameObject>(64);
            for (int s = 0; s < SceneManager.sceneCount; s++)
            {
                Scene scene = SceneManager.GetSceneAt(s);
                if (!scene.isLoaded)
                {
                    continue;
                }
                scene.GetRootGameObjects(roots);
            }

            for (int i = 0; i < roots.Count; i++)
            {
                Walk(roots[i], ref missingObjects, ref missingSlots, ref detail);
            }

            if (missingSlots > 0)
            {
                Debug.LogWarning(string.Format(
                    "[Audit] 缺失脚本（missing script）扫描：{0} 个对象 / {1} 个槽位。明细：\n{2}",
                    missingObjects, missingSlots, detail));
            }
            else
            {
                Debug.Log("[Audit] 缺失脚本扫描：0（全部脚本引用解析正常）");
            }
        }

        private static void Walk(GameObject go, ref int missingObjects, ref int missingSlots, ref StringBuilder detail)
        {
            Component[] comps = go.GetComponents<Component>();
            int nullCount = 0;
            for (int i = 0; i < comps.Length; i++)
            {
                if (comps[i] == null)
                {
                    nullCount++;
                }
            }
            if (nullCount > 0)
            {
                missingObjects++;
                missingSlots += nullCount;
                if (detail == null)
                {
                    detail = new StringBuilder(512);
                }
                detail.Append("  - ").Append(GetPath(go.transform))
                      .Append("（缺失 ").Append(nullCount).Append(" 个脚本槽位）\n");
            }

            Transform t = go.transform;
            for (int i = 0; i < t.childCount; i++)
            {
                Walk(t.GetChild(i).gameObject, ref missingObjects, ref missingSlots, ref detail);
            }
        }

        private static string GetPath(Transform t)
        {
            StringBuilder sb = new StringBuilder(128);
            while (t != null)
            {
                if (sb.Length > 0)
                {
                    sb.Insert(0, '/');
                }
                sb.Insert(0, t.name);
                t = t.parent;
            }
            return sb.ToString();
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
namespace FTProject
{
    public class TimerManager : BaseManager<TimerManager>
    {
        class TimerItem
        {
            public int id;
            public float Interval
            {
                get { return _interval; }
                set { _interval = value; }
            }
            public int loopTimes;
            public float _interval;

            public float TempInterval;

            public UnityEngine.Object callbackObject;
            public object[] args;

            public Action callback;
            public Action<UnityEngine.Object> callbackObjectEvent;
            public Action<UnityEngine.Object, object[]> callbackObjAndArgs;
            public bool isNotLimtied;
            public bool isStop;
            public bool isFree;


            public TimerItem()
            {

            }
            public TimerItem(int id, float interval, int loopTimes, Action callback = null, Action<UnityEngine.Object> actionObject = null, Action<UnityEngine.Object, object[]> action = null, UnityEngine.Object obj = null, object[] args = null)
            {
                this.id = id;
                this._interval = interval;
                this.TempInterval = interval;
                this.loopTimes = loopTimes;
                this.callback = callback;
                this.callbackObjectEvent = actionObject;
                this.callbackObjAndArgs = action;
                this.callbackObject = obj;
                this.args = args;
                isStop = false;
                isNotLimtied = loopTimes == -1;
                isFree = true;
            }
            public void Reset()
            {
                this.loopTimes--;
                this._interval = TempInterval;
                isFree = loopTimes == 0;
            }
        }

        private Dictionary<int, TimerItem> _timerDicti;
        public int actionIndex;

        public float checkTimerInterval = 3f;

        public TimerManager()
        {
            _timerDicti = new Dictionary<int, TimerItem>();
            actionIndex = 0;
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="interval">时间间隔</param>
        /// <param name="loopTimes">执行次数</param>
        /// <param name="callback">回调函数</param>
        /// /// /// <param name="isRun">是否立即执行</param>
        /// <param name="actionObject"></param>
        /// <param name="action"></param>
        /// <param name="obj"></param>
        /// <param name="args"></param>
        /// <returns></returns>
        public int AddTimer(float interval, int loopTimes, Action callback, bool isRun = false, Action<UnityEngine.Object> actionObject = null, Action<UnityEngine.Object, object[]> action = null, UnityEngine.Object obj = null, object[] args = null)
        {
            TimerItem item = GetTimerItem(interval, loopTimes, callback, actionObject, action, obj, args);
            if (isRun)
            {
                item.loopTimes--;
                if (callback != null)
                {
                    callback();
                }
                if (actionObject != null)
                {
                    actionObject(item.callbackObject);
                }
                if (action != null)
                {
                    action(item.callbackObject, item.args);
                }
            }
            return item.id;
        }


        public void Update(float intervalTime)
        {
            //CheckTimerItem();
            if (_timerDicti.Count > 0)
            {
                for (int i = 0; i < _timerDicti.Count; i++)
                {
                    KeyValuePair<int, TimerItem> item = _timerDicti.ElementAt(i);

                    if (!item.Value.isStop)
                    {
                        if (item.Value.isNotLimtied || item.Value.loopTimes > 0)
                        {
                            item.Value.Interval -= intervalTime;
                            if (item.Value.Interval <= 0)
                            {
                                if (item.Value.callback != null)
                                {
                                    item.Value.callback();
                                }
                                if (item.Value.callbackObjectEvent != null && item.Value.callbackObject != null)
                                {
                                    item.Value.callbackObjectEvent(item.Value.callbackObject);
                                }
                                if (item.Value.callbackObjAndArgs != null && item.Value.callbackObject != null && item.Value.args != null)
                                {
                                    item.Value.callbackObjAndArgs(item.Value.callbackObject, item.Value.args);
                                }
                                item.Value.Reset();
                            }
                        }
                    }
                }
            }
        }
        public void StopTimerById(int id, bool isStop = true)
        {
            if (_timerDicti.ContainsKey(id))
            {
                _timerDicti[id].isStop = isStop;
            }
        }

        public void RemoveTimerById(int id)
        {
            if (_timerDicti.ContainsKey(id))
            {
                _timerDicti[id].isFree = true;
                _timerDicti[id].isStop = true;
            }
        }

        private TimerItem GetTimerItem(float interval, int loopTimes, Action callback, Action<UnityEngine.Object> actionObject, Action<UnityEngine.Object, object[]> action = null, UnityEngine.Object obj = null, object[] args = null)
        {
            if (_timerDicti.Count > 0)
            {
                for (int i = 1; i < _timerDicti.Count; i++)
                {
                    KeyValuePair<int, TimerItem> item = _timerDicti.ElementAt(i);
                    if (item.Value.isFree)
                    {
                        item.Value.TempInterval = interval;
                        item.Value.Interval = interval;
                        item.Value.loopTimes = loopTimes;
                        item.Value.callback = callback;
                        item.Value.callbackObjectEvent = actionObject;
                        item.Value.callbackObjAndArgs = action;
                        item.Value.args = args;
                        item.Value.isFree = false;
                        item.Value.isStop = false;
                        return item.Value;
                    }
                }
            }
            actionIndex++;
            TimerItem item1 = new TimerItem(actionIndex, interval, loopTimes, callback, actionObject, action, obj, args);
            item1.isFree = false;
            item1.isStop = false; ;
            _timerDicti.Add(actionIndex, item1);
            return item1;
        }

        public override void OnDestroy()
        {
            base.OnDestroy();
            _timerDicti.Clear();
        }

        public void CheckTimerItem()
        {
            if(_timerDicti.Count > 5)
            {
                for (int i = _timerDicti.Count - 1; i > 0; i++)
                {
                    KeyValuePair<int, TimerItem> item = _timerDicti.ElementAt(i);
                    if (item.Value.isFree)
                    {
                        _timerDicti.Remove(item.Key);
                        if (_timerDicti.Count <= 5)
                        {
                            return;
                        }
                    }
                }
            }
        }

        public void ClearAll()
        {
            _timerDicti.Clear();
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 安全区适配（M4-1）：把挂载的 RectTransform 收进 Screen.safeArea。
    ///
    /// 【为什么需要】刘海屏 / 挖孔屏 / 圆角屏会把屏幕四边一小条挡住。
    /// 不处理的话，HUD 左上角的「金币」正好会被刘海压住 —— 这是移动端最常见的一类"看不见的 bug"。
    ///
    /// 【为什么是改 anchor 而不是改 offset】
    ///   anchorMin/Max 表达的是"占屏幕的比例"，正好对应 safeArea 的定义；
    ///   而 offset 是像素量，换分辨率就要重算。用 anchor 一次写对，之后自适应。
    ///
    /// 【为什么要缓存上一次的值】Update 里每帧比较 Rect 是廉价的，
    ///   但 Apply 会触发 Canvas 重建（改 RectTransform 会影响布局），
    ///   每帧无脑调会在低端机上明显掉帧。
    ///
    /// 【谁挂它】UIManager 在解析到 UICanvas 时会自动补挂（见 UIManager.UICanvas），
    ///   这样不需要重建场景就能生效。
    /// </summary>
    [RequireComponent(typeof(RectTransform))]
    public class SafeAreaFitter : MonoBehaviour
    {
        private RectTransform _rt;
        private Rect _lastSafe;
        private int _lastW = -1;
        private int _lastH = -1;

        private void Awake()
        {
            _rt = GetComponent<RectTransform>();
            Apply();
        }

        private void Update()
        {
            if (Screen.width != _lastW || Screen.height != _lastH || Screen.safeArea != _lastSafe)
            {
                Apply();
            }
        }

        public void Apply()
        {
            if (_rt == null)
            {
                _rt = GetComponent<RectTransform>();
            }
            if (_rt == null || Screen.width <= 0 || Screen.height <= 0)
            {
                return;
            }

            Rect sa = Screen.safeArea;
            _lastSafe = sa;
            _lastW = Screen.width;
            _lastH = Screen.height;

            Vector2 min = sa.position;
            Vector2 max = sa.position + sa.size;
            min.x /= Screen.width;
            min.y /= Screen.height;
            max.x /= Screen.width;
            max.y /= Screen.height;

            _rt.anchorMin = min;
            _rt.anchorMax = max;
            _rt.offsetMin = Vector2.zero;
            _rt.offsetMax = Vector2.zero;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 界面级"全局点击音"（M4-W7）。
    ///
    /// 【为什么挂在界面上，而不是在每个 View 的 onClick 里手动 Play】
    ///   本项目有 7 个界面、几十个按钮，且不少按钮是**运行时创建**的
    ///   （例如 SelectView 每次显示都会 Instantiate 一批关卡按钮）。
    ///   逐个去写 `AudioManager.Play(AudioName.UiClick)` 的后果是：
    ///   ① 一定会漏；② 新加按钮的人不知道该写；
    ///   ③ 想换点击音要全局搜字符串。
    ///   挂在界面根节点上统一代管，就只需要在 `UIManager.Open` 里加一行。
    ///
    /// 【为什么要周期性重扫】
    ///   按钮是运行时创建的（关卡按钮、以后可能有的动态列表），
    ///   OnEnable 那一刻它们可能还不存在；SelectView 还会在每次 OnEnable 时
    ///   **销毁并重建**按钮，旧引用随之作废。
    ///   与其在每个 View 里加"通知钩子"，不如让本组件低频重扫：
    ///   代价是每个界面每 0.4 秒一次 `GetComponentsInChildren`（几十个节点，可忽略），
    ///   换来的是"谁建的按钮都能自动有声音"。
    ///
    /// 【为什么用未缩放时间】暂停界面在 timeScale=0 下打开，用缩放时间会让重扫停摆。
    /// </summary>
    public class UiClickSfx : MonoBehaviour
    {
        /// <summary>重扫间隔（秒）。太密没必要，太疏会让"新出现的按钮"短时间没声音。</summary>
        private const float RescanInterval = 0.4f;

        private readonly List<Button> _hooked = new List<Button>();
        private float _nextRescan;

        private void OnEnable()
        {
            // 立刻扫一次，避免刚打开的界面在第一次间隔内点了没声
            _nextRescan = 0f;
            HookAll();
        }

        private void OnDisable()
        {
            // 【必须解绑】界面会被 SetActive(false) 后复用（UIManager.Open 对已存在实例直接返回），
            // 不解绑会让同一个按钮累积多个监听 → 一次点击播多次（音量翻倍）。
            for (int i = 0; i < _hooked.Count; i++)
            {
                if (_hooked[i] != null)
                {
                    _hooked[i].onClick.RemoveListener(OnAnyClick);
                }
            }
            _hooked.Clear();
            _nextRescan = 0f;
        }

        private void Update()
        {
            if (Time.unscaledTime < _nextRescan)
            {
                return;
            }
            _nextRescan = Time.unscaledTime + RescanInterval;
            HookAll();
        }

        /// <summary>把本界面下所有 Button（含未激活的）都挂上点击音。可重复调用，幂等。</summary>
        private void HookAll()
        {
            // ① 先剔除已被销毁的引用（SelectView 重建按钮后，旧引用会变成"假 null"）
            for (int i = _hooked.Count - 1; i >= 0; i--)
            {
                if (_hooked[i] == null)
                {
                    _hooked.RemoveAt(i);
                }
            }

            // ② 再补齐新出现的按钮
            Button[] all = GetComponentsInChildren<Button>(true);
            for (int i = 0; i < all.Length; i++)
            {
                Button b = all[i];
                if (b == null || IsHooked(b))
                {
                    continue;
                }
                b.onClick.AddListener(OnAnyClick);
                _hooked.Add(b);
            }
        }

        /// <summary>
        /// 用 `==` 比较（UnityEngine.Object 重载了它，能正确处理"已销毁对象"）。
        /// 注意不要用 List.Contains —— 它走 EqualityComparer，语义与 Unity 的 == 不同。
        /// </summary>
        private bool IsHooked(Button b)
        {
            for (int i = 0; i < _hooked.Count; i++)
            {
                if (_hooked[i] == b)
                {
                    return true;
                }
            }
            return false;
        }

        private void OnAnyClick()
        {
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.Play(AudioName.UiClick);
            }
        }
    }
}

using System.Collections;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 界面淡入（M4-3）。由 UIManager 在打开界面时按需补挂。
    ///
    /// 【为什么不用 DOTween】工程里确实带了 DOTween，但界面淡入是"一个 alpha 从 0 到 1"的量级，
    /// 为此引入一条补间链、还要保证 DOTween 已初始化，收益为负。
    /// 十来行的协程更可控，也少一处运行时依赖。
    ///
    /// 【为什么用 unscaledDeltaTime】暂停界面（PauseView）是在 timeScale = 0 下打开的，
    /// 用 scaled 时间的话它永远不会淡入，直接卡在全透明。
    /// </summary>
    public class UIFader : MonoBehaviour
    {
        private CanvasGroup _cg;
        private float _duration;
        private Coroutine _running;

        public void Begin(CanvasGroup cg, float durationSec)
        {
            _cg = cg;
            _duration = Mathf.Max(0.01f, durationSec);
            if (_running != null)
            {
                StopCoroutine(_running);
            }
            _running = StartCoroutine(Run());
        }

        private IEnumerator Run()
        {
            if (_cg == null)
            {
                yield break;
            }
            float t = 0f;
            _cg.alpha = 0f;
            while (t < _duration)
            {
                t += Time.unscaledDeltaTime;
                _cg.alpha = Mathf.Clamp01(t / _duration);
                yield return null;
            }
            _cg.alpha = 1f;
            _running = null;
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>Only shrink a fixed-size dialog when its safe-area parent cannot contain it.</summary>
    [DisallowMultipleComponent, RequireComponent(typeof(RectTransform))]
    public sealed class UIFitInParent : MonoBehaviour
    {
        [SerializeField] private Vector2 padding = new Vector2(24f, 24f);
        private RectTransform _rect;
        private Vector2 _lastParentSize;
        private Vector2 _lastSize;

        private void OnEnable() { Refresh(); }
        private void LateUpdate() { Refresh(); }

        public void Refresh()
        {
            if (_rect == null) _rect = (RectTransform)transform;
            RectTransform parent = _rect.parent as RectTransform;
            if (parent == null) return;
            Vector2 available = parent.rect.size;
            Vector2 size = _rect.rect.size;
            if (available.x <= 0f || available.y <= 0f || size.x <= 0f || size.y <= 0f) return;
            float scale = Mathf.Clamp01(Mathf.Min((available.x - 2f * padding.x) / size.x,
                (available.y - 2f * padding.y) / size.y));
            if (_lastParentSize == available && _lastSize == size &&
                Mathf.Approximately(_rect.localScale.x, scale)) return;
            _lastParentSize = available;
            _lastSize = size;
            _rect.localScale = new Vector3(scale, scale, 1f);
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>Keep the mask on the full canvas while its sibling controls inherit the safe area.</summary>
    [DisallowMultipleComponent, RequireComponent(typeof(RectTransform))]
    public sealed class UIFullScreenBackground : MonoBehaviour
    {
        private readonly Vector3[] _corners = new Vector3[4];
        private RectTransform _rect;

        private void OnEnable()
        {
            Canvas.willRenderCanvases += Refresh;
            Refresh();
        }

        private void OnDisable() { Canvas.willRenderCanvases -= Refresh; }

        public void Refresh()
        {
            if (_rect == null) _rect = (RectTransform)transform;
            RectTransform parent = _rect.parent as RectTransform;
            Canvas canvas = GetComponentInParent<Canvas>();
            if (parent == null || canvas == null) return;
            RectTransform screen = canvas.rootCanvas.transform as RectTransform;
            if (screen == null) return;
            screen.GetWorldCorners(_corners);
            Vector2 min = parent.InverseTransformPoint(_corners[0]);
            Vector2 max = parent.InverseTransformPoint(_corners[2]);
            Vector2 offsetMin = min - parent.rect.min;
            Vector2 offsetMax = max - parent.rect.max;
            if ((_rect.offsetMin - offsetMin).sqrMagnitude > 0.001f) _rect.offsetMin = offsetMin;
            if ((_rect.offsetMax - offsetMax).sqrMagnitude > 0.001f) _rect.offsetMax = offsetMax;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>UI 分层（与场景中 UICanvas 下的三个 Panel 节点一一对应）</summary>
    public enum UILayout
    {
        BgPanel,
        NormalPanel,
        TipsPanel,
    }

    /// <summary>
    /// UI 管理器（v2.1 重写）。
    ///
    /// 相对 v1.0 的改动：
    ///   - **去掉 AssetData / ResourcesManager 依赖**（这两个类已废弃，Resources 目录也不再使用）
    ///   - 界面加载改走 ResLoader（编辑器直读 / 真机 AB 同一套调用）
    ///   - 去掉 BaseView / BaseDisplayObject 那套"new 一个非 MonoBehaviour 的 View 对象"的设计：
    ///     它要求 View 是 `new()` 可构造的普通类，导致 View 拿不到 MonoBehaviour 生命周期、
    ///     也无法用 `transform.Find` 之外的方式引用子节点。现在 View 一律是挂在 prefab 上的
    ///     MonoBehaviour，由 UIManager 负责实例化与层级归属。
    ///
    /// 三层结构（场景中必须齐备，否则 UI 打不开）：
    ///   UICanvas(tag=UICanvas) ├─ BgPanel ├─ NormalPanel └─ TipsPanel
    /// </summary>
    public class UIManager : BaseManager<UIManager>
    {
        private RectTransform _uiCanvas;
        private readonly Dictionary<UILayout, RectTransform> _layers =
            new Dictionary<UILayout, RectTransform>();
        private readonly Dictionary<string, GameObject> _opened =
            new Dictionary<string, GameObject>();

        public RectTransform UICanvas
        {
            get
            {
                if (_uiCanvas == null)
                {
                    GameObject go = GameObject.FindGameObjectWithTag("UICanvas");
                    if (go == null)
                    {
                        Debug.LogError(
                            "[UI] 场景中找不到 Tag 为 UICanvas 的对象。" +
                            "请执行「Tools ▸ 塔防 ▸ 搭建 main 场景」自动创建，或手动给 Canvas 打上该 Tag。");
                        return null;
                    }
                    _uiCanvas = go.GetComponent<RectTransform>();

                    // M4-1 安全区适配（2026-10-16 修正挂载点）。
                    // 【为什么不再挂在 UICanvas 根上】根画布的 RectTransform 完全由 Canvas 驱动：
                    //   实测向根写入锚点后会被覆盖——先瞬间塌成 0×0，随后锚点被复位、rect 回全屏
                    //   → 挂根上等于"写了个不起作用的组件"。改为在 GetLayer 里挂到三个层节点
                    //   （BgPanel/NormalPanel/TipsPanel）：层节点是普通 RectTransform，锚点写入生效；
                    //   界面按层铺满时自动继承安全区（全屏遮罩如需覆盖刘海区，另见界面 Bg 外扩方案）。
                }
                return _uiCanvas;
            }
        }

        public RectTransform GetLayer(UILayout type)
        {
            RectTransform rect;
            if (_layers.TryGetValue(type, out rect) && rect != null)
            {
                EnsureSafeArea(rect);
                return rect;
            }

            RectTransform canvas = UICanvas;
            if (canvas == null)
            {
                return null;
            }
            Transform child = canvas.Find(type.ToString());
            if (child == null)
            {
                Debug.LogError(string.Format(
                    "[UI] UICanvas 下缺少子节点「{0}」，无法挂载界面", type));
                return null;
            }
            rect = child as RectTransform;
            _layers[type] = rect;
            EnsureSafeArea(rect);
            return rect;
        }

        /// <summary>
        /// 给层节点补挂安全区适配（2026-10-16 从画布根迁移而来，原因见 UICanvas getter 注释）。
        /// 挂载在这里而不是要求重建场景：层节点按名字查找，老场景同样立即生效。
        /// </summary>
        private static void EnsureSafeArea(RectTransform layer)
        {
            if (layer != null && layer.GetComponent<SafeAreaFitter>() == null)
            {
                layer.gameObject.AddComponent<SafeAreaFitter>();
            }
        }

        // ------------------------------------------------------------------
        // 打开 / 关闭
        // ------------------------------------------------------------------

        /// <summary>
        /// 打开一个界面 prefab（逻辑名对应 ResTable）。
        /// 已打开则直接返回原实例（不重复实例化）。
        /// </summary>
        public GameObject Open(string logicalName, UILayout layout)
        {
            GameObject exist;
            if (_opened.TryGetValue(logicalName, out exist))
            {
                if (exist != null)
                {
                    exist.SetActive(true);
                    return exist;
                }
                _opened.Remove(logicalName);
            }

            RectTransform parent = GetLayer(layout);
            if (parent == null)
            {
                return null;
            }

            // Only the stable AOT HotUpdateView may use the APK Resources copy.
            // Loading/Splash must resolve from the verified active AB release.
            GameObject go = null;
            ResAddress addr;
            if (logicalName != "HotUpdateView" && ResLoader.Instance.IsReady && ResTable.TryGet(logicalName, out addr))
            {
                go = ResLoader.Instance.Instantiate(logicalName, parent);
            }
            if (go == null)
            {
                go = InstantiateBootUi(logicalName, parent);
                if (go != null)
                {
                    _bootOpened.Add(logicalName);
                }
            }
            if (go == null)
            {
                Debug.LogError(string.Format("[UI] 界面「{0}」实例化失败", logicalName));
                return null;
            }

            // 铺满所属层
            RectTransform rt = go.GetComponent<RectTransform>();
            if (rt != null)
            {
                rt.anchorMin = Vector2.zero;
                rt.anchorMax = Vector2.one;
                rt.offsetMin = Vector2.zero;
                rt.offsetMax = Vector2.zero;
                rt.localScale = Vector3.one;
            }
            _opened[logicalName] = go;
            EnsureFadeIn(go);
            EnsureClickSfx(go);
            return go;
        }

        /// <summary>界面淡入时长（秒，走 unscaled 时间 —— 暂停界面是在 timeScale=0 下打开的）</summary>
        private const float FadeInSec = 0.12f;

        /// <summary>引导期界面的 Resources 相对目录（见 Open 里关于"先有鸡还是先有蛋"的说明）。</summary>
        private const string BootUiDir = "BootUI/";

        /// <summary>
        /// 记录哪些已打开界面是"引导期从 Resources 加载"的。
        /// 【为什么要单独记】这类实例不是 ResLoader 创建的，不能交给 ReleaseInstance
        /// （它会去 ResTable 查地址 → 查不到就报错，而且 YooAsset 那边也没有对应句柄）。
        /// 它们只由本类 Destroy。
        /// </summary>
        private readonly HashSet<string> _bootOpened = new HashSet<string>();

        /// <summary>
        /// 从 `Resources/BootUI/` 取引导期界面并实例化。取不到返回 null（由调用方报错）。
        /// 只有 3 个界面走这里：SplashView / LoadingView / HotUpdateView。
        /// </summary>
        private static GameObject InstantiateBootUi(string logicalName, Transform parent)
        {
            if (logicalName != "HotUpdateView") return null;
            GameObject prefab = Resources.Load<GameObject>(BootUiDir + logicalName);
            if (prefab == null)
            {
                return null;
            }
            GameObject go = Object.Instantiate(prefab, parent, false);
            go.name = logicalName;
            Debug.Log(string.Format(
                "[UI] 资源系统尚未就绪，界面「{0}」从 Resources/{1} 以引导期模式加载", logicalName, BootUiDir));
            return go;
        }

        /// <summary>
        /// 给新打开的界面补一个淡入（M4-3）。
        ///
        /// 【为什么"自带 CanvasGroup 的界面就跳过"】TipsView 用 CanvasGroup 自己管淡入淡出，
        /// 我们再插一脚就会两边抢 alpha，表现为"提示一闪一闪"。
        /// 约定：prefab 自带 CanvasGroup ⇒ 该界面自己负责透明度，UIManager 不插手。
        /// 这样不改任何 prefab 就能给 M3 新界面加上转场。
        /// </summary>
        private static void EnsureFadeIn(GameObject go)
        {
            if (go == null || go.GetComponent<CanvasGroup>() != null)
            {
                return;
            }
            CanvasGroup cg = go.AddComponent<CanvasGroup>();
            UIFader fader = go.AddComponent<UIFader>();
            fader.Begin(cg, FadeInSec);
        }

        /// <summary>
        /// 给界面挂一个"全局点击音"（M4-W7）。已挂则跳过。
        ///
        /// 【为什么统一挂在这里，而不是让每个 View 自己播】
        ///   本项目按钮多且部分是运行时创建的（SelectView 每次显示都会重造关卡按钮）。
        ///   统一代管的收益是：新加按钮**自动**有声音，不用记得写、也不用全局搜字符串；
        ///   代价只是每个界面每 0.4 秒重扫一次按钮（见 <see cref="UiClickSfx"/>）。
        /// </summary>
        private static void EnsureClickSfx(GameObject go)
        {
            if (go == null || go.GetComponent<UiClickSfx>() != null)
            {
                return;
            }
            go.AddComponent<UiClickSfx>();
        }

        /// <summary>打开并取组件</summary>
        public T Open<T>(string logicalName, UILayout layout) where T : Component
        {
            GameObject go = Open(logicalName, layout);
            if (go == null)
            {
                return null;
            }
            T comp = go.GetComponent<T>();
            if (comp == null)
            {
                Debug.LogError(string.Format(
                    "[UI] 界面「{0}」上没有 {1} 组件（prefab 可能没挂脚本）",
                    logicalName, typeof(T).Name));
            }
            return comp;
        }

        public void Close(string logicalName)
        {
            GameObject go;
            if (_opened.TryGetValue(logicalName, out go))
            {
                _opened.Remove(logicalName);
                if (go != null)
                {
                    // 【为什么要先 SetActive(false)】Destroy 要到本帧末才真正生效。
                    // 而"切关"是在同一帧里 Close 旧的 + Open 新的（例如 HUD），
                    // 不先隐藏的话，同屏会短暂存在两份界面，且旧界面仍会响应事件。
                    go.SetActive(false);
                    if (_bootOpened.Remove(logicalName))
                    {
                        // 引导期界面不是 ResLoader 创建的 → 直接 Destroy，不走 ReleaseInstance
                        Object.Destroy(go);
                    }
                    else
                    {
                        ResLoader.Instance.ReleaseInstance(logicalName, go);
                    }
                }
            }
        }

        public T Get<T>(string logicalName) where T : Component
        {
            GameObject go;
            if (_opened.TryGetValue(logicalName, out go) && go != null)
            {
                return go.GetComponent<T>();
            }
            return null;
        }

        public bool IsOpen(string logicalName)
        {
            GameObject go;
            return _opened.TryGetValue(logicalName, out go) && go != null;
        }

        public override void OnDestroy()
        {
            base.OnDestroy();
            foreach (KeyValuePair<string, GameObject> kv in _opened)
            {
                if (kv.Value != null)
                {
                    Object.Destroy(kv.Value);
                }
            }
            _opened.Clear();
            _layers.Clear();
        }

        public string DumpDebugInfo()
        {
            return string.Format("[UI] 已打开界面 {0} 个：{1}", _opened.Count,
                string.Join("、", new List<string>(_opened.Keys).ToArray()));
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// Fit page content between the header and footer, leaving LoopListView2's cached local
    /// viewport and item dimensions unchanged. Scaling an ancestor preserves that coordinate system.
    /// </summary>
    [DisallowMultipleComponent, RequireComponent(typeof(RectTransform))]
    public sealed class UIResponsivePage : MonoBehaviour
    {
        public enum PageKind { MainMenu, Select, TowerCodex }
        [SerializeField] private PageKind page;
        private RectTransform _panel;
        private RectTransform _list;
        private RectTransform _viewport;
        private RectTransform _left;
        private RectTransform _right;
        private RectTransform[] _menu;
        private Vector2 _lastSize = new Vector2(-1f, -1f);
        private static readonly string[] MenuNames = { "Logo", "GameTitle", "Subtitle", "StartBtn", "CodexBtn", "SettingBtn" };
        private static readonly float[] MenuY = { 270f, 83f, 9f, -66f, -184f, -302f };

        public void Configure(PageKind kind) { page = kind; _panel = null; _lastSize = new Vector2(-1f, -1f); }
        private void OnEnable() { Refresh(); }
        private void LateUpdate() { Refresh(); }

        public void Refresh()
        {
            if (_panel == null)
            {
                _panel = transform.Find("Panel") as RectTransform;
                if (_panel == null) return;
                _list = _panel.Find("List") as RectTransform;
                _viewport = _panel.Find("List/Viewport") as RectTransform;
                _left = _panel.Find("LeftBtn") as RectTransform;
                _right = _panel.Find("RightBtn") as RectTransform;
                _menu = new RectTransform[MenuNames.Length];
                for (int i = 0; i < _menu.Length; i++) _menu[i] = _panel.Find(MenuNames[i]) as RectTransform;
            }
            Vector2 size = _panel.rect.size;
            if (size.x <= 0f || size.y <= 0f || size == _lastSize) return;
            _lastSize = size;
            FitTextWidth("Title", 1400f, size.x);
            FitTextWidth("CodexTitle", 1400f, size.x);
            FitTextWidth("Summary", 1400f, size.x);
            if (page == PageKind.MainMenu)
            {
                // Baseline column bounds [-348,460], with 80 top and 192 bottom reserved.
                float scale = Mathf.Clamp01(Mathf.Min((size.y - 272f) / 808f, (size.x - 64f) / 1000f));
                for (int i = 0; i < _menu.Length; i++)
                {
                    if (_menu[i] == null) continue;
                    _menu[i].localScale = new Vector3(scale, scale, 1f);
                    _menu[i].anchoredPosition = new Vector2(0f, 56f + (MenuY[i] - 56f) * scale);
                }
            }
            else if (page == PageKind.Select && _viewport != null)
            {
                float top = size.y * 0.5f - 262f;
                float bottom = -size.y * 0.5f + 172f;
                float scale = Mathf.Clamp01(Mathf.Min((size.x - 432f) / 1150f, (top - bottom) / 550f));
                float center = Mathf.Clamp(0f, bottom + 275f * scale, top - 275f * scale);
                _viewport.localScale = new Vector3(scale, scale, 1f);
                _viewport.anchoredPosition = new Vector2(-575f * scale, center);
                MoveArrows(center + 10f);
            }
            else if (page == PageKind.TowerCodex && _list != null)
            {
                float top = size.y * 0.5f - 140f;
                float bottom = -size.y * 0.5f + 210f;
                float scale = Mathf.Clamp01(Mathf.Min((size.x - 380f) / 1300f, (top - bottom) / 640f));
                float center = Mathf.Clamp(-10f, bottom + 320f * scale, top - 320f * scale);
                _list.localScale = new Vector3(scale, scale, 1f);
                _list.anchoredPosition = new Vector2(0f, center);
                MoveArrows(center);
            }
        }

        private void FitTextWidth(string name, float maximum, float width)
        {
            RectTransform text = _panel.Find(name) as RectTransform;
            if (text != null) text.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, Mathf.Min(maximum, Mathf.Max(0f, width - 64f)));
        }

        private void MoveArrows(float y)
        {
            if (_left != null) _left.anchoredPosition = new Vector2(_left.anchoredPosition.x, y);
            if (_right != null) _right.anchoredPosition = new Vector2(_right.anchoredPosition.x, y);
        }
    }
}

using System.Text;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 版本信息统一出口（P：版本号显示与日志）。
    ///
    /// 【它把两件事合在一处】
    ///   ① 应用版本 —— Player Settings → Version（打包时写进 APK 的 versionName），
    ///      读 <see cref="Application.version"/>，与 SplashView 既有逻辑同一口径。
    ///   ② 资源版本 —— YooAsset 激活清单的版本号（热更后自动变化），
    ///      经 <see cref="IHotUpdateLoader.CurrentResourceVersion"/> 读取；
    ///      编辑器直读 / 纯 AB 链路没有远端概念，返回 null（显示时自动省略）。
    ///
    /// 【谁用它】
    ///   · Launcher：启动时打印当前版本号日志（BuildLogSummary）。
    ///   · MainMenuView：主菜单底部中间版本行（BuildDisplayVersion）。
    ///   · YooAssetResLoader：检查更新 / 更新完成的前后版本日志。
    ///
    /// 【为什么显示格式用 "r" 而不是中文"资源"】版本行是技术信息，
    /// 走多语言要处理取词时序（主菜单打开前 LanguageManager 才初始化），
    /// 而 "v1.0.0 · r2026101501" 这种格式对任何语言玩家都无歧义，刻意保持中立。
    /// </summary>
    public static class VersionInfo
    {
        /// <summary>
        /// 应用版本（Player Settings → Version）。可能为空（工程没填），
        /// 调用方必须容忍空串 —— 显示层直接省略，日志层写 "(未设置)"。
        /// </summary>
        public static string AppVersion
        {
            get { return Application.version ?? string.Empty; }
        }

        /// <summary>
        /// 当前**已激活**的资源清单版本（YooAsset Init 成功后才有值；
        /// 热更完成后会变成远端最新版本）。拿不到时返回 null。
        ///
        /// 【为什么不直接引用 YooAssetResLoader】ResLoader.HotUpdate 按编译宏
        /// 自动选实现，本类与 UI 一样只认接口，不感知具体资源系统。
        /// </summary>
        public static string ResourceVersion
        {
            get
            {
                IHotUpdateLoader hot = ResLoader.HotUpdate;
                if (hot == null)
                {
                    return null;
                }
                try
                {
                    return hot.CurrentResourceVersion;
                }
                catch (System.Exception)
                {
                    // GetPackageVersion 在清单未激活等状态下可能抛异常 ——
                    // 版本号属于"锦上添花"的信息，绝不因为取版本把启动/界面搞挂。
                    return null;
                }
            }
        }

        /// <summary>
        /// 主菜单底部版本行的显示文案：
        ///   有应用版本且有资源版本 → <c>v1.0.0 · r2026101501</c>
        ///   只有应用版本           → <c>v1.0.0</c>
        ///   两者都没有             → 空串（节点隐藏文字，不占视觉）
        /// </summary>
        public static string BuildDisplayVersion()
        {
            string app = AppVersion;
            string res = ResourceVersion;

            StringBuilder sb = new StringBuilder(64);
            if (!string.IsNullOrEmpty(app))
            {
                sb.Append('v').Append(app);
            }
            if (!string.IsNullOrEmpty(res))
            {
                if (sb.Length > 0)
                {
                    sb.Append(" · ");
                }
                sb.Append('r').Append(res);
            }
            return sb.ToString();
        }

        /// <summary>
        /// 启动日志用的完整版本摘要（一行，方便adb logcat / Editor Console 过滤）。
        /// 示例：<c>[Version] 应用版本=1.0.0 | 资源版本=2026101501 | 资源实现=YooAssetResLoader</c>
        /// </summary>
        public static string BuildLogSummary()
        {
            string app = AppVersion;
            string res = ResourceVersion;
            return string.Format(
                "[Version] 应用版本={0} | 资源版本={1} | 资源实现={2}",
                string.IsNullOrEmpty(app) ? "(未设置)" : app,
                string.IsNullOrEmpty(res) ? "(未激活)" : res,
                ResLoader.ImplName);
        }
    }
}

