        /// <summary>
        /// 异步加载全部配置表。回调参数为 true 表示全部加载成功。
        /// 可重复调用（已加载则直接回调）。
        /// </summary>
        public static void LoadAsync(Action<bool> onDone)
        {
            LoadAsync(null, onDone);
        }

        /// <summary>
        /// 异步加载全部配置表（带阶段进度，UI 补全 A2）。
        /// <paramref name="onStep"/> 参数为 (已完成表数, 总表数)——按"已就绪 tables / 总 tables"报，
        /// 而不是编一个假的百分比：9 张表的解析是分次同步完成的，只有"几张完了"是真实信息。
        /// </summary>
        public static void LoadAsync(Action<int, int> onStep, Action<bool> onDone)
        {
            // 【2026-10-19】早退条件从「IsLoaded」收紧为「加载成功过」。
            // 原实现里失败也会置 IsLoaded=true（表全是 null、FailedTables 非空），
            // 之后任何一次 LoadAsync 都会直接回调 true —— 上层想重试也重试不了，
            // 还会拿到"假成功"。现在只有全表成功才走短路；失败后再调用会重走完整加载。
            if (IsLoaded && FailedTables.Count == 0)
            {
                if (onStep != null)
                {
                    onStep(ConfigKeys.Length, ConfigKeys.Length);
                }
                if (onDone != null)
                {
                    onDone(true);
                }
                return;
            }

            // The config service owns one preload reference for its entire lifetime.
            // Failed parses retry the same assets without acquiring extra bundle references.
            Action loadTables = () =>
            {
                    FailedTables.Clear();
                    LoadedJson.Clear();

                EnemyTable = LoadTable("tbenemydata", n => new TBEnemyData(n));
                TowerTable = LoadTable("tbtowerinfo", n => new TBTowerInfo(n));
                BulletTable = LoadTable("tbbulletdata", n => new TBBulletData(n));
                WaveTable = LoadTable("tbenemylist", n => new TBEnemyList(n));
                RoundTable = LoadTable("tbrounddata", n => new TBRoundData(n));
                LevelTable = LoadTable("tbsceneinfo", n => new TBSceneInfo(n));
                LevelMapTable = LoadTable("tblevelmap", n => new TBLevelMap(n));
                GlobalTable = LoadTable("tbglobal", n => new TBGlobal(n));
                AudioTable = LoadTable("tbaudio", n => new TBAudio(n));
                LocalizationTable = LoadTable("tblocalization", n => new TBLocalization(n));
                RatingTable = LoadTable("tblevelrating", n => new TBLevelRating(n));
                _audioByLogicalName = null;   // 换了一份表数据 → 索引缓存必须作废

                // Global 是单行表，单独取
                if (GlobalTable != null)
                {
                    Global g = GlobalTable.GetOrDefault(1);
                    if (g == null && GlobalTable.DataList != null && GlobalTable.DataList.Count > 0)
                    {
                        g = GlobalTable.DataList[0];
                    }
                    if (g != null)
                    {
                        Global = new GlobalConfig(g);
                    }
                    else
                    {
                        Debug.LogError("[Config] TBGlobal 表为空，全局参数将全部使用代码内置默认值");
                        FailedTables.Add("tbglobal(空表)");
                    }
                }
                else
                {
                    FailedTables.Add("tbglobal");
                }

                bool ok = FailedTables.Count == 0;
                RatingContentVerified = ok && VerifyRatingContent();
                if (!RatingContentVerified) { FailedTables.Add("tblevelrating(content hash mismatch)"); ok = false; }
                IsLoaded = FailedTables.Count == 0;

                LogSummary(ok);
                if (ok)
                {
                    ValidateCrossReferences();
                    ApplyGlobalSettings();
                }

                if (onDone != null)
                {
                    onDone(ok);
                }
            };
            if (_preloadHeld) { loadTables(); return; }
            _preloadHeld = true;
            ResLoader.Instance.Preload(ConfigKeys,
                progress => onStep?.Invoke(Mathf.Clamp(Mathf.RoundToInt(progress * ConfigKeys.Length), 0, ConfigKeys.Length), ConfigKeys.Length),
                loadTables);
        }

        /// <summary>读取并解析单张表；失败返回 null 并记录</summary>
        private static T LoadTable<T>(string key, Func<JSONNode, T> ctor) where T : class
        {
            TextAsset ta = ResLoader.Instance.Load<TextAsset>(key);
            if (ta == null)
            {
                Debug.LogError(string.Format("[Config] 读取失败：{0}.json（详见上一条资源错误）", key));
                FailedTables.Add(key);
                return null;
            }
            if (string.IsNullOrEmpty(ta.text))
            {
                Debug.LogError(string.Format("[Config] {0}.json 内容为空", key));
                FailedTables.Add(key + "(空)");
                return null;
            }
            try
            {
                JSONNode node = JSONNode.Parse(ta.text);
                LoadedJson[key] = ta.text;
                T table = ctor(node);
                if (table == null)
                {
                    FailedTables.Add(key + "(构造返回 null)");
                }
                return table;
            }
            catch (Exception ex)
            {
                Debug.LogError(string.Format("[Config] {0}.json 解析异常：{1}\n{2}", key, ex.Message, ex.StackTrace));
                FailedTables.Add(key + "(解析异常)");
                return null;
            }
        }

