                "  TBSceneInfo  : {6} 条\n" +
                "  TBLevelMap   : {7} 条\n" +
                "  TBGlobal     : {8} 条\n" +
                "  TBAudio      : {9} 条\n" +
                "  TBLocalization: {10} 条",
                ok ? "完成" : "完成（有失败项）",
                Count(EnemyTable), Count(TowerTable), Count(BulletTable), Count(WaveTable),
                Count(RoundTable), Count(LevelTable), Count(LevelMapTable), Count(GlobalTable),
                Count(AudioTable), Count(LocalizationTable));

