using System;
using System.Security.Cryptography;
using System.Text;

namespace FTProject
{
    /// <summary>
    /// 字段级加解密服务。
    ///
    /// 【设计目标】把"加密"这件事收敛到一个可替换的接口后面，
    ///   让仓储层只关心"这个字段是敏感的 → 交给 ICryptoService"，
    ///   而不需要知道用的是什么算法、密钥从哪来。
    ///   将来换成国密 SM4 或服务端下发的密钥，只替换实现即可。
    ///
    /// 【幂等约定（很重要）】<see cref="Decrypt"/> 对"没有加密标记"的输入**原样返回**。
    ///   这样带来两个好处：
    ///     1. 老版本明文存档可以直接被读到（自动兼容旧数据）；
    ///     2. 同一列可以同时存在明文与密文（加密策略是逐字段开关的），
    ///        不需要为"该列是否已加密"再做一次全表迁移。
    /// </summary>
    public interface ICryptoService
    {
        /// <summary>
        /// 服务是否真的可用（密钥是否正确加载 / 平台是否支持所需算法）。
        /// 为 false 时 <see cref="Encrypt"/> 会原样返回明文 —— 属于降级而非崩溃，
        /// 但上层应当在初始化时把这条信息打出来，避免"以为加密了其实没有"。
        /// </summary>
        bool IsAvailable { get; }

        /// <summary>加密。null / 空串原样返回；已加密的输入不会二次加密。</summary>
        string Encrypt(string plainText);

        /// <summary>解密。未加密的输入原样返回；密文损坏时抛 <see cref="CryptoServiceException"/>。</summary>
        string Decrypt(string cipherText);

        /// <summary>该值是否是本服务产出的密文（用于自检与迁移工具）。</summary>
        bool IsEncrypted(string value);
    }

    /// <summary>密文损坏 / 被篡改 / 版本不认识时抛出。</summary>
    public class CryptoServiceException : Exception
    {
        public CryptoServiceException(string message) : base(message) { }
        public CryptoServiceException(string message, Exception inner) : base(message, inner) { }
    }

    /// <summary>
    /// AES-256-CBC 加密 + HMAC-SHA256 认证实现（Encrypt-then-MAC）。
    ///
    /// ==================================================================
    /// 【为什么不直接用 AES-GCM】
    ///   GCM 更现代，但 `AesGcm` 在 Unity 的 Mono / 部分 IL2CPP 平台上是
    ///   PlatformNotSupportedException 的重灾区。CBC + 独立 HMAC 是**到处都能跑**
    ///   的方案，安全性等价（前提是"先加密后验签"，本实现严格遵循）。
    ///
    /// 【密文封装格式】（定长头 + 变长体，整体再做 Base64 存进 TEXT 列）
    ///   ┌──────┬──────────┬──────────┬────────────────────┐
    ///   │ 版本 │  IV(16)  │ MAC(16)  │  密文（CBC/PKCS7）   │
    ///   │ 1B   │          │          │                     │
    ///   └──────┴──────────┴──────────┴────────────────────┘
    ///   外层文本前缀固定为 "ft1:"。
    ///
    ///   · IV **每次加密都随机重新生成**，并随密文一起保存 —— 复用 IV 会让
    ///     相同明文产出相同密文，等于把"玩家的金币是不是 0"这类信息泄漏出去。
    ///   · MAC 覆盖「版本 ‖ IV ‖ 密文」，因此任何一段被改写都会被验签拦下
    ///     （防止有人直接改动存档里的数字）。
    ///
    /// 【两把子密钥】加密密钥与认证密钥**必须不同**（否则存在跨用途攻击面）。
    ///   它们由同一把主密钥经 HMAC 打上不同标签派生得到，见 DeriveSubKeys。
    /// ==================================================================
    /// </summary>
    public sealed class AesCryptoService : ICryptoService
    {
        /// <summary>密文标记。解密时靠它区分"明文存档"与"密文"。</summary>
        public const string Prefix = "ft1:";

        private const byte Version = 1;
        private const int IvSize = 16;
        private const int MacSize = 16;   // SHA-256 截断到 128 位，足够且省空间

        private readonly byte[] _encKey;
        private readonly byte[] _macKey;
        private readonly bool _available;

        /// <summary>主密钥不可用时的降级实例（原样读写）。</summary>
        private AesCryptoService()
        {
            _available = false;
        }

        private AesCryptoService(byte[] masterKey)
        {
            byte[] enc, mac;
            DeriveSubKeys(masterKey, out enc, out mac);
            _encKey = enc;
            _macKey = mac;
            _available = true;
        }

        /// <summary>
        /// 由主密钥构造服务。主密钥为 null / 长度不足时返回降级实例（IsAvailable == false）。
        /// 【为什么不在构造里抛异常】存档服务不应因为"拿不到密钥"就让游戏起不来，
        ///   降级 + 明确告警是更合适的行为。
        /// </summary>
        public static AesCryptoService Create(byte[] masterKey)
        {
            if (masterKey == null || masterKey.Length < 16)
            {
                return new AesCryptoService();
            }
            try
            {
                return new AesCryptoService(masterKey);
            }
            catch (Exception ex)
            {
                UnityEngine.Debug.LogError("[Crypto] 初始化 AES 失败，将退化为明文存储：" + ex.Message);
                return new AesCryptoService();
            }
        }

        public bool IsAvailable { get { return _available; } }

        // ------------------------------------------------------------------
        // 对外：加解密
        // ------------------------------------------------------------------

        public string Encrypt(string plainText)
        {
            if (string.IsNullOrEmpty(plainText))
            {
                return plainText;
            }
            if (!_available)
            {
                return plainText;   // 降级：明文直存
            }
            if (IsEncrypted(plainText))
            {
                return plainText;   // 已经是密文，不二次加密
            }

            byte[] plain = Encoding.UTF8.GetBytes(plainText);
            // 每次加密都用新的随机 IV —— 复用 IV 会让相同明文产出相同密文。
            byte[] iv = new byte[IvSize];
            using (RandomNumberGenerator rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(iv);
            }

            byte[] cipher = AesTransform(true, plain, iv);

            // Encrypt-then-MAC：先有完整密文，再对「版本 ‖ IV ‖ 密文」算 MAC。
            byte[] macInput = Concat(new byte[] { Version }, iv, cipher);
            byte[] mac;
            using (HMACSHA256 h = new HMACSHA256(_macKey))
            {
                mac = h.ComputeHash(macInput);
            }

            byte[] envelope = Concat(new byte[] { Version }, iv, Truncate(mac, MacSize), cipher);
            return Prefix + Convert.ToBase64String(envelope);
        }

        public string Decrypt(string cipherText)
        {
            if (string.IsNullOrEmpty(cipherText))
            {
                return cipherText;
            }
            if (!IsEncrypted(cipherText))
            {
                return cipherText;   // 明文（含旧存档）原样返回
            }
            if (!_available)
            {
                throw new CryptoServiceException("数据是加密的，但当前密钥不可用，无法解密。");
            }

            byte[] envelope;
            try
            {
                envelope = Convert.FromBase64String(cipherText.Substring(Prefix.Length));
            }
            catch (FormatException ex)
            {
                throw new CryptoServiceException("密文 Base64 解码失败（数据可能被截断）", ex);
            }

            if (envelope.Length < 1 + IvSize + MacSize)
            {
                throw new CryptoServiceException("密文长度不足，封装头不完整。");
            }
            if (envelope[0] != Version)
            {
                throw new CryptoServiceException(
                    "密文版本 " + envelope[0] + " 不被当前版本（" + Version + "）支持。");
            }

            byte[] iv = new byte[IvSize];
            byte[] mac = new byte[MacSize];
            byte[] cipher = new byte[envelope.Length - 1 - IvSize - MacSize];
            Array.Copy(envelope, 1, iv, 0, IvSize);
            Array.Copy(envelope, 1 + IvSize, mac, 0, MacSize);
            Array.Copy(envelope, 1 + IvSize + MacSize, cipher, 0, cipher.Length);

            byte[] macInput = Concat(new byte[] { Version }, iv, cipher);
            byte[] expected;
            using (HMACSHA256 h = new HMACSHA256(_macKey))
            {
                expected = h.ComputeHash(macInput);
            }
            // 常量时间比较：普通逐字节比较会提前 return，理论上可从耗时差异里
            // 逐字节猜出正确 MAC（时序攻击）。存档虽小，但这是零成本的正确做法。
            if (!FixedTimeEquals(Truncate(expected, MacSize), mac))
            {
                throw new CryptoServiceException("密文完整性校验失败（MAC 不匹配，数据可能被篡改或密钥已更换）。");
            }

            byte[] plain = AesTransform(false, cipher, iv);
            return Encoding.UTF8.GetString(plain);
        }

        public bool IsEncrypted(string value)
        {
            return !string.IsNullOrEmpty(value) && value.StartsWith(Prefix, StringComparison.Ordinal);
        }

        // ------------------------------------------------------------------
        // 内部：算法与工具
        // ------------------------------------------------------------------

        /// <summary>
        /// 由主密钥派生两把子密钥。
        /// 【为什么用 HMAC 打标签而不是"切一半"】切一半要求主密钥足够长，
        ///   而且两半之间可能存在代数关系；用 HMAC(master, "用途标签") 派生是
        ///   标准的 KDF 做法：只要主密钥是密码学随机的，两把子密钥就互相独立。
        /// </summary>
        private static void DeriveSubKeys(byte[] masterKey, out byte[] encKey, out byte[] macKey)
        {
            encKey = HmacSha256(masterKey, "FT.Persistence/enc/v1");
            macKey = HmacSha256(masterKey, "FT.Persistence/mac/v1");
        }

        private static byte[] HmacSha256(byte[] key, string label)
        {
            using (HMACSHA256 h = new HMACSHA256(key))
            {
                return h.ComputeHash(Encoding.UTF8.GetBytes(label));
            }
        }

        /// <summary>一次性的 AES 变换（CBC + PKCS7 正好适合 TransformFinalBlock 单次调用）。</summary>
        private byte[] AesTransform(bool encrypt, byte[] data, byte[] iv)
        {
            using (Aes aes = Aes.Create())
            {
                aes.KeySize = 256;
                aes.BlockSize = 128;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                aes.Key = _encKey;
                aes.IV = iv;

                using (ICryptoTransform t = encrypt ? aes.CreateEncryptor() : aes.CreateDecryptor())
                {
                    try
                    {
                        return t.TransformFinalBlock(data, 0, data.Length);
                    }
                    catch (CryptographicException ex)
                    {
                        throw new CryptoServiceException("AES 变换失败（密文损坏或密钥不匹配）", ex);
                    }
                }
            }
        }

        private static byte[] Truncate(byte[] src, int len)
        {
            if (src.Length == len)
            {
                return src;
            }
            byte[] dst = new byte[len];
            Array.Copy(src, dst, Math.Min(len, src.Length));
            return dst;
        }

        /// <summary>
        /// 按顺序拼接若干字节数组。
        /// 【为什么用 params 而不是固定 2/3 参重载】信封由「版本 + IV + MAC + 密文」四段拼成，
        /// MAC 的输入只要三段 —— 固定参数就不得不写多个重载，多一处就多一处调错的风险。
        /// </summary>
        private static byte[] Concat(params byte[][] parts)
        {
            int total = 0;
            for (int i = 0; i < parts.Length; i++)
            {
                total += parts[i].Length;
            }
            byte[] r = new byte[total];
            int offset = 0;
            for (int i = 0; i < parts.Length; i++)
            {
                Array.Copy(parts[i], 0, r, offset, parts[i].Length);
                offset += parts[i].Length;
            }
            return r;
        }

        /// <summary>常量时间比较（长度不同直接判否，长度本身不是秘密）。</summary>
        private static bool FixedTimeEquals(byte[] a, byte[] b)
        {
            if (a == null || b == null || a.Length != b.Length)
            {
                return false;
            }
            int diff = 0;
            for (int i = 0; i < a.Length; i++)
            {
                diff |= a[i] ^ b[i];
            }
            return diff == 0;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;

namespace FTProject
{
    /// <summary>
    /// 一行查询结果（列名 → 值）。
    ///
    /// 【为什么不用 DataTable / DataRow】那是 System.Data 的东西，Unity 的
    /// .NET Standard 2.1 剖面里没有 System.Data；而且我们的查询都是小结果集，
    /// 一个"列名 → 值"的轻量容器足够了。
    ///
    /// 【取值一律不抛异常】列名写错、类型对不上、值为 NULL —— 都返回调用方给的默认值。
    /// 读档路径上抛异常等于"玩家进不去游戏"，这个代价太大；真正的错误由
    /// 建表/迁移阶段的严格校验去拦（见 SaveSchema）。
    /// </summary>
    public sealed class DbRow
    {
        private readonly string[] _names;
        private readonly object[] _values;
        private readonly Dictionary<string, int> _index;

        public DbRow(string[] names, object[] values)
        {
            _names = names != null ? names : new string[0];
            _values = values != null ? values : new object[0];
            // 列名大小写不敏感：SQLite 的列名比对就是大小写不敏感的，
            // 这里保持一致，避免 `SELECT Stars ...` 之后用 row.GetInt("stars") 取不到。
            _index = new Dictionary<string, int>(_names.Length, StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < _names.Length; i++)
            {
                string n = _names[i];
                if (!string.IsNullOrEmpty(n) && !_index.ContainsKey(n))
                {
                    _index.Add(n, i);
                }
            }
        }

        public int ColumnCount { get { return _names.Length; } }

        public string GetColumnName(int i)
        {
            return (i >= 0 && i < _names.Length) ? _names[i] : null;
        }

        public bool HasColumn(string column)
        {
            return !string.IsNullOrEmpty(column) && _index.ContainsKey(column);
        }

        public bool IsNull(string column)
        {
            object v = GetRaw(column);
            return v == null || v is DBNull;
        }

        /// <summary>取原始值（string / long / double / byte[] / null）。</summary>
        public object GetRaw(string column)
        {
            int i;
            if (string.IsNullOrEmpty(column) || !_index.TryGetValue(column, out i))
            {
                return null;
            }
            return _values[i];
        }

        public string GetString(string column, string defaultValue)
        {
            object v = GetRaw(column);
            if (v == null || v is DBNull)
            {
                return defaultValue;
            }
            string s = v as string;
            if (s != null)
            {
                return s;
            }
            byte[] b = v as byte[];
            if (b != null)
            {
                return System.Text.Encoding.UTF8.GetString(b);
            }
            return Convert.ToString(v, CultureInfo.InvariantCulture);
        }

        public string GetString(string column)
        {
            return GetString(column, null);
        }

        public long GetLong(string column, long defaultValue)
        {
            object v = GetRaw(column);
            if (v == null || v is DBNull)
            {
                return defaultValue;
            }
            if (v is long)
            {
                return (long)v;
            }
            if (v is int)
            {
                return (int)v;
            }
            if (v is double)
            {
                return (long)(double)v;
            }
            long r;
            // 【为什么要走不变文化】`"1.0"` 在德/法语区会被解析成 1，
            // 但 `"1,5"` 这类字符串若按本地文化解析会得到 15 —— 存档必须与语言环境无关。
            return long.TryParse(GetString(column), NumberStyles.Integer, CultureInfo.InvariantCulture, out r)
                ? r : defaultValue;
        }

        public long GetLong(string column)
        {
            return GetLong(column, 0L);
        }

        public int GetInt(string column, int defaultValue)
        {
            return (int)GetLong(column, defaultValue);
        }

        public int GetInt(string column)
        {
            return (int)GetLong(column, 0L);
        }

        public bool GetBool(string column, bool defaultValue)
        {
            long v = GetLong(column, defaultValue ? 1L : 0L);
            return v != 0;
        }

        public bool GetBool(string column)
        {
            return GetBool(column, false);
        }

        public double GetDouble(string column, double defaultValue)
        {
            object v = GetRaw(column);
            if (v == null || v is DBNull)
            {
                return defaultValue;
            }
            if (v is double)
            {
                return (double)v;
            }
            if (v is long)
            {
                return (long)v;
            }
            double r;
            return double.TryParse(GetString(column), NumberStyles.Float, CultureInfo.InvariantCulture, out r)
                ? r : defaultValue;
        }

        public double GetDouble(string column)
        {
            return GetDouble(column, 0d);
        }

        public float GetFloat(string column, float defaultValue)
        {
            return (float)GetDouble(column, defaultValue);
        }

        public float GetFloat(string column)
        {
            return (float)GetDouble(column, 0d);
        }

        public byte[] GetBlob(string column)
        {
            object v = GetRaw(column);
            if (v == null || v is DBNull)
            {
                return null;
            }
            return v as byte[];
        }
    }
}

using System;
using System.Collections.Generic;

namespace FTProject
{
    /// <summary>
    /// 数据库访问层的统一抽象。
    ///
    /// 【为什么要抽这一层】SQLite 只是"当前选定的后端"，不是架构本身。
    ///   业务/存储层只依赖本接口，所以：
    ///     · 换后端（写死 JSON、内置 KV、服务端同步）不需要动上层代码；
    ///     · 单测里可以塞一个内存假实现，不需要真的落盘。
    ///
    /// 【约定】
    ///   · SQL 一律使用 **参数化占位符**（`?1` / `?2`），禁止字符串拼接 ——
    ///     拼接既是被注入的入口，也会因为中文/引号转义问题直接把语句写坏。
    ///   · 所有方法遇到错误都抛 <see cref="DatabaseException"/>，调用方要么接住降级，
    ///     要么让它上抛；**不允许静默失败**（否则存档"看起来写了"其实没写）。
    /// </summary>
    public interface IDatabase : IDisposable
    {
        /// <summary>连接是否可用</summary>
        bool IsOpen { get; }

        /// <summary>后端标识（日志与自检用），例如 "SQLite 3.43.2" / "JSON"</summary>
        string BackendName { get; }

        /// <summary>数据库文件路径（JSON 回退后端下为 JSON 文件路径）</summary>
        string DatabasePath { get; }

        /// <summary>执行一条写语句（INSERT/UPDATE/DELETE/DDL），返回受影响行数。参数按 ?1、?2… 顺序绑定。</summary>
        int Execute(string sql, params object[] args);

        /// <summary>
        /// 执行一条 INSERT 并返回自增主键（`last_insert_rowid`）。
        /// 与 Execute 分开是为了避免"到处都要再查一次 max(id)"这种既慢又容易错的写法。
        /// </summary>
        long ExecuteInsert(string sql, params object[] args);

        /// <summary>执行查询，返回全部行。结果集不可为空集合（无行时返回空 List，不返回 null）。</summary>
        List<DbRow> Query(string sql, params object[] args);

        /// <summary>查询单行；无结果返回 null。</summary>
        DbRow QuerySingle(string sql, params object[] args);

        /// <summary>
        /// 查询单值。无结果或值为 NULL 时返回 <paramref name="defaultValue"/>。
        /// 内部转成 string 后按不变文化解析，因此 int / long / double / bool 都能用。
        /// </summary>
        T QueryScalar<T>(string sql, T defaultValue, params object[] args);

        /// <summary>
        /// 开启事务。**必须 Dispose**：未 Commit 就 Dispose 会视为 Rollback。
        /// 支持嵌套调用（内层复用外层事务，只有最外层提交/回滚）。
        /// </summary>
        IDbTransaction BeginTransaction();

        /// <summary>把缓冲区落盘（SQLite 下执行 WAL checkpoint）。无缓冲的后端是空实现。</summary>
        void Flush();
    }

    /// <summary>事务句柄。语义见 <see cref="IDatabase.BeginTransaction"/>。</summary>
    public interface IDbTransaction : IDisposable
    {
        /// <summary>提交。可重复调用，只有第一次生效。</summary>
        void Commit();

        /// <summary>回滚。可重复调用，只有第一次生效。</summary>
        void Rollback();

        /// <summary>是否已结束（提交或回滚过）</summary>
        bool IsFinished { get; }
    }

    /// <summary>
    /// 数据层统一异常。
    /// 【为什么不直接抛 SQLite 的返回码】返回码是 int，很容易被无声忽略；
    /// 抛出带语句与错误信息的异常，排查时能直接定位到是哪条 SQL 出了问题。
    /// </summary>
    public class DatabaseException : Exception
    {
        /// <summary>触发出错的 SQL（已截断到 200 字符，避免日志被超长语句刷屏）</summary>
        public string Sql { get; private set; }

        /// <summary>后端原始错误码（SQLite 的 result code）；非 SQLite 后端为 0</summary>
        public int ResultCode { get; private set; }

        public DatabaseException(string message, string sql, int resultCode)
            : base(message)
        {
            Sql = Truncate(sql);
            ResultCode = resultCode;
        }

        public DatabaseException(string message, string sql, int resultCode, Exception inner)
            : base(message, inner)
        {
            Sql = Truncate(sql);
            ResultCode = resultCode;
        }

        private static string Truncate(string sql)
        {
            if (string.IsNullOrEmpty(sql))
            {
                return string.Empty;
            }
            string one = sql.Replace('\n', ' ').Replace('\r', ' ').Trim();
            return one.Length <= 200 ? one : one.Substring(0, 200) + "...";
        }

        public override string ToString()
        {
            return Message + (string.IsNullOrEmpty(Sql) ? string.Empty : "\n  SQL: " + Sql);
        }
    }
}

using System;
using System.Collections.Generic;

namespace FTProject
{
    /// <summary>
    /// 存档存储的**语义化**接口 —— 这是业务层（SaveManager）唯一认识的数据层契约。
    ///
    /// ==================================================================
    /// 【为什么要这一层，而不是让 SaveManager 直接写 SQL】
    ///   如果 SaveManager 里出现 `INSERT INTO level_progress ...`，那么：
    ///     · 表结构一改，业务代码必须跟着改；
    ///     · 想做"存档后端可切换"（SQLite / 云同步 / 内存）就无从下手；
    ///     · "加密哪些字段"这个决策会散落在业务逻辑里。
    ///   所以这一层负责"把业务概念映射成存储动作"，业务层只表达意图：
    ///   "保存这一关的进度" —— 至于落到哪张表、哪些列加密，这里说了算。
    ///
    /// 【异常策略】
    ///   读：**不抛异常**，缺数据就返回默认值（空档），读坏了按"这一项没有"处理。
    ///   写：**不抛异常**，失败只记日志。理由与项目原有的 SaveManager 一致 ——
    ///       存档写失败不该让玩家中断游戏；真正的错误在日志里可查。
    ///   <see cref="Initialize"/> 是例外：它会抛 <see cref="DatabaseException"/>，
    ///   好让上层有机会降级到备用后端（创建失败必须当场知道）。
    /// ==================================================================
    /// </summary>
    public interface ISaveStorage : IDisposable
    {
        /// <summary>后端标识，例如 "SQLite 3.43.2" / "JSON 文件"。日志与自检用。</summary>
        string BackendName { get; }

        /// <summary>数据落盘位置（数据库文件路径 / JSON 文件路径）。</summary>
        string Location { get; }

        /// <summary>是否已成功初始化</summary>
        bool IsReady { get; }

        /// <summary>敏感字段是否真的在加密（密钥不可用时会退化为明文）。</summary>
        bool IsEncrypted { get; }

        /// <summary>最近一次错误（null 表示无）。</summary>
        string LastError { get; }

        /// <summary>创建/校验表结构、准备后端。失败抛 <see cref="DatabaseException"/>。</summary>
        void Initialize();

        // ---- 会话设置 ----------------------------------------------------

        GameSettings LoadSettings();
        void SaveSettings(GameSettings settings);

        // ---- 关卡进度 ----------------------------------------------------

        List<LevelProgress> LoadLevels();
        void SaveLevel(LevelProgress progress);
        void DeleteLevel(int levelId);

        // ---- 局内快照 ----------------------------------------------------

        LevelSnapshot LoadSnapshot();
        void SaveSnapshot(LevelSnapshot snapshot);
        /// <summary>Commit a run and invalidate its checkpoint in one durable unit.</summary>
        bool CommitClear(LevelProgress progress);

        // ---- 通用键值（设置项 / 其它零散数据）-----------------------------

        /// <summary>读一个键值（自动解密）。不存在返回 false。</summary>
        bool TryGetValue(string key, out string value);

        /// <summary>写一个键值。<paramref name="sensitive"/> 决定该值是否加密后落库。</summary>
        void SetValue(string key, string value, bool sensitive);

        void DeleteValue(string key);

        // ---- 维护 --------------------------------------------------------

        /// <summary>清空全部业务数据（保留表结构）。设置界面的"重置存档"走这里。</summary>
        void ResetAll();

        /// <summary>把缓冲区刷到磁盘。</summary>
        void Flush();
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace FTProject
{
    /// <summary>键值文件里的一条记录（JsonUtility 要求 [Serializable] + public 字段）。</summary>
    [Serializable]
    public class KvEntry
    {
        public string k;
        public string v;
        public bool sensitive;
    }

    /// <summary>键值文件的根对象。</summary>
    [Serializable]
    public class KvFile
    {
        public List<KvEntry> items = new List<KvEntry>();
    }

    /// <summary>
    /// <see cref="ISaveStorage"/> 的纯托管回退实现：整体 JSON 落盘（内容再整体 AES 加密）。
    ///
    /// ==================================================================
    /// 【它为什么必须存在】
    ///   原生 SQLite 库在个别环境里可能缺失（换平台没带库、精简版系统等）。
    ///   没有回退实现的话，那种情况下玩家连设置都存不了 —— 而这类失败是**环境问题**，
    ///   不该由一个游戏功能来承担。所以架构上把"后端"做成可替换的，
    ///   SQLite 打不开就自动退到这里，功能不减、只是查询能力弱一些。
    ///
    /// 【顺带承担旧存档迁移】
    ///   文件路径与旧版本 SaveManager 使用的 `freetower_save.json` **完全一致**，
    ///   且读取时先尝试解密、不是密文就按明文 JSON 解析 —— 于是老玩家的存档
    ///   可以无缝读入，不需要任何手工迁移步骤。
    /// ==================================================================
    /// </summary>
    internal sealed class JsonSaveStorage : ISaveStorage
    {
        private const string SaveFileName = "freetower_save.json";
        private const string KvFileName = "freetower_kv.json";

        private readonly ICryptoService _crypto;
        private readonly string _directory;
        private SaveData _data;
        private KvFile _kv;
        private bool _initialized;
        private bool _futureFormatReadOnly;

        internal JsonSaveStorage(ICryptoService crypto, string directory = null)
        {
            _crypto = crypto;
            _directory = directory ?? Application.persistentDataPath;
            Directory.CreateDirectory(_directory);
        }

        public string BackendName { get { return "JSON 文件（SQLite 回退）"; } }

        public string Location
        {
            get { return Path.Combine(_directory, SaveFileName); }
        }

        private string KvPath
        {
            get { return Path.Combine(_directory, KvFileName); }
        }

        public bool IsReady { get { return _initialized; } }

        public bool IsEncrypted { get { return _crypto != null && _crypto.IsAvailable; } }

        public string LastError { get; private set; }

        public void Initialize()
        {
            _data = ReadSaveFile();
            _kv = ReadKvFile();
            _initialized = true;
            Debug.Log(string.Format(
                "[Save] 存档后端就绪：{0}\n  位置：{1}\n  内容加密：{2}",
                BackendName, Location, IsEncrypted ? "已启用" : "未启用"));
        }

        // ------------------------------------------------------------------
        // 文件读写
        // ------------------------------------------------------------------

        private SaveData ReadSaveFile()
        {
            string path = Location;
            try
            {
                if (!File.Exists(path))
                {
                    return new SaveData();
                }
                string text = File.ReadAllText(path);
                if (string.IsNullOrEmpty(text))
                {
                    return new SaveData();
                }

                // 先解密。老存档是明文 JSON，Decrypt 会原样返回 → 兼容读入。
                string json = text;
                if (_crypto != null)
                {
                    json = _crypto.Decrypt(text);
                }
                if (string.IsNullOrEmpty(json))
                {
                    return new SaveData();
                }

                SaveData d = JsonUtility.FromJson<SaveData>(json);
                if (d == null)
                {
                    Debug.LogWarning("[Save] 存档解析为 null，按新档处理：" + path);
                    return new SaveData();
                }
                if (d.version > SaveData.CurrentVersion)
                {
                    _futureFormatReadOnly = true;
                    Debug.LogWarning("[Save] Save format is newer than this client; original file is read-only");
                    return new SaveData();
                }
                if (d.version < SaveData.CurrentVersion)
                {
                    string backup = path + ".legacy-v" + d.version + ".bak";
                    if (!File.Exists(backup)) File.Copy(path, backup);
                    // Preserve old scores verbatim; content-version migration is done by SaveManager.
                    d.version = SaveData.CurrentVersion;
                    if (d.snapshot != null && d.snapshot.formatVersion < 2) d.snapshot.valid = false;
                }
                Normalize(d);
                return d;
            }
            catch (Exception ex)
            {
                LastError = "读档失败：" + ex.Message;
                Debug.LogWarning("[Save] " + LastError + "（按新档处理）\n  路径：" + path);
                return new SaveData();
            }
        }

        /// <summary>补齐可能缺失的字段（手改过文件 / 老版本没有该字段）。</summary>
        private static void Normalize(SaveData d)
        {
            if (d.levels == null) d.levels = new List<LevelProgress>();
            if (d.settings == null) d.settings = new GameSettings();
            if (d.snapshot == null) d.snapshot = new LevelSnapshot();
            if (d.snapshot.towers == null) d.snapshot.towers = new List<TowerSnapshot>();
            d.settings.Clamp();
            foreach (LevelProgress p in d.levels)
            {
                if (p == null) continue;
                p.stars = Mathf.Clamp(p.stars, 0, LevelRatingEvaluator.MaxStars);
                if (p.legacy == null) p.legacy = new List<LegacyLevelProgress>();
                if (p.committedRunIds == null) p.committedRunIds = new List<string>();
            }
        }

        private bool WriteSaveFile(SaveData candidate = null)
        {
            if (_futureFormatReadOnly) { LastError = "Future-format save is read-only"; Debug.LogWarning("[Save] " + LastError); return false; }
            try
            {
                string json = JsonUtility.ToJson(candidate ?? _data, true);
                string payload = _crypto != null ? _crypto.Encrypt(json) : json;
                // 同样用"临时文件 + 替换"，避免写一半崩溃留下半截存档。
                string path = Location;
                string tmp = path + ".tmp";
                File.WriteAllText(tmp, payload);
                if (File.Exists(path))
                {
                    File.Replace(tmp, path, path + ".previous.bak");
                }
                else File.Move(tmp, path);
                return true;
            }
            catch (Exception ex)
            {
                LastError = "写档失败：" + ex.Message;
                Debug.LogWarning("[Save] " + LastError + "\n  路径：" + Location);
                return false;
            }
        }

        private KvFile ReadKvFile()
        {
            try
            {
                string path = KvPath;
                if (!File.Exists(path))
                {
                    return new KvFile();
                }
                string text = File.ReadAllText(path);
                if (string.IsNullOrEmpty(text))
                {
                    return new KvFile();
                }
                string json = _crypto != null ? _crypto.Decrypt(text) : text;
                KvFile f = JsonUtility.FromJson<KvFile>(json);
                if (f == null)
                {
                    return new KvFile();
                }
                if (f.items == null)
                {
                    f.items = new List<KvEntry>();
                }
                return f;
            }
            catch (Exception ex)
            {
                LastError = "读取键值文件失败：" + ex.Message;
                Debug.LogWarning("[Save] " + LastError + "（按空处理）");
                return new KvFile();
            }
        }

        private bool WriteKvFile(KvFile candidate)
        {
            try
            {
                string json = JsonUtility.ToJson(candidate, true);
                string payload = _crypto != null ? _crypto.Encrypt(json) : json;
                string tmp = KvPath + ".tmp";
                File.WriteAllText(tmp, payload);
                if (File.Exists(KvPath)) File.Replace(tmp, KvPath, KvPath + ".previous.bak"); else File.Move(tmp, KvPath);
                return true;
            }
            catch (Exception ex)
            {
                LastError = "写入键值文件失败：" + ex.Message;
                Debug.LogWarning("[Save] " + LastError);
                return false;
            }
        }

        private KvEntry FindKv(string key)
        {
            if (_kv == null || _kv.items == null)
            {
                return null;
            }
            for (int i = 0; i < _kv.items.Count; i++)
            {
                KvEntry e = _kv.items[i];
                if (e != null && e.k == key)
                {
                    return e;
                }
            }
            return null;
        }

        // ------------------------------------------------------------------
        // ISaveStorage
        // ------------------------------------------------------------------

        public GameSettings LoadSettings()
        {
            return _data != null ? Clone(_data.settings) : new GameSettings();
        }

        public void SaveSettings(GameSettings settings)
        {
            if (settings == null)
            {
                return;
            }
            settings.Clamp();
            SaveData candidate = Clone(_data);
            candidate.settings = Clone(settings);
            if (WriteSaveFile(candidate)) _data = candidate;
        }

        public List<LevelProgress> LoadLevels()
        {
            return _data != null ? Clone(_data).levels : new List<LevelProgress>();
        }

        public void SaveLevel(LevelProgress progress)
        {
            if (progress == null || progress.levelId <= 0)
            {
                return;
            }
            SaveData candidate = Clone(_data);
            int index = candidate.levels.FindIndex(p => p != null && p.levelId == progress.levelId);
            LevelProgress copy = Clone(progress);
            copy.stars = Mathf.Clamp(copy.stars, 0, LevelRatingEvaluator.MaxStars);
            if (index < 0) candidate.levels.Add(copy); else candidate.levels[index] = copy;
            if (WriteSaveFile(candidate)) _data = candidate;
        }

        public void DeleteLevel(int levelId)
        {
            SaveData candidate = Clone(_data);
            LevelProgress p = candidate.Find(levelId);
            if (p != null)
            {
                candidate.levels.Remove(p);
                if (WriteSaveFile(candidate)) _data = candidate;
            }
        }

        public LevelSnapshot LoadSnapshot()
        {
            LastError = null;
            return _data != null ? Clone(_data.snapshot) : new LevelSnapshot();
        }
        public bool CommitClear(LevelProgress progress)
        {
            if (progress == null) return false;
            SaveData candidate = Clone(_data);
            int index = candidate.levels.FindIndex(p => p != null && p.levelId == progress.levelId);
            var copy = Clone(progress);
            if (index < 0) candidate.levels.Add(copy); else candidate.levels[index] = copy;
            candidate.snapshot = new LevelSnapshot();
            if (!WriteSaveFile(candidate)) return false;
            _data = candidate;
            return true;
        }

        public void SaveSnapshot(LevelSnapshot snapshot)
        {
            LastError = null;
            SaveData candidate = Clone(_data);
            candidate.snapshot = snapshot != null ? Clone(snapshot) : new LevelSnapshot();
            if (WriteSaveFile(candidate)) _data = candidate;
        }
        private static T Clone<T>(T value) where T : class
        {
            return value == null ? null : JsonUtility.FromJson<T>(JsonUtility.ToJson(value));
        }

        public bool TryGetValue(string key, out string value)
        {
            value = null;
            KvEntry e = FindKv(key);
            if (e == null)
            {
                return false;
            }
            if (e.sensitive && _crypto != null)
            {
                try
                {
                    value = _crypto.Decrypt(e.v);
                }
                catch (Exception ex)
                {
                    LastError = "解密键值失败：" + ex.Message;
                    Debug.LogWarning("[Save] " + LastError);
                    value = null;
                }
            }
            else
            {
                value = e.v;
            }
            return value != null;
        }

        public void SetValue(string key, string value, bool sensitive)
        {
            if (string.IsNullOrEmpty(key))
            {
                return;
            }
            string stored = (sensitive && _crypto != null) ? _crypto.Encrypt(value) : value;
            KvFile candidate = Clone(_kv);
            KvEntry e = candidate.items.Find(x => x != null && x.k == key);
            if (e == null)
            {
                e = new KvEntry();
                e.k = key;
                candidate.items.Add(e);
            }
            e.v = stored;
            e.sensitive = sensitive;
            if (WriteKvFile(candidate)) _kv = candidate;
        }

        public void DeleteValue(string key)
        {
            KvFile candidate = Clone(_kv);
            KvEntry e = candidate.items.Find(x => x != null && x.k == key);
            if (e != null)
            {
                candidate.items.Remove(e);
                if (WriteKvFile(candidate)) _kv = candidate;
            }
        }

        public void ResetAll()
        {
            _data = new SaveData();
            _kv = new KvFile();
            _futureFormatReadOnly = false;
            try
            {
                if (File.Exists(Location)) File.Delete(Location);
                if (File.Exists(KvPath)) File.Delete(KvPath);
            }
            catch (Exception ex)
            {
                LastError = "删除存档文件失败：" + ex.Message;
                Debug.LogWarning("[Save] " + LastError);
            }
            Debug.Log("[Save] 存档已清空（JSON 后端）");
        }

        public void Flush()
        {
            // JSON 后端每次写入即落盘，没有缓冲需要刷。
        }

        public void Dispose()
        {
            _initialized = false;
        }
    }
}

using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;

namespace FTProject
{
    /// <summary>主密钥来源。抽成接口是为了将来换成"服务端下发 / 平台 Keychain"实现。</summary>
    public interface IKeyProvider
    {
        /// <summary>取 32 字节主密钥。失败返回 false（上层据此降级为明文存储）。</summary>
        bool TryGetMasterKey(out byte[] masterKey);

        /// <summary>密钥是否是本次启动时"重新生成"的（意味着旧密文已无法解密，需要作废旧数据）。</summary>
        bool KeyWasRotated { get; }

        /// <summary>最近一次失败原因（用于日志）。null 表示无错误。</summary>
        string LastError { get; }
    }

    /// <summary>
    /// 本机密钥管理：**代码里没有任何密钥常量**，主密钥在首次运行时随机生成，
    /// 并**拆成两半分处存放**。
    ///
    /// ==================================================================
    /// 【为什么拆成两半】
    ///   单点存放的问题很直白：只要拿到那一个文件（或那一处偏好设置），密钥就到手了。
    ///   拆开后，攻击者必须**同时**取得两处：
    ///     · 分片 A（16 字节）：`{persistentDataPath}/ft_keystore.bin`，应用私有数据目录；
    ///     · 分片 B（16 字节）：PlayerPrefs（Windows 为当前用户注册表 / iOS 为 NSUserDefaults
    ///       / Android 为 SharedPreferences），属于**另一个存储系统**，
    ///       备份策略、清理工具、提权路径都不一样。
    ///   两处都拿到才能拼出主密钥 —— 这显著抬高了"只改存档文件"这类作弊的门槛。
    ///
    /// 【主密钥怎么来的】master = HMAC-SHA256(key = "FT.Persistence/master/v1", data = A ‖ B)。
    ///   即把两分片按固定顺序拼起来，再用带标签的 HMAC 做一次 KDF 展开，
    ///   保证输出是 32 字节且与输入分布无关。
    ///
    /// 【一致性校验】文件里除分片 A 外还存了 8 字节校验值 check = HMAC(A, B)[0..8]。
    ///   它解决一个很隐蔽的故障：玩家用备份工具只还原了 `ft_keystore.bin`（A 变回旧的），
    ///   而 PlayerPrefs 里的 B 是新的 —— 此时 A/B 拼接能算出"一把看起来正常"的密钥，
    ///   但解不开任何旧数据，症状是"存档莫名其妙全没了"。
    ///   有 check 就能识别出"两半不是同一代"，直接走轮换流程并给出明确日志。
    ///
    /// 【威胁模型（必须说清楚）】
    ///   这是**客户端本地加密**，能防的是：直接改存档文件、翻看明文、简单内存/文件篡改。
    ///   防不了的是：具有 root/越权能力、能 dump 进程内存或 hook 运行时的攻击者 ——
    ///   密钥最终必须在客户端参与运算，这是本地加密的固有上限。
    ///   需要真正抗作弊时，应把**关键数值的权威判定放到服务端**，本地加密只当第一道门槛。
    /// ==================================================================
    /// </summary>
    public sealed class LocalKeyProvider : IKeyProvider
    {
        private const string PrefsKey = "FT.KeyShard.B.v1";
        private const string MasterLabel = "FT.Persistence/master/v1";
        private const string CheckLabel = "FT.Persistence/check/v1";
        private const string FileName = "ft_keystore.bin";

        /// <summary>调试用：设置该环境变量（Base64 的 32 字节）可强制指定主密钥，便于自动化测试。</summary>
        private const string EnvOverride = "FT_SAVE_KEY";

        private const int ShardSize = 16;
        private const int CheckSize = 8;

        public bool KeyWasRotated { get; private set; }

        public string LastError { get; private set; }

        /// <summary>密钥文件完整路径（排查问题时打印它最快）</summary>
        public static string KeyFilePath
        {
            get { return Path.Combine(Application.persistentDataPath, FileName); }
        }

        public bool TryGetMasterKey(out byte[] masterKey)
        {
            masterKey = null;

            if (TryEnvOverride(out masterKey))
            {
                return true;
            }

            byte[] shardA;
            byte[] shardB;
            string error = LoadShards(out shardA, out shardB);
            if (error != null)
            {
                LastError = error;
                Debug.LogWarning("[Key] 密钥不可用，重新生成：" + error);
                KeyWasRotated = true;
                if (!CreateShards(out shardA, out shardB))
                {
                    LastError = "生成新密钥失败（磁盘不可写？）";
                    Debug.LogError("[Key] " + LastError + "，本次将退化为明文存储。");
                    return false;
                }
            }

            masterKey = DeriveMaster(shardA, shardB);
            return true;
        }

        // ------------------------------------------------------------------
        // 读取 / 生成
        // ------------------------------------------------------------------

        /// <summary>读取并校验两处分片；任何一步不成立都返回非 null 的错误说明。</summary>
        private string LoadShards(out byte[] shardA, out byte[] shardB)
        {
            shardA = null;
            shardB = null;

            string path = KeyFilePath;
            if (!File.Exists(path))
            {
                return "密钥文件不存在（" + path + "）";
            }

            byte[] fileBytes;
            try
            {
                fileBytes = File.ReadAllBytes(path);
            }
            catch (Exception ex)
            {
                return "读取密钥文件失败：" + ex.Message;
            }

            if (fileBytes.Length != ShardSize + CheckSize)
            {
                return "密钥文件长度异常（" + fileBytes.Length + " 字节，期望 " + (ShardSize + CheckSize) + "）";
            }
            byte[] a = new byte[ShardSize];
            byte[] check = new byte[CheckSize];
            Array.Copy(fileBytes, 0, a, 0, ShardSize);
            Array.Copy(fileBytes, ShardSize, check, 0, CheckSize);

            // 分片 B 存在 PlayerPrefs 里（与文件属于不同存储系统）
            string b64 = null;
            try
            {
                b64 = PlayerPrefs.GetString(PrefsKey, null);
            }
            catch (Exception ex)
            {
                return "读取偏好设置中的密钥分片失败：" + ex.Message;
            }
            if (string.IsNullOrEmpty(b64))
            {
                return "偏好设置中的密钥分片缺失（密钥文件与偏好设置不同步）";
            }

            byte[] b;
            try
            {
                b = Convert.FromBase64String(b64);
            }
            catch (FormatException)
            {
                return "偏好设置中的密钥分片格式非法";
            }
            if (b.Length != ShardSize)
            {
                return "偏好设置中的密钥分片长度异常（" + b.Length + "）";
            }

            // 校验：确认文件里的 A 与偏好设置里的 B 属于同一代
            byte[] expect = Hmac(Concat(a, b), CheckLabel, CheckSize);
            if (!FixedTimeEquals(expect, check))
            {
                return "密钥两半分片不属于同一代（可能只还原了其中一处备份）";
            }

            shardA = a;
            shardB = b;
            return null;
        }

        /// <summary>生成并持久化一对新分片。</summary>
        private bool CreateShards(out byte[] shardA, out byte[] shardB)
        {
            shardA = new byte[ShardSize];
            shardB = new byte[ShardSize];
            using (RandomNumberGenerator rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(shardA);
                rng.GetBytes(shardB);
            }

            byte[] check = Hmac(Concat(shardA, shardB), CheckLabel, CheckSize);
            byte[] fileBytes = Concat(shardA, check);

            try
            {
                // 先写临时文件再原子替换：直接覆写时若中途崩溃，会留下半截文件，
                // 下次启动就变成"密钥损坏"，玩家的存档会整批作废。
                string path = KeyFilePath;
                string tmp = path + ".tmp";
                File.WriteAllBytes(tmp, fileBytes);
                if (File.Exists(path))
                {
                    File.Delete(path);
                }
                File.Move(tmp, path);

                PlayerPrefs.SetString(PrefsKey, Convert.ToBase64String(shardB));
                PlayerPrefs.Save();
                return true;
            }
            catch (Exception ex)
            {
                LastError = "写入密钥失败：" + ex.Message;
                return false;
            }
        }

        private static byte[] DeriveMaster(byte[] shardA, byte[] shardB)
        {
            return Hmac(Concat(shardA, shardB), MasterLabel, 32);
        }

        // ------------------------------------------------------------------
        // 调试覆盖
        // ------------------------------------------------------------------

        private static bool TryEnvOverride(out byte[] masterKey)
        {
            masterKey = null;
            string raw = null;
            try
            {
                raw = Environment.GetEnvironmentVariable(EnvOverride);
            }
            catch (Exception)
            {
                return false;
            }
            if (string.IsNullOrEmpty(raw))
            {
                return false;
            }
            try
            {
                byte[] key = Convert.FromBase64String(raw);
                if (key.Length < 16)
                {
                    Debug.LogWarning("[Key] 环境变量 " + EnvOverride + " 长度不足，已忽略。");
                    return false;
                }
                Debug.LogWarning("[Key] 正在使用环境变量指定的调试密钥（" + EnvOverride + "），请勿用于正式构建。");
                masterKey = key;
                return true;
            }
            catch (FormatException)
            {
                Debug.LogWarning("[Key] 环境变量 " + EnvOverride + " 不是合法 Base64，已忽略。");
                return false;
            }
        }

        // ------------------------------------------------------------------
        // 工具
        // ------------------------------------------------------------------

        private static byte[] Hmac(byte[] key, string label, int outLen)
        {
            byte[] mac;
            using (HMACSHA256 h = new HMACSHA256(key))
            {
                mac = h.ComputeHash(Encoding.UTF8.GetBytes(label));
            }
            if (mac.Length == outLen)
            {
                return mac;
            }
            byte[] r = new byte[outLen];
            Array.Copy(mac, r, Math.Min(outLen, mac.Length));
            return r;
        }

        private static byte[] Concat(byte[] a, byte[] b)
        {
            byte[] r = new byte[a.Length + b.Length];
            Array.Copy(a, 0, r, 0, a.Length);
            Array.Copy(b, 0, r, a.Length, b.Length);
            return r;
        }

        private static bool FixedTimeEquals(byte[] a, byte[] b)
        {
            if (a == null || b == null || a.Length != b.Length)
            {
                return false;
            }
            int diff = 0;
            for (int i = 0; i < a.Length; i++)
            {
                diff |= a[i] ^ b[i];
            }
            return diff == 0;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;

namespace FTProject
{
    /// <summary>
    /// 存档库的表结构与版本迁移。
    ///
    /// ==================================================================
    /// 【表结构设计说明】
    ///   设计原则是「一张表只描述一类事实」，避免把整份存档塞进一个 JSON 大字段：
    ///     · 单行表（player_profile / game_settings / level_snapshot）
    ///       用 `CHECK (id = 1)` 强制只能有一行 —— 从表结构上杜绝"出现两行设置，
    ///       读到的和写进去的不是同一行"这类诡异问题。
    ///     · level_progress 以 level_id 为主键：天然幂等，重复写同一关就是覆盖，不需要先查后写。
    ///     · snapshot_tower 是快照的子表，单行表里存"塔列表"会退化成逗号分隔字符串，
    ///       加一个字段就要改解析代码；独立成表后，塔的字段将来想扩展直接 ALTER 即可。
    ///
    /// 【哪些列加密】
    ///   凡是"改了就能占便宜"的数值一律加密（玩家档案的金币/钻石/昵称、关卡星级/通关次数），
    ///   加密后以 TEXT 列承载 Base64 信封（见 AesCryptoService）。
    ///   代价是这些列**不能用于 SQL 排序/聚合** —— 本工程不需要：
    ///   总星数、已通关数都是在 C# 里遍历累加的（见 SaveManager）。
    ///   会话设置（音量/静音）与局内快照属于"改了也没收益、且要频繁读写"的数据，保持明文。
    ///
    /// 【版本迁移】
    ///   meta 表里存 schema_version。新库写入当前版本；老库按 <see cref="CurrentVersion"/>
    ///   逐版本升级；**库版本高于程序**时只告警不动数据（可能是玩家降级了客户端，
    ///   贸然改表会把他高版本的数据毁掉）。
    /// ==================================================================
    /// </summary>
    public static class SaveSchema
    {
        /// <summary>当前表结构版本。**改动任何列语义时必须 +1，并在 Migrations 里补一段。**</summary>
        /// <remarks>
        /// v2（UI 补全 B4）：level_progress 增加 best_time_ms（最快通关的游戏内毫秒数）。
        /// </remarks>
        public const int CurrentVersion = 3;

        public const string MetaSchemaVersion = "schema_version";
        public const string MetaCreatedAt = "created_at";

        /// <summary>全部业务表名（自检与日志用）</summary>
        public static readonly string[] Tables =
        {
            "meta", "player_profile", "level_progress", "game_settings",
            "level_snapshot", "snapshot_tower", "kv_store"
        };

        /// <summary>
        /// 建表语句。全部带 IF NOT EXISTS，因此**可重复执行** ——
        /// 每次启动都跑一遍，就等于"缺表自动补齐"，不需要单独判断"是不是首次运行"。
        /// </summary>
        private static readonly string[] CreateStatements =
        {
            // 元信息：表结构版本、创建时间等
            "CREATE TABLE IF NOT EXISTS meta (" +
            "  k TEXT PRIMARY KEY NOT NULL," +
            "  v TEXT" +
            ");",

            // 玩家档案（单行）。金色数值列均为密文，故类型是 TEXT。
            "CREATE TABLE IF NOT EXISTS player_profile (" +
            "  id         INTEGER PRIMARY KEY CHECK (id = 1)," +
            "  nickname   TEXT," +
            "  gold       TEXT," +
            "  diamond    TEXT," +
            "  player_lv  TEXT," +
            "  exp        TEXT," +
            "  created_at INTEGER," +
            "  updated_at INTEGER" +
            ");",

            // 关卡进度：主键即关卡 id，写入天然幂等
            // best_time_ms：**最快**通关用时（游戏内毫秒，0 = 尚无记录）。
            //   ⚠️ 与 stars/best_hp_left/clear_count 同为"改了就能占便宜"的数值 → 走密文，
            //   所以列类型是 TEXT 而不是 INTEGER（密文信封是 Base64 字符串）。
            //   代价同其它敏感列：不能参与 SQL 排序/聚合 —— 取最快值在 C# 里做（见 SaveManager）。
            "CREATE TABLE IF NOT EXISTS level_progress (" +
            "  level_id     INTEGER PRIMARY KEY," +
            "  stars        TEXT," +
            "  best_hp_left TEXT," +
            "  clear_count  TEXT," +
            "  last_play_at INTEGER," +
            "  best_time_ms TEXT," +
            "  rating_payload TEXT," +
            "  updated_at   INTEGER" +
            ");",

            // 会话设置（单行，明文）
            "CREATE TABLE IF NOT EXISTS game_settings (" +
            "  id         INTEGER PRIMARY KEY CHECK (id = 1)," +
            "  volume     REAL," +
            "  muted      INTEGER," +
            "  updated_at INTEGER" +
            ");",

            // 局内快照主表（单行，明文）
            "CREATE TABLE IF NOT EXISTS level_snapshot (" +
            "  id           INTEGER PRIMARY KEY CHECK (id = 1)," +
            "  valid        INTEGER," +
            "  level_id     INTEGER," +
            "  round_cursor INTEGER," +
            "  gold         INTEGER," +
            "  hp           INTEGER," +
            "  max_hp       INTEGER," +
            "  rating_payload TEXT," +
            "  updated_at   INTEGER" +
            ");",

            // 局内快照的塔列表（子表）。slot 是槽位序号，整批替换时用它保持顺序稳定。
            "CREATE TABLE IF NOT EXISTS snapshot_tower (" +
            "  slot        INTEGER PRIMARY KEY," +
            "  grid_row    INTEGER," +
            "  grid_col    INTEGER," +
            "  tower_type  INTEGER," +
            "  tower_level INTEGER" +
            ");",

            // 通用键值表：给"设置项/杂项开关"这类零散数据留的扩展位。
            // sensitive = 1 表示该行的 v 会加密存放（由调用方声明）。
            "CREATE TABLE IF NOT EXISTS kv_store (" +
            "  k          TEXT PRIMARY KEY NOT NULL," +
            "  v          TEXT," +
            "  sensitive  INTEGER NOT NULL DEFAULT 0," +
            "  updated_at INTEGER" +
            ");"
        };

        /// <summary>
        /// 确保库结构就绪。**可重复调用**。抛出 <see cref="DatabaseException"/> 表示
        /// 建表失败（此时上层应当降级到 JSON 存档，而不是继续用一张不完整的库）。
        /// </summary>
        public static void Ensure(IDatabase db)
        {
            if (db == null)
            {
                throw new DatabaseException("Ensure 收到 null 数据库", null, 0);
            }

            IDbTransaction tx = db.BeginTransaction();
            try
            {
                for (int i = 0; i < CreateStatements.Length; i++)
                {
                    db.Execute(CreateStatements[i]);
                }

                int existing = db.QueryScalar<int>(
                    "SELECT v FROM meta WHERE k = ?1", 0, MetaSchemaVersion);

                if (existing <= 0)
                {
                    // 全新库：登记版本与创建时间
                    long now = Now();
                    db.Execute("INSERT OR REPLACE INTO meta (k, v) VALUES (?1, ?2)",
                        MetaSchemaVersion, CurrentVersion.ToString(CultureInfo.InvariantCulture));
                    db.Execute("INSERT OR REPLACE INTO meta (k, v) VALUES (?1, ?2)",
                        MetaCreatedAt, now.ToString(CultureInfo.InvariantCulture));
                }
                else if (existing < CurrentVersion)
                {
                    RunMigrations(db, existing);
                    db.Execute("INSERT OR REPLACE INTO meta (k, v) VALUES (?1, ?2)",
                        MetaSchemaVersion, CurrentVersion.ToString(CultureInfo.InvariantCulture));
                }
                else if (existing > CurrentVersion)
                {
                    // 不降级、不清表：只提示。极端情况下宁可让读写走"未知列"的容忍路径。
                    UnityEngine.Debug.LogWarning(string.Format(
                        "[Save] 存档库版本 {0} 高于本程序支持的 {1}（客户端被降级？）。" +
                        "将按只读兼容模式继续，不会修改库结构。", existing, CurrentVersion));
                }

                tx.Commit();
            }
            finally
            {
                tx.Dispose();
            }
        }

        /// <summary>
        /// 逐版本迁移。每个 case 都是"把库从 n 升到 n+1"，逐个串起来自然支持跨多版本升级。
        /// ⚠️ 老库（v1）的 level_progress 没有 best_time_ms 列，必须在这里补 ALTER，
        /// 否则老存档读取时会报"no such column"。
        /// </summary>
        private static void RunMigrations(IDatabase db, int fromVersion)
        {
            UnityEngine.Debug.Log(string.Format("[Save] 开始迁移存档库：{0} → {1}", fromVersion, CurrentVersion));

            for (int v = fromVersion; v < CurrentVersion; v++)
            {
                switch (v)
                {
                    // v1 → v2：关卡时间记录（UI 补全 B4「最佳用时」）
                    // 密文列 → TEXT；老行该列为 NULL，读取端 UnprotectInt(null) 回落 0（= 无记录）。
                    case 1:
                        db.Execute("ALTER TABLE level_progress ADD COLUMN best_time_ms TEXT;");
                        break;
                    case 2:
                        db.Execute("ALTER TABLE level_progress ADD COLUMN rating_payload TEXT;");
                        db.Execute("ALTER TABLE level_snapshot ADD COLUMN rating_payload TEXT;");
                        break;

                    default:
                        UnityEngine.Debug.LogWarning("[Save] 没有为版本 " + v + " 定义迁移步骤，已跳过。");
                        break;
                }
            }
        }

        /// <summary>表结构摘要（启动日志里打印一次，排查"表没建出来"最快）。</summary>
        public static string Describe()
        {
            List<string> rows = new List<string>(Tables.Length);
            for (int i = 0; i < Tables.Length; i++)
            {
                rows.Add(Tables[i]);
            }
            return string.Join(", ", rows.ToArray());
        }

        /// <summary>秒级时间戳（UTC）。用 UTC 是为了避免玩家改时区导致时间倒流。</summary>
        public static long Now()
        {
            return DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        }
    }
}

using System;
using System.IO;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 组装并选择存档后端：密钥 → 加密服务 → (SQLite → 失败则 JSON)。
    ///
    /// ==================================================================
    /// 【启动顺序（每一步失败都有明确的降级去向）】
    ///   ① 取密钥（LocalKeyProvider：两处存储各自持有一半，代码里无任何密钥常量）
    ///      ├─ 成功 → 建 AES 服务
    ///      └─ 失败 → 建"降级 AES 服务"（IsAvailable=false，读写走明文）
    ///   ② 尝试打开 SQLite（路径：persistentDataPath/freetower.db）
    ///      ├─ 成功 → 建表/迁移 → 用它
    ///      └─ 失败（原生库缺失、目录只读…）→ 打警告，落到 ③
    ///   ③ JSON 文件后端（顺带兼容旧版明文存档）
    ///
    /// 【为什么降级而不是报错退出】
    ///   这三步里任何一步都是"环境/权限"问题，不是玩家的错。降级之后游戏功能完整，
    ///   只是"没加密"或"没用到 SQL"，而这两种情况都会在日志里留下明确痕迹。
    /// ==================================================================
    /// </summary>
    internal static class SaveStorageFactory
    {
        /// <summary>数据库文件名（放在 Application.persistentDataPath 下）</summary>
        internal const string DatabaseFileName = "freetower.db";
        internal static string TestContextId;
        internal static string ActiveTestContextId
        {
            get
            {
                if (!string.IsNullOrEmpty(TestContextId)) return TestContextId;
#if UNITY_EDITOR
                return UnityEditor.SessionState.GetString("FT.Balance.TestStorageContext", "");
#else
                return null;
#endif
            }
        }
        internal static string StorageDirectory
        {
            get
            {
                if (string.IsNullOrEmpty(ActiveTestContextId)) return Application.persistentDataPath;
                string safe = System.Text.RegularExpressions.Regex.Replace(ActiveTestContextId, "[^A-Za-z0-9_-]", "_");
                return Path.Combine(Application.persistentDataPath, "BalanceTests", safe);
            }
        }

        /// <summary>数据库完整路径（排查问题时打印它最快）</summary>
        internal static string DatabasePath
        {
            get { return Path.Combine(StorageDirectory, DatabaseFileName); }
        }

        /// <summary>创建存档存储。**永不抛异常** —— 最差情况也会返回一个可用的 JSON 后端。</summary>
        internal static ISaveStorage Create()
        {
            ICryptoService crypto = CreateCrypto();
            Directory.CreateDirectory(StorageDirectory);

            // ② 优先 SQLite
            string dbPath = DatabasePath;
            SqliteDatabase db;
            string openError;
            if (SqliteDatabase.TryOpen(dbPath, out db, out openError))
            {
                try
                {
                    SqliteSaveStorage storage = new SqliteSaveStorage(db, crypto);
                    storage.Initialize();   // 建表 + 版本迁移；失败会抛
                    return storage;
                }
                catch (Exception ex)
                {
                    Debug.LogError("[Save] 建表/迁移失败，将改用 JSON 后端：" + ex.Message + "\n  位置：" + dbPath);
                    db.Dispose();
                }
            }
            else
            {
                Debug.LogWarning("[Save] 无法使用 SQLite，改用 JSON 文件后端。原因：" + openError);
            }

            // ③ 回退
            JsonSaveStorage fallback = new JsonSaveStorage(crypto, StorageDirectory);
            fallback.Initialize();
            return fallback;
        }

        // ------------------------------------------------------------------

        private static ICryptoService CreateCrypto()
        {
            LocalKeyProvider provider = new LocalKeyProvider();
            byte[] masterKey;
            if (!provider.TryGetMasterKey(out masterKey))
            {
                Debug.LogError("[Save] 无法取得加密密钥：" + provider.LastError +
                               "\n  敏感数据将以明文存储（功能不受影响）。");
                return AesCryptoService.Create(null);
            }

            ICryptoService crypto = AesCryptoService.Create(masterKey);

            if (!crypto.IsAvailable)
            {
                Debug.LogError("[Save] 加密服务初始化失败，敏感数据将以明文存储。");
            }
            else if (provider.KeyWasRotated)
            {
                // 密钥轮换意味着旧密文已解不开。这里刻意**不删除任何数据**：
                // 解密失败的项会各自退化为默认值（效果等同于新档），
                // 但万一是误判，文件还在，仍有人工抢救的余地。
                Debug.LogWarning(string.Format(
                    "[Save] 检测到密钥已重新生成（原因：{0}）。\n" +
                    "  旧存档中的加密字段将无法解密，会被当作未设置处理（等同新档）。\n" +
                    "  这是预期行为，不是崩溃；仅在你手动删除了 keystore 或偏好设置时才应出现。",
                    provider.LastError));
            }
            return crypto;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Runtime.InteropServices;
using System.Text;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// <see cref="IDatabase"/> 的 SQLite 实现（P/Invoke 直连原生库）。
    ///
    /// ==================================================================
    /// 【连接管理策略：一个长连接 + 一把锁】
    /// ==================================================================
    ///   存档库的访问模式是"低频、极小、偶尔并发"（一局结束写一次、每次改设置写一次），
    ///   所以：
    ///     · 不做连接池 —— 池化在这里只增加复杂度，没有任何收益；
    ///     · 用一个**长连接**（打开一次，一直用到进程退出），避免每次操作都 open/close
    ///       带来的文件句柄抖动；
    ///     · 打开时带 `SQLITE_OPEN_FULLMUTEX`，并在托管侧再加一把锁，
    ///       于是"主线程写档 + 后台线程读档"也不会踩到 prepared statement 的竞态。
    ///
    /// 【语句不缓存】每条 SQL 走一次 prepare → bind → step → finalize。
    ///   prepare 的解析开销在这个调用频率下完全可以忽略（微秒级），
    ///   而缓存会引入"语句句柄泄漏 / schema 变更后失效"这两类难查的问题。
    ///
    /// 【资源释放】所有语句都在 try/finally 里 finalize；Dispose 关连接。
    ///   即使中途抛异常也不会留下悬空的 statement 句柄。
    /// </summary>
    internal sealed class SqliteDatabase : IDatabase
    {
        private IntPtr _db = IntPtr.Zero;
        private readonly object _gate = new object();
        private bool _open;
        private int _txDepth;
        private bool _txRollbackOnly;
        private string _path;
        private string _version;

        // ------------------------------------------------------------------
        // 打开 / 关闭
        // ------------------------------------------------------------------

        /// <summary>
        /// 尝试打开数据库。**不抛异常**，失败时返回 false 并给出原因文本。
        ///
        /// 【为什么要"尝试"而不是"直接打开"】原生库可能不存在（例如换了平台却没带库、
        /// 精简版 Windows 缺少 winsqlite3）。这种情况必须能让上层优雅降级到 JSON 存档，
        /// 而不是把玩家挡在启动画面外。
        /// </summary>
        public static bool TryOpen(string path, out SqliteDatabase db, out string error)
        {
            db = null;
            error = null;
            SqliteDatabase instance = new SqliteDatabase();
            try
            {
                IntPtr handle;
                int rc = SqliteNative.Open(
                    Utf8Z(path), out handle,
                    SqliteNative.OPEN_READWRITE | SqliteNative.OPEN_CREATE | SqliteNative.OPEN_FULLMUTEX,
                    IntPtr.Zero);

                if (rc != SqliteNative.OK || handle == IntPtr.Zero)
                {
                    error = "sqlite3_open_v2 失败，返回码 " + rc;
                    if (handle != IntPtr.Zero)
                    {
                        SqliteNative.Close(handle);
                    }
                    return false;
                }

                instance._db = handle;
                instance._path = path;
                instance._open = true;

                try
                {
                    IntPtr vp = SqliteNative.LibVersion();
                    instance._version = PtrToUtf8Z(vp);
                }
                catch (Exception)
                {
                    instance._version = "unknown";
                }

                SqliteNative.BusyTimeout(handle, 5000);
                instance.ApplyPragmas();
                db = instance;
                return true;
            }
            catch (DllNotFoundException ex)
            {
                error = "找不到原生 SQLite 库（" + SqliteNative.Library + "）：" + ex.Message;
                instance.SafeClose();
                return false;
            }
            catch (EntryPointNotFoundException ex)
            {
                error = "原生库缺少所需导出函数： " + ex.Message;
                instance.SafeClose();
                return false;
            }
            catch (Exception ex)
            {
                error = "打开数据库异常：" + ex.Message;
                instance.SafeClose();
                return false;
            }
        }

        /// <summary>
        /// 打开时统一设置 PRAGMA。逐条注释见下方，配置理由集中在函数头。
        ///
        /// · journal_mode=WAL  —— 写不阻塞读，且崩溃后能自动恢复；
        ///                        存档在移动端被杀进程是常态，这一点很关键。
        /// · synchronous=NORMAL —— WAL 下的推荐档位：进程崩溃不会丢已提交数据，
        ///                        只在操作系统级掉电时可能丢最后几条。存档可以接受。
        /// · foreign_keys=ON   —— 让快照子表随主表级联删除，避免"孤儿塔"。
        /// · temp_store=MEMORY —— 临时结果放内存，省掉 sd 卡上的临时文件。
        /// </summary>
        private void ApplyPragmas()
        {
            ExecRaw("PRAGMA journal_mode=WAL;");
            ExecRaw("PRAGMA synchronous=NORMAL;");
            ExecRaw("PRAGMA foreign_keys=ON;");
            ExecRaw("PRAGMA temp_store=MEMORY;");
        }

        /// <summary>执行一条不需要参数、不关心结果的语句（PRAGMA / DDL）。失败只告警。</summary>
        private void ExecRaw(string sql)
        {
            try
            {
                Execute(sql);
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[DB] PRAGMA 设置失败（可忽略）：" + sql + " → " + ex.Message);
            }
        }

        public bool IsOpen { get { return _open; } }

        public string BackendName
        {
            get { return "SQLite " + (_version ?? "?"); }
        }

        public string DatabasePath { get { return _path; } }

        // ------------------------------------------------------------------
        // 写 / 查
        // ------------------------------------------------------------------

        public int Execute(string sql, params object[] args)
        {
            lock (_gate)
            {
                EnsureOpen();
                IntPtr stmt = PrepareStatement(sql, args);
                try
                {
                    StepToCompletion(stmt, sql);
                    return SqliteNative.Changes(_db);
                }
                finally
                {
                    SqliteNative.Finalize(stmt);
                }
            }
        }

        public long ExecuteInsert(string sql, params object[] args)
        {
            lock (_gate)
            {
                EnsureOpen();
                IntPtr stmt = PrepareStatement(sql, args);
                try
                {
                    StepToCompletion(stmt, sql);
                    return SqliteNative.LastInsertRowId(_db);
                }
                finally
                {
                    SqliteNative.Finalize(stmt);
                }
            }
        }

        public List<DbRow> Query(string sql, params object[] args)
        {
            lock (_gate)
            {
                EnsureOpen();
                IntPtr stmt = PrepareStatement(sql, args);
                try
                {
                    List<DbRow> rows = new List<DbRow>();
                    int rc;
                    while ((rc = SqliteNative.Step(stmt)) == SqliteNative.ROW)
                    {
                        rows.Add(ReadRow(stmt));
                    }
                    if (rc != SqliteNative.DONE)
                    {
                        throw MakeException(rc, sql);
                    }
                    return rows;
                }
                finally
                {
                    SqliteNative.Finalize(stmt);
                }
            }
        }

        public DbRow QuerySingle(string sql, params object[] args)
        {
            lock (_gate)
            {
                EnsureOpen();
                IntPtr stmt = PrepareStatement(sql, args);
                try
                {
                    int rc = SqliteNative.Step(stmt);
                    if (rc == SqliteNative.ROW)
                    {
                        return ReadRow(stmt);
                    }
                    if (rc != SqliteNative.DONE)
                    {
                        throw MakeException(rc, sql);
                    }
                    return null;
                }
                finally
                {
                    SqliteNative.Finalize(stmt);
                }
            }
        }

        public T QueryScalar<T>(string sql, T defaultValue, params object[] args)
        {
            DbRow row = QuerySingle(sql, args);
            if (row == null || row.ColumnCount == 0)
            {
                return defaultValue;
            }
            object raw = row.GetRaw(row.GetColumnName(0));
            if (raw == null || raw is DBNull)
            {
                return defaultValue;
            }
            return ConvertScalar<T>(raw, defaultValue);
        }

        // ------------------------------------------------------------------
        // 事务
        // ------------------------------------------------------------------

        public IDbTransaction BeginTransaction()
        {
            lock (_gate)
            {
                EnsureOpen();
                if (_txDepth == 0)
                {
                    // IMMEDIATE：立刻拿写锁，避免在"读→改→写"的临界区里
                    // 到提交那一刻才发现拿不到锁而失败（那会让整个事务白做）。
                    ExecInner("BEGIN IMMEDIATE;");
                    _txRollbackOnly = false;
                }
                _txDepth++;
                return new SqliteTransaction(this);
            }
        }

        /// <summary>内层事务句柄调用：只有最外层真正提交/回滚。</summary>
        internal void EndTransaction(bool commit)
        {
            lock (_gate)
            {
                if (_txDepth <= 0)
                {
                    return;
                }
                if (!commit) _txRollbackOnly = true;
                _txDepth--;
                if (_txDepth > 0)
                {
                    return;
                }
                bool shouldCommit = commit && !_txRollbackOnly;
                try
                {
                    ExecInner(shouldCommit ? "COMMIT;" : "ROLLBACK;");
                    if (commit && !shouldCommit) throw new DatabaseException("An inner transaction rolled back; outer commit was rejected", "COMMIT", 0);
                }
                catch (Exception ex)
                {
                    if (shouldCommit) { try { ExecInner("ROLLBACK;"); } catch (Exception) { } }
                    throw new DatabaseException("Transaction completion failed: " + ex.Message, shouldCommit ? "COMMIT" : "ROLLBACK", 0, ex);
                }
            }
        }

        private void ExecInner(string sql)
        {
            IntPtr stmt = PrepareStatement(sql, null);
            try
            {
                StepToCompletion(stmt, sql);
            }
            finally
            {
                SqliteNative.Finalize(stmt);
            }
        }

        public void Flush()
        {
            lock (_gate)
            {
                if (!_open)
                {
                    return;
                }
                try
                {
                    // 把 WAL 收拢回主库文件。失败不影响正确性（WAL 里的数据不会丢），
                    // 所以这里吞掉异常只做提示 —— 关机流程里绝不能因为 checkpoint 失败而报错。
                    ExecInner("PRAGMA wal_checkpoint(TRUNCATE);");
                }
                catch (Exception ex)
                {
                    Debug.LogWarning("[DB] wal_checkpoint 失败（可忽略）：" + ex.Message);
                }
            }
        }

        // ------------------------------------------------------------------
        // 内部：语句准备 / 绑定 / 读取
        // ------------------------------------------------------------------

        private void EnsureOpen()
        {
            if (!_open || _db == IntPtr.Zero)
            {
                throw new DatabaseException("数据库连接已关闭", null, 0);
            }
        }

        /// <summary>准备语句并绑定全部参数。失败时抛异常（语句句柄已回收）。</summary>
        private IntPtr PrepareStatement(string sql, object[] args)
        {
            if (string.IsNullOrEmpty(sql))
            {
                throw new DatabaseException("SQL 为空", sql, 0);
            }
            byte[] sqlBytes = Encoding.UTF8.GetBytes(sql);
            IntPtr stmt;
            // 传精确长度（而非 -1）：这样 SQL 不需要以 0 结尾，也就没有"越界读"的风险。
            int rc = SqliteNative.Prepare(_db, sqlBytes, sqlBytes.Length, out stmt, IntPtr.Zero);
            if (rc != SqliteNative.OK || stmt == IntPtr.Zero)
            {
                throw MakeException(rc, sql);
            }
            try
            {
                Bind(stmt, args, sql);
            }
            catch
            {
                SqliteNative.Finalize(stmt);
                throw;
            }
            return stmt;
        }

        private void Bind(IntPtr stmt, object[] args, string sql)
        {
            if (args == null || args.Length == 0)
            {
                return;
            }
            for (int i = 0; i < args.Length; i++)
            {
                // 占位符下标从 1 开始，所以这里 +1。
                int index = i + 1;
                object v = args[i];
                int rc;
                if (v == null || v is DBNull)
                {
                    rc = SqliteNative.BindNull(stmt, index);
                }
                else if (v is byte[])
                {
                    byte[] b = (byte[])v;
                    // SQLITE_TRANSIENT：让 SQLite 立刻拷贝，避免托管数组被 GC 后读到脏内存。
                    rc = SqliteNative.BindBlob(stmt, index, b, b.Length, SqliteNative.TRANSIENT);
                }
                else if (v is string)
                {
                    byte[] b = Encoding.UTF8.GetBytes((string)v);
                    rc = SqliteNative.BindText(stmt, index, b, b.Length, SqliteNative.TRANSIENT);
                }
                else if (v is bool)
                {
                    rc = SqliteNative.BindInt64(stmt, index, ((bool)v) ? 1L : 0L);
                }
                else if (v is float || v is double || v is decimal)
                {
                    rc = SqliteNative.BindDouble(stmt, index, Convert.ToDouble(v, CultureInfo.InvariantCulture));
                }
                else if (v is sbyte || v is byte || v is short || v is ushort ||
                         v is int || v is uint || v is long || v is ulong)
                {
                    rc = SqliteNative.BindInt64(stmt, index, Convert.ToInt64(v, CultureInfo.InvariantCulture));
                }
                else if (v is Enum)
                {
                    rc = SqliteNative.BindInt64(stmt, index, Convert.ToInt64(v, CultureInfo.InvariantCulture));
                }
                else
                {
                    byte[] b = Encoding.UTF8.GetBytes(Convert.ToString(v, CultureInfo.InvariantCulture));
                    rc = SqliteNative.BindText(stmt, index, b, b.Length, SqliteNative.TRANSIENT);
                }

                if (rc != SqliteNative.OK)
                {
                    throw MakeException(rc, sql);
                }
            }
        }

        /// <summary>把语句执行到结束。语句自带结果集时（DONE 之前的 ROW）直接丢弃。</summary>
        private void StepToCompletion(IntPtr stmt, string sql)
        {
            int rc;
            while ((rc = SqliteNative.Step(stmt)) == SqliteNative.ROW)
            {
                // 故意空转：调用方要的是"执行完"，结果集由 Query 系列负责。
            }
            if (rc != SqliteNative.DONE)
            {
                throw MakeException(rc, sql);
            }
        }

        private DbRow ReadRow(IntPtr stmt)
        {
            int n = SqliteNative.ColumnCount(stmt);
            string[] names = new string[n];
            object[] values = new object[n];
            for (int i = 0; i < n; i++)
            {
                names[i] = PtrToUtf8Z(SqliteNative.ColumnName(stmt, i));
                int type = SqliteNative.ColumnType(stmt, i);
                switch (type)
                {
                    case SqliteNative.TYPE_INTEGER:
                        values[i] = SqliteNative.ColumnInt64(stmt, i);
                        break;
                    case SqliteNative.TYPE_FLOAT:
                        values[i] = SqliteNative.ColumnDouble(stmt, i);
                        break;
                    case SqliteNative.TYPE_TEXT:
                        int len = SqliteNative.ColumnBytes(stmt, i);
                        // 【空串 ≠ NULL】UTF-8 长度 0 表示"存的是空字符串"，
                        // 必须还原成 string.Empty；若返回 null，调用方就无法区分
                        // "这个键存在但值为空" 与 "这个键根本不存在"。
                        values[i] = len <= 0 ? string.Empty : PtrToUtf8(SqliteNative.ColumnText(stmt, i), len);
                        break;
                    case SqliteNative.TYPE_BLOB:
                        int blen = SqliteNative.ColumnBytes(stmt, i);
                        values[i] = PtrToBytes(SqliteNative.ColumnBlob(stmt, i), blen);
                        break;
                    default:
                        values[i] = null;
                        break;
                }
            }
            return new DbRow(names, values);
        }

        private DatabaseException MakeException(int rc, string sql)
        {
            string msg = "(无法读取错误信息)";
            try
            {
                if (_db != IntPtr.Zero)
                {
                    msg = PtrToUtf8Z(SqliteNative.ErrMsg(_db));
                    int ext = SqliteNative.ExtendedErrCode(_db);
                    if (ext != 0)
                    {
                        msg = msg + "（extended code " + ext + "）";
                    }
                }
            }
            catch (Exception)
            {
                // 取错误信息本身失败时，不要掩盖原始错误。
            }
            return new DatabaseException("SQLite 错误 " + rc + "：" + msg, sql, rc);
        }

        // ------------------------------------------------------------------
        // 内部：UTF-8 与指针互转
        // ------------------------------------------------------------------

        /// <summary>托管字符串 → 以 0 结尾的 UTF-8 字节（给只接受 C 字符串的原生接口用）。</summary>
        internal static byte[] Utf8Z(string s)
        {
            byte[] body = Encoding.UTF8.GetBytes(s ?? string.Empty);
            byte[] z = new byte[body.Length + 1];
            Buffer.BlockCopy(body, 0, z, 0, body.Length);
            return z;
        }

        /// <summary>把原生 UTF-8 指针按给定长度解成字符串（不依赖 0 结尾）。</summary>
        internal static string PtrToUtf8(IntPtr p, int byteLength)
        {
            if (p == IntPtr.Zero || byteLength <= 0)
            {
                return null;
            }
            byte[] buf = new byte[byteLength];
            Marshal.Copy(p, buf, 0, byteLength);
            return Encoding.UTF8.GetString(buf, 0, buf.Length);
        }

        private static byte[] PtrToBytes(IntPtr p, int byteLength)
        {
            if (p == IntPtr.Zero || byteLength <= 0)
            {
                return null;
            }
            byte[] buf = new byte[byteLength];
            Marshal.Copy(p, buf, 0, byteLength);
            return buf;
        }

        /// <summary>读取以 0 结尾的原生 UTF-8 字符串（errmsg / column_name / libversion）。</summary>
        internal static string PtrToUtf8Z(IntPtr p)
        {
            if (p == IntPtr.Zero)
            {
                return null;
            }
            int len = 0;
            // 上限只是防御性护栏：原生字符串不可能超过这个长度，
            // 万一拿到野指针也不会把进程读挂。
            while (len < 65536 && Marshal.ReadByte(p, len) != 0)
            {
                len++;
            }
            return PtrToUtf8(p, len);
        }

        // ------------------------------------------------------------------
        // 标量类型转换
        // ------------------------------------------------------------------

        private static T ConvertScalar<T>(object raw, T defaultValue)
        {
            Type t = typeof(T);
            try
            {
                if (t == typeof(string))
                {
                    string s = raw as string;
                    if (s == null)
                    {
                        byte[] b = raw as byte[];
                        s = b != null ? Encoding.UTF8.GetString(b) : Convert.ToString(raw, CultureInfo.InvariantCulture);
                    }
                    return (T)(object)s;
                }
                if (t == typeof(int)) return (T)(object)(int)Convert.ToInt64(raw, CultureInfo.InvariantCulture);
                if (t == typeof(long)) return (T)(object)Convert.ToInt64(raw, CultureInfo.InvariantCulture);
                if (t == typeof(short)) return (T)(object)(short)Convert.ToInt64(raw, CultureInfo.InvariantCulture);
                if (t == typeof(byte)) return (T)(object)(byte)Convert.ToInt64(raw, CultureInfo.InvariantCulture);
                if (t == typeof(double)) return (T)(object)Convert.ToDouble(raw, CultureInfo.InvariantCulture);
                if (t == typeof(float)) return (T)(object)(float)Convert.ToDouble(raw, CultureInfo.InvariantCulture);
                if (t == typeof(decimal)) return (T)(object)Convert.ToDecimal(raw, CultureInfo.InvariantCulture);
                if (t == typeof(bool)) return (T)(object)(Convert.ToInt64(raw, CultureInfo.InvariantCulture) != 0L);
                if (t == typeof(byte[]))
                {
                    byte[] b = raw as byte[];
                    if (b != null) return (T)(object)b;
                    return (T)(object)Encoding.UTF8.GetBytes(Convert.ToString(raw, CultureInfo.InvariantCulture));
                }
                return (T)Convert.ChangeType(raw, t, CultureInfo.InvariantCulture);
            }
            catch (Exception)
            {
                return defaultValue;
            }
        }

        // ------------------------------------------------------------------
        // 释放
        // ------------------------------------------------------------------

        public void Dispose()
        {
            lock (_gate)
            {
                if (!_open)
                {
                    return;
                }
                try
                {
                    Flush();
                }
                catch (Exception)
                {
                    // 关库流程里不再抛异常。
                }
                _open = false;
                SafeClose();
            }
        }

        private void SafeClose()
        {
            if (_db != IntPtr.Zero)
            {
                try
                {
                    SqliteNative.Close(_db);
                }
                catch (Exception ex)
                {
                    Debug.LogWarning("[DB] 关闭连接失败：" + ex.Message);
                }
                _db = IntPtr.Zero;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// <see cref="ISaveStorage"/> 的 SQLite 实现。
    ///
    /// 【职责边界】
    ///   · 把「关卡进度 / 会话设置 / 局内快照 / 键值」翻译成对若干张表的读写；
    ///   · 对声明为敏感的列，写入前加密、读取后解密（业务层完全无感）；
    ///   · 事务边界：凡是一次操作会碰多行/多表的（保存快照、重置存档），一律包在事务里。
    ///
    /// 【为什么所有 public 方法都不抛异常】
    ///   见 <see cref="ISaveStorage"/> 的说明。这里统一的做法是：
    ///   用一个 try/catch 包住，失败 → 记 LastError + 打日志 + 返回安全默认值。
    ///   唯一的例外是 <see cref="Initialize"/>，它必须把失败暴露给上层以便降级。
    /// </summary>
    internal sealed class SqliteSaveStorage : ISaveStorage
    {
        private const int SingleRowId = 1;

        private readonly IDatabase _db;
        private readonly ICryptoService _crypto;
        private bool _initialized;

        internal SqliteSaveStorage(IDatabase db, ICryptoService crypto)
        {
            _db = db;
            _crypto = crypto;
        }

        public string BackendName
        {
            get { return _db != null ? _db.BackendName : "未连接"; }
        }

        public string Location
        {
            get { return _db != null ? _db.DatabasePath : null; }
        }

        public bool IsReady
        {
            get { return _initialized && _db != null && _db.IsOpen; }
        }

        public bool IsEncrypted
        {
            get { return _crypto != null && _crypto.IsAvailable; }
        }

        public string LastError { get; private set; }

        // ------------------------------------------------------------------
        // 初始化
        // ------------------------------------------------------------------

        public void Initialize()
        {
            SaveSchema.Ensure(_db);
            _initialized = true;
            Debug.Log(string.Format(
                "[Save] 存档库就绪：{0}\n  位置：{1}\n  数据表：{2}\n  敏感字段加密：{3}",
                BackendName, Location, SaveSchema.Describe(), IsEncrypted ? "已启用（AES-256-CBC + HMAC-SHA256）" : "未启用（密钥不可用）"));
        }

        // ------------------------------------------------------------------
        // 会话设置（明文）
        // ------------------------------------------------------------------

        public GameSettings LoadSettings()
        {
            GameSettings s = new GameSettings();
            try
            {
                DbRow row = _db.QuerySingle(
                    "SELECT volume, muted FROM game_settings WHERE id = ?1", SingleRowId);
                if (row != null)
                {
                    s.volume = row.GetFloat("volume", s.volume);
                    s.muted = row.GetBool("muted", s.muted);
                    s.Clamp();
                }
                string language;
                if (TryGetValue("settings.language", out language)) s.language = language ?? "";
            }
            catch (Exception ex)
            {
                Fail("读取会话设置失败", ex);
            }
            return s;
        }

        public void SaveSettings(GameSettings settings)
        {
            if (settings == null)
            {
                return;
            }
            try
            {
                settings.Clamp();
                _db.Execute(
                    "INSERT OR REPLACE INTO game_settings (id, volume, muted, updated_at) " +
                    "VALUES (?1, ?2, ?3, ?4)",
                    SingleRowId, settings.volume, settings.muted ? 1 : 0, SaveSchema.Now());
                SetValue("settings.language", settings.language ?? "", false);
            }
            catch (Exception ex)
            {
                Fail("写入会话设置失败", ex);
            }
        }

        // ------------------------------------------------------------------
        // 关卡进度（星级/最佳成绩/通关次数 → 加密列）
        // ------------------------------------------------------------------

        public List<LevelProgress> LoadLevels()
        {
            List<LevelProgress> list = new List<LevelProgress>();
            try
            {
                List<DbRow> rows = _db.Query(
                    "SELECT level_id, stars, best_hp_left, clear_count, best_time_ms, rating_payload FROM level_progress ORDER BY level_id");
                for (int i = 0; i < rows.Count; i++)
                {
                    DbRow r = rows[i];
                    LevelProgress p = new LevelProgress();
                    p.levelId = r.GetInt("level_id");
                    p.stars = UnprotectInt(r.GetString("stars"), 0);
                    p.bestHpLeft = UnprotectInt(r.GetString("best_hp_left"), 0);
                    p.clearCount = UnprotectInt(r.GetString("clear_count"), 0);
                    // 老库（v1）迁移后该列为 NULL → UnprotectInt 回落 0（= 无记录），不会报错
                    p.bestTimeMs = UnprotectInt(r.GetString("best_time_ms"), 0);
                    string payload = Unprotect(r.GetString("rating_payload"));
                    if (!string.IsNullOrEmpty(payload))
                    {
                        LevelProgress full = JsonUtility.FromJson<LevelProgress>(payload);
                        if (full == null || full.levelId != p.levelId) throw new InvalidOperationException("Rating progress identity mismatch");
                        p = full;
                    }
                    // 星级非法（>3）说明密文被换过或历史脏数据 —— 夹紧而不是丢弃整条记录，
                    // 丢掉会让玩家平白少一关进度。
                    if (p.stars < 0) p.stars = 0;
                    if (p.stars > LevelRatingEvaluator.MaxStars) p.stars = LevelRatingEvaluator.MaxStars;
                    if (p.levelId > 0)
                    {
                        list.Add(p);
                    }
                }
            }
            catch (Exception ex)
            {
                Fail("读取关卡进度失败", ex);
            }
            return list;
        }

        public void SaveLevel(LevelProgress progress)
        {
            if (progress == null || progress.levelId <= 0)
            {
                return;
            }
            try
            {
                WriteLevel(progress);
            }
            catch (Exception ex)
            {
                Fail("写入关卡进度失败", ex);
            }
        }
        private void WriteLevel(LevelProgress progress)
        {
            long now = SaveSchema.Now();
            _db.Execute("INSERT OR REPLACE INTO level_progress (level_id, stars, best_hp_left, clear_count, best_time_ms, last_play_at, updated_at, rating_payload) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)", progress.levelId, ProtectInt(Mathf.Clamp(progress.stars, 0, LevelRatingEvaluator.MaxStars)), ProtectInt(progress.bestHpLeft), ProtectInt(progress.clearCount), ProtectInt(progress.bestTimeMs), now, now, Protect(JsonUtility.ToJson(progress)));
        }
        public bool CommitClear(LevelProgress progress)
        {
            LastError = null;
            if (progress == null) return false;
            try
            {
                // BEGIN IMMEDIATE can fail before a transaction handle exists (for
                // example another connection owns the writer lock). Keep startup,
                // commit and disposal inside the same non-throwing save boundary.
                using (IDbTransaction tx = _db.BeginTransaction())
                {
                    WriteLevel(progress);
                    _db.Execute("DELETE FROM level_snapshot");
                    _db.Execute("DELETE FROM snapshot_tower");
                    tx.Commit();
                }
                return true;
            }
            catch (Exception ex) { Fail("Atomic clear commit failed", ex); return false; }
        }

        public void DeleteLevel(int levelId)
        {
            try
            {
                _db.Execute("DELETE FROM level_progress WHERE level_id = ?1", levelId);
            }
            catch (Exception ex)
            {
                Fail("删除关卡进度失败", ex);
            }
        }

        // ------------------------------------------------------------------
        // 局内快照（主表单行 + 塔子表，整批替换）
        // ------------------------------------------------------------------

        public LevelSnapshot LoadSnapshot()
        {
            LastError = null;
            LevelSnapshot snap = new LevelSnapshot();
            try
            {
                DbRow row = _db.QuerySingle(
                    "SELECT valid, level_id, round_cursor, gold, hp, max_hp, rating_payload " +
                    "FROM level_snapshot WHERE id = ?1", SingleRowId);
                if (row == null)
                {
                    return snap;   // 没有快照 → 返回 valid=false 的空快照
                }

                snap.valid = row.GetBool("valid");
                snap.levelId = row.GetInt("level_id");
                snap.roundCursor = row.GetInt("round_cursor");
                snap.gold = row.GetInt("gold");
                snap.hp = row.GetInt("hp");
                snap.maxHp = row.GetInt("max_hp");
                string payload = Unprotect(row.GetString("rating_payload"));
                if (!string.IsNullOrEmpty(payload))
                {
                    LevelSnapshot full = JsonUtility.FromJson<LevelSnapshot>(payload);
                    if (full == null || full.levelId != snap.levelId || full.roundCursor != snap.roundCursor || full.gold != snap.gold || full.hp != snap.hp || full.maxHp != snap.maxHp || full.valid != snap.valid) throw new InvalidOperationException("Checkpoint identity mismatch");
                    return full;
                }
                // Old checkpoints have no rating evidence and cannot resume the new campaign.
                snap.valid = false;

                if (snap.towers == null)
                {
                    snap.towers = new List<TowerSnapshot>();
                }
                List<DbRow> towers = _db.Query(
                    "SELECT grid_row, grid_col, tower_type, tower_level " +
                    "FROM snapshot_tower ORDER BY slot");
                for (int i = 0; i < towers.Count; i++)
                {
                    DbRow t = towers[i];
                    TowerSnapshot ts = new TowerSnapshot();
                    ts.row = t.GetInt("grid_row");
                    ts.col = t.GetInt("grid_col");
                    ts.type = t.GetInt("tower_type");
                    ts.level = t.GetInt("tower_level");
                    snap.towers.Add(ts);
                }
            }
            catch (Exception ex)
            {
                Fail("读取局内快照失败", ex);
                return new LevelSnapshot();
            }
            return snap;
        }

        public void SaveSnapshot(LevelSnapshot snapshot)
        {
            LastError = null;
            if (snapshot == null)
            {
                return;
            }
            IDbTransaction tx = null;
            try
            {
                // 主表与塔子表必须整体替换 —— 中途失败若留下"新主表 + 旧塔表"，
                // 下次恢复会建出一批本不该存在的塔。所以走事务。
                tx = _db.BeginTransaction();

                long now = SaveSchema.Now();
                _db.Execute(
                    "INSERT OR REPLACE INTO level_snapshot " +
                    "(id, valid, level_id, round_cursor, gold, hp, max_hp, updated_at, rating_payload) " +
                    "VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
                    SingleRowId,
                    snapshot.valid ? 1 : 0,
                    snapshot.levelId,
                    snapshot.roundCursor,
                    snapshot.gold,
                    snapshot.hp,
                    snapshot.maxHp,
                    now, Protect(JsonUtility.ToJson(snapshot)));

                _db.Execute("DELETE FROM snapshot_tower");

                if (snapshot.towers != null)
                {
                    for (int i = 0; i < snapshot.towers.Count; i++)
                    {
                        TowerSnapshot ts = snapshot.towers[i];
                        if (ts == null)
                        {
                            continue;
                        }
                        _db.Execute(
                            "INSERT OR REPLACE INTO snapshot_tower " +
                            "(slot, grid_row, grid_col, tower_type, tower_level) " +
                            "VALUES (?1, ?2, ?3, ?4, ?5)",
                            i, ts.row, ts.col, ts.type, ts.level);
                    }
                }

                tx.Commit();
            }
            catch (Exception ex)
            {
                Fail("写入局内快照失败", ex);
            }
            finally
            {
                if (tx != null)
                {
                    tx.Dispose();
                }
            }
        }

        // ------------------------------------------------------------------
        // 通用键值
        // ------------------------------------------------------------------

        public bool TryGetValue(string key, out string value)
        {
            value = null;
            if (string.IsNullOrEmpty(key))
            {
                return false;
            }
            try
            {
                DbRow row = _db.QuerySingle(
                    "SELECT v, sensitive FROM kv_store WHERE k = ?1", key);
                if (row == null)
                {
                    return false;
                }
                string raw = row.GetString("v");
                value = row.GetBool("sensitive")
                    ? Unprotect(raw)     // 敏感行 → 解密
                    : raw;
                return true;
            }
            catch (Exception ex)
            {
                Fail("读取键值「" + key + "」失败", ex);
                return false;
            }
        }

        public void SetValue(string key, string value, bool sensitive)
        {
            if (string.IsNullOrEmpty(key))
            {
                return;
            }
            try
            {
                string stored = sensitive ? Protect(value) : value;
                _db.Execute(
                    "INSERT OR REPLACE INTO kv_store (k, v, sensitive, updated_at) " +
                    "VALUES (?1, ?2, ?3, ?4)",
                    key, stored, sensitive ? 1 : 0, SaveSchema.Now());
            }
            catch (Exception ex)
            {
                Fail("写入键值「" + key + "」失败", ex);
            }
        }

        public void DeleteValue(string key)
        {
            try
            {
                _db.Execute("DELETE FROM kv_store WHERE k = ?1", key);
            }
            catch (Exception ex)
            {
                Fail("删除键值「" + key + "」失败", ex);
            }
        }

        // ------------------------------------------------------------------
        // 维护
        // ------------------------------------------------------------------

        public void ResetAll()
        {
            IDbTransaction tx = null;
            try
            {
                tx = _db.BeginTransaction();
                // meta 表刻意保留：它存的是表结构版本，删掉只会让下次启动误判为"全新库"。
                _db.Execute("DELETE FROM player_profile");
                _db.Execute("DELETE FROM level_progress");
                _db.Execute("DELETE FROM game_settings");
                _db.Execute("DELETE FROM level_snapshot");
                _db.Execute("DELETE FROM snapshot_tower");
                _db.Execute("DELETE FROM kv_store");
                tx.Commit();
                Debug.Log("[Save] 存档已清空（表结构保留）");
            }
            catch (Exception ex)
            {
                Fail("重置存档失败", ex);
            }
            finally
            {
                if (tx != null)
                {
                    tx.Dispose();
                }
            }
        }

        public void Flush()
        {
            if (_db == null)
            {
                return;
            }
            _db.Flush();
        }

        public void Dispose()
        {
            _initialized = false;
            // 连接的所有权在本类：由 SaveStorageFactory 创建后即交接过来，
            // 没有第二个持有者。所以这里负责关闭它 —— 否则进程内会一直挂着一个
            // 已无用的 SQLite 连接与文件句柄（编辑器里反复进出播放模式时尤其明显）。
            if (_db != null)
            {
                try
                {
                    _db.Dispose();
                }
                catch (Exception ex)
                {
                    Debug.LogWarning("[Save] 关闭数据库连接失败（可忽略）：" + ex.Message);
                }
            }
        }

        // ------------------------------------------------------------------
        // 加密包装（只在这里出现，业务层看不到）
        // ------------------------------------------------------------------

        private string Protect(string plain)
        {
            if (_crypto == null || string.IsNullOrEmpty(plain))
            {
                return plain;
            }
            try
            {
                return _crypto.Encrypt(plain);
            }
            catch (Exception ex)
            {
                LastError = "加密失败：" + ex.Message;
                Debug.LogError("[Save] " + LastError + "（该项将以明文写入）");
                return plain;
            }
        }

        private string Unprotect(string stored)
        {
            if (_crypto == null || string.IsNullOrEmpty(stored))
            {
                return stored;
            }
            try
            {
                return _crypto.Decrypt(stored);
            }
            catch (Exception ex)
            {
                // 密钥变了 / 有人改了密文 → 这一项当"没有"，但不影响其余数据。
                LastError = "解密失败：" + ex.Message;
                Debug.LogWarning("[Save] " + LastError + "（该项按默认值处理）");
                return null;
            }
        }

        private string ProtectInt(int value)
        {
            return Protect(value.ToString(CultureInfo.InvariantCulture));
        }

        private int UnprotectInt(string stored, int defaultValue)
        {
            if (string.IsNullOrEmpty(stored))
            {
                return defaultValue;
            }
            string plain = Unprotect(stored);
            int r;
            return int.TryParse(plain, NumberStyles.Integer, CultureInfo.InvariantCulture, out r)
                ? r : defaultValue;
        }

        private void Fail(string what, Exception ex)
        {
            LastError = what + "：" + ex.Message;
            Debug.LogWarning("[Save] " + LastError);
        }
    }
}

using System;

namespace FTProject
{
    /// <summary>
    /// SQLite 事务句柄。
    ///
    /// 【为什么单独成类而不是嵌套在 SqliteDatabase 里】嵌套私有类会让"类的成员声明"
    /// 出现在更深的括号层级，本项目的静态校验脚本（check_code.py 的嵌套层级检查）
    /// 会把它误判为"方法跑到类外面"。平级声明既避开误报，也更易读。
    ///
    /// 【语义】
    ///   · 支持嵌套（SaveManager 可能在外层"存档整体保存"里再调用某个 Upsert），
    ///     但只有最外层那个真正 COMMIT / ROLLBACK；
    ///   · Dispose 而未 Commit 视为 **Rollback** —— 这是"异常时就该什么都不留下"的正确默认；
    ///   · Commit / Rollback / Dispose 都幂等，重复调用不会二次递减事务深度。
    /// </summary>
    internal sealed class SqliteTransaction : IDbTransaction
    {
        private readonly SqliteDatabase _db;
        private bool _finished;

        internal SqliteTransaction(SqliteDatabase db)
        {
            _db = db;
        }

        public bool IsFinished { get { return _finished; } }

        public void Commit()
        {
            if (_finished)
            {
                return;
            }
            _finished = true;
            if (_db != null)
            {
                _db.EndTransaction(true);
            }
        }

        public void Rollback()
        {
            if (_finished)
            {
                return;
            }
            _finished = true;
            if (_db != null)
            {
                _db.EndTransaction(false);
            }
        }

        public void Dispose()
        {
            // 未显式提交 → 回滚。这样 `using (var tx = db.BeginTransaction()) { ... }`
            // 中途抛异常时不会把半截数据留在库里。
            Rollback();
        }
    }
}

using System;
using System.Collections.Generic;

namespace FTProject
{
    /// <summary>
    /// 单个关卡的进度。
    /// 【为什么用 public 字段而不是属性】Unity 的 JsonUtility **只序列化字段**，
    /// 属性会被静默忽略 —— 那样存出来的 json 永远是空的，而且不报错。
    /// </summary>
    [Serializable]
    public class LevelProgress
    {
        public int levelId;
        /// <summary>当前完整评级版本的星级 0~5；0 表示本版尚未评定。</summary>
        public int stars;
        /// <summary>历史最好成绩（剩余生命），仅用于展示</summary>
        public int bestHpLeft;
        /// <summary>累计通关次数</summary>
        public int clearCount;
        /// <summary>
        /// 历史**最快**通关用时（游戏内毫秒，0 = 尚无记录）。
        /// 【为什么是游戏内时间】见 GameClock.LevelElapsedSec：它是确定性的、跨倍速可比，
        /// 作为"最佳记录"才公平；用墙钟时间会让高倍速玩家的记录失真。
        /// </summary>
        public int bestTimeMs;
        public int bestCombatTimeMs;
        public string ratingVersionKey;
        public LevelRatingResult bestRating;
        public List<LegacyLevelProgress> legacy = new List<LegacyLevelProgress>();
        public List<string> committedRunIds = new List<string>();
        public bool Cleared { get { return stars > 0 || clearCount > 0 || (legacy != null && legacy.Exists(p => p.stars > 0 || p.clearCount > 0)); } }
    }

