    /// <summary>索敌策略（对应 TBTowerInfo.targetMode）</summary>
    public enum TargetMode
    {
        /// <summary>路径进度最靠前（最危险）优先 —— 塔防标准策略，默认</summary>
        FurthestAlongPath = 0,
        /// <summary>距离自身最近优先</summary>
        Nearest = 1,
        /// <summary>当前血量最高优先</summary>
