using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 棋盘视图：按 TBLevelMap 生成格子、提供坐标换算与高亮。
    ///
    /// 【性能注意】格子用 SpriteRenderer 逐个摆放，**不使用 LayoutGroup**
    /// （UGUI 的 LayoutGroup 在子节点增删时会触发整层 Rebuild，是低端机卡顿的常见根因）。
    ///
    /// 【为什么单独成文件】Unity 要求 MonoBehaviour 的类名与文件名一致，
    /// 否则该组件拿不到 MonoScript、无法被序列化进 prefab。
    /// </summary>
    public class BoardView : MonoBehaviour
    {
        public static BoardView Instance { get; private set; }

        /// <summary>格子贴图占格子的比例（留一点缝隙便于目视看清格线）</summary>
        public const float CellFillRatio = 0.94f;

        private Transform _root;
        private float _cellSize = 1f;
        private Vector2 _origin = Vector2.zero;
        private int _rows;
        private int _cols;
        private CellData[,] _cells;
        private CellView[,] _views;
        private Sprite[] _cellSprites;   // 索引与 CellType 对应（0..5）

        public float CellSize { get { return _cellSize; } }
        public Vector2 Origin { get { return _origin; } }
        public int Rows { get { return _rows; } }
        public int Cols { get { return _cols; } }
        public CellData SpawnCell { get; private set; }
        public CellData EndCell { get; private set; }
        public bool IsBuilt { get { return _cells != null; } }

        private void Awake()
        {
            Instance = this;
        }

        private void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        /// <summary>
        /// 按配置生成棋盘。
        /// origin 为棋盘左上角的世界坐标；调用方通常把它设为让棋盘居中的位置。
        /// </summary>
        public void Build(LevelMapConfig map, float cellSize, Vector2 origin, Transform root)
        {
            // ★ 先清掉上一次建的格子。
            // 【为什么必须放在最前面】格子是 new GameObject 出来的，父节点 boardRoot
            // 是**场景常驻**的（不随关卡切换销毁）。不清就再 Build 一次的话，
            // 上一关的整张地图会原样留在场景里 —— 通关后进下一关/回选关，
            // 看到的是"两张地图叠在一起"。
            Clear();

            _root = root != null ? root : transform;
            _cellSize = cellSize;
            _origin = origin;
            _rows = map.Rows;
            _cols = map.Cols;

            _cells = new CellData[_rows, _cols];
            _views = new CellView[_rows, _cols];
            SpawnCell = null;
            EndCell = null;

            LoadCellSprites();

            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c < _cols; c++)
                {
                    CellType type = BoardGeometry.ParseCell(map.GetCell(r, c));
                    CellData data = new CellData
                    {
                        Row = r,
                        Col = c,
                        Type = type,
                        Center = BoardGeometry.CellCenter(r, c, _cellSize, _origin),
                    };
                    _cells[r, c] = data;

                    GameObject go = new GameObject(string.Format("Cell({0},{1})", r, c));
                    go.transform.SetParent(_root, false);
                    go.transform.position = new Vector3(data.Center.x, data.Center.y, 0f);

                    CellView view = go.AddComponent<CellView>();
                    // 缩放由 CellView 按精灵原生尺寸折算（不用 LayoutGroup，也不写死 scale）
                    view.Setup(data, GetSpriteFor(type), _cellSize, CellFillRatio);
                    _views[r, c] = view;

                    if (type == CellType.Spawn) SpawnCell = data;
                    if (type == CellType.End) EndCell = data;
                }
            }

            if (SpawnCell == null || EndCell == null)
            {
                Debug.LogError("[Board] 棋盘缺少起点(S)或终点(E)，请检查 TBLevelMap 的 cells 配置");
            }
        }

        /// <summary>
        /// 清掉棋盘上所有格子视图（切关 / 重开用）。
        ///
        /// 【为什么必须有这一步】格子是 Build 时 `new GameObject` 出来的，而父节点
        /// boardRoot 是场景常驻对象 —— 不显式销毁，上一关的地图就会一直留在场景里。
        ///
        /// 【只销毁自己产出的节点】遍历 _views（Build 时记下的那一批），
        /// 不清空 boardRoot 的全部子物体 —— 万一日后有人往 boardRoot 下挂别的东西，
        /// 整层 Clean 会把它一起误删。
        /// </summary>
        public void Clear()
        {
            if (_views != null)
            {
                for (int r = 0; r < _rows; r++)
                {
                    for (int c = 0; c < _cols; c++)
                    {
                        CellView v = _views[r, c];
                        if (v == null)
                        {
                            continue;
                        }
                        GameObject go = v.gameObject;
                        if (go == null)
                        {
                            continue;
                        }
                        // 先 SetActive(false) 再 Destroy：Destroy 要到本帧末才真正生效，
                        // 而 Build 常常在同一帧紧接着执行 —— 不先隐藏的话，
                        // 会有整整一帧新旧两套格子同时可见（画面闪一下双地图）。
                        go.SetActive(false);
                        Destroy(go);
                    }
                }
            }
            _views = null;
            _cells = null;
            _rows = 0;
            _cols = 0;
            SpawnCell = null;
            EndCell = null;
        }

        private void LoadCellSprites()
        {
            if (_cellSprites != null)
            {
                return;
            }
            _cellSprites = new Sprite[6];
            _cellSprites[(int)CellType.Ground] = ResLoader.Instance.Load<Sprite>("Cell_Ground");
            _cellSprites[(int)CellType.Spawn] = ResLoader.Instance.Load<Sprite>("Cell_Spawn");
            _cellSprites[(int)CellType.End] = ResLoader.Instance.Load<Sprite>("Cell_End");
            _cellSprites[(int)CellType.Obstacle] = ResLoader.Instance.Load<Sprite>("Cell_Blocked");
            _cellSprites[(int)CellType.Hole] = ResLoader.Instance.Load<Sprite>("Cell_Blocked");
            _cellSprites[(int)CellType.Decor] = ResLoader.Instance.Load<Sprite>("Cell_Ground");
        }

        private Sprite GetSpriteFor(CellType t)
        {
            int i = (int)t;
            if (_cellSprites == null || i < 0 || i >= _cellSprites.Length)
            {
                return null;
            }
            return _cellSprites[i];
        }

        // ------------------------------------------------------------------
        // 查询与换算
        // ------------------------------------------------------------------

        public bool IsValid(int row, int col)
        {
            return _cells != null && row >= 0 && row < _rows && col >= 0 && col < _cols;
        }

        public CellData GetCell(int row, int col)
        {
            return IsValid(row, col) ? _cells[row, col] : null;
        }

        public CellView GetView(int row, int col)
        {
            return IsValid(row, col) ? _views[row, col] : null;
        }

        public Vector3 CellCenter3(int row, int col)
        {
            return BoardGeometry.CellCenter3(row, col, _cellSize, _origin);
        }

        public Vector2 CellCenter(int row, int col)
        {
            return BoardGeometry.CellCenter(row, col, _cellSize, _origin);
        }

        public bool WorldToCell(Vector2 world, out int row, out int col)
        {
            return BoardGeometry.WorldToCell(world, _cellSize, _origin, _rows, _cols, out row, out col);
        }

        /// <summary>
        /// 屏幕坐标 → 格子索引。
        /// 正交相机下 ScreenToWorldPoint 的 z 必须取 -camera.z，否则结果落在错误的深度。
        /// </summary>
        public bool ScreenToCell(Vector2 screenPos, out int row, out int col)
        {
            row = -1;
            col = -1;
            Camera cam = Camera.main;
            if (cam == null)
            {
                return false;
            }
            Vector3 world = cam.ScreenToWorldPoint(
                new Vector3(screenPos.x, screenPos.y, -cam.transform.position.z));
            return WorldToCell(world, out row, out col);
        }

        /// <summary>棋盘几何中心（相机对准用）</summary>
        public Vector2 BoardCenterWorld()
        {
            return BoardGeometry.BoardCenter(_rows, _cols, _cellSize, _origin);
        }

        // ------------------------------------------------------------------
        // 高亮
        // ------------------------------------------------------------------

        public void SetHighlight(int row, int col, CellHighlight h)
        {
            CellView v = GetView(row, col);
            if (v != null)
            {
                v.SetHighlight(h);
            }
        }

        public void ResetHighlight(int row, int col)
        {
            CellView v = GetView(row, col);
            if (v != null)
            {
                v.ResetHighlight();
            }
        }

        public void ResetAllHighlight()
        {
            if (_views == null)
            {
                return;
            }
            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c < _cols; c++)
                {
                    if (_views[r, c] != null)
                    {
                        _views[r, c].ResetHighlight();
                    }
                }
            }
        }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 单个格子的视图（世界空间 SpriteRenderer）。
    /// 只负责显示与高亮，不含任何游戏逻辑。
    ///
    /// 【为什么单独成文件】Unity 要求 MonoBehaviour 的类名与文件名一致，
    /// 否则该组件拿不到 MonoScript、无法被序列化进 prefab。
    /// </summary>
    public class CellView : MonoBehaviour
    {
        private SpriteRenderer _sr;
        private Color _baseColor = Color.white;
        private CellHighlight _highlight = CellHighlight.None;

        public CellData Data { get; private set; }

        /// <summary>
        /// 初始化。
        /// 【关于缩放】生成出来的格子贴图是 128×128 像素、PPU=100 → 原生 1.28 世界单位，
        /// 而格子边长是 1.0。如果直接 localScale = 0.94 会得到 1.20 单位，格子互相重叠。
        /// 正确做法是**按精灵原生尺寸折算**：scale = 目标尺寸 / 原生尺寸。
        /// 这样以后换任何分辨率的格子图都不用改代码。
        /// </summary>
        public void Setup(CellData data, Sprite sprite, float cellSize, float fillRatio = 0.94f)
        {
            Data = data;
            _sr = GetComponent<SpriteRenderer>();
            if (_sr == null)
            {
                _sr = gameObject.AddComponent<SpriteRenderer>();
            }
            _sr.sprite = sprite;
            _sr.sortingLayerName = BoardSorting.LayerMain;
            _sr.sortingOrder = BoardSorting.Cell;

            float target = cellSize * fillRatio;
            float native = 1f;
            if (sprite != null)
            {
                native = Mathf.Max(sprite.bounds.size.x, sprite.bounds.size.y);
            }
            float s = native > 0.0001f ? target / native : target;
            transform.localScale = new Vector3(s, s, 1f);

            // 障碍/空洞用暗色区分，便于目视核对配置表
            switch (data.Type)
            {
                case CellType.Obstacle:
                case CellType.Hole:
                    _baseColor = new Color(0.35f, 0.35f, 0.4f, 1f);
                    break;
                case CellType.Spawn:
                    _baseColor = new Color(0.6f, 0.9f, 0.6f, 1f);
                    break;
                case CellType.End:
                    _baseColor = new Color(0.95f, 0.6f, 0.6f, 1f);
                    break;
                default:
                    _baseColor = Color.white;
                    break;
            }
            transform.position = new Vector3(data.Center.x, data.Center.y, 0f);
            _sr.color = _baseColor;
        }

        public void SetHighlight(CellHighlight h)
        {
            if (_sr == null || _highlight == h)
            {
                return;
            }
            _highlight = h;
            switch (h)
            {
                case CellHighlight.Buildable:
                    _sr.color = new Color(0.4f, 1f, 0.4f, 1f);
                    break;
                case CellHighlight.Blocked:
                    _sr.color = new Color(1f, 0.35f, 0.35f, 1f);
                    break;
                case CellHighlight.Selected:
                    // 暖黄：与"可建造绿/不可建造红"在色相上完全分开，
                    // 也和塔身选中提亮色（1,0.95,0.72）同色系，观感统一。
                    _sr.color = new Color(1f, 0.88f, 0.45f, 1f);
                    break;
                default:
                    _sr.color = _baseColor;
                    break;
            }
        }

        public void ResetHighlight()
        {
            SetHighlight(CellHighlight.None);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>关卡流程状态</summary>
    public enum GameFlowState
    {
        None = 0,
        /// <summary>配置/资源加载中</summary>
        Loading,
        /// <summary>关卡已就绪，等待玩家点「开始」</summary>
        Preparing,
        /// <summary>回合进行中</summary>
        RoundRunning,
        /// <summary>回合完成，等待进入下一回合</summary>
        RoundComplete,
        /// <summary>胜负已定</summary>
        GameOver,
    }

    /// <summary>
    /// 关卡流程总控（P0-8）。
    ///
    /// 职责边界：
    ///   - 启动顺序编排（资源 → 配置 → 建关）
    ///   - 建关：棋盘 / 寻路网格 / 相机取景 / 管理器父节点 / UI / 预加载
    ///   - 回合推进：把 WaveManager 的一回合接到关卡的多回合链上，并判胜负
    ///   - **不碰具体战斗逻辑**（塔怎么打、怪怎么走都在各自模块里）
    ///
    /// 挂在 main.unity 的 GameFlow 对象上，由 SceneMainBuilder 自动创建并连线。
    /// </summary>
    public class GameFlowManager : MonoBehaviour
    {
        public static GameFlowManager Instance { get; private set; }

        [Header("场景引用（由 SceneMainBuilder 自动填充）")]
        public BoardView boardView;
        public PathArrowView pathArrowView;
        public Transform boardRoot;
        public Transform pathRoot;
        public Transform towerRoot;
        public Transform enemyRoot;
        public Transform bulletRoot;

        [Header("运行参数")]
        [Tooltip("为 0 表示使用配置表里的第一个关卡")]
        public int startLevelId = 0;

        public GameFlowState State { get; private set; }
        public LevelConfig Level { get; private set; }
        public LevelMapConfig Map { get; private set; }

        private readonly WaveManager _wave = new WaveManager();
        private List<int> _roundIds = new List<int>(8);
        private int _roundCursor;

        /// <summary>自动开下一回合的剩余秒数；&lt;=0 表示不在倒计时</summary>
        private float _autoNextTimer;
        /// <summary>倒计时提示的节流（每秒提示一次，避免每帧刷 Tips）</summary>
        private float _autoNextTipAcc;
        /// <summary>HUD 引用（倒计时需要更新按钮文字）</summary>
        private HudView _hud;

        /// <summary>
        /// 刚算好、等待结算界面展示的这一局成绩。
        ///
        /// 【为什么要暂存一层】结算发生在 <see cref="FinishRound"/>，而弹窗是在
        ///   <see cref="OnGameOver"/> 里统一打开的（胜负两条路都从那里出来）。
        ///   中间隔着 Win() → GameOverEvent 的一次派发，若在那里重新推算，
        ///   "本局**之前**的历史星级"就已经被 RecordClear 覆盖了，再也拿不回来。
        /// </summary>
        private LevelClearInfo _pendingResult;
        private LevelRatingProfile _ratingProfile;
        private LevelRunMetrics _run;
        private readonly HashSet<BaseEnemy> _unresolvedEnemies = new HashSet<BaseEnemy>();
        private bool _settled;
        private LevelRatingResult _pendingSaveResult;
        public LevelRunMetrics RunMetrics { get { return _run != null ? _run.Clone() : null; } }
        public LevelRatingProfile RatingProfile { get { return _ratingProfile != null ? _ratingProfile.Clone() : null; } }

        /// <summary>塔升级/出售面板是否已打开（惰性打开，见 OnTowerSelected）</summary>
        private bool _towerPanelOpened;

        /// <summary>当前回合序号（从 1 计，0 = 尚未开始）</summary>
        public int CurrentRoundIndex { get { return _roundCursor + (State == GameFlowState.RoundRunning ? 1 : 0); } }

        // ==================================================================
        // 启动
        // ==================================================================

        private void Awake()
        {
            Instance = this;
        }

        private void OnEnable()
        {
            EventDispatcher.AddEventListener<bool>(EventName.ConfigLoadedEvent, OnConfigLoaded);
            EventDispatcher.AddEventListener<BaseEnemy, int>(EventName.EnemyKilledEvent, OnRatedEnemyKilled);
            EventDispatcher.AddEventListener<BaseEnemy, int>(EventName.EnemyReachedEndEvent, OnRatedEnemyLeaked);
            EventDispatcher.AddEventListener(EventName.StartRoundRequestEvent, OnStartRequest);
            EventDispatcher.AddEventListener<bool>(EventName.GameOverEvent, OnGameOver);
            // M2：塔选中 → 打开升级/出售面板；升级/出售请求 → 执行
            EventDispatcher.AddEventListener<BaseTower>(EventName.TowerSelectedEvent, OnTowerSelected);
            EventDispatcher.AddEventListener<BaseTower>(EventName.TowerUpgradeRequestEvent, OnTowerUpgradeRequest);
            EventDispatcher.AddEventListener<BaseTower>(EventName.TowerSellRequestEvent, OnTowerSellRequest);
            // UI 补全 C1：出售必须经确认弹窗后才真正执行（只监听"确认"事件）
            EventDispatcher.AddEventListener<BaseTower>(EventName.TowerSellConfirmEvent, OnTowerSellConfirm);
            // M3：关卡选择 / 暂停 / 设置
            EventDispatcher.AddEventListener<int>(EventName.SelectLevelRequestEvent, OnSelectLevelRequest);
            EventDispatcher.AddEventListener(EventName.CloseSelectRequestEvent, OnCloseSelectRequest);
            EventDispatcher.AddEventListener(EventName.PauseRequestEvent, OnPauseRequest);
            EventDispatcher.AddEventListener(EventName.PauseToggleRequestEvent, OnPauseToggleRequest);
            EventDispatcher.AddEventListener(EventName.ResumeRequestEvent, OnResumeRequest);
            EventDispatcher.AddEventListener(EventName.RestartLevelRequestEvent, OnRestartRequest);
            EventDispatcher.AddEventListener(EventName.QuitToSelectRequestEvent, OnQuitToSelectRequest);
            // 2026-10-14：游戏介绍弹窗（HUD 右上角按钮）
            EventDispatcher.AddEventListener(EventName.OpenGameIntroRequestEvent, OnOpenGameIntroRequest);
            EventDispatcher.AddEventListener(EventName.OpenSettingsRequestEvent, OnOpenSettingsRequest);
            EventDispatcher.AddEventListener(EventName.CloseSettingsRequestEvent, OnCloseSettingsRequest);
            // P2b：倍速请求（HudView 发，这里校验后再写 GameClock）
            EventDispatcher.AddEventListener<float>(EventName.GameSpeedChangeRequestEvent, OnGameSpeedChangeRequest);
            // UI 补全 B1：主菜单入口（"开始游戏"+"图鉴"）
            EventDispatcher.AddEventListener(EventName.StartGameRequestEvent, OnStartGameRequest);
            EventDispatcher.AddEventListener<bool>(EventName.OpenCodexRequestEvent, OnOpenCodexRequest);
        }

        private void OnDisable()
        {
            EventDispatcher.RemoveEventListener<bool>(EventName.ConfigLoadedEvent, OnConfigLoaded);
            EventDispatcher.RemoveEventListener<BaseEnemy, int>(EventName.EnemyKilledEvent, OnRatedEnemyKilled);
            EventDispatcher.RemoveEventListener<BaseEnemy, int>(EventName.EnemyReachedEndEvent, OnRatedEnemyLeaked);
            EventDispatcher.RemoveEventListener(EventName.StartRoundRequestEvent, OnStartRequest);
            EventDispatcher.RemoveEventListener<bool>(EventName.GameOverEvent, OnGameOver);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.TowerSelectedEvent, OnTowerSelected);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.TowerUpgradeRequestEvent, OnTowerUpgradeRequest);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.TowerSellRequestEvent, OnTowerSellRequest);
            EventDispatcher.RemoveEventListener<int>(EventName.SelectLevelRequestEvent, OnSelectLevelRequest);
            EventDispatcher.RemoveEventListener(EventName.CloseSelectRequestEvent, OnCloseSelectRequest);
            EventDispatcher.RemoveEventListener(EventName.PauseRequestEvent, OnPauseRequest);
            EventDispatcher.RemoveEventListener(EventName.PauseToggleRequestEvent, OnPauseToggleRequest);
            EventDispatcher.RemoveEventListener(EventName.ResumeRequestEvent, OnResumeRequest);
            EventDispatcher.RemoveEventListener(EventName.RestartLevelRequestEvent, OnRestartRequest);
            EventDispatcher.RemoveEventListener(EventName.QuitToSelectRequestEvent, OnQuitToSelectRequest);
            EventDispatcher.RemoveEventListener(EventName.OpenGameIntroRequestEvent, OnOpenGameIntroRequest);
            EventDispatcher.RemoveEventListener(EventName.OpenSettingsRequestEvent, OnOpenSettingsRequest);
            EventDispatcher.RemoveEventListener(EventName.CloseSettingsRequestEvent, OnCloseSettingsRequest);
            EventDispatcher.RemoveEventListener<float>(EventName.GameSpeedChangeRequestEvent, OnGameSpeedChangeRequest);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.TowerSellConfirmEvent, OnTowerSellConfirm);
            EventDispatcher.RemoveEventListener(EventName.StartGameRequestEvent, OnStartGameRequest);
            EventDispatcher.RemoveEventListener<bool>(EventName.OpenCodexRequestEvent, OnOpenCodexRequest);
        }

        private void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        private void OnConfigLoaded(bool ok)
        {
            if (!ok)
            {
                Debug.LogError("[Flow] 配置表加载失败，已中止建关。请查看上方 [Config] 错误日志。");
                Tips(Localization.Get("Config load failed, see Console") ?? "配置表加载失败，请查看 Console");
                State = GameFlowState.None;
                return;
            }

            // M3：开机先进关卡选择。
            // 【为什么保留 startLevelId 直进】调试时要跳过选关，在 Inspector 里填 startLevelId 即可，
            // 不用改代码、也不用把选关界面拆掉。
            if (startLevelId > 0)
            {
                InitLevel(startLevelId);
                return;
            }

            // UI 补全 B1：先给玩家一个入口页，而不是直接把他丢在选关页上。
            // 主菜单缺 prefab 时降级为原来的"直接进选关"，不让启动卡住。
            MainMenuView menu = UIManager.Instance.Open<MainMenuView>("MainMenuView", UILayout.NormalPanel);
            if (menu != null)
            {
                return;
            }

            Debug.LogWarning("[Flow] MainMenuView 打开失败（prefab 可能还没生成），降级为直接进选关");
            OpenSelectOrFirstLevel();
        }

        /// <summary>打开选关界面；缺 prefab 时降级直接进第一关（原逻辑，抽出来复用）。</summary>
        private void OpenSelectOrFirstLevel()
        {
            SelectView sv = OpenSelect();
            if (sv == null)
            {
                // 【降级】SelectView.prefab 还没生成时不能把玩家卡在黑屏 ——
                // 直接进第一关，玩法照常，只是没有选关界面。
                Debug.LogWarning("[Flow] SelectView 打开失败（prefab 可能还没生成），降级为直接进入第一关");
                InitLevel(Configs.GetFirstLevelId());
            }
        }

        /// <summary>主菜单点「开始游戏」：关掉主菜单，进选关。</summary>
        private void OnStartGameRequest()
        {
            UIManager.Instance.Close("MainMenuView");
            OpenSelectOrFirstLevel();
        }

        /// <summary>
        /// 主菜单点图鉴。参数 true = 塔图鉴，false = 怪物图鉴。
        /// 【为什么先关主菜单】两个图鉴都是**整页**界面，整页界面叠在主菜单上会让
        /// "返回"到底回到哪一层变得含糊；先关再开，"返回"永远回主菜单。
        /// </summary>
        private void OnOpenCodexRequest(bool isTower)
        {
            UIManager.Instance.Close("MainMenuView");
            if (!isTower)
            {
                // 怪物图鉴（B3）尚未实现：明确提示，不静默失败
                EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent,
                    Localization.Get("Monster codex: UI not ready yet") ?? "怪物图鉴：界面生成中");
                UIManager.Instance.Open<MainMenuView>("MainMenuView", UILayout.NormalPanel);
                return;
            }
            TowerCodexView view = UIManager.Instance.Open<TowerCodexView>("TowerCodexView", UILayout.NormalPanel);
            if (view == null)
            {
                Debug.LogWarning("[Flow] TowerCodexView 打开失败（prefab 可能还没生成），回主菜单");
                UIManager.Instance.Open<MainMenuView>("MainMenuView", UILayout.NormalPanel);
            }
        }

        // ==================================================================
        // 建关
        // ==================================================================

        public void InitLevel(int levelId)
        {
            State = GameFlowState.Loading;
            // 进 Loading 就把倍速复位 ×1（P2b 硬性约束③）：新一局应当从最慢档开始
            ResetGameSpeed();

            Level = Configs.GetLevel(levelId);
            Map = Configs.GetLevelMapOfLevel(levelId);
            if (Level == null || Map == null)
            {
                Debug.LogError(string.Format("[Flow] 关卡 {0} 配置不完整，无法建关", levelId));
                Tips(Localization.Get("Level config incomplete") ?? "关卡配置不完整");
                State = GameFlowState.None;
                return;
            }

            string err = Map.Validate();
            if (!string.IsNullOrEmpty(err))
            {
                // 只是告警：cells 行长度不足时 GetCell 会按空地兜底，不至于崩
                Debug.LogError(string.Format("[Flow] 棋盘配置 id={0} 校验未通过：{1}", Map.Id, err));
            }

            // 关卡计时起点（UI 补全 B4「最佳用时」）。
            // 【为什么放在这里而不是方法最开头】上面的关卡/棋盘校验失败会提前 return，
            // 那次不算"进了一关"；放在校验之后，计时只在真正开始建关时启动。
            GameClock.ResetLevelTimer();
            _ratingProfile = Configs.GetLevelRating(levelId);
            _ratingProfile = _ratingProfile != null ? _ratingProfile.Clone() : null;
            string ratingError;
            if (!Configs.RatingContentVerified || !Configs.ValidateRatingPlan(_ratingProfile, out ratingError))
            {
                Debug.LogError("[Rating] Level cannot start: rating config missing, invalid, or content hash mismatch");
                State = GameFlowState.None;
                return;
            }
            _run = new LevelRunMetrics { runId = System.Guid.NewGuid().ToString("N"), statisticsValid = true, timingValid = true };
            if (_ratingProfile != null)
            {
                _run.profileId = _ratingProfile.profileId; _run.profileRevision = _ratingProfile.profileRevision;
                _run.balanceRevision = _ratingProfile.balanceRevision; _run.ratingRevision = _ratingProfile.ratingRevision; _run.planHash = _ratingProfile.planHash;
                _run.expectedWaveCount = _ratingProfile.expectedWaveCount; _run.expectedEnemyCount = _ratingProfile.expectedEnemyCount;
            }
            _settled = false; _pendingResult = null; _pendingSaveResult = null; _unresolvedEnemies.Clear();
            SaveManager.Instance.EnsureRatingVersion(levelId);

            // 关卡配置确认可用后才切战斗 BGM。
            // 【为什么放在校验之后】配置不完整会在上面提前 return，那时不该把音乐换成战斗曲。
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.PlayBgm(AudioName.BgmBattle);
            }

            float cellSize = Configs.Global.CellSize;
            // 棋盘左上角原点：让棋盘几何中心正好落在世界原点
            Vector2 origin = new Vector2(-Map.Cols * cellSize * 0.5f, Map.Rows * cellSize * 0.5f);
            Vector2 center = BoardGeometry.BoardCenter(Map.Rows, Map.Cols, cellSize, origin);

            SetupCamera(Map, cellSize, center);

            // ① 视图层：生成格子
            if (boardView == null)
            {
                Debug.LogError("[Flow] boardView 未连线，请执行「Tools ▸ 塔防 ▸ 搭建 main 场景」重新生成场景");
                State = GameFlowState.None;
                return;
            }
            boardView.Build(Map, cellSize, origin, boardRoot);

            // ② 数据层：只建寻路网格（不生成任何物件）
            AStarManager.Instance.BuildGrid(Map, cellSize, origin);
            EventDispatcher.TriggerEvent(EventName.MapInitFinish);

            // ③ 管理器父节点（对象池创建的实例据此归位，保持 Hierarchy 整洁）
            EnemyManager.Instance.SetParent(enemyRoot);
            BulletManager.Instance.SetParent(bulletRoot);
            TowerManager.Instance.SetParent(towerRoot);
            if (TowerPlacement.Instance != null)
            {
                TowerPlacement.Instance.SetGhostParent(towerRoot);
            }

            // ④ 路径可视化
            if (pathArrowView != null)
            {
                pathArrowView.Init(pathRoot);
                pathArrowView.Render(AStarManager.Instance.CurrentPathWorld);
            }

            // ⑥ 打开 UI
            HudView hud = UIManager.Instance.Open<HudView>(HudView.LogicalName, UILayout.NormalPanel);
            if (hud == null)
            {
                Debug.LogWarning("[Flow] HUD 未能打开，玩法仍可运行（无法用鼠标操作，请检查 ui_hud 包）");
            }
            _hud = hud;   // 自动回合倒计时需要更新按钮文字
            UIManager.Instance.Open<TipsView>("TipsView", UILayout.TipsPanel);

            // ⑦ 玩家数据（金币/生命来自关卡配置，不再是硬编码）
            PlayerDataManager.Instance.InitFromLevel(Level);

            // ⑧ 预加载本关会用到的资源（打 AB 时提前取好包引用）
            PreloadLevelResources();

            // ⑨ 回合队列
            _roundIds = Level.RoundIds != null ? new List<int>(Level.RoundIds) : new List<int>();
            _roundCursor = 0;

            // ⑩ M3-5：若本关存在局内快照，恢复到"上次退出的那一刻"。
            //    放在最后：棋盘/管理器/HUD 都已就绪，恢复出来的塔才有地方落。
            TryRestoreSnapshot(Level.Id);

            State = GameFlowState.Preparing;
            // The restored cursor must be published together with the restored economy and statistics.
            if (hud != null) hud.RefreshAll();
            if (_roundCursor == _roundIds.Count && _run.completedWaveCount == _roundIds.Count)
            {
                CompleteVictory();
                return;
            }
            Debug.Log(string.Format(
                "[Flow] 关卡 {0}「{1}」就绪：棋盘 {2}×{3}，格子 {4} 世界单位，回合 {5} 个\n{6}",
                Level.Id, Level.Name, Map.Cols, Map.Rows, cellSize, _roundIds.Count,
                AStarManager.Instance.DescribeCurrentPath()));
            Tips(Localization.Get("Level ready: {0}, click Start to fight", Localization.LevelName(Level.Id, Level.Name)) ?? string.Format("关卡就绪：{0}，点击「开始」迎战", Localization.LevelName(Level.Id, Level.Name)));

            // ⑪ 【真机诊断】缺失脚本扫描：延时 1 秒，覆盖 HUD / 资源预加载 / 快照恢复
            //    全部就位后的对象树。无缺失打一行 OK；有缺失则列出"对象路径 + 槽位数"
            //    （[Audit] 前缀），配合 Unity 自身的 "referenced script is missing" 警告
            //    可一步定位缺失脚本的宿主对象。
            RuntimeMissingScriptAudit.RunDeferred(this, 1f);

            // 可选：关卡就绪后自动开始第一回合
            // （常数表 Global.autoStartRoundDelayMs；默认 0，留给玩家先看地图 + 布防）
            float firstDelay = Configs.Global != null ? Configs.Global.AutoStartRoundDelaySec : 0f;
            if (firstDelay > 0f)
            {
                _autoNextTimer = firstDelay;
                _autoNextTipAcc = 0f;
                Debug.Log(string.Format("[Flow] {0:F0} 秒后自动开始第一回合", firstDelay));
            }
        }

        private void SetupCamera(LevelMapConfig map, float cellSize, Vector2 center)
        {
            Camera cam = Camera.main;
            if (cam == null)
            {
                Debug.LogError("[Flow] 场景中没有 Tag=MainCamera 的相机，棋盘无法取景");
                return;
            }
            CameraController ctrl = cam.GetComponent<CameraController>();
            if (ctrl == null)
            {
                ctrl = cam.gameObject.AddComponent<CameraController>();
            }
            ctrl.topMarginCells = Mathf.Max(ctrl.topMarginCells, 1.6f);
            ctrl.FitBoard(map.Rows, map.Cols, cellSize, center);
        }

        private void PreloadLevelResources()
        {
            List<string> keys = new List<string>(32);
            // 【为什么逐级登记】Normal / Power / Retard 各有 3 个分等级 prefab，升级时要换实例。
            // 这里一次全预载：塔就那么几座，省掉升级瞬间的加载卡顿比省内存更划算。
            // 新增塔型/等级时此处必须同步 —— 漏了会在升级时报"资源加载失败"。
            keys.Add("Tower_Normal0");
            keys.Add("Tower_Normal1");
            keys.Add("Tower_Normal2");
            keys.Add("Tower_Power0");
            keys.Add("Tower_Power1");
            keys.Add("Tower_Power2");
            keys.Add("Tower_Retard0");
            keys.Add("Tower_Retard1");
            keys.Add("Tower_Retard2");
            keys.Add("Bullet_Normal");
            keys.Add(HudView.LogicalName);
            keys.Add("TipsView");
            keys.Add("TowerInfoView");
            // 结算弹窗在本关结束的那一刻才需要，但那正是最不能卡顿的瞬间
            // （玩法已经停了，界面却要等 IO），所以提前预载。
            keys.Add("LevelClearView");

            if (Level.RoundIds != null)
            {
                for (int i = 0; i < Level.RoundIds.Count; i++)
                {
                    RoundConfig rc = Configs.GetRound(Level.RoundIds[i]);
                    if (rc == null || rc.WaveIds == null)
                    {
                        continue;
                    }
                    for (int w = 0; w < rc.WaveIds.Count; w++)
                    {
                        WaveGroupConfig wg = Configs.GetWaveGroup(rc.WaveIds[w]);
                        if (wg == null || wg.EnemyIds == null)
                        {
                            continue;
                        }
                        for (int e = 0; e < wg.EnemyIds.Count; e++)
                        {
                            EnemyConfig ec = Configs.GetEnemy(wg.EnemyIds[e]);
                            if (ec != null && !string.IsNullOrEmpty(ec.ResName) && !keys.Contains(ec.ResName))
                            {
                                keys.Add(ec.ResName);
                            }
                        }
                    }
                }
            }

            ResLoader.Instance.Preload(keys.ToArray(), null);
        }

        // ==================================================================
        // 回合推进
        // ==================================================================

        private void OnStartRequest()
        {
            // 玩家手动推进 → 取消自动倒计时（避免"点了按钮又自动开一回合"）
            _autoNextTimer = 0f;

            if (State == GameFlowState.RoundRunning)
            {
                Tips(Localization.Get("Wave in progress, wait for it to finish") ?? "波次进行中，请等待本波结束");
                return;
            }
            if (State == GameFlowState.GameOver)
            {
                Tips(Localization.Get("Game already ended") ?? "本局已结束");
                return;
            }
            if (State != GameFlowState.Preparing)
            {
                return;
            }
            if (_roundCursor >= _roundIds.Count)
            {
                CompleteVictory();
                return;
            }

            RoundConfig round = Configs.GetRound(_roundIds[_roundCursor]);
            if (round == null)
            {
                Tips(Localization.Get("Wave config missing") ?? "波次配置缺失");
                Debug.LogError(string.Format("[Flow] 找不到回合配置 id={0}", _roundIds[_roundCursor]));
                return;
            }

            // Persist preparation as one complete checkpoint, then freeze all half-wave changes.
            SaveSnapshotNow();
            if (_roundCursor == 0 && _run.completedWaveCount == 0) GameClock.StartLevelTimer();
            _unresolvedEnemies.Clear();
            int expected = 0;
            if (round.WaveIds != null) foreach (int waveId in round.WaveIds) { var group = Configs.GetWaveGroup(waveId); if (group != null) expected += group.EnemyCount; }
            _run.waves.Add(new WaveRunMetrics { ordinal = _roundCursor + 1, expected = expected, combatStartSeconds = GameClock.CombatElapsedSeconds });
            _wave.BeginRound(round);
            State = GameFlowState.RoundRunning;
            EventDispatcher.TriggerEvent<int>(EventName.RoundStartEvent, _roundCursor + 1);
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.Play(AudioName.RoundStart);
            }
            Tips(Localization.Get("Wave {0}/{1}", _roundCursor + 1, _roundIds.Count)
                ?? string.Format("第 {0}/{1} 波", _roundCursor + 1, _roundIds.Count));
        }

        /// <summary>
        /// 倍速请求（来自 HudView 的 ×1/×2/×3 按钮）。
        /// 【为什么要在这里二次校验，而不是信任 UI】
        ///   UI 只负责"循环切档"，它看不到游戏状态。若只有 UI 把关，
        ///   暂停遮罩或结算界面下只要点到按钮就会改速度（遮罩挡不住键盘/程序化调用）。
        ///   这里四道校验：档位合法 / 未暂停 / 局中状态 / 确有变化。
        /// </summary>
        private void OnGameSpeedChangeRequest(float requested)
        {
            if (!GameClock.IsValidTier(requested))
            {
                return;
            }
            // 暂停期间（timeScale=0）不改档：恢复时要按暂停前的原档位立即生效
            if (Time.timeScale <= 0f)
            {
                return;
            }
            // 只有"局中"允许改档：Loading / None / GameOver 一律忽略
            if (State != GameFlowState.Preparing &&
                State != GameFlowState.RoundRunning &&
                State != GameFlowState.RoundComplete)
            {
                return;
            }
            if (Mathf.Approximately(GameClock.Speed, requested))
            {
                return;
            }

            GameClock.Speed = requested;
            EventDispatcher.TriggerEvent<float>(EventName.GameSpeedChangedEvent, GameClock.Speed);
        }

        /// <summary>
        /// 把倍速复位为 ×1（GameOver / 重开 / 回选关 / 进 Loading 时调用）。
        /// 【为什么要派事件】HudView 的按钮文案靠 GameSpeedChangedEvent 同步；
        ///   只改 GameClock 而不派事件，下一局的按钮会停在上一局的档位文案上。
        /// </summary>
        private void ResetGameSpeed()
        {
            if (Mathf.Approximately(GameClock.Speed, 1f))
            {
                return;   // 本来就是 ×1，不必派多余事件
            }
            GameClock.Reset();
            EventDispatcher.TriggerEvent<float>(EventName.GameSpeedChangedEvent, GameClock.Speed);
        }

        /// <summary>
        /// CombatSystem 先完成本帧战斗，LateUpdate 再推进出生时间轴。
        /// 结束判定使用即时出生/结算账本，覆盖本阶段刚生成的怪物。
        /// </summary>
        private void LateUpdate()
        {
#if UNITY_EDITOR
            if (GameClock.IsManualSimulation) return;
#endif
            TickFlowSimulation();
        }
#if UNITY_EDITOR
        public void StepManualSimulation() { TickFlowSimulation(); }
#endif
        private void TickFlowSimulation()
        {
            // 自动回合倒计时（不受 State 限制，见 TickAutoNextRound 的说明）
            TickAutoNextRound(GameClock.DeltaTime);

            if (State != GameFlowState.RoundRunning)
            {
                return;
            }

            _wave.Tick(GameClock.DeltaTime);

            // The wave may have spawned its final enemy after CombatSystem cached its
            // count this frame. The outcome ledger includes that spawn immediately.
            int alive = _unresolvedEnemies.Count;
            _wave.CheckGroupCleared(alive);

            if (_wave.IsRoundFinished(alive))
            {
                FinishRound();
            }
        }

        private void FinishRound()
        {
            if (State != GameFlowState.RoundRunning || _settled) return;
            if (_unresolvedEnemies.Count > 0) return;
            WaveRunMetrics completed = _run != null && _run.waves.Count > 0 ? _run.waves[_run.waves.Count - 1] : null;
            if (completed == null || completed.successfulSpawned != completed.expected || completed.killed + completed.leaked != completed.expected)
            {
                InvalidateRun("Wave ended with incomplete enemy accounting");
                return;
            }
            _wave.Stop();
            GameClock.SetCombatRunning(false);
            int finishedIndex = _roundCursor + 1;

            // 回合奖励
            if (_roundCursor < _roundIds.Count)
            {
                RoundConfig rc = Configs.GetRound(_roundIds[_roundCursor]);
                if (rc != null && rc.RewardGold > 0)
                {
                    PlayerDataManager.Instance.AddGold(rc.RewardGold);
                    Tips(Localization.Get("Wave reward +{0} gold", rc.RewardGold)
                        ?? string.Format("波次奖励 +{0} 金币", rc.RewardGold));
                }
            }

            EventDispatcher.TriggerEvent<int>(EventName.RoundClearEvent, finishedIndex);
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.Play(AudioName.RoundClear);
            }

            _roundCursor++;
            _run.completedWaveCount = _roundCursor;
            if (completed != null)
            {
                completed.combatEndSeconds = GameClock.CombatElapsedSeconds;
                completed.levelEndSeconds = GameClock.LevelElapsedSeconds;
                completed.gold = PlayerDataManager.Instance.Gold; completed.hp = PlayerDataManager.Instance.Hp;
                RoundConfig finishedRound = Configs.GetRound(_roundIds[_roundCursor - 1]);
                completed.clearGold = finishedRound != null ? finishedRound.RewardGold : 0;
            }
            State = GameFlowState.RoundComplete;

            // Save the next-wave wait in the same coherent boundary as tower phases.
            float delay = _roundCursor < _roundIds.Count && Configs.Global != null ? Configs.Global.AutoNextRoundDelaySec : 0f;
            _autoNextTimer = Mathf.Max(0f, delay); _autoNextTipAcc = 0f;

            // M3-5：每回合结束存一次快照 —— 这是"退出后继续"的粒度。
            // 【为什么是回合边界】只有此刻状态是自洽的：场上无残留怪物、金币与塔都已结算。
            // 半途存盘就得额外记录每只怪的位置/血量/波次进度，复杂度与收益完全不成比例。
            SaveSnapshotNow();

            if (_roundCursor >= _roundIds.Count)
            {
                CompleteVictory();
            }
            else
            {
                // 回到可开始状态：HUD 收到 RoundClearEvent 会把按钮恢复成「下一回合」
                State = GameFlowState.Preparing;

                // 自动开下一回合：间隔读常数表（Global.autoNextRoundDelayMs）
                // 留出间隔是为了让玩家在两波之间布防/卖塔；设 0 则完全交给玩家手动点
                if (delay > 0f)
                {
                    Debug.Log(string.Format("[Flow] 回合 {0} 完成，{1:F1} 秒后自动开始回合 {2}",
                        finishedIndex, delay, _roundCursor + 1));
                }
                else
                {
                    Debug.Log(string.Format("[Flow] 回合 {0} 完成，等待开始回合 {1}（自动回合已关闭）",
                        finishedIndex, _roundCursor + 1));
                }
            }
        }

        /// <summary>
        /// 自动开下一回合的倒计时。
        /// 【为什么放在 LateUpdate 的最前面、且不受 State 限制】
        /// 上一回合结束时 State 已经回到 Preparing，如果跟着 `State == RoundRunning`
        /// 的早退一起被打断，倒计时就永远不会推进。
        /// </summary>
        private void TickAutoNextRound(float dt)
        {
            if (_autoNextTimer <= 0f)
            {
                return;
            }
            _autoNextTimer -= dt;

            if (_autoNextTimer <= 0f)
            {
                _autoNextTimer = 0f;
                Debug.Log("[Flow] 自动开始下一回合");
                if (_hud != null)
                {
                    _hud.SetStartButtonLabel(Localization.Get("Next Wave") ?? "下一波");
                }
                OnStartRequest();
                return;
            }

            // 每秒提示一次倒计时
            _autoNextTipAcc -= dt;
            if (_autoNextTipAcc <= 0f)
            {
                _autoNextTipAcc = 1f;
                int sec = Mathf.CeilToInt(_autoNextTimer);
                if (_hud != null)
                {
                    _hud.SetStartButtonLabel(Localization.Get("Next Wave ({0})", sec)
                        ?? string.Format("下一波({0})", sec));
                }
                Tips(Localization.Get("Wave complete, next wave starts in {0}s", sec)
                    ?? string.Format("本波完成，{0} 秒后自动开始下一波", sec));
            }
        }

        private void OnGameOver(bool victory)
        {
            GameClock.StopLevelTimer();
            if (_run != null && victory && !_settled) _run.debugOverride = true;
            _wave.Stop();
            State = GameFlowState.GameOver;
            // 结算即离场：倍速复位 ×1，结算界面下按钮也不再可用（HudView 会置灰）
            ResetGameSpeed();
            Debug.Log(string.Format("[Flow] 本局结束：{0}\n{1}",
                victory ? "胜利" : "失败", PlayerDataManager.Instance.DumpDebugInfo()));
            Tips(victory
                ? (Localization.Get("Congratulations!") ?? "恭喜通关！")
                : (Localization.Get("Defense failed...") ?? "防御失败……"));

            // 屏幕震动（UI 补全 C3）：只有"失败"才震，且给最大的系数 1.5 ——
            // 生命归零是本局最重的一次负面事件；胜利时抖一下反而像出错。
            if (!victory && CameraController.Instance != null && Configs.Global != null)
            {
                CameraController.Instance.Shake(
                    Configs.Global.ShakeAmplitude * 1.5f, Configs.Global.ShakeDurationSec);
            }

            ShowClearPopup(victory);
        }
        private LevelRatingResult EvaluateRun(bool victory)
        {
            if (_run == null) return LevelRatingEvaluator.Evaluate(_ratingProfile, null);
            _run.victory = victory;
            var pd = PlayerDataManager.Instance;
            _run.hp = pd != null ? pd.Hp : 0; _run.maxHp = pd != null ? pd.MaxHp : 0;
            _run.combatElapsedSeconds = GameClock.CombatElapsedSeconds;
            _run.levelElapsedSeconds = GameClock.LevelElapsedSeconds;
            return LevelRatingEvaluator.Evaluate(_ratingProfile, _run);
        }
        private void CompleteVictory()
        {
            if (_settled) return;
            _settled = true;
            GameClock.StopLevelTimer();
            State = GameFlowState.GameOver;
            var result = EvaluateRun(true);
            int previousBest = SaveManager.Instance.GetStars(Level.Id);
            bool saved = result.valid && SaveManager.Instance.RecordClear(Level.Id, result);
            _pendingSaveResult = result.valid && !saved ? result : null;
            _pendingResult = BuildClearInfo(true, result.stars, previousBest);
            _pendingResult.ratingResult = result;
            _pendingResult.progressSaved = saved;
            _pendingResult.savePending = result.valid && !saved;
            _pendingResult.newRecord = saved && result.stars > previousBest;
            if (_pendingResult.savePending)
            {
                var reasons = new List<string>(result.reasons); reasons.Add("Record could not be saved; retry save"); result.reasons = reasons.ToArray();
                Debug.LogWarning("[Save] Final checkpoint retained; retry result saving before leaving.");
            }
            EventDispatcher.TriggerEvent<int, int, int>(EventName.LevelClearEvent, Level.Id, result.stars, PlayerDataManager.Instance.Hp);
            PlayerDataManager.Instance.Win();
        }
        public bool RetryPendingClearSave()
        {
            if (_pendingSaveResult == null || _pendingResult == null || Level == null) return false;
            if (!SaveManager.Instance.RecordClear(Level.Id, _pendingSaveResult)) return false;
            _pendingResult.progressSaved = true; _pendingResult.savePending = false;
            _pendingResult.newRecord = _pendingResult.stars > _pendingResult.previousBest;
            _pendingResult.ratingResult = LevelRatingEvaluator.Evaluate(_pendingSaveResult.profile, _pendingSaveResult.metrics);
            _pendingSaveResult = null;
            var view = UIManager.Instance.Open<LevelClearView>(LevelClearView.LogicalName, UILayout.NormalPanel);
            if (view != null) view.Show(_pendingResult);
            return true;
        }
        public void MarkDebugRun() { if (_run != null) _run.debugOverride = true; }
        public void InvalidateRun(string reason)
        {
            if (_run != null) _run.statisticsValid = false;
            GameClock.StopLevelTimer(); _wave.Stop();
            Debug.LogError("[Rating] Formal run invalidated: " + reason);
            State = GameFlowState.GameOver;
            ShowClearPopup(false);
        }
        public void NotifyEnemySpawned(BaseEnemy enemy)
        {
            if (_run == null || State != GameFlowState.RoundRunning || enemy == null) return;
            if (!_unresolvedEnemies.Add(enemy)) { _run.statisticsValid = false; return; }
            _run.successfulSpawned++;
            GameClock.SetCombatRunning(true);
            if (_run.waves.Count > 0)
            {
                var wave = _run.waves[_run.waves.Count - 1]; wave.successfulSpawned++;
                wave.peakAlive = Mathf.Max(wave.peakAlive, _unresolvedEnemies.Count);
            }
        }
        private void OnRatedEnemyKilled(BaseEnemy enemy, int reward) { RecordEnemyOutcome(enemy, false, reward); }
        private void OnRatedEnemyLeaked(BaseEnemy enemy, int damage) { RecordEnemyOutcome(enemy, true, 0); }
        private void RecordEnemyOutcome(BaseEnemy enemy, bool leaked, int reward)
        {
            if (_run == null || enemy == null || !_unresolvedEnemies.Remove(enemy)) return;
            // Read identity before ReachedEnd recycles the object; HP is read only at final settlement.
            int id = enemy.Config != null ? enemy.Config.Id : 0;
            bool boss = _ratingProfile != null && _ratingProfile.bossVariantIds.Contains(id);
            bool critical = _ratingProfile != null && _ratingProfile.criticalVariantIds.Contains(id);
            if (leaked) { _run.leaked++; if (boss) _run.bossLeaked++; if (critical) _run.criticalLeaked++; }
            else _run.killed++;
            if (_run.waves.Count > 0)
            {
                var wave = _run.waves[_run.waves.Count - 1];
                if (leaked) { wave.leaked++; if (boss) wave.bossLeaked++; if (critical) wave.criticalLeaked++; }
                else { wave.killed++; wave.killGold += reward; }
                // The last planned entity has settled; death animation recycling does not count.
                if (wave.successfulSpawned == wave.expected && wave.killed + wave.leaked == wave.expected) GameClock.SetCombatRunning(false);
            }
        }
        private void OnApplicationPause(bool paused) { GameClock.SetBackground(paused); }
        private void OnApplicationFocus(bool focused) { GameClock.SetBackground(!focused); }

        // ------------------------------------------------------------------
        // 关卡结算弹窗
        //
        // 【为什么要有这一段】原实现只做了「写档 + 触发 LevelClearEvent + 弹一条 Tips」，
        //   而 **LevelClearEvent 全工程没有任何监听者** —— 事件空放，
        //   所以玩家打通关后看不到任何结算界面。这里把"打开界面"明确落在流程管理器上
        //   （与 PauseView / SettingView / SelectView 的开法一致：UI 只发事件，
        //    由流程层决定开什么、开在哪一层）。
        // ------------------------------------------------------------------

        private void ShowClearPopup(bool victory)
        {
            LevelClearInfo info;
            if (victory && _pendingResult != null)
            {
                info = _pendingResult;              // 正常通关：直接用 FinishRound 算好的成绩
            }
            else
            {
                // Failure and debug previews use the same evaluator without persisting progress.
                int previousBest = Level != null ? SaveManager.Instance.GetStars(Level.Id) : 0;
                LevelRatingResult result = EvaluateRun(victory);
                info = BuildClearInfo(victory, result.stars, previousBest);
                info.ratingResult = result;
            }
            // Keep the same frozen result if a duplicate event reopens the popup.
            _pendingResult = info;

            LevelClearView view = UIManager.Instance.Open<LevelClearView>(
                LevelClearView.LogicalName, UILayout.NormalPanel);
            if (view == null)
            {
                Debug.LogWarning("[Flow] 结算弹窗未能打开（请确认 ui_hud 包里已生成 LevelClearView.prefab）");
                return;
            }
            view.Show(info);
        }

        /// <summary>把"这一局的结果"组装成结算界面需要的数据。</summary>
        private LevelClearInfo BuildClearInfo(bool victory, int stars, int previousBest)
        {
            PlayerDataManager pd = PlayerDataManager.Instance;
            LevelClearInfo info = new LevelClearInfo();
            info.victory = victory;
            info.levelId = Level != null ? Level.Id : 0;
            info.levelName = Level != null ? Localization.LevelName(Level.Id, Level.Name) : null;
            info.stars = Mathf.Clamp(stars, 0, LevelRatingEvaluator.MaxStars);
            info.previousBest = Mathf.Clamp(previousBest, 0, LevelRatingEvaluator.MaxStars);
            // 只有"打得比历史最好还好"才算刷新记录；平了不算
            info.newRecord = victory && info.stars > info.previousBest;
            info.hp = pd != null ? pd.Hp : 0;
            info.maxHp = pd != null ? pd.MaxHp : 0;
            info.killed = pd != null ? pd.TotalKilled : 0;
            info.leaked = pd != null ? pd.TotalLeaked : 0;
            FindNextLevel(info);
            return info;
        }

        /// <summary>
        /// 找下一关：**id 大于本关的最小一关**。
        /// 【为什么不是简单 +1】与 SaveManager.PreviousLevelId 同一口径 ——
        ///   按配置表实际存在的关卡取相邻项，这样以后中间插入关卡也不会把链路走错。
        /// </summary>
        private void FindNextLevel(LevelClearInfo info)
        {
            info.nextLevelId = 0;
            info.nextLevelName = null;
            info.hasNext = false;

            if (Level == null || Configs.LevelTable == null || Configs.LevelTable.DataList == null)
            {
                return;
            }
            int cur = Level.Id;
            List<cfg.SceneInfo> all = Configs.LevelTable.DataList;
            for (int i = 0; i < all.Count; i++)
            {
                cfg.SceneInfo s = all[i];
                if (s == null || s.Id <= cur)
                {
                    continue;
                }
                if (info.nextLevelId == 0 || s.Id < info.nextLevelId)
                {
                    info.nextLevelId = s.Id;
                    info.nextLevelName = Localization.LevelName(s.Id, s.Name);
                }
            }
            info.hasNext = info.nextLevelId > 0;
        }

        // ------------------------------------------------------------------
        // 局内快照（M3-5）
        // ------------------------------------------------------------------

        /// <summary>把当前局内状态写进快照并落盘。</summary>
        public void SaveSnapshotNow()
        {
            if (Level == null || _run == null || State == GameFlowState.RoundRunning || State == GameFlowState.GameOver)
            {
                return;
            }
            LevelSnapshot snap = new LevelSnapshot();
            snap.valid = true;
            snap.levelId = Level.Id;
            snap.roundCursor = _roundCursor;
            snap.gold = PlayerDataManager.Instance.Gold;
            snap.hp = PlayerDataManager.Instance.Hp;
            snap.maxHp = PlayerDataManager.Instance.MaxHp;
            snap.formatVersion = 2;
            snap.ratingProfile = _ratingProfile != null ? _ratingProfile.Clone() : null;
            _run.combatElapsedSeconds = GameClock.CombatElapsedSeconds;
            _run.levelElapsedSeconds = GameClock.LevelElapsedSeconds;
            _run.hp = snap.hp; _run.maxHp = snap.maxHp;
            snap.metrics = _run.Clone();
            snap.levelTimerStarted = GameClock.IsLevelTimerRunning;
            snap.autoNextRemainingSeconds = _autoNextTimer;

            System.Collections.Generic.IList<BaseTower> towers = TowerManager.Instance.Towers;
            for (int i = 0; i < towers.Count; i++)
            {
                BaseTower t = towers[i];
                if (t == null || t.Cell == null || t.Config == null)
                {
                    continue;
                }
                TowerSnapshot ts = new TowerSnapshot();
                ts.row = t.Cell.Row;
                ts.col = t.Cell.Col;
                ts.type = t.Config.Type;
                ts.level = t.Config.Level;
                t.CaptureCheckpointState(ts);
                snap.towers.Add(ts);
            }

            SaveManager.Instance.SetSnapshot(snap);
        }

        /// <summary>
        /// 尝试用快照恢复本关进度。
        ///
        /// Restore the complete checkpoint, including statistics and fractional clocks.
        /// Any incompatible content or missing tower invalidates the entire checkpoint.
        /// </summary>
        private void TryRestoreSnapshot(int levelId)
        {
            if (!SaveManager.Instance.HasSnapshot)
            {
                return;
            }
            LevelSnapshot snap = SaveManager.Instance.Snapshot;
            if (snap == null || snap.levelId != levelId)
            {
                return;
            }
            string invalidReason;
            if (!LevelCheckpointValidator.IsCompatible(snap, _ratingProfile, _roundIds.Count, out invalidReason) || SaveManager.Instance.IsRunCommitted(levelId, snap.metrics != null ? snap.metrics.runId : null))
            {
                Debug.LogWarning("[Rating] Checkpoint discarded; restart current level: " + invalidReason);
                Tips(Localization.Get("Checkpoint incompatible: restart level") ?? "Checkpoint incompatible: restart level");
                SaveManager.Instance.ClearSnapshot(true);
                return;
            }

            PlayerDataManager.Instance.RestoreState(levelId, snap.gold, snap.hp, snap.maxHp, snap.metrics.killed, snap.metrics.leaked);

            int built = 0;
            for (int i = 0; i < snap.towers.Count; i++)
            {
                TowerSnapshot ts = snap.towers[i];
                BaseTower restored = ts != null ? TowerManager.Instance.RestoreTower(ts.type, ts.level, ts.row, ts.col) : null;
                if (restored != null && restored.RestoreCheckpointState(ts))
                {
                    built++;
                }
                else
                {
                    // Never certify a partially restored layout. Reset the whole checkpoint.
                    TowerManager.Instance.ClearAll();
                    PlayerDataManager.Instance.InitFromLevel(Level);
                    SaveManager.Instance.ClearSnapshot(true);
                    AStarManager.Instance.RequestRefresh();
                    Debug.LogWarning("[Rating] Tower restoration failed: checkpoint discarded, level restarted");
                    return;
                }
            }

            _roundCursor = snap.roundCursor;
            _run = snap.metrics.Clone();
            GameClock.RestoreTimers(_run.combatElapsedSeconds, _run.levelElapsedSeconds, snap.levelTimerStarted);
            _autoNextTimer = snap.autoNextRemainingSeconds; _autoNextTipAcc = 0f;

            // 【必须重算路径】恢复出来的塔会重新设置 A* 的墙标记，地图阻挡关系变了，
            // 不重算的话怪物会按"没塔时"的旧路径走，一路穿塔而过。
            if (AStarManager.Instance != null)
            {
                AStarManager.Instance.RequestRefresh();
            }
            if (pathArrowView != null && AStarManager.Instance != null)
            {
                pathArrowView.Render(AStarManager.Instance.CurrentPathWorld);
            }

            Debug.Log(string.Format("[Flow] 已恢复第 {0} 关的局内快照：回合进度 {1}/{2}，塔 {3} 座",
                levelId, _roundCursor, _roundIds.Count, built));
            Tips(Localization.Get("Resumed from checkpoint (next wave: {0})", _roundCursor + 1)
                ?? string.Format("已从完整检查点继续（下一波：第 {0} 波）", _roundCursor + 1));
        }

        // ------------------------------------------------------------------
        // 关卡切换 / 暂停 / 设置（M3）
        // ------------------------------------------------------------------

        /// <summary>
        /// 彻底清掉当前关卡的一切运行时状态。
        ///
        /// 【为什么必须有这一步】所有管理器都是**静态单例**，不随场景重建而重置；
        /// 而棋盘容器 BoardRoot / PathRoot / TowerRoot… 都是**场景常驻**节点，
        /// 谁往里面建了东西，谁就得负责拆。直接再 InitLevel 一次的话：
        /// 上一关的格子还挂在 BoardRoot 下、塔还挂在已被销毁的格子上、
        /// 怪物还留在空间哈希里、子弹还在飞 —— 会立刻出现一堆空引用与"幽灵塔"。
        ///
        /// 【顺序有讲究，本身就是正确性的一部分】
        ///   ① 先收回"玩家操作态"（放置预览 / 选中高亮 / 射程圈）：
        ///      它们要访问塔与格子（还原塔身颜色、复位格子高亮），
        ///      实体清完再收，就是在操作已经销毁的对象。
        ///   ② 再清战斗实体（它们互相引用：塔注册在 CombatSystem、怪在空间哈希）。
        ///   ③ 然后清棋盘与路径箭头 —— 这两样是"场景视觉残留"的主要来源。
        ///   ④ 最后关界面、恢复时间。
        /// </summary>
        public void TeardownLevel()
        {
            _autoNextTimer = 0f;
            // 离开对局必须解除暂停：走统一写入口（原先是裸写 Time.timeScale = 1f）
            SetPausedState(false);

            // 关卡计时停止（UI 补全 B4）。放在这里而不是各出口分别调：
            // TeardownLevel 是唯一的拆卸入口，所有离开对局的路径都会经过它。
            GameClock.StopLevelTimer();

            // ① 玩家操作态
            if (TowerPlacement.Instance != null)
            {
                // ★ 光调 Deselect 不够：放置中的预览体走的是另一条分支，
                //   关卡结束时正在放塔的话，幽灵塔会跟着进下一关。
                TowerPlacement.Instance.CancelPlacement();
                TowerPlacement.Instance.Deselect();
            }
            // 面板的"已打开过"标记跟着实例一起作废，否则下次选中塔会走错分支
            _towerPanelOpened = false;

            // ② 战斗实体（互相引用，一起清）
            _wave.Stop();
            if (EnemyManager.Instance != null) EnemyManager.Instance.ClearAll();
            if (BulletManager.Instance != null) BulletManager.Instance.RecycleAll();
            if (TowerManager.Instance != null) TowerManager.Instance.ClearAll();
            if (CombatSystem.Instance != null) CombatSystem.Instance.ResetStats();

            // ③ 场景视觉残留：棋盘格子 + 路径箭头。
            //    ★ 这里是"通关后地图没被清掉"的根因所在 —— 原实现只清了实体，
            //      完全没碰 BoardView 建出来的那一堆格子。
            if (boardView != null) boardView.Clear();
            if (pathArrowView != null) pathArrowView.Clear();
            // 飘字是"一次性表现"，寿命很短、自己也会消失，但它同样是
            // "上一关的画面"。一起收掉，让 TeardownLevel 成为一个完整的闭环 ——
            // 以后新增这类短命特效时，也照这个模式在这里登记一笔。
            FloatingTextManager.ClearAll();

            // ④ 界面
            UIManager.Instance.Close(TowerInfoView.LogicalName);
            UIManager.Instance.Close(PauseView.LogicalName);
            UIManager.Instance.Close(SettingView.LogicalName);
            // 游戏介绍弹窗（2026-10-14）也归这里关：点弹窗里的「回到选关」同样走
            // TeardownLevel，不在这里关的话弹窗会跟着进到新关卡里盖住画面。
            UIManager.Instance.Close(GameIntroView.LogicalName);
            // 结算弹窗也归这里关：点「下一关 / 重玩 / 返回选关」都会走到 StartLevel/QuitToSelect，
            // 两者第一步都是 TeardownLevel —— 不在这里关，弹窗会跟着进到新关卡里盖住画面。
            UIManager.Instance.Close(LevelClearView.LogicalName);
            // ★ HUD 也必须关。它是**被复用**的界面（UIManager.Open 对已存在的实例直接返回），
            //   不销毁就等于把上一局的按钮状态（"已通关"且不可点）原样带进新关卡 ——
            //   玩家进新关后会发现「开始」按钮点不动，第一回合永远开不了。
            UIManager.Instance.Close(HudView.LogicalName);
            _hud = null;
            State = GameFlowState.None;
        }

        /// <summary>切到指定关卡（或重开同一关）。</summary>
        public void StartLevel(int levelId)
        {
            if (levelId <= 0)
            {
                return;
            }
            if (SaveManager.Instance.HasSnapshot && SaveManager.Instance.Snapshot.levelId != levelId && !SaveManager.Instance.TryClearSnapshot())
            {
                Tips(Localization.Get("Checkpoint could not be cleared; original progress preserved") ?? "无法清除续玩记录，已保留原进度");
                return;
            }
            TeardownLevel();
            UIManager.Instance.Close(SelectView.LogicalName);
            // Selection resumes the compatible checkpoint for the same level.
            BeginLevelWithMask(levelId);
        }

        /// <summary>
        /// 带遮罩的进关（UI 补全 C4）。
        /// 【为什么必须"延迟一帧"】`InitLevel` 全程同步 —— 同帧里 Show 完立刻 Hide，
        /// 遮罩一帧都不会被渲染，等于没做。这里先让遮罩拿到一帧，再干重活。
        /// </summary>
        private void BeginLevelWithMask(int levelId)
        {
            LevelLoadingMask.Show(Localization.Get("Entering level {0}...", levelId)
                ?? string.Format("正在进入第 {0} 关...", levelId));
            StartCoroutine(InitLevelDeferred(levelId));
        }

        private System.Collections.IEnumerator InitLevelDeferred(int levelId)
        {
            yield return null;          // 让遮罩先渲染一帧
            InitLevel(levelId);         // 同步重建（棋盘/路径/实体/界面）
            LevelLoadingMask.Hide();    // 就绪后淡出（unscaled 时间，约 0.18s）
        }

        public void RestartLevel()
        {
            if (Level == null)
            {
                return;
            }
            if (_pendingSaveResult != null && !RetryPendingClearSave()) return;
            if (!SaveManager.Instance.TryClearSnapshot())
            {
                Tips(Localization.Get("Checkpoint could not be cleared; original progress preserved") ?? "无法清除续玩记录，已保留原进度");
                return;
            }
            StartLevel(Level.Id);
        }

        /// <summary>退出当前对局，回到关卡选择。</summary>
        public void QuitToSelect()
        {
            if (_pendingSaveResult != null && !RetryPendingClearSave()) return;
            SaveSnapshotNow();
            TeardownLevel();
            State = GameFlowState.None;
            // 回选关 = 离场：倍速复位 ×1（重开/下一关走 StartLevel→InitLevel，那里也会复位）
            ResetGameSpeed();
            OpenSelect();
        }

        /// <summary>
        /// 打开关卡选择界面，并切到选关 BGM。
        /// 【为什么返回 SelectView】调用方（OnConfigLoaded）要判断"是否打开成功"来决定降级路径；
        /// 顺带把"切选关 BGM"收进这一处，避免多个入口各写一遍。
        /// </summary>
        public SelectView OpenSelect()
        {
            SelectView sv = UIManager.Instance.Open<SelectView>(SelectView.LogicalName, UILayout.NormalPanel);
            if (sv != null && AudioManager.Instance != null)
            {
                AudioManager.Instance.PlayBgm(AudioName.BgmSelect);
            }
            return sv;
        }

        private void OnSelectLevelRequest(int levelId)
        {
            StartLevel(levelId);
        }

        /// <summary>
        /// 选关界面点「返回」。
        ///
        /// 【修了什么】原实现只 <c>Close(SelectView)</c> 就返回 —— 但选关**没有自己的场景**：
        ///   选关是叠在主菜单上的一层整页界面（见 <see cref="OnStartGameRequest"/>：先把主菜单
        ///   Close 掉才开选关）。只关掉自己，屏幕就只剩背景，玩家**既没回到主菜单、也没回到对局**，
        ///   看起来就是"点了返回没反应"。这里补上"回主菜单"这一步。
        ///
        /// 【为什么用 State 区分】选关有两个入口：
        ///   · 主菜单「开始游戏」→ State 仍是 None（没有对局）→ 返回 = 回主菜单；
        ///   · 对局中「退出选关」(QuitToSelect) → State != None → 返回 = 回对局（先 Teardown 再开选关，
        ///     否则旧棋盘 / HUD 会跟回来，与 <see cref="QuitToSelect"/> 的拆卸口径一致）。
        /// </summary>
        private void OnCloseSelectRequest()
        {
            UIManager.Instance.Close(SelectView.LogicalName);

            if (State == GameFlowState.None)
            {
                // 没有进行中的对局 → 返回主菜单。缺 prefab 时降级：直接进选关（不让启动卡住）。
                MainMenuView menu = UIManager.Instance.Open<MainMenuView>(
                    MainMenuView.LogicalName, UILayout.NormalPanel);
                if (menu == null)
                {
                    Debug.LogWarning("[Flow] MainMenuView 打开失败（prefab 可能还没生成），降级为直接进选关");
                    OpenSelectOrFirstLevel();
                }
                return;
            }

            // 对局中退出的选关 → 返回 = 回对局（先按要求拆卸，再重新建关）
            TeardownLevel();
            State = GameFlowState.None;
            ResetGameSpeed();
            InitLevel(Level != null ? Level.Id : Configs.GetFirstLevelId());
        }

        /// <summary>
        /// 打开暂停**菜单**弹窗（2026-10-18 起由 HUD 的 Btn_Intro 发送）。
        /// 【为什么不在这里暂停】暂停已与"弹窗"解耦：
        ///   · 暂停/继续 = Btn_Pause → <see cref="OnPauseToggleRequest"/> → <see cref="TogglePause"/>；
        ///   · 本方法只负责"把菜单摆出来"，**不动 timeScale**（弹窗想开就开，战斗照常）。
        ///   这样两个按钮的职责互不覆盖，也不会出现"关菜单顺手把暂停丢了"。
        /// </summary>
        private void OnPauseRequest()
        {
            if (State == GameFlowState.GameOver)
            {
                return;   // 已结算就别再开菜单了（结算界面在那儿）
            }
            PauseView view = UIManager.Instance.Open<PauseView>(PauseView.LogicalName, UILayout.NormalPanel);
            if (view == null)
            {
                Debug.LogWarning("[Flow] PauseView 打开失败（prefab 可能还没生成）");
            }
        }

        /// <summary>
        /// 暂停 / 继续（HUD 的 Btn_Pause、键盘 P）。
        /// 【为什么暂停也要过流程层】HUD 持有不了"是否局中/是否已结算"这些状态；
        ///   而且暂停唯一的合法写入口必须只有一处（GameClock.SetPaused），否则
        ///   多个界面各写一次 timeScale 就会出现互相覆盖的僵死状态。
        /// </summary>
        private void OnPauseToggleRequest()
        {
            TogglePause();
        }

        /// <summary>暂停态取反。只在"局中"三种状态生效（Loading / None / GameOver 一律忽略）。</summary>
        public void TogglePause()
        {
            if (State != GameFlowState.Preparing &&
                State != GameFlowState.RoundRunning &&
                State != GameFlowState.RoundComplete)
            {
                Debug.Log(string.Format("[Flow] 当前状态 {0} 不接受暂停切换，已忽略", State));
                return;
            }
            bool paused = !GameClock.IsPaused;
            SetPausedState(paused);
            // 【真机诊断埋点】"点暂停没反应"排查链第二环：开关是否真的落到 timeScale 上
            Debug.Log(string.Format("[Flow] {0}（timeScale={1}）", paused ? "暂停" : "继续", Time.timeScale));
        }

        /// <summary>
        /// 暂停状态的**唯一**写入口：改 timeScale + 广播变化（真的变了才广播）。
        /// 【为什么集中在一处】UI（PauseView 标题）与流程层都要看这个状态；
        ///   若各处分别写 timeScale、再各自派事件，就会出现"界面已切文案但时间没停"这类错位。
        /// </summary>
        private void SetPausedState(bool paused)
        {
            bool changed = GameClock.IsPaused != paused;
            GameClock.SetPaused(paused);
            if (changed)
            {
                EventDispatcher.TriggerEvent<bool>(EventName.PauseStateChangedEvent, paused);
            }
        }

        /// <summary>强制恢复运行（离开对局 / 重开 / 热键取消时用），幂等。</summary>
        public void EnsureRunning()
        {
            if (GameClock.IsPaused)
            {
                GameClock.SetPaused(false);
            }
        }

        private void OnResumeRequest()
        {
            UIManager.Instance.Close(PauseView.LogicalName);
            UIManager.Instance.Close(SettingView.LogicalName);
            // 走统一写入口（原先是直接写 Time.timeScale，与流程层的暂停状态容易脱钩）
            SetPausedState(false);
        }

        private void OnRestartRequest()
        {
            RestartLevel();
        }

        private void OnQuitToSelectRequest()
        {
            QuitToSelect();
        }

        /// <summary>
        /// 打开游戏介绍弹窗（GameIntroView，2026-10-14）。
        /// 【2026-10-18 现状】HUD 的 Btn_Intro 已改为打开暂停菜单（PauseRequestEvent），
        ///   本入口暂时**没有发送方**——保留是为了 GameIntroView 的资产/契约不失效
        ///   （将来要恢复入口，加一颗按钮发 OpenGameIntroRequestEvent 即可，流程层不用再改）。
        /// 【为什么不暂停】弹窗是查阅型界面，打开期间战斗照常；暂停只由 Btn_Pause 控制。
        /// </summary>
        private void OnOpenGameIntroRequest()
        {
            GameIntroView view = UIManager.Instance.Open<GameIntroView>(
                GameIntroView.LogicalName, UILayout.NormalPanel);
            if (view == null)
            {
                Debug.LogWarning("[Flow] GameIntroView 打开失败（prefab 可能还没生成）");
            }
        }

        private void OnOpenSettingsRequest()
        {
            UIManager.Instance.Open<SettingView>(SettingView.LogicalName, UILayout.NormalPanel);
        }

        private void OnCloseSettingsRequest()
        {
            UIManager.Instance.Close(SettingView.LogicalName);
        }

        /// <summary>
        /// 暂停热键。
        /// 【为什么用 P 而不是 ESC】ESC 已经被 TowerPlacement 用作"取消放置 / 取消选中"，
        /// 两个系统同帧抢同一个键必然出现"按一下既取消选中又暂停"。P 无歧义。
        /// 【为什么用 unscaledDeltaTime】暂停时 timeScale=0，用 deltaTime 的话热键轮询会停摆，
        /// 一旦暂停就再也按不回来了。
        /// </summary>
        // ------------------------------------------------------------------
        // 塔选中 / 升级 / 出售（M2）
        // ------------------------------------------------------------------

        /// <summary>
        /// 选中塔 → 惰性打开升级/出售面板。
        ///
        /// 【为什么打开后要显式 Show(tower)】面板是**在 TowerSelectedEvent 的分发过程中**实例化的，
        /// 它的 OnEnable（订阅事件）发生在本次分发之后 —— 于是它收不到"这一次"选中事件。
        /// 所以这里打开后必须手动喂一次，否则面板打开是空白。
        /// </summary>
        private void OnTowerSelected(BaseTower tower)
        {
            if (tower == null)
            {
                return;
            }

            // 【真机诊断埋点】"点塔没反应/不能升级"时，先看这条有没有出现：
            //   有 → 选中链路通，问题在面板；没有 → 点击没选中（输入/射线问题）。
            Debug.Log("[Flow] OnTowerSelected: " + tower.name);

            TowerInfoView view;
            if (!_towerPanelOpened)
            {
                view = UIManager.Instance.Open<TowerInfoView>(
                    TowerInfoView.LogicalName, UILayout.NormalPanel);
                if (view == null)
                {
                    // 面板资源未就绪时降级：提示玩家升级/出售暂不可用（逻辑本身没坏）
                    // 【真机诊断埋点】"点塔后不弹面板"若出现这条，说明 TowerInfoView 资源加载失败
                    Debug.LogWarning("[Flow] TowerInfoView 打开失败（面板资源未就绪），升级/出售入口不可用");
                    Tips(Localization.Get("Tower panel not ready, cannot upgrade/sell yet")
                        ?? "塔操作面板资源未就绪，暂无法升级/出售（补齐 TowerInfoView 后可用）");
                    return;
                }
                _towerPanelOpened = true;
            }
            else
            {
                UIManager.Instance.Open(TowerInfoView.LogicalName, UILayout.NormalPanel);
                view = UIManager.Instance.Get<TowerInfoView>(TowerInfoView.LogicalName);
            }

            if (view != null)
            {
                view.Show(tower);
            }
        }

        private void OnTowerUpgradeRequest(BaseTower tower)
        {
            // 【真机诊断埋点】面板 UpgradeBtn → 这里 → TryUpgrade。
            //   有这条但没升级 → TryUpgrade 内部失败（金币/满级/资源），Tips 有提示；
            //   连这条都没有 → 按钮点击没发事件（prefab 节点缺失或点击被吞）。
            Debug.Log("[Flow] OnTowerUpgradeRequest: " + (tower != null ? tower.name : "null"));
            TowerManager.Instance.TryUpgrade(tower);
        }

        private void OnTowerSellRequest(BaseTower tower)
        {
            // UI 补全 C1：这里**不再直接卖**，改为弹确认窗。
            // 真正执行在 OnTowerSellConfirm（只由 SellConfirmView 的"确认出售"触发）。
            SellConfirmView.Show(tower);
        }

        /// <summary>玩家在出售确认窗里点了"确认出售"——这才是真正执行出售的唯一入口。</summary>
        private void OnTowerSellConfirm(BaseTower tower)
        {
            if (tower == null)
            {
                return;
            }
            TowerManager.Instance.Sell(tower);
        }

        private static void Tips(string msg)
        {
            EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent, msg);
        }

        // ==================================================================
        // 诊断
        // ==================================================================

        public string DumpDebugInfo()
        {
            return string.Format(
                "[Flow] 状态={0} 关卡={1} 回合={2}/{3}\n  {4}\n  {5}\n  {6}",
                State, Level != null ? Level.Id : 0, _roundCursor, _roundIds.Count,
                PlayerDataManager.Instance.DumpDebugInfo(),
                _wave.DumpDebugInfo(),
                CombatSystem.Instance != null ? CombatSystem.Instance.DumpDebugInfo() : "(战斗系统未初始化)");
        }

        private void Update()
        {
            // P2b：每帧刷新 GameClock 的本帧缓存值（Time.deltaTime × Speed）。
            // 【放首行的原因】它必须在任何消费点之前跑过一次，本帧全工程才会取到同一个 dt。
            //   GameClock.DeltaTime 本身是惰性按帧缓存的（谁先取谁算），这里只是显式提前算好，
            //   因此即便本 Update 的执行顺序排在 CombatSystem 之后也不影响正确性。
            GameClock.Tick();

            // ---- M3：暂停热键（2026-10-18 改为与 Btn_Pause 同一语义：只暂停/继续，不弹窗）----
            // 【为什么是 P 而不是 ESC】ESC 已被 TowerPlacement 用作"取消放置 / 取消选中"，
            // 两个系统同帧抢同一个键，必然出现"按一下既取消选中又暂停"。
            //
            // 【为什么这里不用 deltaTime】暂停时 Time.timeScale = 0，
            // 任何依赖 scaled time 的轮询都会停摆 —— 一旦暂停就再也按不回来。
            // GetKeyDown 不受 timeScale 影响，所以这个热键在暂停中依然有效。
            if (Input.GetKeyDown(KeyCode.P))
            {
                // 原先：菜单开着 → 继续；否则开菜单。现在暂停与菜单彻底分开：
                // 热键只当暂停开关（菜单由 HUD 的 Btn_Intro 打开），避免"按 P 弹窗"的旧行为残留。
                TogglePause();
            }

            // 调试快捷键：F1 打印完整状态，F2 强制获胜，F3 性能报告（联调/压测用）
            if (Input.GetKeyDown(KeyCode.F1))
            {
                Debug.Log(DumpDebugInfo());
            }
            else if (Input.GetKeyDown(KeyCode.F2))
            {
                MarkDebugRun();
                PlayerDataManager.Instance.Win();
            }
            else if (Input.GetKeyDown(KeyCode.F3))
            {
                // M5-3：真机压测就靠它把"手感"变成可贴出来的数字
                Debug.Log(PerfProbe.Ensure().Report());
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 路径箭头渲染（§6.1.4）。
    ///
    /// 监听 RefreshPathEvent，按 AStarManager.CurrentPathWorld 摆放箭头。
    /// 箭头对象池化复用 —— 每次建塔都会重算路径，反复 Instantiate/Destroy 会产生大量 GC。
    ///
    /// 【M0 简化】只画"当前路径经过的每一格"，不区分拐角与直行朝向差异以外的美化。
    ///
    /// 【2026-10-22 新增预览层】放置防御塔时，悬停格会实时推演"建成后怪物会走哪里"，
    /// 用**另一种颜色**画在真实路径之上（PreviewPathEvent → PreviewPathWorld）。
    /// 两套箭头各用各的对象池，互不顶替：预览消失时真实路径必须原样还在，
    /// 否则玩家会看到"只是滑了一下，路径箭头就没了"。
    /// </summary>
    public class PathArrowView : MonoBehaviour
    {
        private Transform _root;
        private Sprite _arrowSprite;
        private readonly List<SpriteRenderer> _pool = new List<SpriteRenderer>(128);
        private int _used;
        /// <summary>预览箭头（放置态专用），与真实路径箭头分池</summary>
        private readonly List<SpriteRenderer> _previewPool = new List<SpriteRenderer>(128);
        private int _previewUsed;
        private bool _inited;

        /// <summary>箭头占格子的比例（相对格子边长，不是相对精灵原生尺寸）</summary>
        private const float ArrowScale = 0.5f;

        /// <summary>真实路径箭头：白色半透明（现状不变）</summary>
        private static readonly Color PathColor = new Color(1f, 1f, 1f, 0.75f);

        /// <summary>
        /// 预览箭头：红色（2026-10-22 用户定：预览线路显示为红色）。
        /// 与白色真实路径一眼可分，且"红 = 将要变成这样"的语义比青色更直觉。
        /// </summary>
        private static readonly Color PreviewColor = new Color(1f, 0.23f, 0.23f, 0.9f);

        /// <summary>箭头精灵的原生世界尺寸（由 Init 从 Sprite 实测，避免写死缩放）</summary>
        private float _arrowNativeSize = 0.64f;

        public void Init(Transform root)
        {
            // 幂等：重复进关卡时不要重复注册监听（EventDispatcher 用委托 += 实现，
            // 重复注册会让每次路径刷新触发多次渲染）
            if (_inited)
            {
                if (root != null)
                {
                    _root = root;
                }
                return;
            }
            _inited = true;
            _root = root;
            _arrowSprite = ResLoader.Instance.Load<Sprite>("Path_Arrow");
            if (_arrowSprite != null)
            {
                _arrowNativeSize = Mathf.Max(_arrowSprite.bounds.size.x, _arrowSprite.bounds.size.y);
                if (_arrowNativeSize < 0.0001f)
                {
                    _arrowNativeSize = 0.64f;
                }
            }
            else
            {
                Debug.LogWarning("[Path] 箭头贴图未就绪，路径可视化将不显示（不影响玩法）");
            }
            EventDispatcher.AddEventListener(EventName.RefreshPathEvent, OnRefreshPath);
            EventDispatcher.AddEventListener(EventName.MapInitFinish, OnRefreshPath);
            // 放置预览：只画箭头，不驱动怪物（见 AStarManager.PreviewPathWorld 的说明）
            EventDispatcher.AddEventListener(EventName.PreviewPathEvent, OnPreviewPathChanged);
        }

        private void OnDestroy()
        {
            EventDispatcher.RemoveEventListener(EventName.RefreshPathEvent, OnRefreshPath);
            EventDispatcher.RemoveEventListener(EventName.MapInitFinish, OnRefreshPath);
            EventDispatcher.RemoveEventListener(EventName.PreviewPathEvent, OnPreviewPathChanged);
        }

        private void OnRefreshPath()
        {
            Render(AStarManager.Instance != null ? AStarManager.Instance.CurrentPathWorld : null);
        }

        private void OnPreviewPathChanged()
        {
            RenderPreview(AStarManager.Instance != null ? AStarManager.Instance.PreviewPathWorld : null);
        }

        /// <summary>按世界坐标序列摆放箭头</summary>
        public void Render(Vector3[] path)
        {
            _used = LayoutArrows(path, _pool, "Arrow", PathColor, BoardSorting.PathArrow);
            HideFrom(_pool, _used);
        }

        /// <summary>
        /// 摆放预览箭头。
        /// 【为什么与真实路径逐格比对】若这一格建塔并不会改变路线（新路 == 旧路），
        /// 两条箭头会完全重叠，看起来像渲染重影；这时不画预览，画面语义反而更准确。
        /// </summary>
        public void RenderPreview(Vector3[] path)
        {
            Vector3[] current = AStarManager.Instance != null ? AStarManager.Instance.CurrentPathWorld : null;
            if (SamePath(path, current))
            {
                path = null;
            }
            _previewUsed = LayoutArrows(path, _previewPool, "PreviewArrow", PreviewColor, BoardSorting.PathArrow + 1);
            HideFrom(_previewPool, _previewUsed);
        }

        /// <summary>两条路径是否逐格相同（世界坐标误差 1e-4 内视为同一点）</summary>
        private static bool SamePath(Vector3[] a, Vector3[] b)
        {
            if (a == null || b == null)
            {
                return a == b;
            }
            if (a.Length != b.Length)
            {
                return false;
            }
            for (int i = 0; i < a.Length; i++)
            {
                if ((a[i] - b[i]).sqrMagnitude > 0.0001f)
                {
                    return false;
                }
            }
            return true;
        }

        /// <summary>
        /// 把路径摆成箭头，返回用掉的箭头数。
        /// 真实路径与预览路径共用这一份布局逻辑 —— 两者几何必须完全一致，
        /// 复制两份迟早分叉（一处改了缩放/朝向，另一处忘了改）。
        /// </summary>
        private int LayoutArrows(Vector3[] path, List<SpriteRenderer> pool, string namePrefix,
            Color color, int sortingOrder)
        {
            if (path == null || path.Length < 2 || _arrowSprite == null)
            {
                return 0;
            }

            float cellSize = BoardView.Instance != null ? BoardView.Instance.CellSize : 1f;

            // 只画中间段：起点格显示为出生点、终点格显示为终点，画箭头反而看不清
            int used = 0;
            for (int i = 0; i < path.Length - 1; i++)
            {
                Vector2 cur = path[i];
                Vector2 next = path[i + 1];
                Vector2 dir = next - cur;
                if (dir.sqrMagnitude < 0.0001f)
                {
                    continue;
                }

                // 在格子之间插一个箭头（指向下一格），避免每格都画导致视觉噪杂
                SpriteRenderer sr = GetArrow(pool, namePrefix, used, color, sortingOrder);
                if (sr == null)
                {
                    break;
                }
                Vector2 mid = (cur + next) * 0.5f;
                sr.transform.position = new Vector3(mid.x, mid.y, 0f);
                // 按精灵原生尺寸折算，自适应任何格子边长与箭头图分辨率
                float s = cellSize * ArrowScale / _arrowNativeSize;
                sr.transform.localScale = new Vector3(s, s, 1f);

                float angle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
                sr.transform.localRotation = Quaternion.Euler(0f, 0f, angle - 90f);
                sr.gameObject.SetActive(true);
                used++;
            }
            return used;
        }

        private SpriteRenderer GetArrow(List<SpriteRenderer> pool, string namePrefix, int index,
            Color color, int sortingOrder)
        {
            while (pool.Count <= index)
            {
                GameObject go = new GameObject(namePrefix + pool.Count);
                go.transform.SetParent(_root != null ? _root : transform, false);
                SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
                sr.sprite = _arrowSprite;
                sr.sortingLayerName = BoardSorting.LayerMain;
                sr.sortingOrder = sortingOrder;
                sr.color = color;
                go.SetActive(false);
                pool.Add(sr);
            }
            return pool[index];
        }

        private static void HideFrom(List<SpriteRenderer> pool, int index)
        {
            for (int i = index; i < pool.Count; i++)
            {
                if (pool[i] != null && pool[i].gameObject.activeSelf)
                {
                    pool[i].gameObject.SetActive(false);
                }
            }
        }

        public void Clear()
        {
            HideFrom(_pool, 0);
            HideFrom(_previewPool, 0);
            _used = 0;
            _previewUsed = 0;
        }

        public int VisibleCount { get { return _used; } }

        /// <summary>预览箭头可见数量（自检/测试用：预览是否真的画出来了）</summary>
        public int VisiblePreviewCount { get { return _previewUsed; } }
    }
}

using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// main 场景的**组合根**（Composition Root）。
    ///
    /// 为什么单独要这个类：Unity 的 prefab/场景序列化字段散落在各个组件上，
    /// 一旦某个引用漏连，往往要到运行时某个随机时刻才以 NullReference 的形式暴露。
    /// 把所有场景引用集中在这里、在 Awake 里一次性校验并注入给 GameFlowManager，
    /// 出错时能立刻给出"哪个引用没连"的明确报错。
    ///
    /// 该脚本与全部引用由「Tools ? 塔防 ? 搭建 main 场景」自动生成并连线，
    /// 一般情况下不需要手动改。
    /// </summary>
    public class GameSceneLauncher : MonoBehaviour
    {
        [Header("流程")]
        public GameFlowManager flowManager;

        [Header("视图")]
        public BoardView boardView;
        public PathArrowView pathArrowView;

        [Header("层级容器")]
        public Transform boardRoot;
        public Transform pathRoot;
        public Transform towerRoot;
        public Transform enemyRoot;
        public Transform bulletRoot;

        private void Awake()
        {
            if (!Validate())
            {
                enabled = false;
                return;
            }

            // 注入流程管理器
            flowManager.boardView = boardView;
            flowManager.pathArrowView = pathArrowView;
            flowManager.boardRoot = boardRoot;
            flowManager.pathRoot = pathRoot;
            flowManager.towerRoot = towerRoot;
            flowManager.enemyRoot = enemyRoot;
            flowManager.bulletRoot = bulletRoot;

            StartCoroutine(EnsureReporterWhenResourcesReady());
        }

        private System.Collections.IEnumerator EnsureReporterWhenResourcesReady()
        {
            // Direct main-scene entry initializes the resource loader asynchronously.
            // Reporter.Awake loads its icons immediately, so wait for that contract first.
            double deadline = Time.realtimeSinceStartupAsDouble + 120d;
            while (!ResLoader.Instance.IsReady)
            {
                if (Time.realtimeSinceStartupAsDouble >= deadline)
                {
                    Debug.LogError("[Scene] Reporter 初始化超时：资源系统 120 秒内未就绪。请检查此前的资源启动错误。");
                    yield break;
                }
                yield return null;
            }
            EnsureReporter();
        }

        /// <summary>
        /// 挂上 Reporter 调试控制台（真机上**画圈或双击**调出，看日志/内存/FPS）。
        ///
        /// 【为什么动态挂而不是进场景】Reporter 脚本在热更程序集
        /// （FTProject.ThirdParty.Reporter）里 —— 挂进 Build Settings 场景会在打包时
        /// 被烘焙成空壳（HybridCLR 限制，见 BootLoader 注释）；放 prefab 里也没人
        /// 实例化它。动态 AddComponent 时热更 dll 已加载（main 场景加载的前提），
        /// 组件能正常工作。Reporter 的 Awake 会自建 UI（Initialized 默认 false）。
        ///
        /// 【为什么要注入图片加载器】Reporter 的 images 字段原本靠编辑器菜单
        /// 「Reporter/Create」填充并随场景序列化；动态挂载没有这一步，images 为空会
        /// 让 Initialize 抛 NullReferenceException、初始化中断，面板永远打不开
        /// （2026-10-14 模拟器实测定位）。这里把图片接到工程统一资源链路
        /// （ResTable Reporter_* → 编辑器 AssetDatabase / 真机 YooAsset AB，
        /// 收集器 ReporterData 组），加载失败时 Reporter 内部退化为占位图，不崩。
        /// **必须在 AddComponent 之前注入**：AddComponent 会同步触发 Awake。
        /// </summary>
        private void EnsureReporter()
        {
            // Reporter 是全局命名空间的 MonoBehaviour（无命名空间），直接泛型挂载。
            // 【注意】必须用泛型 AddComponent —— 官方已知问题：字符串重载
            // GetComponent/AddComponent 对热更脚本不可靠。
            if (GetComponent<Reporter>() != null)
            {
                return;
            }
            // 跨场景守卫：main 场景若被重载，旧 Reporter 已 DontDestroyOnLoad 常驻，
            // 不要再挂第二个（重复注册日志回调会让每条日志记两遍；且 Reporter 的
            // "第二实例自删"逻辑会连本物体一起 Destroy，必须在这里拦住）。
            if (Reporter.Instance != null)
            {
                return;
            }

            Reporter.ImageLoader = LoadReporterIcon;
            Reporter.ScrollerSkinLoader = LoadReporterScrollerSkin;

            // 原版 Reporter prefab 同一物体上自带 ReporterMessageReceiver
            // （OnPreStart 按分辨率调面板尺寸 + OnShow/OnHide/OnLog 用户钩子）。
            // 动态挂载时漏掉它，SendMessage("OnPreStart") 等会报 "no receiver" 警告
            // （恢复原版契约；OnLog 一侧的死循环隐患另在 Reporter.cs 用
            // DontRequireReceiver 釜底抽薪）。
            if (GetComponent<ReporterMessageReceiver>() == null)
            {
                gameObject.AddComponent<ReporterMessageReceiver>();
            }
            // Reporter.Awake synchronously sends OnPreStart; its receiver must already exist.
            gameObject.AddComponent<Reporter>();
            Debug.Log("[Scene] Reporter 调试控制台已挂载（画圈或双击调出）");
        }

        /// <summary>Reporter 图标（逻辑名见 ResTable 的 Reporter_* 段；失败返回 null，由 Reporter 兜底占位）</summary>
        private static Texture2D LoadReporterIcon(string name)
        {
            return ResLoader.Instance.Load<Texture2D>("Reporter_" + name);
        }

        /// <summary>Reporter 滚动条皮肤（失败返回 null，由 Reporter 兜底为空 GUISkin）</summary>
        private static GUISkin LoadReporterScrollerSkin()
        {
            return ResLoader.Instance.Load<GUISkin>("Reporter_scrollerSkin");
        }

        private bool Validate()
        {
            bool ok = true;
            ok &= Check(flowManager, "flowManager");
            ok &= Check(boardView, "boardView");
            ok &= Check(pathArrowView, "pathArrowView");
            ok &= Check(boardRoot, "boardRoot");
            ok &= Check(pathRoot, "pathRoot");
            ok &= Check(towerRoot, "towerRoot");
            ok &= Check(enemyRoot, "enemyRoot");
            ok &= Check(bulletRoot, "bulletRoot");

            if (!ok)
            {
                Debug.LogError(
                    "[Scene] GameSceneLauncher 存在未连线的引用，流程已停止。\n" +
                    "  修复：菜单「Tools ? 塔防 ? 搭建 main 场景」重新生成场景，" +
                    "或手工把缺失的引用拖到 Inspector 对应槽位。");
            }
            return ok;
        }

        private static bool Check(Object o, string name)
        {
            if (o == null)
            {
                Debug.LogError("[Scene] 引用未连线：" + name);
                return false;
            }
            return true;
        }
    }
}

using System;
using System.Collections;
using UnityEngine;
using FTProject.AOT;

namespace FTProject
{
    public class HotUpdateEntry : IHotUpdateEntry
    {
        public static bool Started { get; private set; }
        private static bool _entering;
        public void Start()
        {
            if (Started) return;
            Started = true;
            Debug.Log("[BootSequence] DLLReady");
        }
        public void EnterMainScene(Action<bool, string> onResult)
        {
            if (_entering) { onResult(false, "Scene entry already running"); return; }
            _entering = true;
            ResLoaderRunner.Start(EnterMainCo(onResult));
        }
        private IEnumerator EnterMainCo(Action<bool, string> onResult)
        {
            try
            {
                while (true)
                {
                    bool initialized = false;
                    BootUpdateSession.Report("Initializing", .4f);
                    ResLoader.Instance.Init(() => initialized = true);
                    while (!initialized) yield return null;
                    if (ResLoader.Instance.IsReady) break;
                    var loader = ResLoader.Instance as YooAssetResLoader;
                    bool retry = false;
                    BootUpdateSession.Report("Failed", .4f, -1, loader?.LastInitError ?? "Resource initialization failed");
                    BootUpdateSession.Controls(retry: () => retry = true);
                    while (!retry) yield return null;
                    BootUpdateSession.Controls();
                    if (loader == null) { onResult(false, "No safe resource rebuild provider"); yield break; }
                    var destroy = loader.BeginRetryDestroy();
                    while (destroy != null && !destroy.IsDone) yield return null;
                    loader.CompleteRetryRebuild();
                }
                bool gated = false;
                BootHotUpdateGate.Run(() => gated = true);
                while (!gated) yield return null;
                BootUpdateSession.Controls();
                Debug.Log("[BootSequence] Main");
                ResLoader.Instance.LoadSceneAsync("Assets/Scenes/Main.unity", onResult);
            }
            finally { _entering = false; }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using FTProject.AOT;

namespace FTProject
{
    // Main owns configuration/game initialization, then Splash, then the game-ready event.
    public class Launcher : MonoBehaviour
    {
        public enum BootPhase { Loading, HotUpdate, Splash, Ready, Failed }
        public BootPhase Phase { get; private set; }
        public bool IsBootComplete { get; private set; }
        public static Launcher Instance { get; private set; }
        private const int ConfigLoadMaxAttempts = 3;
        private const float ConfigLoadRetryDelaySec = 3f;
        private int _configLoadAttempts;
        private bool _configBusy;
        private readonly List<IManagerInterface> _managers = new List<IManagerInterface>
        {
            AStarManager.Instance,
            // 存档最早初始化：它的设置要在 AudioManager 起来后立刻生效（见 Awake 末尾）
            SaveManager.Instance,
            PlayerDataManager.Instance,
            EnemyManager.Instance,
            BulletManager.Instance,
            TowerManager.Instance,
            CombatSystem.Instance,
            UIManager.Instance,
            // 音效放最后：它依赖 Configs（TBAudio 表）与 ResLoader，
            // 但两项都是"用到时才查"，早注册晚注册都不影响正确性，放在末尾更符合阅读顺序。
            AudioManager.Instance,
        };

        private bool _booted;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Debug.LogWarning("[Launcher] 场景中存在多个 Launcher，已销毁后出现的那个");
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);

            Screen.orientation = ScreenOrientation.AutoRotation;
            Screen.autorotateToPortrait = false;
            Screen.autorotateToPortraitUpsideDown = false;
            Screen.autorotateToLandscapeLeft = true;
            Screen.autorotateToLandscapeRight = true;

            for (int i = 0; i < _managers.Count; i++)
            {
                _managers[i].OnInit();
            }

            // M5-3：性能探针常驻（只在按 F3 / 到达自动打印间隔时才输出，平时零日志）
            PerfProbe.Ensure();

            // 所有管理器就绪后，把存档里的设置推给音频系统。
            // 【为什么放在循环之后】SaveManager 读档时 AudioManager 可能还没 OnInit，
            // 那时 ApplyToAudio 会因为 Instance 还没准备好而空转。
            SaveManager.Instance.ApplyToAudio();
        }

        private void Start()
        {
            if (_booted)
            {
                return;
            }
            _booted = true;
            BootResAndConfig();
        }

        /// <summary>
        /// 启动链（UI 补全 §5.1 重写）。
        ///
        /// 【旧实现的两个问题】
        ///   ① 全程黑屏静默：ResLoader.Init → Configs.LoadAsync 是纯嵌套回调，没有任何界面；
        ///   ② 没有热更新：发版后无法更新资源，只能整包重发。
        ///
        /// 【进度口径】LoadingView 只显示 [0,1] 的**总进度**，各阶段权重见常量：
        ///   资源系统 → 0.30；配置表 → 0.90；收尾 → 1.00；热更新有自己的界面与进度条，不占本进度。
        /// </summary>
        private void BootResAndConfig()
        {
            Debug.Log(VersionInfo.BuildLogSummary());
            StartCoroutine(PrepareMain());
        }
        private IEnumerator PrepareMain()
        {
            // Direct Main in the editor uses the same ordering and waits for resource readiness.
            if (!ResLoader.Instance.IsReady)
            {
                UIManager.Instance.Open<HotUpdateView>("HotUpdateView", UILayout.NormalPanel);
                BootUpdateSession.Report("Initializing", .4f);
                bool done = false;
                ResLoader.Instance.Init(() => done = true);
                while (!done) yield return null;
                if (!ResLoader.Instance.IsReady)
                {
                    Phase = BootPhase.Failed;
                    BootUpdateSession.Report("Failed", .4f, -1, "Resource initialization failed");
                    BootUpdateSession.Controls(retry: () => StartCoroutine(PrepareMain()));
                    yield break;
                }
            }
            BeginHotUpdate();
        }
        private void BeginHotUpdate(bool forceRecheck = false)
        {
            if (!forceRecheck && BootHotUpdateGate.Completed) { BeginLoadingConfig(); return; }
            Phase = BootPhase.HotUpdate;
            UIManager.Instance.Close("LoadingView");
            UIManager.Instance.Open<HotUpdateView>("HotUpdateView", UILayout.NormalPanel);
            BootUpdateSession.Report("Resources", .45f);
            var hot = ResLoader.HotUpdate;
            if (hot == null) { ShowFailure("Resource verifier unavailable", () => BeginHotUpdate(forceRecheck)); return; }
            hot.StartCheckUpdate(
                phase => BootUpdateSession.Report("Resources", .45f),
                (cur, total) => BootUpdateSession.Progress(cur, total, 0, 0),
                (bytes, totalBytes) => BootUpdateSession.Progress(BootUpdateSession.Files, BootUpdateSession.TotalFiles, bytes, totalBytes),
                error => ShowFailure(error, () => BeginHotUpdate(forceRecheck)),
                updated => BeginLoadingConfig());
        }
        public void RetryHotUpdate() { if (Phase == BootPhase.Failed) BeginHotUpdate(true); }
        private void ShowFailure(string error, System.Action retry)
        {
            Phase = BootPhase.Failed;
            Debug.LogWarning("[Launcher] Startup stopped: " + error);
            UIManager.Instance.Close("LoadingView");
            UIManager.Instance.Open<HotUpdateView>("HotUpdateView", UILayout.NormalPanel);
            BootUpdateSession.Report("Failed", .9f, -1, error);
            BootUpdateSession.Controls(retry: retry);
        }
        private void BeginLoadingConfig()
        {
            if (_configBusy) return;
            if (!LanguageManager.PrepareStartup())
            {
                ShowFailure("Localization resources missing", () => BeginHotUpdate(true)); return;
            }
            Phase = BootPhase.Loading;
            BootUpdateSession.Controls();
            UIManager.Instance.Close("HotUpdateView");
            var loading = UIManager.Instance.Open<LoadingView>("LoadingView", UILayout.NormalPanel);
            if (loading == null) { ShowFailure("LoadingView missing from active resource release", () => BeginHotUpdate(true)); return; }
            Debug.Log("[BootSequence] LoadingView");
            _configBusy = true;
            Configs.LoadAsync(
                (done, total) => PublishLoading(Localization.Get("Loading config...") ?? "Loading config...", total > 0 ? .1f + .8f * done / total : .1f),
                ok =>
                {
                    _configBusy = false;
                    if (Debug.isDebugBuild && ResLoader.Instance is YooAssetResLoader diagnostics)
                        Debug.Log("[BootDiagnostics] Config attempt=" + (_configLoadAttempts + 1) + " ok=" + ok + " " + diagnostics.Diagnostics());
                    if (!ok) { HandleConfigLoadFailed(); return; }
                    LanguageManager.Initialize(SaveManager.Instance);
                    CombatSystem.Instance.RebuildGridFromConfig();
                    try { if (BootReleaseStore.Selected != null) BootReleaseStore.Commit(); }
                    catch (System.Exception e) { ShowFailure(e.Message, () => BeginHotUpdate(true)); return; }
                    PublishLoading(Localization.Get("Ready") ?? "Ready", 1f);
                    StartCoroutine(FinishLoading());
                });
        }
        private static void PublishLoading(string phase, float progress)
        {
            EventDispatcher.TriggerEvent<string, float>(EventName.LoadingProgressEvent, phase, progress);
        }
        private void HandleConfigLoadFailed()
        {
            _configLoadAttempts++;
            if (_configLoadAttempts < ConfigLoadMaxAttempts)
            {
                PublishLoading(Localization.Get("Config load failed, retrying...") ?? "Config load failed, retrying...", -.1f);
                StartCoroutine(RetryConfigLoadCo());
                return;
            }
            ShowFailure("Configuration failed after 3 attempts: " + string.Join(", ", Configs.FailedTables), () =>
            {
                _configLoadAttempts = 0;
                BeginHotUpdate(true);
            });
        }
        private IEnumerator RetryConfigLoadCo()
        {
            yield return new WaitForSecondsRealtime(ConfigLoadRetryDelaySec);
            // Never advance to another release after its DLLs have been loaded.
            // Reverify/repair only the pinned resource version, preserving bounded config retries.
            BeginHotUpdate(forceRecheck: true);
        }
        private IEnumerator FinishLoading()
        {
            yield return new WaitForSecondsRealtime(.25f);
            UIManager.Instance.Close("LoadingView");
            Phase = BootPhase.Splash;
            EventDispatcher.AddEventListener(EventName.SplashFinishedEvent, OnSplashFinished);
            if (UIManager.Instance.Open<SplashView>("SplashView", UILayout.NormalPanel) == null)
            {
                EventDispatcher.RemoveEventListener(EventName.SplashFinishedEvent, OnSplashFinished);
                ShowFailure("SplashView missing from active resource release", () => StartCoroutine(FinishLoading()));
                yield break;
            }
            Debug.Log("[BootSequence] SplashView");
        }
        private void OnSplashFinished()
        {
            EventDispatcher.RemoveEventListener(EventName.SplashFinishedEvent, OnSplashFinished);
            UIManager.Instance.Close("SplashView");
            Phase = BootPhase.Ready;
            IsBootComplete = true;
            Debug.Log("[BootSequence] GameReady");
            EventDispatcher.TriggerEvent<bool>(EventName.ConfigLoadedEvent, true);
        }
        private void Update()
        {
            TimerManager.Instance.Update(Time.deltaTime);
            // CombatSystem 是唯一的 UpdateEvent 订阅者（见 CombatSystem.OnInit）
            EventDispatcher.TriggerEvent(EventName.UpdateEvent);
        }

        private void OnDestroy()
        {
            if (Instance != this)
            {
                return;
            }
            EventDispatcher.RemoveEventListener(EventName.SplashFinishedEvent, OnSplashFinished);
            BootUpdateSession.Controls();
            for (int i = 0; i < _managers.Count; i++)
            {
                _managers[i].OnDestroy();
            }
            Instance = null;
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// Image 多语言组件 —— 挂在带 `Image` 的节点上，按当前语言切换 Sprite。
    ///
    /// 【用法 · 两套并行机制（显式引用优先）】
    ///   ① **每语言直填引用**（enSprite / zhHansSprite / zhHantSprite）—— 传统用法，
    ///      填了就走它，与旧行为完全一致；
    ///   ② **key 驱动**（`key` 字段）—— 填了 key（或留空走"原值当 key"，见下）后，
    ///      用 key 去多语言表查**图片资源名**，再按资源名加载 Sprite。
    ///
    /// 【key 为空时"原值当 key"指什么】
    ///   Image 没有文本，所以"原值"取 **Image.sprite 的资源名**（如 `UI_Btn_Primary`）；
    ///   若 sprite 也为空，再退到**节点名**（`gameObject.name`）。
    ///   这和多语言表"英文原文即 key"的约定同构：资源名即 key。
    ///
    /// 【回退】key 查不到 / 该语言留空 → 回退英文 → 再回退 prefab 原 Sprite。
    ///
    /// 【为什么保留"每语言直填引用"】工程里 Sprite 是 prefab 的直接依赖
    ///   （UIPrefabBuilder 生成时烘 sprite 的写法），直填引用符合现有惯例，
    ///   且免去再维护一张图片映射表的成本。key 驱动是给"想统一走表"的场景用的补充。
    /// </summary>
    [RequireComponent(typeof(Image))]
    [DisallowMultipleComponent]
    public class ImageLocalizer : MonoBehaviour
    {
        [Tooltip("多语言表的 key（英文原文）。留空则自动用 Image.sprite 资源名，再回退节点名。")]
        public string key;

        [Tooltip("英文（默认语言）用图。也作为其它语言的回退图。")]
        [SerializeField] private Sprite enSprite;

        [Tooltip("简体中文用图。留空则回退英文。")]
        [SerializeField] private Sprite zhHansSprite;

        [Tooltip("繁体中文用图。留空则回退英文。")]
        [SerializeField] private Sprite zhHantSprite;

        private Image _image;
        private Sprite _originalSprite;
        private bool _subscribed;

        private void Awake()
        {
            _image = GetComponent<Image>();
            if (_image != null)
            {
                _originalSprite = _image.sprite;
            }
        }

        private void OnEnable()
        {
            Refresh();
            Subscribe();
        }

        private void OnDisable()
        {
            Unsubscribe();
        }

        private void Subscribe()
        {
            if (_subscribed)
            {
                return;
            }
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = true;
        }

        private void Unsubscribe()
        {
            if (!_subscribed)
            {
                return;
            }
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = false;
        }

        private void OnLanguageChanged(int lang)
        {
            Refresh();
        }

        /// <summary>
        /// 解析本组件该用的 key：
        ///   ① 显式 key 非空 → 用它；
        ///   ② 否则用 Image.sprite 的资源名（`UI_Btn_Primary`）；
        ///   ③ sprite 也为空 → 用节点名（`gameObject.name`）。
        /// ⚠️ 取 sprite 名用 **_originalSprite**（Awake 缓存的原图），
        ///   不用 `_image.sprite`：刷新过之后它已是本语言的图，
        ///   再拿它当 key 会"查一次译文再查表"层层套娃。
        /// </summary>
        public string ResolveKey()
        {
            if (!string.IsNullOrEmpty(key))
            {
                return key;
            }
            if (_originalSprite != null && !string.IsNullOrEmpty(_originalSprite.name))
            {
                return _originalSprite.name;
            }
            return gameObject.name;
        }

        /// <summary>按当前语言刷新 Sprite（幂等，可外部调用）。</summary>
        public void Refresh()
        {
            if (_image == null)
            {
                return;
            }

            Sprite s = Pick(LanguageManager.Current);
            if (s == null)
            {
                s = enSprite;   // 回退英文
            }
            if (s == null)
            {
                // 显式引用全空 → 走 key 驱动：key → 资源名 → ResLoader 加载
                s = LoadByKey(ResolveKey(), LanguageManager.Current);
            }
            if (s != null)
            {
                _image.sprite = s;
            }
            else if (_originalSprite != null)
            {
                _image.sprite = _originalSprite;
            }
        }

        private Sprite Pick(Language lang)
        {
            switch (lang)
            {
                case Language.ChineseSimplified:  return zhHansSprite;
                case Language.ChineseTraditional: return zhHantSprite;
                default:                          return enSprite;
            }
        }

        /// <summary>
        /// key → 资源名 → Sprite。
        ///
        /// 【查表口径】与文本同构：key 先去多语言表取"该语言下的资源名"；
        ///   取不到就用 key 本身当资源名（因为表的 id 就是英文资源名/原文）。
        /// 【资源名 → Sprite】走 ResTable 的逻辑名（唯一寻址源），例如
        ///   `UI_TowerIcon_Normal` → Assets/_UIAssets/UI/UI_TowerIcon_Normal.png。
        ///   取不到就返回 null，由调用方回退到 prefab 原图（"零破坏"）。
        /// </summary>
        private Sprite LoadByKey(string k, Language lang)
        {
            if (string.IsNullOrEmpty(k))
            {
                return null;
            }
            if (!ResLoader.Instance.IsReady)
            {
                return null;    // 引导期资源系统未就绪 → 回退原图
            }

            string resName = LanguageManager.GetText(k);
            if (string.IsNullOrEmpty(resName))
            {
                resName = k;    // 表里没有这条 → key 本身即资源名
            }

            return ResLoader.Instance.Load<Sprite>(resName);
        }
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 多语言总门面（静态类，热更层）。
    ///
    /// 职责：
    ///   1. 持有"当前语言"，并在切换时广播 <see cref="EventName.LanguageChangedEvent"/>
    ///   2. 从多语言配置表构建 key→文本 字典（<see cref="LocalizationLookup"/>）
    ///   3. 对外提供**不抛异常**的取词 / 取字体接口
    ///
    /// 【取词回退链】当前语言 → 英文 → null（null 由调用方回退到原文本）。
    /// 【为什么不抛异常】多语言表可能不全、可能还没加载；界面绝不能因为缺一个 key 就崩。
    ///   所以所有接口在"未就绪/找不到"时一律返回 null，最多打印一条限流警告。
    /// </summary>
    public static class LanguageManager
    {
        /// <summary>ResTable/YooAsset 中的本地化配置逻辑地址。</summary>
        private const string SettingsPath = "LocalizationSettings";

        private static LocalizationSettings _settings;
        private static LocalizationLookup _lookup;

        /// <summary>已经 Warn 过的 key（限流，避免同一个缺失 key 把 Console 刷爆）。</summary>
        private static readonly HashSet<string> _warned = new HashSet<string>();

        /// <summary>当前语言。默认英文（硬兜底），Initialize/SetLanguage 会改写它。</summary>
        public static Language Current { get; private set; } = Language.English;

        /// <summary>是否已完成 Initialize（表已构建）。</summary>
        public static bool IsReady { get; private set; }

        /// <summary>配置资产（懒加载）。可能为 null（资产缺失时）。</summary>
        public static LocalizationSettings Settings
        {
            get { EnsureSettings(); return _settings; }
        }

        // ------------------------------------------------------------------
        // 生命周期
        // ------------------------------------------------------------------

        /// <summary>
        /// 启动时调用一次：确定语言 + 构建字典。
        /// 调用时机：`Launcher` 里 `Configs.LoadAsync` 完成之后、广播 ConfigLoadedEvent 之前。
        /// </summary>
        /// <param name="save">存档管理器（可空）。有玩家显式选择时优先用存档里的语言。</param>
        public static bool PrepareStartup()
        {
            if (!ResLoader.Instance.IsReady) return false;
            _settings = ResLoader.Instance.Load<LocalizationSettings>(SettingsPath);
            var table = ResLoader.Instance.Load<TextAsset>("tblocalization");
            if (_settings == null || table == null) return false;
            try
            {
                var raw = new cfg.TBLocalization(SimpleJSON.JSONNode.Parse(table.text));
                _lookup = new LocalizationLookup();
                _lookup.Build(raw);
                FTProject.AOT.BootLocalization.Initialize();
                Current = FTProject.AOT.BootLocalization.HasSelection ? FTProject.AOT.BootLocalization.Current : SafeLanguage(_settings.defaultLanguage);
                IsReady = true;
                _warned.Clear();
                EventDispatcher.TriggerEvent<int>(EventName.LanguageChangedEvent, (int)Current);
                Debug.Log("[BootSequence] LocalizationReady " + Current + " entries=" + _lookup.Count);
                if (Debug.isDebugBuild) Debug.Log("[Localization] default=" + _settings.defaultLanguage
                    + " saved=" + FTProject.AOT.BootLocalization.HasSelection + " font=" + GetFont(Current)?.name
                    + " supported=" + (_settings.supportedLanguages == null ? "(fallback)" : string.Join(",", _settings.supportedLanguages)));
                return true;
            }
            catch (System.Exception e) { Debug.LogWarning("[Loc] Startup table invalid: " + e.Message); return false; }
        }

        public static void Initialize(SaveManager save)
        {
            EnsureSettings();

            // 优先级：存档用户选择 → 配置默认语言 → 英文（硬兜底）
            Language lang = Language.English;
            if (save != null && save.TryGetLanguage(out lang))
            {
                // 用了存档里的选择
            }
            else if (_settings != null)
            {
                lang = _settings.defaultLanguage;
            }
            Current = lang;

            RefreshLookup();
            IsReady = true;
            EventDispatcher.TriggerEvent<int>(EventName.LanguageChangedEvent, (int)Current);

            Debug.Log(string.Format("[Loc] 语言初始化完成：{0}（多语言表 {1} 条）",
                Current, _lookup != null ? _lookup.Count : 0));
        }

        /// <summary>从当前配置表重新构建字典。配置表加载完 / 热更替换表之后调用。</summary>
        public static void RefreshLookup()
        {
            if (_lookup == null)
            {
                _lookup = new LocalizationLookup();
            }
            _lookup.Build(Configs.LocalizationTable);
        }

        /// <summary>
        /// 切换语言：写存档 + 广播事件。
        /// 所有 TextLocalizer / ImageLocalizer 订阅了事件，会自动刷新，这里不必遍历场景。
        /// </summary>
        public static void SetLanguage(Language lang)
        {
            lang = SafeLanguage(lang);
            if (Current == lang)
            {
                return;
            }
            Current = lang;
            FTProject.AOT.BootLocalization.Remember(lang);

            SaveManager sm = SaveManager.Instance;
            if (sm != null)
            {
                sm.SetLanguage(lang);
            }

            EventDispatcher.TriggerEvent<int>(EventName.LanguageChangedEvent, (int)lang);
        }

        // ------------------------------------------------------------------
        // 取词
        // ------------------------------------------------------------------

        /// <summary>取词。回退：当前语言 → 英文 → null。</summary>
        public static string GetText(string key)
        {
            if (string.IsNullOrEmpty(key) || _lookup == null)
            {
                return null;
            }

            LocEntry e;
            if (!_lookup.TryGet(key, out e))
            {
                return null;
            }

            string s = e.Get(Current);
            if (string.IsNullOrEmpty(s))
            {
                s = e.En;   // 该语言为空 → 回退英文
            }
            return string.IsNullOrEmpty(s) ? null : s;
        }

        /// <summary>
        /// 带占位符取词：命中则 string.Format。
        /// 未命中 / 格式串与参数不匹配时返回 null（调用方回退原文本）。
        /// </summary>
        public static string GetText(string key, params object[] args)
        {
            string fmt = GetText(key);
            if (fmt == null)
            {
                return null;
            }
            if (args == null || args.Length == 0)
            {
                return fmt;
            }
            try
            {
                return string.Format(fmt, args);
            }
            catch (System.FormatException)
            {
                Debug.LogWarning(string.Format("[Loc] 文案 key「{0}」占位符与参数不匹配：{1}", key, fmt));
                if (_lookup != null && _lookup.TryGet(key, out LocEntry fallback) && !string.IsNullOrEmpty(fallback.En))
                {
                    try { return string.Format(fallback.En, args); }
                    catch (System.FormatException) { }
                }
                return null;
            }
        }

        // ------------------------------------------------------------------
        // 字体
        // ------------------------------------------------------------------

        /// <summary>取某语言的 TMP 字体；未配置返回 null（调用方判空后跳过设字体，避免设成 null 变方块）。</summary>
        public static TMP_FontAsset GetFont(Language lang)
        {
            EnsureSettings();
            return _settings != null ? (_settings.GetFont(lang) ?? _settings.GetFont(Language.English)) : null;
        }

        /// <summary>
        /// 把"当前语言的字体"应用到一段文本 —— 给**不走 TextLocalizer 的手动拼词文本**用
        /// （各 View 标题、HUD 状态行等；TextLocalizer.Refresh 内部做的就是同样的事）。
        /// 【为什么集中在这里】避免每个 View 各抄一份"取字体 → 判空 → 赋值"，
        ///   也让"以后加新语言要配字体"只需要改配置资产这一处。
        /// 字体为 null（该语言没配字体）时静默跳过：宁可沿用旧字体，也不能设成 null 变方块。
        /// </summary>
        public static void ApplyFont(TMP_Text text)
        {
            if (text == null)
            {
                return;
            }
            TMP_FontAsset font = GetFont(Current);
            if (font != null && text.font != font)
            {
                text.font = font;
            }
        }

        // ------------------------------------------------------------------
        // 诊断
        // ------------------------------------------------------------------

        /// <summary>限流警告：同一个 key 只报一次。</summary>
        public static void WarnMissingKeyOnce(string key)
        {
            if (string.IsNullOrEmpty(key) || _warned.Contains(key))
            {
                return;
            }
            _warned.Add(key);
            Debug.LogWarning(string.Format("[Loc] 多语言表缺少 key：「{0}」（已回退原文本）", key));
        }

        /// <summary>
        /// 确保配置资产已加载（幂等）。
        /// 【为什么 public】界面在"记录/取字体"时不一定会先走 Initialize
        ///   （例如 LevelLoadingMask 在极早期就自建文本节点），需要一个显式的加载入口；
        ///   内部有 _settings != null 短路，重复调用零成本。
        /// </summary>
        public static void EnsureSettings()
        {
            if (_settings != null)
            {
                return;
            }
            if (ResLoader.Instance.IsReady) _settings = ResLoader.Instance.Load<LocalizationSettings>(SettingsPath);
        }

        private static Language SafeLanguage(Language language)
        {
            return System.Enum.IsDefined(typeof(Language), language) ? language : Language.English;
        }
    }
}

namespace FTProject
{
    /// <summary>
    /// 多语言取词快捷入口（业务层主要用它）。
    ///
    /// 等价于 <see cref="LanguageManager.GetText"/>，但更短、更好读：
    /// <code>
    /// SetText(label, Localization.Get("Start") ?? "开始");
    /// SetText(round, Localization.Get("Round {0}", idx) ?? string.Format("回合 {0}", idx));
    /// </code>
    ///
    /// 【零破坏约定】所有 Get 在"未命中/表未就绪"时返回 null，
    /// 调用方一律用 `?? 原文` 兜底 —— 这样即使多语言表不全，界面也照旧显示旧文案，不会空白。
    /// </summary>
    public static class Localization
    {
        public static string Get(string key)
        {
            return LanguageManager.GetText(key);
        }

        public static string Get(string key, params object[] args)
        {
            return LanguageManager.GetText(key, args);
        }

        /// <summary>当前语言（只读）。</summary>
        public static Language Current
        {
            get { return LanguageManager.Current; }
        }

        /// <summary>
        /// 关卡显示名（2026-10-16 多语言审计新增）。
        /// 【背景】SceneInfo 表里的 name 是"关卡 N"形态的**中文单一语言数据** ——
        ///   英文/繁体界面下直接透传会出现"中文关卡名"。界面统一改用词条
        ///   "Level {0}" 按 id 格式化（Level 2 / 关卡 2 / 關卡 2）。
        /// 【将来若把关卡名升级为专名】把这里演进为"查表 name"即可，调用点不用动。
        /// </summary>
        public static string LevelName(int levelId, string fallback)
        {
            return LanguageManager.GetText("Level {0}", levelId) ?? fallback;
        }
    }
}

using System.Collections.Generic;

namespace FTProject
{
    /// <summary>一条多语言记录（语言无关的载体）。</summary>
    public struct LocEntry
    {
        public string En;
        public string ZhHans;
        public string ZhHant;

        /// <summary>取指定语言的文本；当前未支持的语言回退英文。</summary>
        public string Get(Language lang)
        {
            switch (lang)
            {
                case Language.ChineseSimplified:  return ZhHans;
                case Language.ChineseTraditional: return ZhHant;
                default:                          return En;
            }
        }
    }

    /// <summary>
    /// key → 多语言文本 的运行时字典。
    ///
    /// 【存在意义】Luban 表 `TBLocalization` 的 `DataList` 只能顺序遍历，
    /// 而 UI 每次取词都是按 key 随机查 —— 建一次字典把查询变成 O(1)。
    /// 【谁负责重建】LanguageManager.RefreshLookup()，在配置表加载完之后调用。
    /// </summary>
    public sealed class LocalizationLookup
    {
        private readonly Dictionary<string, LocEntry> _map = new Dictionary<string, LocEntry>();

        public int Count { get { return _map.Count; } }

        /// <summary>从 Luban 表构建字典。传 null / 空表时不抛异常，只得到空字典。</summary>
        public void Build(cfg.TBLocalization raw)
        {
            _map.Clear();
            if (raw == null || raw.DataList == null)
            {
                return;
            }

            for (int i = 0; i < raw.DataList.Count; i++)
            {
                cfg.Localization r = raw.DataList[i];
                if (r == null || string.IsNullOrEmpty(r.Id))
                {
                    continue;
                }

                LocEntry e;
                e.En = r.En;
                e.ZhHans = r.ZhHans;
                e.ZhHant = r.ZhHant;
                // 重名 key 直接覆盖（不抛异常），与 Configs/AudioTable 的处理风格一致
                _map[r.Id] = e;
            }
        }

        public bool TryGet(string key, out LocEntry entry)
        {
            return _map.TryGetValue(key, out entry);
        }
    }
}

using TMPro;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// TMP 文本本地化组件 —— 直接挂在带 `TMP_Text` 的节点上。
    ///
    /// 【用法 · 两种 key 来源】
    ///   ① 在 Inspector 的 `key` 字段填一个 key；
    ///   ② **留空** —— 此时组件自动拿**本节点上 TMP 已序列化的文本内容当 key**
    ///      （prefab 里的静态英文原文即 key，见下）。
    ///
    /// 【为什么支持"文本内容即 key"】
    ///   多语言表（`Localization.xlsx`）的主键就是**英文原文本身**（id == en）。
    ///   于是"给 TMP 填英文原文"和"给它一个 key"是同一件事 ——
    ///   prefab 里天然写的就是英文原文，组件只要把它当 key 查一下表即可，
    ///   Inspector 里不必再手工抄一遍 key（少一处会写岔的地方）。
    ///
    /// 【回退链】显式 key（若填了）→ 节点文本内容 → 都查不到时保留原文/打警告。
    ///
    /// 【字体】刷新文本的同时，按当前语言设 `TMP_Text.font`（这是"根据语言切字体"的落点）。
    ///
    /// 【什么时候不该用它】运行时才知道参数的动态文本（如"回合 {0}"）——
    ///   这类文本由 View 代码用 `Localization.Get(key, args)` 主动赋值，不要挂本组件。
    /// </summary>
    [RequireComponent(typeof(TMP_Text))]
    [DisallowMultipleComponent]
    public class TextLocalizer : MonoBehaviour
    {
        [Tooltip("多语言表的 key（英文原文，如 Start）。留空则自动用本节点 TMP 的文本内容当 key。")]
        public string key;

        [Tooltip("查不到 key 时，是否保留 prefab 里序列化的原文。")]
        [SerializeField] private bool fallbackToOriginalText = true;

        private TMP_Text _text;
        private string _originalText;
        private bool _subscribed;

        /// <summary>运行时读写 key（改了会立即刷新）。留空即走"文本内容当 key"。</summary>
        public string Key
        {
            get { return key; }
            set
            {
                if (key == value)
                {
                    return;
                }
                key = value;
                Refresh();
            }
        }

        private void Awake()
        {
            _text = GetComponent<TMP_Text>();
            // 缓存 prefab 原文作为回退基线（只记一次；刷新后 text 会被改写，不能靠它再取）
            if (_text != null && _originalText == null)
            {
                _originalText = _text.text;
            }
        }

        private void OnEnable()
        {
            Refresh();
            Subscribe();
        }

        private void OnDisable()
        {
            Unsubscribe();
        }

        private void Subscribe()
        {
            if (_subscribed)
            {
                return;
            }
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = true;
        }

        private void Unsubscribe()
        {
            if (!_subscribed)
            {
                return;
            }
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = false;
        }

        private void OnLanguageChanged(int lang)
        {
            Refresh();
        }

        /// <summary>
        /// 解析本组件该用的 key：
        ///   ① 显式 key 非空 → 用它；
        ///   ② 否则用本节点 TMP 的**序列化原文**（_originalText，即 prefab 里的英文）；
        ///   ③ 都拿不到 → null（调用方走回退）。
        /// ⚠️ 必须用 _originalText 而不是 _text.text：刷新过一次之后
        ///   _text.text 已是译文，再拿它当 key 会"查一次译文再查表"层层套娃。
        /// </summary>
        public string ResolveKey()
        {
            if (!string.IsNullOrEmpty(key))
            {
                return key;
            }
            return string.IsNullOrEmpty(_originalText) ? null : _originalText;
        }

        /// <summary>按当前语言刷新文本与字体（幂等，可外部调用）。</summary>
        public void Refresh()
        {
            if (_text == null)
            {
                return;
            }

            // ① 字体先跟随语言（即使本文本未命中 key，字体也要对）
            TMP_FontAsset font = LanguageManager.GetFont(LanguageManager.Current);
            if (font != null && _text.font != font)
            {
                _text.font = font;
            }

            // ② 文本
            string resolved = ResolveKey();
            if (string.IsNullOrEmpty(resolved))
            {
                return;
            }

            string value = LanguageManager.GetText(resolved);
            if (value != null)
            {
                _text.text = value;
            }
            else if (fallbackToOriginalText && _originalText != null)
            {
                _text.text = _originalText;
            }
            else
            {
                LanguageManager.WarnMissingKeyOnce(resolved);
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 波次管理器（P0-8）。
    ///
    /// 【设计要点】把"回合 → 多个波次编组 → 每组的若干怪物与间隔"在回合开始时
    /// **一次性展开成一条扁平的 (时刻, 怪物id) 时间轴**，之后只用一个累加计时器推进。
    ///
    /// 为什么不用每只怪一个 TimerManager 定时器：
    ///   v1.0 用 `TimerManager.AddTimer(interval, count, cb)` 递归补时，
    ///   一波 40 只怪就是 40 个定时器，且 TimerManager 用 `Time.fixedDeltaTime` 驱动
    ///   （Launcher 里传的正是 fixedDeltaTime），改帧率后波次节奏会漂。
    ///   单计时器 + 时间轴是 O(n) 且与帧率无关。
    ///
    /// 【单位】时间轴统一用秒（表里是毫秒，展开时换算）。
    /// </summary>
    public class WaveManager
    {
        /// <summary>时间轴上的一个出生点</summary>
        private struct SpawnEntry
        {
            public float TimeSec;
            public int EnemyId;
            /// <summary>所属波次编组在回合内的序号（从 0 计）</summary>
            public int GroupIndex;
        }

        private readonly List<SpawnEntry> _timeline = new List<SpawnEntry>(256);
        private readonly List<float> _groupStartTime = new List<float>(16);
        private readonly List<bool> _groupCleared = new List<bool>(16);

        private RoundConfig _round;
        private float _timer;
        private int _cursor;
        private bool _running;
        private bool _allSpawned;

        public bool IsRunning { get { return _running; } }
        public bool AllSpawned { get { return _allSpawned; } }
        public int SpawnedCount { get { return _cursor; } }
        public int TotalCount { get { return _timeline.Count; } }
        public int GroupCount { get { return _groupStartTime.Count; } }
        public RoundConfig Round { get { return _round; } }

        /// <summary>当前波次序号（从 0 计，供 UI 显示）</summary>
        public int CurrentGroupIndex { get; private set; }

        /// <summary>时间轴总时长（秒），供 UI 显示进度</summary>
        public float TotalDurationSec
        {
            get { return _timeline.Count > 0 ? _timeline[_timeline.Count - 1].TimeSec : 0f; }
        }

        // ------------------------------------------------------------------
        // 回合开始
        // ------------------------------------------------------------------

        /// <summary>
        /// 开始一个回合：展开时间轴并复位。
        /// 若配置有缺失（例如某波次 id 不存在），跳过该组并告警，不阻塞其余内容 ——
        /// 符合"功能缺失不应阻塞实现"的要求。
        /// </summary>
        public void BeginRound(RoundConfig round)
        {
            _round = round;
            _timeline.Clear();
            _groupStartTime.Clear();
            _groupCleared.Clear();
            _timer = 0f;
            _cursor = 0;
            _allSpawned = false;
            CurrentGroupIndex = -1;

            if (round == null || round.WaveIds == null || round.WaveIds.Count == 0)
            {
                Debug.LogWarning("[Wave] 回合配置为空，本回合不会有怪物");
                _running = false;
                _allSpawned = true;
                return;
            }

            // 回合自身的准备时间（StartDelayMs）作为时间轴起点
            float offset = round.StartDelayMs > 0 ? round.StartDelayMs / 1000f : 0f;
            int groupIndex = 0;

            for (int i = 0; i < round.WaveIds.Count; i++)
            {
                int waveId = round.WaveIds[i];
                WaveGroupConfig group = Configs.GetWaveGroup(waveId);
                if (group == null || group.EnemyIds == null || group.EnemyIds.Count == 0)
                {
                    Debug.LogWarning(string.Format(
                        "[Wave] 回合 {0} 的第 {1} 个波次（id={2}）无有效怪物，已跳过", round.Id, i, waveId));
                    continue;
                }

                // 相对回合开始的绝对时刻
                float groupStart = offset + group.StartDelayMs / 1000f;
                float gap = group.SpawnIntervalSec;

                _groupStartTime.Add(groupStart);
                _groupCleared.Add(false);

                for (int k = 0; k < group.EnemyIds.Count; k++)
                {
                    SpawnEntry e;
                    e.TimeSec = groupStart + gap * k;
                    e.EnemyId = group.EnemyIds[k];
                    e.GroupIndex = groupIndex;
                    _timeline.Add(e);
                }

                // 下一组的偏移以本组结束时间为基准（各组 Interval 通常已是相对回合开始，
                // 这里取"本组最后一只是时刻 + 一个间隔"与"下一组自身延迟"的最大值，避免重叠）
                float groupEnd = groupStart + gap * Mathf.Max(1, group.EnemyIds.Count - 1);
                offset = Mathf.Max(offset, groupEnd + gap);
                groupIndex++;
            }

            if (_timeline.Count == 0)
            {
                Debug.LogWarning(string.Format("[Wave] 回合 {0} 展开后没有任何怪物", round.Id));
                _running = false;
                _allSpawned = true;
                return;
            }

            _timeline.Sort(CompareEntry);
            _running = true;

            Debug.Log(string.Format(
                "[Wave] 回合 {0} 开始：{1} 个波次 / {2} 只怪 / 时间轴 {3:F1} 秒",
                round.Id, _groupStartTime.Count, _timeline.Count, TotalDurationSec));
        }

        private static int CompareEntry(SpawnEntry a, SpawnEntry b)
        {
            return a.TimeSec.CompareTo(b.TimeSec);
        }

        public void Stop()
        {
            _running = false;
        }

        // ------------------------------------------------------------------
        // 推进
        // ------------------------------------------------------------------

        /// <summary>推进计时器并按时间轴生成怪物</summary>
        public void Tick(float dt)
        {
            if (!_running)
            {
                return;
            }

            _timer += dt;

            while (_cursor < _timeline.Count && _timer >= _timeline[_cursor].TimeSec)
            {
                SpawnEntry e = _timeline[_cursor];

                // 进入新的波次编组 → 广播（HUD 可据此显示"第 N 波"）
                if (e.GroupIndex != CurrentGroupIndex)
                {
                    CurrentGroupIndex = e.GroupIndex;
                    EventDispatcher.TriggerEvent<int>(EventName.WaveStartEvent, CurrentGroupIndex + 1);
                }

                BaseEnemy spawned = EnemyManager.Instance.Spawn(e.EnemyId);
                if (spawned == null)
                {
                    // Capacity is transient. Keep this exact timeline item for a later frame.
                    if (EnemyManager.Instance.LastSpawnFailure == EnemyManager.SpawnFailure.Capacity)
                    {
                        var run = GameFlowManager.Instance != null ? GameFlowManager.Instance.RunMetrics : null;
                        if (run != null && run.waves.Count > 0) run.waves[run.waves.Count - 1].spawnDeferredCount++;
                        break;
                    }
                    _running = false;
                    if (GameFlowManager.Instance != null) GameFlowManager.Instance.InvalidateRun("Spawn failed: " + EnemyManager.Instance.LastSpawnFailure);
                    return;
                }
                _cursor++;
            }

            if (_cursor >= _timeline.Count)
            {
                _allSpawned = true;
                _running = false;
            }
        }

        /// <summary>
        /// 回合是否已结束：全部出生完毕且场上无存活怪物。
        /// aliveCount 由调用方传入（取自 CombatSystem），避免本类依赖战斗系统。
        /// </summary>
        public bool IsRoundFinished(int aliveCount)
        {
            return _allSpawned && aliveCount <= 0;
        }

        /// <summary>
        /// 检查并广播波次清空。
        /// 判定：该组的怪已全部出生 且 场上无存活（简单可靠，M0 够用）。
        /// </summary>
        public void CheckGroupCleared(int aliveCount)
        {
            if (aliveCount > 0 || _timeline.Count == 0)
            {
                return;
            }
            for (int g = 0; g < _groupCleared.Count; g++)
            {
                if (_groupCleared[g])
                {
                    continue;
                }
                // 该组是否还有未出生的怪
                bool fullySpawned = true;
                for (int i = 0; i < _timeline.Count; i++)
                {
                    if (_timeline[i].GroupIndex == g && i >= _cursor)
                    {
                        fullySpawned = false;
                        break;
                    }
                }
                if (fullySpawned)
                {
                    _groupCleared[g] = true;
                    EventDispatcher.TriggerEvent<int>(EventName.WaveClearEvent, g + 1);
                }
            }
        }

        public string DumpDebugInfo()
        {
            return string.Format("[Wave] 回合={0} 波次={1} 已出生={2}/{3} 波内序号={4} 运行中={5}",
                _round != null ? _round.Id : 0, _groupStartTime.Count,
                _cursor, _timeline.Count, CurrentGroupIndex + 1, _running);
        }
    }
}

using System.Collections.Generic;
using AStar;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 塔型。编号与 TBTowerInfo.type 一一对应（2026-10-14 收敛定案的**三类**）。
    ///
    /// 【命名与行为的偏差，只在这里解释一次】
    ///   · Aoe(2) 是美术名「Power/强力塔」（火力塔），其**行为**是范围伤害 —— 见 TBTowerInfo.effectType=3；
    ///   · Slow(3) 的行为是**范围减速光环**（进入射程的怪持续被减速，不发射子弹），
    ///     而美术、节点名、资源目录一律叫 "Retard"
    ///     （映射表在 HudView.TowerTypeOf，别处不要再推导一遍）。
    ///
    /// 【2026-10-14 三塔型收敛】原 Pierce(4)/Laser(5) 已整体删除
    /// （表行、子弹、音效、图标、文档同步清理）；塔型若要扩展，从配置表加行开始。
    /// </summary>
    public enum TowerType
    {
        None = 0,
        /// <summary>单体：普通塔。可攻击**飞行与行走**两类怪物（canAttackAir=1）</summary>
        Normal = 1,
        /// <summary>范围伤害：火力塔（美术名 Power，行为是 AOE）。**仅能攻击行走怪物**（canAttackAir=0）</summary>
        Aoe = 2,
        /// <summary>减速：美术名 Retard。**行为是范围光环**（见 SlowAuraView），不发射子弹；飞行与行走都覆盖（canAttackAir=1）</summary>
        Slow = 3,
    }

    /// <summary>
    /// 防御塔基类（v2.1 的 2D 版）。
    ///
    /// 相对 v1.0 的关键改动：
    ///   - 去掉 Renderer/GetComponentsInChildren 换色 → 改 SpriteRenderer.color
    ///   - **攻击逻辑抽出为 TickAttack(dt)，由 CombatSystem 集中驱动**（不再自行订阅 UpdateEvent）
    ///   - 索敌走 EnemyGrid 空间哈希 + 节流 + 目标锁定（不再用 SphereCollider / OnTriggerEnter）
    ///   - **对空优先**：能打飞行单位的塔，射程内有飞行怪就先打飞行怪，没有才打地面（2026-10-21）
    ///   - **无目标绝不开火**（v1.0 是每 0.2s 无条件空放）
    ///   - 塔头转向目标；数值全部来自 TBTowerInfo
    /// </summary>
    public class BaseTower : MonoBehaviour
    {
        public TowerConfig Config { get; private set; }
        public CellData Cell { get; private set; }
        public bool IsBuilt { get; private set; }

        /// <summary>自检计数（CombatSystem 汇总，用于验证"空放为 0"）</summary>
        public int SearchCount { get; set; }
        public int FireCount { get; set; }
#if UNITY_EDITOR
        // Evidence counters never participate in combat or rating decisions.
        public double EvidenceDamage, EvidenceOverkill;
        public int EvidenceHits, EvidenceSlowApplications, EvidenceAirHits;
        public static bool EvidenceTrackReentry;
        public int EvidenceRepeatedEnemyEffects;
        private struct RangeEvidence { public bool inside; public int entry, affectedEntry; }
        private Dictionary<long, RangeEvidence> _rangeEvidence = new Dictionary<long, RangeEvidence>();
        private HashSet<long> _repeatedEvidence = new HashSet<long>();

        internal void CopyRangeEvidenceFrom(BaseTower old)
        {
            EvidenceRepeatedEnemyEffects = old.EvidenceRepeatedEnemyEffects;
            _rangeEvidence = new Dictionary<long, RangeEvidence>(old._rangeEvidence);
            _repeatedEvidence = new HashSet<long>(old._repeatedEvidence);
        }

        public void ObserveEvidenceRange(BaseEnemy enemy)
        {
            if (!enemy.IsAlive) return;
            RangeEvidence state;
            _rangeEvidence.TryGetValue(enemy.EvidenceSpawnSerial, out state);
            bool inside = InRange(enemy);
            if (inside && !state.inside) state.entry++;
            state.inside = inside;
            _rangeEvidence[enemy.EvidenceSpawnSerial] = state;
        }

        private void RecordEvidenceEffect(BaseEnemy enemy)
        {
            if (!EvidenceTrackReentry) return;
            RangeEvidence state;
            if (!_rangeEvidence.TryGetValue(enemy.EvidenceSpawnSerial, out state)) return;
            if (state.affectedEntry > 0 && state.entry > state.affectedEntry && _repeatedEvidence.Add(enemy.EvidenceSpawnSerial))
                EvidenceRepeatedEnemyEffects++;
            state.affectedEntry = state.entry;
            _rangeEvidence[enemy.EvidenceSpawnSerial] = state;
        }
#endif

        private BaseEnemy _target;
        private float _fireTimer;
        private float _searchTimer;
        private readonly List<BaseEnemy> _candidates = new List<BaseEnemy>(32);
        private Transform _barrel;
        private Transform _muzzle;
        private SpriteRenderer[] _renderers;
        private Vector2 _lastDir = Vector2.right;

        private const float MinRotateStep = 0.5f;

        // ---- 减速光环（Slow / 美术名 Retard）----
        /// <summary>
        /// 减速时长的额外余量（秒）：实际时长 = 塔的冷却间隔 + 本值。
        /// 取 0.1s，刷新周期之外只保留短暂的离场缓冲，
        /// 又不至于让玩家觉得"明明出圈了还慢"。
        /// </summary>
        private const float SlowAuraLingerSec = 0.1f;

        /// <summary>光环命中时的视觉脉冲时长（秒），每次结算触发一次。</summary>
        private const float AuraPulseSec = 0.15f;
        private float _auraPulseTimer;
        private SlowAuraView _auraView;

        // ---- 开火后坐（M4-3）----
        /// <summary>炮管后坐距离（世界单位）。要小到"几乎看不见但能感觉到"。</summary>
        private const float RecoilDistance = 0.07f;
        /// <summary>后坐回位时长（秒）</summary>
        private const float RecoilDurationSec = 0.09f;
        private float _recoilTimer;
        private Vector3 _barrelBasePos;
        private bool _barrelBaseCached;

        // ---- 开火序列帧（2026-10-17 表现改版）----
        /// <summary>
        /// 枪口焰播放器（挂在炮管下的子物体，随炮管旋转）。
        /// 普通塔/火力塔开火时重放一遍；减速光环塔不挂（永不开火）。
        /// </summary>
        private TowerFireFx _muzzleFx;

        /// <summary>
        /// 炮管贴图**自身画朝哪个方向**（Unity 角度，0°=右、90°=上）。
        ///
        /// 【为什么需要这个偏移】`Atan2(y,x)` 算出的角是"0°=右"，
        /// 而旋转是作用在贴图上的 —— 两者之间差一个"贴图原生朝向"。
        /// 本工程的炮管贴图（turret_barrel_128.png）是**竖着画**的：上窄下宽、枪口朝上，
        /// 即原生朝向 90°。所以实际要转的角度 = 目标角 - 90°。
        ///
        /// 【怎么量出来的】把贴图降采样成 ASCII 图看形状：枪口（窄端）在图像顶部。
        /// 这类美术事实从代码/节点名推不出来，必须看图。
        /// 换炮管美术时若朝向不对，改这一个常数即可。
        /// </summary>
        private const float BarrelNativeAngle = 90f;

        // ------------------------------------------------------------------
        // 初始化
        // ------------------------------------------------------------------

        public void Init(TowerConfig cfg, CellData cell)
        {
            Config = cfg;
            Cell = cell;
            IsBuilt = true;
            _fireTimer = 0f;
            _searchTimer = 0f;
            _target = null;
            SearchCount = 0;
            FireCount = 0;
#if UNITY_EDITOR
            EvidenceDamage = EvidenceOverkill = 0;
            EvidenceHits = EvidenceSlowApplications = EvidenceAirHits = 0;
            EvidenceRepeatedEnemyEffects = 0; _rangeEvidence.Clear(); _repeatedEvidence.Clear();
#endif

            if (_renderers == null)
            {
                // 只做缓存（SetTint / 预览半透明要用），**不再改写 sortingOrder**：
                // 塔根节点已挂 SortingGroup，子渲染器用的是组内相对序号（0=炮座 / 1=炮管）。
                // 旧的「< Tower 就抬到 Tower」规则会把炮座与炮管压成同一层，破坏相对层次；
                // 塔的全局位置现在由根节点的组序 BoardSorting.Tower 决定。
                _renderers = GetComponentsInChildren<SpriteRenderer>(true);
            }
            if (_barrel == null)
            {
                _barrel = transform.Find("barbette/Img_gun");
                if (_barrel == null)
                {
                    _barrel = transform.Find("Img_gun");
                }
            }
            if (_muzzle == null && _barrel != null)
            {
                _muzzle = _barrel.Find("BarrelPoint");
            }
            SetTint(Color.white);

            // 非光环塔挂枪口焰播放器（幂等：已挂则复用；光环塔不索敌不开火，不挂）
            if (!cfg.IsSlowAura && _barrel != null)
            {
                _muzzleFx = TowerFireFx.AttachMuzzle(_barrel, _muzzle);
            }

            // 减速塔：挂一个光环表现（射程圈 + 命中脉冲），并常亮显示射程
            if (cfg.IsSlowAura)
            {
                if (_auraView == null)
                {
                    _auraView = SlowAuraView.Attach(transform, cfg.RadiusWorld);
                }
                else
                {
                    _auraView.SetRadius(cfg.RadiusWorld);
                }
                if (_auraView != null)
                {
                    _auraView.SetVisible(true);
                }
            }
            else if (_auraView != null)
            {
                _auraView.SetVisible(false);
            }
            _auraPulseTimer = 0f;
        }

        public Vector2 Position
        {
            get { Vector2 p = transform.position; return p; }
        }

        /// <summary>Capture combat phases as well as the layout at an enemy-free boundary.</summary>
        public void CaptureCheckpointState(TowerSnapshot snapshot)
        {
            snapshot.runtimeStateSaved = true;
            snapshot.fireTimer = _fireTimer; snapshot.searchTimer = _searchTimer;
            snapshot.recoilTimer = _recoilTimer; snapshot.auraPulseTimer = _auraPulseTimer;
            snapshot.lastDirection = _lastDir;
            snapshot.barrelPoseSaved = _barrel != null;
            snapshot.barrelBaseCached = _barrel != null && _barrelBaseCached;
            if (_barrel != null)
            {
                snapshot.barrelLocalPosition = _barrel.localPosition;
                snapshot.barrelLocalRotation = _barrel.localRotation;
                snapshot.barrelBasePosition = _barrelBasePos;
            }
        }

        public bool RestoreCheckpointState(TowerSnapshot snapshot)
        {
            if (snapshot == null || !snapshot.HasValidRuntimeState() || snapshot.barrelPoseSaved != (_barrel != null)) return false;
            _fireTimer = snapshot.fireTimer; _searchTimer = snapshot.searchTimer;
            _recoilTimer = snapshot.recoilTimer; _auraPulseTimer = snapshot.auraPulseTimer;
            _lastDir = snapshot.lastDirection; _target = null; _candidates.Clear();
            _barrelBaseCached = snapshot.barrelBaseCached; _barrelBasePos = snapshot.barrelBasePosition;
            if (_barrel != null) { _barrel.localPosition = snapshot.barrelLocalPosition; _barrel.localRotation = snapshot.barrelLocalRotation; }
            return true;
        }

        private Vector2 MuzzlePosition
        {
            get
            {
                if (_muzzle != null)
                {
                    Vector2 m = _muzzle.position;
                    return m;
                }
                return Position;
            }
        }

        // ------------------------------------------------------------------
        // 每帧（由 CombatSystem 驱动）
        // ------------------------------------------------------------------

        public void TickAttack(float dt)
        {
            if (!IsBuilt || Config == null)
            {
                return;
            }

            // ① 光环塔（减速）：逻辑与普通塔完全不同 —— 不索敌、不转向、不开火，
            //    只是把射程内的**所有**敌人持续施加减速。单独一条支路，避免
            //    在下面那条"锁定单目标"的流程里塞 if，两者语义本就不同。
            if (Config.IsSlowAura)
            {
                TickSlowAura(dt);
                return;
            }

            // ② 目标有效性检查：死亡/回收/走出射程 → 立即解除锁定
            if (_target != null && (!_target.IsAlive || !InRange(_target)))
            {
                _target = null;
            }

            // ③ 节流索敌
            //    · 无锁定 → 整圈找：飞行单位优先，没有飞行单位才选地面；
            //    · 已锁定**地面**目标 → 每个节拍复查一次，只要圈里有飞行单位就立刻抢断
            //      （否则塔会一直咬着地面怪，飞行怪整队从头顶溜过去 —— 这正是本次需求的由来）。
            //    · 已锁定飞行目标 → 不再复查，保持地面目标原有的"锁定不抖动"手感。
            _searchTimer += dt;
            if (_searchTimer >= Config.SearchIntervalSec)
            {
                _searchTimer = 0f;
                if (_target == null)
                {
                    _target = FindTarget();
                }
                else if (Config.CanAttackAir && !IsFlying(_target))
                {
                    BaseEnemy air = FindAirTarget();
                    if (air != null)
                    {
                        _target = air;
                    }
                }
            }

            if (_target == null)
            {
                return;   // ★ 无目标绝不开火
            }

            // ④ 塔头转向 + 后坐回位
            RotateBarrelTowards(_target.Position, dt);
            TickRecoil(dt);

            // ⑤ 冷却结束才开火
            _fireTimer += dt;
            if (_fireTimer < Config.CooldownSec)
            {
                return;
            }
            _fireTimer = 0f;
            Fire(_target);
        }

        /// <summary>
        /// 减速光环：把射程内全部存活敌人施加/刷新减速。
        ///
        /// 【为什么按冷却间隔结算，而不是每帧刷】每帧调用 ApplySlow 会把怪的
        /// _slowTimer 一直顶在满值，那么"离开光环后该多久恢复"就取决于帧率 ——
        /// 用冷却间隔（CD）作为**施加节拍**，时长取 CD + 一个固定余量，
        /// 于是"站在光环里 = 一直被减速，走出去 0.x 秒后恢复"这件事是确定的。
        ///
        /// 【为什么不做目标列表缓存】减速塔射程内的怪随时进出，缓存要维护增删，
        /// 而空间哈希查询本身就是常数级 —— 直接查更简单也更不容易出错。
        ///
        /// 【对空规则与普通塔同一口径（2026-10-14 三塔型收敛）】
        /// 飞行单位是否吃光环，同样由塔表 canAttackAir 决定（减速塔填 1，行为不变）。
        /// 这样"这座塔能不能打到飞行怪"在代码里**只有一条判定**（FindTarget 与此处相同），
        /// 不会出现塔型分支各说各话。目标模式不在此过滤 —— 那是"选哪个目标打"的概念，
        /// 光环没有选择行为，范围内一律结算。
        ///
        /// 【不参与"对空优先"（2026-10-21 确认）】光环没有单目标，射程内的飞行与地面
        /// 一律同时结算，"优先打飞行"在这里没有落点。**不要**为了对齐而加
        /// "圈里有飞行就跳过地面"的分支 —— 那会白白削掉地面减速，属于改坏而不是改好。
        /// </summary>
        private void TickSlowAura(float dt)
        {
            _fireTimer += dt;
            if (_fireTimer < Config.CooldownSec)
            {
                return;
            }
            _fireTimer = 0f;

            CombatSystem cs = CombatSystem.Instance;
            if (cs == null || cs.Grid == null)
            {
                return;
            }

            float radius = Config.RadiusWorld;
            _candidates.Clear();
            cs.Grid.QueryCircle(Position, radius, _candidates);
            if (_candidates.Count == 0)
            {
                return;
            }

            float r2 = radius * radius;
            Vector2 self = Position;
            float ratio = Config.EffectValue;          // 配置中的减速比例
            float duration = Config.CooldownSec + SlowAuraLingerSec;
            int applied = 0;
            for (int i = 0; i < _candidates.Count; i++)
            {
                BaseEnemy e = _candidates[i];
                if (e == null || !e.IsAlive)
                {
                    continue;
                }
                // 对空过滤：与 FindTarget 同一条口径 —— 本塔打不到飞行单位时直接跳过
                if (e.Config != null && e.Config.IsFlying && !Config.CanAttackAir)
                {
                    continue;
                }
                // 网格查询会带出圆形包围盒外的元素，这里精确过滤成圆形射程
                if ((e.Position - self).sqrMagnitude > r2)
                {
                    continue;
                }
                e.ApplySlow(ratio, duration);
#if UNITY_EDITOR
                EvidenceSlowApplications++;
                RecordEvidenceEffect(e);
#endif
                applied++;
            }

            // 有怪被减速才算"开火"，供自检区分"空放"与"有效作用"
            if (applied > 0)
            {
                FireCount++;
                _auraPulseTimer = AuraPulseSec;   // 触发一次视觉脉冲
            }
        }

        /// <summary>
        /// 光环表现的每帧推进（脉冲渐隐）。**独立于结算节拍** ——
        /// 结算每 CD 才跑一次，而渐隐必须每帧推进，否则脉冲会"跳"没。
        /// 由 CombatSystem 的 TickTowers 每帧调用（与 TickAttack 并列）。
        /// </summary>
        public void TickVisual(float dt)
        {
            if (_auraView == null)
            {
                return;
            }
            if (_auraPulseTimer > 0f)
            {
                _auraPulseTimer -= dt;
                if (_auraPulseTimer < 0f)
                {
                    _auraPulseTimer = 0f;
                }
            }
            _auraView.SetPulse(_auraPulseTimer / AuraPulseSec);
        }

        /// <summary>
        /// 开火后坐：炮管沿自身"向后"退一点再回位。
        ///
        /// 【为什么要乘 localRotation】炮管是跟着目标转的，直接改 localPosition.y
        /// 在后坐方向上就错了（转 90° 时变成横着平移）。
        /// 正确做法是把"本地朝下"这个方向用炮管自身的旋转转换到父空间
        /// —— 炮管贴图原生朝上（见 BarrelNativeAngle），所以本地 -Y 就是"向后"。
        /// </summary>
        private void TickRecoil(float dt)
        {
            if (_barrel == null)
            {
                return;
            }
            if (!_barrelBaseCached)
            {
                _barrelBasePos = _barrel.localPosition;
                _barrelBaseCached = true;
            }
            if (_recoilTimer <= 0f)
            {
                return;
            }

            _recoilTimer -= dt;
            if (_recoilTimer <= 0f)
            {
                _recoilTimer = 0f;
                _barrel.localPosition = _barrelBasePos;
                return;
            }
            float k = Mathf.Clamp01(_recoilTimer / RecoilDurationSec);
            Vector3 back = _barrel.localRotation * Vector3.down;
            _barrel.localPosition = _barrelBasePos + back * (RecoilDistance * k);
        }

        private bool InRange(BaseEnemy e)
        {
            float r = Config.RadiusWorld;
            return (e.Position - Position).sqrMagnitude <= r * r;
        }

        /// <summary>本怪是否飞行（Config 缺失时按地面处理，与原对空过滤口径一致）</summary>
        private static bool IsFlying(BaseEnemy e)
        {
            return e != null && e.Config != null && e.Config.IsFlying;
        }

        /// <summary>空间哈希取候选 → 精确过滤 → 按 targetMode 打分 → 对空优先分层</summary>
        private BaseEnemy FindTarget()
        {
            return SelectBest(false);
        }

        /// <summary>只挑飞行单位（用于抢断已锁定的地面目标）</summary>
        private BaseEnemy FindAirTarget()
        {
            return SelectBest(true);
        }

        /// <summary>
        /// 选敌核心。
        ///
        /// 【对空优先（2026-10-21）】飞行单位与地面单位分成两层各自打分：
        /// 只要圈内存在本塔打得到的飞行单位，就在飞行层里按 targetMode 选，
        /// 地面层彻底不参与；没有飞行单位时才回落到地面层。
        /// 分层的意义：targetMode=0 的"最靠前"是按地面路径算的，
        /// 飞行怪走直线、没有 PathProgress，混在一起比分会把飞行怪永久压在地面怪后面。
        ///
        /// 【为什么按层而不是给分数加常数】加常数要挑一个"足够大"的值，
        /// 而 PathProgress / CurrentHp / 距离的量纲各不相同，迟早会被某个极端值穿透；
        /// 两个候选变量互不干扰，也不存在溢出与比较误差。
        /// </summary>
        /// <param name="flyingOnly">true = 只考虑飞行单位（抢断检查用）</param>
        private BaseEnemy SelectBest(bool flyingOnly)
        {
            CombatSystem cs = CombatSystem.Instance;
            if (cs == null || cs.Grid == null)
            {
                return null;
            }

            SearchCount++;
            cs.AddSearchCount(1);

            _candidates.Clear();
            cs.Grid.QueryCircle(Position, Config.RadiusWorld, _candidates);
            if (_candidates.Count == 0)
            {
                return null;   // ★ 空列表直接返回，杜绝 v1.0 的 IndexOutOfRange
            }

            float radius = Config.RadiusWorld;
            return PickBestTarget(_candidates, Position, radius * radius,
                Config.TargetMode, Config.CanAttackAir, flyingOnly);
        }

        /// <summary>
        /// 选敌策略本体：**纯函数**（不查场景、不读全局表），EditMode 可直接验证。
        /// 规则只有两条，按顺序生效：
        ///   ① 能否攻击飞行单位（塔表 canAttackAir）→ 打不到就直接剔除；
        ///   ② 对空优先 → 有可打的飞行单位就绝不选地面，层内再按 targetMode 打分。
        /// </summary>
        internal static BaseEnemy PickBestTarget(IList<BaseEnemy> candidates, Vector2 self, float radiusSqr,
            TargetMode targetMode, bool canAttackAir, bool flyingOnly)
        {
            if (candidates == null)
            {
                return null;
            }

            BaseEnemy bestAir = null;
            BaseEnemy bestGround = null;
            float bestAirScore = float.MinValue;
            float bestGroundScore = float.MinValue;

            for (int i = 0; i < candidates.Count; i++)
            {
                BaseEnemy e = candidates[i];
                if (e == null || !e.IsAlive)
                {
                    continue;
                }
                bool flying = IsFlying(e);
                // 对空过滤：本塔打不到飞行单位时**直接跳过**，
                // 而不是"锁一个打不到的目标然后空放"——那会让无目标开火的自检计数器爆掉。
                if (flying && !canAttackAir)
                {
                    continue;
                }
                if (flyingOnly && !flying)
                {
                    continue;
                }
                float d2 = (e.Position - self).sqrMagnitude;
                if (d2 > radiusSqr)
                {
                    continue;   // 网格查询会带出范围外元素，这里精确过滤
                }

                float score = ScoreCandidate(e, d2, targetMode);
                if (flying)
                {
                    if (score > bestAirScore)
                    {
                        bestAirScore = score;
                        bestAir = e;
                    }
                }
                else if (score > bestGroundScore)
                {
                    bestGroundScore = score;
                    bestGround = e;
                }
            }

            // ★ 对空优先：有能打的飞行单位就不选地面
            return bestAir != null ? bestAir : bestGround;
        }

        /// <summary>按塔表 targetMode 打分（口径与改造前完全一致，只是不再跨层比较）</summary>
        private static float ScoreCandidate(BaseEnemy e, float d2, TargetMode mode)
        {
            switch (mode)
            {
                case TargetMode.Nearest:
                    return -d2;
                case TargetMode.HighestHp:
                    return e.CurrentHp;
                default:
                    return e.PathProgress;   // 最危险优先
            }
        }

        private void RotateBarrelTowards(Vector2 targetPos, float dt)
        {
            Vector2 d = targetPos - Position;
            if (d.sqrMagnitude >= 0.000001f)
            {
                _lastDir = d.normalized;
            }
            if (_barrel == null)
            {
                return;
            }
            Vector2 bd = targetPos - (Vector2)_barrel.position;
            if (bd.sqrMagnitude < 0.000001f)
            {
                return;
            }
            float targetAngle = Mathf.Atan2(bd.y, bd.x) * Mathf.Rad2Deg - BarrelNativeAngle;
            Vector3 e = _barrel.localEulerAngles;
            float cur = e.z;
            float next = Mathf.MoveTowardsAngle(cur, targetAngle, Config.RotateSpeed * dt);
            if (Mathf.Abs(Mathf.DeltaAngle(cur, next)) >= MinRotateStep)
            {
                _barrel.localEulerAngles = new Vector3(e.x, e.y, next);
            }
        }

        /// <summary>
        /// 开火（冷却到点、有目标时由 TickAttack 调用）。
        ///
        /// 【2026-10-17 表现改版：移除真实子弹，《坚守阵地》式即时命中】
        ///   开火瞬间直接结算伤害，塔上只重放一段枪口焰序列帧（TowerFireFx）；
        ///   火力塔在落点补播爆炸序列帧。攻击节奏完全不变：
        ///   冷却间隔（CooldownSec）、索敌/锁定、伤害值（Power）、音效、后坐、震动全部照旧。
        ///   唯一的判定差异是"伤害不再等弹体飞行"——即时命中本来就是去掉真实子弹后的题中之义。
        ///
        /// 【为什么数值仍从子弹表取】aoeRadius / effectType / effectValue 的权威来源
        ///   依旧是 TBBulletData（见 BulletConfig 注释），这里只是把"弹体飞到落点才结算"
        ///   换成"开火瞬间在落点结算"，表驱动的方式没有变。
        /// </summary>
        private void Fire(BaseEnemy target)
        {
            _recoilTimer = RecoilDurationSec;   // M4-3：开火即后坐，回位在 TickRecoil 里推进

            // 屏幕震动（UI 补全 C3）：满级塔开火给一点"重火力"的手感。
            // 系数 0.15 —— 满级塔攻速不低，震感必须轻到"感觉得到但不烦人"。
            if (Config.Level >= 2 && CameraController.Instance != null && Configs.Global != null)
            {
                CameraController.Instance.Shake(
                    Configs.Global.ShakeAmplitude * 0.15f, Configs.Global.ShakeDurationSec);
            }

            // 减速光环塔走 TickSlowAura，永远不会到这里（与原 FiresBullet 口径一致的防御分支）
            if (!Config.FiresBullet)
            {
                return;
            }

            BulletConfig bulletCfg = Configs.GetBullet(Config.BulletId);
            if (bulletCfg == null)
            {
                return;
            }

            if (Config.IsAoe)
            {
                // 火力塔：落点 = 发射瞬间锁定的目标位置（与原"落点弹"锁定时机一致），
                // 对落点 aoeRadius（格）内全部存活敌人造成同等伤害 + 命中效果。
                Vector2 center = target.Position;
                DetonateAt(center, bulletCfg.AoeRadius, Config.Power, bulletCfg);
                // 爆炸的分量感：与原 BaseBullet.Explode 同系数 0.3（爆炸很频繁，晃多了没法玩）
                if (CameraController.Instance != null && Configs.Global != null)
                {
                    CameraController.Instance.Shake(
                        Configs.Global.ShakeAmplitude * 0.3f, Configs.Global.ShakeDurationSec);
                }
                TowerFireFx.PlayBlastAt(center);
            }
            else
            {
                // 普通塔：单体即时命中（原为追踪弹命中才结算，此处只去掉飞行环节）
                HurtEnemy(target, Config.Power, bulletCfg);
            }

            // 枪口焰序列帧（普通塔黄白细焰 / 火力塔橙红重焰）
            if (_muzzleFx != null)
            {
                _muzzleFx.PlayMuzzle(TowerFireFx.GetMuzzleFrames(Config.IsAoe));
            }
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.PlayAt(AudioName.TowerFire(Config.Type), MuzzlePosition);
            }
            FireCount++;
        }

        /// <summary>
        /// 对单个敌人结算一次伤害 + 命中效果（效果语义与 BaseBullet.ApplyEffect 同口径）。
        /// </summary>
        private void HurtEnemy(BaseEnemy e, float damage, BulletConfig bulletCfg)
        {
            if (e == null || !e.IsAlive)
            {
                return;
            }
#if UNITY_EDITOR
            float effective = damage * (1f - e.Config.Armor);
            EvidenceDamage += Mathf.Min(e.CurrentHp, effective);
            EvidenceOverkill += Mathf.Max(0, effective - e.CurrentHp);
            EvidenceHits++;
            RecordEvidenceEffect(e);
            if (e.Config.IsFlying) EvidenceAirHits++;
#endif
            e.Hurt(damage);
            CombatSystem.Instance.AddHitCount(1);
            ApplyHitEffect(e, bulletCfg.Effect,
                Config.EffectValue > 0f ? Config.EffectValue : bulletCfg.EffectValue);
        }

        /// <summary>
        /// 在落点引爆：对半径内可攻击的存活敌人造成伤害并施加效果。
        /// 与原 BaseBullet.Explode 同口径：范围从落点算，与落点上是否站怪无关。
        /// </summary>
        private void DetonateAt(Vector2 center, float radius, float damage, BulletConfig bulletCfg)
        {
            if (radius <= 0f)
            {
                return;
            }
            CombatSystem cs = CombatSystem.Instance;
            if (cs == null || cs.Grid == null)
            {
                return;
            }
            _candidates.Clear();
            cs.Grid.QueryCircle(center, radius, _candidates);
            float r2 = radius * radius;
            for (int i = 0; i < _candidates.Count; i++)
            {
                BaseEnemy e = _candidates[i];
                if (e == null || !e.IsAlive)
                {
                    continue;
                }
                // 命中集合与索敌使用同一对空规则，避免地面爆炸误伤贴近的飞行怪。
                if (e.Config == null || (e.Config.IsFlying && !Config.CanAttackAir))
                {
                    continue;
                }
                // 网格查询会带出范围外元素，精确过滤成圆形落点范围（与原实现一致）
                if ((e.Position - center).sqrMagnitude > r2)
                {
                    continue;
                }
                HurtEnemy(e, damage, bulletCfg);
            }
        }

        /// <summary>命中效果。与 BaseBullet.ApplyEffect 共用同一组时长常数（那里是唯一权威）。</summary>
        private void ApplyHitEffect(BaseEnemy e, EffectType effect, float effectValue)
        {
            switch (effect)
            {
                case EffectType.Slow:
                    e.ApplySlow(effectValue, BaseBullet.SlowDurationSec);
                    break;
                case EffectType.Dot:
                    e.ApplyDot(effectValue, BaseBullet.DotDurationSec);
                    break;
                default:
                    break;
            }
        }

        // ------------------------------------------------------------------
        // 表现
        // ------------------------------------------------------------------

        public void SetTint(Color c)
        {
            if (_renderers == null)
            {
                return;
            }
            for (int i = 0; i < _renderers.Length; i++)
            {
                if (_renderers[i] != null)
                {
                    _renderers[i].color = c;
                }
            }
        }

        public void SetPreviewAlpha(float a)
        {
            if (_renderers == null)
            {
                return;
            }
            for (int i = 0; i < _renderers.Length; i++)
            {
                if (_renderers[i] != null)
                {
                    Color c = _renderers[i].color;
                    c.a = a;
                    _renderers[i].color = c;
                }
            }
        }

        /// <summary>吸附到格子中心</summary>
        public void SnapToCell(CellData cell)
        {
            Cell = cell;
            transform.position = new Vector3(cell.Center.x, cell.Center.y, 0f);
        }

        public void MarkDestroyed()
        {
            IsBuilt = false;
            _target = null;
            // 枪口焰是挂在**炮管下**的子物体，随塔一起销毁；这里只清引用
            _muzzleFx = null;
            // 光环表现是挂在**塔自己**的 transform 上的子物体，随塔一起销毁；
            // 这里只把引用清掉，避免持有已销毁对象
            _auraView = null;
            _auraPulseTimer = 0f;
        }
    }

    /// <summary>
    /// 防御塔管理器：建塔（含路径校验与扣费）、出售、按格查询。
    /// v1.0 的 `GetTower&lt;T&gt;() where T : new()` 对 MonoBehaviour 是反模式，已废弃。
    ///
    /// 【注意】本类不是 MonoBehaviour（继承 BaseManager），可以与本文件共存；
    /// 而 NormalTower 是 MonoBehaviour，Unity 要求它与文件名一致，故放在 NormalTower.cs。
    /// </summary>
    public class TowerManager : BaseManager<TowerManager>
    {
        public Transform TowerParent { get; private set; }

        private readonly List<BaseTower> _towers = new List<BaseTower>(64);
        /// <summary>ClearAll 的复用缓冲（避免每次切关都分配一个 List）</summary>
        private readonly List<BaseTower> _clearBuf = new List<BaseTower>(64);

        public IList<BaseTower> Towers { get { return _towers; } }

        public void SetParent(Transform parent)
        {
            TowerParent = parent;
        }

        /// <summary>
        /// 尝试在指定格建塔。
        /// 顺序：占位校验 → 临时设墙跑 A*（堵死则回滚）→ 扣费 → 实例化。
        /// 任何一步失败都完整回滚，不会出现"扣了钱又建不成"。
        /// </summary>
        public BaseTower TryBuild(int type, int level, int row, int col)
        {
            return TryBuildInternal(type, level, row, col, true);
        }

        /// <summary>
        /// 按快照恢复一座塔（M3-5）：与 TryBuild 走**同一套**实例化/注册流程，
        /// 唯一区别是**不扣钱**（钱已经在上次游戏时扣过了）。
        ///
        /// 【为什么复用 TryBuildInternal 而不是另写一份】
        /// "建塔"这件事牵扯格子占用、A* 墙标记、战斗注册、对象池取出，
        /// 复制一份出来迟早会分叉 —— 而分叉点往往在某个不常走的分支上，很难发现。
        /// </summary>
        public BaseTower RestoreTower(int type, int level, int row, int col)
        {
            return TryBuildInternal(type, level, row, col, false);
        }

        private BaseTower TryBuildInternal(int type, int level, int row, int col, bool charge)
        {
            BoardView board = BoardView.Instance;
            if (board == null)
            {
                Debug.LogError("[Tower] BoardView 未初始化");
                return null;
            }

            CellData cell = board.GetCell(row, col);
            if (cell == null)
            {
                Tips(Localization.Get("No Tile Here") ?? "该位置无法建造");
                return null;
            }
            if (!cell.IsBuildable)
            {
                board.SetHighlight(row, col, CellHighlight.Blocked);
                Tips(Localization.Get("Not Buildable Here") ?? "该位置不可建造");
                return null;
            }
            if (cell.HasTower)
            {
                Tips(Localization.Get("Tower already there") ?? "该位置已有防御塔");
                return null;
            }

            TowerConfig cfg = Configs.GetTowerByTypeAndLevel(type, level);
            if (cfg == null)
            {
                return null;
            }

            // 【2026-10-22 规则调整】不再禁止"该格上正有怪物"。
            // 需求：只要建上去不会堵死路径就允许建 —— 怪物压在脚下属于玩家的正当操作
            // （补刀/围堵），落地后由本方法末尾的 RerouteEnemiesThrough 让它立刻走出去。

            AStarManager astar = AStarManager.Instance;
            Point point = astar.GetPoint(row, col);
            bool oldWall = point != null && point.IsWall;

            // ① 临时占位，校验不会把路完全堵死
            if (point != null)
            {
                point.IsWall = true;
            }
            if (!astar.IsFindPath())
            {
                if (point != null)
                {
                    point.IsWall = oldWall;
                }
                board.SetHighlight(row, col, CellHighlight.Blocked);
                Tips(Localization.Get("Cannot fully block the path") ?? "不能完全阻断怪物路径");
                return null;
            }

            // ② 扣费（放在路径校验之后，避免扣了钱建不成）
            //    charge=false 是"按快照恢复"路径：钱在上次游戏时已经扣过，不能再扣一次。
            if (charge && !PlayerDataManager.Instance.TrySpend(cfg.Prices))
            {
                if (point != null)
                {
                    point.IsWall = oldWall;
                }
                Tips(Localization.Get("Not enough gold") ?? "金币不足");
                return null;
            }

            // ③ 实例化
            GameObject go = ResLoader.Instance.Instantiate(cfg.ResName, TowerParent);
            if (go == null)
            {
                if (point != null)
                {
                    point.IsWall = oldWall;
                }
                if (charge)
                {
                    PlayerDataManager.Instance.AddGold(cfg.Prices);   // 退还（恢复路径没扣过，自然也不用退）
                }
                Tips(Localization.Get("Failed to load tower asset") ?? "防御塔资源加载失败");
                Debug.LogError("[Tower] 建塔失败：无法加载 " + cfg.ResName);
                return null;
            }

            BaseTower tower = go.GetComponent<BaseTower>();
            if (tower == null)
            {
                tower = go.AddComponent<NormalTower>();
            }
            tower.Init(cfg, cell);
            tower.SnapToCell(cell);

            cell.Tower = tower;
            cell.Point = point;
            _towers.Add(tower);

            CombatSystem.Instance.RegisterTower(tower);
            EventDispatcher.TriggerEvent<BaseTower>(EventName.BuildTowerSuccess, tower);
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.PlayAt(AudioName.TowerBuild, cell.Center);
            }
            astar.RequestRefresh();      // 节流重算，敌人改道

            // 【怪物脚下建塔的收尾】建好的瞬间，正站在这一格上的怪就被墙包住了。
            // 它的路径是建塔**之前**算的，未必经过新墙的位置；而 RequestRefresh 走的是
            // "路径哈希判重"——若本次"起点→终点"主路径恰好没变（例如这只怪已被前一座塔引到支路），
            // RefreshPathEvent 不会广播，它就会沿着旧路径从塔身里穿出去。
            // 这里按"格"精确补一次改道（脚下那只 + 剩余路径会踏进这一格的），
            // 让"允许脚下建塔"这件事的行为是确定的。
            CombatSystem combat = CombatSystem.Instance;
            if (combat != null)
            {
                combat.RerouteEnemiesThrough(row, col);
            }

            return tower;
        }

        /// <summary>
        /// 升级一座已建造的塔（M2「换实例」方案）。
        ///
        /// 【为什么是"换实例"而不是"就地改数值"】
        ///   1. 塔的等级差异不止数值，还有外观（炮座/炮管贴图、后续可能加特效），
        ///      就地改数值无法换皮，"换实例"一步到位。
        ///   2. 不同塔型会挂不同子类组件（NormalTower / PowerTower / RetardTower），
        ///      AddComponent 覆盖旧组件会留下脏数据；换实例最干净。
        ///   3. 升级后等级/射程/伤害/攻速全部由新行的 TBTowerInfo 驱动，
        ///      不用在代码里维护任何"等级 → 数值"映射表。
        ///
        /// 【顺序很重要，且顺序本身就是正确性的一部分】
        ///   读旧状态 → 校验升级链 → 扣费（失败即返回，无副作用）
        ///   → **先实例化新塔**（失败则退还金币、旧塔原样保留）
        ///   → 摘旧塔的战斗注册与列表引用 → 新塔 Init + SnapToCell
        ///   → 写回格子 → 注册新塔 → 释放旧实例 → 广播事件（★ 全程不触发路径重算）
        ///
        /// 【为什么必须"先建后拆"】
        ///   如果先拆旧塔再实例化，一旦新塔资源加载失败，旧塔已经被 MarkDestroyed
        ///   并归还对象池 —— 玩家花了钱，格子上却什么都不剩。
        ///   先建后拆才能做到"失败时原样保留原塔"，与 TryBuild 的回滚风格一致。
        ///
        /// 【注册顺序】必须先 UnregisterTower(old) 再 RegisterTower(new)，
        ///   否则会出现短暂的双份 tick（同一格被两座塔各开一次火）。
        ///
        /// 【为什么不 RequestRefresh 路径】
        ///   换塔前后格子始终是"有塔"状态，地图阻挡关系没变，路径无需重算。
        ///   若重算反而会让怪物在升级瞬间抖动改道。
        /// </summary>
        public BaseTower TryUpgrade(BaseTower old)
        {
            // 【真机诊断埋点】升级请求进入执行层
            if (old != null)
            {
                Debug.Log("[Tower] TryUpgrade: " + old.name
                    + " (Lv." + (old.Config != null ? old.Config.Level : -1) + ")");
            }
            if (old == null || old.Config == null || !old.IsBuilt)
            {
                // 【真机诊断埋点】塔句柄无效（空/未建成）——"升级没反应"时先看这条
                Debug.LogWarning(string.Format("[Tower] TryUpgrade 失败：old={0} config={1} isBuilt={2}",
                    old == null ? "null" : old.name,
                    old == null || old.Config == null ? "null" : old.Config.Name,
                    old != null && old.IsBuilt));
                return null;
            }
            if (old.Config.IsMaxLevel)
            {
                // 【真机诊断埋点】满级拦截（按钮此时本应置灰，若用户仍点到这里说明按钮状态不同步）
                Debug.Log(string.Format("[Tower] TryUpgrade 失败：{0} 已是满级 Lv.{1}", old.Config.Name, old.Config.Level));
                Tips(Localization.Get("Tower is already at max level") ?? "该防御塔已满级");
                return null;
            }

            // 升级链：upgradeTo 指向"下一等级的 TBTowerInfo.id"，0 表示满级。
            // 走 Configs.GetNextLevel 而不是"type + level + 1"：口径只允许有一处。
            TowerConfig nextCfg = Configs.GetNextLevel(old.Config);
            if (nextCfg == null)
            {
                // 【真机诊断埋点】升级链断了（配置问题）——"升级没反应"时看这条
                Debug.LogWarning(string.Format("[Tower] TryUpgrade 失败：{0} Lv.{1} 找不到下一级配置（upgradeTo={2}）",
                    old.Config.Name, old.Config.Level, old.Config.UpgradeTo));
                Tips(Localization.Get("No next-level config available") ?? "该防御塔暂无可升级的下一级配置");
                return null;
            }

            CellData cell = old.Cell;
            if (cell == null)
            {
                // 【真机诊断埋点】塔不在格子上（数据不一致）
                Debug.LogWarning("[Tower] TryUpgrade 失败：塔不在格子上（cell=null）");
                Tips(Localization.Get("Tower is not on a tile, cannot upgrade") ?? "该防御塔不在格子上，无法升级");
                return null;
            }

            // ① 扣费（在一切破坏性操作之前，失败则完全无副作用）
            if (!PlayerDataManager.Instance.TrySpend(nextCfg.Prices))
            {
                // 【真机诊断埋点】金币不足（按钮置灰时本不该触发；若触发说明 HUD 状态不同步）
                Debug.Log(string.Format("[Tower] TryUpgrade 失败：金币不足（升级需要 {0}，现有 {1}）",
                    nextCfg.Prices, PlayerDataManager.Instance.Gold));
                Tips(Localization.Get("Not enough gold, upgrade needs {0}", nextCfg.Prices)
                    ?? string.Format("金币不足，升级需要 {0}", nextCfg.Prices));
                return null;
            }

            // ② **先实例化新塔**。此处失败必须做到"零损失"：
            //    金币退还、旧塔保持 IsBuilt、仍在 _towers、仍在 CombatSystem 注册、格子占用不变。
            GameObject go = ResLoader.Instance.Instantiate(nextCfg.ResName, TowerParent);
            if (go == null)
            {
                PlayerDataManager.Instance.AddGold(nextCfg.Prices);   // 退还
                Tips(Localization.Get("Upgrade failed: tower asset missing, gold refunded") ?? "升级失败：防御塔资源加载失败，已退还金币");
                Debug.LogError("[Tower] 升级失败：无法加载 " + nextCfg.ResName + "（原塔保持不变）");
                return null;
            }

            BaseTower tower = go.GetComponent<BaseTower>();
            if (tower == null)
            {
                tower = go.AddComponent<NormalTower>();
            }

            string oldResName = old.Config.ResName;

            // ③ 新塔已就位，才拆旧塔：只摘战斗注册与列表引用，**不动格子阻挡与路径**。
            //    顺序不变量：先 Unregister 旧的，再 Register 新的（避免双份 tick）。
            old.MarkDestroyed();
            _towers.Remove(old);
            CombatSystem.Instance.UnregisterTower(old);

            tower.Init(nextCfg, cell);
#if UNITY_EDITOR
            tower.EvidenceDamage = old.EvidenceDamage; tower.EvidenceOverkill = old.EvidenceOverkill;
            tower.EvidenceHits = old.EvidenceHits; tower.EvidenceSlowApplications = old.EvidenceSlowApplications;
            tower.EvidenceAirHits = old.EvidenceAirHits;
            tower.CopyRangeEvidenceFrom(old);
#endif
            tower.SnapToCell(cell);

            cell.Tower = tower;
            _towers.Add(tower);
            CombatSystem.Instance.RegisterTower(tower);

            // ④ 释放旧实例（放在新塔注册之后：即使释放过程出问题，战斗注册也已一致）
            ResLoader.Instance.ReleaseInstance(oldResName, old.gameObject);

            // 升级后选中态要指向"新实例"，否则面板还拿着已被销毁的旧塔
            if (TowerPlacement.Instance != null)
            {
                TowerPlacement.Instance.ReselectAfterSwap(old, tower);
            }

            // 【为什么不用 BuildTowerSuccess】它的语义是"新建了一座塔"，
            // HudView 收到会退出放置态并复位按钮 —— 升级时发它会把 HUD 状态搅乱。
            EventDispatcher.TriggerEvent<BaseTower>(EventName.TowerUpgradeSuccess, tower);
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.PlayAt(AudioName.TowerUpgrade, tower.Position);
            }
            Tips(Localization.Get("Upgraded to {0} Lv.{1}", nextCfg.DisplayName, nextCfg.Level)
                ?? string.Format("已升级为 {0} Lv.{1}", nextCfg.DisplayName, nextCfg.Level));

            return tower;
        }

        /// <summary>出售：返还金币 + 释放格子 + 请求重算路径</summary>
        public bool Sell(BaseTower tower)
        {
            if (tower == null || tower.Config == null || !tower.IsBuilt)
            {
                return false;
            }
            // 返还金额 = 配置的 sellPrice × 常数表的返还比例
            // （比例做成常数是为了以后能加"卖塔折损"的经济压力，而不用改代码）
            float rate = Configs.Global != null ? Configs.Global.SellRefundRate : 1f;
            int refund = Mathf.Max(0, Mathf.RoundToInt(tower.Config.SellPrice * rate));
            string resName = tower.Config.ResName;

            if (tower.Cell != null)
            {
                tower.Cell.Tower = null;
                if (tower.Cell.Point != null)
                {
                    tower.Cell.Point.IsWall = false;
                }
            }
            tower.MarkDestroyed();
            _towers.Remove(tower);
            CombatSystem.Instance.UnregisterTower(tower);

            PlayerDataManager.Instance.AddGold(refund);
            EventDispatcher.TriggerEvent<BaseTower>(EventName.DestroyTower, tower);
            if (AudioManager.Instance != null)
            {
                AudioManager.Instance.PlayAt(AudioName.TowerSell, tower.Position);
            }
            ResLoader.Instance.ReleaseInstance(resName, tower.gameObject);
            AStarManager.Instance.RequestRefresh();
            Tips(Localization.Get("Tower sold, refunded {0} gold", refund)
                ?? string.Format("已出售防御塔，返还 {0} 金币", refund));
            return true;
        }

        /// <summary>
        /// 清除全部防御塔（切关 / 重开用）。**不返还金币** ——
        /// 这是关卡重置，不是玩家卖塔，返还会让"重开"变成刷钱手段。
        ///
        /// 【为什么用 CombatSystem 的快照而不是遍历 _towers】
        /// ReleaseInstance 会销毁 GameObject，可能连带触发回调；
        /// 拿一份快照再逐个清理，遍历期间就不受这些副作用影响。
        /// </summary>
        public void ClearAll()
        {
            _clearBuf.Clear();
            if (CombatSystem.Instance != null)
            {
                CombatSystem.Instance.CopyTowers(_clearBuf);
            }
            for (int i = _clearBuf.Count - 1; i >= 0; i--)
            {
                BaseTower t = _clearBuf[i];
                if (t == null)
                {
                    continue;
                }
                CellData cell = t.Cell;
                if (cell != null)
                {
                    cell.Tower = null;
                    if (cell.Point != null)
                    {
                        cell.Point.IsWall = false;
                    }
                }
                string resName = t.Config != null ? t.Config.ResName : "Tower_Normal0";
                t.MarkDestroyed();
                CombatSystem.Instance.UnregisterTower(t);
                ResLoader.Instance.ReleaseInstance(resName, t.gameObject);
            }
            _towers.Clear();
            _clearBuf.Clear();
            // 落点爆炸序列帧的池与帧缓存随关卡一起清（枪口焰随塔销毁，无需处理）
            TowerFireFx.ClearPool();
        }

        private static void Tips(string msg)
        {
            EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent, msg);
        }

        public int Count { get { return _towers.Count; } }
    }
}

