namespace FTProject
{
    /// <summary>
    /// 减速光环表现（减速塔 / 美术名 Retard）。**纯表现**，不含任何减速逻辑 ——
    /// 减速已在 BaseTower.TickSlowAura 里当场结算到每个敌人身上。
    ///
    /// 【为什么需要它】改造前减速是"打中某只怪才减速"，玩家能靠子弹轨迹理解；
    /// 改成范围光环后，如果没有可见的范围提示，玩家会疑惑
    /// "这塔到底管多大范围、到底有没有生效"。所以给两样东西：
    ///   ① 常亮的射程圈（浅蓝）—— 明确"谁在范围内"
    ///   ② 每次结算时的一次脉冲（圈短暂变亮）—— 明确"正在起作用"
    ///
    /// 【为什么复用 Range_Ring 而不是新增贴图】
    ///   新增贴图就必须先在编辑器里跑一次占位美术生成，
    ///   而把现成的圈图换个颜色/透明度就是"光环"。零新增资产即可联调。
    ///   将来美术给了正式光环图，改 LogicalName 一行即可。
    ///
    /// 【为什么挂在塔的 transform 下而不是全局单例】
    ///   射程圈是**每座塔各一个**（同屏可能有多座减速塔），
    ///   挂在塔下能随塔自动销毁、自动跟随位置，省掉一套生命周期管理。
    /// </summary>
    public class SlowAuraView : MonoBehaviour
    {
        /// <summary>ResTable 逻辑名（与射程提示圈共用"圈图"）</summary>
        public const string LogicalName = "Range_Ring";

        /// <summary>常亮射程圈颜色：偏冷的浅蓝 —— 与减速的语义呼应，也和白色射程提示圈区分开</summary>
        private static readonly Color RingColor = new Color(0.55f, 0.8f, 1f, 0.06f);

        /// <summary>脉冲时叠加到的亮度（0~1 之间插值）</summary>
        private static readonly Color PulseColor = new Color(0.75f, 0.92f, 1f, 0.26f);

        /// <summary>排序：压在格子之上、怪物之下（与 RangeIndicator 同一层，避免穿帮）</summary>
        private const int SortingOrder = BoardSorting.RangeIndicator;

        private SpriteRenderer _sr;
        private float _nativeDiameter = 1f;
        private float _radius = 1f;
        private bool _ready;

        /// <summary>
        /// 在指定塔的 transform 下挂一个光环表现。贴图缺失时返回 null（不阻塞玩法）。
        /// </summary>
        public static SlowAuraView Attach(Transform towerRoot, float radiusWorld)
        {
            if (towerRoot == null)
            {
                return null;
            }

            Sprite sp = ResLoader.Instance.Load<Sprite>(LogicalName);
            if (sp == null)
            {
                return null;   // 占位美术未生成：静默跳过，减速逻辑照常生效
            }

            GameObject go = new GameObject("SlowAura");
            go.transform.SetParent(towerRoot, false);
            SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
            sr.sprite = sp;
            sr.sortingLayerName = BoardSorting.LayerMain;
            sr.sortingOrder = SortingOrder;
            sr.color = RingColor;

            SlowAuraView v = go.AddComponent<SlowAuraView>();
            v._sr = sr;
            v._nativeDiameter = Mathf.Max(sp.bounds.size.x, sp.bounds.size.y);
            v._ready = true;
            v.SetRadius(radiusWorld);
            return v;
        }

        /// <summary>设置光环半径（世界单位）。塔升级换实例时会重新 Attach，这里也能改。</summary>
        public void SetRadius(float radiusWorld)
        {
            _radius = Mathf.Max(0.01f, radiusWorld);
            ApplyScale();
        }

        /// <summary>整体显示/隐藏（塔换成非减速塔型时关掉）</summary>
        public void SetVisible(bool visible)
        {
            if (_ready && _sr != null && _sr.gameObject.activeSelf != visible)
            {
                _sr.gameObject.SetActive(visible);
            }
        }

        /// <summary>脉冲强度 0~1（1 = 刚命中，0 = 完全平息）。由 BaseTower.TickVisual 每帧推进。</summary>
        public void SetPulse(float k)
        {
            if (!_ready || _sr == null)
            {
                return;
            }
            float t = Mathf.Clamp01(k);
            _sr.color = Color.Lerp(RingColor, PulseColor, t);
        }

        private void ApplyScale()
        {
            if (!_ready || _sr == null)
            {
                return;
            }
            // 与 RangeIndicatorView / CellView 同一套折算：scale = 目标直径 / 贴图原生直径
            float diameter = _radius * 2f;
            float s = _nativeDiameter > 0.0001f ? diameter / _nativeDiameter : diameter;
            // ★ 塔根节点通常有 0.8 缩放，而本节点是它的子节点 ——
            //   因此这里必须换算回本地尺度，否则光环会比实际射程小 20%，
            //   而射程判定用的是世界单位（Config.RadiusWorld），两者就会对不上。
            Vector3 ps = transform.parent != null ? transform.parent.lossyScale : Vector3.one;
            float px = Mathf.Abs(ps.x) > 0.0001f ? Mathf.Abs(ps.x) : 1f;
            float py = Mathf.Abs(ps.y) > 0.0001f ? Mathf.Abs(ps.y) : 1f;
            transform.localScale = new Vector3(s / px, s / py, 1f);
            transform.localPosition = Vector3.zero;   // 与塔同心
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 塔开火序列帧播放器（2026-10-17 攻击表现改版）。
    ///
    /// 【背景】普通塔(1)/火力塔(2) 移除真实子弹，改为《坚守阵地》式表现：
    ///   开火只在炮口播一段枪口焰序列帧，伤害在开火瞬间即时结算（见 BaseTower.Fire）；
    ///   火力塔另在落点播一段爆炸序列帧。本组件就是这两段序列帧的播放器。
    ///
    /// 【两种形态】
    ///   1. 枪口焰：Attach 到炮口节点 BarrelPoint 下作为子物体 —— 与炮口严格同点、
    ///      跟随炮管旋转。帧内火焰**朝上画**、轴点在焰底（与炮管贴图原生朝向 90° 一致，
    ///      见 BaseTower.BarrelNativeAngle 的说明），因此无需再转。
    ///   2. 落点爆炸：PlayBlastAt(worldPos) 从静态池取一个一次性实例播放，
    ///      播完自动归池。池化是因为火力塔攻速不低，逐次 Instantiate 会产生 GC 尖峰。
    ///
    /// 【帧数据】来自 ResTable 登记的散帧（Tower_Muzzle_* / Tower_Blast_*），
    ///   懒加载一次后缓存到静态字段 —— 所有塔共享，切关后随域重载自然清空。
    ///
    /// 【节拍】帧率固定 MuzzleFps/BlastFps，用 Time.deltaTime 推进：
    ///   暂停时 timeScale=0，序列自然冻结，与攻击节奏保持一致。
    /// </summary>
    public class TowerFireFx : MonoBehaviour
    {
        private const float MuzzleFps = 20f;
        private const float BlastFps = 16f;
        /// <summary>枪口焰子物体的节点名（幂等复用靠它找回来）。</summary>
        private const string FxNodeName = "FireFx_Muzzle";

        private SpriteRenderer _sr;
        private Sprite[] _frames;
        private float _frameSec;
        private float _timer;
        private int _index;
        private bool _playing;
        /// <summary>播完是否隐藏（枪口焰 true；爆炸实例回池时统一 SetActive(false)）</summary>
        private bool _hideWhenDone;

        // ---- 静态帧缓存（全塔共享）----
        private static Sprite[] _muzzleNormal;
        private static Sprite[] _muzzlePower;
        private static Sprite[] _blast;

        // ---- 落点爆炸的静态池 ----
        private static readonly List<TowerFireFx> _blastIdle = new List<TowerFireFx>(8);
        private static Transform _blastRoot;

        // ------------------------------------------------------------------
        // 枪口焰
        // ------------------------------------------------------------------

        /// <summary>
        /// 在炮口节点下挂一个枪口焰子物体（每塔一个，随炮管旋转）。
        ///
        /// ★位置权威 = 预制体里的 BarrelPoint 节点：焰直接作为它的子物体、本地位置置零，
        ///   与节点严格重合（不复制本地坐标，避免以后中间层加缩放/旋转时算错）。
        ///   帧的轴点在**焰底**（见 .workbuddy/tools/gen_tower_fire_frames.py 的
        ///   MUZZLE_BASE_MARGIN + meta alignment=9/pivot y=0.2），所以焰根正好从枪口喷出，
        ///   焰底以下那圈回喷光晕落在炮管上作过渡。
        ///   只有预制体缺 BarrelPoint 时才退回"炮管上沿"的估算位置并告警。
        /// </summary>
        public static TowerFireFx AttachMuzzle(Transform barrel, Transform muzzleTip)
        {
            if (barrel == null)
            {
                return null;
            }
            Transform anchor = muzzleTip != null ? muzzleTip : barrel;
            Transform t = anchor.Find(FxNodeName);
            if (t == null && muzzleTip != null)
            {
                // 兼容：旧版本把焰挂在炮管上，换了锚点后重新挂到炮口
                t = barrel.Find(FxNodeName);
            }
            GameObject go;
            if (t == null)
            {
                go = new GameObject(FxNodeName);
                go.transform.SetParent(anchor, false);
                SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
                // 焰是塔的子节点 → 落在塔的 SortingGroup 内，这里用的是**组内相对序号**：
                // 必须大于炮管（TowerBarrel），才能盖住炮口。
                sr.sortingLayerName = BoardSorting.LayerMain;
                sr.sortingOrder = BoardSorting.TowerMuzzleFx;
            }
            else
            {
                go = t.gameObject;
                if (go.transform.parent != anchor)
                {
                    go.transform.SetParent(anchor, false);
                }
            }
            if (muzzleTip != null)
            {
                go.transform.localPosition = Vector3.zero;
            }
            else
            {
                go.transform.localPosition = new Vector3(0f, 0.6f, 0f);
                Debug.LogWarning("[TowerFireFx] 塔预制体缺 BarrelPoint，枪口焰退回炮管上沿绘制");
            }
            go.transform.localRotation = Quaternion.identity;
            go.transform.localScale = Vector3.one * 0.9f;
            TowerFireFx fx = go.GetComponent<TowerFireFx>();
            if (fx == null)
            {
                fx = go.AddComponent<TowerFireFx>();
            }
            fx._sr = go.GetComponent<SpriteRenderer>();
            fx._hideWhenDone = true;
            fx._playing = false;
            if (fx._sr != null)
            {
                fx._sr.enabled = false;
            }
            return fx;
        }

        /// <summary>按塔型取枪口焰帧序列（懒加载）。</summary>
        public static Sprite[] GetMuzzleFrames(bool isPower)
        {
            if (isPower)
            {
                if (_muzzlePower == null)
                {
                    _muzzlePower = LoadFrames("Tower_Muzzle_Power_", 5);
                }
                return _muzzlePower;
            }
            if (_muzzleNormal == null)
            {
                _muzzleNormal = LoadFrames("Tower_Muzzle_Normal_", 4);
            }
            return _muzzleNormal;
        }

        /// <summary>重放一遍枪口焰（正在播时从头打断重放 —— 攻速快时表现为持续喷吐）。</summary>
        public void PlayMuzzle(Sprite[] frames)
        {
            if (frames == null || frames.Length == 0 || _sr == null)
            {
                return;
            }
            _frames = frames;
            _frameSec = 1f / MuzzleFps;
            _index = 0;
            _timer = 0f;
            _playing = true;
            _sr.sprite = frames[0];
            _sr.enabled = true;
        }

        // ------------------------------------------------------------------
        // 落点爆炸
        // ------------------------------------------------------------------

        /// <summary>在落点播一次爆炸序列帧（池化）。</summary>
        public static void PlayBlastAt(Vector2 worldPos)
        {
            if (_blast == null)
            {
                _blast = LoadFrames("Tower_Blast_", 6);
            }
            if (_blast == null || _blast.Length == 0)
            {
                return;
            }
            TowerFireFx fx = null;
            // 从池里找一个空闲实例
            while (_blastIdle.Count > 0 && fx == null)
            {
                int last = _blastIdle.Count - 1;
                fx = _blastIdle[last];
                _blastIdle.RemoveAt(last);
                if (fx == null)
                {
                    continue;   // 池里残留了已销毁实例（切关），跳过
                }
            }
            if (fx == null)
            {
                fx = CreateBlastInstance();
            }
            if (fx == null)
            {
                return;
            }
            fx.transform.position = new Vector3(worldPos.x, worldPos.y, 0f);
            fx.gameObject.SetActive(true);
            fx._frames = _blast;
            fx._frameSec = 1f / BlastFps;
            fx._index = 0;
            fx._timer = 0f;
            fx._playing = true;
            fx._hideWhenDone = false;
            fx._sr.sprite = _blast[0];
            fx._sr.enabled = true;
        }

        private static TowerFireFx CreateBlastInstance()
        {
            if (_blastRoot == null)
            {
                GameObject root = GameObject.Find("TowerFireFxRoot");
                if (root == null)
                {
                    root = new GameObject("TowerFireFxRoot");
                }
                _blastRoot = root.transform;
            }
            GameObject go = new GameObject("FireFx_Blast");
            go.transform.SetParent(_blastRoot, false);
            go.transform.localScale = Vector3.one;
            SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
            sr.sortingLayerName = BoardSorting.LayerMain;
            sr.sortingOrder = BoardSorting.Bullet + 1;
            TowerFireFx fx = go.AddComponent<TowerFireFx>();
            fx._sr = sr;
            return fx;
        }

        private void ReturnToPool()
        {
            _playing = false;
            if (_sr != null)
            {
                _sr.enabled = false;
                _sr.sprite = null;
            }
            if (!_blastIdle.Contains(this))
            {
                _blastIdle.Add(this);
            }
            gameObject.SetActive(false);
        }

        // ------------------------------------------------------------------
        // 帧推进
        // ------------------------------------------------------------------

        private void Update()
        {
            if (!_playing)
            {
                return;
            }
            _timer += Time.deltaTime;
            while (_timer >= _frameSec)
            {
                _timer -= _frameSec;
                _index++;
                if (_index >= _frames.Length)
                {
                    // 播完：枪口焰隐藏待命，爆炸实例回池
                    if (_hideWhenDone)
                    {
                        _playing = false;
                        _sr.enabled = false;
                    }
                    else
                    {
                        ReturnToPool();
                    }
                    return;
                }
                _sr.sprite = _frames[_index];
            }
        }

        /// <summary>切关清理：清空爆炸池与帧缓存（塔本体随场景销毁，枪口焰无需处理）。</summary>
        public static void ClearPool()
        {
            for (int i = 0; i < _blastIdle.Count; i++)
            {
                TowerFireFx fx = _blastIdle[i];
                if (fx != null)
                {
                    Object.Destroy(fx.gameObject);
                }
            }
            _blastIdle.Clear();
            _blastRoot = null;
            _muzzleNormal = null;
            _muzzlePower = null;
            _blast = null;
        }

        /// <summary>按逻辑名前缀加载一串散帧；缺失按 0 帧处理（自检日志会提示）。</summary>
        private static Sprite[] LoadFrames(string prefix, int count)
        {
            List<Sprite> list = new List<Sprite>(count);
            for (int i = 0; i < count; i++)
            {
                Sprite s = ResLoader.Instance.Load<Sprite>(prefix + i);
                if (s != null)
                {
                    list.Add(s);
                }
                else
                {
                    Debug.LogWarning("[TowerFireFx] 缺序列帧 " + prefix + i + "，请检查 ResTable 与 AB 包");
                }
            }
            return list.ToArray();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;

namespace FTProject
{
    /// <summary>
    /// 塔放置控制器（P0-7）。
    ///
    /// 【相对 v1.0 的关键改动】
    ///   v1.0 用"塔模型挂 Collider，落到节点上由 OnTriggerEnter 把节点染绿"，
    ///   依赖物理系统与节点物件。现在改为**纯数学**：
    ///     屏幕坐标 → 摄像机世界坐标 → BoardGeometry.WorldToCell → (row, col)
    ///   既去掉了物理开销（需求 8），也不再需要 Node/Point 预制体。
    ///
    /// 【校验顺序（与 TowerManager.TryBuild 一致）】
    ///   格子在棋盘内 → 可建造（非障碍/空洞/装饰） → 无塔 → 金币够 → 不会堵死路径
    ///   前 4 项是廉价判断，A* 推演只在"悬停格变化"时做一次（16×9 网格下开销可忽略）。
    ///
    /// 【2026-10-22：两条放置规则调整（需求）】
    ///   ① **预览只画不改**：悬停格变化时就推演出"建成后怪物会走的新路径"并实时画出来，
    ///      但该路径只存在 AStarManager.PreviewPathWorld（箭头视图读），
    ///      怪物逻辑一行都不读 —— 玩家滑动期间怪物仍旧走原路，松手落地后才真正改道
    ///      （落地时 TryBuild 置墙 + RequestRefresh → RefreshPathEvent → CombatSystem 让怪物改道）。
    ///   ② **怪物脚下可以建塔**：只要求"不会把路彻底堵死"，不再禁止"该格上有怪物"。
    ///      建好后由 CombatSystem.RerouteEnemiesThrough 让脚下那只怪立刻重新寻路走出去。
    ///
    /// 【2026-10-14：两种放置态（对标《坚守阵地》Fieldrunners）】
    ///   · 经典（_dragMode=false）：快速点塔按钮进入，ghost 跟鼠标、点击落子 —— 原交互全保留；
    ///   · 拖拽（_dragMode=true）：长按/按住塔按钮移动触发（HudView 发 TowerDragBeginEvent），
    ///     ghost 跟手 + 悬停格高亮（绿可建/红不可建），**松手**才校验落子：
    ///     可建格 → TryPlace（内部扣钱）；不可建格 → 提示具体原因并取消；
    ///     拖回建造栏/棋盘外松手 → 静默取消（原作"拖回原处收回"的语义）。
    ///   两种模式的"移动/悬停高亮/校验"完全共用，只有"落子时机"不同。
    /// </summary>
    public class TowerPlacement : MonoBehaviour
    {
        public static TowerPlacement Instance { get; private set; }

        /// <summary>预览塔的透明度</summary>
        public const float GhostAlpha = 0.55f;

        private Transform _ghostParent;

        private bool _active;
        private int _type;
        private int _level;
        private TowerConfig _cfg;
        /// <summary>
        /// 拖拽建造模式（2026-10-14）：true = 长按拖拽（松手落子/取消）；
        /// false = 经典放置态（点击落子）。两种模式共用移动/高亮/校验逻辑。
        /// </summary>
        private bool _dragMode;
        private GameObject _ghost;
        private readonly List<SpriteRenderer> _ghostRenderers = new List<SpriteRenderer>(8);

        private int _hoverRow = -1;
        private int _hoverCol = -1;
        private CellHighlight _hoverState = CellHighlight.None;
        private bool _canBuild;
        /// <summary>不可建造的原因 key（多语言），显示时查表；空串 = 可建造。</summary>
        private string _blockReason = "Cannot Build Here";
        /// <summary>原因文案里的可选参数（目前只有"金币不足（需要 N）"用到）。</summary>
        private int? _blockArg;

        /// <summary>当前选中的已建造塔（M2-B1）。未选中为 null。</summary>
        private BaseTower _selected;

        public bool IsPlacing { get { return _active; } }

        public BaseTower SelectedTower { get { return _selected; } }

        private void Awake()
        {
            Instance = this;
        }

        private void OnEnable()
        {
            EventDispatcher.AddEventListener<int, int>(EventName.BuildTowerRequestEvent, OnBuildRequest);
            EventDispatcher.AddEventListener(EventName.CancelBuildRequestEvent, OnCancelRequest);
            // 拖拽建造（2026-10-14）：HudView 长按塔按钮触发
            EventDispatcher.AddEventListener<int, int>(EventName.TowerDragBeginEvent, OnDragBegin);
        }

        private void OnDisable()
        {
            EventDispatcher.RemoveEventListener<int, int>(EventName.BuildTowerRequestEvent, OnBuildRequest);
            EventDispatcher.RemoveEventListener(EventName.CancelBuildRequestEvent, OnCancelRequest);
            EventDispatcher.RemoveEventListener<int, int>(EventName.TowerDragBeginEvent, OnDragBegin);
        }

        private void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
            DestroyGhost();
        }
        public void SetGhostParent(Transform parent)
        {
            _ghostParent = parent;
        }

        // ------------------------------------------------------------------
        // 进入 / 退出放置模式
        // ------------------------------------------------------------------

        private void OnBuildRequest(int type, int level)
        {
            if (_active)
            {
                ExitPlacement(false);
                return;
            }
            EnterPlacement(type, level, false);
        }

        /// <summary>
        /// 拖拽建造入口（HudView 长按/拖动塔按钮时触发）。
        /// 【与 OnBuildRequest 的关键差别】放置态已激活时**不再退出**，而是"换塔"：
        ///   玩家按住 A 塔拖到一半又按住 B 塔的按钮（interactable=false 不拦截指针事件），
        ///   语义显然是"我要建 B"，直接切过去；同塔同等级则视为重复触发，忽略。
        /// </summary>
        private void OnDragBegin(int type, int level)
        {
            if (_active)
            {
                if (_dragMode && _type == type && _level == level)
                {
                    return;   // 已经在拖同一座塔
                }
                Debug.Log(string.Format("[Place] 拖拽切塔 {0}Lv{1} → {2}Lv{3}", _type, _level, type, level));
                ExitPlacement(false);
            }
            EnterPlacement(type, level, true);
        }

        private void OnCancelRequest()
        {
            ExitPlacement(false);
        }

        /// <summary>经典放置态入口（快速点塔按钮）：保留原交互 —— ghost 跟鼠标、点击落子。</summary>
        public void EnterPlacement(int type, int level)
        {
            EnterPlacement(type, level, false);
        }

        private void EnterPlacement(int type, int level, bool dragMode)
        {
            TowerConfig cfg = Configs.GetTowerByTypeAndLevel(type, level);
            if (cfg == null)
            {
                // 【真机诊断埋点】配置缺失导致"点塔按钮无反应"（同时有 Tips 提示）
                Debug.LogWarning(string.Format("[Place] EnterPlacement 失败：找不到 type={0} level={1} 的塔配置", type, level));
                Tips(Localization.Get("No tower config for type={0} level={1}", type, level)
                    ?? string.Format("找不到 type={0} level={1} 的塔配置", type, level));
                return;
            }
            if (!PlayerDataManager.Instance.TryPeek(cfg.Prices))
            {
                // 【真机诊断埋点】金币不足导致"点塔按钮无反应"（同时有 Tips 提示）
                Debug.Log(string.Format("[Place] EnterPlacement 失败：金币不足（需要 {0}，现有 {1}）",
                    cfg.Prices, PlayerDataManager.Instance.Gold));
                Tips(Localization.Get("Not enough gold, need {0}", cfg.Prices)
                    ?? string.Format("金币不足，需要 {0}", cfg.Prices));
                return;
            }

            _type = type;
            _level = level;
            _cfg = cfg;
            _active = true;
            _dragMode = dragMode;
            // 【真机诊断埋点】放置态进入成功（按钮→配置→金币检查全通过）
            Debug.Log(string.Format("[Place] EnterPlacement {0} Lv.{1} price={2} drag={3}",
                cfg.Name, cfg.Level, cfg.Prices, dragMode));
            _hoverRow = -1;
            _hoverCol = -1;
            _hoverState = CellHighlight.None;

            // 进入放置态时先取消已选中的塔（否则面板不会自动关，两个状态并存会互相干扰）
            Deselect();

            CreateGhost(cfg);
            if (_ghost != null && _dragMode)
            {
                // 拖拽模式：ghost 立即落到手指/鼠标位置 —— 否则从按下到下一帧 Update
                // 之间 ghost 会闪现在世界原点（视觉上"塔凭空出现又跳走"）。
                Vector3 w = ScreenToWorld(Input.mousePosition);
                _ghost.transform.position = new Vector3(w.x, w.y, 0f);
            }
            EventDispatcher.TriggerEvent(EventName.BuildingTower);
            if (_dragMode)
            {
                Tips(Localization.Get("{0}: drag onto a buildable tile and release to place", cfg.DisplayName)
                    ?? string.Format("{0}：拖到可建造格上松手放置，拖回按钮取消", cfg.DisplayName));
            }
            else
            {
                Tips(Localization.Get("{0}: move to a buildable tile and click to place, right-click/ESC to cancel", cfg.DisplayName)
                    ?? string.Format("{0}：移动到可建造格上点击放置，右键/ESC 取消", cfg.DisplayName));
            }
        }

        /// <summary>
        /// 取消放置态（切关 / 重开时由流程层调用）。
        ///
        /// 【为什么不能只调 Deselect】Deselect 管的是"已建造塔的选中态"，
        /// 而放置中的预览体（_ghost）与射程圈走的是另一条分支 ——
        /// 关卡结束时若正处在放置态，预览塔会跟着进到下一关，并且继续跟着鼠标跑。
        /// </summary>
        public void CancelPlacement()
        {
            ExitPlacement(false);
        }

        private void ExitPlacement(bool built)
        {
            if (!_active)
            {
                return;
            }
            _active = false;
            // 【真机诊断埋点】与 EnterPlacement 成对：放置态何时进入/退出必须可追溯。
            // 排查"点塔无反应"时若只看到 Enter 没有 Exit，说明点击被放置分支吞掉 →
            // 对照本文件 UpdatePlacement 里"点已建塔自动退出并选中"的处理是否生效。
            Debug.Log(string.Format("[Place] ExitPlacement built={0}", built));
            ClearHover();
            HideRange();
            DestroyGhost();
            EventDispatcher.TriggerEvent(EventName.CancelBuildRequestEvent);
        }

        private void CreateGhost(TowerConfig cfg)
        {
            DestroyGhost();
            _ghost = ResLoader.Instance.Instantiate(cfg.ResName, _ghostParent);
            if (_ghost == null)
            {
                Debug.LogError("[Place] 预览模型创建失败：" + cfg.ResName);
                _active = false;
                return;
            }
            _ghost.name = "TowerGhost";

            _ghostRenderers.Clear();
            _ghostRenderers.AddRange(_ghost.GetComponentsInChildren<SpriteRenderer>(true));
            // 不改 sortingOrder：prefab 里已排好炮座/炮管的相对层次，改半透明即可
            for (int i = 0; i < _ghostRenderers.Count; i++)
            {
                SpriteRenderer sr = _ghostRenderers[i];
                if (sr == null)
                {
                    continue;
                }
                Color c = sr.color;
                c.a = GhostAlpha;
                sr.color = c;
            }

            // 预览体不参与战斗：BaseTower 未 Init（IsBuilt=false），也不会注册进 CombatSystem
            BaseTower t = _ghost.GetComponent<BaseTower>();
            if (t != null)
            {
                t.SetPreviewAlpha(GhostAlpha);
            }
        }

        private void DestroyGhost()
        {
            if (_ghost != null)
            {
                ResLoader.Instance.ReleaseInstance(_cfg != null ? _cfg.ResName : "Tower_Normal0", _ghost);
                _ghost = null;
            }
        }

        // ------------------------------------------------------------------
        // 选中 / 取消选中（M2-B1：点击已建造塔 → 打开升级/出售面板）
        // ------------------------------------------------------------------

        /// <summary>
        /// 处理"非放置态"下的鼠标左键：命中已建造塔 → 选中并广播事件。
        /// 【为什么放在这里】塔是纯 SpriteRenderer，没有 Collider，
        /// 靠"屏幕坐标 → 格子"反查而不是物理射线，与放置预览共用同一套坐标换算，天然一致。
        ///
        /// 【真机诊断埋点】一次点击 = 一条日志，覆盖全链路判定：
        ///   overUi  —— 是否被 UI 拦截（是则直接 return，不改变选中态）
        ///   inBoard —— 是否落在棋盘格内；(row,col) 为命中格子
        ///   tower   —— 命中格子上的塔（null = 空格子）
        /// 排查"点塔没反应"：看这条日志的断点即可（UI 拦截 / 棋盘外 / 空格 / 正常命中→
        /// 后续应出现 [Place] Select 与 [Flow] OnTowerSelected）。
        /// </summary>
        private void HandleSelectClick()
        {
            bool overUi = IsPointerOverUI();
            BoardView board = BoardView.Instance;
            int row = -1;
            int col = -1;
            bool inBoard = board != null && board.ScreenToCell(Input.mousePosition, out row, out col);
            CellData cell = inBoard ? board.GetCell(row, col) : null;
            BaseTower hit = cell != null ? cell.Tower : null;
            Debug.Log(string.Format("[Place] 点塔判定 screen=({0:F0},{1:F0}) overUi={2} inBoard={3} cell=({4},{5}) tower={6}",
                Input.mousePosition.x, Input.mousePosition.y, overUi, inBoard, row, col, hit != null ? hit.name : "null"));

            // 点在 UI 上不要触发（否则点 HUD 面板会顺手选中/取消塔）
            if (overUi)
            {
                return;
            }
            if (board == null)
            {
                return;
            }
            if (!inBoard)
            {
                // 点到棋盘外 → 视为取消选中
                Deselect();
                return;
            }
            if (hit == null)
            {
                Deselect();
                return;
            }
            Select(hit);
        }

        /// <summary>选中一座塔：广播事件（UI 据此打开面板）。重复点同一座不重复广播。</summary>
        public void Select(BaseTower tower)
        {
            if (tower == null)
            {
                Deselect();
                return;
            }
            if (_selected == tower)
            {
                return;
            }
            // 【顺序不能反】必须先清"旧选中"的高亮，再改 _selected。
            // 反过来的话 ClearSelectionHighlight 看到的就是新塔，旧塔的高亮永远清不掉。
            // 也正因为如此，清理方法必须**接收参数**，不能内部读 _selected。
            ClearSelectionHighlight(_selected);
            _selected = tower;
            ApplySelectionHighlight(_selected);
            // 【真机诊断埋点】选中切换成功（重复点同一座塔会在上方相等判断处静默返回）
            Debug.Log("[Place] Select: " + tower.name);
            EventDispatcher.TriggerEvent<BaseTower>(EventName.TowerSelectedEvent, _selected);
        }

        /// <summary>取消选中：广播事件（UI 据此关闭面板）。</summary>
        public void Deselect()
        {
            if (_selected == null)
            {
                return;
            }
            ClearSelectionHighlight(_selected);
            _selected = null;
            EventDispatcher.TriggerEvent(EventName.TowerDeselectedEvent);
        }

        /// <summary>
        /// 升级（换实例）后把选中态从旧塔迁到新塔。
        /// 若升级的正是当前选中的塔，则静默改指向（不发 Deselect，避免面板闪烁关闭）。
        /// 面板随后通过 TowerUpgradeSuccess 事件重新读 SelectedTower 刷新。
        /// </summary>
        public void ReselectAfterSwap(BaseTower old, BaseTower newer)
        {
            if (_selected != old)
            {
                return;
            }
            _selected = newer;
            // 新实例是刚 Instantiate + Init 出来的，Init 内部已经 SetTint(white)，
            // 所以这里必须把"选中"的视觉重新贴回去，否则升级后高亮会莫名消失。
            ApplySelectionHighlight(_selected);
        }

        /// <summary>选中态塔身提亮色。偏暖白，与"可建造"的绿色 hover 高亮区分开。</summary>
        private static readonly Color SelectedTint = new Color(1f, 0.95f, 0.72f, 1f);

        /// <summary>
        /// 选中态高亮，三件套一起上：① 塔身提亮 ② 所在格染色 ③ 射程圈。
        ///
        /// 【为什么先做提亮而不是描边】描边需要额外的美术资源（M2 待补），
        /// 而 BaseTower.SetTint 已存在，零新增资源就能给出明确、可用的选中反馈。
        /// 美术到位后把这里换成描边/选中 Sprite，调用方无需改动。
        /// </summary>
        private void ApplySelectionHighlight(BaseTower tower)
        {
            if (tower == null)
            {
                return;
            }
            tower.SetTint(SelectedTint);
            SetCellHighlight(tower.Cell, CellHighlight.Selected);
            ShowRange(tower.Position, tower.Config != null ? tower.Config.RadiusWorld : 0f);
        }

        /// <summary>
        /// 清除选中高亮。
        /// 【参数是"要清哪一座"】调用发生在 _selected 被改写**之前**，
        /// 所以不能依赖 _selected —— 这是原先的 bug：清理方法读不到旧塔，等于没清。
        /// </summary>
        private void ClearSelectionHighlight(BaseTower tower)
        {
            if (tower == null)
            {
                return;
            }
            tower.SetTint(Color.white);
            ResetCellHighlight(tower.Cell);
            HideRange();
        }

        // ------------------------------------------------------------------
        // 高亮 / 射程圈工具（都做了空引用容错：棋盘或占位美术缺失时静默降级）
        // ------------------------------------------------------------------

        private static void SetCellHighlight(CellData cell, CellHighlight h)
        {
            if (cell == null || BoardView.Instance == null)
            {
                return;
            }
            BoardView.Instance.SetHighlight(cell.Row, cell.Col, h);
        }

        private static void ResetCellHighlight(CellData cell)
        {
            if (cell == null || BoardView.Instance == null)
            {
                return;
            }
            BoardView.Instance.ResetHighlight(cell.Row, cell.Col);
        }

        /// <summary>
        /// 显示射程圈。RangeIndicatorView.Ensure 在占位贴图缺失时返回 null ——
        /// 射程圈是"锦上添花"，不该因为一张图没生成就把整局玩法拖下水。
        /// </summary>
        private static void ShowRange(Vector2 center, float radiusWorld)
        {
            RangeIndicatorView v = RangeIndicatorView.Ensure();
            if (v != null)
            {
                v.Show(center, radiusWorld);
            }
        }

        private static void HideRange()
        {
            if (RangeIndicatorView.Instance != null)
            {
                RangeIndicatorView.Instance.Hide();
            }
        }

        /// <summary>
        /// 售卖鼠标下的防御塔（**仅当该塔已被选中时**）。
        /// 【M2 变更】原来右键 = 直接卖，误触风险高；现在改为
        /// 右键 = 关闭面板 / 取消选中，出售必须走面板上的确认按钮。
        /// </summary>
        public bool SellSelected()
        {
            if (_selected == null)
            {
                return false;
            }
            BaseTower tower = _selected;
            Deselect();
            return TowerManager.Instance.Sell(tower);
        }

        // ------------------------------------------------------------------
        // 每帧：跟随鼠标 + 校验 + 高亮
        // ------------------------------------------------------------------

        private void Update()
        {
            if (_active)
            {
                UpdatePlacement();
                return;
            }

            // 非放置态：右键 / ESC 取消选中。
            //
            // 【ESC 的分层语义】优先级是"放置态 > 选中态"，靠上面的 _active 提前 return 实现：
            //   · 放置中按 ESC → ExitPlacement（取消放置，塔还没落地，无损失）
            //   · 非放置态按 ESC → Deselect（面板随之关闭，因为它订阅的是 TowerDeselectedEvent）
            // 两层不会同时生效，也不会互相遗漏。
            if (Input.GetMouseButtonDown(1) || Input.GetKeyDown(KeyCode.Escape))
            {
                Deselect();
                return;
            }
            if (Input.GetMouseButtonDown(0))
            {
                HandleSelectClick();
            }
        }

        private void UpdatePlacement()
        {
            // 右键 / ESC：取消放置
            if (Input.GetMouseButtonDown(1))
            {
                ExitPlacement(false);
                return;
            }
            if (_ghost == null)
            {
                return;
            }

            if (Input.GetKeyDown(KeyCode.Escape))
            {
                ExitPlacement(false);
                return;
            }

            BoardView board = BoardView.Instance;
            if (board == null)
            {
                return;
            }

            int row, col;
            bool inside = board.ScreenToCell(Input.mousePosition, out row, out col);

            if (inside)
            {
                // 悬停格变化时才重新校验（A* 探测不每帧做）
                if (row != _hoverRow || col != _hoverCol)
                {
                    ClearHover();
                    _hoverRow = row;
                    _hoverCol = col;
                    EvaluateCell(board, row, col);
                    _hoverState = _canBuild ? CellHighlight.Buildable : CellHighlight.Blocked;
                    board.SetHighlight(row, col, _hoverState);
                }
                _ghost.transform.position = board.CellCenter3(row, col);
                // 射程圈跟着悬停格走：放置前就能看清这座塔能覆盖到哪几格
                ShowRange(board.CellCenter(row, col), _cfg != null ? _cfg.RadiusWorld : 0f);
            }
            else
            {
                ClearHover();
                HideRange();   // 棋盘外不显示射程，避免圈飘在空地上误导
                // 棋盘外：跟随鼠标自由移动，方便玩家看清塔的样子
                Vector3 world = ScreenToWorld(Input.mousePosition);
                _ghost.transform.position = new Vector3(world.x, world.y, 0f);
            }

            // 拖拽建造（2026-10-14）：按住期间只做"跟手 + 悬停高亮"（上面已共用完成），
            // 落子/取消只在松手瞬间判定 —— 见 UpdateDragPlacement。
            if (_dragMode)
            {
                UpdateDragPlacement(board);
                return;
            }

            // 点击放置（避开 UI，否则点 HUD 按钮也会顺手把塔放下去）。
            //
            // 【交互 v2 —— 双手势兼容】
            //   ① 按下即放（原行为，鼠标/点按用户：点哪放哪）；
            //   ② 松手兜底（触摸拖动用户：按住拖到目标格松手落子）。
            //   TryPlace 成功会 ExitPlacement 退出放置态 → 同一手势的 up 不会再触发，天然防重。
            //   【真机诊断埋点】"不能建造"时按这几个日志定位断点：
            //     down/up/inside/canBuild/overUi 全打出来，哪一环断了一眼可见。
            if (Input.GetMouseButtonDown(0))
            {
                bool overUiDown = IsPointerOverUI();
                bool insideDown = board.ScreenToCell(Input.mousePosition, out int rDown, out int cDown);
                Debug.Log(string.Format("[Place] down overUi={0} inside={1} canBuild={2}", overUiDown, insideDown, _canBuild));
                if (overUiDown)
                {
                    return;
                }
                if (!insideDown)
                {
                    // 棋盘外按下：只提示，不取消（防误触；取消走右键/ESC/再点一次塔按钮）
                    Tips("Tap on a buildable tile to place");
                    return;
                }
                if (_canBuild)
                {
                    TryPlace(board, rDown, cDown);
                }
                else
                {
                    // 【点已建塔=转选中】放置态下点到"已有塔的格子"时，玩家的意图几乎必然
                    // 是"操作这座塔"（升级/出售），而不是"在原地再建一座"（也不可能）。
                    // 旧行为只弹一条"该位置已有防御塔"并留在放置态 —— 点击被放置分支吞掉，
                    // 选中/升级面板永远打不开，玩家体验就是"点塔没反应"。
                    // 现在：退出放置态并把这座塔选中，升级面板随 TowerSelectedEvent 打开。
                    CellData hitCell = board.GetCell(rDown, cDown);
                    if (hitCell != null && hitCell.Tower != null)
                    {
                        BaseTower hitTower = hitCell.Tower;
                        Debug.Log(string.Format("[Place] 放置态点击已建塔 ({0},{1}) → 退出放置并选中 {2}",
                            rDown, cDown, hitTower.name));
                        ExitPlacement(false);
                        Select(hitTower);
                    }
                    else
                    {
                        Tips(BlockReasonText());
                    }
                }
                return;
            }

            if (Input.GetMouseButtonUp(0))
            {
                bool insideUp = board.ScreenToCell(Input.mousePosition, out int rUp, out int cUp);
                bool overUiUp = IsPointerOverUI();
                Debug.Log(string.Format("[Place] up overUi={0} inside={1} canBuild={2}", overUiUp, insideUp, _canBuild));
                if (overUiUp)
                {
                    return;
                }
                // 拖动兜底：down 时按偏了（没放出去），拖到可建格松手 → 放
                if (insideUp && _canBuild)
                {
                    TryPlace(board, rUp, cUp);
                }
            }
        }

        /// <summary>
        /// 拖拽建造的"松手判定"（2026-10-14，需求：松开时执行放置前合法性检测）。
        ///
        /// 【四条出路，语义对标《坚守阵地》】
        ///   ① 松在可建格上 → TryPlace（成功扣钱、失败给原因，见 TryPlace/TowerManager）；
        ///   ② 松在不可建格上 → Tips 具体原因（格子有塔/不可建/金币不足/会堵死路径…）并取消；
        ///   ③ 松在已有塔的格子上 → 提示"该位置已有防御塔"并取消 ——
        ///      拖拽语义是"放下"，与经典模式"点已建塔转选中"不同（那个分支在 down 才有意义）；
        ///   ④ 松在 UI 上（拖回建造栏）或棋盘外 → 静默取消 —— 玩家意图就是"不建了"，
        ///      对标原作"拖回原处收回"，此时再弹提示反而像报错。
        /// </summary>
        private void UpdateDragPlacement(BoardView board)
        {
            if (!Input.GetMouseButtonUp(0))
            {
                return;   // 还按着：跟手/高亮已由共用逻辑处理完
            }

            bool overUiUp = IsPointerOverUI();
            bool insideUp = board.ScreenToCell(Input.mousePosition, out int rUp, out int cUp);
            Debug.Log(string.Format("[Place] drag up overUi={0} inside={1} canBuild={2}", overUiUp, insideUp, _canBuild));

            if (overUiUp)
            {
                ExitPlacement(false);
                return;
            }
            if (!insideUp)
            {
                ExitPlacement(false);
                return;
            }
            if (_canBuild)
            {
                TryPlace(board, rUp, cUp);   // 成功 → 内部 ExitPlacement(true)
                return;
            }

            // 松手在不可建格：给出具体原因并取消（需求：不通过则取消放置并给出提示）
            CellData hitCell = board.GetCell(rUp, cUp);
            if (hitCell != null && hitCell.Tower != null)
            {
                Tips(Localization.Get("Tower already there") ?? "该位置已有防御塔");
            }
            else
            {
                Tips(BlockReasonText());
            }
            ExitPlacement(false);
        }

        /// <summary>校验某个格子能否建塔。只做廉价判断 + 一次 A* 推演（推演结果同时用作预览）。</summary>
        private void EvaluateCell(BoardView board, int row, int col)
        {
            _canBuild = false;
            _blockArg = null;
            CellData cell = board.GetCell(row, col);

            if (cell == null)
            {
                _blockReason = "Cannot Build Here";
                ClearPreview();
                return;
            }
            if (!cell.IsBuildable)
            {
                _blockReason = "Not Buildable Here";
                ClearPreview();
                return;
            }
            if (cell.HasTower)
            {
                _blockReason = "Tower already there";
                ClearPreview();
                return;
            }
            // 【2026-10-22】原先这里还有一条"该格上正有怪物 → 不可建造"。
            // 需求改为：只要不堵死路径就允许建，怪物压在脚下由落地后的定点改道解决
            // （见 TowerManager.TryBuildInternal → CombatSystem.RerouteEnemiesThrough）。
            if (!PlayerDataManager.Instance.TryPeek(_cfg.Prices))
            {
                // 带参数的 key：语序可随语言调整
                _blockReason = "Not enough gold, need {0}";
                _blockArg = _cfg.Prices;
                ClearPreview();
                return;
            }
            if (!PreviewPathThrough(row, col))
            {
                _blockReason = "Cannot fully block the path";
                return;   // 预览已在 PreviewPathThrough 内部清掉
            }
            _canBuild = true;
            _blockReason = string.Empty;
        }

        /// <summary>
        /// 推演"在这格建塔后怪物会怎么走"，并把结果挂成**预览路径**。
        /// 返回 false = 这格会把路彻底堵死（预览同时被清空）。
        ///
        /// 【预览为什么不作用于怪物】推演只写 AStarManager.PreviewPathWorld，不写 CurrentPathWorld、
        /// 不发 RefreshPathEvent；怪物与"已生效路径"完全读不到它。落地后 TryBuild 才真正置墙重算。
        /// 【预览为什么一定等于实际】落地做的是同一件事（该格 IsWall 置真后跑一次 A*），
        /// 同一个网格、同一套搜索、同一对起终点 —— 两边不会算出不同的路。
        /// </summary>
        private static bool PreviewPathThrough(int row, int col)
        {
            AStarManager astar = AStarManager.Instance;
            if (astar == null || !astar.IsGridReady)
            {
                // 没有寻路数据时不做堵路判定：悬停高亮不该因为 A* 未就绪就整片变红。
                // 注意落地仍会拦 —— TowerManager.TryBuildInternal 里 `IsFindPath()` 在 Map==null 时返回 false，
                // 会以"不能完全阻断怪物路径"拒绝。这是"棋盘/配置异常"下的降级，不是正常路径。
                return true;
            }
            Vector3[] preview = astar.ComputePathWithExtraWall(row, col);
            if (preview == null)
            {
                astar.ClearPreviewPath();
                return false;
            }
            astar.ShowPreviewPath(preview);
            return true;
        }

        /// <summary>清掉预览路径（幂等：没有预览时是空操作，不会白广播事件）。</summary>
        private static void ClearPreview()
        {
            if (AStarManager.Instance != null)
            {
                AStarManager.Instance.ClearPreviewPath();
            }
        }

        private void TryPlace(BoardView board, int row, int col)
        {
            BaseTower tower = TowerManager.Instance.TryBuild(_type, _level, row, col);
            if (tower == null)
            {
                // TryBuild 内部已通过 ShowTipEvent 给出具体原因
                ClearHover();
                return;
            }

            // 建成功后退出放置模式（HudView 收到 BuildTowerSuccess 会复位按钮）
            ExitPlacement(true);
        }

        private void ClearHover()
        {
            if (_hoverRow >= 0 && _hoverCol >= 0 && BoardView.Instance != null)
            {
                BoardView.Instance.ResetHighlight(_hoverRow, _hoverCol);
            }
            _hoverRow = -1;
            _hoverCol = -1;
            _hoverState = CellHighlight.None;
            // 悬停格没了，针对那一格的预览路径也必须一起消失
            // （否则箭头会指向一个玩家已经不在看的格子，滑出棋盘后尤其明显）
            ClearPreview();
        }

        // ------------------------------------------------------------------
        // 工具
        // ------------------------------------------------------------------

        private static Vector3 ScreenToWorld(Vector2 screenPos)
        {
            Camera cam = Camera.main;
            if (cam == null)
            {
                return Vector3.zero;
            }
            return cam.ScreenToWorldPoint(new Vector3(screenPos.x, screenPos.y, -cam.transform.position.z));
        }

        /// <summary>
        /// 指针是否悬在 UI 上。
        /// 【2026-10-14 升级：触摸感知】原版只查 IsPointerOverGameObject()（无参 = 鼠标指针 -1），
        /// 真机触摸的 pointerId ≥ 0，会恒返回 false —— 经典模式下"点 HUD 按钮顺手落塔"、
        /// 拖拽模式下"松手误判成棋盘内"都可能出现。现在：有任何活动触摸时逐一查
        /// IsPointerOverGameObject(fingerId)，两者任一命中即算 overUi。
        /// 编辑器（鼠标）行为不变。
        /// </summary>
        private static bool IsPointerOverUI()
        {
            EventSystem es = EventSystem.current;
            if (es == null)
            {
                return false;
            }
            if (Input.touchCount > 0)
            {
                for (int i = 0; i < Input.touchCount; i++)
                {
                    if (es.IsPointerOverGameObject(Input.GetTouch(i).fingerId))
                    {
                        return true;
                    }
                }
            }
            return es.IsPointerOverGameObject();
        }

        private static void Tips(string msg)
        {
            EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent, msg);
        }

        /// <summary>
        /// 把 _blockReason（key）解析成当前语言的文案。
        /// 【为什么把 key 存在字段里】_blockReason 在 EvaluateCell 每帧被重算，
        ///   用"存 key + 显示时查表"只需一处映射；若直接存译文，切换语言后残留的
        ///   旧译文会一直挂在字段上（直到下一次 EvaluateCell 才刷新）。
        /// </summary>
        private string BlockReasonText()
        {
            if (string.IsNullOrEmpty(_blockReason))
            {
                return string.Empty;
            }
            string text = _blockArg.HasValue
                ? Localization.Get(_blockReason, _blockArg.Value)
                : Localization.Get(_blockReason);
            return text ?? FallbackBlockReason(_blockReason);
        }

        /// <summary>表里缺 key 时的中文兜底（保证"零破坏"）。</summary>
        private static string FallbackBlockReason(string key)
        {
            switch (key)
            {
                case "Cannot Build Here": return "超出棋盘范围";
                case "Not Buildable Here": return "该位置不可建造";
                case "Tower already there": return "该位置已有防御塔";
                case "Not enough gold, need {0}": return "金币不足（需要 {0}）";
                case "Cannot fully block the path": return "不能完全阻断怪物路径";
                default: return "无法建造";
            }
        }
    }
}

using System;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>确认弹窗的性质（决定顶部色条与确定按钮的颜色）。</summary>
    public enum ConfirmType
    {
        Info,
        Success,
        Danger,
        Warning
    }

    /// <summary>
    /// 通用二次确认弹窗（UI 补全 C2 / 效果图 22_ConfirmView.svg 右）。
    ///
    /// 【它解决什么问题】改造前"重置存档"是**点一下就真的清了**（`SettingView.OnClickReset` 直接
    /// `ResetAll()`），退出游戏也没有确认。这类不可撤销的操作必须拦一道。
    ///
    /// 【为什么做成静态 Show 而不是让调用方自己 Open + Show】
    ///   调用点关心的是"我要确认一件事"，不是"我要打开某个界面"。
    ///   静态入口把 Open→Show 的样板收在一处，接新调用点只要一行。
    ///
    /// 【高度为什么不做自适应】策划案 §3 C2 写了"高随正文行数自适应（480~700）"，
    ///   但**固定 760×560** 才是效果图 22 的实测几何，而且自适应高度会破坏
    ///   UIPrefabBuilder 的静态布局（生成器产出的节点坐标是写死的，运行期改面板高
    ///   就得同时重排 6 个子节点，很容易出错）。
    ///   按"以 SVG 为准"的裁定：**固定 760×560**，正文限 3 行内，超出自动缩字号。
    /// </summary>
    public class ConfirmView : MonoBehaviour
    {
        public const string LogicalName = "ConfirmView";

        /// <summary>正文最长行数（超过就缩字号，而不是撑破面板）。</summary>
        private const int MaxBodyLines = 3;

        private static readonly Color Cyan = new Color(0.208f, 0.878f, 1f, 1f);          // #35E0FF
        private static readonly Color Gold = new Color(1f, 0.788f, 0.302f, 1f);          // #FFC94D
        private static readonly Color DangerRed = new Color(1f, 0.302f, 0.369f, 1f);     // #FF4D5E
        private static readonly Color Fire = new Color(1f, 0.478f, 0.161f, 1f);          // #FF7A29
        private static readonly Color TextPrimary = new Color(0.910f, 0.941f, 0.980f, 1f);
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f);

        private TMP_Text _title;
        private TMP_Text _body;
        private Image _topBar;
        private Image _dangerIcon;
        private Button _confirmBtn;
        private Button _cancelBtn;
        private TMP_Text _confirmLabel;
        private TMP_Text _cancelLabel;

        private Action _onConfirm;

        /// <summary>
        /// 弹一个确认框。<paramref name="onConfirm"/> 在点"确定"后**只执行一次**。
        /// 【prefab 缺失时的行为】记一条明确错误并**不执行** onConfirm ——
        /// 不可撤销的操作宁可"什么都没发生"，也不能在玩家没确认的情况下执行。
        /// </summary>
        public static void Show(string title, string body, ConfirmType type, Action onConfirm,
            string confirmLabel = "确定", string cancelLabel = "取消")
        {
            ConfirmView view = UIManager.Instance.Open<ConfirmView>(LogicalName, UILayout.NormalPanel);
            if (view == null)
            {
                Debug.LogError("[Confirm] ConfirmView 打开失败（prefab 可能还没生成），已取消本次操作：" + title);
                return;
            }
            view.Setup(title, body, type, onConfirm, confirmLabel, cancelLabel);
        }

        private void Awake()
        {
            _title = FindText("Panel/TopBar/BodyTitle");
            _body = FindText("Panel/BodyText");
            _confirmBtn = FindButton("Panel/ConfirmBtn");
            _cancelBtn = FindButton("Panel/CancelBtn");
            _confirmLabel = FindText("Panel/ConfirmBtn/Label");
            _cancelLabel = FindText("Panel/CancelBtn/Label");
            Transform bar = transform.Find("Panel/TopBar");
            _topBar = bar != null ? bar.GetComponent<Image>() : null;
            Transform icon = transform.Find("Panel/DangerIcon");
            _dangerIcon = icon != null ? icon.GetComponent<Image>() : null;

            if (_confirmBtn != null) _confirmBtn.onClick.AddListener(OnClickConfirm);
            if (_cancelBtn != null) _cancelBtn.onClick.AddListener(OnClickCancel);
            // 点背景 = 取消（与"点右上角关闭"同义；不做成"确定"，避免误触致不可撤销）
            Button bg = FindButton("Bg");
            if (bg != null) bg.onClick.AddListener(OnClickCancel);
        }

        private void Setup(string title, string body, ConfirmType type, Action onConfirm,
            string confirmLabel, string cancelLabel)
        {
            _onConfirm = onConfirm;

            SetText(_title, title);
            SetText(_body, body);
            SetText(_confirmLabel, string.IsNullOrEmpty(confirmLabel)
                ? (Localization.Get("OK") ?? "确定") : confirmLabel);
            SetText(_cancelLabel, string.IsNullOrEmpty(cancelLabel)
                ? (Localization.Get("Cancel") ?? "取消") : cancelLabel);

            if (_title != null) _title.color = TextPrimary;
            if (_body != null) _body.color = TextSecondary;

            Color accent = ColorFor(type);
            if (_topBar != null) _topBar.color = accent;
            if (_dangerIcon != null) _dangerIcon.color = accent;

            // 正文超长就缩字号（固定高度面板下的兜底，总比文字溢出到面板外好）
            if (_body != null)
            {
                int lines = 1 + Mathf.Max(0, body != null ? body.Length / 22 : 0);
                int size = lines <= MaxBodyLines ? 28 : Mathf.Max(20, 28 - (lines - MaxBodyLines) * 2);
                _body.fontSize = size;
            }
        }

        private static Color ColorFor(ConfirmType type)
        {
            switch (type)
            {
                case ConfirmType.Success: return Gold;
                case ConfirmType.Danger: return DangerRed;
                case ConfirmType.Warning: return Fire;
                default: return Cyan;
            }
        }

        private void OnClickConfirm()
        {
            // 【为什么要先取出再清空】onConfirm 里可能又打开别的界面/再次弹确认，
            // 不清空的话"连点两次确定"会把回调执行两遍（不可撤销操作执行两次是灾难）。
            Action cb = _onConfirm;
            _onConfirm = null;
            UIManager.Instance.Close(LogicalName);
            if (cb != null)
            {
                cb();
            }
        }

        private void OnClickCancel()
        {
            _onConfirm = null;
            UIManager.Instance.Close(LogicalName);
        }

        private static void SetText(TMP_Text t, string v)
        {
            if (t != null && t.text != v)
            {
                t.text = v;
            }
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Confirm] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Confirm] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

using TMPro;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 伤害飘字（M2-W5）。世界空间 Canvas + 对象池 TMP 文本。
    ///
    /// 【为什么是"管理器 + 懒创建"，而不是挂在场景里的 prefab】
    ///   挂 prefab 就多一个必须在 Unity 里生成的资产；而飘字属于纯表现，
    ///   用代码创建可以零资产交付，也少一处"忘了往场景里拖引用"的失败模式。
    ///
    /// 【为什么需要一个专门的 MonoBehaviour 来 Update】
    ///   工程约定 CombatSystem 是 UpdateEvent 的**唯一**订阅者（性能与顺序都可控）。
    ///   为了不破坏这条不变量，飘字自带一个轻量 Update，
    ///   而不是把自己塞进全局事件总线。
    ///
    /// 【节流】同一只怪在 DamageTextThrottleMs 内只弹一次。
    ///   高频塔（穿透塔 CD=200ms、激光塔更密）每跳都弹的话，屏幕会被数字糊满，
    ///   反而看不出伤害高低 —— 这是"表现"与"信息量"的取舍。
    ///
    /// 【字体从哪来】全工程统一 TMP。TMP 的 SDF 字体资产自带中文字形，
    ///   这里取 TMP Settings 配置的默认字体（工程已指向 SiYuanSongTi SDF），
    ///   不依赖 UGUI 的 Font / Resources.GetBuiltinResource（那套已弃用）。
    /// </summary>
    public class FloatingTextManager : MonoBehaviour
    {
        private const int PoolSize = 24;
        private const float LifeSec = 0.7f;
        private const float RiseSpeed = 1.4f;
        private const int FontSize = 34;

        private static readonly Color NormalColor = new Color(1f, 0.95f, 0.6f, 1f);
        private static readonly Color KillColor = new Color(1f, 0.42f, 0.32f, 1f);

        private static FloatingTextManager _instance;

        private TextMeshProUGUI[] _texts;
        private RectTransform[] _rects;
        private float[] _life;
        private int _next;
        private bool _ready;

        /// <summary>
        /// 弹一个伤害数字。
        /// </summary>
        /// <param name="owner">伤害归属的怪，用于节流（可为 null，则不节流）</param>
        /// <param name="killing">是否是致命一击 —— 用颜色区分，玩家一眼能看出"这只死了"</param>
        public static void Show(BaseEnemy owner, Vector3 worldPos, int amount, bool killing)
        {
            // 关掉时整条链路短路：压测与低端机降级都靠这一个开关
            if (Configs.Global == null || !Configs.Global.ShowDamageText)
            {
                return;
            }
            if (amount <= 0)
            {
                return;
            }

            // 节流：写在怪身上，避免用"怪 → 时间"的字典（对象池复用时字典键会失效并泄漏）
            if (owner != null)
            {
                float now = Time.unscaledTime;
                if (now < owner.NextDamageTextTime)
                {
                    return;
                }
                owner.NextDamageTextTime = now + Configs.Global.DamageTextThrottleSec;
            }

            if (_instance == null)
            {
                _instance = Create();
                if (_instance == null)
                {
                    return;
                }
            }
            _instance.ShowInternal(worldPos, amount, killing);
        }

        /// <summary>
        /// 立刻收起所有正在飘的伤害数字（切关 / 重开用）。
        ///
        /// 【为什么要它】飘字有 0.7 秒寿命，而切关是同一帧完成的 ——
        /// 不清的话，上一关的伤害数字会继续飘进新关卡，看起来像"新关卡凭空掉血"。
        /// 实例还没被创建过时是空操作（那就本来没有东西可清）。
        /// </summary>
        public static void ClearAll()
        {
            if (_instance != null)
            {
                _instance.ClearInternal();
            }
        }

        private void ClearInternal()
        {
            if (!_ready)
            {
                return;
            }
            for (int i = 0; i < _texts.Length; i++)
            {
                _life[i] = 0f;
                TextMeshProUGUI t = _texts[i];
                if (t != null && t.gameObject.activeSelf)
                {
                    t.gameObject.SetActive(false);
                }
            }
        }

        private static FloatingTextManager Create()
        {
            TMP_FontAsset font = ResolveFont();
            if (font == null)
            {
                Debug.LogWarning("[FloatText] 找不到可用 TMP 字体资产，伤害飘字已跳过（不影响战斗）");
                return null;
            }

            GameObject root = new GameObject("FloatingTextRoot");
            Canvas canvas = root.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            // 伤害飘字走 Pop 排序层：层优先级高于层内 order，任何 Main 层物体都压不住它。
            canvas.sortingLayerName = BoardSorting.LayerPop;
            canvas.sortingOrder = BoardSorting.PopOverlay;

            // 世界空间 Canvas 的常规做法：整体缩小，让 1 canvas 单位 = 0.01 世界单位。
            // 于是 fontSize=34 的字约 0.34 世界单位高，与"1 格 = 1 世界单位"相称。
            root.transform.localScale = Vector3.one * 0.01f;
            RectTransform crt = root.GetComponent<RectTransform>();
            crt.sizeDelta = new Vector2(200f, 200f);

            FloatingTextManager m = root.AddComponent<FloatingTextManager>();
            m.Init(font);
            return m;
        }

        /// <summary>
        /// 取 TMP 字体资产。
        /// 【为什么不再借场景 UI 文本的 Font】那套是 UGUI 的；TMP 用的是**字体资产**。
        ///   直接取 TMP Settings 的默认字体（工程已配置为 SiYuanSongTi SDF，含中文字形），
        ///   该资产已随 TMP 资源配置进包，不需要再从场景里"借"一个引用。
        /// </summary>
        private static TMP_FontAsset ResolveFont()
        {
            // 多语言字体优先（数字本身无需翻译，但字形集要跟随当前语言）
            LanguageManager.EnsureSettings();
            if (LanguageManager.Settings != null)
            {
                TMP_FontAsset localized = LanguageManager.GetFont(LanguageManager.Current);
                if (localized != null)
                {
                    return localized;
                }
            }
            TMP_FontAsset font = TMP_Settings.defaultFontAsset;
            if (font == null && TMP_Settings.fallbackFontAssets != null && TMP_Settings.fallbackFontAssets.Count > 0)
            {
                font = TMP_Settings.fallbackFontAssets[0];
            }
            return font;
        }

        private void Init(TMP_FontAsset font)
        {
            _texts = new TextMeshProUGUI[PoolSize];
            _rects = new RectTransform[PoolSize];
            _life = new float[PoolSize];

            for (int i = 0; i < PoolSize; i++)
            {
                GameObject go = new GameObject("Dmg" + i, typeof(RectTransform));
                go.transform.SetParent(transform, false);

                RectTransform rt = (RectTransform)go.transform;
                rt.anchorMin = new Vector2(0.5f, 0.5f);
                rt.anchorMax = new Vector2(0.5f, 0.5f);
                rt.pivot = new Vector2(0.5f, 0.5f);
                rt.sizeDelta = new Vector2(200f, 60f);

                TextMeshProUGUI t = go.AddComponent<TextMeshProUGUI>();
                if (font != null)
                {
                    t.font = font;
                }
                t.fontSize = FontSize;
                t.alignment = TextAlignmentOptions.Center;
                t.raycastTarget = false;      // 飘字绝不能吃掉点击
                t.enableWordWrapping = false;
                t.overflowMode = TextOverflowModes.Overflow;
                t.color = NormalColor;

                _texts[i] = t;
                _rects[i] = rt;
                go.SetActive(false);
            }
            _ready = true;
        }

        private void OnDestroy()
        {
            if (_instance == this)
            {
                _instance = null;
            }
        }

        private void ShowInternal(Vector3 worldPos, int amount, bool killing)
        {
            if (!_ready)
            {
                return;
            }
            int i = _next;
            _next = (_next + 1) % PoolSize;

            // 【为什么要缓存数字字符串】每跳 ToString 都会产生托管分配，
            // 在 200 怪 + 高频塔的场景下足以在 Profiler 里看出来。
            // 伤害值种类有限，用一个小缓存把它变成零分配。
            TextMeshProUGUI t = _texts[i];
            t.text = NumberCache.Get(amount);
            t.color = killing ? KillColor : NormalColor;

            _rects[i].position = worldPos;
            _texts[i].gameObject.SetActive(true);
            _life[i] = LifeSec;
        }

        private void Update()
        {
            if (!_ready)
            {
                return;
            }
            float dt = GameClock.DeltaTime;
            for (int i = 0; i < _texts.Length; i++)
            {
                if (_life[i] <= 0f)
                {
                    continue;
                }
                _life[i] -= dt;
                if (_life[i] <= 0f)
                {
                    _life[i] = 0f;
                    _texts[i].gameObject.SetActive(false);
                    continue;
                }
                // 上浮 + 淡出
                _rects[i].position += Vector3.up * (RiseSpeed * dt);
                Color c = _texts[i].color;
                c.a = Mathf.Clamp01(_life[i] / LifeSec) * (c.r > 0.9f && c.g < 0.5f ? 1f : 0.95f);
                _texts[i].color = c;
            }
        }
    }

    /// <summary>
    /// 伤害数字的字符串缓存。
    /// 整数伤害的取值范围有限（几百以内），缓存后 Show 就完全不产生垃圾。
    /// </summary>
    internal static class NumberCache
    {
        private const int MaxCached = 512;
        private static readonly string[] _cache = new string[MaxCached];

        public static string Get(int value)
        {
            if (value >= 0 && value < MaxCached)
            {
                string s = _cache[value];
                if (s == null)
                {
                    s = value.ToString();
                    _cache[value] = s;
                }
                return s;
            }
            return value.ToString();
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 游戏介绍弹窗（2026-10-14 新增，原由 HUD 右上角「游戏介绍」按钮打开）。
    ///
    /// 【2026-10-18 现状：暂无入口】HUD 的 Btn_Intro 已改为打开暂停菜单（PauseView），
    ///   本弹窗的按钮入口随之撤下；界面资产、多语言词条、事件链路
    ///   （OpenGameIntroRequestEvent → GameFlowManager.OnOpenGameIntroRequest）全部保留，
    ///   将来要恢复入口只需加一颗按钮发那个事件，不用改本文件。
    ///
    /// 【需求契约】弹窗中必须包含一个「回到选关」按钮，点击后返回关卡选择界面 ——
    ///   走 QuitToSelectRequestEvent（与暂停界面的退出、结算弹窗的返回完全同源），
    ///   由 GameFlowManager.QuitToSelect 统一拆卸关卡（TeardownLevel）并打开选关。
    ///   本界面不自己拆关卡 —— "UI 只发事件，流程层决定干什么"是本工程的铁律。
    ///
    /// 【为什么不碰 timeScale】本弹窗是"查阅型"界面，打开期间战斗照常进行
    ///   （想暂停请用旁边的暂停按钮）。若在这里也压 timeScale，就要处理
    ///   "暂停界面 → 介绍弹窗"的嵌套恢复顺序，复杂度换不来收益。
    ///   副作用是关闭必须显式：CloseBtn 直接 UIManager.Close 自己（见下）。
    ///
    /// 【正文四行是动态文本】Info1..Info4 在 LocalizationPrefabBinder.DynamicNames
    ///   里被排除（运行时代码赋值的节点不挂 TextLocalizer），所以这里在 Awake
    ///   主动按当前语言查表；按钮标签是静态文案（BackBtn/CloseBtn 的 Label），
    ///   由生成器写入英文原文 + 批量挂 TextLocalizer 自动切语言。
    /// </summary>
    public class GameIntroView : MonoBehaviour
    {
        /// <summary>ResTable / UIManager 用的逻辑名（与 prefab 名逐字相同）。</summary>
        public const string LogicalName = "GameIntroView";

        private Button _backBtn;
        private Button _closeBtn;
        private TMP_Text _title;
        private TMP_Text[] _infos;

        /// <summary>正文四行的多语言 key（key = 英文原文，表的主键口径）。</summary>
        private static readonly string[] InfoKeys =
        {
            "Stop the monsters before they reach your base: build towers on the open tiles beside the path.",
            "Long-press a tower button, drag it onto the board, then release to build.",
            "You may slow the monsters down, but never fully block their path.",
            "Survive every round to win the level.",
        };

        /// <summary>表未就绪/缺 key 时的中文兜底（与 InfoKeys 一一对应，保证零破坏）。</summary>
        private static readonly string[] InfoFallbacks =
        {
            "在怪物途经的路边空地建造防御塔，阻止它们抵达你的基地。",
            "长按建造栏的塔按钮，拖到棋盘格子上松手即可建造（金币在落地成功后扣除）。",
            "你可以拖慢怪物的脚步，但不能把它们的路完全堵死。",
            "撑过全部回合即通关。",
        };

        private void Awake()
        {
            _title = FindText("Panel/Title");
            _infos = new TMP_Text[InfoKeys.Length];
            for (int i = 0; i < InfoKeys.Length; i++)
            {
                _infos[i] = FindText("Panel/Info" + (i + 1));
            }

            _backBtn = FindButton("Panel/BackBtn");
            _closeBtn = FindButton("Panel/CloseBtn");
            if (_backBtn != null)
            {
                _backBtn.onClick.AddListener(OnClickBack);
            }
            if (_closeBtn != null)
            {
                _closeBtn.onClick.AddListener(OnClickClose);
            }
        }

        /// <summary>
        /// 每次打开按当前语言重建标题与正文四行。
        /// 【为什么必须在 OnEnable 重建】UIManager 池化复用实例（Awake 只跑一次），
        /// 而语言可以在暂停界面随时切换 —— 若只在 Awake 赋值，二次打开会显示上一次
        /// 语言的残留（2026-10-16 多语言审计修复）。
        /// </summary>
        private void OnEnable()
        {
            Refresh();
        }

        private void Refresh()
        {
            if (_title != null)
            {
                _title.text = Localization.Get("Game Intro") ?? "游戏介绍";
                LanguageManager.ApplyFont(_title);
            }
            if (_infos != null)
            {
                for (int i = 0; i < _infos.Length; i++)
                {
                    if (_infos[i] != null)
                    {
                        _infos[i].text = Localization.Get(InfoKeys[i]) ?? InfoFallbacks[i];
                        LanguageManager.ApplyFont(_infos[i]);
                    }
                }
            }
        }

        /// <summary>「回到选关」：发退出对局事件（口径与 PauseView.OnClickQuit 一致）。</summary>
        private void OnClickBack()
        {
            // 【真机诊断埋点】"点回到选关没反应"排查链第一环；
            // 后续链路：QuitToSelectRequestEvent → GameFlowManager.QuitToSelect → TeardownLevel。
            Debug.Log("[Intro] 点击回到选关");
            // 【2026-10-18】不再在这里写 Time.timeScale：暂停的唯一写入口是
            //   GameClock.SetPaused(false)，而退出对局走 TeardownLevel 时已经统一解除暂停。
            //   UI 再写一次会与流程层状态脱钩（例如把别处设好的暂停态冲掉）。
            EventDispatcher.TriggerEvent(EventName.QuitToSelectRequestEvent);
        }

        /// <summary>「关闭」：只关自己，不打断对局。TeardownLevel 也会兜底关本界面。</summary>
        private void OnClickClose()
        {
            Debug.Log("[Intro] 点击关闭");
            UIManager.Instance.Close(LogicalName);
        }

        // （与 PauseView 同口径：缺节点只警告、不阻断 —— 介绍弹窗缺正文不至于卡玩法）
        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Intro] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Intro] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 战斗 HUD（P0-9 / M2-A4）。
    ///
    /// 【设计原则】HUD 只做两件事：①把数据变化显示出来 ②把玩家操作转成事件。
    /// 它不持有任何游戏逻辑引用（不碰 TowerManager / WaveManager），
    /// 这样 UI 挂了也不会影响战斗正确性。
    ///
    /// 【节点名必须与 Assets/Editor/UIPrefabBuilder.cs 生成/维护的 prefab 严格一致】，
    /// 否则会在 Console 里看到「HUD 缺少子节点」的错误（查找是显式报错的，不静默失败）。
    /// 因此 prefab 与 .cs 是**成对修改**的。
    ///
    /// 【M2 新增：三颗塔按钮】
    ///   Btn_Tower_Normal (type=1) / Btn_Tower_Power (type=2) / Btn_Tower_Retard (type=3)
    ///   ★ 命名映射：节点里的 "Retard" ⇄ 枚举 TowerType.Slow(3)，同一件事的两种叫法，
    ///     映射只在本文件的 TowerTypeOf 与美术目录两处，别处不要各写一份。
    ///
    /// 【2026-10-14 新增】右上角两颗按钮 + 塔按钮长按拖拽建造：
    ///   · Btn_Pause  → PauseToggleRequestEvent（GameFlowManager.TogglePause → GameClock.SetPaused）
    ///     ★ 2026-10-18：**不再弹任何窗**，只做暂停/继续开关（点击一次暂停、再点一次恢复）；
    ///       文案两态：未暂停 `Pause` ⇄ 已暂停 `Continue`（RefreshPauseLabel，不挂 TextLocalizer）。
    ///   · Btn_Intro  → PauseRequestEvent（打开暂停菜单 PauseView：继续/重开/设置/退出选关）
    ///     ★ 2026-10-18：弹窗能力由 Btn_Pause 迁移过来；打开菜单**不暂停游戏**
    ///       （暂停只由 Btn_Pause / 热键 P 控制，两个按钮职责互不覆盖）。
    ///   · 塔按钮手势两分：快速点按 = 经典放置态（点击落子）；长按/按住后移动 =
    ///     拖拽建造（TowerDragBeginEvent，ghost 跟手、松手校验落子）——对标《坚守阵地》。
    ///     判定细节见 TowerHoldSec / TowerDragStartPixels 与 OnTowerButtonPressed/Released。
    ///
    /// 【节点层级：文本内嵌在芯片底下】
    ///   GoldText / HpText / RoundText 是 Bg_Gold / Bg_Hp / Bg_Round 的**子节点**
    ///   （不再是 HudView 的直接子节点），所以取值路径是 "Bg_Gold/GoldText" 这种两段式。
    ///   改层级必须与 UIPrefabBuilder.BuildHud 成对改。
    /// </summary>
    public class HudView : MonoBehaviour
    {
        /// <summary>ResTable / UIManager 用的逻辑名（别再各处写字符串字面量）</summary>
        public const string LogicalName = "HudView";

        // ---- 文本（全工程统一 TMP，不再用 UGUI Text）----
        private TMP_Text _goldText;
        private TMP_Text _hpText;
        private TMP_Text _roundText;

        // ---- 开始按钮 ----
        private Button _startButton;
        private TMP_Text _startLabel;

        // ---- 倍速按钮（P2b）----
        private Button _speedButton;
        private TMP_Text _speedLabel;

        // ---- 右上角：暂停开关 / 暂停菜单（2026-10-14；2026-10-18 职责重划）----
        private Button _pauseButton;
        private Button _introButton;
        /// <summary>
        /// 暂停按钮的文案（2026-10-18 起由本类按状态写：未暂停 = Pause，已暂停 = Continue）。
        /// 【为什么不用 TextLocalizer】它是**两态文本**，和 MuteBtn 同类：挂了本地化组件后，
        ///   切语言会按 prefab 原文（Pause）重刷，把"已暂停 → Continue"冲掉。
        ///   所以该节点刻意不挂 TextLocalizer（见 LocalizationPrefabBinder 的 Btn_Pause 跳过规则），
        ///   切语言时由 OnLanguageChanged → RefreshPauseLabel 按当前状态重算。
        /// </summary>
        private TMP_Text _pauseLabel;

        /// <summary>
        /// 塔按钮：节点名 → (按钮, 塔型, 价格文本)。
        /// 用数组而不是一堆字段，是为了让"进入/退出放置态时统一置灰"这类操作用循环即可。
        /// </summary>
        private Button[] _towerButtons;
        private int[] _towerButtonTypes;
        private TMP_Text[] _towerPriceTexts;

        // 保留 prefab 的 16:9 槽位；窄安全区只整体右移建塔栏，避开左下倍速按钮。
        private RectTransform _hudRect;
        private RectTransform _speedRect;
        private RectTransform[] _towerButtonRects;
        private Vector2[] _towerButtonLayoutOrigins;
        private float _bottomLayoutWidth = -1f;
        private const float BottomControlGap = 24f;

        /// <summary>当前选中的塔类型与等级（M2 起由按钮决定 type；level 固定 1 = 建造等级）</summary>
        private int _towerType = 1;
        private int _towerLevel = 1;

        /// <summary>进入放置模式后按钮变灰，避免重复点</summary>
        private bool _placing;

        // ---- 语言切换重放（2026-10-16）：见 OnLanguageChanged 的完整说明 ----
        /// <summary>回合文本配方：key + 参数 + 中文兜底格式（null = 当前没有回合文本）。</summary>
        private string _roundKey;
        private int _roundArg;
        private string _roundFallback;

        /// <summary>开始按钮文本配方（null = 外部接管中，如自动回合倒计时每秒重写）。</summary>
        private string _startKey;
        private string _startFallback;

        /// <summary>
        /// 建造栏的塔按钮（三类：普通 / 火力 / 减速 —— 2026-10-14 三塔型收敛定案）。
        ///
        /// 【为什么节点名必须显式映射，不能由配置推导】
        ///   Slow(3) 在美术/节点/资源目录里叫 "Retard" —— 这处不一致无法用字符串规则还原。
        ///   所以塔型 ↔ 节点名 的对应关系**只在这里写一次**，
        ///   UIPrefabBuilder 与 prefab 三处保持同名即可（契约见 Docs/HudView_Sync_and_TowerUI_Plan.md §2）。
        ///
        /// 【为什么在 Awake 里按固定名单绑定，而不是读配置表动态生成】
        ///   HUD 的 Awake 可能早于 Configs 加载完成；靠配置决定"绑哪几个节点"会在时序上翻车。
        ///   所以：**节点绑定固定，是否显示由配置决定**（见 RefreshTowerAffordability）——
        ///   表里没有对应 type 时按钮自动隐藏，等于按表驱动，又不引入时序依赖。
        /// </summary>
        private static readonly string[] TowerNodeNames =
        {
            "Btn_Tower_Normal", "Btn_Tower_Power", "Btn_Tower_Retard",
        };

        // 与 TowerNodeNames 一一对应（TowerType：1单体/2范围/3减速）
        private static readonly int[] TowerNodeTypes = { 1, 2, 3 };

        private void Awake()
        {
            BindNodes();
            BindEvents();
        }

        private void OnDestroy()
        {
            EventDispatcher.RemoveEventListener<int, int>(EventName.GoldChangeEvent, OnGoldChanged);
            EventDispatcher.RemoveEventListener<int, int>(EventName.PlayerHpChangeEvent, OnHpChanged);
            EventDispatcher.RemoveEventListener<int>(EventName.RoundStartEvent, OnRoundStart);
            EventDispatcher.RemoveEventListener<int>(EventName.WaveStartEvent, OnWaveStart);
            // 【易错点】OnRoundClear 带一个 int 参数，必须写成 RemoveEventListener<int>；
            // 写成无参形式会匹配到 `RemoveEventListener(string, Action)` 重载并报 CS1503。
            EventDispatcher.RemoveEventListener<int>(EventName.RoundClearEvent, OnRoundClear);
            EventDispatcher.RemoveEventListener<bool>(EventName.GameOverEvent, OnGameOver);
            EventDispatcher.RemoveEventListener(EventName.BuildingTower, OnEnterPlacement);
            EventDispatcher.RemoveEventListener(EventName.CancelBuildRequestEvent, OnExitPlacement);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.BuildTowerSuccess, OnBuildSuccess);
            EventDispatcher.RemoveEventListener(EventName.PlayerStateInitEvent, RefreshAll);
            EventDispatcher.RemoveEventListener<float>(EventName.GameSpeedChangedEvent, OnSpeedChanged);
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            EventDispatcher.RemoveEventListener<bool>(EventName.PauseStateChangedEvent, OnPauseStateChanged);
        }

        // ------------------------------------------------------------------
        // 绑定
        // ------------------------------------------------------------------

        private void BindNodes()
        {
            // 文本内嵌在芯片底之下（Bg_* 的子节点），路径必须是两段式
            _goldText = FindText("Bg_Gold/GoldText");
            _hpText = FindText("Bg_Hp/HpText");
            _roundText = FindText("Bg_Round/RoundText");

            _startButton = FindButton("StartButton");
            _startLabel = FindChildText("StartButton/Label");
            if (_startButton != null)
            {
                _startButton.onClick.AddListener(OnClickStart);
            }
            if (_startLabel != null)
            {
                // 记配方而非直接写死：切语言时由 OnLanguageChanged 按配方重算（见文件下方"语言切换重放"）
                SetStartLabelLocalized("Start", "开始");
            }

            // 倍速按钮（P2b）：点击循环 ×1→×2→×3→×1
            _speedButton = FindButton("SpeedButton");
            _speedLabel = FindChildText("SpeedButton/Label");
            if (_speedButton != null)
            {
                _speedButton.onClick.AddListener(OnClickSpeed);
            }
            // 【为什么要在这里初始化文案】HUD 是进关时才创建的，而 GameSpeedChangedEvent
            //   只在"档位真的变了"时才派发。若只靠事件，按钮会一直显示 prefab 里的占位文字。
            SetSpeedLabel(GameClock.Speed);

            // 塔按钮（五类）
            _towerButtons = new Button[TowerNodeNames.Length];
            _towerButtonTypes = new int[TowerNodeNames.Length];
            _towerPriceTexts = new TMP_Text[TowerNodeNames.Length];
            _towerButtonRects = new RectTransform[TowerNodeNames.Length];
            _towerButtonLayoutOrigins = new Vector2[TowerNodeNames.Length];
            for (int i = 0; i < TowerNodeNames.Length; i++)
            {
                int type = TowerNodeTypes[i];
                _towerButtons[i] = FindButton(TowerNodeNames[i]);
                _towerButtonTypes[i] = type;
                // PriceText 是"可选节点"：老的 prefab 没有它，不应该报错，只是没有价格可显示
                _towerPriceTexts[i] = FindChildText(TowerNodeNames[i] + "/PriceText");
                if (_towerButtons[i] != null)
                {
                    _towerButtonRects[i] = _towerButtons[i].transform as RectTransform;
                    _towerButtonLayoutOrigins[i] = _towerButtonRects[i].anchoredPosition;
                    int captured = type;
                    _towerButtons[i].onClick.AddListener(delegate { OnClickTower(captured); });

                    // 长按拖拽建造：给每个塔按钮挂按压中继（运行时 AddComponent，不进 prefab，
                    // 避免 prefab 与程序集版本错位产生 missing-script）。手势判定集中在 Update。
                    TowerDragButton drag = _towerButtons[i].GetComponent<TowerDragButton>();
                    if (drag == null)
                    {
                        drag = _towerButtons[i].gameObject.AddComponent<TowerDragButton>();
                    }
                    int capturedIdx = i;
                    drag.OnPressed = delegate { OnTowerButtonPressed(capturedIdx); };
                    drag.OnReleased = delegate { OnTowerButtonReleased(capturedIdx); };
                }
            }

            // 右上角：暂停开关 / 暂停菜单（2026-10-14 新增；2026-10-18 职责重划）
            // 【文案口径】Btn_Intro 的 Label 是静态文案（英文原文 Menu 写死在 prefab），
            //   由 LocalizationPrefabBinder 批量挂 TextLocalizer 自动切语言 —— 与其它界面按钮同口径。
            //   但 Btn_Pause 是**两态**（Pause ⇄ Continue），刻意不挂 TextLocalizer，
            //   由 RefreshPauseLabel 按 GameClock.IsPaused 写、并在语言切换时重算。
            // 【为什么监听器只加一次、且不重复绑】这两个按钮的 prefab 上没有任何持久化 onClick
            //   （m_Calls 为空），绑定只发生在 Awake 这一次；重绑会给同一次点击派发两次事件
            //   （表现为"点暂停立刻又恢复"），所以这里保持"一个按钮一个监听"。
            _pauseButton = FindButton("Btn_Pause");
            if (_pauseButton != null)
            {
                _pauseButton.onClick.AddListener(OnClickPause);
            }
            // 暂停按钮是"暂停/继续"两态：文案由 RefreshPauseLabel 按当前状态写（见字段注释）
            _pauseLabel = FindChildText("Btn_Pause/Label");
            RefreshPauseLabel();
            _introButton = FindButton("Btn_Intro");
            if (_introButton != null)
            {
                _introButton.onClick.AddListener(OnClickIntro);
            }

            _hudRect = transform as RectTransform;
            _speedRect = _speedButton != null ? _speedButton.transform as RectTransform : null;
            RefreshBottomLayout();
        }

        private void OnRectTransformDimensionsChange()
        {
            RefreshBottomLayout();
        }

        private void RefreshBottomLayout()
        {
            if (_hudRect == null || _speedRect == null || _towerButtonRects == null ||
                _towerButtonRects.Length == 0 || _towerButtonRects[0] == null)
                return;

            float width = _hudRect.rect.width;
            if (width <= 0f || Mathf.Abs(width - _bottomLayoutWidth) < 0.01f)
                return;
            _bottomLayoutWidth = width;

            // 角落锚的速度按钮会随屏幕变窄向建塔栏靠近。以父级实际宽度计算边界，
            // 不用 Screen.width，避免 CanvasScaler 和安全区改变后再次互叠。
            Rect parent = _hudRect.rect;
            float speedRight = parent.xMin + width * _speedRect.anchorMin.x +
                _speedRect.anchoredPosition.x + _speedRect.rect.width * (1f - _speedRect.pivot.x);
            RectTransform first = _towerButtonRects[0];
            float firstLeft = parent.xMin + width * first.anchorMin.x +
                _towerButtonLayoutOrigins[0].x - first.rect.width * first.pivot.x;
            float shift = Mathf.Max(0f, speedRight + BottomControlGap - firstLeft);
            for (int i = 0; i < _towerButtonRects.Length; i++)
            {
                if (_towerButtonRects[i] == null) continue;
                Vector2 position = _towerButtonLayoutOrigins[i];
                position.x += shift;
                _towerButtonRects[i].anchoredPosition = position;
            }
        }

        private void BindEvents()
        {
            EventDispatcher.AddEventListener<int, int>(EventName.GoldChangeEvent, OnGoldChanged);
            EventDispatcher.AddEventListener<int, int>(EventName.PlayerHpChangeEvent, OnHpChanged);
            EventDispatcher.AddEventListener<int>(EventName.RoundStartEvent, OnRoundStart);
            EventDispatcher.AddEventListener<int>(EventName.WaveStartEvent, OnWaveStart);
            // 同上：带 int 参数的回调必须显式写 <int>
            EventDispatcher.AddEventListener<int>(EventName.RoundClearEvent, OnRoundClear);
            EventDispatcher.AddEventListener<bool>(EventName.GameOverEvent, OnGameOver);
            EventDispatcher.AddEventListener(EventName.BuildingTower, OnEnterPlacement);
            EventDispatcher.AddEventListener(EventName.CancelBuildRequestEvent, OnExitPlacement);
            EventDispatcher.AddEventListener<BaseTower>(EventName.BuildTowerSuccess, OnBuildSuccess);
            EventDispatcher.AddEventListener(EventName.PlayerStateInitEvent, RefreshAll);
            EventDispatcher.AddEventListener<float>(EventName.GameSpeedChangedEvent, OnSpeedChanged);
            // 语言切换：重放回合文本与开始按钮文本（配方见 OnLanguageChanged）
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            // 暂停状态变化：刷新暂停按钮的两态文案（Pause ⇄ Continue）
            EventDispatcher.AddEventListener<bool>(EventName.PauseStateChangedEvent, OnPauseStateChanged);
        }

        private TMP_Text FindText(string path)
        {
            TMP_Text t = FindChildText(path);
            if (t == null)
            {
                Debug.LogError(string.Format("[HUD] 缺少文本节点「{0}」（prefab 与 HudView.cs 不一致）", path));
            }
            return t;
        }

        /// <summary>
        /// 取子节点上的 TMP 文本组件。
        /// 【TMP_Text 而不是 TextMeshProUGUI】取基类即可，读取 .text 与颜色都不依赖具体子类；
        ///   基类还能兼容以后的 TextMeshPro（世界空间）节点，耦合更小。
        /// </summary>
        private TMP_Text FindChildText(string path)
        {
            Transform tr = transform.Find(path);
            return tr != null ? tr.GetComponent<TMP_Text>() : null;
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogError(string.Format("[HUD] 缺少按钮节点「{0}」（prefab 与 HudView.cs 不一致）", path));
                return null;
            }
            Button b = tr.GetComponent<Button>();
            if (b == null)
            {
                Debug.LogError(string.Format("[HUD] 节点「{0}」上没有 Button 组件", path));
            }
            return b;
        }

        // ------------------------------------------------------------------
        // 交互 → 事件
        // ------------------------------------------------------------------

        private void OnClickStart()
        {
            // 【真机诊断埋点】"点开始没反应"排查链第一环：点击是否到达 HUD。
            // 后续链路：StartRoundRequestEvent → GameFlowManager.OnStartRoundRequest。
            Debug.Log("[HUD] 点击开始回合按钮");
            if (_startButton != null)
            {
                _startButton.interactable = false;
                SetStartLabelLocalized("In Progress", "进行中");
            }
            EventDispatcher.TriggerEvent(EventName.StartRoundRequestEvent);
        }

        private void OnClickTower(int type)
        {
            // 拖拽刚触发过的这一帧，Button 的 onClick 也会跟着来（松手仍在按钮上时），
            // 必须吞掉，否则会把刚进入的拖拽放置态当成"再点一次"给切出去。
            if (_suppressTowerClick)
            {
                Debug.Log("[HUD] 吞掉拖拽残留的 onClick（防误切放置态）");
                return;
            }
            // 不在这里判断"是否已在放置态"——那是 TowerPlacement 的职责。
            // 统一发同一个请求事件，由它决定是进入还是退出（单一状态源，避免两边状态不一致）。
            _towerType = type;
            // 【真机诊断埋点】"点塔按钮无反应"排查链第一环：点击是否到达 HUD；
            // 后续链路看 [Place] EnterPlacement（进入放置）或 [Place] ExitPlacement（切换/取消）。
            Debug.Log(string.Format("[HUD] 点击塔按钮 type={0} level={1}", type, _towerLevel));
            EventDispatcher.TriggerEvent<int, int>(EventName.BuildTowerRequestEvent, _towerType, _towerLevel);
        }

        // ------------------------------------------------------------------
        // 塔按钮手势判定：快速点按 = 经典放置态；长按/按住后移动 = 拖拽建造
        // （2026-10-14，对标《坚守阵地》Fieldrunners 的拖拽建造）
        // ------------------------------------------------------------------

        /// <summary>按住多久判定为"长按拖拽"（秒）。取 0.25：比系统长按（0.5）跟手，又不会把普通点按误判成拖拽。</summary>
        private const float TowerHoldSec = 0.25f;

        /// <summary>按住期间位移超过该像素数也直接进入拖拽（对标原作"按住就拖"，不等长按计时走完）。</summary>
        private const float TowerDragStartPixels = 30f;
        private const float TowerDragStartPixelsSq = TowerDragStartPixels * TowerDragStartPixels;

        /// <summary>当前按住中的塔按钮下标；-1 = 没有按住。</summary>
        private int _towerPressIndex = -1;
        private float _towerPressTime;
        private Vector2 _towerPressPos;
        /// <summary>本次按压是否已经触发过拖拽（一次按压最多触发一次）。</summary>
        private bool _towerDragFiredForPress;
        /// <summary>
        /// 拖拽触发后的一帧窗口：吞掉 Button 的 onClick。
        /// 【为什么只保留一帧】click 在松手当帧由 EventSystem 派发；拖拽已触发后
        /// （无论长按触发还是松手触发），同帧的 click 都属于"拖拽手势的收尾"而非新意图。
        /// 下一帧 Update 清零，不影响之后的正常点按。
        /// </summary>
        private bool _suppressTowerClick;

        private void OnTowerButtonPressed(int index)
        {
            // 已有按住中的按钮 → 忽略第二根手指（同一时刻只认一根，防多点同时开拖）
            if (_towerPressIndex >= 0)
            {
                return;
            }
            _towerPressIndex = index;
            // 用 unscaled 时间：即便有界面把 timeScale 压成 0，手势判定也不能停摆
            _towerPressTime = Time.unscaledTime;
            _towerPressPos = Input.mousePosition;
            _towerDragFiredForPress = false;
        }

        private void OnTowerButtonReleased(int index)
        {
            if (index != _towerPressIndex)
            {
                return;
            }
            _towerPressIndex = -1;

            if (_suppressTowerClick || _towerDragFiredForPress)
            {
                return;   // 拖拽已在按住期间触发过，松手交给 TowerPlacement 的松手分支
            }

            // 兜底判定：长按阈值恰好在"松手这一帧"才满足（Update 先于/后于事件系统都可能），
            // 在这里补一次判定，保证"按住足够久再松"必然走拖拽而不是点按。
            float held = Time.unscaledTime - _towerPressTime;
            Vector2 move = (Vector2)Input.mousePosition - _towerPressPos;
            if (held >= TowerHoldSec || move.sqrMagnitude >= TowerDragStartPixelsSq)
            {
                FireTowerDrag(index);
            }
            // 否则是快速点按：什么都不做，让 Button.onClick 走经典放置态（原交互保留）
        }

        private void FireTowerDrag(int index)
        {
            _towerDragFiredForPress = true;
            _suppressTowerClick = true;
            int type = _towerButtonTypes[index];
            // 【真机诊断埋点】长按拖拽触发点；后续链路看 [Place] EnterPlacement（drag 模式）
            Debug.Log(string.Format("[HUD] 塔按钮长按/拖动 → 拖拽建造 type={0} level={1}", type, _towerLevel));
            EventDispatcher.TriggerEvent<int, int>(EventName.TowerDragBeginEvent, type, _towerLevel);
        }

        private void Update()
        {
            // Canvas 初次布局可能晚于 Awake；宽度未变时不写 RectTransform。
            RefreshBottomLayout();
            // 吞 click 的窗口只保留一帧：click 永远发生在松手当帧，下一帧必然已处理完
            _suppressTowerClick = false;

            // 按住期间的长按/位移监测（拖拽实例由 TowerPlacement 创建并跟手）
            if (_towerPressIndex >= 0 && !_towerDragFiredForPress)
            {
                float held = Time.unscaledTime - _towerPressTime;
                Vector2 move = (Vector2)Input.mousePosition - _towerPressPos;
                if (held >= TowerHoldSec || move.sqrMagnitude >= TowerDragStartPixelsSq)
                {
                    FireTowerDrag(_towerPressIndex);
                }
            }
        }

        // ------------------------------------------------------------------
        // 右上角：暂停开关 / 暂停菜单（2026-10-14；2026-10-18 职责重划）
        // ------------------------------------------------------------------

        /// <summary>
        /// 暂停/继续开关（Btn_Pause）。**不弹任何窗**。
        /// 【链路】PauseToggleRequestEvent → GameFlowManager.OnPauseToggleRequest → TogglePause
        ///   → GameClock.SetPaused（timeScale 0/1）。
        /// 【为什么发给流程层而不是直接写 timeScale】HUD 不持有游戏状态（见类注释），
        ///   且暂停的唯一写入口必须只有一处，否则界面与流程层会各写一次、状态互相覆盖。
        /// </summary>
        private void OnClickPause()
        {
            // 【真机诊断埋点】"点暂停没反应"排查链第一环：点击是否到达 HUD。
            // 后续链路看 [Flow] 暂停/继续（timeScale=…）。
            Debug.Log("[HUD] 点击暂停按钮（暂停/继续开关，不弹窗）");
            EventDispatcher.TriggerEvent(EventName.PauseToggleRequestEvent);
        }

        /// <summary>
        /// 打开暂停菜单弹窗（Btn_Intro）。
        /// 【2026-10-18】原 Btn_Pause 的"弹窗"能力迁移到这里：
        ///   本方法**只发打开菜单的请求，不触发暂停**（PauseView 也不再改 timeScale），
        ///   所以点一下不会把游戏停住；想停请按旁边的 Btn_Pause。
        /// </summary>
        private void OnClickIntro()
        {
            // 【真机诊断埋点】"点菜单按钮没反应"排查链第一环；
            // 后续链路：PauseRequestEvent → GameFlowManager.OnPauseRequest → PauseView。
            Debug.Log("[HUD] 点击暂停菜单按钮（只开菜单，不暂停）");
            EventDispatcher.TriggerEvent(EventName.PauseRequestEvent);
        }

        // ------------------------------------------------------------------
        // 倍速（P2b）
        // ------------------------------------------------------------------

        /// <summary>
        /// 点倍速按钮：按档位表循环切下一档。
        /// 【为什么这里只"发请求"而不直接改 GameClock】
        ///   HUD 不持有任何游戏逻辑（见类注释）。改档要校验"是否暂停/是否局中"，
        ///   那是 GameFlowManager 的职责 —— 直接在 UI 里写 GameClock 会绕过校验。
        /// </summary>
        private void OnClickSpeed()
        {
            EventDispatcher.TriggerEvent<float>(
                EventName.GameSpeedChangeRequestEvent, GameClock.NextTier(GameClock.Speed));
        }

        private void OnSpeedChanged(float speed)
        {
            SetSpeedLabel(speed);
        }

        /// <summary>同步倍速按钮文案：「×1 / ×2 / ×3」（非整数档位如 ×2.5 也支持）。</summary>
        private void SetSpeedLabel(float speed)
        {
            if (_speedLabel != null)
            {
                // 用 InvariantCulture：某些区域设置的小数点是逗号，会显示成「×2,5」
                _speedLabel.text = "×" + speed.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture);
            }
        }

        // ------------------------------------------------------------------
        // 事件 → 显示
        // ------------------------------------------------------------------

        /// <summary>
        /// 更新「开始 / 下一回合」按钮的文字。
        /// 自动回合倒计时会用它显示 "下一回合(3)" 这样的剩余秒数。
        /// </summary>
        public void SetStartButtonLabel(string text)
        {
            // 外部接管（自动回合倒计时每秒重写）→ 清掉配方，语言事件不再重放旧文案；
            // 倒计时每一拍都会用当前语言重新拼串，切换语言后最多一秒自然对齐。
            _startKey = null;
            if (_startLabel != null)
            {
                _startLabel.text = text;
            }
        }

        // ------------------------------------------------------------------
        // 语言切换重放（2026-10-16）
        //
        // 【为什么需要】回合文本与开始按钮文本是"事件驱动 + 手动拼词"的 —— 节点因此也没有
        //   挂 TextLocalizer（挂了反而会在切语言时把"进行中 / 回合 3"这类状态文本冲成 prefab 原文）。
        //   所以把"最近一次显示用的取词配方"记下来，收到 LanguageChangedEvent 时按同一配方重算：
        //   **只重算文本、不重放副作用**（interactable 等交互状态由原事件路径负责，不能重跑）。
        // ------------------------------------------------------------------

        private void OnLanguageChanged(int lang)
        {
            if (_roundKey != null)
            {
                SetRoundTextLocalized(_roundKey, _roundArg, _roundFallback);
            }
            if (_startKey != null)
            {
                SetStartLabelLocalized(_startKey, _startFallback);
            }
            // 暂停按钮的两态文案（Pause / Continue）没有 TextLocalizer，必须在这里重算；
            // 状态从 GameClock 现取，不依赖任何配方 —— 中途暂停/继续都不会让文案过期。
            RefreshPauseLabel();
        }

        /// <summary>暂停状态变化 → 重刷暂停按钮文案（Pause ⇄ Continue）。</summary>
        private void OnPauseStateChanged(bool paused)
        {
            RefreshPauseLabel();
        }

        /// <summary>
        /// 写暂停按钮文案：未暂停 = Pause（暂停），已暂停 = Continue（继续）。
        /// 【状态源是 GameClock.IsPaused】与"暂停的唯一写入口 GameClock.SetPaused"同一份状态，
        ///   不另存一个布尔，免得 UI 与流程层的暂停态各说各话。
        /// </summary>
        private void RefreshPauseLabel()
        {
            if (_pauseLabel == null)
            {
                return;
            }
            bool paused = GameClock.IsPaused;
            _pauseLabel.text = paused
                ? (Localization.Get("Continue") ?? "继续")
                : (Localization.Get("Pause") ?? "暂停");
            LanguageManager.ApplyFont(_pauseLabel);
        }

        /// <summary>写回合文本并记住配方（语言切换时按配方重放）。</summary>
        private void SetRoundTextLocalized(string key, int arg, string fallbackFormat)
        {
            _roundKey = key;
            _roundArg = arg;
            _roundFallback = fallbackFormat;
            LevelConfig level = Configs.GetLevel(PlayerDataManager.Instance.CurrentLevelId);
            int total = level != null ? level.RoundCount : 0;
            SetText(_roundText, Localization.Get(key, arg, total) ?? string.Format(fallbackFormat, arg, total));
            LanguageManager.ApplyFont(_roundText);
        }

        /// <summary>写开始按钮文本并记住配方（语言切换时按配方重放）。</summary>
        private void SetStartLabelLocalized(string key, string fallback)
        {
            _startKey = key;
            _startFallback = fallback;
            if (_startLabel != null)
            {
                _startLabel.text = Localization.Get(key) ?? fallback;
                LanguageManager.ApplyFont(_startLabel);
            }
        }

        /// <summary>
        /// 按当前玩家数据刷新全部显示。
        /// 【为什么必须公开】HUD 是在关卡初始化过程中才被实例化的，而
        /// PlayerStateInitEvent 在它实例化之前就已经触发过一次 —— 只靠监听事件的话，
        /// HUD 会一直显示 prefab 里的占位文案（"金币 0"）直到第一次数值变化。
        /// 所以 GameFlowManager 打开 HUD 后会显式调用一次本方法。
        /// </summary>
        public void RefreshAll()
        {
            PlayerDataManager pd = PlayerDataManager.Instance;
            SetText(_goldText, pd.Gold.ToString());
            SetText(_hpText, string.Format("{0}/{1}", pd.Hp, pd.MaxHp));
            GameFlowManager flow = GameFlowManager.Instance;
            SetRoundTextLocalized("Wave {0}/{1}", flow != null ? flow.CurrentRoundIndex : 0, "第 {0}/{1} 波");
            RefreshTowerAffordability();
        }

        private void OnGoldChanged(int current, int delta)
        {
            SetText(_goldText, current.ToString());
            // 金币变化 → 刷新塔按钮可用性（买不起的置灰）
            RefreshTowerAffordability();
        }

        /// <summary>
        /// 按当前金币刷新三颗塔按钮的 interactable。
        /// 放置中时不改（避免和"放置中"的置灰状态打架）。
        /// </summary>
        private void RefreshTowerAffordability()
        {
            if (_towerButtons == null)
            {
                return;
            }
            PlayerDataManager pd = PlayerDataManager.Instance;
            for (int i = 0; i < _towerButtons.Length; i++)
            {
                Button btn = _towerButtons[i];
                if (btn == null)
                {
                    continue;
                }

                // 按配置表决定这颗按钮是否登场：表里没有这个 type 就隐藏，
                // 免得留下"点了没反应"的死按钮。新增塔型 = 加配置行 + 加节点名。
                TowerConfig cfg = Configs.GetTowerByTypeAndLevelSilent(_towerButtonTypes[i], 1);
                if (cfg == null)
                {
                    if (btn.gameObject.activeSelf)
                    {
                        btn.gameObject.SetActive(false);
                    }
                    continue;
                }
                if (!btn.gameObject.activeSelf)
                {
                    btn.gameObject.SetActive(true);
                }

                SetText(_towerPriceTexts[i], cfg.Prices.ToString());

                // 放置中时不动 interactable：那由 SetTowerButtonState 统一管，
                // 两边都写会互相覆盖（"放置中全部置灰"会被这里刷新回可点）。
                if (!_placing)
                {
                    btn.interactable = pd.Gold >= cfg.Prices;
                }
            }
        }

        private void OnHpChanged(int current, int delta)
        {
            PlayerDataManager pd = PlayerDataManager.Instance;
            SetText(_hpText, string.Format("{0}/{1}", current, pd.MaxHp));
        }

        private void OnRoundStart(int roundIndex)
        {
            SetRoundTextLocalized("Wave {0}/{1}", roundIndex, "第 {0}/{1} 波");
        }

        private void OnWaveStart(int waveIndex)
        {
            // WaveStart 是 Round 内编组索引，不能覆盖本关的正式波次序号。
        }

        private void OnRoundClear(int roundIndex)
        {
            SetRoundTextLocalized("Wave {0}/{1} clear", roundIndex, "第 {0}/{1} 波完成");
            // 恢复"开始"按钮，让玩家推进到下一回合
            if (_startButton != null)
            {
                _startButton.interactable = true;
            }
            SetStartLabelLocalized("Next Wave", "下一波");
        }

        private void OnGameOver(bool victory)
        {
            if (_startButton != null)
            {
                _startButton.interactable = false;
            }
            if (_startLabel != null)
            {
                SetStartLabelLocalized(
                    victory ? "Cleared" : "Failed",
                    victory ? "已通关" : "已失败");
            }
            // 结算后倍速按钮不可用（策划案 §7.3：倍速档位在 GameOver 时复位且不再可切）
            if (_speedButton != null)
            {
                _speedButton.interactable = false;
            }
        }

        private void OnEnterPlacement()
        {
            _placing = true;
            SetTowerButtonState(false);
        }

        private void OnExitPlacement()
        {
            _placing = false;
            SetTowerButtonState(true);
            RefreshTowerAffordability();
        }

        private void OnBuildSuccess(BaseTower tower)
        {
            // 建完后自动退出放置模式（想连建就再点一次按钮）
            OnExitPlacement();
        }

        /// <summary>统一设置三颗塔按钮的可用性（放置中全部置灰）</summary>
        private void SetTowerButtonState(bool interactable)
        {
            if (_towerButtons == null)
            {
                return;
            }
            for (int i = 0; i < _towerButtons.Length; i++)
            {
                if (_towerButtons[i] != null)
                {
                    _towerButtons[i].interactable = interactable;
                }
            }
        }

        private static void SetText(TMP_Text t, string value)
        {
            if (t != null && t.text != value)
            {
                t.text = value;
            }
        }

        /// <summary>供金币不足时置灰塔按钮（由 TowerPlacement 调用）</summary>
        public void SetTowerButtonInteractable(bool value)
        {
            if (_placing)
            {
                return;
            }
            SetTowerButtonState(value);
        }
    }
}

namespace FTProject
{
    /// <summary>
    /// 一局结算的数据快照（通关与失败共用同一份结构）。
    ///
    /// 【为什么要单独抽一个类，而不是给 Show() 传十来个参数】
    ///   结算界面要同时用到：本次星级、**结算前的历史最高星级**、是否刷新记录、
    ///   关卡名、下一关 id、战绩三项……十几个参数挤在一个签名里，
    ///   调用点与实现点稍有出入就会错位（本项目已真实踩过一次"实参个数不匹配"的坑）。
    ///   用对象传递后，字段名即文档，增删字段也不会牵动调用签名。
    ///
    /// 【数据从哪来】
    ///   由 <see cref="GameFlowManager"/> 在回合全部结束、调用 RecordClear **之前**组装：
    ///   因为 RecordClear 会把星级"只升不降"地合并进存档，一旦先写再读，
    ///   就再也拿不到"这一局之前玩家最好打到几星"了 —— 而那正是"是否刷新记录"的依据。
    /// </summary>
    public class LevelClearInfo
    {
        /// <summary>true = 通关；false = 防御失败</summary>
        public bool victory;

        /// <summary>本关 id</summary>
        public int levelId;

        /// <summary>关卡展示名（取自配置表，失败时也可能为空）</summary>
        public string levelName;

        /// <summary>本次获得的星级 0~5（失败恒为 0）</summary>
        public int stars;

        /// <summary>唯一评分器产生的本局证据与原因。界面只展示，不重新评星。</summary>
        public LevelRatingResult ratingResult;

        /// <summary>正式成绩已成功写入存储后才允许展示新纪录或前往下一关。</summary>
        public bool progressSaved;

        /// <summary>有效成绩等待重试保存；重玩按钮在此状态下重试保存。</summary>
        public bool savePending;

        /// <summary>本局**之前**的历史最高星级，用于对比展示</summary>
        public int previousBest;

        /// <summary>本局是否刷新了历史最高星级</summary>
        public bool newRecord;

        /// <summary>本局结束时的剩余生命</summary>
        public int hp;

        /// <summary>本关最大生命</summary>
        public int maxHp;

        /// <summary>本局击杀数</summary>
        public int killed;

        /// <summary>本局漏怪数</summary>
        public int leaked;

        /// <summary>下一关 id；0 表示没有下一关（已是最后一关）</summary>
        public int nextLevelId;

        /// <summary>下一关展示名（可为空 —— 调用方拿不到配置时就不显示名字）</summary>
        public string nextLevelName;

        /// <summary>是否存在下一关（决定「下一关」按钮是否可点）</summary>
        public bool hasNext;
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 关卡结算弹窗（通关 / 失败）。
    ///
    /// ==================================================================
    /// 【为什么会有这个文件：原来根本没有"通关弹窗"】
    ///   GameFlowManager 在全部回合结束后只做了三件事：写档、触发 LevelClearEvent、
    ///   弹一条 Tips 文字。而 **LevelClearEvent 在全工程没有任何监听者** ——
    ///   事件空放，玩家自然看不到任何"通关完成"的界面。
    ///   本类就是那个缺失的接收端，改由 GameFlowManager 在 OnGameOver 里打开并 Show()。
    ///
    /// 【为什么星级要在这里显示两遍（本次 / 历史最高）】
    ///   "这个成绩好不好"只有跟自己的历史比才有意义。存档里的星级是**只升不降**的合并值，
    ///   所以如果把"本次所得"和"存档里的值"当成一回事：
    ///     · 玩家第二次打出 1 星时，界面会显示 3 星（历史最高）→ 看起来像"这次打得很好"；
    ///     · 再配上"新纪录"提示就会自相矛盾。
    ///   因此 LevelClearInfo 里同时带 stars（本次）与 previousBest（本局之前的最好成绩），
    ///   两行分开展示，谁也不冒充谁。
    ///
    /// 【本类不做的事】不改任何游戏数值、不直接碰存档 —— 统计与落库都在 GameFlowManager
    ///   与 SaveManager 里完成，本类只负责"把已经算好的结果画出来"并发事件。
    ///   这样结算逻辑无论怎么改，都不会因为界面被销毁/复用而算错。
    /// ==================================================================
    /// </summary>
    public class LevelClearView : MonoBehaviour
    {
        public const string LogicalName = "LevelClearView";

        private TMP_Text _title;
        private TMP_Text _levelName;
        private TMP_Text _stars;
        private TMP_Text _starDetail;
        private TMP_Text _recordTip;
        private TMP_Text _stats;
        private TMP_Text _ratingTimes;
        private TMP_Text _ratingReasons;
        private TMP_Text _ratingContext;
        private Button _nextBtn;
        private TMP_Text _nextLabel;
        private Button _retryBtn;
        private TMP_Text _retryLabel;
        private Button _selectBtn;

        /// <summary>当前展示的结算数据。按钮回调要用到 nextLevelId / hasNext。</summary>
        private LevelClearInfo _info;

        private void Awake()
        {
            BindNodes();
        }

        private void OnEnable()
        {
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
        }

        private void OnDisable()
        {
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
        }

        private void OnLanguageChanged(int language)
        {
            if (_info != null) Show(_info);
        }

        private void BindNodes()
        {
            _title = FindText("Panel/Title");
            _levelName = FindText("Panel/LevelName");
            _stars = FindText("Panel/Stars");
            _starDetail = FindText("Panel/StarDetail");
            _recordTip = FindText("Panel/RecordTip");
            _stats = FindText("Panel/Stats");
            _ratingTimes = FindText("Panel/RatingTimes");
            _ratingReasons = FindText("Panel/RatingReasons");
            _ratingContext = FindText("Panel/RatingContext");

            _nextBtn = FindButton("Panel/NextBtn");
            _nextLabel = FindText("Panel/NextBtn/Label");
            _retryBtn = FindButton("Panel/RetryBtn");
            _retryLabel = FindText("Panel/RetryBtn/Label");
            _selectBtn = FindButton("Panel/SelectBtn");

            if (_nextBtn != null) _nextBtn.onClick.AddListener(OnClickNext);
            if (_retryBtn != null) _retryBtn.onClick.AddListener(OnClickRetry);
            if (_selectBtn != null) _selectBtn.onClick.AddListener(OnClickSelect);

            // 【为什么 Bg 不绑"点击关闭"】其它对话框（设置/暂停/选关）点背景即关闭是合理的，
            //   它们随时能再开；但结算弹窗是一个**终结状态**，随手点掉之后玩家会卡在
            //   "关卡已结束、却没有任何入口推进"的死角里（只剩暂停键可走）。
            //   所以这里刻意留空：Bg 仍然吞掉点击（挡住下面的 HUD），但必须明确点一个按钮。
            //   注意：prefab 里 Bg 自带 Button 组件（CreateDialogShell 统一给的），只是没接回调。
        }

        /// <summary>
        /// 用一局结算数据刷新弹窗。由 GameFlowManager 在打开界面后立刻调用。
        /// 【为什么不是 OnEnable 里自己算】界面不该知道存档与流程的存在 ——
        ///   否则它被复用（对象池）时算出来的可能是上一局的结果。
        /// </summary>
        public void Show(LevelClearInfo info)
        {
            _info = info;
            if (info == null)
            {
                return;
            }

            SetText(_title, info.victory
                ? (Localization.Get("Level Clear!") ?? "通关完成！")
                : (Localization.Get("Defense Failed") ?? "防御失败"));
            SetText(_levelName, string.IsNullOrEmpty(info.levelName)
                ? (Localization.Get("Level {0}", info.levelId) ?? string.Format("关卡 {0}", info.levelId))
                : info.levelName);

            // ---- 星级评价 ----
            // 星星字形统一走 SelectView.StarRichText，避免"同一个星级在两处长得不一样"
            // （金色实心 + 暗蓝灰空心，与效果图 05 一致）
            SetText(_stars, SelectView.StarRichText(info.stars));

            if (info.victory)
            {
                SetText(_starDetail, Localization.Get("This {0}    Best {1}",
                        SelectView.StarRichText(info.stars), SelectView.StarRichText(info.previousBest))
                    ?? string.Format(
                        "<color=#9FB3C8>本次</color> {0}　　<color=#9FB3C8>历史最高</color> {1}",
                        SelectView.StarRichText(info.stars), SelectView.StarRichText(info.previousBest)));
            }
            else
            {
                // 失败不给星，但历史成绩仍然要显示 —— 这正是"重新进游戏也能看到记录"的体现
                SetText(_starDetail, Localization.Get("<color=#9FB3C8>Best</color> {0}",
                        SelectView.StarRichText(info.previousBest))
                    ?? string.Format(
                        "<color=#9FB3C8>历史最高</color> {0}",
                        SelectView.StarRichText(info.previousBest)));
            }

            // "新纪录"只在真的超过历史最好成绩时出现
            if (_recordTip != null)
            {
                bool show = info.victory && info.progressSaved && !info.savePending && info.newRecord;
                if (_recordTip.gameObject.activeSelf != show)
                {
                    _recordTip.gameObject.SetActive(show);
                }
                if (show)
                {
                    SetText(_recordTip, Localization.Get("★ New Record! Best stars improved") ?? "★ 新纪录！刷新了本关最高星级");
                }
            }

            // ---- 战绩 ----
            SetText(_stats, Localization.Get("HP {0}/{1}    Kills {2}    Leaks {3}", info.hp, info.maxHp, info.killed, info.leaked)
                ?? string.Format("剩余生命 {0}/{1}　　击杀 {2}　　漏怪 {3}",
                    info.hp, info.maxHp, info.killed, info.leaked));

            LevelRatingResult result = info.ratingResult;
            LevelRunMetrics metrics = result != null ? result.metrics : null;
            LevelRatingProfile profile = result != null ? result.profile : null;
            string combatTime = RatingPresentation.Time(metrics != null ? metrics.combatElapsedMs : 0);
            string parTime = RatingPresentation.Time(profile != null ? profile.parCombatTimeMs : 0);
            string levelTime = RatingPresentation.Time(metrics != null ? metrics.levelElapsedMs : 0);
            SetText(_ratingTimes, Localization.Get("Combat {0} / Par {1} · Level {2}", combatTime, parTime, levelTime)
                ?? string.Format("战斗 {0} / 五星上限 {1} · 整局 {2}", combatTime, parTime, levelTime));
            string context = profile == null ? string.Empty
                : SelectView.Difficulty(profile.difficultyTier) + " · "
                    + (Localization.Get("Balance preset: {0}", RatingPresentation.ProfileName(profile.profileId))
                        ?? ("调参预设：" + RatingPresentation.ProfileName(profile.profileId)));
            if (metrics != null)
            {
                context += "\n" + (Localization.Get("Boss leaks {0} · Critical leaks {1}", metrics.bossLeaked, metrics.criticalLeaked)
                    ?? string.Format("首领漏怪 {0} · 精英及首领漏怪 {1}", metrics.bossLeaked, metrics.criticalLeaked));
            }
            SetText(_ratingContext, context);
            SetText(_ratingReasons, RatingPresentation.Reasons(result));

            // ---- 按钮 ----
            // 三种情况分开处理，避免"最后一关却显示一个可点的下一关"或
            // "失败时显示已是最后一关"这类自相矛盾的文案。
            if (_nextBtn != null)
            {
                if (!info.victory || !info.progressSaved || info.savePending || result == null || !result.valid)
                {
                    _nextBtn.gameObject.SetActive(false);          // 失败没有下一关可言
                }
                else
                {
                    bool canGo = info.hasNext && info.nextLevelId > 0 && result != null && result.valid;
                    _nextBtn.gameObject.SetActive(true);
                    _nextBtn.interactable = canGo;
                    if (!canGo)
                    {
                        SetText(_nextLabel, Localization.Get("Final Level") ?? "已是最后一关");
                    }
                    else if (!string.IsNullOrEmpty(info.nextLevelName))
                    {
                        SetText(_nextLabel, Localization.Get("Next: {0}", info.nextLevelName)
                            ?? ("下一关：" + info.nextLevelName));
                    }
                    else
                    {
                        SetText(_nextLabel, Localization.Get("Next Level") ?? "下一关");
                    }
                }
            }

            SetText(_retryLabel, info.savePending
                ? (Localization.Get("Retry Save") ?? "重试保存")
                : info.victory
                    ? (Localization.Get("Replay") ?? "重玩本关")
                    : (Localization.Get("Try Again") ?? "重新挑战"));
        }

        // ------------------------------------------------------------------
        // 交互 → 事件（真正的跳转由 GameFlowManager 执行，见其事件监听）
        // ------------------------------------------------------------------

        private void OnClickNext()
        {
            if (_info == null || !_info.victory || !_info.progressSaved || _info.savePending
                || _info.ratingResult == null || !_info.ratingResult.valid
                || !_info.hasNext || _info.nextLevelId <= 0)
            {
                return;
            }
            // 复用「选择关卡」请求，让下一关和玩家手点关卡走**同一条**入口（StartLevel），
            // 否则两套启动路径迟早分叉。
            EventDispatcher.TriggerEvent<int>(EventName.SelectLevelRequestEvent, _info.nextLevelId);
        }

        private void OnClickRetry()
        {
            if (_info != null && _info.savePending)
            {
                if (GameFlowManager.Instance != null) GameFlowManager.Instance.RetryPendingClearSave();
                return;
            }
            EventDispatcher.TriggerEvent(EventName.RestartLevelRequestEvent);
        }

        private void OnClickSelect()
        {
            EventDispatcher.TriggerEvent(EventName.QuitToSelectRequestEvent);
        }

        // ------------------------------------------------------------------
        // 节点查找（与 SettingView / PauseView 同口径：缺节点只警告、不阻断）
        // ------------------------------------------------------------------

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Clear] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Clear] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }

        private static void SetText(TMP_Text t, string v)
        {
            if (t != null)
            {
                if (t.text != v) t.text = v;
                LanguageManager.ApplyFont(t);
            }
        }
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 关卡详情（UI 补全 B4 / 效果图 21_LevelDetailView.svg）。
    ///
    /// 【它解决什么问题】改造前点选关卡片**直接进关**，玩家看不到"几回合、多少波、
    /// 什么难度、历史最好多久"，进关才发现不是自己想要的，只能退出来。
    ///
    /// 【为什么走 SelectLevelRequestEvent 而不是直接 StartLevel】
    ///   选关界面与结算界面本来都在用这条事件，详情窗口再插一条新链路就会出现
    ///   "从详情进关"与"从卡片进关"两套入口，将来改建关流程必然漏改一处。
    /// </summary>
    public class LevelDetailView : MonoBehaviour
    {
        public const string LogicalName = "LevelDetailView";

        /// <summary>怪物名字最多显示几个（效果图 21 的图标行一屏放得下 7 个）。</summary>
        private const int MaxEnemyNames = 7;

        private static readonly Color Gold = new Color(1f, 0.788f, 0.302f, 1f);           // #FFC94D
        private static readonly Color StarOff = new Color(0.22f, 0.27f, 0.35f, 1f);       // 未获得的星
        private static readonly Color TextPrimary = new Color(0.910f, 0.941f, 0.980f, 1f);
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f);

        private TMP_Text _title;
        private TMP_Text _levelName;
        private TMP_Text _bestStarText;
        private TMP_Text _enemyLabel;
        private TMP_Text _enemyIcons;
        private TMP_Text _ratingTarget;
        private readonly Image[] _stars = new Image[LevelRatingEvaluator.MaxStars];
        private readonly TMP_Text[] _info = new TMP_Text[6];
        private Button _playBtn;
        private Button _replayBtn;
        private Button _closeBtn;
        private TMP_Text _playLabel;

        private int _levelId;

        private void OnEnable()
        {
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
        }

        private void OnDisable()
        {
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
        }

        private void OnLanguageChanged(int language)
        {
            if (_levelId > 0) Fill(_levelId);
        }

        /// <summary>打开并展示某一关的详情。levelId 非法时直接不显示（不弹空窗）。</summary>
        public static void Show(int levelId)
        {
            LevelConfig lv = Configs.GetLevel(levelId);
            if (lv == null)
            {
                Debug.LogWarning("[LevelDetail] 关卡 " + levelId + " 不存在，无法显示详情");
                return;
            }
            LevelDetailView view = UIManager.Instance.Open<LevelDetailView>(LogicalName, UILayout.NormalPanel);
            if (view == null)
            {
                Debug.LogError("[LevelDetail] LevelDetailView 打开失败（prefab 可能还没生成）");
                return;
            }
            view.Fill(levelId);
        }

        private void Awake()
        {
            _title = FindText("Panel/DetailTitle");
            _levelName = FindText("Panel/LevelName");
            _bestStarText = FindText("Panel/BestStarText");
            _enemyLabel = FindText("Panel/EnemyLabel");
            _enemyIcons = FindText("Panel/EnemyIcons");
            _ratingTarget = FindText("Panel/RatingTarget");
            _playBtn = FindButton("Panel/PlayBtn");
            _replayBtn = FindButton("Panel/ReplayBtn");
            _closeBtn = FindButton("Panel/CloseBtn");
            _playLabel = FindText("Panel/PlayBtn/Label");

            // ⚠️ 逐个写开而不是循环：`transform.Find("Panel/Star" + i)` 这种拼接写法会让
            //   节点契约校验脚本只取到字面量前缀（"Panel/Star"），从而误报"生成器不产出该节点"。
            _stars[0] = FindImage("Panel/Star1");
            _stars[1] = FindImage("Panel/Star2");
            _stars[2] = FindImage("Panel/Star3");
            _stars[3] = FindImage("Panel/Star4");
            _stars[4] = FindImage("Panel/Star5");

            _info[0] = FindText("Panel/Info1");
            _info[1] = FindText("Panel/Info2");
            _info[2] = FindText("Panel/Info3");
            _info[3] = FindText("Panel/Info4");
            _info[4] = FindText("Panel/Info5");
            _info[5] = FindText("Panel/Info6");

            if (_playBtn != null) _playBtn.onClick.AddListener(OnClickPlay);
            if (_replayBtn != null) _replayBtn.onClick.AddListener(OnClickReplay);
            if (_closeBtn != null) _closeBtn.onClick.AddListener(OnClickClose);
            Button bg = FindButton("Bg");
            if (bg != null) bg.onClick.AddListener(OnClickClose);

            if (_title != null) _title.color = TextPrimary;
            if (_levelName != null) _levelName.color = TextSecondary;
            if (_bestStarText != null) _bestStarText.color = TextSecondary;
            if (_enemyLabel != null) _enemyLabel.color = TextSecondary;
            if (_enemyIcons != null) _enemyIcons.color = TextPrimary;
            for (int i = 0; i < _info.Length; i++)
            {
                if (_info[i] != null) _info[i].color = TextPrimary;
            }
        }

        private void Fill(int levelId)
        {
            _levelId = levelId;
            LevelConfig lv = Configs.GetLevel(levelId);
            if (lv == null)
            {
                return;
            }

            SetText(_title, Localization.Get("Level {0} Detail", levelId) ?? string.Format("第 {0} 关", levelId));
            // 关卡名走 LevelName（词条 "Level {0}" 按 id 格式化；数据里的 name 是中文单一语言）
            SetText(_levelName, string.IsNullOrEmpty(lv.Name) ? string.Empty : Localization.LevelName(levelId, lv.Name));

            SaveManager sm = SaveManager.Instance;
            int stars = sm != null ? sm.GetStars(levelId) : 0;
            bool unlocked = sm == null || sm.IsUnlocked(levelId);

            for (int i = 0; i < _stars.Length; i++)
            {
                if (_stars[i] != null)
                {
                    _stars[i].color = i < stars ? Gold : StarOff;
                }
            }
            // 【为什么先算出字符串再赋值】把三元表达式拆成独立语句：
            // 多行调用会让参数个数的静态校验脚本误判（它按行解析）。
            string bestText = stars > 0
                ? (Localization.Get("Current version best: {0}/5", stars) ?? string.Format("本版历史最佳：{0}/5", stars))
                : (sm != null && sm.GetLegacyStars(levelId) > 0
                    ? (Localization.Get("Legacy clear; current version unrated") ?? "旧版已通关，本版待评定")
                    : (Localization.Get("Current version unrated") ?? "本版待评定"));
            SetText(_bestStarText, bestText);

            // 波次总数 = 各回合的 WaveCount 之和（回合数 ≠ 波数，分开显示）
            List<int> roundIds = lv.RoundIds;
            HashSet<int> enemyIds = new HashSet<int>();
            if (roundIds != null)
            {
                for (int i = 0; i < roundIds.Count; i++)
                {
                    RoundConfig round = Configs.GetRound(roundIds[i]);
                    if (round == null)
                    {
                        continue;
                    }
                    List<int> waveIds = round.WaveIds;
                    if (waveIds == null)
                    {
                        continue;
                    }
                    for (int w = 0; w < waveIds.Count; w++)
                    {
                        WaveGroupConfig group = Configs.GetWaveGroup(waveIds[w]);
                        List<int> ids = group != null ? group.EnemyIds : null;
                        if (ids == null)
                        {
                            continue;
                        }
                        for (int e = 0; e < ids.Count; e++)
                        {
                            enemyIds.Add(ids[e]);
                        }
                    }
                }
            }

            LevelRatingProfile rating = Configs.GetLevelRating(levelId);
            long bestTimeMs = sm != null ? sm.GetBestCombatTimeMs(levelId) : 0;

            SetText(_info[0], Localization.Get("Waves     {0}", lv.RoundCount) ?? string.Format("波次　　{0}", lv.RoundCount));
            string profileName = rating != null ? RatingPresentation.ProfileName(rating.profileId) : "—";
            SetText(_info[1], Localization.Get("Balance preset: {0}", profileName) ?? ("调参预设：" + profileName));
            SetText(_info[2], Localization.Get("Start Gold {0}", lv.InitialGold) ?? string.Format("初始金币　{0}", lv.InitialGold));
            SetText(_info[3], Localization.Get("Start HP   {0}", lv.InitialHp) ?? string.Format("初始生命　{0}", lv.InitialHp));
            SetText(_info[4], SelectView.Difficulty(lv.Difficulty));
            // 【最佳用时】0 显示成 --:--（SaveManager.FormatTime 统一口径）——
            // "没有记录"与"0 秒通关"必须一眼分得开
            SetText(_info[5], Localization.Get("Best combat: {0}", RatingPresentation.Time(bestTimeMs))
                ?? ("最佳战斗用时：" + RatingPresentation.Time(bestTimeMs)));
            string target = rating == null
                ? (Localization.Get("Rating config missing or invalid") ?? "评分配置缺失或无效")
                : (Localization.Get("Five-star target: full HP, no leaks, all enemies defeated; combat ≤ {0}", RatingPresentation.Time(rating.parCombatTimeMs))
                    ?? ("五星目标：满血、无漏怪、全部击杀；战斗用时 ≤ " + RatingPresentation.Time(rating.parCombatTimeMs)));
            string calibrationNotice = rating != null && rating.calibrationStatus == "verified_unity_reference"
                ? "" : "\n" + (Localization.Get("Time baseline pending verification") ?? "时间基准待验证");
            SetText(_ratingTarget, target + "\n" + (Localization.Get("Combat time excludes preparation, inter-wave waits and pauses") ?? "战斗用时不含开场准备、波间等待与暂停")
                + calibrationNotice);

            SetText(_enemyLabel, Localization.Get("Enemies in this level") ?? "本关出现怪物");
            SetText(_enemyIcons, BuildEnemySummary(enemyIds));

            // 未解锁的关卡不给"开始挑战"，只留"返回"（效果图 21 的既定行为）
            if (_playBtn != null && _playBtn.gameObject.activeSelf != unlocked)
            {
                _playBtn.gameObject.SetActive(unlocked);
            }
            if (_playLabel != null)
            {
                _playLabel.text = stars > 0
                    ? (Localization.Get("Challenge Again") ?? "再次挑战")
                    : (Localization.Get("Start Challenge") ?? "开始挑战");
            }
            if (_replayBtn != null && _replayBtn.gameObject.activeSelf != unlocked)
            {
                _replayBtn.gameObject.SetActive(unlocked);
            }
        }

        /// <summary>
        /// 怪物一览。当前用**名字串**而不是图标：怪物图标是图集（`Atlas_&lt;怪名&gt;`），
        /// 要做成图标行得先给每个怪生成一个 Image 节点并运行时按怪名取图集 ——
        /// 那是"图鉴界面（B2/B3）"的活。这里先用真实数据把"有哪些怪"讲清楚，
        /// 不编造图标，也不写死数量。
        /// 【为什么按显示名去重】(2026-10-16) 多个 id 可能是"同名同形"的怪
        ///   （如 NormalEnemy 的 id 1/4/7），不去重会连列好几个"普通怪"。
        /// </summary>
        private string BuildEnemySummary(HashSet<int> enemyIds)
        {
            if (enemyIds.Count == 0)
            {
                return "—";
            }
            List<int> sorted = new List<int>(enemyIds);
            sorted.Sort();

            // 先按"显示名"去重（同名怪只留首次出现），再按上限截断
            List<string> names = new List<string>();
            HashSet<string> seen = new HashSet<string>();
            for (int i = 0; i < sorted.Count; i++)
            {
                EnemyConfig cfg = Configs.GetEnemy(sorted[i]);
                if (cfg == null)
                {
                    continue;
                }
                string display = string.IsNullOrEmpty(cfg.Name)
                    ? ("#" + sorted[i])
                    : (Localization.Get(cfg.Name) ?? cfg.Name);   // 怪物名过多语言表（缺条目回退英文原名）
                if (seen.Add(display))
                {
                    names.Add(display);
                }
            }

            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            int shown = Mathf.Min(names.Count, MaxEnemyNames);
            for (int i = 0; i < shown; i++)
            {
                if (i > 0)
                {
                    sb.Append("　");
                }
                sb.Append(names[i]);
            }
            if (names.Count > shown)
            {
                sb.Append(Localization.Get("    {0} kinds", names.Count)
                    ?? string.Format("　等 {0} 种", names.Count));
            }
            return sb.ToString();
        }

        private void OnClickPlay()
        {
            int id = _levelId;
            UIManager.Instance.Close(LogicalName);
            // 复用既有入口：选关界面与结算界面都发这个事件
            EventDispatcher.TriggerEvent<int>(EventName.SelectLevelRequestEvent, id);
        }

        private void OnClickReplay()
        {
            SaveManager save = SaveManager.Instance;
            // 选关入口会续玩兼容快照；“从头重打”须先确认清除已落盘，再进入同一入口。
            if (save != null && !save.TryClearSnapshot())
            {
                EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent,
                    Localization.Get("Checkpoint could not be cleared; original progress preserved")
                    ?? "未能清除续玩存档，原进度已保留");
                return;
            }
            OnClickPlay();
        }

        private void OnClickClose()
        {
            UIManager.Instance.Close(LogicalName);
        }

        private static void SetText(TMP_Text t, string v)
        {
            if (t != null)
            {
                if (t.text != v) t.text = v;
                LanguageManager.ApplyFont(t);
            }
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[LevelDetail] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[LevelDetail] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }

        private Image FindImage(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[LevelDetail] 缺少图片节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Image>();
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 切关加载遮罩（UI 补全 C4）。
    ///
    /// 【它解决什么问题】`StartLevel` → `TeardownLevel` → `InitLevel` 是一条**同步**链路：
    ///   拆棋盘、清实体、按配置重建棋盘与路径全在同一帧里做完。关卡越大这一帧越长，
    ///   玩家看到的是"画面一黑/一闪，然后新关卡已经在了"——没有过渡，像卡了一下。
    ///
    /// 【为什么用代码建而不是走 UIPrefabBuilder】
    ///   ① 它必须在**任何时刻**都能显示，不能受"资源系统是否就绪""prefab 是否已生成"影响；
    ///   ② 它不属于任何 UILayout 层（要压在所有界面之上），硬塞进 NormalPanel 会跟 Tips 抢层级；
    ///   ③ 工程里已有同样的先例：`FloatingTextManager` 也是纯代码懒创建的 Canvas。
    ///   所以这里用独立 Canvas + 高 sortingOrder，不新增 UILayout 枚举。
    ///
    /// 【为什么必须是"延迟一帧"的用法】同步链路里 show 完立刻 hide，本帧根本不会渲染遮罩。
    ///   调用方必须先 `Show`，`yield return null` 一帧，再做重活，最后 `Hide`（见 GameFlowManager）。
    ///
    /// 【时间基准】一律 `unscaledDeltaTime`：切关时 `timeScale` 可能是 0（从暂停界面重开），
    ///   用缩放时间会让遮罩永远淡不出去。
    /// </summary>
    public class LevelLoadingMask : MonoBehaviour
    {
        /// <summary>遮罩最高不透明度（留一点底透出来，避免纯黑像崩溃）。</summary>
        private const float MaxAlpha = 0.9f;

        private const float FadeInSec = 0.12f;
        private const float FadeOutSec = 0.18f;

        /// <summary>sortingOrder 取 500：远高于 UICanvas（背景/常规/提示三层都在 0 附近）。</summary>
        private const int SortingOrder = 500;

        private static LevelLoadingMask _instance;

        private CanvasGroup _cg;
        private TMP_Text _text;
        private float _targetAlpha;
        private bool _visible;

        /// <summary>显示遮罩并设置文案（首次调用会懒创建整块遮罩）。</summary>
        public static void Show(string text)
        {
            Ensure();
            if (_instance == null)
            {
                return;
            }
            if (_instance._text != null)
            {
                _instance._text.text = text;
            }
            _instance.SetVisible(true);
        }

        /// <summary>开始淡出（淡完自动 SetActive(false)，不销毁 —— 下一关还要用）。</summary>
        public static void Hide()
        {
            if (_instance != null)
            {
                _instance.SetVisible(false);
            }
        }

        /// <summary>是否显示中（调试/自检用）。</summary>
        public static bool IsShowing
        {
            get { return _instance != null && _instance._visible; }
        }

        private static void Ensure()
        {
            if (_instance != null)
            {
                return;
            }

            GameObject root = new GameObject("LevelLoadingMask", typeof(RectTransform));
            Object.DontDestroyOnLoad(root);

            Canvas canvas = root.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = SortingOrder;

            CanvasScaler scaler = root.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;

            _instance = root.AddComponent<LevelLoadingMask>();

            GameObject bg = new GameObject("Bg", typeof(RectTransform));
            bg.transform.SetParent(root.transform, false);
            RectTransform brt = (RectTransform)bg.transform;
            brt.anchorMin = Vector2.zero;
            brt.anchorMax = Vector2.one;
            brt.offsetMin = Vector2.zero;
            brt.offsetMax = Vector2.zero;
            Image bgImg = bg.AddComponent<Image>();
            bgImg.color = new Color(0.031f, 0.043f, 0.071f, 1f);   // #080B12
            bgImg.raycastTarget = true;   // 挡住底下的误点（加载中不该能操作）

            GameObject textGo = new GameObject("Text", typeof(RectTransform));
            textGo.transform.SetParent(root.transform, false);
            RectTransform trt = (RectTransform)textGo.transform;
            trt.anchorMin = new Vector2(0.5f, 0.5f);
            trt.anchorMax = new Vector2(0.5f, 0.5f);
            trt.pivot = new Vector2(0.5f, 0.5f);
            trt.anchoredPosition = Vector2.zero;
            trt.sizeDelta = new Vector2(1200f, 60f);
            TextMeshProUGUI tmp = textGo.AddComponent<TextMeshProUGUI>();
            // 字体按当前语言取（多语言设置优先）；取不到再退 ResTable 里的中文 SDF，最后退 TMP 默认。
            // 遮罩只在切关时使用，那时资源系统早已就绪。
            TMP_FontAsset font = null;
            LanguageManager.EnsureSettings();
            if (LanguageManager.Settings != null)
            {
                font = LanguageManager.GetFont(LanguageManager.Current);
            }
            if (font == null && ResLoader.Instance.IsReady)
            {
                font = ResLoader.Instance.Load<TMP_FontAsset>("Font_SiYuanSongTi_SDF");
            }
            if (font == null)
            {
                font = TMP_Settings.defaultFontAsset;
            }
            if (font != null)
            {
                tmp.font = font;
            }
            tmp.fontSize = 34f;
            tmp.alignment = TextAlignmentOptions.Center;
            tmp.color = new Color(0.910f, 0.941f, 0.980f, 1f);
            tmp.raycastTarget = false;
            tmp.text = string.Empty;

            _instance._cg = root.AddComponent<CanvasGroup>();
            _instance._cg.alpha = 0f;
            _instance._text = tmp;
            _instance._visible = false;
            root.SetActive(false);
        }

        private void SetVisible(bool visible)
        {
            _visible = visible;
            _targetAlpha = visible ? MaxAlpha : 0f;
            if (visible)
            {
                gameObject.SetActive(true);
            }
        }

        private void Update()
        {
            float dt = Time.unscaledDeltaTime;
            // 速度按"全程跨度 / 该方向的时长"算，淡入淡出各用各的时长
            bool fadingIn = _targetAlpha > _cg.alpha;
            float speed = MaxAlpha / (fadingIn ? FadeInSec : FadeOutSec);
            _cg.alpha = Mathf.MoveTowards(_cg.alpha, _targetAlpha, speed * dt);

            if (!_visible && _cg.alpha <= 0.001f && gameObject.activeSelf)
            {
                gameObject.SetActive(false);
            }
        }
    }
}

using TMPro;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 资源加载进度界面（UI 补全 A2 / 效果图 16_LoadingView.svg）。
    ///
    /// 【进度从哪来】只听 `LoadingProgressEvent(phase, progress)`，由 Launcher 在启动链各阶段发布。
    /// 界面**不认识** Launcher、ResLoader、Configs —— 换实现不用改这里。
    /// progress 传负数表示失败（见 Launcher.PublishLoadingFailed）。
    ///
    /// 【为什么进度条必须补间，不能直接赋真实值】真实进度是"阶段跳变"的：
    /// 资源系统 0→0.3 几乎是瞬时的，配置表 0.3→0.9 又要等一会儿。
    /// 直接赋值会让数字"啪"地跳一下，看起来像卡顿。这里用 SmoothDamp 追目标值，
    /// 表现为平滑滚动，同时**最终一定收敛到真实值**（不会像固定速度的假进度那样跑飞）。
    /// </summary>
    public class LoadingView : MonoBehaviour
    {
        public const string LogicalName = "LoadingView";

        /// <summary>进度条满宽（必须与 UIPrefabBuilder 里的 ProgressBar 宽度一致）。</summary>
        public const float FillMaxWidth = 900f;

        private const float SmoothSec = 0.3f;
        private const float TipSwitchSec = 3.5f;

        private static readonly Color TextPrimary = new Color(0.910f, 0.941f, 0.980f, 1f);   // #E8F0FA
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f); // #9FB3C8
        private static readonly Color Gold = new Color(1f, 0.788f, 0.302f, 1f);              // #FFC94D
        private static readonly Color Danger = new Color(1f, 0.302f, 0.369f, 1f);            // #FF4D5E

        /// <summary>
        /// 加载提示池（策划案 §A2 的 7 条，2026-10-14 起随穿透塔移除剩 6 条）。
        /// ⚠️ 刻意**不写"退回 70%"**：当前 tbglobal 的 sellRefundRate = 1（100%），
        /// 写死 70% 会变成一句与实现不符的假承诺。等数值定稿后再补数字。
        /// </summary>
        private static readonly string[] Tips =
        {
            "可以在任意空地建塔，路径会实时重算",
            "塔没有目标时绝不会浪费火力",
            "出售塔可以退回一部分累计投入",
            "减速塔能大幅提升周围所有塔的输出",
            "飞行怪会无视地面路径，注意覆盖对空",
            "回合之间有布防时间，也可以立即开始",
        };

        /// <summary>Tips 对应的多语言 key（与 Tips 一一对应，取不到 key 时回退中文原文）。</summary>
        private static readonly string[] TipKeys =
        {
            "You can build on any open ground; paths recompute in real time.", "Towers never waste fire when they have no target.", "Selling a tower refunds part of its total investment.", "Slow towers greatly boost the damage of all nearby towers.",
            "Flying enemies ignore ground paths; watch your anti-air coverage.", "There is build time between rounds, but you can start early.",
        };

        private TMP_Text _statusText;
        private TMP_Text _percentText;
        private TMP_Text _tipText;
        private RectTransform _fill;
        private RectTransform _glow;

        private float _target;
        private float _shown;
        private float _velocity;
        private float _tipTimer;
        private int _tipIndex = -1;

        private void Awake()
        {
            _statusText = FindText("Panel/StatusText");
            _percentText = FindText("Panel/PercentText");
            _tipText = FindText("Panel/TipText");
            _fill = FindRect("Panel/ProgressBar/Fill");
            _glow = FindRect("Panel/ProgressBar/Glow");

            if (_percentText != null) _percentText.color = Gold;
            if (_tipText != null) _tipText.color = TextSecondary;

            ApplyProgress(0f);
        }

        private void OnEnable()
        {
            EventDispatcher.AddEventListener<string, float>(EventName.LoadingProgressEvent, OnProgress);
            _tipIndex = -1;
            ShowNextTip();
            _tipTimer = TipSwitchSec;
        }

        private void OnDisable()
        {
            EventDispatcher.RemoveEventListener<string, float>(EventName.LoadingProgressEvent, OnProgress);
        }

        private void OnProgress(string phase, float progress)
        {
            if (progress < 0f)
            {
                SetFailed(phase);
                return;
            }

            if (_statusText != null)
            {
                _statusText.text = phase;
                _statusText.color = TextPrimary;
            }
            if (_percentText != null)
            {
                _percentText.color = Gold;
            }
            _target = Mathf.Clamp01(progress);
        }

        private void Update()
        {
            float dt = Time.unscaledDeltaTime;

            _shown = Mathf.SmoothDamp(_shown, _target, ref _velocity, SmoothSec, Mathf.Infinity, dt);
            if (Mathf.Abs(_shown - _target) < 0.0005f)
            {
                _shown = _target;
                _velocity = 0f;
            }
            ApplyProgress(_shown);

            _tipTimer -= dt;
            if (_tipTimer <= 0f)
            {
                ShowNextTip();
                _tipTimer = TipSwitchSec;
            }
        }

        /// <summary>加载失败：状态文字转红并把原因显示出来，**绝不静默卡住**。</summary>
        public void SetFailed(string reason)
        {
            if (_statusText != null)
            {
                _statusText.text = reason;
                _statusText.color = Danger;
            }
            if (_percentText != null)
            {
                _percentText.color = Danger;
            }
        }

        private void ApplyProgress(float t)
        {
            float clamped = Mathf.Clamp01(t);
            SetFillWidth(_fill, clamped);
            SetFillWidth(_glow, clamped);
            if (_percentText != null)
            {
                _percentText.text = Mathf.RoundToInt(clamped * 100f) + "%";
            }
        }

        private static void SetFillWidth(RectTransform rt, float t)
        {
            if (rt == null)
            {
                return;
            }
            Vector2 size = rt.sizeDelta;
            size.x = FillMaxWidth * t;
            rt.sizeDelta = size;
        }

        private void ShowNextTip()
        {
            if (_tipText == null || Tips.Length == 0)
            {
                return;
            }
            // 顺序轮播而不是随机：随机会出现"连续两次同一条"，看起来像没换
            _tipIndex = (_tipIndex + 1) % Tips.Length;
            string key = _tipIndex < TipKeys.Length ? TipKeys[_tipIndex] : null;
            _tipText.text = (key != null ? Localization.Get(key) : null) ?? Tips[_tipIndex];
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Loading] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private RectTransform FindRect(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Loading] 缺少矩形节点「" + path + "」");
                return null;
            }
            return tr as RectTransform;
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 主菜单（UI 补全 B1 / 效果图 18_MainMenuView.svg）。
    ///
    /// 【它解决什么问题】改造前开机直接进关卡选择，没有"开始游戏 / 图鉴 / 设置 / 退出"的入口页，
    /// 玩家第一次进来会莫名其妙地站在选关页上。
    ///
    /// 【为什么所有按钮都发事件、不直接操作】
    ///   主菜单是"门面"，不该知道 SelectView 怎么开、设置界面挂在哪一层。
    ///   统一由 GameFlowManager 收事件再决定，改跳转逻辑时不用动本类。
    /// </summary>
    public class MainMenuView : MonoBehaviour
    {
        public const string LogicalName = "MainMenuView";

        private static readonly Color Cyan = new Color(0.208f, 0.878f, 1f, 1f);           // #35E0FF
        private static readonly Color Gold = new Color(1f, 0.788f, 0.302f, 1f);           // #FFC94D
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f);
        private static readonly Color TextTertiary = new Color(0.369f, 0.451f, 0.588f, 1f);

        private TMP_Text _title;
        private TMP_Text _subtitle;
        private TMP_Text _starText;
        private TMP_Text _clearText;
        private TMP_Text _version;
        private Button _startBtn;
        private Button _codexBtn;
        private Button _settingBtn;
        private Button _quitBtn;

        private void Awake()
        {
            _title = FindText("Panel/GameTitle");
            _subtitle = FindText("Panel/Subtitle");
            _starText = FindText("Panel/StatBg/StarText");
            _clearText = FindText("Panel/StatBg/ClearText");
            _version = FindText("Panel/Version");
            _startBtn = FindButton("Panel/StartBtn");
            _codexBtn = FindButton("Panel/CodexBtn");
            _settingBtn = FindButton("Panel/SettingBtn");
            _quitBtn = FindButton("Panel/QuitBtn");

            if (_startBtn != null) _startBtn.onClick.AddListener(OnClickStart);
            if (_codexBtn != null) _codexBtn.onClick.AddListener(OnClickCodex);
            if (_settingBtn != null) _settingBtn.onClick.AddListener(OnClickSetting);
            if (_quitBtn != null) _quitBtn.onClick.AddListener(OnClickQuit);

            if (_title != null) _title.color = Cyan;
            if (_subtitle != null) _subtitle.color = TextSecondary;
            if (_starText != null) _starText.color = Gold;
            if (_clearText != null) _clearText.color = TextSecondary;
            if (_version != null)
            {
                _version.color = TextTertiary;
                // 底部中间版本行（P：版本号显示与日志）：显示"应用版本 · 资源版本"。
                // 资源版本来自 YooAsset 激活清单 —— 热更完成后进主菜单，这里自动变成新版本；
                // 编辑器直读 / 纯 AB 模式下资源版本拿不到，只显示应用版本。
                // 打开主菜单时资源系统必然已 Init（配置表都加载完了），此时取值即最终版本。
                _version.text = VersionInfo.BuildDisplayVersion();
            }
        }

        private void OnEnable()
        {
            RefreshStats();
            Subscribe();
        }

        private void OnDisable()
        {
            Unsubscribe();
        }

        // ------------------------------------------------------------------
        // 语言切换（2026-10-16）
        // 【为什么主菜单要听这个】设置界面就从主菜单的「SettingsBtn」进 —— 打开设置时
        //   主菜单在全屏遮罩背后；切完语言关闭设置，立刻会看到它。静态文案由 TextLocalizer
        //   自动刷新，这里补的是"代码手动拼出来的动态文本"（通关进度行）。
        // ------------------------------------------------------------------

        private bool _subscribed;

        private void Subscribe()
        {
            if (_subscribed)
            {
                return;
            }
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = true;
        }

        private void Unsubscribe()
        {
            if (!_subscribed)
            {
                return;
            }
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = false;
        }

        private void OnLanguageChanged(int lang)
        {
            RefreshStats();
        }

        /// <summary>
        /// 刷新玩家总览。**全部实时读存档，绝不硬编码** ——
        /// 硬编码的"12/24"在加了新关卡之后必然与实际不符，而且没人会想起来改。
        /// </summary>
        private void RefreshStats()
        {
            int totalLevels = Configs.LevelTable != null && Configs.LevelTable.DataList != null
                ? Configs.LevelTable.DataList.Count
                : 0;
            SaveManager sm = SaveManager.Instance;
            if (sm != null)
            {
                SetText(_starText, string.Format("{0}/{1}", sm.TotalStars, totalLevels * LevelRatingEvaluator.MaxStars));
                SetText(_clearText, Localization.Get("Cleared {0}/{1}", sm.ClearedCount, totalLevels)
                    ?? string.Format("已通关 {0}/{1}", sm.ClearedCount, totalLevels));
            }
            else
            {
                SetText(_starText, string.Format("0/{0}", totalLevels * LevelRatingEvaluator.MaxStars));
                SetText(_clearText, Localization.Get("Cleared {0}/{1}", 0, totalLevels)
                    ?? string.Format("已通关 0/{0}", totalLevels));
            }

            // 字体跟随语言（这两行是手动拼写的文本，不在 TextLocalizer 管辖内）
            LanguageManager.ApplyFont(_starText);
            LanguageManager.ApplyFont(_clearText);
        }

        // ------------------------------------------------------------------
        // 操作 → 事件
        // ------------------------------------------------------------------

        private void OnClickStart()
        {
            EventDispatcher.TriggerEvent(EventName.StartGameRequestEvent);
        }

        private void OnClickCodex()
        {
            // 参数 true = 塔图鉴；怪物图鉴用 false（同一事件，少一个事件名）
            EventDispatcher.TriggerEvent<bool>(EventName.OpenCodexRequestEvent, true);
        }

        private void OnClickSetting()
        {
            EventDispatcher.TriggerEvent(EventName.OpenSettingsRequestEvent);
        }

        private void OnClickQuit()
        {
            // 退出是"不可撤销"的（对玩家来说等于关掉游戏），必须先确认
            ConfirmView.Show(
                Localization.Get("Quit Game") ?? "退出游戏",
                Localization.Get("Are you sure you want to quit?") ?? "确定要退出游戏吗？",
                ConfirmType.Warning, DoQuit,
                Localization.Get("Quit") ?? "退出",
                Localization.Get("Cancel") ?? "取消");
        }

        private static void DoQuit()
        {
#if UNITY_EDITOR
            // 编辑器里 Application.Quit() 没有任何效果，会让人以为按钮坏了
            UnityEditor.EditorApplication.isPlaying = false;
#else
            Application.Quit();
#endif
        }

        private static void SetText(TMP_Text t, string v)
        {
            if (t != null && t.text != v)
            {
                t.text = v;
            }
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[MainMenu] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[MainMenu] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 暂停菜单弹窗（M3-6；2026-10-18 起与"暂停"解耦）。
    ///
    /// 【它现在是什么】一个**菜单浮层**：继续 / 重开 / 设置 / 退出选关。
    ///   入口 = HUD 右上角 Btn_Intro（原 Btn_Pause 的弹窗能力迁移过来）。
    ///   标题按状态取词：已暂停 → `Game Paused`；未暂停 → `Menu`（见 Refresh）。
    ///   （Btn_Intro 的按钮文案 2026-10-18 也从 `Game Intro` 改成了 `Menu`，与之对应）
    ///
    /// 【为什么不再碰 timeScale】2026-10-18 的需求把两件事拆开了：
    ///   · 暂停/继续 = Btn_Pause（或热键 P）→ GameFlowManager.TogglePause → GameClock.SetPaused；
    ///   · 打开本菜单 = 只摆 UI，不改变游戏时间（点 Btn_Intro 不该把游戏停住）。
    ///   所以本界面**不再在 OnEnable 压 timeScale、也不在 OnDisable 恢复**——
    ///   那种"界面负责暂停"的写法会在"开着菜单被人从别处解除暂停"时把时间又写回去，
    ///   与流程层的暂停状态互相打架（这正是本次要清理的遗留耦合）。
    ///   时间恢复的唯一入口是 GameClock.SetPaused(false)（GameFlowManager 负责）。
    ///
    /// 【本界面不做的事】不改任何游戏数值，只发事件；真正的重开/退出由 GameFlowManager 执行。
    /// </summary>
    public class PauseView : MonoBehaviour
    {
        public const string LogicalName = "PauseView";

        private Button _resumeBtn;
        private Button _restartBtn;
        private Button _settingsBtn;
        private Button _quitBtn;
        private TMP_Text _title;

        private void Awake()
        {
            _title = FindText("Panel/Title");
            _resumeBtn = FindButton("Panel/ResumeBtn");
            _restartBtn = FindButton("Panel/RestartBtn");
            _settingsBtn = FindButton("Panel/SettingsBtn");
            _quitBtn = FindButton("Panel/QuitBtn");

            if (_resumeBtn != null) _resumeBtn.onClick.AddListener(OnClickResume);
            if (_restartBtn != null) _restartBtn.onClick.AddListener(OnClickRestart);
            if (_settingsBtn != null) _settingsBtn.onClick.AddListener(OnClickSettings);
            if (_quitBtn != null) _quitBtn.onClick.AddListener(OnClickQuit);

            // 标题文案不在这里写死：挪到 Refresh() —— UIManager 池化复用实例（Awake 只跑一次），
            // 且语言随时可能被切，必须在每次打开时按当前语言重建（见 Refresh / OnLanguageChanged）。
        }

        private void OnEnable()
        {
            // 注意：这里**不写 Time.timeScale**（见类注释）。暂停由流程层独占。
            Refresh();
            Subscribe();
        }

        /// <summary>
        /// 关闭时同样不碰 timeScale：本界面可能是在"游戏正常运行"时打开的，
        /// 关掉它不该顺手暂停/恢复任何东西（原先无条件 Time.timeScale = 1f 会把
        /// 别处设好的暂停态冲掉）。
        /// </summary>
        private void OnDisable()
        {
            Unsubscribe();
        }

        // ------------------------------------------------------------------
        // 语言切换（2026-10-16）
        // 【为什么暂停界面要听这个】设置界面也可以从暂停界面的「SettingsBtn」进 ——
        //   切完语言关闭设置，看到的就是暂停界面：标题必须已是新语言。
        //   （标题走手动 Refresh：它在批量挂载工具的动态文本排除名单里，不挂 TextLocalizer。）
        // ------------------------------------------------------------------

        private bool _subscribed;

        private void Refresh()
        {
            if (_title != null)
            {
                // 【标题为什么按状态取词】本菜单可以在"游戏正常运行"时打开（Btn_Intro），
                //   这时写"已暂停"就是假话。所以：
                //     已暂停 → Game Paused（暂停）；未暂停 → Menu（菜单）。
                //   两个 key 都在多语言表里（Menu = 2026-10-18 新增），缺表时才用中文兜底。
                string text = GameClock.IsPaused
                    ? (Localization.Get("Game Paused") ?? "暂停")
                    : (Localization.Get("Menu") ?? "菜单");
                _title.text = text;
                LanguageManager.ApplyFont(_title);
            }
        }

        private void Subscribe()
        {
            if (_subscribed)
            {
                return;
            }
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            // 暂停状态可能在菜单开着时变化（热键 P / 别的入口），标题要跟着切
            EventDispatcher.AddEventListener<bool>(EventName.PauseStateChangedEvent, OnPauseStateChanged);
            _subscribed = true;
        }

        private void Unsubscribe()
        {
            if (!_subscribed)
            {
                return;
            }
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            EventDispatcher.RemoveEventListener<bool>(EventName.PauseStateChangedEvent, OnPauseStateChanged);
            _subscribed = false;
        }

        private void OnLanguageChanged(int lang)
        {
            Refresh();
        }

        private void OnPauseStateChanged(bool paused)
        {
            Refresh();
        }

        private void OnClickResume()
        {
            EventDispatcher.TriggerEvent(EventName.ResumeRequestEvent);
        }

        private void OnClickRestart()
        {
            // 【为什么这里不再写 timeScale】重开走 RestartLevel → StartLevel → TeardownLevel，
            //   而 TeardownLevel 里已经有唯一的解除暂停入口（GameClock.SetPaused(false)）。
            //   在 UI 里再写一次就是双写，容易与流程层状态脱钩。
            EventDispatcher.TriggerEvent(EventName.RestartLevelRequestEvent);
        }

        private void OnClickSettings()
        {
            EventDispatcher.TriggerEvent(EventName.OpenSettingsRequestEvent);
        }

        private void OnClickQuit()
        {
            // 同上：退出对局由 QuitToSelect → TeardownLevel 统一解除暂停
            EventDispatcher.TriggerEvent(EventName.QuitToSelectRequestEvent);
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Pause] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Pause] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

using System.Text;

namespace FTProject
{
    /// <summary>评分展示的共用文案与格式，不参与评分计算。</summary>
    public static class RatingPresentation
    {
        public static string ProfileName(string profileId)
        {
            string key;
            switch (profileId)
            {
                case "D01": key = "Very Easy"; break;
                case "D02": key = "Easy"; break;
                case "D03": key = "Below Medium"; break;
                case "D04": key = "Medium"; break;
                case "D05": key = "Above Medium"; break;
                case "D06": key = "Hard"; break;
                case "D07": key = "Very Hard"; break;
                case "D08": key = "Extreme"; break;
                default: return string.IsNullOrEmpty(profileId) ? "—" : profileId;
            }
            return Localization.Get(key) ?? key;
        }

        public static string Time(long milliseconds)
        {
            if (milliseconds <= 0) return "--:--.---";
            return string.Format("{0:00}:{1:00}.{2:000}", milliseconds / 60000,
                milliseconds / 1000 % 60, milliseconds % 1000);
        }

        public static string Reasons(LevelRatingResult result)
        {
            if (result == null) return Localization.Get("Rating config missing or invalid") ?? "评分配置缺失或无效";
            if (result.reasons == null || result.reasons.Length == 0)
                return Localization.Get("All five-star conditions met") ?? "已满足全部五星条件";
            StringBuilder text = new StringBuilder();
            for (int i = 0; i < result.reasons.Length; i++)
            {
                string reason = result.reasons[i];
                if (string.IsNullOrEmpty(reason)) continue;
                if (text.Length > 0) text.Append(" · ");
                text.Append(Localization.Get(reason) ?? reason);
            }
            return text.ToString();
        }
    }
}

using System.Collections.Generic;
using SuperScrollView;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 关卡选择界面（M3-4；整页全屏 + 横向画廊）。
    ///
    /// 【为什么这版换成 SuperScrollView 的 LoopListView2】
    ///   旧版是"运行时克隆模板按钮 + 手排 4 列网格"。关卡一多就整屏塞满，
    ///   既看不出"现在该打哪一关"，也没法扩展成章节/皮肤那种卡片式选关。
    ///   现在改用工程里已有的 SuperScrollView：条目池化复用、横向滑动、
    ///   **并且开启条目吸附（ItemSnap）让某一关始终停在屏幕正中**。
    ///
    /// 【交互约定（本版新增）】
    ///   · 居中的那一关 = "当前选中的关卡"，进入游戏**只认它**。
    ///   · 点居中的卡片 → 立刻进关。
    ///   · 点旁边没居中的卡片 → 先**动画滑到正中**，滑到位后再自动进关
    ///     （见 <see cref="OnClickItem"/> 与 <see cref="OnSnapItemFinished"/>）。
    ///   · 未解锁的卡片仍然只弹提示、不进关。
    ///   · 左右两颗箭头把"居中的关卡"前后挪一格（只挪，不进关）。
    ///
    /// 【为什么不把条目摆进 prefab，仍然由代码填内容】
    ///   与旧版同一理由：摆进 prefab 意味着"改关卡数量就要改 prefab"。
    ///   现在的分工是：`SelectLevelItem.prefab` 只描述**一张卡片长什么样**，
    ///   数量与内容仍由 TBSceneInfo 在运行时喂进去 —— 加关卡 = 加配置行。
    ///
    /// 【节点容错】与 TowerInfoView 同一口径：缺节点只警告、不阻断，
    ///   美术重排 prefab 时不会把功能一起弄坏。
    /// </summary>
    public class SelectView : MonoBehaviour
    {
        public const string LogicalName = "SelectView";

        /// <summary>
        /// 条目预制体名。
        /// 【必须与 UIPrefabBuilder 里登记进 LoopListView2 的名字一致】——
        ///   LoopListView2 是**按预制体名字**从对象池取条目的（见 NewListViewItem），
        ///   名字对不上只会 return null → 列表整片空白，**不报错**。
        /// </summary>
        private const string ItemPrefabName = "SelectLevelItem";

        /// <summary>
        /// 条目卡片宽度与间距（**必须与 UIPrefabBuilder 里的 SelectItemW / SelectItemGap 一致**）。
        /// 【为什么要在这里再写一份】LoopListView2 用 `mItemDefaultWithPaddingSize`
        ///   估算"还没实例化出来的条目"的位置。用它的默认值 20 会让内容总宽度被严重低估，
        ///   初始化定位时会被 clamp 回 0（表现为"要定位到第 N 关却永远停在第 1 关"）。
        /// </summary>
        private const float ItemWidth = 1150f;
        private const float ItemGap = 56f;

        /// <summary>
        /// 条目中心离视口中心多远时缩到最小 / 最暗。
        /// 取"一个步长"，于是**相邻的那一张正好落在最暗端**，当前条目与邻居的对比一眼可见。
        /// </summary>
        private const float FocusFalloff = ItemWidth + ItemGap;

        /// <summary>最远端条目的缩放（居中条目恒为 1）</summary>
        private const float MinItemScale = 0.9f;

        /// <summary>最远端条目的不透明度（居中条目恒为 1）</summary>
        private const float MinItemAlpha = 0.5f;

        /// <summary>
        /// "滑到中间再进关"的兜底时限（秒）。
        /// 【为什么需要】吸附可能根本没跑起来（内容不满一屏、被拖拽打断……）。
        ///   没有这道兜底，一次失败的滑动就会让"点了却没反应"，玩家只能干等。
        /// 【为什么给到 2.5s】滑动本身约 0.5s 就把卡片送到位了，但插件要一直
        ///   微调到自己 0.01px 的完成阈值才罢休（实测还要再花 1s 以上）。
        ///   给得太紧会在动画尾巴上触发兜底、反而"啪"地跳一下。
        /// </summary>
        private const float SnapGuardSeconds = 2.5f;

        /// <summary>
        /// 判定"已经停在正中"的距离阈值（像素）。
        /// 【为什么不是 0.01】插件收尾是指数逼近，等它走完要 2 秒，玩家会觉得"点了半天没反应"。
        ///   4px 在 1150 宽的卡片上肉眼不可辨，到了就直接进关，手感才跟得上。
        /// </summary>
        private const float CenteredEpsilon = 4f;

        private TMP_Text _title;
        private TMP_Text _summary;
        private LoopListView2 _list;
        private Button _closeBtn;
        private Button _leftBtn;
        private Button _rightBtn;

        private List<cfg.SceneInfo> _levels;

        /// <summary>InitListView 只允许调一次（再调 LoopListView2 会直接报错），用它守住</summary>
        private bool _listInited;

        /// <summary>
        /// 等首帧排版完成后才执行 InitListView（见 <see cref="Build"/> 的说明）。
        /// 【为什么必须延后】LoopListView2 在 InitListView 里会把 viewport 的
        ///   `GetLocalCorners` 快照**缓存**下来（mViewPortRectLocalCorners），之后所有
        ///   "显示/回收/吸附"的算式都用这份缓存。而本界面的 List 是**拉伸型**
        ///   （锚点 0,0/1,1），OnEnable 那刻 Canvas 尚未排版 → List 宽 = 0 →
        ///   Viewport 拉伸算出的宽 = 0 − 2×inset（负值）→ 缓存进去一份**负宽**视口，
        ///   于是插件永远只留 1 张卡、且横向完全不动（实测 shown=1、contentPos 不随交互变化）。
        /// </summary>
        private bool _pendingInit;

        /// <summary>待居中到第几个条目；&lt;0 表示无需处理（首次打开时用）</summary>
        private int _pendingCenterIndex = -1;

        /// <summary>当前"停在正中"的条目下标（每帧从到中心的距离推出来）；-1 = 尚未确定</summary>
        private int _centerIndex = -1;

        /// <summary>正在滑向哪一条；-1 = 没有进行中的滑动（箭头在此期间锁住，避免连点跳格）</summary>
        private int _targetCenterIndex = -1;

        /// <summary>点了没居中的卡片后，滑到位要进哪一关；&lt;=0 表示没有待进关</summary>
        private int _pendingEnterLevelId;

        /// <summary>滑动兜底倒计时（&lt;=0 表示没在等）</summary>
        private float _snapGuardTimer;

        private void Awake()
        {
            BindNodes();
        }

        private void OnEnable()
        {
            Build();
        }

        private void LateUpdate()
        {
            if (_list == null || _levels == null)
            {
                return;
            }

            // ★★ 首帧才真正 InitListView（见 Build 里的 _pendingInit 说明）
            if (_pendingInit)
            {
                _pendingInit = false;
                DoInitListView();
            }

            if (!_listInited)
            {
                return;
            }

            // 【为什么首次定位要拖到第一帧 LateUpdate】
            //   OnEnable 那一刻 Canvas 还没排版，viewport / Content 的 rect 仍是 0，
            //   此时 MovePanelToItemIndex 会被 clamp 到 0 而"定位不过去"。
            if (_pendingCenterIndex >= 0)
            {
                int idx = _pendingCenterIndex;
                _pendingCenterIndex = -1;
                CenterOnIndexInstant(idx);
            }

            // 顺序有讲究：先把吸附距离刷新出来（UpdateFocusAndCenter 内部会做），
            // 再据此判断"滑到位了没有"
            UpdateFocusAndCenter();
            TickSliding();
            UpdateArrowInteractable();
        }

        // ------------------------------------------------------------------
        // 节点
        // ------------------------------------------------------------------

        private void BindNodes()
        {
            _title = FindText("Panel/Title");
            _summary = FindText("Panel/Summary");

            RectTransform listRect = FindRect("Panel/List");
            if (listRect != null)
            {
                _list = listRect.GetComponent<LoopListView2>();
                if (_list == null)
                {
                    Debug.LogWarning(
                        "[Select] Panel/List 上没有 LoopListView2 组件（prefab 可能还是旧版），关卡列表无法生成");
                }
            }

            _closeBtn = FindButton("Panel/CloseBtn");
            if (_closeBtn != null)
            {
                _closeBtn.onClick.AddListener(OnClickClose);
            }

            _leftBtn = FindButton("Panel/LeftBtn");
            if (_leftBtn != null)
            {
                _leftBtn.onClick.AddListener(delegate { OnClickStep(-1); });
            }
            _rightBtn = FindButton("Panel/RightBtn");
            if (_rightBtn != null)
            {
                _rightBtn.onClick.AddListener(delegate { OnClickStep(1); });
            }

            Button bg = FindButton("Bg");
            if (bg != null)
            {
                bg.onClick.AddListener(OnClickClose);
            }
        }

        // ------------------------------------------------------------------
        // 构建关卡列表
        // ------------------------------------------------------------------

        /// <summary>按 TBSceneInfo 重建关卡条目。可重复调用（界面是复用的，每次打开都会走一遍）。</summary>
        public void Build()
        {
            if (_list == null)
            {
                return;
            }
            if (Configs.LevelTable == null || Configs.LevelTable.DataList == null)
            {
                Debug.LogWarning("[Select] 配置表尚未加载，关卡列表为空");
                return;
            }

            _levels = Configs.LevelTable.DataList;

            // 兜底：预制体里已经勾好，这里再确认一次（漏勾则"吸附居中"整个失效）
            _list.ItemSnapEnable = true;

            if (!_listInited && !_pendingInit)
            {
                // ★★ 不在这里立刻 InitListView —— 见 DoInitListView / _pendingInit 的说明：
                //   此刻 Canvas 还没排版，拉伸型 List / Viewport 的 rect 是 0（甚至负宽），
                //   插件会把这份错误的视口尺寸缓存下来，导致横向列表只剩 1 张卡且不能滑动。
                //   改成挂个"待初始化"标记，等第一帧 LateUpdate（排版已完成）再真正初始化。
                _pendingInit = true;
                RefreshHeader(_levels.Count);
                return;
            }

            // 重复打开：关卡数量一般不变，但星级 / 解锁态会变 → 整体重刷一遍内容
            if (_listInited)
            {
                if (_list.ItemTotalCount != _levels.Count)
                {
                    _list.SetListItemCount(_levels.Count, false);
                }
                _list.RefreshAllShownItem();
            }

            RefreshHeader(_levels.Count);
        }

        /// <summary>
        /// 真正执行 InitListView（由第一帧 LateUpdate 调用，此时 Canvas 必已排版）。
        /// 拆出来是为了让 <see cref="Build"/> 能在"开着界面复用"与"首次打开"两条路径上保持一致。
        /// </summary>
        private void DoInitListView()
        {
            if (_listInited)
            {
                return;
            }
            _listInited = true;
            LoopListViewInitParam p = LoopListViewInitParam.CopyDefaultInitParam();
            p.mItemDefaultWithPaddingSize = ItemWidth + ItemGap;
            // 默认 0.3 的平滑时长偏拖沓：卡片"肉眼到位"要 0.5s 以上，
            // 点一下要等这么久才进关会显得卡顿。0.25 约 0.4s，仍看得清是"滑过去"的。
            p.mSmoothDumpRate = 0.25f;
            _list.InitListView(_levels.Count, OnGetItemByIndex, p);

            // 初次打开：居中到"最靠前的未通关关卡"（通关后重进会自动停在下一关）。
            // 这一次用**瞬时**定位而不是动画 —— 刚打开界面就自己滑一段会很怪。
            _pendingCenterIndex = FirstUnclearedIndex();
        }

        /// <summary>第一个"还没拿到星"的关卡下标；全通关则停在最后一关。空表返回 -1。</summary>
        private int FirstUnclearedIndex()
        {
            if (_levels == null || _levels.Count == 0)
            {
                return -1;
            }
            for (int i = 0; i < _levels.Count; i++)
            {
                cfg.SceneInfo s = _levels[i];
                if (s != null && SaveManager.Instance.GetStars(s.Id) == 0)
                {
                    return i;
                }
            }
            return _levels.Count - 1;
        }

        // ------------------------------------------------------------------
        // 居中 / 翻页 / 进关
        // ------------------------------------------------------------------

        /// <summary>
        /// 让第 index 个条目**立刻**停在正中（无动画）。
        /// 用于"刚打开界面时的初始定位"以及滑动兜底。
        /// </summary>
        private void CenterOnIndexInstant(int index)
        {
            if (!EnsureShown(index))
            {
                return;
            }
            _list.SetSnapTargetItemIndex(index);
            _list.FinishSnapImmediately();
            _targetCenterIndex = -1;
            _pendingEnterLevelId = 0;
            _snapGuardTimer = 0f;
        }

        /// <summary>
        /// 让第 index 个条目**动画滑动**到正中。
        /// 【为什么不用 FinishSnapImmediately】那一句是"瞬移"；这里要的是看得见的滑动，
        ///   所以只设吸附目标，交给 LoopListView2 自己用 SmoothDamp 滑过去。
        /// </summary>
        private bool RequestCenterOnIndex(int index)
        {
            if (!EnsureShown(index))
            {
                return false;
            }
            _list.SetSnapTargetItemIndex(index);
            _targetCenterIndex = index;
            _snapGuardTimer = SnapGuardSeconds;
            return true;
        }

        /// <summary>
        /// 保证第 index 个条目已经是"已显示条目"。
        /// 【为什么必须先保证】`SetSnapTargetItemIndex` 内部会去取"已显示条目"，
        ///   取不到就静默放弃（表现为"点了没反应"）。跨多格跳转时目标可能还在屏幕外，
        ///   所以先用 MovePanelToItemIndex 把它拉进来。
        /// </summary>
        private bool EnsureShown(int index)
        {
            if (_list == null || _list.ItemTotalCount <= 0)
            {
                return false;
            }
            index = Mathf.Clamp(index, 0, _list.ItemTotalCount - 1);
            if (_list.GetShownItemByItemIndex(index) == null)
            {
                _list.MovePanelToItemIndex(index, 0);
            }
            return true;
        }

        /// <summary>
        /// 滑动推进器：等目标条目真正落到正中，再决定要不要进关。
        ///
        /// 【为什么用"轮询距离"而不是插件的 mOnSnapItemFinished 回调】
        ///   实测那条回调并不可靠：它内部传的是 `mCurSnapNearestItemIndex`，
        ///   而这个值只在"容器位置变了"的那一帧才重算 —— 会出现"回调提前触发、
        ///   传回来的还不是我们要的那一条"的情况（表现为点击后下一帧就直接进关了，
        ///   滑动动画等于没播）。直接读目标条目到视口中心的距离，才是唯一可信的判据。
        /// </summary>
        private void TickSliding()
        {
            if (_targetCenterIndex < 0)
            {
                return;
            }

            _snapGuardTimer -= Time.unscaledDeltaTime;

            // 玩家中途自己拖了 → 视为改主意：取消这次"点哪进哪"，也不再自动进关
            bool dragging = _list.IsDraging;
            LoopListViewItem2 item = dragging ? null : _list.GetShownItemByItemIndex(_targetCenterIndex);
            bool centered = item != null &&
                            Mathf.Abs(item.DistanceWithViewPortSnapCenter) <= CenteredEpsilon;

            if (!centered && !dragging && _snapGuardTimer > 0f)
            {
                return;   // 还在滑，继续等
            }

            int enterId = dragging ? 0 : _pendingEnterLevelId;
            int index = _targetCenterIndex;
            _targetCenterIndex = -1;
            _pendingEnterLevelId = 0;
            _snapGuardTimer = 0f;

            if (enterId <= 0)
            {
                return;
            }
            if (!centered)
            {
                CenterOnIndexInstant(index);   // 兜底：滑动没跑起来就直接顶到正中
            }
            EnterLevel(enterId);
        }

        /// <summary>左右箭头：把"居中的那一关"前后挪一格。只挪，不进关。</summary>
        private void OnClickStep(int delta)
        {
            if (_list == null || !_listInited || _centerIndex < 0)
            {
                return;
            }
            if (_targetCenterIndex >= 0)
            {
                return;   // 正在滑，先让这一次走完（否则连点会跳格）
            }
            int target = _centerIndex + delta;
            if (target < 0 || target >= _list.ItemTotalCount)
            {
                return;
            }
            _pendingEnterLevelId = 0;
            RequestCenterOnIndex(target);
        }

        /// <summary>点条目：居中的直接进；没居中的先滑到中间，到位后再进。</summary>
        private void OnClickItem(LoopListViewItem2 item)
        {
            if (item == null)
            {
                return;
            }
            int index = item.ItemIndex;
            int levelId = item.UserIntData1;

            // 未解锁：给明确提示，不进关（与旧版一字不差的逻辑）
            if (item.UserIntData2 == 0)
            {
                EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent,
                    Localization.Get("Clear the previous level first") ?? "先通关上一关才能解锁");
                return;
            }

            // 已经停在正中、也没有滑动在跑 → 就是"点击居中关卡"，直接进
            if (index == _centerIndex && _targetCenterIndex < 0)
            {
                EnterLevel(levelId);
                return;
            }

            // 没居中 → 先动画滑到中间，滑到位后由 TickSliding 进关
            _pendingEnterLevelId = levelId;
            if (!RequestCenterOnIndex(index))
            {
                // 吸附起不来（例如内容不满一屏）→ 不能把玩家卡住，直接进
                _pendingEnterLevelId = 0;
                EnterLevel(levelId);
            }
        }

        /// <summary>
        /// 调试开关：勾上则恢复"点卡片直接进关"的旧行为（跳过详情弹窗）。
        /// 调"进关本身"的问题时，中间多一层弹窗很碍事。
        /// </summary>
        [SerializeField] private bool skipDetail;

        /// <summary>
        /// 进入某一关。
        /// 【UI 补全 B4 改了什么】原来这里直接进关；现在先开**关卡详情弹窗**，
        /// 让玩家看清回合数/波次/初始资源/难度/历史最佳之后再决定 ——
        /// 否则进关才发现不是自己想要的，只能退出来重选。
        /// </summary>
        private void EnterLevel(int levelId)
        {
            if (skipDetail)
            {
                EventDispatcher.TriggerEvent<int>(EventName.SelectLevelRequestEvent, levelId);
                return;
            }
            LevelDetailView.Show(levelId);
        }

        /// <summary>
        /// 每帧刷新两件事：① 谁停在正中 ② 非居中卡片的缩小/压暗。
        /// 用一次遍历同时算出来（展示的条目只有几个，开销可忽略）。
        /// </summary>
        private void UpdateFocusAndCenter()
        {
            if (!_list.ItemSnapEnable)
            {
                return;
            }

            _list.UpdateAllShownItemSnapData();
            int count = _list.ShownItemCount;
            float bestDist = float.MaxValue;
            int bestIndex = -1;

            for (int i = 0; i < count; i++)
            {
                LoopListViewItem2 item = _list.GetShownItemByIndex(i);
                if (item == null)
                {
                    continue;
                }

                float dist = item.DistanceWithViewPortSnapCenter;
                float abs = Mathf.Abs(dist);

                // 拖拽中不做"谁是中心"的判定，否则箭头会在手指底下乱闪
                if (!_list.IsDraging && abs < bestDist)
                {
                    bestDist = abs;
                    bestIndex = item.ItemIndex;
                }

                // 缩放/淡化只动卡片的 Body 子节点（围绕卡片中心，左右对称），
                // 不碰条目根节点，因此不会干扰 LoopListView2 的排布算式。
                CanvasGroup body = item.UserObjectData as CanvasGroup;
                if (body == null)
                {
                    continue;
                }
                float t = Mathf.Clamp01(abs / FocusFalloff);
                float scale = Mathf.Lerp(1f, MinItemScale, t);
                body.transform.localScale = new Vector3(scale, scale, 1f);
                body.alpha = Mathf.Lerp(1f, MinItemAlpha, t);
            }

            if (bestIndex >= 0)
            {
                _centerIndex = bestIndex;
            }
        }

        /// <summary>到头了就把对应的箭头置灰，给出"没法再往那边翻"的反馈。</summary>
        private void UpdateArrowInteractable()
        {
            bool sliding = _targetCenterIndex >= 0;
            if (_leftBtn != null)
            {
                bool canPrev = !sliding && _centerIndex > 0;
                if (_leftBtn.interactable != canPrev)
                {
                    _leftBtn.interactable = canPrev;
                }
            }
            if (_rightBtn != null)
            {
                bool canNext = !sliding && _centerIndex >= 0 &&
                               _centerIndex < _list.ItemTotalCount - 1;
                if (_rightBtn.interactable != canNext)
                {
                    _rightBtn.interactable = canNext;
                }
            }
        }

        // ------------------------------------------------------------------
        // 条目回填
        // ------------------------------------------------------------------

        /// <summary>LoopListView2 的条目回调：池里取一张卡片，填上新内容。</summary>
        private LoopListViewItem2 OnGetItemByIndex(LoopListView2 listView, int index)
        {
            if (_levels == null || index < 0 || index >= _levels.Count)
            {
                return null;
            }
            cfg.SceneInfo raw = _levels[index];
            if (raw == null)
            {
                return null;
            }

            LoopListViewItem2 item = listView.NewListViewItem(ItemPrefabName);
            if (item == null)
            {
                Debug.LogWarning(
                    "[Select] LoopListView2 未登记条目预制体「" + ItemPrefabName + "」，关卡列表无法生成");
                return null;
            }

            int levelId = raw.Id;
            bool unlocked = SaveManager.Instance.IsUnlocked(levelId);
            int stars = SaveManager.Instance.GetStars(levelId);
            int diff = raw.Difficulty;

            // 【为什么点击回调只在首次初始化时挂】
            //   条目是**池化复用**的：每次回填都 AddListener 会让同一条目累积 N 个回调，
            //   横向滚一圈之后一次点击就会触发 N 次选关。回调里读的是条目的
            //   UserIntData1/2，所以复用时只要换数据，不必重挂。
            if (!item.IsInitHandlerCalled)
            {
                item.IsInitHandlerCalled = true;

                // 卡片的视觉层（缩放/淡化都作用在它身上）缓存一次，省掉每帧 GetComponent。
                // 取"第一个子节点"即可 —— 卡片预制体的结构由生成器固定为 Body 一个子节点。
                CanvasGroup body = item.transform.childCount > 0
                    ? item.transform.GetChild(0).GetComponent<CanvasGroup>()
                    : null;
                item.UserObjectData = body;

                Button btn = item.GetComponentInChildren<Button>(true);
                if (btn != null)
                {
                    btn.onClick.AddListener(delegate { OnClickItem(item); });
                }
            }
            item.UserIntData1 = levelId;
            item.UserIntData2 = unlocked ? 1 : 0;

            TMP_Text label = item.GetComponentInChildren<TMP_Text>(true);
            if (label != null)
            {
                // 【为什么要着色】效果图里实心星是金色、空心星与难度是暗蓝灰，
                //   全靠富文本在**一段文本内**分色，否则得拆成三个 TMP 节点。
                // 【字号为什么逐行给】卡片只有三行文案，名称/星级要压住难度，
                //   富文本标签即便失效，基础字号仍能保证三行落在卡片内。
                label.text = string.Format(
                    "<size=56><color=#E8F0FA>{0}</color></size>\n" +
                    "<size=56>{1}</size>\n" +
                    "<size=40>{2}</size>",
                    Localization.LevelName(raw.Id, raw.Name),
                    StarRichText(stars),
                    unlocked
                        ? "<color=#7A8CA6>" + Difficulty(diff) + "</color>"
                        : "<color=#5A6B80>" + (Localization.Get("Locked") ?? "未解锁") + "</color>");
            }

            return item;
        }

        private void RefreshHeader(int levelCount)
        {
            int cleared = SaveManager.Instance.ClearedCount;
            int stars = SaveManager.Instance.TotalStars;
            // 数字提亮、星级用金色（效果图 01 的 Summary 配色）
            SetText(_summary, Localization.Get("Cleared <color=#E8F0FA>{0}/{1}</color>　<color=#FFC94D>★ {2}/{3}</color>", cleared, levelCount, stars, levelCount * LevelRatingEvaluator.MaxStars)
                ?? string.Format(
                    "已通关 <color=#E8F0FA>{0}/{1}</color>　<color=#FFC94D>★ {2}/{3}</color>",
                    cleared, levelCount, stars, levelCount * LevelRatingEvaluator.MaxStars));
            SetText(_title, Localization.Get("Select Level") ?? "选择关卡");
        }

        /// <summary>星级字符串。用实心/空心星而不是数字，一眼能扫完所有关卡。</summary>
        public static string Stars(int n)
        {
            n = Mathf.Clamp(n, 0, LevelRatingEvaluator.MaxStars);
            return new string('★', n) + new string('☆', LevelRatingEvaluator.MaxStars - n);
        }

        /// <summary>星级富文本：已得星金色、未得星暗蓝灰（效果图 01）。**公开**给结算界面复用，
        /// 否则"同一个星级在两处长得不一样"（与 Stars() 同样的理由）。</summary>
        public static string StarRichText(int n)
        {
            n = Mathf.Clamp(n, 0, LevelRatingEvaluator.MaxStars);
            return "<color=#FFC94D>" + new string('★', n) + "</color>" +
                   "<color=#3F4E63>" + new string('☆', LevelRatingEvaluator.MaxStars - n) + "</color>";
        }

        public static string Difficulty(int d)
        {
            switch (Mathf.Clamp(d, 1, 5))
            {
                case 1: return Localization.Get("Campaign Stage I") ?? "战役阶段 I";
                case 2: return Localization.Get("Campaign Stage II") ?? "战役阶段 II";
                case 3: return Localization.Get("Campaign Stage III") ?? "战役阶段 III";
                case 4: return Localization.Get("Campaign Stage IV") ?? "战役阶段 IV";
                default: return Localization.Get("Campaign Stage V") ?? "战役阶段 V";
            }
        }

        private void OnClickClose()
        {
            EventDispatcher.TriggerEvent(EventName.CloseSelectRequestEvent);
        }

        // ------------------------------------------------------------------
        // 节点查找（容错）
        // ------------------------------------------------------------------

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Select] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Select] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }

        private RectTransform FindRect(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Select] 缺少容器节点「" + path + "」");
                return null;
            }
            return tr as RectTransform;
        }

        private static void SetText(TMP_Text t, string v)
        {
            if (t != null && t.text != v)
            {
                t.text = v;
            }
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 出售塔二次确认（UI 补全 C1 / 效果图 22_ConfirmView.svg 左）。
    ///
    /// 【为什么从"原地两段式"升级成独立弹窗】
    ///   原实现（`TowerInfoView.OnClickSell` 的原地改文案）确实能拦误触，但有三个问题：
    ///     ① 玩家看不到"这一卖要亏多少"——退回金额只在按钮文案里一闪而过；
    ///     ② 因为要"记住上次点的是哪个按钮"，面板一刷新就得小心别把确认态刷掉；
    ///     ③ 文案"确认出售？"顶掉"出售 (+46)"之后，玩家不知道自己点的是哪座塔。
    ///   独立弹窗能一次讲清：塔名 + 退回多少 + 不可撤销。
    ///
    /// 【退回额怎么算】与 `TowerInfoView` 用同一口径（`Configs.Global.SellRefundRate × cfg.SellPrice`），
    ///   不在这里另算一套 —— 两处算法分叉是"按钮写退 46、实际退 30"这类 bug 的根源。
    /// </summary>
    public class SellConfirmView : MonoBehaviour
    {
        public const string LogicalName = "SellConfirmView";

        private static readonly Color TextPrimary = new Color(0.910f, 0.941f, 0.980f, 1f);
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f);
        private static readonly Color Fire = new Color(1f, 0.478f, 0.161f, 1f);      // #FF7A29
        private static readonly Color Gold = new Color(1f, 0.788f, 0.302f, 1f);      // #FFC94D

        private TMP_Text _title;
        private TMP_Text _towerName;
        private TMP_Text _warnText;
        private TMP_Text _refundValue;
        private TMP_Text _refundLabel;
        private Image _topBar;
        private Image _towerIcon;
        private Button _confirmBtn;
        private Button _cancelBtn;

        private BaseTower _tower;

        /// <summary>弹出出售确认。<paramref name="tower"/> 为 null 时不弹（避免出现"确认卖掉空气"）。</summary>
        public static void Show(BaseTower tower)
        {
            if (tower == null)
            {
                return;
            }
            SellConfirmView view = UIManager.Instance.Open<SellConfirmView>(LogicalName, UILayout.NormalPanel);
            if (view == null)
            {
                // 【降级】弹窗缺失时不静默卖掉，而是提示"暂不可用"——
                // 不可撤销的操作绝不能因为 UI 缺失就自动执行。
                Debug.LogError("[Sell] SellConfirmView 打开失败（prefab 可能还没生成），已取消本次出售");
                EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent,
                    Localization.Get("Sell is unavailable here") ?? "出售确认界面不可用");
                return;
            }
            view.Setup(tower);
        }

        private void Awake()
        {
            _title = FindText("Panel/TopBar/SellTitle");
            _towerName = FindText("Panel/TowerName");
            _warnText = FindText("Panel/WarnText");
            _refundValue = FindText("Panel/RefundValue");
            _refundLabel = FindText("Panel/RefundLabel");
            _confirmBtn = FindButton("Panel/ConfirmBtn");
            _cancelBtn = FindButton("Panel/CancelBtn");
            Transform bar = transform.Find("Panel/TopBar");
            _topBar = bar != null ? bar.GetComponent<Image>() : null;
            Transform icon = transform.Find("Panel/TowerIcon");
            _towerIcon = icon != null ? icon.GetComponent<Image>() : null;

            if (_confirmBtn != null) _confirmBtn.onClick.AddListener(OnClickConfirm);
            if (_cancelBtn != null) _cancelBtn.onClick.AddListener(OnClickCancel);
            Button bg = FindButton("Bg");
            if (bg != null) bg.onClick.AddListener(OnClickCancel);

            if (_title != null) _title.color = TextPrimary;
            if (_towerName != null) _towerName.color = TextPrimary;
            if (_warnText != null) _warnText.color = Fire;
            if (_refundLabel != null) _refundLabel.color = TextSecondary;
            if (_refundValue != null) _refundValue.color = Gold;
            if (_topBar != null) _topBar.color = Fire;

            // 警告文案里的比例**跟随配置**，不写死 70%：数值一改文案就跟着对
            float rate = Configs.Global != null ? Configs.Global.SellRefundRate : 1f;
            if (_warnText != null)
            {
                _warnText.text = Localization.Get("Refund {0}% of total investment.\nThis cannot be undone.", Mathf.RoundToInt(rate * 100f))
                    ?? string.Format("出售后将退回 {0}% 的累计投入\n且无法撤销", Mathf.RoundToInt(rate * 100f));
            }
        }

        private void Setup(BaseTower tower)
        {
            _tower = tower;
            TowerConfig cfg = tower.Config;
            if (cfg == null)
            {
                return;
            }

            if (_towerName != null)
            {
                // DisplayName：过多语言表（"普通塔"），缺条目回退英文原文
                _towerName.text = cfg.DisplayName;
            }

            float rate = Configs.Global != null ? Configs.Global.SellRefundRate : 1f;
            int refund = Mathf.Max(0, Mathf.RoundToInt(cfg.SellPrice * rate));
            if (_refundValue != null)
            {
                _refundValue.text = refund.ToString();
            }
            if (_towerIcon != null)
            {
                // 图标缺失只是不好看，不影响功能：取不到就留一个暗色块
                Sprite icon = ResLoader.Instance.IsReady
                    ? ResLoader.Instance.Load<Sprite>("UI_TowerIcon_" + TypeSuffix(cfg.Type))
                    : null;
                if (icon != null)
                {
                    _towerIcon.sprite = icon;
                    _towerIcon.color = Color.white;
                }
            }
        }

        /// <summary>TowerType → 图标名后缀（与 UIPrefabBuilder.TowerIconSpriteName 同一口径）。</summary>
        private static string TypeSuffix(int type)
        {
            switch (type)
            {
                case 2: return "Power";
                case 3: return "Retard";
                default: return "Normal";
            }
        }

        private void OnClickConfirm()
        {
            BaseTower t = _tower;
            _tower = null;
            UIManager.Instance.Close(LogicalName);
            if (t != null)
            {
                // 只有这里才真正出售：TowerSellRequestEvent 是"玩家想卖"（意图），
                // 本事件是"玩家确认了"（决定）。GameFlowManager 只监听本事件。
                EventDispatcher.TriggerEvent<BaseTower>(EventName.TowerSellConfirmEvent, t);
            }
        }

        private void OnClickCancel()
        {
            _tower = null;
            UIManager.Instance.Close(LogicalName);
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Sell] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Sell] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 设置界面（M3-6；2026-10-16 新增语言切换下拉框）。
    ///
    /// 【为什么音量用 Slider】(M3-6 修订)
    ///   音量改为滑动条拖拽调节，所见即所得；VolumeText 仍同步显示百分比。
    ///   Slider 节点树（Background / Fill Area / Handle）由 UIPrefabBuilder 生成，
    ///   本脚本只关心 Panel/VolumeSlider 的 onValueChanged。
    ///
    /// 【语言切换为什么能"实时生效、不用重启"】
    ///   选语言 → LanguageManager.SetLanguage（写存档 + 广播 LanguageChangedEvent）→
    ///   ① 全场景挂了 TextLocalizer / ImageLocalizer 的静态节点**自动**刷新（不需要遍历界面）；
    ///   ② 本界面订阅了同一事件：标题、音量、静音这些"代码手动拼词"的文本在这里重刷，
    ///      下拉框选中值也一并同步；
    ///   ③ 主菜单 / 暂停 / HUD 也各自订阅（它们是设置界面打开时的"背景双人组"），
    ///      关闭设置后看到的每一处文案都已是新语言。
    ///
    /// 【设置写到哪里】SaveManager（持久化），并立刻推给 AudioManager 生效。
    /// </summary>
    public class SettingView : MonoBehaviour
    {
        public const string LogicalName = "SettingView";

        private TMP_Text _volumeText;
        private Slider _volumeSlider;
        private Button _muteBtn;
        private TMP_Text _muteLabel;
        private Button _resetBtn;
        private Button _closeBtn;
        private TMP_Text _title;
        private TMP_Dropdown _languageDropdown;

        /// <summary>下拉框第 i 项 ↔ Language 的映射（顺序 = LocalizationSettings.supportedLanguages）。</summary>
        private readonly List<Language> _languages = new List<Language>();
        private bool _subscribed;

        private void Awake()
        {
            _title = FindText("Panel/Title");
            _volumeText = FindText("Panel/VolumeText");
            _volumeSlider = FindSlider("Panel/VolumeSlider");
            _muteBtn = FindButton("Panel/MuteBtn");
            _muteLabel = FindText("Panel/MuteBtn/Label");
            _resetBtn = FindButton("Panel/ResetBtn");
            _closeBtn = FindButton("Panel/CloseBtn");
            _languageDropdown = FindDropdown("Panel/LanguageDropdown");

            if (_volumeSlider != null) _volumeSlider.onValueChanged.AddListener(OnVolumeChanged);
            if (_muteBtn != null) _muteBtn.onClick.AddListener(OnClickMute);
            if (_resetBtn != null) _resetBtn.onClick.AddListener(OnClickReset);
            if (_closeBtn != null) _closeBtn.onClick.AddListener(OnClickClose);
            if (_languageDropdown != null) _languageDropdown.onValueChanged.AddListener(OnPickLanguage);
            Button bg = FindButton("Bg");
            if (bg != null) bg.onClick.AddListener(OnClickClose);

            BuildLanguageOptions();
        }

        private void OnEnable()
        {
            // 每次打开都按当前语言全量刷新（UIManager 池化复用实例，Awake 只跑一次）
            Refresh();
            Subscribe();
        }

        private void OnDisable()
        {
            Unsubscribe();
        }

        // ------------------------------------------------------------------
        // 语言切换（2026-10-16）
        // ------------------------------------------------------------------

        /// <summary>
        /// 构建语言下拉框的选项列表。
        ///
        /// 【数据源】LocalizationSettings.supportedLanguages（配置即真理，不硬编码语言集合）；
        ///   资产缺失 / 列表为空时回退到"枚举里的三语言"硬兜底（保持零崩溃口径）。
        /// 【选项文案】LanguageUtil.DisplayName 的**自显名**（"English / 简体中文 / 繁體中文"）——
        ///   刻意不查多语言表：用语言 A 的界面显示语言 B 的名字时，永远不会因缺 key 露馅。
        /// </summary>
        private void BuildLanguageOptions()
        {
            _languages.Clear();
            LocalizationSettings settings = LanguageManager.Settings;
            if (settings != null && settings.supportedLanguages != null)
            {
                for (int i = 0; i < settings.supportedLanguages.Count; i++)
                {
                    Language lang = settings.supportedLanguages[i];
                    if (!_languages.Contains(lang))
                    {
                        _languages.Add(lang);   // 去重：配置里写重了也不给下拉框放两遍
                    }
                }
            }
            if (_languages.Count == 0)
            {
                _languages.Add(Language.English);
                _languages.Add(Language.ChineseSimplified);
                _languages.Add(Language.ChineseTraditional);
            }

            if (_languageDropdown == null)
            {
                return;
            }
            List<string> options = new List<string>(_languages.Count);
            for (int i = 0; i < _languages.Count; i++)
            {
                options.Add(_languages[i].DisplayName());
            }
            _languageDropdown.ClearOptions();
            _languageDropdown.AddOptions(options);
            SyncLanguageDropdown();
        }

        /// <summary>
        /// 下拉框选中项 → 切换语言。
        /// 真正的全局刷新交给 LanguageChangedEvent（唯一入口，见 LanguageManager.SetLanguage）；
        /// 这里补一次 Refresh 是为了覆盖"选中的就是当前语言"（SetLanguage 内部会短路不广播）的情况。
        /// </summary>
        private void OnPickLanguage(int index)
        {
            if (index < 0 || index >= _languages.Count)
            {
                return;
            }
            LanguageManager.SetLanguage(_languages[index]);
            Refresh();
        }

        /// <summary>把下拉框选中值同步到"当前语言"（SetValueWithoutNotify：不触发 onValueChanged 回环）。</summary>
        private void SyncLanguageDropdown()
        {
            if (_languageDropdown == null)
            {
                return;
            }
            int index = _languages.IndexOf(LanguageManager.Current);
            if (index < 0)
            {
                index = 0;      // 当前语言不在候选列表（配置被改过）→ 显示第一项，不强切语言
            }
            if (_languageDropdown.value != index)
            {
                _languageDropdown.SetValueWithoutNotify(index);
            }
        }

        /// <summary>语言已切换（广播回来）→ 重刷本界面手动拼写的文本 + 同步下拉框选中值。</summary>
        private void OnLanguageChanged(int lang)
        {
            Refresh();
        }

        private void Subscribe()
        {
            if (_subscribed)
            {
                return;
            }
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = true;
        }

        private void Unsubscribe()
        {
            if (!_subscribed)
            {
                return;
            }
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
            _subscribed = false;
        }

        // ------------------------------------------------------------------
        // 音量 / 静音 / 重置 / 关闭
        // ------------------------------------------------------------------

        private void OnVolumeChanged(float value)
        {
            SaveManager.Instance.SetVolume(value);
            Refresh();
        }

        private void OnClickMute()
        {
            GameSettings s = SaveManager.Instance.Settings;
            SaveManager.Instance.SetMuted(!s.muted);
            Refresh();
        }

        private void OnClickReset()
        {
            // UI 补全 C2：重置存档是**不可撤销**的，必须先确认。
            // 改造前这里点一下就真的清了（玩家点错就没了）。
            ConfirmView.Show(
                Localization.Get("Reset Save") ?? "重置存档",
                Localization.Get("This will erase all progress. Continue?") ?? "将清空所有关卡进度与星级，此操作不可撤销。",
                ConfirmType.Danger, DoReset,
                Localization.Get("OK") ?? "确定重置",
                Localization.Get("Cancel") ?? "取消");
        }

        private void DoReset()
        {
            // 【易错点】重置存档会连带把音量也重置回默认 —— 这是"重置"应有的语义，
            // 但要在界面上说清楚，否则玩家会以为设置丢了。
            SaveManager.Instance.ResetAll();
            SaveManager.Instance.ApplyToAudio();
            Refresh();
            EventDispatcher.TriggerEvent<string>(EventName.ShowTipEvent,
                Localization.Get("Save reset") ?? "存档已重置");
        }

        private void OnClickClose()
        {
            EventDispatcher.TriggerEvent(EventName.CloseSettingsRequestEvent);
        }

        private void Refresh()
        {
            // 标题：静态文案，但在批量挂载工具的"动态文本排除名单"里（Title），
            // 不走 TextLocalizer —— 由本方法负责随语言刷新。
            if (_title != null)
            {
                _title.text = Localization.Get("Settings") ?? "设置";
                LanguageManager.ApplyFont(_title);
            }

            GameSettings s = SaveManager.Instance.Settings;
            SetText(_volumeText,
                Localization.Get("Volume {0}%", Mathf.RoundToInt(s.volume * 100f))
                ?? string.Format("音量 {0}%", Mathf.RoundToInt(s.volume * 100f)));
            LanguageManager.ApplyFont(_volumeText);
            if (_volumeSlider != null) _volumeSlider.SetValueWithoutNotify(s.volume);
            SetText(_muteLabel, s.muted
                ? (Localization.Get("Unmute") ?? "取消静音")
                : (Localization.Get("Mute") ?? "静音"));
            LanguageManager.ApplyFont(_muteLabel);

            SyncLanguageDropdown();
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Setting] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Slider FindSlider(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Setting] 缺少滑动条节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Slider>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Setting] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }

        private TMP_Dropdown FindDropdown(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Setting] 缺少下拉框节点「" + path + "」（prefab 可能未重生成？）");
                return null;
            }
            return tr.GetComponent<TMP_Dropdown>();
        }

        private static void SetText(TMP_Text t, string v)
        {
            if (t != null && t.text != v)
            {
                t.text = v;
            }
        }
    }
}

using TMPro;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 开屏页（UI 补全 A1 / 效果图 15_SplashView.svg）。
    ///
    /// 【它解决什么问题】改造前 `Launcher.Start()` 直接进异步资源初始化，**全程黑屏静默**，
    /// 玩家会以为游戏没启动。开屏页给出"正在启动"的确定反馈，同时承担品牌露出。
    ///
    /// 【为什么自带 CanvasGroup】`UIManager.EnsureFadeIn` 对"prefab 自带 CanvasGroup"的界面
    /// 会整体跳过（见 UIManager.cs）—— 本界面要自己控制整屏淡入节奏，
    /// 与 UIManager 的 0.12s 统一淡入会互相打架。
    ///
    /// 【为什么不用 DOTween】本工程虽然装了 DOTween，但**全工程零处使用**。
    /// 为一个 1.5 秒的开屏动画引入新运行时依赖不划算，这里用 Update 里按 unscaled 时间插值，
    /// 行为完全确定、也能在 timeScale=0 时正常播放。
    /// </summary>
    public class SplashView : MonoBehaviour
    {
        public const string LogicalName = "SplashView";

        /// <summary>整页停留时长（秒）。到点后发 <see cref="EventName.SplashFinishedEvent"/>，由 Launcher 接手。</summary>
        public const float HoldSeconds = 1.5f;

        private const float BgFadeSec = 0.4f;
        private const float FadeSec = 0.5f;
        private const float TitleDelay = 0.3f;
        private const float SubDelay = 0.5f;
        private const float LogoScaleFrom = 0.85f;

        private static readonly Color TitleColor = new Color(0.208f, 0.878f, 1f, 1f);        // #35E0FF
        private static readonly Color SubColor = new Color(0.624f, 0.702f, 0.784f, 1f);       // #9FB3C8
        private static readonly Color TertiaryColor = new Color(0.369f, 0.451f, 0.588f, 1f);  // #5E7396
        private static readonly Color SteelColor = new Color(0.624f, 0.702f, 0.784f, 1f);     // #9FB3C8

        private CanvasGroup _cg;
        private TMP_Text _title;
        private TMP_Text _subtitle;
        private TMP_Text _version;
        private TMP_Text _dots;
        private RectTransform _logo;

        private float _t;
        private bool _fired;

        private void Awake()
        {
            _cg = GetComponent<CanvasGroup>();
            _title = FindText("Panel/GameTitle");
            _subtitle = FindText("Panel/Subtitle");
            _version = FindText("Panel/Version");
            _dots = FindText("Panel/LoadingDots");
            _logo = FindRect("Panel/Logo");

            if (_title != null) _title.color = TitleColor;
            if (_subtitle != null) _subtitle.color = SubColor;
            if (_version != null) _version.color = TertiaryColor;
            if (_dots != null) _dots.color = SteelColor;

            // 版本号**从 Application.version 读**，绝不硬编码 ——
            // 硬编码的版本号在发版后必然与实际包体不一致，且没人会想起来改。
            if (_version != null)
            {
                _version.text = string.IsNullOrEmpty(Application.version)
                    ? string.Empty
                    : "v" + Application.version;
            }

            if (_cg != null) _cg.alpha = 0f;
            if (_logo != null) _logo.localScale = Vector3.one * LogoScaleFrom;
            SetAlpha(_title, 0f);
            SetAlpha(_subtitle, 0f);
            SetAlpha(_version, 0f);
        }

        private void Update()
        {
            if (_fired)
            {
                return;
            }

            float dt = Time.unscaledDeltaTime;
            _t += dt;

            if (_cg != null)
            {
                _cg.alpha = Mathf.Clamp01(_t / BgFadeSec);
            }

            float titleP = Mathf.Clamp01((_t - TitleDelay) / FadeSec);
            SetAlpha(_title, titleP);

            float subP = Mathf.Clamp01((_t - SubDelay) / FadeSec);
            SetAlpha(_subtitle, subP * 0.9f);

            // 版本号最后出现（它是"技术支持"类信息，不该抢品牌标题的注意力）
            SetAlpha(_version, Mathf.Clamp01((_t - SubDelay) / FadeSec));

            if (_logo != null)
            {
                float lp = Mathf.Clamp01(_t / 0.6f);
                _logo.localScale = Vector3.one * Mathf.Lerp(LogoScaleFrom, 1f, EaseOutBack(lp));
            }

            if (_dots != null)
            {
                // 省略号随时间的简单循环（1~3 个点），比转圈图省一张贴图
                int n = 1 + ((int)(_t * 2.5f) % 3);
                string suffix = n == 1 ? "." : (n == 2 ? ".." : "...");
                _dots.text = (Localization.Get("Starting...") ?? "正在启动") + suffix;
            }

            if (_t >= HoldSeconds)
            {
                _fired = true;
                EventDispatcher.TriggerEvent(EventName.SplashFinishedEvent);
            }
        }

        /// <summary>回弹缓动：末尾轻微过冲再回收，用于 Logo 入场。</summary>
        private static float EaseOutBack(float p)
        {
            const float c1 = 1.70158f;
            const float c3 = c1 + 1f;
            float x = p - 1f;
            return 1f + c3 * x * x * x + c1 * x * x;
        }

        private static void SetAlpha(TMP_Text t, float a)
        {
            if (t == null)
            {
                return;
            }
            Color c = t.color;
            c.a = Mathf.Clamp01(a);
            t.color = c;
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Splash] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private RectTransform FindRect(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[Splash] 缺少矩形节点「" + path + "」");
                return null;
            }
            return tr as RectTransform;
        }
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEngine;

namespace FTProject
{
    /// <summary>
    /// 浮动提示（P0-9）。
    /// 监听 ShowTipEvent，把消息排队显示，避免短时间内多条提示互相覆盖
    ///（塔防里"金币不足"很容易在一秒内被触发好几次）。
    ///
    /// 节点：根 TipsView（CanvasGroup + 本脚本）→ 子节点 TipBar（底条）→ 其下 TipText(TMP)
    /// （★ 2026-10-15 手工版把 TipText 从 root 直挂改为挂在 TipBar 之下，随条一起动）
    /// </summary>
    public class TipsView : MonoBehaviour
    {
        /// <summary>单条提示的显示时长（秒）</summary>
        private const float HoldSec = 1.2f;
        /// <summary>淡入/淡出时长（秒）</summary>
        private const float FadeSec = 0.15f;

        private sealed class Tip
        {
            public string Message;
            public float Remain;
        }

        private readonly Queue<Tip> _queue = new Queue<Tip>(8);
        private TMP_Text _text;
        private CanvasGroup _group;
        private float _alpha;
        private float _fadeTarget;
        private bool _showing;

        private void Awake()
        {
            _group = GetComponent<CanvasGroup>();
            if (_group == null)
            {
                _group = gameObject.AddComponent<CanvasGroup>();
            }
            _group.blocksRaycasts = false;
            _group.interactable = false;
            _alpha = 0f;
            _group.alpha = 0f;

            Transform tr = transform.Find("TipBar/TipText");
            if (tr == null)
            {
                Debug.LogError("[Tips] 缺少子节点「TipBar/TipText」（prefab 与 TipsView.cs 不一致）");
            }
            else
            {
                _text = tr.GetComponent<TMP_Text>();
                if (_text == null)
                {
                    Debug.LogError("[Tips] 节点「TipBar/TipText」上没有 TMP 文本组件");
                }
            }

            EventDispatcher.AddEventListener<string>(EventName.ShowTipEvent, Show);
        }

        private void OnDestroy()
        {
            EventDispatcher.RemoveEventListener<string>(EventName.ShowTipEvent, Show);
        }

        /// <summary>入队一条提示</summary>
        public void Show(string message)
        {
            if (string.IsNullOrEmpty(message))
            {
                return;
            }
            // 队列过长时丢弃最旧的，保证最新提示一定能显示出来
            while (_queue.Count >= 3)
            {
                _queue.Dequeue();
            }
            Tip t = new Tip();
            t.Message = message;
            t.Remain = HoldSec;
            _queue.Enqueue(t);
        }

        private void Update()
        {
            // 当前没有在显示的，就从队列取一条
            if (!_showing)
            {
                if (_queue.Count == 0)
                {
                    return;
                }
                Tip next = _queue.Dequeue();
                if (_text != null)
                {
                    _text.text = next.Message;
                }
                _showing = true;
                _fadeTarget = 1f;
                // 显示时长与淡出时长都计入 Remain，整体节奏更紧凑
                _holdRemain = next.Remain;
            }

            if (!_showing)
            {
                return;
            }

            // 淡入保持 → 计时结束后淡出
            if (_holdRemain > 0f)
            {
                _holdRemain -= Time.deltaTime;
                if (_holdRemain <= 0f)
                {
                    _fadeTarget = 0f;
                }
            }

            float step = Time.deltaTime / Mathf.Max(0.01f, FadeSec);
            _alpha = Mathf.MoveTowards(_alpha, _fadeTarget, step);
            if (_group != null)
            {
                _group.alpha = _alpha;
            }

            if (_fadeTarget <= 0f && _alpha <= 0f)
            {
                _showing = false;
            }
        }

        private float _holdRemain;
    }
}

using TMPro;
using UnityEngine;
