namespace FTProject
{
    /// <summary>
    /// 塔图鉴的一张卡片（UI 补全 B2）。
    ///
    /// 【为什么卡片必须有脚本】图鉴是**同一个 prefab 被池化复用 3 次**（LoopListView2 的机制，
    /// 2026-10-14 起塔型收敛为三类），一次显示、一次回收再填别的塔 ——
    /// 所以内容只能在运行时灌进去，不能烘死在 prefab 里。
    ///
    /// 【缩放/淡化挂在 Body 而不是根节点】LoopListView2 的条目根节点 pivot 固定 (0,0.5)，
    /// 缩放根节点会让卡片围绕左缘缩放 → 视觉上"居中卡左右空隙一宽一窄"。
    /// </summary>
    public class TowerCodexItem : MonoBehaviour
    {
        private static readonly Color Cyan = new Color(0.208f, 0.878f, 1f, 1f);
        private static readonly Color Gold = new Color(1f, 0.788f, 0.302f, 1f);
        private static readonly Color TextPrimary = new Color(0.910f, 0.941f, 0.980f, 1f);
        private static readonly Color TextSecondary = new Color(0.624f, 0.702f, 0.784f, 1f);

        private RectTransform _body;
        private Image _cardBg;
        private Image _topBar;
        private Image _icon;
        private TMP_Text _typeName;
        private TMP_Text _role;
        private TMP_Text _dpsRow;
        private TMP_Text _rangeRow;
        private TMP_Text _speedRow;
        private TMP_Text _priceRow;
        private TMP_Text _desc;

        /// <summary>供 LoopListView2 做缩放/淡化（挂在 Body 上，不缩根节点）。</summary>
        public RectTransform Body { get { return _body; } }

        private void Awake()
        {
            Transform bodyTr = transform.Find("Body");
            _body = bodyTr as RectTransform;
            _cardBg = FindImage("Body/CardBg");
            _topBar = FindImage("Body/TopBar");
            _icon = FindImage("Body/Icon");
            _typeName = FindText("Body/TypeName");
            _role = FindText("Body/Role");
            _dpsRow = FindText("Body/DpsRow");
            _rangeRow = FindText("Body/RangeRow");
            _speedRow = FindText("Body/SpeedRow");
            _priceRow = FindText("Body/PriceRow");
            _desc = FindText("Body/DescText");

            if (_typeName != null) _typeName.color = Cyan;
            if (_role != null) _role.color = TextSecondary;
            if (_dpsRow != null) _dpsRow.color = TextPrimary;
            if (_rangeRow != null) _rangeRow.color = TextPrimary;
            if (_speedRow != null) _speedRow.color = TextPrimary;
            if (_priceRow != null) _priceRow.color = Gold;
            if (_desc != null) _desc.color = TextSecondary;
        }

        /// <summary>回填一座塔的数据。全部取自配置，**没有任何硬编码数值**。</summary>
        public void SetData(TowerConfig cfg, string roleText)
        {
            if (cfg == null)
            {
                return;
            }

            Color theme = ThemeColor(cfg.Type);
            if (_topBar != null) _topBar.color = theme;
            if (_typeName != null)
            {
                // DisplayName：过多语言表（"普通塔"），缺条目回退英文原文（"Normal Tower"）
                _typeName.text = cfg.DisplayName;
                _typeName.color = theme;
            }
            if (_role != null) _role.text = roleText;
            if (_dpsRow != null) _dpsRow.text = cfg.IsSlowAura
                ? (Localization.Get("Slow {0:P0} · DPS 0", cfg.EffectValue) ?? string.Format("减速 {0:P0} · DPS 0", cfg.EffectValue))
                : (Localization.Get("Damage   {0}", cfg.Power) ?? string.Format("伤害　{0}", cfg.Power));
            if (_rangeRow != null) _rangeRow.text = Localization.Get("Range    {0:F1}", cfg.RadiusGrid) ?? string.Format("射程　{0:F1} 格", cfg.RadiusGrid);
            if (_speedRow != null) _speedRow.text = cfg.IsSlowAura
                ? (Localization.Get("Aura refresh {0:0.00}s", cfg.CooldownSec) ?? string.Format("光环刷新　{0:0.00} 秒", cfg.CooldownSec))
                : (Localization.Get("Speed    {0:F2}", cfg.CooldownSec) ?? string.Format("攻速　{0:F2} 秒", cfg.CooldownSec));
            if (_priceRow != null) _priceRow.text = Localization.Get("Cost     {0}", cfg.Prices) ?? string.Format("造价　{0} 金币", cfg.Prices);
            if (_desc != null)
            {
                _desc.text = string.IsNullOrEmpty(cfg.Desc) ? roleText : cfg.Desc;
            }

            if (_icon != null)
            {
                Sprite sprite = ResLoader.Instance.IsReady
                    ? ResLoader.Instance.Load<Sprite>("UI_TowerIcon_" + IconSuffix(cfg.Type))
                    : null;
                if (sprite != null)
                {
                    _icon.sprite = sprite;
                    _icon.color = Color.white;
                }
            }
            if (_cardBg != null)
            {
                _cardBg.color = new Color(0.118f, 0.161f, 0.224f, 0.96f);   // L3 面板色
            }
        }

        /// <summary>塔型主题色（2026-10-14 三塔型收敛后的三色映射）。</summary>
        public static Color ThemeColor(int type)
        {
            switch (type)
            {
                case 2: return new Color(1f, 0.478f, 0.161f, 1f);      // Power 火 #FF7A29
                case 3: return new Color(0.490f, 0.910f, 1f, 1f);      // Retard 冰 #7DE8FF
                default: return new Color(0.208f, 0.878f, 1f, 1f);     // Normal 青 #35E0FF
            }
        }

        /// <summary>塔型 → 图标名后缀（与 ResTable 登记的逻辑名一致）。</summary>
        public static string IconSuffix(int type)
        {
            switch (type)
            {
                case 2: return "Power";
                case 3: return "Retard";
                default: return "Normal";
            }
        }

        /// <summary>塔型 → 一句话定位（三塔型的定位文案）。</summary>
        public static string RoleText(int type)
        {
            switch (type)
            {
                case 2: return Localization.Get("Area blast · swarm clearer") ?? "范围爆炸 · 清群核心";
                case 3: return Localization.Get("Slows enemies · control") ?? "减速光环 · 增益全队";
                default: return Localization.Get("Single-target rapid fire") ?? "单体速射 · 性价比基准";
            }
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[TowerCodexItem] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Image FindImage(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[TowerCodexItem] 缺少图片节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Image>();
        }
    }
}

using System.Collections.Generic;
using SuperScrollView;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 防御塔图鉴（UI 补全 B2 / 效果图 19_TowerCodexView.svg）。
    ///
    /// 【它解决什么问题】5 种塔的定位、形态与三级数值在游戏里**没有任何地方能看到**，
    /// 玩家只能靠"造一座试试"。图鉴把配置表里的数值直接摊开。
    ///
    /// 【几何为什么照抄 SelectView】横向画廊的"精确居中 + 邻卡可见"是一组很脆的约束，
    /// 见 UIPrefabBuilder.SelectItemW 的注释（条目宽 ≡ 视口宽；视口比可视区窄；
    /// Viewport.pivot.x 必须预置 0；InitListView 只能调一次）。这里与那边**同一套参数与写法**，
    /// 改一处必须两处一起改。
    ///
    /// 【为什么不做点击态】图鉴是"看"的界面，点卡片没有下一层可去
    /// （详情已经在卡片上全部摊开），所以不做 onClick ——
    /// 顺带避开了 LoopListView2 "条目池化复用导致 onClick 重复挂"这个经典坑。
    /// </summary>
    public class TowerCodexView : MonoBehaviour
    {
        public const string LogicalName = "TowerCodexView";

        /// <summary>与 UIPrefabBuilder.TowerCodexItemPath 的资产名一致（LoopListView2 按名字取池）。</summary>
        private const string ItemPrefabName = "TowerCodexItem";

        /// <summary>必须与 UIPrefabBuilder 的 CodexItemW / CodexItemGap 一致（用于估算未实例化条目的位置）。</summary>
        private const float ItemWidth = 460f;
        private const float ItemGap = 70f;

        /// <summary>离视口中心一个步长就缩到最小/最暗（相邻那张落在最暗端）。</summary>
        private const float FocusFalloff = ItemWidth + ItemGap;

        private const float MinScale = 0.86f;
        private const float MinAlpha = 0.45f;

        private LoopListView2 _list;
        private Button _leftBtn;
        private Button _rightBtn;
        private Button _closeBtn;
        private TMP_Text _pageText;

        private List<TowerConfig> _towers;
        private bool _listInited;
        private int _pendingCenterIndex = -1;
        private int _centerIndex;

        private void Awake()
        {
            Transform listTr = transform.Find("Panel/List");
            _list = listTr != null ? listTr.GetComponent<LoopListView2>() : null;
            _leftBtn = FindButton("Panel/LeftBtn");
            _rightBtn = FindButton("Panel/RightBtn");
            _closeBtn = FindButton("Panel/CloseBtn");
            _pageText = FindText("Panel/PageText");

            if (_leftBtn != null) _leftBtn.onClick.AddListener(OnClickLeft);
            if (_rightBtn != null) _rightBtn.onClick.AddListener(OnClickRight);
            if (_closeBtn != null) _closeBtn.onClick.AddListener(OnClickClose);
        }

        private void OnEnable()
        {
            BuildList();
        }

        /// <summary>
        /// 取"每种塔的 1 级配置"作为图鉴数据源。
        /// 【为什么用 GetBaseTowers】它正是"建造栏上那 3 颗塔"的口径（2026-10-14 三塔型收敛）——
        /// 图鉴要与玩家实际能造的塔一一对应，用等级遍历会把 9 行都列出来（3 倍冗余）。
        /// </summary>
        private void BuildList()
        {
            if (_list == null)
            {
                Debug.LogWarning("[TowerCodex] 缺少 List 节点（LoopListView2），图鉴无法显示");
                return;
            }

            _towers = Configs.GetBaseTowers();
            if (_towers == null)
            {
                _towers = new List<TowerConfig>();
            }

            // 兜底：预制体里已经勾好，这里再确认一次（漏勾则"吸附居中"整个失效）
            _list.ItemSnapEnable = true;

            if (!_listInited)
            {
                _listInited = true;
                LoopListViewInitParam p = LoopListViewInitParam.CopyDefaultInitParam();
                p.mItemDefaultWithPaddingSize = ItemWidth + ItemGap;   // 用默认 20 会让初始定位被 clamp 回 0
                p.mSmoothDumpRate = 0.25f;
                _list.InitListView(_towers.Count, OnGetItemByIndex, p);
                _pendingCenterIndex = _towers.Count > 0 ? 0 : -1;
            }
            else if (_list.ItemTotalCount != _towers.Count)
            {
                _list.SetListItemCount(_towers.Count, false);
                _list.RefreshAllShownItem();
            }
            else
            {
                _list.RefreshAllShownItem();
            }

            RefreshFooter();
        }

        private LoopListViewItem2 OnGetItemByIndex(LoopListView2 listView, int index)
        {
            if (index < 0 || _towers == null || index >= _towers.Count)
            {
                return null;
            }

            LoopListViewItem2 item = listView.NewListViewItem(ItemPrefabName);
            if (item == null)
            {
                return null;
            }

            // 池化复用：数据每帧都要重灌，否则滚回来会看到上一张卡的内容
            item.UserIntData1 = index;
            TowerCodexItem card = item.GetComponent<TowerCodexItem>();
            if (card != null)
            {
                TowerConfig cfg = _towers[index];
                card.SetData(cfg, TowerCodexItem.RoleText(cfg.Type));
            }
            return item;
        }

        private void LateUpdate()
        {
            if (_list == null || !_listInited || _towers == null)
            {
                return;
            }

            // 【为什么首次定位拖到第一帧 LateUpdate】OnEnable 时 Canvas 还没排版，
            //   viewport / Content 的 rect 仍是 0，此时定位会被 clamp 回 0（永远停在第 1 张）。
            if (_pendingCenterIndex >= 0)
            {
                int idx = _pendingCenterIndex;
                _pendingCenterIndex = -1;
                _centerIndex = idx;
                _list.SetSnapTargetItemIndex(idx);
                _list.FinishSnapImmediately();
                RefreshFooter();
            }

            UpdateItemVisuals();
        }

        /// <summary>
        /// 按"离列表中心多远"缩放 + 淡化每张卡片。
        /// 【为什么不在卡片内部自己算】卡片不知道自己在视口里的位置；
        ///   而且 LoopListView2 的排布只有这里看得全。
        /// 【为什么改 Body 的缩放而不是卡片根节点】根节点 pivot=(0,0.5)，缩它会围绕左缘缩 → 偏心。
        /// </summary>
        private void UpdateItemVisuals()
        {
            RectTransform viewport = _list.GetComponent<ScrollRect>().viewport;
            float centerX = viewport.rect.center.x;
            int count = _list.ShownItemCount;
            for (int i = 0; i < count; i++)
            {
                LoopListViewItem2 item = _list.GetShownItemByIndex(i);
                if (item == null)
                {
                    continue;
                }
                TowerCodexItem card = item.GetComponent<TowerCodexItem>();
                RectTransform body = card != null ? card.Body : null;
                if (body == null)
                {
                    continue;
                }

                RectTransform itemRect = (RectTransform)item.transform;
                Vector3 itemCenter = viewport.InverseTransformPoint(itemRect.TransformPoint(itemRect.rect.center));
                float dist = Mathf.Abs(itemCenter.x - centerX);
                float t = Mathf.Clamp01(dist / FocusFalloff);
                float scale = Mathf.Lerp(1f, MinScale, t);
                body.localScale = new Vector3(scale, scale, 1f);

                CanvasGroup cg = body.GetComponent<CanvasGroup>();
                if (cg != null)
                {
                    cg.alpha = Mathf.Lerp(1f, MinAlpha, t);
                }
            }
        }

        // ------------------------------------------------------------------
        // 交互
        // ------------------------------------------------------------------

        private void OnClickLeft()
        {
            MoveCenter(-1);
        }

        private void OnClickRight()
        {
            MoveCenter(1);
        }

        private void MoveCenter(int delta)
        {
            if (_towers == null || _towers.Count == 0)
            {
                return;
            }
            int target = Mathf.Clamp(_centerIndex + delta, 0, _towers.Count - 1);
            if (target == _centerIndex)
            {
                RefreshFooter();
                return;
            }
            _centerIndex = target;
            _list.SetSnapTargetItemIndex(target);
            RefreshFooter();
        }

        private void RefreshFooter()
        {
            int total = _towers != null ? _towers.Count : 0;
            if (_pageText != null)
            {
                _pageText.text = total > 0 ? string.Format("{0} / {1}", _centerIndex + 1, total) : "0 / 0";
            }
            // 到头置灰（只挪不进关，所以置灰比"循环回绕"更符合预期）
            if (_leftBtn != null) _leftBtn.interactable = _centerIndex > 0;
            if (_rightBtn != null) _rightBtn.interactable = _centerIndex < total - 1;
        }

        private void OnClickClose()
        {
            UIManager.Instance.Close(LogicalName);
            // 图鉴是从主菜单进来的整页界面，"返回"就该回到主菜单
            UIManager.Instance.Open<MainMenuView>("MainMenuView", UILayout.NormalPanel);
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[TowerCodex] 缺少文本节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning("[TowerCodex] 缺少按钮节点「" + path + "」");
                return null;
            }
            return tr.GetComponent<Button>();
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;

namespace FTProject
{
    /// <summary>
    /// 塔按钮的"按压/松开"中继组件（长按拖拽建造 · 2026-10-14）。
    ///
    /// 【为什么需要单独一个组件，而不能只靠 Button.onClick】
    ///   拖拽建造（对标《坚守阵地》）需要区分两种手势：
    ///     · 快速点按（按下→松开都在按钮上、时间短、没怎么动）→ 经典放置态（点击落子）；
    ///     · 长按 / 按住后移动 → 立即生成拖拽实例跟手，松手落子。
    ///   Button 只会给 onClick（松手时才判定），拿不到"按住了多久、挪了多远"，
    ///   所以必须监听 IPointerDownHandler / IPointerUpHandler。
    ///   本组件只做"转发"，手势判定（长按时长/位移阈值）全部在 HudView 里 ——
    ///   保持"HUD 一个脑子"的既有结构，避免判定逻辑散进 prefab 组件。
    ///
    /// 【为什么不进 prefab】由 HudView.Awake 对每个塔按钮 AddComponent（实例级），
    ///   不动 HudView.prefab 资产 —— prefab 里少一个脚本引用，就少一类
    ///   "prefab 与程序集版本错位"的 missing-script 风险。
    ///
    /// 【OnPointerUp 一定收得到吗】UGUI 会把 pointerUp 路由给"按下时捕获"的
    ///   pointerPress 对象，即使手指已经挪出按钮也会送达 —— 所以松手回调可靠；
    ///   而 onClick 只有"松手仍在按钮上"才触发，天然区分"原地松手/拖走松手"。
    /// </summary>
    public class TowerDragButton : MonoBehaviour, IPointerDownHandler, IPointerUpHandler
    {
        /// <summary>按下回调（HudView 记录按下时间/位置，开始长按计时）。</summary>
        public System.Action OnPressed;

        /// <summary>松开回调（HudView 判定这次按压最终算"拖拽"还是"点按"）。</summary>
        public System.Action OnReleased;

        public void OnPointerDown(PointerEventData eventData)
        {
            if (OnPressed != null)
            {
                OnPressed();
            }
        }

        public void OnPointerUp(PointerEventData eventData)
        {
            if (OnReleased != null)
            {
                OnReleased();
            }
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace FTProject
{
    /// <summary>
    /// 已建塔的升级 / 出售面板（M2-B3/B4/B5，v1 纯逻辑优先版）。
    ///
    /// 【为什么先做"逻辑优先"】升级/出售的**规则**（升级链、费用、返还、点击响应）
    /// 与美术资源无关，先把这部分打通并可用占位 UI 验证，等升级面板美术到位后
    /// 只换 prefab、不改本脚本。所以本脚本对节点**全部做了容错**：
    /// 缺哪个节点就跳过它的刷新，只打一条 warning，不阻断游戏。
    ///
    /// 【节点约定（与 UIPrefabBuilder 生成的一致）】
    ///   TowerInfoView
    ///   ├── Bg            半透明底（点它关闭面板）
    ///   ├── Panel
    ///   │   ├── Title     塔名 + 等级
    ///   │   ├── Stats     攻击力 / 射程 / 攻速 文本
    ///   │   ├── UpgradeBtn（→ Label）  升级
    ///   │   ├── SellBtn  （→ Label）  出售
    ///   │   └── CloseBtn （→ Label）  关闭
    ///
    /// 【交互约定】
    ///   - 打开：收到 TowerSelectedEvent(BaseTower)
    ///   - 关闭：收到 TowerDeselectedEvent，或点 Bg / CloseBtn
    ///   - 升级：发 TowerUpgradeRequestEvent(tower)，由 TowerManager.TryUpgrade 执行（换实例）
    ///   - 出售：本面板弹二次确认（LogWarning 占位 + 直接执行），执行后关闭
    ///
    /// 【不做的事】不直接持有 TowerManager 做业务判断，只发事件；
    /// 但升级/出售的"结果"需要立刻反映到面板（等级/费用），所以订阅升级成功事件来刷新。
    /// </summary>
    public class TowerInfoView : MonoBehaviour
    {
        // 文本
        private TMP_Text _title;
        private TMP_Text _stats;

        // 按钮
        private Button _upgradeBtn;
        private TMP_Text _upgradeLabel;
        private Button _sellBtn;
        private TMP_Text _sellLabel;
        private Button _closeBtn;
        private Button _bgBtn;

        /// <summary>当前面板展示的塔</summary>
        private BaseTower _tower;

        /// <summary>
        /// 【真机诊断】上一次升级按钮可用性（-1=未知 / 0=置灰 / 1=可点）。
        /// 仅在"变化"时打日志，避免每帧刷屏；随 Show(塔) 切换重置，保证新塔首次刷新必打。
        /// </summary>
        private int _lastUpgradeInteractable = -1;

        /// <summary>面板 prefab 的逻辑名（ResTable 登记）</summary>
        public const string LogicalName = "TowerInfoView";

        private void Awake()
        {
            BindNodes();
            SetContentVisible(false);
        }

        private void OnEnable()
        {
            EventDispatcher.AddEventListener<BaseTower>(EventName.TowerSelectedEvent, OnTowerSelected);
            EventDispatcher.AddEventListener(EventName.TowerDeselectedEvent, OnTowerDeselected);
            EventDispatcher.AddEventListener<BaseTower>(EventName.TowerUpgradeSuccess, OnUpgradeSuccess);
            EventDispatcher.AddEventListener<BaseTower>(EventName.DestroyTower, OnTowerDestroyed);
            EventDispatcher.AddEventListener<int, int>(EventName.GoldChangeEvent, OnGoldChanged);
            // 语言切换：本面板在游戏中可能与暂停/设置同屏（暂停不会关面板），
            // 切语言后必须重刷标题/数值行/按钮文案（2026-10-16 多语言审计）
            EventDispatcher.AddEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
        }

        private void OnDisable()
        {
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.TowerSelectedEvent, OnTowerSelected);
            EventDispatcher.RemoveEventListener(EventName.TowerDeselectedEvent, OnTowerDeselected);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.TowerUpgradeSuccess, OnUpgradeSuccess);
            EventDispatcher.RemoveEventListener<BaseTower>(EventName.DestroyTower, OnTowerDestroyed);
            EventDispatcher.RemoveEventListener<int, int>(EventName.GoldChangeEvent, OnGoldChanged);
            EventDispatcher.RemoveEventListener<int>(EventName.LanguageChangedEvent, OnLanguageChanged);
        }

        /// <summary>语言已切换 → 重刷当前展示的塔（Refresh 内部同时刷按钮文案）。</summary>
        private void OnLanguageChanged(int lang)
        {
            if (_tower != null && _tower.Config != null)
            {
                Refresh();
            }
        }

        // ------------------------------------------------------------------
        // 绑定（全部容错：缺节点只警告，不报错阻断）
        // ------------------------------------------------------------------

        private void BindNodes()
        {
            _title = FindText("Panel/Title");
            _stats = FindText("Panel/Stats");
            if (_stats != null)
            {
                _stats.enableWordWrapping = true;
                _stats.enableAutoSizing = true;
                _stats.fontSizeMin = 20f;
                _stats.fontSizeMax = 32f;
                Vector2 size = _stats.rectTransform.sizeDelta;
                size.y = Mathf.Max(size.y, 130f);
                _stats.rectTransform.sizeDelta = size;
            }

            _upgradeBtn = FindButton("Panel/UpgradeBtn");
            _upgradeLabel = FindText("Panel/UpgradeBtn/Label");
            _sellBtn = FindButton("Panel/SellBtn");
            _sellLabel = FindText("Panel/SellBtn/Label");
            _closeBtn = FindButton("Panel/CloseBtn");
            _bgBtn = FindButton("Bg");

            if (_upgradeBtn != null)
            {
                _upgradeBtn.onClick.AddListener(OnClickUpgrade);
            }
            if (_sellBtn != null)
            {
                _sellBtn.onClick.AddListener(OnClickSell);
            }
            if (_closeBtn != null)
            {
                _closeBtn.onClick.AddListener(OnClickClose);
            }
            if (_bgBtn != null)
            {
                _bgBtn.onClick.AddListener(OnClickClose);
            }
        }

        private TMP_Text FindText(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning(string.Format(
                    "[TowerInfoView] 缺少文本节点「{0}」—— 面板将跳过该项刷新（美术补齐后自动恢复）", path));
                return null;
            }
            return tr.GetComponent<TMP_Text>();
        }

        private Button FindButton(string path)
        {
            Transform tr = transform.Find(path);
            if (tr == null)
            {
                Debug.LogWarning(string.Format(
                    "[TowerInfoView] 缺少按钮节点「{0}」—— 该操作本版不可用（美术补齐后自动恢复）", path));
                return null;
            }
            return tr.GetComponent<Button>();
        }

        // ------------------------------------------------------------------
        // 事件 → 面板
        // ------------------------------------------------------------------

        private void OnTowerSelected(BaseTower tower)
        {
            Show(tower);
        }

        /// <summary>
        /// 打开面板并展示指定塔。
        /// 【为什么是公开方法】面板实例化发生在 TowerSelectedEvent 的分发过程中，
        /// 它的 OnEnable 订阅晚于本次分发 → 收不到"这一次"事件。GameFlowManager 打开后
        /// 必须显式调用本方法喂一次数据（详见 GameFlowManager.OnTowerSelected 注释）。
        /// </summary>
        public void Show(BaseTower tower)
        {
            if (tower == null)
            {
                SetContentVisible(false);
                return;
            }
            _tower = tower;
            // 【真机诊断埋点】面板被打开并喂了数据 —— 升级面板本身是活的
            Debug.Log("[TowerInfoView] Show: " + tower.name);
            _lastUpgradeInteractable = -1;   // 诊断状态随塔切换重置（新塔首次刷新必打一条可用性日志）
            SetContentVisible(true);
            Refresh();
        }

        private void OnTowerDeselected()
        {
            _tower = null;
            SetContentVisible(false);
        }

        /// <summary>
        /// 升级成功 → 面板切到**新实例**。
        /// 【为什么直接收参数，而不是回查 TowerPlacement.SelectedTower】
        ///   升级是"换实例"，旧的 BaseTower 已被销毁并归还对象池。
        ///   事件里直接带着新实例，面板不需要再依赖 TowerPlacement 这个全局单例去绕一圈；
        ///   依赖越少，将来换 UI / 换状态机时改动面越小。
        /// </summary>
        private void OnUpgradeSuccess(BaseTower newTower)
        {
            _tower = newTower;
            Refresh();
        }

        private void OnTowerDestroyed(BaseTower tower)
        {
            if (_tower == tower)
            {
                _tower = null;
                SetContentVisible(false);
            }
        }

        private void OnGoldChanged(int current, int delta)
        {
            if (_tower != null)
            {
                RefreshButtons();
            }
        }

        /// <summary>显示/隐藏面板内容（保留本组件启用，以便持续监听事件）</summary>
        private void SetContentVisible(bool visible)
        {
            if (_bgBtn != null)
            {
                _bgBtn.gameObject.SetActive(visible);
            }
            Transform panel = transform.Find("Panel");
            if (panel != null)
            {
                panel.gameObject.SetActive(visible);
            }
        }

        // ------------------------------------------------------------------
        // 刷新
        // ------------------------------------------------------------------

        private void Refresh()
        {
            if (_tower == null || _tower.Config == null)
            {
                SetText(_title, Localization.Get("Tower Panel") ?? "防御塔");
                SetText(_stats, string.Empty);
                return;
            }

            TowerConfig cfg = _tower.Config;
            // 塔名走 DisplayName（多语言表；缺条目回退英文原文）
            SetText(_title, string.Format("{0}  Lv.{1}", cfg.DisplayName, cfg.Level));
            // 带上 DPS：升级值不值得，玩家看"攻击力"是看不出来的，
            // 而 power / CD 才是这条升级链真正在卖的东西。
            if (cfg.IsSlowAura)
            {
                SetText(_stats, Localization.Get("Slow {0:P0}  Range {1}  Refresh {2:0.00}s  DPS 0",
                        cfg.EffectValue, cfg.RadiusGrid, cfg.CooldownSec)
                    ?? string.Format("减速 {0:P0}   覆盖 {1} 格   刷新 {2:0.00}s   DPS 0",
                        cfg.EffectValue, cfg.RadiusGrid, cfg.CooldownSec));
            }
            else SetText(_stats, Localization.Get("ATK {0}  RNG {1}  SPD {2}s  DPS {3}",
                    cfg.Power, cfg.RadiusGrid, cfg.CooldownSec, cfg.Power / cfg.CooldownSec)
                ?? string.Format("攻击 {0:0.#}   射程 {1:0.#} 格   攻速 {2:0.00}s   DPS {3:0.#}",
                    cfg.Power, cfg.RadiusGrid, cfg.CooldownSec, cfg.Power / cfg.CooldownSec));

            RefreshButtons();
        }

        /// <summary>
        /// 刷新升级/出售按钮：文案（含费用）+ 可用性。
        /// - 升级：满级 → 禁用并显示「已满级」；否则显示「升级 (费用)」，金币不足置灰
        /// - 出售：始终可用，显示「出售 (+返还)」
        /// </summary>
        private void RefreshButtons()
        {
            if (_tower == null || _tower.Config == null)
            {
                return;
            }
            TowerConfig cfg = _tower.Config;
            PlayerDataManager pd = PlayerDataManager.Instance;

            // ---- 升级 ----
            if (_upgradeBtn != null)
            {
                // 下一级一律由 upgradeTo 链决定（与 TowerManager.TryUpgrade 同一口径）
                TowerConfig next = cfg.IsMaxLevel ? null : Configs.GetNextLevel(cfg);
                if (cfg.IsMaxLevel)
                {
                    _upgradeBtn.interactable = false;
                    SetText(_upgradeLabel, Localization.Get("MAX") ?? "已满级");
                }
                else
                {
                    int cost = next != null ? next.Prices : 0;
                    _upgradeBtn.interactable = next != null && pd.Gold >= cost;
                    SetText(_upgradeLabel, next != null
                        ? (Localization.Get("Upgrade ({0})", cost) ?? string.Format("升级 ({0})", cost))
                        : (Localization.Get("No Next Level") ?? "无下一级"));
                }

                // 【真机诊断埋点】升级按钮可用性**变化时**打一条：置灰的 Button 不会触发
                // onClick，"点升级没反应"时先看这条——若为"置灰"，原因（金币不足/无下一级/
                // 满级）直接列在括号里，不需要再猜。
                int state = _upgradeBtn.interactable ? 1 : 0;
                if (state != _lastUpgradeInteractable)
                {
                    _lastUpgradeInteractable = state;
                    Debug.Log(string.Format(
                        "[TowerInfoView] 升级按钮可用性={0}（塔={1} Lv.{2} 金币={3} 下一级费用={4} 满级={5} 有下一级={6}）",
                        _upgradeBtn.interactable ? "可点" : "置灰",
                        cfg.Name, cfg.Level, pd.Gold,
                        next != null ? next.Prices : -1, cfg.IsMaxLevel, next != null));
                }
            }

            // ---- 出售 ----
            if (_sellBtn != null)
            {
                float rate = Configs.Global != null ? Configs.Global.SellRefundRate : 1f;
                int refund = Mathf.Max(0, Mathf.RoundToInt(cfg.SellPrice * rate));
                _sellBtn.interactable = true;
                // 文案常驻（不再有"确认态"，所以不需要"别把它刷回去"的保护）
                SetText(_sellLabel, Localization.Get("Sell (+{0})", refund)
                    ?? string.Format("出售 (+{0})", refund));
            }
        }

        // ------------------------------------------------------------------
        // 出售：发起请求（确认交给 SellConfirmView）
        // ------------------------------------------------------------------
        // 【为什么把"原地两段式确认"删掉】UI 补全 C1 把确认升级成了独立弹窗。
        // 原地改文案的问题：① 玩家看不到这次要退回多少金币；② 面板任何一次刷新都可能
        // 把"确认出售？"的文案刷回"出售 (+46)"，确认态很难维护；
        // ③ 文案顶掉价格后，玩家不知道自己点的是哪座塔。
        // 现在本面板只负责"发起请求"，确认 + 金额展示都在 SellConfirmView 里完成。

        private void OnClickSell()
        {
            if (_tower == null)
            {
                return;
            }
            EventDispatcher.TriggerEvent<BaseTower>(EventName.TowerSellRequestEvent, _tower);
        }

        private void OnClickUpgrade()
        {
            if (_tower == null)
            {
                return;
            }
            // 【真机诊断埋点】UpgradeBtn 确实被点到了
            Debug.Log("[TowerInfoView] OnClickUpgrade: " + _tower.name);
            EventDispatcher.TriggerEvent<BaseTower>(EventName.TowerUpgradeRequestEvent, _tower);
            // 结果由 TowerUpgradeSuccess 事件回来刷新
        }

        private void OnClickClose()
        {
            // 交给 TowerPlacement 统一取消选中（单一状态源）
            if (TowerPlacement.Instance != null)
            {
                TowerPlacement.Instance.Deselect();
            }
            else
            {
                OnTowerDeselected();
            }
        }

        private static void SetText(TMP_Text t, string value)
        {
            if (t != null && t.text != value)
            {
                t.text = value;
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditorInternal;


namespace SuperScrollView
{

    [CustomEditor(typeof(LoopListView2))]
    public class LoopListViewEditor2 : Editor
    {

        SerializedProperty mSupportScrollBar;
        SerializedProperty mItemSnapEnable;
        SerializedProperty mArrangeType;
        SerializedProperty mItemPrefabDataList;
        SerializedProperty mItemSnapPivot;
        SerializedProperty mViewPortSnapPivot;

        GUIContent mSupportScrollBarContent = new GUIContent("SupportScrollBar");
        GUIContent mItemSnapEnableContent = new GUIContent("ItemSnapEnable");
        GUIContent mArrangeTypeGuiContent = new GUIContent("ArrangeType");
        GUIContent mItemPrefabListContent = new GUIContent("ItemPrefabList");
        GUIContent mItemSnapPivotContent = new GUIContent("ItemSnapPivot");
        GUIContent mViewPortSnapPivotContent = new GUIContent("ViewPortSnapPivot");

        protected virtual void OnEnable()
        {
            mSupportScrollBar = serializedObject.FindProperty("mSupportScrollBar");
            mItemSnapEnable = serializedObject.FindProperty("mItemSnapEnable");
            mArrangeType = serializedObject.FindProperty("mArrangeType");
            mItemPrefabDataList = serializedObject.FindProperty("mItemPrefabDataList");
            mItemSnapPivot = serializedObject.FindProperty("mItemSnapPivot");
            mViewPortSnapPivot = serializedObject.FindProperty("mViewPortSnapPivot");
        }


        void ShowItemPrefabDataList(LoopListView2 listView)
        {
            EditorGUILayout.PropertyField(mItemPrefabDataList, mItemPrefabListContent);
            if (mItemPrefabDataList.isExpanded == false)
            {
                return;
            }
            EditorGUI.indentLevel += 1;
            if (GUILayout.Button("Add New"))
            {
                mItemPrefabDataList.InsertArrayElementAtIndex(mItemPrefabDataList.arraySize);
                if(mItemPrefabDataList.arraySize > 0)
                {
                    SerializedProperty itemData = mItemPrefabDataList.GetArrayElementAtIndex(mItemPrefabDataList.arraySize - 1);
                    SerializedProperty mItemPrefab = itemData.FindPropertyRelative("mItemPrefab");
                    mItemPrefab.objectReferenceValue = null;
                }
            }
            int removeIndex = -1;
            EditorGUILayout.PropertyField(mItemPrefabDataList.FindPropertyRelative("Array.size"));
            for (int i = 0; i < mItemPrefabDataList.arraySize; i++)
            {
                SerializedProperty itemData = mItemPrefabDataList.GetArrayElementAtIndex(i);
                SerializedProperty mInitCreateCount = itemData.FindPropertyRelative("mInitCreateCount");
                SerializedProperty mItemPrefab = itemData.FindPropertyRelative("mItemPrefab");
                SerializedProperty mItemPrefabPadding = itemData.FindPropertyRelative("mPadding");
                SerializedProperty mItemStartPosOffset = itemData.FindPropertyRelative("mStartPosOffset");
                EditorGUILayout.BeginHorizontal();
                EditorGUILayout.PropertyField(itemData);
                if (GUILayout.Button("Remove"))
                {
                    removeIndex = i;
                }
                EditorGUILayout.EndHorizontal();
                if (itemData.isExpanded == false)
                {
                    continue;
                }
                mItemPrefab.objectReferenceValue = EditorGUILayout.ObjectField("ItemPrefab", mItemPrefab.objectReferenceValue, typeof(GameObject), true);
                mItemPrefabPadding.floatValue = EditorGUILayout.FloatField("ItemPadding", mItemPrefabPadding.floatValue);
                if(listView.ArrangeType == ListItemArrangeType.TopToBottom || listView.ArrangeType == ListItemArrangeType.BottomToTop)
                {
                    mItemStartPosOffset.floatValue = EditorGUILayout.FloatField("XPosOffset", mItemStartPosOffset.floatValue);
                }
                else
                {
                    mItemStartPosOffset.floatValue = EditorGUILayout.FloatField("YPosOffset", mItemStartPosOffset.floatValue);
                }
                mInitCreateCount.intValue = EditorGUILayout.IntField("InitCreateCount", mInitCreateCount.intValue);
                EditorGUILayout.Space();
                EditorGUILayout.Space();
            }
            if (removeIndex >= 0)
            {
                mItemPrefabDataList.DeleteArrayElementAtIndex(removeIndex);
            }
            EditorGUI.indentLevel -= 1;
        }

        public override void OnInspectorGUI()
        {
            serializedObject.Update();
            LoopListView2 tListView = serializedObject.targetObject as LoopListView2;
            if (tListView == null)
            {
                return;
            }
            ShowItemPrefabDataList(tListView);
            EditorGUILayout.Space();
            EditorGUILayout.PropertyField(mSupportScrollBar, mSupportScrollBarContent);
            EditorGUILayout.PropertyField(mItemSnapEnable, mItemSnapEnableContent);
            if(mItemSnapEnable.boolValue == true)
            {
                EditorGUILayout.PropertyField(mItemSnapPivot, mItemSnapPivotContent);
                EditorGUILayout.PropertyField(mViewPortSnapPivot, mViewPortSnapPivotContent);
            }
            EditorGUILayout.PropertyField(mArrangeType, mArrangeTypeGuiContent);

            serializedObject.ApplyModifiedProperties();
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;

namespace SuperScrollView
{
    public class ClickEventListener : MonoBehaviour, IPointerClickHandler, IPointerDownHandler, IPointerUpHandler
    {
        public static ClickEventListener Get(GameObject obj)
        {
            ClickEventListener listener = obj.GetComponent<ClickEventListener>();
            if (listener == null)
            {
                listener = obj.AddComponent<ClickEventListener>();
            }
            return listener;
        }

        System.Action<GameObject> mClickedHandler = null;
        System.Action<GameObject> mDoubleClickedHandler = null;
        System.Action<GameObject> mOnPointerDownHandler = null;
        System.Action<GameObject> mOnPointerUpHandler = null;
        bool mIsPressed = false;

        public bool IsPressd
        {
            get { return mIsPressed; }
        }
        public void OnPointerClick(PointerEventData eventData)
        {
            if (eventData.clickCount == 2)
            {
                if (mDoubleClickedHandler != null)
                {
                    mDoubleClickedHandler(gameObject);
                }
            }
            else
            {
                if (mClickedHandler != null)
                {
                    mClickedHandler(gameObject);
                }
            }

        }
        public void SetClickEventHandler(System.Action<GameObject> handler)
        {
            mClickedHandler = handler;
        }

        public void SetDoubleClickEventHandler(System.Action<GameObject> handler)
        {
            mDoubleClickedHandler = handler;
        }

        public void SetPointerDownHandler(System.Action<GameObject> handler)
        {
            mOnPointerDownHandler = handler;
        }

        public void SetPointerUpHandler(System.Action<GameObject> handler)
        {
            mOnPointerUpHandler = handler;
        }


        public void OnPointerDown(PointerEventData eventData)
        {
            mIsPressed = true;
            if (mOnPointerDownHandler != null)
            {
                mOnPointerDownHandler(gameObject);
            }
        }

        public void OnPointerUp(PointerEventData eventData)
        {
            mIsPressed = false;
            if (mOnPointerUpHandler != null)
            {
                mOnPointerUpHandler(gameObject);
            }
        }

    }

}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

namespace SuperScrollView
{

    public class ItemSizeGroup
    {

        public float[] mItemSizeArray = null;
        public float[] mItemStartPosArray = null;
        public int mItemCount = 0;
        int mDirtyBeginIndex = ItemPosMgr.mItemMaxCountPerGroup;
        public float mGroupSize = 0;
        public float mGroupStartPos = 0;
        public float mGroupEndPos = 0;
        public int mGroupIndex = 0;
        float mItemDefaultSize = 0;
        public ItemSizeGroup(int index,float itemDefaultSize)
        {
            mGroupIndex = index;
            mItemDefaultSize = itemDefaultSize;
            Init();
        }

        public void Init()
        {
            mItemSizeArray = new float[ItemPosMgr.mItemMaxCountPerGroup];
            if (mItemDefaultSize != 0)
            {
                for (int i = 0; i < mItemSizeArray.Length; ++i)
                {
                    mItemSizeArray[i] = mItemDefaultSize;
                }
            }
            mItemStartPosArray = new float[ItemPosMgr.mItemMaxCountPerGroup];
            mItemStartPosArray[0] = 0;
            mItemCount = ItemPosMgr.mItemMaxCountPerGroup;
            mGroupSize = mItemDefaultSize * mItemSizeArray.Length;
            if (mItemDefaultSize != 0)
            {
                mDirtyBeginIndex = 0;
            }
            else
            {
                mDirtyBeginIndex = ItemPosMgr.mItemMaxCountPerGroup;
            }
        }

        public float GetItemStartPos(int index)
        {
            return mGroupStartPos + mItemStartPosArray[index];
        }

        public bool IsDirty
        {
            get
            {
                return (mDirtyBeginIndex < mItemCount);
            }
        }
        public float SetItemSize(int index, float size)
        {
            float old = mItemSizeArray[index];
            if (old == size)
            {
                return 0;
            }
            mItemSizeArray[index] = size;
            if (index < mDirtyBeginIndex)
            {
                mDirtyBeginIndex = index;
            }
            float ds = size - old;
            mGroupSize = mGroupSize + ds;
            return ds;
        }

        public void SetItemCount(int count)
        {
            if (mItemCount == count)
            {
                return;
            }
            mItemCount = count;
            RecalcGroupSize();
        }

        public void RecalcGroupSize()
        {
            mGroupSize = 0;
            for (int i = 0; i < mItemCount; ++i)
            {
                mGroupSize += mItemSizeArray[i];
            }
        }

        public int GetItemIndexByPos(float pos)
        {
            if (mItemCount == 0)
            {
                return -1;
            }
            int low = 0;
            int high = mItemCount - 1;
            while (low <= high)
            {
                int mid = (low + high) / 2;
                float startPos = mItemStartPosArray[mid];
                float endPos = startPos + mItemSizeArray[mid];
                if (startPos <= pos && endPos >= pos)
                {
                    return mid;
                }
                else if (pos > endPos)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }
            return -1;
        }

        public void UpdateAllItemStartPos()
        {
            if (mDirtyBeginIndex >= mItemCount)
            {
                return;
            }
            int startIndex = (mDirtyBeginIndex < 1) ? 1 : mDirtyBeginIndex;
            for (int i = startIndex; i < mItemCount; ++i)
            {
                mItemStartPosArray[i] = mItemStartPosArray[i - 1] + mItemSizeArray[i - 1];
            }
            mDirtyBeginIndex = mItemCount;
        }
    }

    public class ItemPosMgr
    {
        public const int mItemMaxCountPerGroup = 100;
        List<ItemSizeGroup> mItemSizeGroupList = new List<ItemSizeGroup>();
        int mDirtyBeginIndex = int.MaxValue;
        public float mTotalSize = 0;
        public float mItemDefaultSize = 20;

        public ItemPosMgr(float itemDefaultSize)
        {
            mItemDefaultSize = itemDefaultSize;
        }

        public void SetItemMaxCount(int maxCount)
        {
            mDirtyBeginIndex = 0;
            mTotalSize = 0;
            int st = maxCount % mItemMaxCountPerGroup;
            int lastGroupItemCount = st;
            int needMaxGroupCount = maxCount / mItemMaxCountPerGroup;
            if (st > 0)
            {
                needMaxGroupCount++;
            }
            else
            {
                lastGroupItemCount = mItemMaxCountPerGroup;
            }
            int count = mItemSizeGroupList.Count;
            if (count > needMaxGroupCount)
            {
                int d = count - needMaxGroupCount;
                mItemSizeGroupList.RemoveRange(needMaxGroupCount, d);
            }
            else if (count < needMaxGroupCount)
            {
                int d = needMaxGroupCount - count;
                for (int i = 0; i < d; ++i)
                {
                    ItemSizeGroup tGroup = new ItemSizeGroup(count + i, mItemDefaultSize);
                    mItemSizeGroupList.Add(tGroup);
                }
            }
            count = mItemSizeGroupList.Count;
            if (count == 0)
            {
                return;
            }
            for (int i = 0; i < count - 1; ++i)
            {
                mItemSizeGroupList[i].SetItemCount(mItemMaxCountPerGroup);
            }
            mItemSizeGroupList[count - 1].SetItemCount(lastGroupItemCount);
            for (int i = 0; i < count; ++i)
            {
                mTotalSize = mTotalSize + mItemSizeGroupList[i].mGroupSize;
            }

        }

        public void SetItemSize(int itemIndex, float size)
        {
            int groupIndex = itemIndex / mItemMaxCountPerGroup;
            int indexInGroup = itemIndex % mItemMaxCountPerGroup;
            ItemSizeGroup tGroup = mItemSizeGroupList[groupIndex];
            float changedSize = tGroup.SetItemSize(indexInGroup, size);
            if (changedSize != 0f)
            {
                if (groupIndex < mDirtyBeginIndex)
                {
                    mDirtyBeginIndex = groupIndex;
                }
            }
            mTotalSize += changedSize;
        }

        public float GetItemPos(int itemIndex)
        {
            Update(true);
            int groupIndex = itemIndex / mItemMaxCountPerGroup;
            int indexInGroup = itemIndex % mItemMaxCountPerGroup;
            return mItemSizeGroupList[groupIndex].GetItemStartPos(indexInGroup);
        }

        public void GetItemIndexAndPosAtGivenPos(float pos, ref int index, ref float itemPos)
        {
            Update(true);
            index = 0;
            itemPos = 0f;
            int count = mItemSizeGroupList.Count;
            if (count == 0)
            {
                return;
            }
            ItemSizeGroup hitGroup = null;

            int low = 0;
            int high = count - 1;
            while (low <= high)
            {
                int mid = (low + high) / 2;
                ItemSizeGroup tGroup = mItemSizeGroupList[mid];
                if (tGroup.mGroupStartPos <= pos && tGroup.mGroupEndPos >= pos)
                {
                    hitGroup = tGroup;
                    break;
                }
                else if (pos > tGroup.mGroupEndPos)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }
            int hitIndex = -1;
            if (hitGroup != null)
            {
                hitIndex = hitGroup.GetItemIndexByPos(pos - hitGroup.mGroupStartPos);
            }
            else
            {
                return;
            }
            if (hitIndex < 0)
            {
                return;
            }
            index = hitIndex + hitGroup.mGroupIndex * mItemMaxCountPerGroup;
            itemPos = hitGroup.GetItemStartPos(hitIndex);
        }

        public void Update(bool updateAll)
        {
            int count = mItemSizeGroupList.Count;
            if (count == 0)
            {
                return;
            }
            if (mDirtyBeginIndex >= count)
            {
                return;
            }
            int loopCount = 0;
            for (int i = mDirtyBeginIndex; i < count; ++i)
            {
                loopCount++;
                ItemSizeGroup tGroup = mItemSizeGroupList[i];
                mDirtyBeginIndex++;
                tGroup.UpdateAllItemStartPos();
                if (i == 0)
                {
                    tGroup.mGroupStartPos = 0;
                    tGroup.mGroupEndPos = tGroup.mGroupSize;
                }
                else
                {
                    tGroup.mGroupStartPos = mItemSizeGroupList[i - 1].mGroupEndPos;
                    tGroup.mGroupEndPos = tGroup.mGroupStartPos + tGroup.mGroupSize;
                }
                if (!updateAll && loopCount > 1)
                {
                    return;
                }

            }
        }

    }
}

using System;
